(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-4-e", [{"sp": "HDR", "t": "Ἱστορίαι (Θʹ–ΙΕʹ)"}, {"sp": "HDR", "t": "Βιβλίον Θʹ", "st": "9"}, {"sp": "N", "t": "αἱ μὲν οὖν ἐπιφανέσταται πράξεις τῶν ὑπὸ τῆς προειρημένης ὀλυμπιάδος περιληφθεισῶν καὶ τοῦ τετραετοῦς διαστήματος, ὅ φαμεν δεῖν ὀλυμπιάδα νομίζειν, εἰσὶν αὗται· περὶ ὧν ἡμεῖς ἐν δυσὶ βυβλίοις πειρασόμεθα ποιεῖσθαι τὴν ἐξήγησιν. οὐκ ἀγνοῶ δὲ διότι συμβαίνει τὴν πραγματείαν ἡμῶν ἔχειν αὐστηρόν τι καὶ πρὸς ἓν γένος ἀκροατῶν οἰκειοῦσθαι καὶ κρίνεσθαι διὰ τὸ μονοειδὲς τῆς συντάξεως. οἱ μὲν γὰρ ἄλλοι συγγραφεῖς σχεδὸν ἅπαντες, εἰ δὲ μή γ’, οἱ πλείους, πᾶσι τοῖς τῆς ἱστορίας μέρεσι χρώμενοι πολλοὺς ἐφέλκονται πρὸς ἔντευξιν τῶν ὑπομνημάτων. τὸν μὲν γὰρ φιλήκοον ὁ γενεαλογικὸς τρόπος ἐπισπᾶται, τὸν δὲ πολυπράγμονα καὶ περιττὸν ὁ περὶ τὰς ἀποικίας καὶ κτίσεις καὶ συγγενείας, καθά που καὶ παρ’ Ἐφόρῳ λέγεται, τὸν δὲ πολιτικὸν ὁ περὶ τὰς πράξεις τῶν ἐθνῶν καὶ πόλεων καὶ δυναστῶν. ἐφ’ ὃν ἡμεῖς ψιλῶς κατηντηκότες καὶ περὶ τοῦτον πεποιημένοι τὴν ὅλην τάξιν, πρὸς ἓν μέν τι γένος, ὡς προεῖπον, οἰκείως ἡρμόσμεθα, τῷ δὲ πλείονι μέρει τῶν ἀκροατῶν ἀψυχαγώγητον παρεσκευάκαμεν τὴν ἀνάγνωσιν. τίνος δὲ χάριν τἄλλα μέρη τῆς ἱστορίας ἀποδοκιμάσαντες αὐτὰ τὰ κατὰ τὰς πράξεις προειλάμεθα γράφειν, ἐν ἑτέροις ἡμῖν εἴρηται διὰ πλειόνων, κεφαλαιωδῶς γε μὴν οὐδὲν ἐπέχει καὶ νῦν ἐμφάσεως χάριν ὑπομνῆσαι τοὺς ἀκούοντας.", "st": "9.1"}, {"sp": "N", "t": "πολλῶν γὰρ καὶ πολλαχῶς ἐξηριθμημένων τά τε περὶ τὰς γενεαλογίας καὶ μύθους καὶ περὶ τὰς ἀποικίας, ἔτι δὲ συγγενείας καὶ κτίσεις, λοιπὸν ἢ τὰ ἀλλότρια δεῖ λέγειν ὡς ἴδια τὸν νῦν περὶ τούτων πραγματευόμενον, ὃ πάντων ἐστὶν αἴσχιστον, ἢ τοῦτο μὴ βουλόμενον προδήλως ματαιοπονεῖν, ὑπὲρ τοιούτων ὁμολογοῦντα συντάττεσθαι καὶ φροντίζειν, ἃ διὰ τῶν προγενεστέρων ἱκανῶς δεδήλωται καὶ παραδέδοται τοῖς ἐπιγινομένοις. ταῦτα μὲν οὖν παρελείφθη τούτων ἕνεκα καὶ πλειόνων ἑτέρων· ὁ δὲ πραγματικὸς τρόπος ἐνεκρίθη πρῶτον μὲν διὰ τὸ καινοποιεῖσθαι συνεχῶς καὶ καινῆς ἐξηγήσεως δεῖσθαι τῷ μὴ συμβατὸν εἶναι τοῖς ἀρχαίοις τὸ τὰς ἐπιγινομένας πράξεις ἡμῖν ἐξαγγεῖλαι, δεύτερον δὲ καὶ διὰ τὸ πάντων ὠφελιμώτατον αὐτὸν καὶ πρὸ τοῦ μέν, μάλιστα δὲ νῦν ὑπάρχειν, τῷ τὰς ἐμπειρίας καὶ τέχνας ἐπὶ τοσοῦτον προκοπὴν εἰληφέναι καθ’ ἡμᾶς ὥστε πᾶν τὸ παραπῖπτον ἐκ τῶν καιρῶν ὡς ἂν εἰ μεθοδικῶς δύνασθαι χειρίζειν τοὺς φιλομαθοῦντας. διόπερ ἡμεῖς οὐχ οὕτως τῆς τέρψεως στοχαζόμενοι τῶν ἀναγνωσομένων ὡς τῆς ὠφελείας τῶν προσεχόντων, τἄλλα παρέντες ἐπὶ τοῦτο τὸ μέρος κατηνέχθημεν. περὶ μὲν οὖν τούτων οἱ συνεφιστάνοντες ἐπιμελῶς ἡμῶν τοῖς ὑπομνήμασι βεβαιότατα μαρτυρήσουσι τοῖς νῦν λεγομένοις.", "st": "9.2"}, {"sp": "N", "t": "Ἀννίβας δὲ κύκλῳ περιλαμβάνων τὸν χάρακα τοῦ Ἀππίου τὸ μὲν πρῶτον ἠκροβολίζετο καὶ κατεπείραζε, βουλόμενος ἐκκαλεῖσθαι πρὸς μάχην· οὐδενὸς δὲ συνυπακούοντος τέλος ἐγίνετο πολιορκίᾳ παραπλήσιον τὸ συμβαῖνον, τῶν μὲν ἱππέων ἐπιφερομένων ταῖς ἴλαις καὶ μετὰ κραυγῆς εἰσακοντιζόντων εἰς τὴν παρεμβολήν, τῶν δὲ πεζῶν κατὰ σπείρας προσπιπτόντων καὶ διασπᾶν τὸ χαράκωμα πειρωμένων. οὐ μὴν ἀλλ’ οὐδ’ ὣς ἐδύνατο κινῆσαι τοὺς Ῥωμαίους ἐκ τῆς ὑποκειμένης προθέσεως, ἀλλὰ τοῖς μὲν εὐζώνοις ἀπετρίβοντο τοὺς προσπίπτοντας πρὸς τὸν χάρακα, τοῖς δὲ βαρέσι τῶν ὅπλων ἀσφαλιζόμενοι τὴν ἐπιφορὰν τῶν βελῶν ἔμενον ἐν τάξει κατὰ τὰς σημαίας. Ἀννίβας δὲ δυσαρεστούμενος τοῖς ὅλοις διὰ τὸ μήτε παραπεσεῖν εἰς τὴν πόλιν δύνασθαι μήτ’ ἐκκαλεῖσθαι τοὺς Ῥωμαίους, ἐβουλεύετο περὶ τῶν ἐνεστώτων τί χρὴ ποιεῖν. ἐμοὶ δ’ οὐ μόνοις ἂν δοκεῖ Καρχηδονίοις τὰ τότε συμβαίνοντα παρέχειν ἀπορίαν, ἀλλὰ καὶ τῶν ἄλλων ἀνθρώπων τοῖς πυθομένοις. τίς γὰρ οὐκ ἂν ἀπιστήσαι πῶς Ῥωμαῖοι, πολλαῖς μὲν ἡττημένοι μάχαις ὑπὸ Καρχηδονίων, οὐ τολμῶντες δὲ κατὰ πρόσωπον ἔτι συγκαθίστασθαι τοῖς ὑπεναντίοις, ὅμως οὔτ’ εἴκειν οἷοί τ’ ἦσαν οὔτ’ ἐκχωρεῖν τῶν ὑπαίθρων; καὶ τὸν μὲν πρὸ τοῦ χρόνον ἀντιπαρῆγον μόνον ἀεὶ ταῖς ὑπωρείαις, τότε δὲ καθίσαντες εἰς τὰ πεδία καὶ τὸν ἐπιφανέστατον τόπον τῆς Ἰταλίας ἐπολιόρκουν τὴν ἰσχυροτάτην πόλιν, κύκλῳ προσμαχομένων αὐτοῖς τῶν πολεμίων, πρὸς οὓς οὐδ’ ἐπινοήσαντες οἷοί τ’ ἦσαν ἀντοφθαλμεῖν· καρχηδόνιοί τ’, ἀδιαλείπτως νικῶντες ταῖς μάχαις, οὐχ ἧττον ἐνίοις καιροῖς ἐδυσχρηστοῦντο τῶν ἡττωμένων. δοκεῖ δέ μοι παραίτιον τοῦτο γεγονέναι τῆς ἑκατέρων προαιρέσεως, τὸ παρ’ ἀμφοῖν συντεθεωρῆσθαι διότι τὸ παρ’ Ἀννίβου σύνταγμα τῶν ἱππέων αἴτιον ἦν καὶ τοῦ νικᾶν τοὺς Καρχηδονίους καὶ τοῦ λείπεσθαι τοὺς Ῥωμαίους. διόπερ αἵ τε τῶν ἡττωμένων στρατοπέδων ἀντιπαραγωγαὶ μετὰ τὰς μάχας εὐθέως κατὰ λόγον ἐγίνοντο· διὰ γὰρ τόπων τοιούτων ἀντιπαρῆγον ἐν οἷς οὐδὲν ἔμελλε βλάψειν αὐτοὺς τὸ τῶν ὑπεναντίων ἱππικόν. τά τε περὶ τὴν Καπύην τότε συμβαίνοντ’ εἰκότως ἑκατέροις ἀπήντα.", "st": "9.3"}, {"sp": "N", "t": "τὸ μὲν γὰρ τῶν Ῥωμαίων στρατόπεδον ἐξιέναι μὲν πρὸς μάχην οὐκ ἐθάρρει τῷ δεδιέναι τοὺς τῶν πολεμίων ἱππεῖς, ἔμενε δ’ ἐν τῇ παρεμβολῇ τετολμηκότως, σαφῶς εἰδὸς ἀβλαβῆ τὴν ἵππον αὐτοῖς ἐσομένην, ὑφ’ ἧς ἐν ταῖς μάχαις ἡττᾶτο. οἵ τε Καρχηδόνιοι πάλιν εὐλόγως οὔτε στρατοπεδεύσαντες μετὰ τῆς ἵππου μένειν ἐδύναντο πλείω χρόνον διὰ τὸ τὰ μὲν ἐν τῇ παρακειμένῃ χώρᾳ χορτάσματα πάντα κατεφθαρκέναι τοὺς Ῥωμαίους αὐτοῦ τούτου χάριν, τοῖς δὲ νώτοις οὐκ ἐφικτὸν εἶναι τοσαύτῃ μὲν ἵππῳ, τοσούτοις δ’ ὑποζυγίοις κατανύσαι χόρτον ἢ κριθὰς κομίζοντας ἐκ μακροῦ διαστήματος· οὔτε μὴν ἄνευ τῶν ἱππέων παραστρατοπεδεύσαντες ἐθάρρουν πολιορκεῖν χάρακα καὶ τάφρον προβεβλημένους τοὺς ὑπεναντίους, πρὸς οὓς καὶ τὸν ἐξ ἴσου κίνδυνον αὐτοῖς ἀμφίδοξον εἶναι συνέβαινε χωρὶς τῶν ἱππέων. ἔτι δὲ πρὸς τούτοις ἠγωνίων καὶ τοὺς ἐπικαθισταμένους ὑπάτους μὴ παραγενηθέντες ἐπιστρατοπεδεύσαιεν καὶ πολλὴν ἀπορίαν σφίσι παραστήσαιεν, ἀφελόμενοι τὴν τῶν χορηγιῶν ἐπάρκειαν. ἐξ ὧν συλλογιζόμενος Ἀννίβας ἀδύνατον ὑπάρχον τὸ διὰ τῆς ἐκ χειρὸς βίας λῦσαι τὴν πολιορκίαν, ἐπ’ ἄλλης ἐγένετο γνώμης. ὑπέλαβε γάρ, εἰ λαθραίαν ποιησάμενος τὴν πορείαν αἰφνιδίως ἐπιφανείη τοῖς κατὰ τὴν Ῥώμην τόποις, ἴσως μὲν ἂν καὶ περὶ τὴν πόλιν ἀνύσασθαί τι τῶν χρησίμων, ἐκπλήξας τῷ παραδόξῳ τοὺς ἐνοικοῦντας· εἰ δὲ μὴ τοῦτο, τούς γε περὶ τὸν Ἄππιον ἀναγκάσειν ἢ λύειν τὴν πολιορκίαν, σπεύδοντας τῇ πατρίδι βοηθεῖν, ἢ διαιροῦντας τὴν δύναμιν εὐκαταγωνίστους ὑπάρξειν καὶ τοὺς βοηθοῦντας καὶ τοὺς ἀπολειπομένους αὐτῶν.", "st": "9.4"}, {"sp": "N", "t": "ἃ διανοηθεὶς ἐξέπεμψε γραμματοφόρον εἰς τὴν Καπύην, πείσας τινὰ τῶν Λιβύων αὐτομολῆσαι πρὸς τοὺς Ῥωμαίους, κἀκεῖθεν εἰς τὴν πόλιν, προνοηθεὶς τῆς τῶν γραμμάτων ἀσφαλείας· πάνυ γὰρ ἠγωνία μὴ θεωρήσαντες αὐτὸν ἀπαλλαττόμενον οἱ Καπυανοί, κἄπειτα διατραπέντες ὡς ἀπηλπισμένοι, παραδῶσι τοῖς Ῥωμαίοις ἑαυτούς. διὸ γράψας ὑπὲρ τῆς ἐπιβολῆς τῆς κατὰ τὴν ἀναζυγὴν ἀπέστειλε τὸν Λίβυν, ἵνα συνέντες τὴν πρόθεσιν αὐτοῦ καὶ τὸν χωρισμὸν εὐθαρσῶς ὑπομένοιεν τὴν πολιορκίαν. τοῖς δ’ ἐν Ῥώμῃ προσπεπτωκότων τῶν περὶ τὴν Καπύην, διότι παρεστρατοπεδευκὼς Ἀννίβας πολιορκεῖ τὰς δυνάμεις αὐτῶν, ὀρθοὶ ταῖς διανοίαις καὶ περίφοβοι πάντες ἦσαν, ὡς καὶ πρὸς τὰ ὅλα διατεινούσης τῆς ἐνεστηκυίας κρίσεως· διὸ καὶ ταῖς ἐξαποστολαῖς καὶ ταῖς παρασκευαῖς πρὸς τοῦτο τὸ μέρος ὅλοι καὶ πάντες ἐνενεύκεισαν. οἱ δὲ Καπυανοὶ κομισάμενοι τὰ παρὰ τοῦ Λίβυος γράμματα καὶ γνόντες τὴν ἐπίνοιαν τῶν Καρχηδονίων, ἔμενον ἐπὶ τῶν ὑποκειμένων, κρίνοντες ἔτι ταύτην ἐξελέγξαι τὴν ἐλπίδα. Ἀννίβας δὲ μετὰ πέμπτην ἡμέραν τῆς παρουσίας, δειπνοποιησάμενος καὶ καταλιπὼν τὰ πυρὰ καιόμενα, τοιαύτην ἐποίησε τὴν ἀναζυγὴν ὥστε μηδένα συνεῖναι τῶν πολεμίων τὸ συμβαῖνον. χρησάμενος δὲ ταῖς πορείαις διὰ τῆς Σαυνίτιδος ἐνεργοῖς καὶ συνεχέσι καὶ τοὺς περὶ τὴν ὁδὸν τόπους αἰεὶ ταῖς προπορείαις ἐξερευνώμενος καὶ προκαταλαμβάνων, ἔτι τῶν ἐν τῇ Ῥώμῃ ταῖς διανοίαις περὶ τὴν Καπύην καὶ τὰς ἐκεῖ πράξεις ὄντων ἔλαθε διαβὰς τὸν Ἀνίωνα ποταμὸν καὶ συνεγγίσας, ὥστε μὴ πλεῖον τετταράκοντα σταδίων ἀποσχὼν τῆς Ῥώμης ποιήσασθαι τὴν παρεμβολήν.", "st": "9.5"}, {"sp": "N", "t": "οὗ γενομένου καὶ προσπεσόντος εἰς τὴν Ῥώμην, εἰς ὁλοσχερῆ συνέβη ταραχὴν καὶ φόβον ἐμπεσεῖν τοὺς κατὰ τὴν πόλιν, ἅτε τοῦ πράγματος αἰφνιδίου μὲν ὄντος καὶ τελέως ἀνελπίστου διὰ τὸ μηδέποτε τὸν Ἀννίβαν ἐπὶ τοσοῦτον ἀπηρκέναι τῆς πόλεως, ὑποτρεχούσης δέ τινος ἅμα καὶ τοιαύτης ἐννοίας ὡς οὐχ οἷόν τε τοὺς ἐναντίους ἐπὶ τοσοῦτον ἐγγίσαι καὶ καταθαρρῆσαι μὴ οὐ τῶν περὶ Καπύην στρατοπέδων ἀπολωλότων. διόπερ οἱ μὲν ἄνδρες τὰ τείχη προκατελάμβανον καὶ τοὺς πρὸ τῆς πόλεως εὐκαίρους τόπους, αἱ δὲ γυναῖκες περιπορευόμεναι τοὺς ναοὺς ἱκέτευον τοὺς θεούς, πλύνουσαι ταῖς κόμαις τὰ τῶν ἱερῶν ἐδάφη· τοῦτο γὰρ αὐταῖς ἔθος ἐστὶ ποιεῖν, ὅταν τις ὁλοσχερὴς τὴν πατρίδα καταλαμβάνῃ κίνδυνος. ἄρτι δὲ τῶν περὶ τὸν Ἀννίβαν κατεστρατοπεδευκότων καὶ διανοουμένων τῇ μετὰ ταῦθ’ ἡμέρᾳ καταπειράζειν αὐτῆς τῆς πόλεως, γίνεται παράδοξόν τι καὶ τυχικὸν σύμπτωμα πρὸς σωτηρίαν τοῖς Ῥωμαίοις. οἱ γὰρ περὶ τὸν Γνάιον καὶ Πόπλιον τοῦ μὲν ἑνὸς στρατοπέδου πρότερον πεποιημένοι τὴν καταγραφὴν ἐνόρκους εἶχον τοὺς στρατιώτας εἰς ἐκείνην τὴν ἡμέραν ἥξειν ἐν τοῖς ὅπλοις εἰς τὴν Ῥώμην, τοῦ δ’ ἑτέρου τότε τὰς καταγραφὰς ἐποιοῦντο καὶ δοκιμασίας. ἐξ οὗ συνέβη πλῆθος ἀνδρῶν αὐτομάτως ἁθροισθῆναι πρὸς τὸν δέοντα καιρὸν εἰς τὴν Ῥώμην. οὓς ἐξαγαγόντες εὐθαρσῶς οἱ στρατηγοὶ καὶ παρεμβαλόντες πρὸ τῆς πόλεως ἐπέσχον τὴν ὁρμὴν τῶν περὶ τὸν Ἀννίβαν. οἱ γὰρ Καρχηδόνιοι τὸ μὲν πρῶτον ὥρμησαν, οὐχ ὅλως ἀπελπίζοντες αἱρήσειν κατὰ κράτος αὐτὴν τὴν Ῥώμην· συνθεασάμενοι δὲ τοὺς ὑπεναντίους παρατεταγμένους καὶ ταχέως διά τινος αἰχμαλώτου πυθόμενοι τὸ γεγονός, τῆς μὲν ἐπὶ τὴν πόλιν ἐπιβολῆς ἀπέστησαν, τὴν δὲ χώραν ἐδῄουν ἐπιπορευόμενοι καὶ τὰς οἰκίας ἐνεπίμπρασαν. τὰς μὲν οὖν ἀρχὰς ἀναρίθμητον περιελασάμενοι λείας πλῆθος ἥθροισαν εἰς τὴν παρεμβολήν, ὡς ἂν εἰς ἄγραν ἥκοντες τοιαύτην εἰς ἣν οὐδεὶς οὐδέποτε πολέμιον ἥξειν ἤλπιζε·", "st": "9.6"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τῶν ὑπάτων τολμησάντων ἐν δέκα σταδίοις ἀντιστρατοπεδεῦσαι σφίσι παραβόλως, Ἀννίβας ἅμα μὲν λείας πλῆθος ἡθροικώς, ἅμα δὲ τῆς κατὰ τὴν πόλιν ἐλπίδος ἀποπεπτωκώς, τὸ δὲ μέγιστον, συλλογιζόμενος τὰς ἡμέρας, ἐν αἷς ἤλπιζε κατὰ τὴν ἐξ ἀρχῆς ἐπίνοιαν πυθομένους τοὺς περὶ τὸν Ἄππιον τὸν περὶ τὴν πόλιν κίνδυνον ἤτοι λύσαντας τὴν πολιορκίαν ὁλοσχερῶς παραβοηθήσειν τοῖς ἐπὶ τῇ Ῥώμῃ πράγμασιν ἢ μέρος τι καταλιπόντας τῷ πλείονι βοηθήσειν κατὰ σπουδήν· ὧν ὁπότερον ἂν συμβῇ, δεόντως ἕξειν ὑπειληφὼς ἐκίνει τὴν δύναμιν ἐκ τῆς παρεμβολῆς ὑπὸ τὴν ἑωθινήν. οἱ δὲ περὶ τὸν Πόπλιον διασπάσαντες τὰς ἐπὶ τοῦ προειρημένου ποταμοῦ γεφύρας καὶ συναναγκάσαντες αὐτὸν διὰ τοῦ ῥεύματος περαιοῦν τὴν δύναμιν, προσέκειντο τοῖς Καρχηδονίοις περὶ τὴν διάβασιν καὶ πολλὴν παρεῖχον δυσχρηστίαν. ὁλοσχερὲς μὲν οὖν οὐδὲν ἐδύναντο πρᾶξαι διὰ τὸ πλῆθος τῶν ἱππέων καὶ τὴν πρὸς πάντα τόπον εὐχρηστίαν τῶν Νομάδων· τῆς δὲ λείας ἱκανόν τι μέρος ἀφελόμενοι καὶ περὶ τριακοσίους καταβαλόντες τῶν πολεμίων τότε μὲν ἀνεχώρησαν πρὸς τὴν παρεμβολήν, μετὰ δὲ ταῦτα νομίσαντες τοὺς Καρχηδονίους διὰ φόβον σπουδῇ ποιεῖσθαι τὴν ὑποχώρησιν, εἵποντο κατόπιν ταῖς παρωρείαις. Ἀννίβας δὲ τὸ μὲν πρῶτον ἠπείγετο, σπεύδων ἐπὶ τὸ προκείμενον· μετὰ δὲ πέμπτην ἡμέραν προσαγγελθέντος αὐτῷ μένειν ἐπὶ τῆς πολιορκίας τοὺς περὶ τὸν Ἄππιον, οὕτως ὑποστὰς καὶ προσδεξάμενος τοὺς ἑπομένους ἐπιτίθεται νυκτὸς ἔτι τῇ στρατοπεδείᾳ, καὶ πολλοὺς μὲν αὐτῶν ἀπέκτεινε, τοὺς δὲ λοιποὺς ἐκ τῆς παρεμβολῆς ἐξέβαλε. τῆς δ’ ἡμέρας ἐπιγενομένης συνθεωρήσας τοὺς Ῥωμαίους πρός τινα λόφον ἐρυμνὸν ἀποκεχωρηκότας, τοῦ μὲν ἔτι προσκαρτερεῖν τούτοις ἀπέγνω, ποιησάμενος δὲ τὴν πορείαν διὰ τῆς Δαυνίας καὶ τῆς Βρεττίας ἐπέστη τοῖς κατὰ τὸ Ῥήγιον τόποις ἀνυπόπτως, ὥστε παρ’ ὀλίγον μὲν καὶ τῆς πόλεως κυριεῦσαι, πάντας δὲ τοὺς ἐπὶ τὴν χώραν ἐκπεπορευμένους ἀποτεμέσθαι καὶ πλείστων γενέσθαι Ῥηγίνων κύριος ἐν ἐκείνῃ τῇ παρουσίᾳ.", "st": "9.7"}, {"sp": "N", "t": "δοκεῖ δέ μοι δικαίως ἄν τις ἐπισημήνασθαι κατὰ τοῦτον τὸν καιρὸν τάς τε Καρχηδονίων καὶ Ῥωμαίων ἀρετὰς καὶ φιλοτιμίας ἐν τῷ πολεμεῖν. καθάπερ γὰρ Ἐπαμινώνδαν τὸν Θηβαῖον θαυμάζουσι πάντες, διότι παραγενόμενος εἰς Τεγέαν μετὰ τῶν συμμάχων καὶ θεωρήσας τοὺς Λακεδαιμονίους αὐτούς τε πανδημεὶ παραγεγονότας εἰς Μαντίνειαν καὶ τοὺς συμμάχους εἰς ταύτην ἡθροικότας τὴν πόλιν, ὡς παραταξομένους τοῖς Θηβαίοις, δειπνοποιήσασθαι τοῖς αὑτοῦ καθ’ ὥραν παραγγείλας ἐξῆγε τὴν δύναμιν ἄρτι τῆς νυκτὸς ἐπιγινομένης, ὡς τῆς παρατάξεως χάριν σπεύδων εὐκαίρους τινὰς προκαταλαβέσθαι τόπους, τοιαύτην δὲ τοῖς πολλοῖς δόξαν ἐνεργασάμενος προῆγε, ποιούμενος τὴν πορείαν ἐπ’ αὐτὴν τὴν Λακεδαίμονα, προσμίξας δὲ περὶ τρίτην ὥραν τῇ πόλει παραδόξως καὶ καταλαβὼν τὴν Σπάρτην ἔρημον τῶν βοηθησόντων, μέχρι μὲν ἀγορᾶς ἐβιάσατο καὶ κατέσχε τῆς πόλεως τοὺς ἐπὶ τὸν ποταμὸν ἐστραμμένους τόπους. γενομένης δὲ περιπετείας, καί τινος αὐτομόλου τὴν νύκτα διαπεσόντος εἰς τὴν Μαντίνειαν καὶ διασαφήσαντος Ἀγησιλάῳ τῷ βασιλεῖ τὸ συμβαῖνον, καὶ τῶν βοηθούντων παραγενομένων εἰς τὸν τῆς καταλήψεως καιρόν, ταύτης μὲν τῆς ἐλπίδος ἀπεσφάλη, μετὰ δὲ ταῦτα περὶ τὸν Εὐρώταν ἀριστοποιησάμενος καὶ προσαναλαβὼν τὴν δύναμιν ἐκ τῆς κακοπαθείας, ὥρμα πάλιν ἐξ ὑποστροφῆς τὴν αὐτὴν ὁδόν, συλλογιζόμενος ὅτι συμβήσεται τῶν Λακεδαιμονίων καὶ τῶν συμμάχων παραβεβοηθηκότων εἰς τὴν Σπάρτην ἔρημον πάλιν καταλείπεσθαι τὴν Μαντίνειαν· ὃ καὶ συνέβη γενέσθαι. διὸ παρακαλέσας τοὺς Θηβαίους καὶ χρησάμενος ἐνεργῷ τῇ νυκτοπορείᾳ παρῆν καὶ προσέμισγε τῇ Μαντινείᾳ περὶ μέσον ἡμέρας, ἐρήμῳ τελέως ὑπαρχούσῃ τῶν βοηθησόντων. οἱ δ’ Ἀθηναῖοι κατὰ τὸν καιρὸν τοῦτον σπουδάζοντες μετασχεῖν τοῦ πρὸς τοὺς Θηβαίους ἀγῶνος τοῖς Λακεδαιμονίοις κατὰ τὴν συμμαχίαν παρῆσαν. ἤδη δὲ τῆς Θηβαίων πρωτοπορείας συναπτούσης πρὸς τὸ τοῦ Ποσειδῶνος ἱερόν, ὃ κεῖται πρὸ τῆς πόλεως ἐν ἑπτὰ σταδίοις, ὥσπερ ἐπίτηδες συνεκύρησεν ἅμα καὶ τοὺς Ἀθηναίους ἐπιφαίνεσθαι κατὰ τὸν τῆς Μαντινείας ὑπερκείμενον λόφον· εἰς οὓς ἐμβλέψαντες οἱ καταλελειμμένοι τῶν Μαντινέων μόλις ἐθάρρησαν ἐπιβῆναι τοῦ τείχους καὶ κωλῦσαι τὴν τῶν Θηβαίων ἔφοδον. διόπερ εἰκότως οἱ συγγραφεῖς ἐπιμέμφονται τοῖς προειρημένοις ἔργοις, φάσκοντες τῷ μὲν ἡγεμόνι πεπρᾶχθαι πᾶν ὅσον ἀγαθῷ στρατηγῷ, καὶ τῶν μὲν ὑπεναντίων κρείττω, τῆς δὲ τύχης ἥττω γεγονέναι τὸν Ἐπαμινώνδαν.", "st": "9.8"}, {"sp": "N", "t": "τὸ δὲ παραπλήσιον ἄν τις εἴποι καὶ περὶ τῶν κατ’ Ἀννίβαν. καὶ γὰρ τὸ προσβαλόντα τοῖς πολεμίοις πειραθῆναι διὰ τῶν ἐκ μέρους ἀγώνων λύειν τὴν πολιορκίαν, καὶ τὸ ταύτης ἀποπεσόντα τῆς προσβολῆς ἐπ’ αὐτὴν ὁρμῆσαι τὴν Ῥώμην, κἄπειτα μὴ καθικόμενον τῆς προθέσεως διὰ τὰς ἐκ ταὐτομάτου περιπετείας αὖθις ἐξ ὑποστροφῆς συντρῖψαι μὲν τοὺς ἑπομένους, ἐφεδρεῦσαι δὲ τῷ κατὰ λόγον, εἰ συνέβη γενέσθαι κίνημα περὶ τοὺς τὴν Καπύην πολιορκοῦντας, τὸ δὲ τελευταῖον μὴ λήξαντα τῆς προθέσεως εἰς τὴν τῶν ἐχθρῶν βλάβην ἀποσκῆψαι, μόνον οὐ δ’ ἀναστάτους ποιῆσαι Ῥηγίνους, τίς οὐκ ἂν ἐπισημήναιτο καὶ θαυμάσαι τὸν προειρημένον ἐπὶ τούτοις ἡγεμόνα; καὶ μὴν Ῥωμαίους Λακεδαιμονίων ἀμείνους ἄν τις ἐν τούτῳ τῷ καιρῷ κρίνειεν. Λακεδαιμόνιοι μὲν γὰρ τῇ πρώτῃ προσαγγελίᾳ συνεκχυθέντες τὴν μὲν Σπάρτην ἔσωσαν, τὴν δὲ Μαντίνειαν τὸ καθ’ αὑτοὺς μέρος ἀπέβαλον· Ῥωμαῖοι δὲ καὶ τὴν πατρίδα διεφύλαξαν καὶ τὴν πολιορκίαν οὐκ ἔλυσαν, ἀλλ’ ἔμειναν ἀσαλεύτως καὶ βεβαίως ἐπὶ τῶν ὑποκειμένων καὶ τὸ λοιπὸν ἤδη τεθαρρηκότως προσέκειντο τοῖς Καπυανοῖς. ταῦτα μὲν οὖν οὐχ οὕτως τοῦ Ῥωμαίων ἢ Καρχηδονίων ἐγκωμίου χάριν εἴρηταί μοι — τούτους μὲν γὰρ ἤδη πολλάκις ἐπεσημηνάμην — τὸ δὲ πλεῖον τῶν ἡγουμένων παρ’ ἀμφοτέροις καὶ τῶν μετὰ ταῦτα μελλόντων χειρίζειν παρ’ ἑκάστοις τὰς κοινὰς πράξεις, ἵνα τῶν μὲν ἀναμιμνησκόμενοι, τὰ δ’ ὑπὸ τὴν ὄψιν λαμβάνοντες ζηλωταὶ γίνωνται παράβολον ἔχειν τι καὶ κινδυνῶδες, τοὐναντίον ἀσφαλῆ μὲν τὴν τόλμαν, θαυμασίαν δὲ τὴν ἐπίνοιαν, ἀείμνηστον δὲ καὶ καλὴν ἔχει τὴν προαίρεσιν καὶ κατορθωθέντα καὶ διαψευσθέντα παραπλησίως, ἐὰν μόνον σὺν νῷ γένηται τὰ πραττόμενα. Ἄτελλα, πόλις Ὀπικῶν Ἰταλίας μεταξὺ Καπύης καὶ Νεαπόλεως. τὸ ἐθνικὸν … Ἀτελλανός, ὡς Πολύβιος ἐνάτῃ ‘Ἀτελλανοὶ παρέδοσαν αὑτούσ’. τῶν γὰρ Ῥωμαίων πολιορκούντων Τάραντα Βομίλκας ὁ τῶν Καρχηδονίων ναύαρχος εἰς τὸ συμμαχήσειν μετὰ δυνάμεως πλείστης καὶ μηδὲν δυνηθεὶς ἐπικουρῆσαι τοῖς ἔνδον διὰ τὸ τοὺς Ῥωμαίους ἀσφαλῶς θέσθαι τὰ περὶ τὴν στρατοπεδείαν, ἔλαθεν ἀναλώσας τὴν χορηγίαν. καὶ μετὰ παρακλήσεως πρότερον ἀφικέσθαι ἐκβιασθεὶς καὶ ὑποσχέσεων μεγάλων, ὕστερον μεθ’ ἱκετηρίας τῶν ἔνδον ἀποπλεῦσαι ἀπηναγκάσθη.", "st": "9.9"}, {"sp": "N", "t": "οὐκ ἐκ τῶν ἔξω κοσμεῖται πόλις, ἀλλ’ ἐκ τῆς τῶν οἰκούντων ἀρετῆς. ἐκρίθη μὲν οὖν διὰ τοῦτο τοῖς Ῥωμαίοις τὰ προειρημένα μετακομίζειν εἰς τὴν ἑαυτῶν πατρίδα καὶ μηδὲν ἀπολιπεῖν· πότερα δ’ ὀρθῶς τοῦτο καὶ συμφερόντως αὑτοῖς ἔπραξαν ἢ τἀναντία, πολὺς ἂν εἴη λόγος, πλείων γε μὴν εἰς τὸ μὴ δεόντως σφίσι πεπρᾶχθαι μηδ’ ἀκμὴν νῦν πράττεσθαι τοῦτο τοὔργον. εἰ μὲν γὰρ ἐκ τοιούτων ὁρμηθέντες προεβίβασαν τὴν πατρίδα, δῆλον ὡς εἰκότως ταῦτα μετέφερον εἰς τὴν οἰκείαν, δι’ ὧν ηὐξήθησαν. εἰ δ’ ἁπλουστάτοις χρώμενοι βίοις καὶ πορρωτάτω τῆς ἐν τούτοις περιττότητος καὶ πολυτελείας ἀφεστῶτες ὅμως ἐπεκράτουν τούτων αἰεὶ παρ’ οἷς ὑπῆρχε πλεῖστα καὶ κάλλιστα τὰ τοιαῦτα, πῶς οὐ νομιστέον εἶναι τὸ γινόμενον ὑπ’ αὐτῶν ἁμάρτημα; τὸ γὰρ ἀπολιπόντας τὰ τῶν νικώντων ἔθη τὸν τῶν ἡττωμένων ζῆλον ἀναλαμβάνειν, προσεπιδραττομένους ἅμα καὶ τὸν ἐξακολουθοῦντα τοῖς τοιούτοις φθόνον, ὃ πάντων ἐστὶ φοβερώτατον ταῖς ὑπεροχαῖς, ὁμολογούμενον ἂν εἴποι τις εἶναι τῶν πραττόντων παράπτωμα. οὐ γὰρ οὕτως ὁ θεώμενος οὐδέποτε μακαρίζει τοὺς τἀλλότρια κεκτημένους, ὡς ἐν τῷ φθονεῖν ἅμα καί τις ἔλεος αὐτὸν ὑποτρέχει τῶν ἐξ ἀρχῆς ἀποβαλόντων. ἐπὰν δὲ καὶ προβαίνῃ τὰ τῆς εὐκαιρίας καὶ πάντα συνάγῃ πρὸς αὑτὸν τὰ τῶν ἄλλων, καὶ ταῦτα συγκαλῇ τρόπον τινὰ τοὺς ἐστερημένους ἐπὶ θέαν, διπλάσιον γίνεται τὸ κακόν. οὐ γὰρ ἔτι τοὺς πέλας ἐλεεῖν συμβαίνει τοὺς θεωμένους, ἀλλὰ σφᾶς αὐτούς, ἀναμιμνησκομένους τῶν οἰκείων συμπτωμάτων. ἐξ ὧν οὐ μόνον φθόνος, ἀλλ’ οἷον ὀργή τις ἐκκαίεται πρὸς τοὺς εὐτυχοῦντας· ἡ γὰρ τῶν ἰδίων περιπετειῶν ἀνάμνησις ὡς ἂν εἰ προτροπή τις ἐστι πρὸς τὸ κατὰ τῶν πραξάντων μῖσος. τὸ μὲν οὖν τὸν χρυσὸν καὶ τὸν ἄργυρον ἁθροίζειν πρὸς αὑτοὺς ἴσως ἔχει τινὰ λόγον· οὐ γὰρ οἷόν τε τῶν καθόλου πραγμάτων ἀντιποιήσασθαι μὴ οὐ τοῖς μὲν ἄλλοις ἀδυναμίαν ἐνεργασαμένους, σφίσι δὲ τὴν τοιαύτην δύναμιν ἑτοιμάσαντας. τὰ δ’ ἐκτὸς ὑπάρχοντα τῆς προειρημένης δυνάμεως ἦν ἐν τοῖς ἐξ ἀρχῆς τόποις ἅμα τῷ φθόνῳ καταλιπόντας ἐνδοξοτέραν ποιεῖν τὴν σφετέραν πατρίδα, μὴ γραφαῖς καὶ τύποις, ἀλλὰ σεμνότητι καὶ μεγαλοψυχίᾳ κοσμοῦντας αὐτήν. οὐ μὴν ἀλλὰ ταῦτα μὲν εἰρήσθω μοι χάριν τῶν μεταλαμβανόντων ἀεὶ τὰς δυναστείας, ἵνα μὴ σκυλεύοντες τὰς πόλεις κόσμον ὑπολαμβάνωσιν εἶναι ταῖς ἑαυτῶν πατρίσι τὰς ἀλλοτρίας συμφοράς· Ῥωμαῖοι δὲ μετακομίσαντες τὰ προειρημένα ταῖς μὲν ἰδιωτικαῖς κατασκευαῖς τοὺς αὑτῶν ἐκόσμησαν βίους, ταῖς δὲ δημοσίαις τὰ κοινὰ τῆς πόλεως.", "st": "9.10"}, {"sp": "N", "t": "ὅτι οἱ τῶν Καρχηδονίων ἡγεμόνες, κρατήσαντες τῶν ὑπεναντίων, σφῶν αὐτῶν οὐκ ἠδύναντο κρατεῖν, καὶ δόξαντες τὸν πρὸς Ῥωμαίους πόλεμον ἀνῃρηκέναι πρὸς αὑτοὺς ἐστασίαζον, ἀεὶ παρατριβόμενοι διὰ τὴν ἔμφυτον Φοίνιξι πλεονεξίαν καὶ φιλαρχίαν. ὧν ὑπάρχων Ἀσδρούβας ὁ Γέσκωνος εἰς τοῦτο κακοπραγμοσύνης προήχθη διὰ τὴν ἐξουσίαν, ὡς τὸν πιστότατον τῶν κατ’ Ἰβηρίαν φίλων Ἀνδοβάλην, πάλαι μὲν ἀποβαλόντα τὴν ἀρχὴν διὰ Καρχηδονίους, ἄρτι δὲ πάλιν ἀπειληφότα διὰ τὴν πρὸς ἐκείνους εὔνοιαν, ἐπεβάλετο χρημάτων πλῆθος αἰτεῖν. τοῦ δὲ παρακούσαντος διὰ τὸ θαρρεῖν ἐπὶ τῇ προγεγενημένῃ πίστει πρὸς τοὺς Καρχηδονίους, ψευδῆ διαβολὴν ἐπενέγκας ἠνάγκασε τὸν Ἀνδοβάλην δοῦναι τὰς ἑαυτοῦ θυγατέρας εἰς ὁμηρείαν.", "st": "9.11"}, {"sp": "N", "t": "πολλὴν μὲν ἐπισκέψεως χρείαν ἔχει τὰ συμβαίνοντα περὶ τὰς πολεμικὰς ἐπιβολάς· ἔστι δὲ δυνατὸν ἐν ἑκάστοις αὐτῶν εὐστοχεῖν, ἐὰν σὺν νῷ τις πράττῃ τὸ προτεθέν. ὅτι μὲν οὖν ἐστι τῶν κατὰ πόλεμον ἔργων ἐλάττω τὰ προδήλως καὶ μετὰ βίας ἐπιτελούμενα τῶν μετὰ δόλου καὶ σὺν καιρῷ πραττομένων, εὐχερὲς τῷ βουλομένῳ καταμαθεῖν ἐκ τῶν ἤδη γεγονότων· ὅτι γε μὴν αὐτῶν τῶν ἐν καιρῷ πάλιν ἐνεργουμένων πλείω γίνεται τὰ διαμαρτανόμενα τῶν κατορθουμένων, οὐδὲ τοῦτο γνῶναι χαλεπὸν ἐκ τῶν συμβαινόντων. καὶ μὴν διότι παρὰ τὰς τῶν ἡγουμένων ἀγνοίας ἢ ῥᾳθυμίας ἐπιτελεῖται τὰ πλεῖστα τῶν ἁμαρτημάτων, οὐδεὶς ἂν τοῦτ’ ἀπορήσειε. τίς οὖν ὁ τρόπος τῆς τοιαύτης διαθέσεως σκοπεῖν ἤδη πάρεστι. τὰ μὲν οὖν ἀπροθέτως ἐν τοῖς πολεμικοῖς συμβαίνοντα πράξεις μὲν οὐδαμῶς ἁρμόζει λέγειν, περιπετείας δὲ καὶ συγκυρήσεις μᾶλλον· διὸ καὶ λόγον οὐκ ἔχοντα μεθοδικὸν οὐδ’ ἑστῶτα παραλειπέσθω· τὰ δὲ κατὰ πρόθεσιν ἐνεργούμενα, ταῦτα δηλούσθω· περὶ ὧν ὁ νῦν δὴ λόγος. πάσης δὴ πράξεως ἐχούσης καιρὸν ὡρισμένον καὶ διάστημα καὶ τόπον, καὶ προσδεομένης τοῦ λαθεῖν καὶ συνθημάτων ὡρισμένων, ἔτι δὲ καὶ δι’ ὧν καὶ μεθ’ ὧν καὶ τίνι τρόπῳ πραχθήσεται, φανερὸν ὡς ὁ μὲν ἑκάστου τούτων εὐστοχήσας οὐχ ἁμαρτήσεται τῆς ἐπιβολῆς, ὁ δ’ ἑνὸς ὀλιγωρήσας σφαλήσεται τῆς ὅλης προθέσεως. οὕτως ἡ φύσις πρὸς τὰς ἀποτυχίας τῶν ἐπινοηθέντων ἱκανὸν ἓν καὶ τὸ τυχὸν ἐποίησε τῶν κατὰ μέρος· πρὸς δὲ τὸ κατορθοῦν μόλις ἱκανὰ πάντα.", "st": "9.12"}, {"sp": "N", "t": "διὸ χρὴ μηδενὸς ἀφροντιστεῖν ἐν ταῖς τοιαύταις ἐπιβολαῖς τοὺς ἡγουμένους. ἔστι δ’ ἀρχὴ μὲν τῶν προειρημένων τὸ σιγᾶν, καὶ μήτε διὰ χαρὰν παραδόξου προφαινομένης ἐλπίδος μήτε διὰ φόβον μήτε διὰ συνήθειαν μήτε διὰ φιλοστοργίαν μεταδιδόναι μηδενὶ τῶν ἐκτός, αὐτοῖς δὲ κοινοῦσθαι τούτοις, ὧν χωρὶς οὐχ οἷόν τε τὸ προτεθὲν ἐπὶ τέλος ἀγαγεῖν, καὶ τούτοις μὴ πρότερον, ἀλλ’ ὅταν ὁ τῆς ἑκάστου χρείας καιρὸς ἐπαναγκάζῃ. χρὴ δὲ σιγᾶν μὴ μόνον τῇ γλώττῃ, πολὺ δὲ μᾶλλον τῇ ψυχῇ· πολλοὶ γὰρ ἤδη κρύψαντες τοὺς λόγους ποτὲ μὲν δι’ αὐτῆς τῆς ἐπιφάσεως, ποτὲ δὲ καὶ διὰ τῶν πραττομένων φανερὰς ἐποίησαν τὰς ἑαυτῶν ἐπινοίας. δεύτερον δ’ ἐπεγνωκέναι τὰς ἡμερησίους καὶ νυκτερινὰς πορείας καὶ τὰ διανύσματα τούτων, μὴ μόνον κατὰ γῆν, ἀλλὰ καὶ κατὰ θάλατταν. τρίτον καὶ μέγιστον, τῶν ἐκ τοῦ περιέχοντος καιρῶν ἔχειν ἔννοιαν καὶ δύνασθαι τούτων κατὰ τὸ κριθὲν εὐστοχεῖν. καὶ μὴν οὐδὲ τὸν τόπον τῆς πράξεως ἐν μικρῷ θετέον, ἐπειδὴ πολλάκις παρὰ τοῦτο τὰ μὲν ἀδύνατα δοκοῦντ’ εἶναι δυνατά, τὰ δὲ δυνατὰ πέφηνεν ἀδύνατα. τὸ δὲ τελευταῖον συνθημάτων καὶ παρασυνθημάτων, ἔτι δὲ τῆς ἐκλογῆς, δι’ ὧν καὶ μεθ’ ὧν ἐνεργηθήσεται τὸ κριθέν, οὐκ ὀλιγωρητέον.", "st": "9.13"}, {"sp": "N", "t": "τῶν δὲ προειρημένων τὰ μὲν ἐκ τριβῆς, τὰ δ’ ἐξ ἱστορίας, τὰ δὲ κατ’ ἐμπειρίαν μεθοδικὴν θεωρεῖται. κάλλιστον μὲν οὖν τὸ γινώσκειν αὐτὸν καὶ τὰς ὁδοὺς καὶ τὸν τόπον, ἐφ’ ὃν δεῖ παραγενέσθαι, καὶ τὴν φύσιν τοῦ τόπου, πρὸς δὲ τούτοις, δι’ ὧν μέλλει καὶ μεθ’ ὧν πράττειν. δεύτερον δ’ ἱστορεῖν ἐπιμελῶς καὶ μὴ πιστεύειν τοῖς τυχοῦσι· τὴν δὲ τῶν καθηγουμένων πίστιν ἐπί τι τῶν τοιούτων ἐν τοῖς ἑπομένοις ἀεὶ δεῖ κεῖσθαι. ταῦτα μὲν οὖν καὶ τὰ τούτοις παραπλήσια δυνατὸν ἴσως καὶ δι’ αὐτῆς τῆς στρατιωτικῆς τριβῆς περιγίνεσθαι τοῖς ἡγουμένοις, τὰ μὲν ἐξ αὐτουργίας, τὰ δ’ ἐξ ἱστορίας· τὰ δ’ ἐκ τῆς ἐμπειρίας προσδεῖται μαθήσεως καὶ θεωρημάτων, καὶ μάλιστα τῶν ἐξ ἀστρολογίας καὶ γεωμετρίας, ὧν τὸ μὲν ἔργον οὐ μέγα πρός γε ταύτην τὴν χρείαν, τὸ δὲ χρῆμα μέγα καὶ μεγάλα συνεργεῖν δυνάμενον πρὸς τὰς προειρημένας ἐπιβολάς. ἀναγκαιότατον δ’ αὐτοῦ τὸ περὶ τὰς νυκτερινὰς θεωρίας καὶ τὰς ἡμερινάς. εἰ μὲν γὰρ ἴσας εἶναι συνέβαινεν ἀεὶ ταύτας, οὐδ’ ἧστινος ἂν ἀσχολίας τὸ πρᾶγμα προσεδεῖτο, κοινὴ δ’ ἂν ἦν ἁπάντων ἡ γνῶσις· ἐπεὶ δ’ οὐ μόνον ἔχει τὰ προειρημένα πρὸς ἄλληλα διαφοράν, ἀλλὰ καὶ πρὸς αὑτά, δῆλον ὡς ἀνάγκη γινώσκειν τὰς αὐξήσεις καὶ μειώσεις ἑκατέρων. πῶς γὰρ ἄν τις εὐστοχήσειε πορείας καὶ διανύσματος ἡμερησίου, πῶς δὲ νυκτερινοῦ, μὴ κατανοήσας τὰς τῶν προειρημένων διαφοράς; καὶ μὴν οὐδὲν πρὸς τὸν δέοντα καιρὸν ἐξικέσθαι δυνατὸν ἄνευ τῆς τούτων ἐμπειρίας, ἀλλὰ ποτὲ μὲν ὑστερεῖν, ποτὲ δὲ προτερεῖν ἀνάγκη. μεῖζον δὲ τὸ προτερεῖν ἐν μόνοις τούτοις ἁμάρτημα τοῦ καθυστερεῖν· ὁ μὲν γὰρ ὑπεράρας τὸν ὡρισμένον καιρὸν αὐτῆς ἀποτυγχάνει τῆς ἐλπίδος — τὸ γὰρ γεγονὸς ἐξ ἀποστήματος ἐπιγνοὺς αὖθις ἀπολύεται μετ’ ἀσφαλείας — ὁ δὲ προλαβὼν τὸν καιρόν, ἐγγίσας καὶ γνωρισθεὶς οὐ μόνον ἀποτυγχάνει τῆς ἐπιβολῆς, ἀλλὰ καὶ κινδυνεύει τοῖς ὅλοις.", "st": "9.14"}, {"sp": "N", "t": "κρατεῖ δ’ ἐπὶ πάντων μὲν τῶν ἀνθρωπείων ἔργων ὁ καιρός, μάλιστα δὲ τῶν πολεμικῶν. διὸ προχείρως ἰστέον τῷ στρατηγῷ τροπὰς ἡλίου θερινὰς καὶ χειμερινάς, ἔτι δ’ ἰσημερίας καὶ τὰς μεταξὺ τούτων αὐξήσεις καὶ μειώσεις ἡμερῶν καὶ νυκτῶν· οὕτως γὰρ ἂν μόνως δύναιτο συμμετρεῖσθαι πρὸς λόγον τὰ διανύσματα καὶ κατὰ γῆν καὶ κατὰ θάλατταν. καὶ μὴν τοὺς κατὰ μέρος καιροὺς ἀναγκαῖον εἰδέναι, καὶ τοὺς τῆς ἡμέρας καὶ τοὺς τῆς νυκτός, πρὸς τὸ γινώσκειν πηνίκα ποιητέον καὶ τὰς ἐξεγέρσεις καὶ τὰς ἀναζυγάς· οὐ γὰρ οἷόν τε τοῦ τέλους τυγχάνειν μὴ οὐ τῆς ἀρχῆς εὐστοχήσαντα. τοὺς μὲν οὖν τῆς ἡμέρας καιροὺς τῇ σκιᾷ θεωρεῖν οὐκ ἀδύνατον, ἔτι δὲ τῇ κατὰ τὸν ἥλιον πορείᾳ καὶ τοῖς ἐπὶ τοῦ κόσμου γινομένοις αὐτοῦ τούτου διαστήμασι· τοὺς δὲ τῆς νυκτὸς δυσχερές, ἐὰν μή τις ἐπὶ τοῦ φαινομένου τῇ τῶν δώδεκα ζῳδίων οἰκονομίᾳ καὶ τάξει συμπεριφέρηται· πάνυ δὲ καὶ τοῦτο ῥᾴδιον τοῖς τὰ φαινόμενα πεπολυπραγμονηκόσιν. ἐπεὶ γὰρ ἀνίσων οὐσῶν τῶν νυκτῶν ὅμως ἐν πάσῃ τῇ νυκτὶ τῶν δώδεκα ζῳδίων ἓξ ἀναφέρεσθαι συμβαίνει, φανερὸν ὡς ἀναγκαῖον ἐν τοῖς αὐτοῖς μέρεσι πάσης νυκτὸς ἴσα μέρη τῶν δώδεκα ζῳδίων ἀναφέρεσθαι. τοῦ δ’ ἡλίου γνωριζομένου καθ’ ἡμέραν, ποίαν μοῖραν ἐπέχει, δῆλον ὡς δύναντος τούτου τὴν κατὰ διάμετρον ἐπιτέλλειν ἀνάγκη. λοιπὸν ὅσον ἂν τὸ μετὰ ταύτην μέρος ἀνατεταλκὸς φαίνηται τοῦ ζῳδιακοῦ, τοσοῦτον εἰκὸς ἠνύσθαι τῆς νυκτὸς αἰεί. γνωριζομένων δὲ τῶν ζῳδίων καὶ κατὰ τὸ πλῆθος καὶ κατὰ τὸ μέγεθος, τοιούτους γίνεσθαι μετὰ ταῦτα συμβαίνει καὶ τοὺς κατὰ μέρος καιροὺς τῆς νυκτός. ἐν δὲ ταῖς συννεφέσι νυξὶ τῇ σελήνῃ προσεκτέον, ἐπεὶ διὰ τὸ μέγεθος ὡς ἐπίπαν αἰεὶ τὸ ταύτης ἐμφαίνεται φῶς, καθ’ ὃν ἂν ᾖ τόπον τοῦ κόσμου. καὶ ποτὲ μὲν ἐκ τῶν περὶ τὰς ἀνατολὰς καιρῶν καὶ τόπων στοχαστέον, ποτὲ δὲ πάλιν ἐκ τῶν περὶ τὰς δύσεις, καθυπαρχούσης καὶ περὶ τοῦτο τὸ μέρος ἐννοίας ἐπὶ τοσοῦτον ὥστε συμπεριφέρεσθαι ταῖς καθ’ ἡμέραν διαφοραῖς τῶν ἀνατολῶν. ἔστι δὲ τρόπος εὐθεώρητος καὶ περὶ ταύτην· ὅρος γὰρ εἷς μὴν ὡς τύπῳ, καὶ πρὸς αἴσθησιν τοιοῦτοι πάντες.", "st": "9.15"}, {"sp": "N", "t": "ᾗ καὶ τὸν ποιητὴν ἄν τις ἐπαινέσειε, διότι παρεισάγει τὸν Ὀδυσσέα, τὸν ἡγεμονικώτατον ἄνδρα, τεκμαιρόμενον ἐκ τῶν ἄστρων οὐ μόνον τὰ κατὰ τοὺς πλοῦς, ἀλλὰ καὶ τὰ περὶ τὰς ἐν τῇ γῇ πράξεις. ἱκανὰ γὰρ καὶ τὰ παρὰ δόξαν γινόμενα μὴ δυνάμενα τυγχάνειν προνοίας ἀκριβοῦς εἰς τὸ πολλὴν ἀπορίαν παρασκευάζειν καὶ πολλάκις, οἷον ὄμβρων καὶ ποταμῶν ἐπιφοραὶ καὶ πάγων ὑπερβολαὶ καὶ χιόνες, ἔτι δ’ ὁ καπνώδης καὶ συννεφὴς ἀὴρ καὶ τἄλλα τὰ παραπλήσια τούτοις. εἰ δὲ καὶ περὶ ὧν δυνατόν ἐστι προϊδέσθαι, καὶ τούτων ὀλιγωρήσομεν, πῶς οὐκ εἰκότως ἐν τοῖς πλείστοις ἀποτευξόμεθα δι’ αὑτούς; διόπερ οὐκ ἀφροντιστητέον οὐδενὸς τῶν προειρημένων, ἵνα μὴ τοιούτοις ἀλογήμασι περιπίπτωμεν οἵοις φασὶ περιπεσεῖν ἑτέρους τε πλείους καὶ τοὺς νῦν ὑφ’ ἡμῶν λέγεσθαι μέλλοντας ὑποδείγματος χάριν.", "st": "9.16"}, {"sp": "N", "t": "Ἄρατος ὁ τῶν Ἀχαιῶν στρατηγὸς ἐπιβαλόμενος πραξικοπεῖν τὴν τῶν Κυναιθέων πόλιν, συνετάξατο πρὸς τοὺς ἐκ τῆς πόλεως αὐτῷ συνεργοῦντας ἡμέραν, ἐν ᾗ τὸν μὲν Ἄρατον ἔδει νυκτὸς παραγενηθέντα πρὸς τὸν ἀπὸ Κυναίθης ῥέοντα ποταμὸν ὡς ἐπὶ πρεπίου μένειν ἐνσχολάσαντα μετὰ τῆς δυνάμεως, τοὺς δ’ ἔνδοθεν περὶ μέσον ἡμέρας, ὅτε λάβοιεν τὸν καιρόν, ἕνα μὲν αὑτῶν μεθ’ ἡσυχίας ἐν ἱματίῳ διὰ τῆς πύλης ἐκπέμψαι, καὶ κελεῦσαι προελθόντα στῆναι πρὸ τῆς πόλεως ἐπὶ τὸν συνταχθέντα τάφον, τοὺς δὲ λοιποὺς προσενεγκεῖν τὰς χεῖρας τοῖς ἄρχουσι, κοιμωμένοις κατὰ μέσον ἡμέρας, τοῖς εἰθισμένοις τηρεῖν τὴν πύλην. γενομένου δὲ τούτου σπουδῇ καταταχεῖν τοὺς Ἀχαιοὺς ἐκ τῆς ἐνέδρας ἔδει πρὸς τὴν πύλην. τούτων δὲ διατεταγμένων καὶ τοῦ καιροῦ συνάψαντος, ὁ μὲν Ἄρατος ἧκε καὶ κρυφθεὶς κατὰ τὸν ποταμὸν ἔμενε τηρῶν τὸ σύνθημα· περὶ δὲ πέμπτην ὥραν ἔχων τις πρόβατα μαλακὰ τῶν εἰθισμένων περὶ πόλιν τρέφειν, δεηθεὶς ἐκ τοῦ καιροῦ πυθέσθαι τι τοῦ ποιμένος βιωτικόν, ἐξῆλθε διὰ τῆς πύλης ἐν ἱματίῳ καὶ στὰς ἐπὶ τὸν αὐτὸν τάφον περιεβλέπετο τὸν ποιμένα. οἱ δὲ περὶ τὸν Ἄρατον ἀποδεδόσθαι σφίσι τὸ σύνθημα νομίσαντες σπουδῇ πρὸς τὴν πόλιν ἐφέροντο πάντες. ταχὺ δὲ τῆς πύλης κλεισθείσης ὑπὸ τῶν ἐφεστώτων διὰ τὸ μηδέπω μηδὲν ὑπὸ τῶν ἔνδον ἡτοιμάσθαι, συνέβη μὴ μόνον τῆς πράξεως ἀποτυχεῖν τοὺς περὶ τὸν Ἄρατον, ἀλλὰ καὶ τοῖς ἐκ τῆς πόλεως συμπράττουσιν αἰτίους γενέσθαι τῶν μεγίστων συμπτωμάτων· καταφανεῖς γὰρ γενόμενοι παραχρῆμα προβληθέντες ἀπέθανον. τί οὖν εἴποι τις ἂν τῆς περιπετείας αἴτιον γεγονέναι; τὸ ποιήσασθαι τὸν στρατηγὸν ἁπλοῦν τὸ σύνθημα, νέον ἀκμὴν ὄντα καὶ τῆς τῶν διπλῶν συνθημάτων καὶ παρασυνθημάτων ἀκριβείας ἄπειρον. οὕτως αἱ πολεμικαὶ πράξεις ἐν μικρῷ τὸ διαφέρον ἔχουσι τῆς ἐφ’ ἑκάτερα ῥοπῆς τῶν ἐκβαινόντων.", "st": "9.17"}, {"sp": "N", "t": "καὶ μὴν Κλεομένης ὁ Σπαρτιάτης προθέμενος διὰ πράξεως ἑλεῖν τὴν τῶν Μεγαλοπολιτῶν πόλιν, συνετάξατο τοῖς τὸ τεῖχος φυλάττουσι τὸ κατὰ τὸν Φωλεὸν καλούμενον νυκτὸς ἥξειν μετὰ τῆς δυνάμεως κατὰ τρίτην φυλακήν· τοῦτον γὰρ ἐφύλαττον τὸν καιρὸν τὸ τεῖχος οἱ συμπράττοντες αὐτῷ. οὐκέτι δὲ προνοηθεὶς ὅτι περὶ τὴν τῆς Πλειάδος ἐπιτολὴν τελέως ἤδη βραχείας εἶναι συμβαίνει τὰς νύκτας, ἐκίνησε τὴν δύναμιν ἐκ τῆς Λακεδαίμονος περὶ δυσμὰς ἡλίου. λοιπὸν οὐ δυνάμενος καταταχεῖν, ἀλλὰ τῆς ἡμέρας καταλαμβανούσης εἰκῇ καὶ ἀλόγως βιαζόμενος, αἰσχρῶς ἐξέπεσε, πολλοὺς ἀποβαλὼν καὶ κινδυνεύσας τοῖς ὅλοις· ὃς εἰ κατὰ τὸ συνταχθὲν ηὐστόχησε τοῦ καιροῦ καὶ κρατούντων τῆς εἰσόδου τῶν συνεργούντων εἰσήγαγε τὴν δύναμιν, οὐκ ἂν διεψεύσθη τῆς ἐπιβολῆς. πάλιν ὁμοίως Φίλιππος ὁ βασιλεύς, ὡς ἐπάνω προεῖπον, πρᾶξιν ἔχων ἐκ τῆς τῶν Μελιταιῶν πόλεως κατὰ δύο τρόπους ἥμαρτε· καὶ γὰρ τὰς κλίμακας ἐλάττους ἔχων ἦλθε τῆς χρείας καὶ τοῦ καιροῦ διέπεσε. συνταξάμενος γὰρ ἥξειν περὶ μέσας νύκτας κατακεκοιμημένων ἤδη πάντων, πρὸ τοῦ δέοντος καιροῦ κινήσας ἐκ Λαρίσης καὶ προσπεσὼν πρὸς τὴν τῶν Μελιταιῶν χώραν, οὔτ’ ἐπιμένειν ἐδύνατο, δεδιὼς μὴ προσαγγελθείη τοῖς ἔνδον, οὔτ’ ἀνακάμψας ἔτι λαθεῖν. διόπερ ἀναγκαζόμενος εἰς τοὔμπροσθεν προάγειν, ἧκε πρὸς τὴν πόλιν ἀκμὴν τῶν ἀνθρώπων ἐγρηγορότων. ὅθεν οὔτε διὰ τῶν κλιμάκων ἠδύνατο βιάζεσθαι διὰ τὴν ἀσυμμετρίαν οὔτε διὰ τῆς πύλης εἰσελθεῖν τῷ μὴ δύνασθαι τοὺς ἔνδον αὐτῷ συνεργεῖν διὰ τὸν καιρόν. τέλος διερεθίσας τοὺς ἐν τῇ πόλει καὶ πολλοὺς τῶν ἰδίων ἀποβαλών, μετ’ αἰσχύνης ἄπρακτος ἐπανῆλθε, πᾶσι καὶ τοῖς ἄλλοις παρηγγελκὼς ἀπιστεῖν αὐτῷ καὶ φυλάττεσθαι.", "st": "9.18"}, {"sp": "N", "t": "καὶ μὴν Νικίας ὁ τῶν Ἀθηναίων στρατηγός, δυνάμενος σῴζειν τὸ περὶ τὰς Συρακούσας στράτευμα, καὶ λαβὼν τῆς νυκτὸς τὸν ἁρμόζοντα καιρὸν εἰς τὸ λαθεῖν τοὺς πολεμίους, ἀποχωρήσας εἰς ἀσφαλές, κἄπειτα τῆς σελήνης ἐκλειπούσης δεισιδαιμονήσας, ὥς τι δεινὸν προσημαινούσης, ἐπέσχε τὴν ἀναζυγήν. καὶ παρὰ τοῦτο συνέβη κατὰ τὴν ἐπιοῦσαν αὐτοῦ νύκτα ποιησαμένου τὴν ἀναζυγήν, προαισθομένων τῶν πολεμίων, καὶ τὸ στρατόπεδον καὶ τοὺς ἡγεμόνας ὑποχειρίους γενέσθαι τοῖς Συρακοσίοις. καίτοι γε παρὰ τῶν ἐμπείρων ἱστορήσας μόνον περὶ τούτων δυνατὸς ἦν οὐχ οἷον παραλιπεῖν διὰ τὰ τοιαῦτα τοὺς ἰδίους καιρούς, ἀλλὰ καὶ συνεργοῖς χρήσασθαι διὰ τὴν τῶν ὑπεναντίων ἄγνοιαν· ἡ γὰρ τῶν πέλας ἀπειρία μέγιστον ἐφόδιον γίνεται τοῖς ἐμπείροις πρὸς κατόρθωσιν. ἐκ μὲν οὖν ἀστρολογίας μέχρι τῶν προειρημένων πολυπραγμονητέον. περὶ δὲ τῆς τῶν κλιμάκων συμμετρίας τοιοῦτός τίς ἐστιν ὁ τρόπος τῆς θεωρίας. ἐὰν μὲν γὰρ διά τινος τῶν συμπραττόντων δοθῇ τὸ τοῦ τείχους ὕψος, πρόδηλος ἡ τῶν κλιμάκων γίνεται συμμετρία· οἵων γὰρ ἂν δέκα τινῶν εἶναι συμβαίνῃ τὸ τοῦ τείχους ὕψος, τοιούτων δώδεκα δεήσει τὰς κλίμακας δαψιλῶν ὑπάρχειν. τὴν δ’ ἀπόβασιν τῆς κλίμακος πρὸς τὴν τῶν ἀναβαινόντων συμμετρίαν ἡμίσειαν εἶναι δεήσει τῆς κλίμακος, ἵνα μήτε πλεῖον ἀφιστάμεναι διὰ τὸ πλῆθος τῶν ἐπιβαινόντων εὐσύντριπτοι γίνωνται μήτε πάλιν ὀρθότεραι προσερειδόμεναι λίαν ἀκροσφαλεῖς ὦσι τοῖς προσβαίνουσιν. ἐὰν δὲ μὴ δυνατὸν ᾖ μετρῆσαι μηδ’ ἐγγίσαι τῷ τείχει, ληπτέον ἐξ ἀποστάσεως παντὸς ὕψους τὸ μέγεθος τῶν πρὸς ὀρθὰς ἐφεστώτων τοῖς ὑποκειμένοις ἐπιπέδοις. ὅ τε τρόπος τῆς λήψεως καὶ δυνατὸς καὶ ῥᾴδιος τοῖς βουλομένοις πολυπραγμονεῖν τὰ παρὰ τῶν μαθηματικῶν.", "st": "9.19"}, {"sp": "N", "t": "διὸ πάλιν ἐν τούτοις φανερὸν ὅτι δεήσει τοὺς βουλομένους εὐστοχεῖν ἐν ταῖς ἐπιβολαῖς καὶ πράξεσι γεγεωμετρηκέναι μὴ τελείως, ἀλλ’ ἐπὶ τοσοῦτον ἐφ’ ὅσον ἀναλογίας ἔννοιαν ἔχειν καὶ τῆς περὶ τὰς ὁμοιότητας θεωρίας. οὐ γὰρ περὶ ταῦτα μόνον, ἀλλὰ καὶ περὶ τὰς τῶν σχημάτων μεταλήψεις ἐν ταῖς στρατοπεδείαις ἀναγκαῖός ἐστιν ὁ τρόπος, χάριν τοῦ δύνασθαι ποτὲ μὲν πᾶν σχῆμα μεταλαμβάνοντας τηρεῖν τὴν αὐτὴν συμμετρίαν τῶν ἐν ταῖς παρεμβολαῖς περιλαμβανομένων, ποτὲ δὲ πάλιν ἐπὶ τῶν αὐτῶν σχημάτων μένοντας αὔξειν ἢ μειοῦν τὸ περιλαμβανόμενον τῇ στρατοπεδείᾳ χωρίον, κατὰ λόγον ἀεὶ τῶν προσγινομένων ἢ τῶν χωριζομένων ἐκ τῆς παρεμβολῆς· ὑπὲρ ὧν ἡμῖν ἐν τοῖς περὶ τὰς τάξεις ὑπομνήμασιν ἀκριβέστερον δεδήλωται. οὐ γὰρ οἴομαι τοῦτό γε μετρίως ἡμῖν ἐποίσειν οὐδένα διότι πολλά τινα προσαρτῶμεν τῇ στρατηγίᾳ, κελεύοντες ἀστρολογεῖν καὶ γεωμετρεῖν τοὺς ὀρεγομένους αὐτῆς. ἐγὼ δὲ τὰ μὲν ἐκ περιττοῦ παρελκόμενα τοῖς ἐπιτηδεύμασι χάριν τῆς ἐν ἑκάστοις ἐπιφάσεως καὶ στωμυλίας πολύ τι μᾶλλον ἀποδοκιμάζων, παραπλησίως δὲ καὶ τὸ πορρωτέρω τοῦ πρὸς τὴν χρείαν ἀνήκοντος ἐπιτάττειν, περὶ τἀναγκαῖα φιλοτιμότατός εἰμι καὶ σπουδάζων. καὶ γὰρ ἄτοπον τοὺς μὲν ὀρχηστικῆς ἢ τοὺς αὐλητικῆς ἐφιεμένους ἐπιδέχεσθαι τήν τε περὶ τοὺς ῥυθμοὺς καὶ τὰ μουσικὰ προκατασκευήν, ἔτι δὲ τὰ περὶ τὴν παλαίστραν, διὰ τὸ δοκεῖν προσδεῖσθαι τὸ τέλος ἑκατέρου τῆς τῶν προειρημένων συνεργίας, τοὺς δὲ στρατηγίας ἀντιποιουμένους ἀσχάλλειν, εἰ δεήσει τῶν ἐκτὸς ἐπιτηδευμάτων μέχρι τινὸς ἀναλαβεῖν. ὥστε τοὺς περὶ τὰς βαναύσους τέχνας ἀσκοῦντας ἐμμελεστέρους εἶναι καὶ φιλοτιμοτέρους τῶν περὶ τὰ κάλλιστα καὶ σεμνότατα προαιρουμένων διαφέρειν· ὧν οὐδὲν ἂν ὁμολογήσειε νοῦν ἔχων οὐδείς. καὶ περὶ μὲν τούτων ἐπὶ τοσοῦτον ἡμῖν εἰρήσθω.", "st": "9.20"}, {"sp": "N", "t": "οἱ δὲ πλεῖστοι τῶν ἀνθρώπων ἐξ αὐτῆς τῆς περιμέτρου τεκμαίρονται τὰ μεγέθη τῶν προειρημένων. λοιπὸν ὅταν εἴπῃ τις τὴν μὲν τῶν Μεγαλοπολιτῶν πόλιν πεντήκοντα σταδίων ἔχειν τὸν περίβολον, τὴν δὲ τῶν Λακεδαιμονίων ὀκτὼ καὶ τετταράκοντα, τῷ δὲ μεγέθει διπλῆν εἶναι τὴν Λακεδαίμονα τῆς Μεγάλης πόλεως, ἄπιστον αὐτοῖς εἶναι δοκεῖ τὸ λεγόμενον. ἂν δὲ καὶ συναυξῆσαί τις βουλόμενος τὴν ἀπορίαν εἴπῃ διότι δυνατόν ἐστι τετταράκοντα σταδίων πόλιν ἢ στρατοπεδείαν ἔχουσαν τὴν περιγραφὴν διπλασίαν γίνεσθαι τῆς ἑκατὸν σταδίων ἐχούσης τὴν περίμετρον, τελέως ἐκπληκτικὸν αὐτοῖς φαίνεται τὸ λεγόμενον. τοῦτο δ’ ἐστὶν αἴτιον ὅτι τῶν ἐν τοῖς παιδικοῖς μαθήμασι παραδιδομένων ἡμῖν διὰ τῆς γεωμετρίας οὐ μνημονεύομεν. περὶ μὲν οὖν τούτων προήχθην εἰπεῖν διὰ τὸ μὴ μόνον τοὺς πολλοὺς ἀλλὰ καὶ τῶν πολιτευομένων καὶ τῶν ἐν ταῖς ἡγεμονίαις ἀναστρεφομένων τινὰς ἐκπλήττεσθαι, θαυμάζοντας ποτὲ μὲν εἰ δυνατόν ἐστι μείζω τὴν τῶν Λακεδαιμονίων πόλιν εἶναι, καὶ πολλῷ μείζω, τῆς τῶν Μεγαλοπολιτῶν, τὸν περίβολον ἔχουσαν ἐλάττω, ποτὲ δὲ τὸ πλῆθος τῶν ἀνδρῶν τεκμαίρεσθαι, στοχαζομένους ἐξ αὐτῆς τῆς περιμέτρου τῶν στρατοπεδειῶν. παραπλήσιον δέ τι καὶ ἕτερον ἀδίκημα συμβαίνει περὶ τὰς τῶν πόλεων ἐπιφάσεις. οἱ γὰρ πολλοὶ τῶν ἀνθρώπων τὰς περικεκλασμένας καὶ βουνώδεις πλείους οἰκίας ὑπολαμβάνουσι κατέχεσθαι τῶν ἐπιπέδων. τὸ δ’ οὐκ ἔστι τοιοῦτον διὰ τὸ τὰ τειχία τῶν οἰκοδομιῶν μὴ τοῖς ἐγκλίμασι τῶν ἐδάφων ἀλλὰ τοῖς ὑποκειμένοις ἐπιπέδοις οἰκοδομεῖσθαι πρὸς ὀρθάς, ἐφ’ ὧν καὶ τοὺς λόφους αὐτοὺς βεβηκέναι συμβαίνει. γνοίη δ’ ἄν τις ἐκ τοῦ φαινομένου παιδικῶς ὅμως τὸ λεγόμενον. εἰ γὰρ νοήσαι τις εἰς ὕψος ἀνατεταμένας τὰς ἐν τοῖς κλίμασιν οἰκίας οὕτως ὥστε πάσας ἰσοϋψεῖς ὑπάρχειν, φανερὸν ὡς ἑνὸς ἐπιπέδου γενομένου τοῦ κατὰ τὰ τέγη τῶν οἰκιῶν, ἴσον καὶ παράλληλον ἔσται τοῦτο τῷ τοῖς λόφοις ὑποκειμένῳ καὶ τοῖς τῶν τειχῶν θεμελίοις ἐπιπέδῳ. περὶ μὲν οὖν τῶν ἡγεῖσθαι καὶ πολιτεύεσθαι βουλομένων, ἀγνοούντων δὲ τὰ τοιαῦτα καὶ θαυμαζόντων, ἐπὶ τοσοῦτον ἡμῖν εἰρήσθω.", "st": "9.21"}, {"sp": "N", "t": "ὅτι τοὺς μὴ μετ’ εὐνοίας καὶ προθυμίας ἐμβαίνοντας οὐδ’ ἐπ’ αὐτῶν εἰκός ἐστι τῶν ἔργων ἀληθεῖς εἶναι συμμάχους.", "st": "9.21"}, {"sp": "N", "t": "ὅτι τοιαύτης διαθέσεως ὑπαρχούσης περί τε τοὺς Ῥωμαίους καὶ Καρχηδονίους, καὶ παλιντρόπων ἑκατέροις ἐκ τῶν ὑπὸ τῆς τύχης ἀπαντωμένων ἐναλλὰξ προσπιπτόντων, κατὰ τὸν ποιητὴν ἅμα λύπην καὶ χαρὰν ὑποτρέχειν εἰκὸς ἦν τὰς ἑκάστων ψυχάς.", "st": "9.21b"}, {"sp": "N", "t": "καὶ ἔστιν ἀληθὲς τὸ πολλάκις ὑφ’ ἡμῶν εἰρημένον ὡς οὐχ οἷόν τε περιλαβεῖν οὐδὲ συνθεάσασθαι τῇ ψυχῇ τὸ κάλλιστον θέαμα τῶν γεγονότων, λέγω δὲ τὴν τῶν ὅλων οἰκονομίαν, ἐκ τῶν τὰς κατὰ μέρος πράξεις γραφόντων.", "st": "9.21b"}, {"sp": "N", "t": "ὅτι τῶν ἑκατέροις, Ῥωμαίοις φημὶ καὶ Καρχηδονίοις, προσπιπτόντων καὶ συμβαινόντων εἷς ἦν ἀνὴρ αἴτιος καὶ μία ψυχή, λέγω δὲ τὴν Ἀννίβου. τά τε γὰρ κατὰ τὴν Ἰταλίαν ὁμολογουμένως οὗτος ἦν ὁ χειρίζων, τά τε κατὰ τὴν Ἰβηρίαν διὰ τοῦ πρεσβυτέρου τῶν ἀδελφῶν Ἀσδρούβου, μετὰ δὲ ταῦτα διὰ τοῦ [πρεσβύτου] Μάγωνος· οἱ γὰρ τοὺς τῶν Ῥωμαίων στρατηγοὺς ἀμφοτέρους ἀποκτείναντες [ἅμα] κατὰ τὴν Ἰβηρίαν ἦσαν οὗτοι. καὶ μὴν τὰ κατὰ τὴν Σικελίαν ἔπραττε τὰς μὲν ἀρχὰς διὰ τῶν περὶ τὸν Ἱπποκράτην, ὕστερον δὲ διὰ Μυττόνου τοῦ Λίβυος. ὁμοίως δὲ καὶ κατὰ τὴν Ἑλλάδα καὶ τὴν Ἰλλυρίδα· καὶ τὸν ἀπὸ τούτων τῶν τόπων φόβον ἀνατεινόμενος ἐξέπληττε καὶ περιέσπα Ῥωμαίους διὰ τῆς πρὸς Φίλιππον κοινοπραγίας. οὕτως μέγα τι φύεται χρῆμα καὶ θαυμάσιον ἀνὴρ καὶ ψυχὴ δεόντως ἁρμοσθεῖσα κατὰ τὴν ἐξ ἀρχῆς σύστασιν πρὸς ὅ,τι ἂν ὁρμήσῃ τῶν ἀνθρωπίνων ἔργων. ἐπεὶ δ’ ἡ τῶν πραγμάτων διάθεσις εἰς ἐπίστασιν ἡμᾶς ἦχε περὶ τῆς Ἀννίβου φύσεως, ἀπαιτεῖν ὁ καιρὸς δοκεῖ μοι τὰς μάλιστα διαπορουμένας ἰδιότητας ὑπὲρ αὐτοῦ δηλῶσαι. τινὲς μὲν γὰρ ὠμὸν αὐτὸν οἴονται γεγονέναι καθ’ ὑπερβολήν, τινὲς δὲ φιλάργυρον. τὸ δ’ ἀληθὲς εἰπεῖν ὑπὲρ αὐτοῦ καὶ τῶν ἐν πράγμασιν ἀναστρεφομένων οὐ ῥᾴδιον. ἔνιοι μὲν γὰρ ἐλέγχεσθαί φασι τὰς φύσεις ὑπὸ τῶν περιστάσεων, καὶ τοὺς μὲν ἐν ταῖς ἐξουσίαις καταφανεῖς γίνεσθαι, κἂν ὅλως τὸν πρὸ τοῦ χρόνον ἀναστέλλωνται, τοὺς δὲ πάλιν ἐν ταῖς ἀτυχίαις. ἐμοὶ δ’ ἔμπαλιν οὐχ ὑγιὲς εἶναι δοκεῖ τὸ λεγόμενον· οὐ γὰρ ὀλίγα μοι φαίνονται, τὰ δὲ πλεῖστα, ποτὲ μὲν διὰ τὰς τῶν φίλων παραθέσεις, ποτὲ δὲ διὰ τὰς τῶν πραγμάτων ποικιλίας, ἄνθρωποι παρὰ τὴν αὑτῶν προαίρεσιν ἀναγκάζεσθαι καὶ λέγειν καὶ πράττειν.", "st": "9.22"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις ἐπὶ πολλῶν τῶν ἤδη γεγονότων ἐπιστήσας. τίς γὰρ Ἀγαθοκλέα τὸν Σικελίας τύραννον οὐχ ἱστόρηκε διότι δόξας ὠμότατος εἶναι κατὰ τὰς πρώτας ἐπιβολὰς καὶ τὴν κατασκευὴν τῆς δυναστείας, μετὰ ταῦτα νομίσας βεβαίως ἐνδεδέσθαι τὴν Σικελιωτῶν ἀρχὴν πάντων ἡμερώτατος δοκεῖ γεγονέναι καὶ πρᾳότατος; ἔτι δὲ Κλεομένης ὁ Σπαρτιάτης οὐ χρηστότατος μὲν βασιλεύς, πικρότατος δὲ τύραννος, εὐτραπελώτατος δὲ πάλιν ἰδιώτης καὶ φιλανθρωπότατος; καίτοι γ’ οὐκ εἰκὸς ἦν περὶ τὰς αὐτὰς φύσεις τὰς ἐναντιωτάτας διαθέσεις ὑπάρχειν· ἀλλ’ ἀναγκαζόμενοι ταῖς τῶν πραγμάτων μεταβολαῖς συμμετατίθεσθαι τὴν ἐναντίαν τῇ φύσει πολλάκις ἐμφαίνουσι διάθεσιν ἔνιοι τῶν δυναστῶν πρὸς τοὺς ἐκτός, ὥστε μὴ οἷον ἐλέγχεσθαι τὰς φύσεις διὰ τούτων, τὸ δ’ ἐναντίον ἐπισκοτεῖσθαι μᾶλλον. τὸ δ’ αὐτὸ καὶ διὰ τὰς τῶν φίλων παραθέσεις εἴωθε συμβαίνειν οὐ μόνον ἡγεμόσι καὶ δυνάσταις καὶ βασιλεῦσιν, ἀλλὰ καὶ πόλεσιν. Ἀθηναίων γοῦν εὕροι τις ἂν ὀλίγα μὲν τὰ πικρά, πολλὰ δὲ τὰ χρηστὰ καὶ σεμνὰ τῆς πολιτείας Ἀριστείδου καὶ Περικλέους προεστώτων, Κλέωνος δὲ καὶ Χάρητος τἀναντία· Λακεδαιμονίων δ’ ἡγουμένων τῆς Ἑλλάδος ὅσα μὲν διὰ Κλεομβρότου τοῦ βασιλέως πράττοιτο, πάντα συμμαχικὴν εἶχε τὴν αἵρεσιν, ὅσα δὲ δι’ Ἀγησιλάου, τοὐναντίον· ὥστε καὶ τὰ τῶν πόλεων ἔθη ταῖς τῶν προεστώτων διαφοραῖς συμμεταπίπτειν. Φίλιππος δ’ ὁ βασιλεύς, ὅτε μὲν Ταυρίων ἢ Δημήτριος αὐτῷ συμπράττοιεν, ἦν ἀσεβέστατος, ὅτε δὲ πάλιν Ἄρατος ἢ Χρυσόγονος, ἡμερώτατος.", "st": "9.23"}, {"sp": "N", "t": "παραπλήσια δέ μοι δοκεῖ τούτοις καὶ τὰ κατ’ Ἀννίβαν γεγονέναι· καὶ γὰρ περιστάσεσι παραδόξοις καὶ ποικίλαις ἐχρήσατο καὶ φίλοις τοῖς ἔγγιστα μεγάλας ἐσχηκόσι διαφοράς, ὥστε καὶ λίαν ἐκ τῶν κατ’ Ἰταλίαν πράξεων δυσθεώρητον εἶναι τὴν τοῦ προειρημένου φύσιν. τὰς μὲν οὖν τῶν περιστάσεων ὑποβολὰς εὐχερὲς καὶ διὰ τῶν προειρημένων καὶ διὰ τῶν μετὰ ταῦτα ῥηθησομένων καταμαθεῖν, τὰς δὲ τῶν φίλων οὐκ ἄξιον παραλιπεῖν, ἄλλως τε καὶ διὰ μιᾶς γνώμης ἱκανὴν τοῦ πράγματος ἔμφασιν ἐξὸν λαβεῖν. καθ’ ὃν γὰρ καιρὸν Ἀννίβας ἐξ Ἰβηρίας τὴν εἰς Ἰταλίαν πορείαν ἐπενόει στέλλεσθαι μετὰ τῶν δυνάμεων, μεγίστης προφαινομένης δυσχρηστίας περὶ τὰς τροφὰς καὶ τὴν ἑτοιμότητα τῶν ἐπιτηδείων τοῖς στρατοπέδοις, ἅτε καὶ κατὰ τὸ μῆκος ἀνήνυτον ἔχειν τι δοκούσης τῆς ὁδοῦ καὶ κατὰ τὸ πλῆθος καὶ τὴν ἀγριότητα τῶν μεταξὺ κατοικούντων βαρβάρων, τότε δοκεῖ καὶ πλεονάκις ἐν τῷ συνεδρίῳ περὶ τούτου τοῦ μέρους ἐμπιπτούσης ἀπορίας εἷς τῶν φίλων Ἀννίβας ὁ Μονομάχος ἐπικαλούμενος ἀποφήνασθαι γνώμην διότι μία τις ὁδὸς αὑτῷ προφαίνεται. δι’ ἧς ἐστιν εἰς Ἰταλίαν ἐλθεῖν ἐφικτόν. τοῦ δ’ Ἀννίβου λέγειν κελεύσαντος, διδάξαι δεῖν ἔφη τὰς δυνάμεις ἀνθρωποφαγεῖν καὶ τούτῳ ποιῆσαι συνήθεις. … Ἀννίβας δὲ πρὸς μὲν τὸ τόλμημα καὶ τὸ πρακτικὸν τῆς ἐπινοίας οὐδὲν ἀντειπεῖν ἐδυνήθη, τοῦ δὲ πράγματος λαβεῖν ἔννοιαν οὔθ’ αὑτὸν οὔτε τοὺς φίλους ἐδύνατο πεῖσαι. τούτου δὲ τἀνδρὸς εἶναί φασιν ἔργα καὶ τὰ κατὰ τὴν Ἰταλίαν εἰς Ἀννίβαν ἀναφερόμενα περὶ τῆς ὠμότητος, οὐχ ἧττον δὲ καὶ τῶν περιστάσεων.", "st": "9.24"}, {"sp": "N", "t": "φιλάργυρός γε μὴν δοκεῖ γεγονέναι διαφερόντως καὶ φίλῳ κεχρῆσθαι φιλαργύρῳ Μάγωνι τῷ τὰ κατὰ τὴν Βρεττίαν χειρίζοντι. ταύτην δὲ τὴν ἱστορίαν ἐγὼ παρέλαβον μὲν καὶ παρ’ αὐτῶν Καρχηδονίων· ἐγχώριοι γὰρ οὐ μόνον τὰς τῶν ἀνέμων στάσεις κατὰ τὴν παροιμίαν, ἀλλὰ καὶ τὰ τῶν ἐγχωρίων ἀνθρώπων ἤθη κάλλιστα γινώσκουσιν· ἔτι δὲ Μασαννάσου … ἀκριβέστερον διήκουσα, φέροντος ἀπολογισμοὺς καθόλου μὲν περὶ πάντων Καρχηδονίων, μάλιστα δὲ περὶ τῆς Ἀννίβου καὶ Μάγωνος τοῦ Σαυνίτου προσαγορευομένου φιλαργυρίας. πρὸς γὰρ τοῖς ἄλλοις ἔφη γενναιότατα κεκοινωνηκότας ἑαυτοῖς πραγμάτων τοὺς προειρημένους ἀπὸ τῆς πρώτης ἡλικίας καὶ πολλὰς μὲν πόλεις κατ’ Ἰβηρίαν, πολλὰς δὲ κατὰ τὴν Ἰταλίαν εἰληφότας ἑκατέρους, τὰς μὲν κατὰ κράτος, τὰς δ’ ἐκ παραδόσεως, οὐδέποτε μετεσχηκέναι τῆς αὐτῆς πράξεως ἀλλήλοις, ἀλλ’ ἀεὶ μᾶλλον ἑαυτοὺς ἢ τοὺς πολεμίους στρατηγεῖν χάριν τοῦ μὴ συμπαρεῖναι θάτερον θατέρῳ πόλεως καταλαμβανομένης, ἵνα μήτε διαφέρωνται πρὸς σφᾶς ἐκ τῶν τοιούτων μήτε μερίζωνται τὸ λυσιτελές, ἐφαμίλλου τῆς ὑπεροχῆς αὐτῶν ὑπαρχούσης.", "st": "9.25"}, {"sp": "N", "t": "πλὴν ὅτι γε καὶ τὴν Ἀννίβου φύσιν οὐ μόνον ἡ τῶν φίλων παράθεσις, ἔτι δὲ μᾶλλον ἡ τῶν πραγμάτων περίστασις ἐβιάζετο καὶ μετετίθετο πολλάκις, ἔκ τε τῶν προειρημένων καὶ τῶν λέγεσθαι μελλόντων ἐστὶ φανερόν. ἅμα γὰρ τῷ γενέσθαι τὴν Καπύην τοῖς Ῥωμαίοις ὑποχείριον εὐθέως ἦσαν, ὅπερ εἰκός, αἱ πόλεις μετέωροι, καὶ περιέβλεπον ἀφορμὰς καὶ προφάσεις τῆς πρὸς Ῥωμαίους μεταβολῆς· ὅτε δὴ καὶ δοκεῖ μάλιστα δυσχρηστηθεὶς Ἀννίβας εἰς ἀπορίαν ἐμπεσεῖν ὑπὲρ τῶν ἐνεστώτων. οὔτε γὰρ τηρεῖν τὰς πόλεις πάσας πολὺ διεστώσας ἀλλήλων δυνατὸς ἦν, καθίσας εἰς ἕνα τόπον, τῶν πολεμίων καὶ πλείοσι στρατοπέδοις ἀντιπαραγόντων, οὔτε διαιρεῖν εἰς πολλὰ μέρη τὴν αὑτοῦ δύναμιν οἷός τ’ ἦν. εὐχείρωτος γὰρ ἔμελλε τοῖς ἐχθροῖς ὑπάρξειν καὶ διὰ τὸ λείπεσθαι τῷ πλήθει καὶ διὰ τὸ μὴ δύνασθαι πᾶσιν αὐτὸς συμπαρεῖναι. διόπερ ἠναγκάζετο τὰς μὲν προδήλως ἐγκαταλείπειν τῶν πόλεων, ἐξ ὧν δὲ τὰς φρουρὰς ἐξάγειν, ἀγωνιῶν μὴ κατὰ τὰς μεταβολὰς τῶν πραγμάτων συγκαταφθείρῃ τοὺς ἰδίους στρατιώτας. ἐνίας δὲ καὶ παρασπονδῆσ’ ὑπέμεινε, μετανιστὰς εἰς ἄλλας πόλεις καὶ ποιῶν ἀναρπάστους αὐτῶν τοὺς βίους. ἐξ ὧν προσκόπτοντες οἱ μὲν ἀσέβειαν, οἱ δ’ ὠμότητα κατεγίνωσκον. καὶ γὰρ ἁρπαγαὶ χρημάτων ἅμα τοῖς προειρημένοις καὶ φόνοι καὶ βίαιοι προφάσεις ἐγίνοντο διά τε τῶν ἐξιόντων καὶ διὰ τῶν εἰσιόντων στρατιωτῶν εἰς τὰς πόλεις, ἑκάστων ὑπειληφότων ὅσον οὐκ ἤδη τοὺς ὑπολειπομένους μεταβαλεῖσθαι πρὸς τοὺς ὑπεναντίους. ἐξ ὧν καὶ λίαν δυσχερὲς ἀποφήνασθαι περὶ τῆς Ἀννίβου φύσεως, διά τε τὴν τῶν φίλων παράθεσιν καὶ τὴν τῶν πραγμάτων περίστασιν. κρατεῖ γε μὴν ἡ φήμη παρὰ μὲν Καρχηδοίοις ὡς φιλαργύρου, παρὰ δὲ Ῥωμαίοις ὡς ὠμοῦ γενομένου [αὐτοῦ].", "st": "9.26"}, {"sp": "N", "t": "ἡ δὲ τῶν Ἀκραγαντίνων πόλις οὐ μόνον κατὰ τὰ προειρημένα διαφέρει τῶν πλείστων πόλεων, ἀλλὰ καὶ κατὰ τὴν ὀχυρότητα, καὶ μάλιστα κατὰ τὸ κάλλος καὶ τὴν κατασκευήν. ἔκτισται μὲν γὰρ ἀπὸ θαλάττης ἐν ὀκτωκαίδεκα σταδίοις, ὥστε μηδενὸς ἀμοίρους εἶναι τῶν ἐκ ταύτης χρησίμων· ὁ δὲ περίβολος αὐτῆς καὶ φύσει καὶ κατασκευῇ διαφερόντως ἠσφάλισται. κεῖται γὰρ τὸ τεῖχος ἐπὶ πέτρας ἀκροτόμου καὶ περιρρῶγος, ᾗ μὲν αὐτοφυοῦς, ᾗ δὲ χειροποιήτου, περιέχεται δὲ ποταμοῖς· ῥεῖ γὰρ αὐτῆς παρὰ μὲν τὴν νότιον πλευρὰν ὁ συνώνυμος τῇ πόλει, παρὰ δὲ τὴν ἐπὶ τὰς δύσεις καὶ τὸν λίβα τετραμμένην ὁ προσαγορευόμενος Ὕψας. ἡ δ’ ἄκρα τῆς πόλεως ὑπέρκειται κατ’ αὐτὰς τὰς θερινὰς ἀνατολάς, κατὰ μὲν τὴν ἔξωθεν ἐπιφάνειαν ἀπροσίτῳ φάραγγι περιεχομένη, κατὰ δὲ τὴν ἐντὸς μίαν ἔχουσα πρόσοδον ἐκ τῆς πόλεως. ἐπὶ δὲ τῆς κορυφῆς Ἀθηνᾶς ἱερὸν ἔκτισται καὶ Διὸς Ἀταβυρίου, καθάπερ καὶ παρὰ Ῥοδίοις· τοῦ γὰρ Ἀκράγαντος ὑπὸ Ῥοδίων ἀπῳκισμένης, εἰκότως ὁ θεὸς οὗτος τὴν αὐτὴν ἔχει προσηγορίαν ἣν καὶ παρὰ τοῖς Ῥοδίοις. κεκόσμηται δὲ καὶ τἄλλα μεγαλοπρεπῶς ἡ πόλις ναοῖς καὶ στοαῖς. καὶ μὴν ὁ τοῦ Διὸς τοῦ Ὀλυμπίου νεὼς παντέλειαν μὲν οὐκ εἴληφε, κατὰ δὲ τὴν ἐπιβολὴν καὶ τὸ μέγεθος οὐδ’ ὁποίου τῶν κατὰ τὴν Ἑλλάδα δοκεῖ λείπεσθαι. Πολύβιος δὲ τὸν ποταμὸν καὶ τὴν πόλιν ἀπὸ τῆς χώρας ὠνομάσθαι Ἀκράγης διὰ τὸ εὔγεων. Ἀγάθυρνα, πόλις Σικελίας, ὡς Πολύβιος ἀνάτῃ. ὁ δὲ Μάρκος δοὺς πίστεις ὑπὲρ ἀσφαλείας ἔπεισεν ἐκχωρεῖν εἰς Ἰταλίαν, ἐφ’ ᾧ λαμβάνοντας μέτρημα παρὰ τῶν Ῥηγίνων πορθεῖν τὴν Βρεττιανήν, κυρίους ὄντας ὧν ἂν ἐκ τῆς πολεμίας ὠφεληθῶσι.", "st": "9.27"}, {"sp": "N", "t": "ὅτι μὲν οὖν, ὦ ἄνδρες Λακεδαιμόνιοι, τὴν Μακεδόνων δυναστείαν ἀρχὴν συνέβη γεγονέναι τοῖς Ἕλλησι δουλείας, οὐδ’ ἄλλως εἰπεῖν οὐδένα πέπεισμαι τολμῆσαι· σκοπεῖν δ’ οὕτως ἔξεστιν. ἦν τι σύστημα τῶν ἐπὶ Θρᾴκης Ἑλλήνων, οὓς ἀπῴκισαν Ἀθηναῖοι καὶ Χαλκιδεῖς, ὧν μέγιστον εἶχε πρόσχημα καὶ δύναμιν ἡ τῶν Ὀλυνθίων πόλις. ταύτην ἐξανδραποδισάμενος Φίλιππος καὶ παράδειγμα ποιήσας οὐ μόνον τῶν ἐπὶ Θρᾴκης πόλεων ἐγένετο κύριος, ἀλλὰ καὶ Θετταλοὺς ὑφ’ αὑτὸν ἐποιήσατο διὰ τὸν φόβον. μετ’ οὐ πολὺ δὲ μάχῃ νικήσας τοὺς Ἀθηναίους ἐχρήσατο μεγαλοψύχως τοῖς εὐτυχήμασιν, οὐχ ὅπως Ἀθηναίους εὖ ποιήσῃ, πολλοῦ γε δεῖν, ἀλλ’ ἵνα διὰ τῆς πρὸς ἐκείνους εὐεργεσίας προκαλέσηται τοὺς ἄλλους εἰς τὸ ποιεῖν ἐθελοντὴν αὐτῷ τὸ προσταττόμενον. ἦν ἔτι τὸ τῆς ὑμετέρας πόλεως ἀξίωμα, δοκοῦν ἂν σὺν καιρῷ προστήσεσθαι τῶν Ἑλλήνων. τοιγαροῦν πᾶσαν ἱκανὴν ποιησάμενος πρόφασιν ἧκε μετὰ τῶν δυνάμεων, καὶ κατέφθειρε μὲν τέμνων τὴν γῆν, κατέφθειρε δ’ αἴθων τὰς οἰκίας. τὸ δὲ τελευταῖον ἀποτεμόμενος καὶ τὰς πόλεις καὶ τὴν χώραν ὑμῶν προσένειμε τὴν μὲν Ἀργείοις, τὴν δὲ Τεγεάταις καὶ Μεγαλοπολίταις, τὴν δὲ Μεσσηνίοις, ἅπαντας βουλόμενος καὶ παρὰ τὸ προσῆκον εὐεργετεῖν, ἐφ’ ᾧ μόνον ὑμᾶς κακῶς ποιεῖν. διεδέξατο παρ’ αὐτοῦ τὴν ἀρχὴν Ἀλέξανδρος. οὗτος πάλιν ὑπολαβὼν βραχύ τι τῆς Ἑλλάδος ἔναυσμα καταλείπεσθαι περὶ τὴν Θηβαίων πόλιν, τίνα τρόπον αὐτὴν διέφθειρε, πάντας ὑμᾶς οἴομαι κατανοεῖν.", "st": "9.28"}, {"sp": "N", "t": "καὶ μὴν περὶ τῶν διαδεξαμένων τούτου τὰ πράγματα πῶς κέχρηνται τοῖς Ἕλλησι, τί με δεῖ κατὰ μέρος λέγειν; οὐδεὶς γάρ ἐστι τῶν ὄντων οὕτως ἀπράγμων ὃς οὐχὶ πέπυσται πῶς Ἀντίπατρος μὲν ἐν τῇ περὶ Λαμίαν μάχῃ νικήσας τοὺς Ἕλληνας κάκιστα μὲν ἐχρήσατο τοῖς ταλαιπώροις Ἀθηναίοις, ὁμοίως δὲ καὶ τοῖς ἄλλοις, εἰς τοῦτο δ’ ὕβρεως ἦλθε καὶ παρανομίας ὡς φυγαδοθήρας καταστήσας ἐξέπεμψε πρὸς τὰς πόλεις ἐπὶ τοὺς ἀντειρηκότας ἢ καθόλου λελυπηκότας τι τὴν Μακεδόνων οἰκίαν. ὧν οἱ μὲν ἐκ τῶν ἱερῶν ἀγόμενοι μετὰ βίας, οἱ δ’ ἀπὸ τῶν βωμῶν ἀποσπώμενοι, μετὰ τιμωρίας ἀπέθνησκον, οἱ δὲ διαφυγόντες ἐκ πάσης ἐξενηλατοῦντο τῆς Ἑλλάδος· φύξιμον γὰρ οὐδὲν ἦν πλὴν ἑνὸς αὐτοῖς τοῦ τῶν Αἰτωλῶν ἔθνους. τά γε μὴν Κασσάνδρῳ καὶ Δημητρίῳ πεπραγμένα, σὺν δὲ τούτοις Ἀντιγόνῳ τῷ Γονατᾷ, τίς οὐκ οἶδε; διὰ γὰρ τὸ προσφάτως αὐτὰ γεγονέναι τελέως ἐναργῆ συμβαίνει τὴν γνῶσιν αὐτῶν ὑπάρχειν. ὧν οἱ μὲν φρουρὰς εἰσάγοντες εἰς τὰς πόλεις, οἱ δὲ τυράννους ἐμφυτεύοντες οὐδεμίαν πόλιν ἄμοιρον ἐποίησαν τοῦ τῆς δουλείας ὀνόματος. ἀφέμενος δὲ τούτων ἐπάνειμι νῦν ἐπὶ τὸν τελευταῖον Ἀντίγονον, ἵνα μὴ τὴν ἐκ τούτου πρᾶξιν ἀκάκως τινὲς ὑμῶν θεωροῦντες ὑπόχρεοι χάριτι νομίζωσιν εἶναι Μακεδόσιν. οὔτε γὰρ Ἀχαιοὺς σῴζειν προαιρούμενος Ἀντίγονος ἐπανείλετο τὸν πρὸς ὑμᾶς πόλεμον οὔτε τῇ Κλεομένους τυραννίδι δυσαρεστούμενος, ἵνα Λακεδαιμονίους ἐλευθερώσῃ· καὶ λίαν γὰρ ὅ γε τοιοῦτός ἐστι τρόπος εὐήθης, εἴ τις ἄρα ταύτην ὑμῶν ἔχει τὴν διάληψιν· ἀλλ’ ὁρῶν οὐκ ἐν ἀσφαλεῖ τὴν ἑαυτοῦ δυναστείαν ἐσομένην, ἐὰν ὑμεῖς τὴν Πελοποννησίων ἀρχὴν κατακτήσησθε, πρὸς δὲ τοῦτο βλέπων εὖ πεφυκότα τὸν Κλεομένην καὶ τὴν τύχην ὑμῖν λαμπρῶς συνεργοῦσαν, ἅμα φοβηθεὶς καὶ φθονήσας παρῆν, οὐ Πελοποννησίοις βοηθήσων, ἀλλὰ τὰς ὑμετέρας ἐλπίδας ἀφελούμενος καὶ τὴν ὑμετέραν ὑπεροχὴν ταπεινώσων. διόπερ οὐκ ἐπὶ τοσοῦτον ἀγαπᾶν ὀφείλετε Μακεδόνας, ὅτι κυριεύσαντες τῆς πόλεως οὐ διήρπασαν, ἐφ’ ὅσον ἐχθροὺς νομίζειν καὶ μισεῖν, ὅτι δυναμένους ὑμᾶς ἡγεῖσθαι τῆς Ἑλλάδος πλεονάκις ἤδη κεκωλύκασι.", "st": "9.29"}, {"sp": "N", "t": "περί γε μὴν τῆς Φιλίππου παρανομίας τίς χρεία πλείω λέγειν; τῆς μὲν γὰρ εἰς τὸ θεῖον ἀσεβείας ἱκανὸν ὑπόδειγμ’ αἱ περὶ τοὺς ἐν Θέρμῳ ναοὺς ὕβρεις, τῆς δ’ εἰς τοὺς ἀνθρώπους ὠμότητος ἡ περὶ τοὺς Μεσσηνίους ἀθεσία καὶ παρασπόνδησις … Αἰτωλοὶ γὰρ μόνοι μὲν τῶν Ἑλλήνων ἀντωφθάλμησαν πρὸς Ἀντίπατρον ὑπὲρ τῆς τῶν ἀδίκως ἀκληρούντων ἀσφαλείας, μόνοι δὲ πρὸς τὴν Βρέννου καὶ τῶν ἅμα τούτῳ βαρβάρων ἔφοδον ἀντέστησαν, μόνοι δὲ καλούμενοι συνηγωνίζοντο, βουλόμενοι τὴν πάτριον ἡγεμονίαν τῶν Ἑλλήνων ὑμῖν συγκατασκευάζειν. ταῦτα μὲν οὖν ἡμῖν ἐπὶ τοσοῦτον εἰρήσθω. περὶ δὲ τοῦ νῦν ἐνεστῶτος διαβουλίου γράφειν μὲν καὶ χειροτονεῖν ἀναγκαῖόν πώς ἐστιν ὡς περὶ πολέμου βουλευομένοις, τῇ μέντοι γ’ ἀληθείᾳ μὴ νομίζειν τοῦτον εἶναι πόλεμον. Ἀχαιοὺς μὲν γὰρ οὐχ οἷον διανοησομένους βλάπτειν ὑμῶν τὴν χώραν, μεγάλην δὲ χάριν ἕξειν αὐτοὺς ὑπολαμβάνω τοῖς θεοῖς, ἐὰν δύνωνται τὴν ἰδίαν τηρεῖν, ἐπειδὰν αὐτοῖς ὁ πόλεμος ὑπ’ Ἠλείων καὶ Μεσσηνίων διὰ τὴν πρὸς ἡμᾶς συμμαχίαν, ἅμα δὲ τούτοις ὑφ’ ἡμῶν περισταθῇ. Φίλιππον δὲ πάντως πέπεισμαι λήξειν τῆς ὁρμῆς κατὰ μὲν γῆν ὑπ’ Αἰτωλῶν πολεμούμενον, κατὰ δὲ θάλατταν ὑπό τε Ῥωμαίων καὶ τοῦ βασιλέως Ἀττάλου. λίαν δ’ εὐμαρῶς ἔστι συλλογίσασθαι τὸ μέλλον ἐκ τῶν ἤδη γεγονότων. εἰ γὰρ πρὸς μόνους Αἰτωλοὺς πολεμῶν μηδέποτε δυνατὸς ἦν χειρώσασθαι τούτους, ἦ που συμβεβηκότων ἀξιόχρεως ἂν εἴη πρὸς τὸν ἐνεστῶτα πόλεμον;", "st": "9.30"}, {"sp": "N", "t": "ταῦτα μὲν οὖν εἰρήσθω μοι κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν χάριν τοῦ γνῶναι πάντας ὑμᾶς διότι καὶ μὴ προεισδεδεμένους, ἀλλ’ ἐξ ἀκεραίου βουλευομένους, μᾶλλον Αἰτωλοῖς ἡμᾶς ἢ Μακεδόσιν ἐχρῆν συμμαχεῖν. εἰ δὲ καὶ προκατέχεσθε καὶ προδιειλήφατε περὶ τούτων, τίς ἔτι καταλείπεται λόγος; εἰ γὰρ συνέθεσθε τὴν νῦν ὑπάρχουσαν ὑμῖν πρὸς ἡμᾶς συμμαχίαν πρότερον τῶν ὑπ’ Ἀντιγόνου γεγονότων εἰς ὑμᾶς εὐεργετημάτων, ἴσως ἦν εἰκὸς διαπορεῖν, εἰ δέον ἐστί, τοῖς ἐπιγεγονόσιν εἴκοντας παριδεῖν τι τῶν πρότερον ὑπαρχόντων. ἐπεὶ δὲ συντετελεσμένης ὑπ’ Ἀντιγόνου τῆς πολυθρυλήτου ταύτης ἐλευθερίας καὶ σωτηρίας, ἣν οὗτοι παρ’ ἕκαστον ὑμῖν ὀνειδίζουσι, μετὰ δὲ ταῦτα βουλευόμενοι καὶ πολλάκις ἑαυτοῖς δόντες λόγον, ποτέροις ὑμᾶς δεῖ κοινωνεῖν πραγμάτων, Αἰτωλοῖς ἢ Μακεδόσιν, εἵλεσθε μετέχειν Αἰτωλοῖς, οἷς ἐδώκατε περὶ τούτων πίστεις καὶ κατελάβετε παρ’ ἡμῶν, καὶ συμπεπολεμήκατε τὸν πρῴην συστάντα πόλεμον ἡμῖν πρὸς Μακεδόνας, τίς ἔτι δύναται περὶ τούτων εἰκότως ἐπαπορεῖν; τὰ μὲν γὰρ πρὸς Ἀντίγονον καὶ Φίλιππον ὑμῖν ὑπάρχοντα φιλάνθρωπα παρεγράφη τότε. λοιπὸν ἢ δι’ Αἰτωλῶν ἀδίκημά τι δεῖ μετὰ ταῦτα γεγονὸς εἰς ὑμᾶς δεικνύειν ἢ διὰ Μακεδόνων εὐεργεσίαν ἢ μηδετέρου τούτων ἐπιγεγονότος, πῶς, οἷς πρότερον ἐξ ἀκεραίου βουλευόμενοι δικαίως οὐ προσέσχετε, τούτων νῦν ἐντραπέντες ἀνασκευάζειν μέλλετε συνθήκας, ὅρκους, τὰς μεγίστας πίστεις παρ’ ἀνθρώποις;’ ὁ μὲν οὖν Χλαινέας τοιαῦτα διαλεχθεὶς καὶ δόξας δυσαντιρρήτως εἰρηκέναι κατέπαυσε τὸν λόγον.", "st": "9.31"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Λυκίσκος ὁ τῶν Ἀκαρνάνων πρεσβευτὴς εἰσελθὼν τὸ μὲν πρῶτον ἐπέσχε, θεωρῶν τοὺς πολλοὺς ἐν αὑτοῖς διαλαλοῦντας ὑπὲρ τῶν προειρημένων, ἐπεὶ δέ ποτε καθησύχασαν, οὕτως πως ἤρξατο τοῦ λέγειν ‘Ἡμεῖς, ἄνδρες Λακεδαιμόνιοι, παρεγενόμεθα μὲν ὑπὸ τοῦ κοινοῦ τῶν Ἀκαρνάνων ἀπεσταλμένοι πρὸς ὑμᾶς, μετέχοντες δὲ σχεδὸν ἀεί ποτε Μακεδόσι τῶν αὐτῶν ἐλπίδων καὶ τὴν πρεσβείαν ταύτην κοινὴν ὑπολαμβάνομεν ἡμῖν ὑπάρχειν καὶ Μακεδόσιν. ὥσπερ δὲ καὶ κατὰ τοὺς κινδύνους διὰ τὴν ὑπεροχὴν καὶ τὸ μέγεθος τῆς Μακεδόνων δυνάμεως ἐμπεριέχεσθαι συμβαίνει τὴν ἡμετέραν ἀσφάλειαν ἐν ταῖς ἐκείνων ἀρεταῖς, οὕτως καὶ κατὰ τοὺς πρεσβευτικοὺς ἀγῶνας ἐμπεριέχεται τὸ τῶν Ἀκαρνάνων συμφέρον ἐν τοῖς Μακεδόνων δικαίοις. διόπερ οὐ δεῖ θαυμάζειν ὑμᾶς, ἐὰν τὸν πλείω λόγον ὑπὲρ Φιλίππου ποιώμεθα καὶ Μακεδόνων. Χλαινέας τοιγαροῦν, καταστρέφων τὴν δημηγορίαν, ἀπότομόν τινα συγκεφαλαίωσιν ἐποιήσατο τῶν ὑπαρχόντων πρὸς ὑμᾶς δικαίων. ἔφη γάρ, εἰ μὲν ἐπιγέγονέ τι μετὰ τὸ θέσθαι τὴν συμμαχίαν ὑμᾶς τὴν πρὸς τούτους ἤτοι βλαβερὸν καὶ δυσχερὲς ὑπ’ Αἰτωλῶν ἢ καὶ νὴ Δία φιλάνθρωπον ὑπὸ Μακεδόνων, εἰκότως ἂν καὶ τὸ νῦν διαβούλιον ἐξ ἀκεραίου σκέψεως τυγχάνειν· εἰ δὲ μηδενὸς ἐπιγεγονότος τοιούτου τὰ κατ’ Ἀντίγονον προφερόμενοι τὰ πρότερον ὑφ’ ὑμῶν δεδοκιμασμένα πεπείσμεθα νῦν ἡμεῖς ἀνασκευάσειν ὅρκους καὶ συνθήκας, εὐηθεστάτους πάντων ἡμᾶς ὑπάρχειν. ἐγὼ δ’, εἰ μὲν μηδὲν ἐπιγέγονε κατὰ τὸν τούτου λόγον, μένει δὲ τὰ πράγματα τοιαῦτα τοῖς Ἕλλησιν οἷα πρότερον ἦν, ὅτε πρὸς αὐτοὺς Αἰτωλοὺς ἐποιεῖσθε τὴν συμμαχίαν, ὁμολογῶ πάντων εὐηθέστατος ὑπάρχειν καὶ ματαίους μέλλειν διατίθεσθαι λόγους· εἰ δὲ τὴν ἐναντίαν ἔσχηκε διάθεσιν, ὡς ἐγὼ σαφῶς δείξω προϊόντος τοῦ λόγου, καὶ λίαν ἐμὲ μὲν οἴομαι φανήσεσθαί τι λέγειν ὑμῖν τῶν συμφερόντων, Χλαινέαν δ’ ἀγνοεῖν. παραγινόμεθα μὲν οὖν ὑπὲρ αὐτοῦ τούτου πεπεισμένοι δεῖν ἡμᾶς ποιεῖσθαι τοὺς λόγους, ὑπὲρ τοῦ δεῖξαι διότι καὶ πρέπον ὑμῖν ἐστι καὶ συμφέρον, εἰ μὲν δυνατόν, ἀκούσαντας τῆς ἐπιφερομένης τοῖς Ἕλλησι περιστάσεως καλόν τι βουλεύσασθαι καὶ πρέπον ἑαυτοῖς, μετασχόντας ἡμῖν τῶν ἐλπίδων· εἰ δὲ μή, τούτων τὴν ἡσυχίαν ἔχειν κατὰ τὸ παρόν.", "st": "9.32"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀνέκαθεν οὗτοι κατηγορεῖν ἐτόλμησαν τῆς Μακεδόνων οἰκίας, ἀναγκαῖον εἶναί μοι δοκεῖ πρότερον ὑπὲρ τούτων βραχέα διαλεχθέντ’ ἀφελέσθαι τὴν ἄγνοιαν τῶν πεπιστευκότων τοῖς εἰρημένοις. ἔφη τοιγαροῦν Χλαινέας Φίλιππον τὸν Ἀμύντου διὰ τῆς Ὀλυνθίων ἀτυχίας κύριον γενέσθαι Θετταλίας. ἐγὼ δὲ διὰ Φίλιππον οὐ μόνον Θετταλούς, ἀλλὰ καὶ τοὺς λοιποὺς Ἕλληνας ὑπολαμβάνω σεσῶσθαι. καθ’ οὓς γὰρ καιροὺς Ὀνόμαρχος καὶ Φιλόμηλος καταλαβόμενοι Δελφοὺς ἀσεβῶς καὶ παρανόμως ἐγένοντο κύριοι τῶν τοῦ θεοῦ χρημάτων, τότε τίς ὑμῶν οὐκ οἶδε διότι τηλικαύτην συνεστήσαντο δύναμιν, πρὸς ἣν οὐδεὶς ἔτι τῶν Ἑλλήνων ἀντοφθαλμεῖν δυνατὸς ἦν; ἀλλ’ ἐκινδύνευον ἅμα ταῖς εἰς τὸ θεῖον ἀσεβείαις καὶ τῆς Ἑλλάδος γενέσθαι κύριοι πάσης. ἐν οἷς καιροῖς Φίλιππος ἐθελοντὴν αὑτὸν ἐπιδοὺς ἐπανείλετο μὲν τοὺς τυράννους, ἠσφαλίσατο δὲ τὰ κατὰ τὸ ἱερόν, αἴτιος δ’ ἐγένετο τοῖς Ἕλλησι τῆς ἐλευθερίας, ὡς αὐτὰ τὰ πράγματα μεμαρτύρηκε καὶ τοῖς ἐπιγενομένοις. οὐ γὰρ ὡς ἠδικηκότα Φίλιππον Θετταλούς, καθάπερ οὗτος ἐτόλμα λέγειν, ἀλλ’ ὡς εὐεργέτην ὄντα τῆς Ἑλλάδος, καὶ κατὰ γῆν αὐτὸν ἡγεμόνα καὶ κατὰ θάλατταν εἵλοντο πάντες· οὗ πρότερον ἀνθρώπων οὐδεὶς ἔτυχε. νὴ Δί’, ἀλλὰ παρεγένετο μετὰ τῆς δυνάμεως εἰς τὴν Λακωνικήν· οὐ κατά γε τὴν αὑτοῦ προαίρεσιν, ὡς ὑμεῖς ἴστε, καλούμενος δὲ καὶ πολλάκις ὀνομαζόμενος ὑπὸ τῶν ἐν Πελοποννήσῳ φίλων καὶ συμμάχων μόλις αὑτὸν ἐπέδωκε. καὶ παραγενόμενος πῶς τοῖς πράγμασιν ἐχρήσατο, ὦ Χλαινέα, σκόπει. δυνάμενος γὰρ συγχρήσασθαι ταῖς τῶν ἀστυγειτόνων ὁρμαῖς πρός τε τὴν τῆς χώρας τῆς τούτων καταφθορὰν καὶ τὴν τῆς πόλεως ταπείνωσιν, καὶ τοῦτο πρᾶξαι μετὰ τῆς μεγίστης χάριτος, ἐπὶ μὲν τὴν τοιαύτην αἵρεσιν οὐδαμῶς αὑτὸν ἐνέδωκε, καταπληξάμενος δὲ κἀκείνους καὶ τούτους ἐπὶ τῷ κοινῇ συμφέροντι διὰ λόγου τὴν ἐξαγωγὴν ἀμφοτέρους ἠνάγκασε ποιήσασθαι περὶ τῶν ἀμφισβητουμένων, οὐχ αὑτὸν ἀποδείξας κριτὴν ὑπὲρ τῶν ἀντιλεγομένων, ἀλλὰ κοινὸν ἐκ πάντων τῶν Ἑλλήνων καθίσας κριτήριον. ἄξιόν γε τὸ γεγονὸς ὀνείδους καὶ προφορᾶς.", "st": "9.33"}, {"sp": "N", "t": "πάλιν Ἀλεξάνδρῳ διότι μὲν ἀδικεῖσθαι δόξας τὴν Θηβαίων πόλιν ἐκόλασε, τοῦτο πικρῶς ὠνείδισας, ὅτι δὲ τιμωρίαν ἔλαβε παρὰ τῶν Περσῶν ὑπὲρ τῆς εἰς ἅπαντας τοὺς Ἕλληνας ὕβρεως, οὐκ ἐποιήσω μνήμην, οὐδὲ διότι μεγάλων κακῶν κοινῇ πάντας ἡμᾶς ἔλυσε, καταδουλωσάμενος τοὺς βαρβάρους καὶ παρελόμενος αὐτῶν τὰς χορηγίας, αἷς ἐκεῖνοι χρώμενοι κατέφθειραν τοὺς Ἕλληνας, ποτὲ μὲν Ἀθηναίους καὶ τοὺς τούτων προγόνους ἀγωνοθετοῦντες καὶ συμβάλλοντες, ποτὲ δὲ Θηβαίους, καὶ τέλος ὑπήκοον ἐποίησε τὴν Ἀσίαν τοῖς Ἕλλησι. περὶ δὲ τῶν διαδεξαμένων πῶς καὶ τολμᾶτε μνημονεύειν; ἐκεῖνοι γὰρ κατὰ τὰς τῶν καιρῶν περιστάσεις οἷς μὲν ἀγαθῶν οἷς δὲ κακῶν ἐγίνοντο παραίτιοι πολλάκις· περὶ ὧν τοῖς μὲν ἄλλοις ἴσως ἂν ἐξείη μνησικακεῖν, ὑμῖν δ’ οὐδαμῶς καθήκει τοῦτο ποιεῖν τοῖς ἀγαθοῦ μὲν μηδενὶ μηδενὸς παραιτίοις γεγονόσι, κακῶν δὲ πολλοῖς καὶ πολλάκις. ἐπεὶ τίνες οἱ τὸν Ἀντίγονον εἰσὶ τὸν Δημητρίου παρακαλέσαντες ἐπὶ διαιρέσει τοῦ τῶν Ἀχαιῶν ἔθνους; τίνες δ’ οἱ πρὸς τὸν Ἀλέξανδρον τὸν Ἠπειρώτην ὅρκους ποιησάμενοι καὶ συνθήκας ἐπ’ ἐξανδραποδισμῷ καὶ μερισμῷ τῆς Ἀκαρνανίας; οὐχ ὑμεῖς; τίνες δὲ κατὰ κοινὸν τοιούτους ἡγεμόνας ἐξέπεμψαν οἵους ὑμεῖς; οἵ γε καὶ τοῖς ἀσύλοις ἱεροῖς ἐτόλμησαν προσάγειν τὰς χεῖρας. ὧν Τίμαιος μὲν τό τ’ ἐπὶ Ταινάρῳ τοῦ Ποσειδῶνος καὶ τὸ τῆς ἐν Λούσοις ἱερὸν Ἀρτέμιδος ἐσύλησε, Φάρυκος δὲ καὶ Πολύκριτος, ὁ μὲν τὸ τῆς Ἥρας ἐν Ἄργει τέμενος, ὁ δὲ τὸ τοῦ Ποσειδῶνος ἐν Μαντινείᾳ διήρπασε. τί δαὶ Λάτταβος καὶ Νικόστρατος; οὐ τὴν τῶν Παμβοιωτίων πανήγυριν εἰρήνης οὔσης παρεσπόνδησαν, Σκυθῶν ἔργα καὶ Γαλατῶν ἐπιτελοῦντες; ὧν οὐδὲν πέπρακται τοῖς διαδεξαμένοις.", "st": "9.34"}, {"sp": "N", "t": "καὶ πρὸς οὐδὲν τούτων ἀπολογηθῆναι δυνάμενοι σεμνύνεσθε, διότι τὴν ἐπὶ Δελφοὺς ἔφοδον τῶν βαρβάρων ὑπέστητε, καὶ φατὲ δεῖν διὰ ταῦτα χάριν ἔχειν ὑμῖν τοὺς Ἕλληνας. ἀλλ’ εἰ διὰ μίαν ταύτην χρείαν Αἰτωλοῖς χάρις ὀφείλεται, τίνος καὶ πηλίκης δεῖ τιμῆς ἀξιοῦσθαι Μακεδόνας, οἳ τὸν πλείω τοῦ βίου χρόνον οὐ παύονται διαγωνιζόμενοι πρὸς τοὺς βαρβάρους ὑπὲρ τῆς τῶν Ἑλλήνων ἀσφαλείας; ὅτι γὰρ αἰεί ποτ’ ἂν ἐν μεγάλοις ἦν κινδύνοις τὰ κατὰ τοὺς Ἕλληνας, εἰ μὴ Μακεδόνας εἴχομεν πρόφραγμα καὶ τὰς τῶν παρὰ τούτοις βασιλέων φιλοτιμίας, τίς οὐ γινώσκει; μέγιστον δὲ τούτου σημεῖον· ἅμα γὰρ τῷ Γαλάτας καταφρονῆσαι Μακεδόνων νικήσαντας Πτολεμαῖον τὸν Κεραυνὸν ἐπικαλούμενον, εὐθέως καταγνόντες τῶν ἄλλων ἧκον οἱ περὶ Βρέννον εἰς μέσην τὴν Ἑλλάδα μετὰ δυνάμεως. ὃ πολλάκις ἂν συνέβαινε γίνεσθαι μὴ προκαθημένων Μακεδόνων. οὐ μὴν ἀλλὰ περὶ μὲν τῶν γεγονότων ἔχων πολλὰ λέγειν ἀρκεῖν ἡγοῦμαι· τῶν δὲ Φιλίππῳ πεπραγμένων εἰς ἀσέβειαν ὠνείδισαν τὴν τοῦ ναοῦ καταφθοράν, οὐ προσθέντες τὴν αὑτῶν ὕβριν καὶ παρανομίαν, ἣν ἐπετελέσαντο περὶ τοὺς ἐν Δίῳ καὶ Δωδώνῃ ναοὺς καὶ τὰ τεμένη τῶν θεῶν. ἐχρῆν δὲ λέγειν τοῦτο πρῶτον. ὑμεῖς δ’ ἃ μὲν ἐπάθετε, τούτοις ἐξηγήσασθε, μείζω ποιοῦντες τῶν γεγονότων, ἃ δ’ ἐποιήσατε πρότεροι, πολλαπλάσια γεγονότα παρεσιωπήσατε, σαφῶς εἰδότες ὅτι τὰς ἀδικίας καὶ ζημίας ἅπαντες ἀεὶ τοῖς ἄρχουσι χειρῶν ἀδίκων ἐπιφέρουσι.", "st": "9.35"}, {"sp": "N", "t": "περὶ δὲ τῶν κατ’ Ἀντίγονον ἕως τούτου βούλομαι ποιήσασθαι τὴν μνήμην, [ἕως] τοῦ μὴ δόξαι καταφρονεῖν τῶν γεγονότων μηδ’ ἐν παρέργῳ τίθεσθαι τὴν τηλικαύτην πρᾶξιν. ἔγωγ’ εὐεργεσίαν μείζω τῆς ὑπ’ Ἀντιγόνου γεγενημένης εἰς ὑμᾶς οὐδ’ ἱστορεῖσθαι νομίζω· δοκεῖ γὰρ ἔμοιγε μηδ’ ὑπερβολὴν ἐπιδέχεσθαι τὸ γεγονός. γνοίη δ’ ἄν τις ἐκ τούτων. ἐπολέμησε πρὸς ὑμᾶς Ἀντίγονος, καὶ μετὰ ταῦτα παραταξάμενος ἐνίκησε· διὰ τῶν ὅπλων ἐγένετο κύριος τῆς χώρας ἅμα καὶ τῆς πόλεως. ὤφειλε ποιεῖν τὰ τοῦ πολέμου· τοσοῦτον ἀπέσχε τοῦ πρᾶξαί τι καθ’ ὑμῶν δεινόν, ὡς πρὸς τοῖς ἄλλοις ἐκβαλὼν τὸν τύραννον καὶ τοὺς νόμους καὶ τὸ πάτριον ὑμῖν ἀποκατέστησε πολίτευμα. ἀνθ’ ὧν ὑμεῖς ἐν ταῖς κοιναῖς πανηγύρεσι μάρτυρας ποιησάμενοι τοὺς Ἕλληνας εὐεργέτην ἑαυτῶν καὶ σωτῆρα τὸν Ἀντίγονον ἀνεκηρύξατε. τί οὖν ἐχρῆν ποιεῖν ὑμᾶς; ἐρῶ γὰρ τὸ φαινόμενον, ἄνδρες. ὑμεῖς δ’ ἀνέξεσθε· ποιήσω γὰρ τοῦτο νῦν οὐκ ἀπροσλόγως ὀνειδίσαι βουλόμενος ὑμῖν, ἀλλ’ ὑπὸ τῆς τῶν πραγμάτων περιστάσεως ἀναγκαζόμενος ἐπὶ τῷ κοινῇ συμφέροντι. τί δὴ μέλλω λέγειν; ὅτι καὶ κατὰ τὸν προγεγονότα πόλεμον οὐκ Αἰτωλοῖς, ἀλλὰ Μακεδόσιν ἔδει συμμαχεῖν ὑμᾶς, καὶ νῦν παρακαλουμένους Φιλίππῳ μᾶλλον ἢ τούτοις ἑαυτοὺς προσνέμειν. νὴ Δί’, ἀλλὰ παραβήσεσθε τὰς συνθήκας· καὶ πότερα δεινότερον ἂν ποιήσαιτε, τὰ κατ’ ἰδίαν πρὸς Αἰτωλοὺς ὑμῖν συγκείμενα δίκαια παριδόντες ἢ τὰ πάντων τῶν Ἑλλήνων ἐναντίον ἐν στήλῃ γεγονότα καὶ καθιερωμένα; πῶς δὲ τούτους ἀθετεῖν εὐλαβεῖσθε, παρ’ ὧν οὐδεμίαν προειλήφατε χάριν, Φίλιππον δὲ καὶ Μακεδόνας οὐκ ἐντρέπεσθε, δι’ οὓς ἔχετε καὶ τοῦ νῦν βουλεύεσθαι τὴν ἐξουσίαν; ἢ τὸ μὲν τοῖς φίλοις τὰ δίκαια ποιεῖν ἀναγκαῖον ἡγεῖσθε; καὶ μὴν οὐχ οὕτως ὅσιόν ἐστι τὸ τὰς ἐγγράπτους πίστεις βεβαιοῦν, ὡς ἀνόσιον τὸ τοῖς σώσασι πολεμεῖν· ὃ νῦν Αἰτωλοὶ πάρεισιν ὑμᾶς ἀξιοῦντες.", "st": "9.36"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἰρήσθω μέν μοι ταῦτα, κρινέσθω δὲ παρὰ τοῖς φιλοτιμότερον διακειμένοις ἐκτὸς εἶναι τῶν ἐνεστώτων. ἐπὶ δὲ τὸ συνέχον, ὡς οὗτοί φασιν, ἐπάνιμεν. τοῦτο δ’ ἦν, εἰ μὲν ὡμοίωται τὰ πράγματα νῦν καὶ καθ’ οὓς καιροὺς ἐποιεῖσθε τὴν πρὸς τούτους συμμαχίαν, διότι δεῖ μένειν καὶ τὴν ὑμετέραν αἵρεσιν ἐπὶ τῶν ὑποκειμένων· ταῦτα γὰρ ἐν ἀρχαῖς εἶναι· εἰ δ’ ὁλοσχερῶς ἠλλοίωται, διότι δίκαιόν ἐστι καὶ νῦν ὑμᾶς ἐξ ἀκεραίου βουλεύεσθαι περὶ τῶν παρακελευομένων. ἐρωτῶ τοιγαροῦν ὑμᾶς, ὦ Κλεόνικε καὶ Χλαινέα, τίνας ἔχοντες συμμάχους τότε παρεκαλεῖτε τούτους εἰς τὴν κοινοπραγίαν; ἆρ’ οὐ πάντας Ἕλληνας; τίσι δὲ νῦν κοινωνεῖτε τῶν ἐλπίδων, ἢ πρὸς ποίαν παρακαλεῖτε τούτους συμμαχίαν; ἆρ’ οὐ πρὸς τὴν τῶν βαρβάρων; ὅμοιά γε δοκεῖ τὰ πράγμαθ’ ὑμῖν ὑπάρχειν νῦν καὶ πρότερον, ἀλλ’ οὐ τἀναντία· τότε μὲν γὰρ ὑπὲρ ἡγεμονίας καὶ δόξης ἐφιλοτιμεῖσθε πρὸς Ἀχαιοὺς καὶ Μακεδόνας ὁμοφύλους καὶ τὸν τούτων ἡγεμόνα Φίλιππον· νῦν δὲ περὶ δουλείας ἐνίσταται πόλεμος τοῖς Ἕλλησι πρὸς ἀλλοφύλους ἀνθρώπους, οὓς ὑμεῖς δοκεῖτε μὲν ἐπισπᾶσθαι κατὰ Φιλίππου, λελήθατε δὲ κατὰ σφῶν αὐτῶν ἐπεσπασμένοι καὶ κατὰ πάσης Ἑλλάδος. ὥσπερ γὰρ οἱ κατὰ τὰς πολεμικὰς περιστάσεις βαρυτέρας ἐπαγόμενοι φυλακὰς εἰς τὰς πόλεις τῆς αὑτῶν δυνάμεως χάριν τῆς ἀσφαλείας ἅμα τὸν ἀπὸ τῶν ἐχθρῶν ἀπωθοῦνται φόβον καὶ ποιοῦσιν ὑποχειρίους σφᾶς αὐτοὺς ταῖς τῶν φίλων ἐξουσίαις, τὸν αὐτὸν τρόπον καὶ νῦν Αἰτωλοὶ διανοοῦνται. βουλόμενοι γὰρ περιγενέσθαι Φιλίππου καὶ ταπεινῶσαι Μακεδόνας, λελήθασιν αὑτοῖς ἐπισπασάμενοι τηλικοῦτο νέφος ἀπὸ τῆς ἑσπέρας, ὃ κατὰ μὲν τὸ παρὸν ἴσως πρώτοις ἐπισκοτήσει Μακεδόσι, κατὰ δὲ τὸ συνεχὲς πᾶσιν ἔσται τοῖς Ἕλλησι μεγάλων κακῶν αἴτιον.", "st": "9.37"}, {"sp": "N", "t": "ἅπαντας μὲν οὖν δεῖ τοὺς Ἕλληνας προϊδέσθαι τὸν ἐπιφερόμενον καιρόν, μάλιστα δὲ Λακεδαιμονίους. ἐπεὶ τίνος χάριν ὑπολαμβάνετε τοὺς ὑμετέρους προγόνους, ἄνδρες Λακεδαιμόνιοι, καθ’ οὓς καιροὺς ὁ Ξέρξης ἀπέστειλε πρεσβευτὴν πρὸς ὑμᾶς, ὕδωρ καὶ γῆν αἰτούμενος, ἀπώσαντας εἰς τὸ φρέαρ τὸν παραγεγονότα καὶ προσεπιβαλόντας τῆς γῆς κελεύειν ἀπαγγεῖλαι τῷ Ξέρξῃ διότι παρὰ Λακεδαιμονίων ἔχει τὰ κατὰ τὴν ἐπαγγελίαν, ὕδωρ καὶ γῆν; τίνος πάλιν ἐθελοντὴν καὶ προδήλως ἐξορμᾶν ἀποθανουμένους τοὺς περὶ Λεωνίδην; ἆρ’ οὐχ ἵνα δόξωσι μὴ μόνον ὑπὲρ τῆς αὑτῶν, ἀλλὰ καὶ περὶ τῆς τῶν ἄλλων Ἑλλήνων ἐλευθερίας προκινδυνεύειν; ἄξιόν γε τοιούτων ἀνδρῶν ἀπογόνους ὑπάρχοντας, κἄπειτα νῦν συμμαχίαν ποιησαμένους τοῖς βαρβάροις, στρατεύειν μετ’ ἐκείνων καὶ πολεμεῖν Ἠπειρώταις, Ἀχαιοῖς, Ἀκαρνᾶσι, Βοιωτοῖς, Θετταλοῖς σχεδὸν πᾶσι τοῖς Ἕλλησι πλὴν Αἰτωλῶν. τούτοις μὲν οὖν ἔθος ἐστὶ ταῦτα πράττειν καὶ μηδὲν αἰσχρὸν νομίζειν, εἰ μόνον πρόσεστι τὸ πλεονεκτεῖν, οὐ μὴν ὑμῖν. καὶ τί δήποτε προσδοκᾶν δεῖ τούτους ἀπεργασομένους, ἐπεὶ τὴν Ῥωμαίων προσειλήφασι συμμαχίαν; οἵ γε τῆς Ἰλλυριῶν ἐπιλαβόμενοι ῥοπῆς καὶ βοηθείας κατὰ μὲν θάλατταν βιάζεσθαι καὶ παρασπονδεῖν ἐπεβάλοντο Πύλον, κατὰ δὲ γῆν ἐπολιόρκησαν μὲν τὴν Κλειτορίων πόλιν, ἐξηνδραποδίσαντο δὲ τὴν Κυναιθέων. καὶ πρότερον μὲν Ἀντιγόνῳ, καθάπερ ἐπάνω προεῖπον, ἐποιήσαντο συνθήκας οὗτοι περί τε τοῦ τῶν Ἀχαιῶν καὶ τοῦ τῶν Ἀκαρνάνων ἔθνους, νῦν δὲ πεποίηνται πρὸς Ῥωμαίους κατὰ πάσης τῆς Ἑλλάδος.", "st": "9.38"}, {"sp": "N", "t": "ἃ τίς οὐκ ἂν πυθόμενος ὑπίδοιτο μὲν τὴν Ῥωμαίων ἔφοδον, μισήσαι δὲ τὴν Αἰτωλῶν ἀπόνοιαν, ὅτι τοιαύτας ἐθάρρησαν ποιήσασθαι συνθήκας; ἤδη παρῄρηνται μὲν Ἀκαρνάνων Οἰνιάδας καὶ Νᾶσον· κατέσχον δὲ πρῴην τὴν τῶν ταλαιπώρων Ἀντικυρέων πόλιν, ἐξανδραποδισάμενοι μετὰ Ῥωμαίων αὐτήν. καὶ τὰ μὲν τέκνα καὶ τὰς γυναῖκας ἀπάγουσι Ῥωμαῖοι, πεισόμενα δῆλον [ὅτι] ἅπερ εἰκός ἐστι πάσχειν τοῖς ὑπὸ τὰς τῶν ἀλλοφύλων πεσοῦσιν ἐξουσίας· τὰ δ’ ἐδάφη κληρονομοῦσι τῶν ἠτυχηκότων Αἰτωλοί. καλόν γε ταύτης τῆς συμμαχίας μετασχεῖν κατὰ προαίρεσιν, ἄλλως τε καὶ Λακεδαιμονίους ὑπάρχοντας, οἵ γε Θηβαίους τοὺς κατ’ ἀνάγκην ἡσυχίαν ἄγειν βουλευσαμένους μόνους τῶν Ἑλλήνων κατὰ τὴν τῶν Περσῶν ἔφοδον ἐψηφίσαντο δεκατεύσειν τοῖς θεοῖς κρατήσαντες τῷ πολέμῳ τῶν βαρβάρων. καλὸν μὲν οὖν, ὦ ἄνδρες Λακεδαιμόνιοι, καὶ πρέπον ὑμῖν ἐστι τὸ μνησθέντας μὲν τῶν προγόνων, εὐλαβηθέντας δὲ τὴν Ῥωμαίων ἔφοδον, ὑπιδομένους δὲ τὴν Αἰτωλῶν κακοπραγμοσύνην, τὸ δὲ μέγιστον τῶν ἐξ Ἀντιγόνου γεγονότων μνησθέντας, ἔτι καὶ νῦν μισοπονηρῆσαι, καὶ τὴν μὲν Αἰτωλῶν ἀποστραφῆναι φιλίαν, Ἀχαιοῖς δὲ καὶ Μακεδόσι κοινωνῆσαι τῶν αὐτῶν ἐλπίδων. εἰ δ’ ἄρα πρὸς τοῦτό τινες ἀντιπράττουσι τῶν πλεῖον δυναμένων παρ’ ὑμῖν, πρός γε τὴν ἡσυχίαν ὁρμήσατε, καὶ μὴ μετάσχητε τῆς τούτων ἀδικίας.’", "st": "9.39"}, {"sp": "N", "t": "τὸ γὰρ τοιοῦτον ἦθος αἰεὶ βούλεται διαφυλάττειν ἡ τῶν Ἀθηναίων πόλις. προθυμίαν γὰρ φίλων συμφόρως μὲν γινομένην μεγάλην παρέχεσθαι χρείαν, ἐφελκομένην δὲ καὶ καθυστεροῦσαν τελέως ἀνωφελῆ ποιεῖν τὴν ἐπικουρίαν. εἴπερ οὖν βούλονται μὴ τοῖς γράμμασι μόνον, ἀλλὰ καὶ τοῖς ἔργοις τηρεῖν τὴν πρὸς αὐτοὺς συμμαχίαν … οἱ δὲ Ἀκαρνᾶνες, πυνθανόμενοι τὴν τῶν Αἰτωλῶν ἔφοδον ἐπὶ σφᾶς, τὰ μὲν ἀπαλγοῦντες ταῖς ἐλπίσι, τὰ δὲ καὶ θυμομαχοῦντες, ἐπί τινα παράστασιν κατήντησαν. εἰ δέ τις λειπόμενος μὴ θάνοι, φύγοι δὲ τὸν κίνδυνον, τοῦτον μήτε πόλει δέχεσθαι μήτε πῦρ ἐναύειν. περὶ τούτων ἀρὰς ἐποιήσαντο πᾶσι μέν, μάλιστα δὲ τοῖς Ἠπειρώταις, εἰς τὸ μηδένα τῶν φευγόντων δέξασθαι τῇ χώρᾳ.", "st": "9.40"}, {"sp": "N", "t": "προθέμενος δὲ τῆς πόλεως κατὰ δύο πύργους ποιεῖσθαι τὴν προσαγωγὴν κατὰ μὲν τούτους χελώνας κατεσκεύαζε χωστρίδας καὶ κριούς, κατὰ δὲ τὸ μεσοπύργιον στοὰν ἐποίει μεταξὺ τῶν κριῶν παράλληλον τῷ τείχει. τῆς δὲ προθέσεως συντελουμένης παραπλήσιος ἡ τῶν ἔργων ἐγίνετο πρόσοψις τῇ τοῦ τείχους διαθέσει· τὰ μὲν γὰρ ἐπὶ ταῖς χελώναις κατασκευάσματα πύργων ἐλάμβανε καὶ φαντασίαν καὶ διάθεσιν ἐκ τῆς τῶν γέρρων συνθέσεως, τὸ δὲ μεταξὺ τούτων τείχους, τῶν ἀνωτέρω γέρρων τῆς στοᾶς εἰς ἐπάλξεις τῇ πλοκῇ διῃρημένων. διὰ μὲν οὖν τοῦ κάτω μέρους τῶν πύργων οἵ τε προσχωννύντες τὰς ἀνωμαλίας τῶν τόπων ἐπὶ τῇ τῶν ἐσχαρίων ἐφόδῳ τὴν γῆν ἐπέβαλλον ὅ τε κριὸς ἐξωθεῖτο. τὸ δὲ δεύτερον ὑδρίας καὶ τὰς πρὸς τοὺς ἐμπυρισμοὺς εἶχε παρασκευὰς καὶ τὰ καταπελτικὰ σὺν τούτοις. ἐπὶ δὲ τοῦ τρίτου πλῆθος ἀνδρῶν ἐφειστήκει τῶν ἀπομαχομένων πρὸς τοὺς κακοποιεῖν ἐπιβαλλομένους τὸν κριόν. οὗτοι δ’ ἦσαν ἰσοϋψεῖς τοῖς τῆς πόλεως πύργοις. ἐκ δὲ τῆς μεταξὺ τῶν πύργων στοᾶς ὀρύγματα διπλᾶ προσήγετο πρὸς τὸ μεσοπύργιον. καὶ τρεῖς ἦσαν βελοστάσεις λιθοβόλοις, ὧν ὁ μὲν εἷς ταλαντιαίους, οἱ δὲ δύο τριακονταμναίους ἐξέβαλλον λίθους. ἀπὸ δὲ τῆς παρεμβολῆς ὡς πρὸς τὰς χελώνας τὰς χωστρίδας ἐπεποίηντο σύριγγες κατάστεγοι χάριν τοῦ μήτε τοὺς προσιόντας ἐκ τῆς στρατοπεδείας μήτε τοὺς ἀπιόντας ἀπὸ τῶν ἔργων βλάπτεσθαι μηδὲν ὑπὸ τῶν ἐκ τῆς πόλεως βελῶν. ἐν ὀλίγαις δὲ τελέως ἡμέραις συνέβη καὶ τὴν τῶν ἔργων ἐπιτελεσθῆναι συντέλειαν διὰ τὸ τὴν χώραν ἀφθόνους ἔχειν τὰς εἰς τοῦτο τὸ μέρος χορηγίας. οἱ γὰρ Ἐχιναιεῖς κεῖνται μὲν ἐν τῷ Μηλιεῖ κόλπῳ, τετραμμένοι πρὸς μεσημβρίαν, καταντίπεραν τῆς τῶν Θρονιέων χώρας, καρποῦνται δὲ γῆν πάμφορον. δι’ ἣν αἰτίαν οὐδὲν ἐνέλειπε τὸν Φίλιππον τῶν πρὸς τὰς ἐπιβολάς. οὐ μὴν ἀλλά, καθάπερ εἶπον, ἐπιτελεσθέντων τῶν ἔργων προσῆγον ἅμα τὰς τῶν ὀρυγμάτων καὶ μηχανημάτων κατασκευάς.", "st": "9.41"}, {"sp": "N", "t": "Πόπλιος ὁ τῶν Ῥωμαίων στρατηγὸς καὶ Δωρίμαχος ὁ τῶν Αἰτωλῶν, τοῦ Φιλίππου πολιορκοῦντος τὴν Ἐχιναιῶν πόλιν, καὶ τὰ πρὸς τὸ τεῖχος καλῶς ἀσφαλισαμένου καὶ τὰ πρὸς τὴν ἐκτὸς ἐπιφάνειαν τοῦ στρατοπέδου τάφρῳ καὶ τείχει ὀχυρωσαμένου, παραγενόμενοι αὐτοί, ὁ μὲν Πόπλιος στόλῳ, ὁ δὲ Δωρίμαχος πεζικῇ καὶ ἱππικῇ δυνάμει, καὶ προσβαλόντες τῷ χάρακι καὶ ἀποκρουσθέντες, τοῦ Φιλίππου μᾶλλον ἰσχυρῶς ἀγωνισαμένου, ἀπελπίσαντες οἱ Ἐχιναιεῖς παρέδοσαν ἑαυτοὺς τῷ Φιλίππῳ. οὐ γὰρ οἷοί τε ἦσαν οἱ περὶ τὸν Δωρίμαχον τῇ τῶν δαπανημάτων ἐνδείᾳ ἀναγκάζειν τὸν Φίλιππον, ἐκ θαλάττης ταῦτα ποριζόμενον. ὅτι τῆς Αἰγίνης ὑπὸ Ῥωμαίων ἁλούσης, [οἱ] Αἰγινῆται συναθροισθέντες ἐπὶ τὰς ναῦς, ὅσοι μὴ διεκλάπησαν, ἐδέοντο τοῦ στρατηγοῦ συγχωρῆσαι σφίσι πρεσβευτὰς ἐκπέμψαι πρὸς τὰς συγγενεῖς πόλεις περὶ λύτρων· ὁ δὲ Πόπλιος τὸ μὲν πρῶτον πικρῶς ἀντέφη, φάσκων, ὅτ’ ἦσαν αὑτῶν κύριοι, τότε δεῖν διαπρεσβεύεσθαι πρὸς τοὺς κρείττους περὶ σωτηρίας, μὴ νῦν δούλους γεγονότας· τὸ δὲ μικρῷ πρότερον αὐτοὺς μηδὲ λόγου καταξιώσαντας τοὺς παρ’ αὐτοῦ πρεσβευτάς, νῦν ὑποχειρίους γεγονότας ἀξιοῦν πρεσβεύειν πρὸς τοὺς συγγενεῖς, πῶς οὐκ εὔηθες εἶναι; καὶ τότε μὲν ἀπέπεμψε τοὺς ἐντυγχάνοντας ταῦτ’ εἰπών· τῇ δ’ ἐπαύριον συγκαλέσας ἅπαντας τοὺς αἰχμαλώτους, Αἰγινήταις μὲν οὐδὲν ὀφείλειν ἔφη ποιεῖν φιλάνθρωπον, τῶν δὲ λοιπῶν Ἑλλήνων ἕνεκα συγχωρεῖν ἔφη πρεσβεύειν περὶ τῶν λύτρων, ἐπεὶ τοῦτο παρ’ αὐτοῖς ἔθος ἐστίν.", "st": "9.42"}, {"sp": "N", "t": "ὁ γὰρ Εὐφράτης τὴν μὲν ἀρχὴν λαμβάνει τῆς συστάσεως ἐξ Ἀρμενίας, διαρρεῖ δὲ [τὸν] διὰ Συρίας καὶ τῶν ἑξῆς τόπων ὡς ἐπὶ Βαβυλωνίαν. καὶ δοκεῖ μὲν εἰς τὴν Ἐρυθρὰν ἐμβάλλειν θάλατταν, οὐ μὴν ἔστι γε τοῦτο· ταῖς γὰρ διώρυξι ταῖς ἐπὶ τὴν χώραν ἀγομέναις προεκδαπανᾶται πρὶν ἐκβολὴν εἰς θάλατταν πεποιῆσθαι. διὸ καὶ συμβαίνει τὴν ὑπεναντίαν φύσιν ἔχειν τοῦτον τοῖς πλείστοις τῶν ποταμῶν. τοῖς μὲν γὰρ ἄλλοις αὔξεται τὸ ῥεῦμα, καθὼς ἂν πλείους διαφέρωνται τόπους, καὶ μέγιστοι μέν εἰσι κατὰ χειμῶνα, ταπεινότατοι δὲ κατὰ τὴν ἀκμὴν τοῦ θέρους· οὗτος δὲ καὶ πλεῖστος γίνεται τῷ ῥεύματι κατὰ κυνὸς ἐπιτολὴν καὶ μέγιστος ἐν τοῖς κατὰ Συρίαν τόποις, αἰεὶ δὲ προϊὼν ἐλάττων. αἴτιον δὲ τούτων ὅτι συμβαίνει τὴν μὲν αὔξησιν οὐκ ἐκ τῆς συρρύσεως τῶν χειμερινῶν ὄμβρων, ἀλλ’ ἐκ τῆς ἀνατήξεως τῶν χιόνων γίνεσθαι, τὴν δὲ μείωσιν διὰ τὰς ἐκτροπὰς τὰς ἐπὶ τὴν χώραν καὶ τὸν μερισμὸν αὐτοῦ τὸν ἐπὶ τὰς ἀρδεύσεις. ᾗ καὶ τότε βραδεῖαν συνέβαινε γίνεσθαι τὴν κομιδὴν τῶν δυνάμεων, ἅτε καταγόμων μὲν ὄντων τῶν πλοίων, ταπεινοτάτου δὲ τοῦ ποταμοῦ καὶ τελέως βραχύ τι συνεργούσης τῆς τοῦ ῥεύματος βίας πρὸς τὸν πλοῦν.", "st": "9.43"}, {"sp": "N", "t": "ὅτι οἱ Ῥωμαῖοι πρεσβευτὰς ἐξαπέστειλαν πρὸς Πτολεμαῖον, βουλόμενοι σίτῳ χορηγηθῆναι διὰ τὸ μεγάλην εἶναι παρ’ αὐτοῖς σπάνιν, ὡς ἂν τοῦ μὲν κατὰ τὴν Ἰταλίαν ὑπὸ τῶν στρατοπέδων ἅπαντος ἐφθαρμένου μέχρι τῶν τῆς Ῥώμης πυλῶν, ἔξωθεν δὲ μὴ γενομένης ἐπικουρίας, ἅτε κατὰ πάντα τὰ μέρη τῆς οἰκουμένης πολέμων ἐνεστώτων καὶ στρατοπέδων παρακαθημένων, πλὴν τῶν κατ’ Αἴγυπτον τόπων. εἰς γὰρ τοσοῦτον κατὰ τὴν Ῥώμην προεβεβήκει τὰ τῆς ἐνδείας ὥστε τὸν Σικελικὸν μέδιμνον πεντεκαίδεκα δραχμῶν ὑπάρχειν. ἀλλ’ ὅμως τοιαύτης οὔσης τῆς περιστάσεως οὐκ ἠμέλουν τῶν πολεμικῶν. —", "st": "9.44"}, {"sp": "N", "t": "Πολύβιος δ’ ἐν τῇ ἐνάτῃ τῶν Ἱστοριῶν καὶ ποταμόν τινα ἀναγράφει Κύαθον καλούμενον περὶ Ἀρσινόην πόλιν Αἰτωλίας. Ἀρσινόη, πόλις Λιβύης. … τὸ ἐθνικὸν Ἀρσινοΐτης, καὶ Ἀρσινοεὺς ἐπὶ τῆς Αἰτωλικῆς, ὡς Πολύβιος ἐνάτῳ. Ξυνία, Θετταλίας πόλις. Πολύβιος ἐνάτῳ. Φόρουννα, πόλις Θρᾴκης· Πολύβιος ἐνάτῳ.", "st": "9.45"}, {"sp": "HDR", "t": "Βιβλίον Ιʹ", "st": "10"}, {"sp": "N", "t": "ὄντων γὰρ ἀπὸ τοῦ πορθμοῦ καὶ τῆς Ῥηγίνων πόλεως σταδίων εἰς Τάραντα πλειόνων ἢ δισχιλίων, εἰς τέλος ἀλίμενον εἶναι συμβαίνει τὴν πλευρὰν τῆς Ἰταλίας ταύτην πλὴν τῶν ἐν Τάραντι λιμένων· ἣ τέτραπται μὲν εἰς τὸ Σικελικὸν πέλαγος, νεύει δὲ πρὸς τοὺς κατὰ τὴν Ἑλλάδα τόπους, ἔχει δὲ τῶν τε βαρβάρων ἐθνῶν τὰ πολυανθρωπότατα καὶ τῶν Ἑλληνίδων πόλεων τὰς ἐπιφανεστάτας. Βρέττιοι γὰρ καὶ Λευκανοὶ καί τινα μέρη τῶν Δαυνίων, ἔτι δὲ Καλαβροὶ καὶ πλείους ἕτεροι τοῦτο τὸ κλῖμα νέμονται τῆς Ἰταλίας· ὁμοίως δὲ καὶ τῶν Ἑλληνίδων πόλεων Ῥήγιον καὶ Καυλωνία καὶ Λοκροὶ καὶ Κρότων, ἔτι δὲ Μεταπόντιον καὶ Θούριοι ταύτην ἐπέχουσι τὴν παραλίαν, ὥστε καὶ τοὺς ἀπὸ Σικελίας καὶ τοὺς ἀπὸ τῆς Ἑλλάδος φερομένους ἐπί τινα τόπον τῶν προειρημένων κατ’ ἀνάγκην ὁρμεῖν ἐν τοῖς τῶν Ταραντίνων λιμέσι, καὶ τὰς ἀμείψεις καὶ τὰς οἰκονομίας πρὸς πάντας τοὺς κατέχοντας ταύτην τὴν πλευρὰν τῆς Ἰταλίας ἐν ταύτῃ ποιεῖσθαι τῇ πόλει. τεκμήραιτο δ’ ἄν τις τοῦ τόπου τὴν εὐκαιρίαν ἐκ τῆς περὶ Κροτωνιάτας γενομένης εὐδαιμονίας. ἐκεῖνοι γὰρ θερινοὺς ἔχοντες ὅρμους καὶ βραχεῖάν τινα παντελῶς προσαγωγήν, μεγάλην εὐδαιμονίαν δοκοῦσι περιποιήσασθαι δι’ οὐδὲν ἕτερον ἢ διὰ τὴν τῶν τόπων εὐφυΐαν, ἣν οὐδὲ συγκρίνειν ἄξιόν ἐστι τοῖς Ταραντίνων λιμέσι καὶ τόποις. τέτακται δὲ καὶ πρὸς τοὺς κατὰ τὸν Ἀδρίαν λιμένας εὐφυῶς καὶ νῦν μέν, ἔτι δὲ μᾶλλον ἦν πρὸ τοῦ. ἀπὸ γὰρ ἄκρας Ἰαπυγίας ἕως εἰς Σιποῦντα πᾶς ὁ προσφερόμενος ἐκ τῶν ἀντιπέρας καὶ καθορμισθεὶς πρὸς τὴν Ἰταλίαν εἰς Τάραντ’ ἐποιεῖτο τὴν ὑπερβολήν, καὶ ταύτῃ συνεχρῆτο τῇ πόλει πρὸς τὰς ἀλλαγὰς καὶ μεταθέσεις οἷον [εἰ] ἐμπορίῳ· οὐδέπω γὰρ συνέβαινε τότε τὴν τῶν Βρεντεσίνων ἐκτίσθαι πόλιν. διόπερ ὁ Φάβιος, ἐν μεγάλῳ τιθέμενος τὴν ἐπιβολήν, τἄλλα παρεὶς πρὸς ταῖς εἰς τοῦτο τὸ μέρος ἦν ἐπινοίαις.", "st": "10.1"}, {"sp": "N", "t": "ὅτι μέλλοντες ἱστορεῖν τὰ πραχθέντα Ποπλίῳ κατὰ τὴν Ἰβηρίαν, συλλήβδην δὲ πάσας τὰς κατὰ τὸν βίον ἐπιτελεσθείσας αὐτῷ πράξεις, ἀναγκαῖον ἡγούμεθα τὸ προεπιστῆσαι τοὺς ἀκούοντας ἐπὶ τὴν αἵρεσιν καὶ φύσιν τἀνδρός. τῷ γὰρ σχεδὸν ἐπιφανέστατον αὐτὸν γεγονέναι τῶν πρὸ τοῦ, ζητοῦσι μὲν πάντες εἰδέναι τίς ποτ’ ἦν καὶ ἀπὸ ποίας φύσεως ἢ τριβῆς ὁρμηθεὶς τὰς τηλικαύτας καὶ τοσαύτας ἐπετελέσατο πράξεις, ἀγνοεῖν δὲ καὶ ψευδοδοξεῖν ἀναγκάζονται διὰ τὸ τοὺς ἐξηγουμένους ὑπὲρ αὐτοῦ παραπεπαικέναι τῆς ἀληθείας. ὅτι δ’ ἔστιν ὑγιὲς τὸ νυνὶ λεγόμενον ὑφ’ ἡμῶν δῆλον ἔσται διὰ τῆς ἡμετέρας ἐξηγήσεως τοῖς ἐπισημαίνεσθαι δυναμένοις τὰ κάλλιστα καὶ παραβολώτατα τῶν ἐκείνῳ πεπραγμένων. οἱ μὲν οὖν ἄλλοι πάντες αὐτὸν ἐπιτυχῆ τινα καὶ τὸ πλεῖον αἰεὶ παραλόγως καὶ ταὐτομάτῳ κατορθοῦντα τὰς ἐπιβολὰς παρεισάγουσι, νομίζοντες ὡς ἂν εἰ θειοτέρους εἶναι καὶ θαυμαστοτέρους τοὺς τοιούτους ἄνδρας τῶν κατὰ λόγον ἐν ἑκάστοις πραττόντων, ἀγνοοῦντες ὅτι τὸ μὲν ἐπαινετόν, τὸ δὲ μακαριστὸν εἶναι συμβαίνει τῶν προειρημένων, καὶ τὸ μὲν κοινόν ἐστι καὶ τοῖς τυχοῦσι, τὸ δ’ ἐπαινετὸν μόνον ἴδιον ὑπάρχει τῶν εὐλογίστων καὶ φρένας ἐχόντων ἀνδρῶν, οὓς καὶ θειοτάτους εἶναι καὶ προσφιλεστάτους τοῖς θεοῖς νομιστέον. ἐμοὶ δὲ δοκεῖ Πόπλιος Λυκούργῳ τῷ τῶν Λακεδαιμονίων νομοθέτῃ παραπλησίαν ἐσχηκέναι φύσιν καὶ προαίρεσιν. οὔτε γὰρ Λυκοῦργον ἡγητέον δεισιδαιμονοῦντα καὶ πάντα προσέχοντα τῇ Πυθίᾳ συστήσασθαι τὸ Λακεδαιμονίων πολίτευμα, οὔτε Πόπλιον ἐξ ἐνυπνίων ὁρμώμενον καὶ κληδόνων τηλικαύτην περιποιῆσαι τῇ πατρίδι δυναστείαν· ἀλλ’ ὁρῶντες ἑκάτεροι τοὺς πολλοὺς τῶν ἀνθρώπων οὔτε τὰ παράδοξα προσδεχομένους ῥᾳδίως οὔτε τοῖς δεινοῖς τολμῶντας παραβάλλεσθαι χωρὶς τῆς ἐκ τῶν θεῶν ἐλπίδος, Λυκοῦργος μὲν αἰεὶ προσλαμβανόμενος ταῖς ἰδίαις ἐπιβολαῖς τὴν ἐκ τῆς Πυθίας φήμην εὐπαραδεκτοτέρας καὶ πιστοτέρας ἐποίει τὰς ἰδίας ἐπινοίας, Πόπλιος δὲ παραπλησίως ἐνεργαζόμενος αἰεὶ δόξαν τοῖς πολλοῖς ὡς μετά τινος θείας ἐπιπνοίας ποιούμενος τὰς ἐπιβολάς, εὐθαρσεστέρους καὶ προθυμοτέρους κατεσκεύαζε τοὺς ὑποταττομένους πρὸς τὰ δεινὰ τῶν ἔργων. ὅτι δ’ ἕκαστα μετὰ λογισμοῦ καὶ προνοίας ἔπραττε, καὶ διότι πάντα κατὰ λόγον ἐξέβαινε τὰ τέλη τῶν πράξεων αὐτῷ, δῆλον ἔσται διὰ τῶν λέγεσθαι μελλόντων.", "st": "10.2"}, {"sp": "N", "t": "ἐκεῖνος γὰρ ὅτι μὲν ἦν εὐεργετικὸς καὶ μεγαλόψυχος ὁμολογεῖται, διότι δ’ ἀγχίνους καὶ νήπτης καὶ τῇ διανοίᾳ περὶ τὸ προτεθὲν ἐντεταμένος, οὐθεὶς ἂν συγχωρήσειε πλὴν τῶν συμβεβιωκότων καὶ τεθεαμένων ὑπ’ αὐγὰς αὐτοῦ τὴν φύσιν. ὧν εἷς ἦν Γάιος Λαίλιος, ἀπὸ νέου μετεσχηκὼς αὐτῷ παντὸς ἔργου καὶ λόγου μέχρι τελευτῆς, ὁ ταύτην περὶ αὐτοῦ τὴν δόξαν ἡμῖν ἐνεργασάμενος διὰ τὸ δοκεῖν εἰκότα λέγειν καὶ σύμφωνα τοῖς ὑπ’ ἐκείνου πεπραγμένοις. ἔφη γὰρ πρώτην γεγονέναι Ποπλίου πρᾶξιν ἐπίσημον, καθ’ ὃν καιρὸν ὁ πατὴρ αὐτοῦ τὴν ἱππομαχίαν συνεστήσατο πρὸς Ἀννίβαν περὶ τὸν Πάδον καλούμενον ποταμόν. τότε γάρ, ὡς ἔοικεν, ἑπτακαιδέκατον ἔτος ἔχων καὶ πρῶτον εἰς ὕπαιθρον ἐξεληλυθώς, συστήσαντος αὐτῷ τοῦ πατρὸς διαφερόντων ἱππέων οὐλαμὸν ἀσφαλείας χάριν, συνθεασάμενος ἐν τῷ κινδύνῳ τὸν πατέρα περιειλημμένον ὑπὸ τῶν πολεμίων μετὰ δυεῖν ἢ τριῶν ἱππέων καὶ τετρωμένον ἐπισφαλῶς, τὰς μὲν ἀρχὰς ἐπεβάλετο παρακαλεῖν τοὺς μεθ’ αὑτοῦ βοηθῆσαι τῷ πατρί, τῶν δ’ ἐπὶ ποσὸν κατορρωδούντων διὰ τὸ πλῆθος τῶν περιεστώτων πολεμίων, αὐτὸς εἰσελάσαι παραβόλως δοκεῖ καὶ τολμηρῶς εἰς τοὺς περικεχυμένους. μετὰ δὲ ταῦτα καὶ τῶν ἄλλων ἀναγκασθέντων ἐμβαλεῖν οἱ μὲν πολέμιοι καταπλαγέντες διέστησαν, ὁ δὲ Πόπλιος ἀνελπίστως σωθεὶς πρῶτος αὐτὸς τὸν υἱὸν σωτῆρα προσεφώνησε πάντων ἀκουόντων. περιγενομένης δ’ αὐτῷ τῆς ἐπ’ ἀνδρείᾳ φήμης ὁμολογουμένης διὰ τὴν προειρημένην χρείαν, λοιπὸν ἤδη πάντως αὑτὸν ἐδίδου κατὰ τοὺς ὕστερον καιροὺς εἰς τοὺς κατ’ ἰδίαν κινδύνους, ὅτ’ εἰς αὐτὸν ἀναρτηθεῖεν ὑπὸ τῆς πατρίδος αἱ τῶν ὅλων ἐλπίδες· ὅπερ ἴδιόν ἐστιν οὐ τῇ τύχῃ πιστεύοντος, ἀλλὰ νοῦν ἔχοντος ἡγεμόνος.", "st": "10.3"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα, πρεσβύτερον ἔχων ἀδελφὸν Λεύκιον, καὶ τούτου προσπορευομένου πρὸς τὴν ἀγορανομίαν, ἣν σχεδὸν ἐπιφανεστάτην ἀρχὴν εἶναι συμβαίνει τῶν νέων παρὰ Ῥωμαίοις, ἔθους δ’ ὄντος δύο πατρικίους καθίστασθαι, τότε δὲ καὶ πλειόνων προσπορευομένων, ἐκ πολλοῦ μὲν οὐκ ἐτόλμα μεταπορεύεσθαι τὴν αὐτὴν ἀρχὴν τἀδελφῷ· συνεγγιζούσης δὲ τῆς καταστάσεως, λογιζόμενος ἐκ τῆς τοῦ πλήθους φορᾶς οὐκ εὐμαρῶς τὸν ἀδελφὸν ἐφιξόμενον τῆς ἀρχῆς, τὴν δὲ πρὸς αὑτὸν εὔνοιαν τοῦ δήμου θεωρῶν μεγάλην ὑπάρχουσαν, καὶ μόνως οὕτως ὑπολαμβάνων κἀκεῖνον καθίξεσθαι τῆς προθέσεως, εἰ συμφρονήσαντες ἅμα ποιήσαιντο τὴν ἐπιβολήν, ἦλθεν ἐπί τινα τοιαύτην ἔννοιαν. θεωρῶν γὰρ τὴν μητέρα περιπορευομένην τοὺς νεὼς καὶ θύουσαν τοῖς θεοῖς ὑπὲρ τἀδελφοῦ καὶ καθόλου μεγάλην προσδοκίαν ἔχουσαν ὑπὲρ τοῦ μέλλοντος, ἧς μόνης ἔμελεν αὐτῷ — τὸν μὲν γὰρ πατέρα τότε πλεῖν συνέβαινεν εἰς Ἰβηρίαν στρατηγὸν καθεσταμένον ἐπὶ τὰς προειρημένας πράξεις — οὐ μὴν ἀλλ’ ἔφη πρὸς αὐτὴν ὄνειρον τεθεωρηκέναι δὶς ἤδη τὸν αὐτόν. δοκεῖν γὰρ ἅμα τἀδελφῷ καθεσταμένος ἀγορανόμος ἀναβαίνειν ἀπὸ τῆς ἀγορᾶς ὡς ἐπὶ τὴν οἰκίαν, ἐκείνην δὲ συναντᾶν αὐτοῖς εἰς τὰς θύρας καὶ περιπτύξασαν ἀσπάσασθαι. τῆς δὲ παθούσης τὸ γυναικεῖον πάθος καί τι προσεπιφθεγξαμένης \"Εἰ γὰρ ἐμοὶ ταύτην ἰδεῖν γένοιτο τὴν ἡμέραν\" \"Βούλει\" φησί \"μῆτερ, πεῖραν λάβωμεν;\" τῆς δὲ συγκαταθεμένης, ὡς οὐ τολμήσοντος αὐτοῦ, πρὸς δὲ τὸν καιρὸν οἱονεὶ προσπαίζοντος — καὶ γὰρ ἦν κομιδῇ νέος — ἠξίου τήβενναν αὑτῷ λαμπρὰν εὐθέως ἑτοιμάσαι· τοῦτο γὰρ ἔθος ἐστὶ τοῖς τὰς ἀρχὰς μεταπορευομένοις.", "st": "10.4"}, {"sp": "N", "t": "καὶ τῇ μὲν οὐδ’ ἐν νῷ τὸ ῥηθὲν ἦν, ὁ δὲ λαβὼν πρῶτον λαμπρὰν ἐσθῆτα κοιμωμένης ἔτι τῆς μητρὸς παρῆν εἰς τὴν ἀγοράν. τοῦ δὲ πλήθους καὶ διὰ τὸ παράδοξον καὶ διὰ τὴν προϋπάρχουσαν εὔνοιαν ἐκπληκτικῶς αὐτὸν ἀποδεξαμένου, καὶ μετὰ ταῦτα προελθόντος εἰς τὸν ἀποδεδειγμένον τόπον καὶ στάντος παρὰ τὸν ἀδελφόν, οὐ μόνον τῷ Ποπλίῳ περιέθεσαν οἱ πολλοὶ τὴν ἀρχήν, ἀλλὰ καὶ τἀδελφῷ δι’ ἐκεῖνον, καὶ παρῆσαν ἐπὶ τὴν οἰκίαν ἀμφότεροι γεγονότες ἀγορανόμοι. τῇ δὲ μητρὶ τοῦ πράγματος ἄφνω προσπεσόντος, περιχαρὴς οὖσα πρὸς τὰς θύρας ἀπήντα καὶ μετὰ παραστάσεως ἠσπάζετο τοὺς νεανίσκους, ὥστε τὸν Πόπλιον ἐκ τοῦ συμβαίνοντος δοκεῖν πᾶσι τοῖς προακηκοόσι τῶν ἐνυπνίων μὴ μόνον κατὰ τὸν ὕπνον, ἔτι δὲ μᾶλλον ὕπαρ καὶ μεθ’ ἡμέραν διαλέγεσθαι τοῖς θεοῖς. ὧν οὐδὲν ἦν ἐνύπνιον, ἀλλ’ ὑπάρχων εὐεργετικὸς καὶ μεγαλόδωρος καὶ προσφιλὴς κατὰ τὴν ἀπάντησιν συνελογίσατο τὴν τοῦ πλήθους πρὸς αὑτὸν εὔνοιαν. λοιπὸν πρός τε τὸν τοῦ δήμου καὶ τὸν τῆς μητρὸς καιρὸν ἁρμοσάμενος εὐστόχως οὐ μόνον καθίκετο τῆς προθέσεως, ἀλλὰ καὶ μετά τινος ἐδόκει θείας ἐπιπνοίας αὐτὸ πράττειν. οἱ γὰρ μὴ δυνάμενοι τοὺς καιροὺς μηδὲ τὰς αἰτίας καὶ διαθέσεις ἑκάστων ἀκριβῶς συνθεωρεῖν, ἢ διὰ φαυλότητα φύσεως ἢ δι’ ἀπειρίαν καὶ ῥᾳθυμίαν, εἰς θεοὺς καὶ τύχας ἀναφέρουσι τὰς αἰτίας τῶν δι’ ἀγχίνοιαν ἐκ λογισμοῦ καὶ προνοίας ἐπιτελουμένων. ταῦτα μὲν οὖν εἰρήσθω μοι χάριν τῶν ἀκουόντων, ἵνα μὴ συγκαταφερόμενοι ψευδῶς τῇ καθωμιλημένῃ δόξῃ περὶ αὐτοῦ παραπέμπωσι τὰ σεμνότατα καὶ κάλλιστα τἀνδρός, λέγω δὲ τὴν ἐπιδεξιότητα καὶ φιλοπονίαν. ἔτι δὲ μᾶλλον ἔσται τοῦτο συμφανὲς ἐπ’ αὐτῶν τῶν πράξεων.", "st": "10.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τότε συνηθροισμένων τῶν δυνάμεων παρεκάλει μὴ καταπεπλῆχθαι τὴν προγεγενημένην περιπέτειαν· οὐ γὰρ ταῖς ἀρεταῖς ἡττῆσθαι Ῥωμαίους ὑπὸ Καρχηδονίων οὐδέποτε, τῇ δὲ προδοσίᾳ τῇ Κελτιβήρων καὶ τῇ προπετείᾳ, διακλεισθέντων τῶν στρατηγῶν ἀπ’ ἀλλήλων διὰ τὸ πιστεῦσαι τῇ συμμαχίᾳ τῶν εἰρημένων. ὧν ἑκάτερα νῦν ἔφη περὶ τοὺς πολεμίους ὑπάρχειν· χωρὶς γὰρ ἀπ’ ἀλλήλων πολὺ διεσπασμένους στρατοπεδεύειν, τοῖς τε συμμάχοις ὑβριστικῶς χρωμένους ἅπαντας ἀπηλλοτριωκέναι καὶ πολεμίους αὑτοῖς παρεσκευακέναι. διὸ καὶ τοὺς μὲν ἤδη διαπέμπεσθαι πρὸς σφᾶς, τοὺς δὲ λοιπούς, ὡς ἂν τάχιστα θαρρήσωσι καὶ διαβάντας ἴδωσι τὸν ποταμόν, ἀσμένως ἥξειν, οὐχ οὕτως εὐνοοῦντας σφίσι, τὸ δὲ πλεῖον ἀμύνεσθαι σπουδάζοντας τὴν Καρχηδονίων εἰς αὐτοὺς ἀσέλγειαν, τὸ δὲ μέγιστον, στασιάζοντας πρὸς ἀλλήλους τοὺς τῶν ὑπεναντίων ἡγεμόνας ἅθρους διαμάχεσθαι πρὸς αὐτοὺς οὐ θελήσειν, κατὰ μέρος δὲ κινδυνεύοντας εὐχειρώτους ὑπάρχειν. διὸ βλέποντας εἰς ταῦτα παρεκάλει περαιοῦσθαι τὸν ποταμὸν εὐθαρσῶς· περὶ δὲ τῶν ἑξῆς ἀνεδέχετο μελήσειν αὑτῷ καὶ τοῖς ἄλλοις ἡγεμόσι. ταῦτα δ’ εἰπὼν τρισχιλίους μὲν ἔχοντα πεζοὺς καὶ πεντακοσίους ἱππεῖς Μάρκον ἀπέλειπε τὸν συνάρχοντα περὶ τὴν διάβασιν ἐφεδρεύσοντα τοῖς ἐντὸς τοῦ ποταμοῦ συμμάχοις· αὐτὸς δὲ τὴν ἄλλην ἐπεραίου δύναμιν, ἄδηλον πᾶσι ποιῶν τὴν αὑτοῦ πρόθεσιν. ἦν γὰρ αὐτῷ κεκριμένον πράττειν ὧν μὲν εἶπε πρὸς τοὺς πολλοὺς μηδέν, προύκειτο δὲ πολιορκεῖν ἐξ ἐφόδου τὴν ἐν Ἰβηρίᾳ Καρχηδόνα προσαγορευομένην. ὃ δὴ καὶ πρῶτον ἄν τις λάβοι καὶ μέγιστον σημεῖον τῆς ὑφ’ ἡμῶν ἄρτι ῥηθείσης διαλήψεως. ἔτος γὰρ ἕβδομον ἔχων πρὸς τοῖς εἴκοσι πρῶτον μὲν ἐπὶ πράξεις αὑτὸν ἔδωκε τελέως παρὰ τοῖς πολλοῖς ἀπηλπισμένας διὰ τὸ μέγεθος τῶν προγεγονότων ἐλαττωμάτων, δεύτερον δοὺς αὑτὸν τὰ μὲν κοινὰ καὶ προφαινόμενα πᾶσι παρέλειπε, τὰ δὲ μήτε παρὰ τοῖς πολεμίοις, ταῦτ’ ἐπενόει καὶ προετίθετο πράττειν. ὧν οὐδὲν ἦν χωρὶς ἐκλογισμῶν τῶν ἀκριβεστάτων.", "st": "10.6"}, {"sp": "N", "t": "ἔτι μὲν γὰρ ἀπὸ τῆς ἀρχῆς ἱστορῶν ἐν τῇ Ῥώμῃ καὶ πυνθανόμενος ἐπιμελῶς τήν τε προδοσίαν τῶν Κελτιβήρων καὶ τὸν διαζευγμὸν τῶν ἰδίων στρατοπέδων, καὶ συλλογιζόμενος ὅτι παρὰ τοῦτο συμβαίνει τοῖς περὶ τὸν πατέρα γενέσθαι τὴν περιπέτειαν, οὐ κατεπέπληκτο τοὺς Καρχηδονίους οὐδ’ ἥττητο τῇ ψυχῇ, καθάπερ οἱ πολλοί. μετὰ δὲ ταῦτα τοὺς ἐντὸς Ἴβηρος ποταμοῦ συμμάχους ἀκούων μένειν ἐν τῇ πρὸς αὐτοὺς φιλίᾳ, τοὺς δὲ τῶν Καρχηδονίων ἡγεμόνας στασιάζειν μὲν πρὸς σφᾶς, ὑβρίζειν δὲ τοὺς ὑποταττομένους, εὐθαρσῶς διέκειτο πρὸς τὴν ἔξοδον, οὐ τῇ τύχῃ πιστεύων, ἀλλὰ τοῖς συλλογισμοῖς. παραγενόμενός γε μὴν εἰς τὴν Ἰβηρίαν, πάντας ἀνακινῶν καὶ παρ’ ἑκάστου πυνθανόμενος τὰ περὶ τοὺς ἐναντίους, ηὕρισκε τὰς μὲν δυνάμεις τῶν Καρχηδονίων εἰς τρία μέρη διῃρημένας· ὧν Μάγωνα μὲν ἐπυνθάνετο διατρίβειν ἐντὸς Ἡρακλείων στηλῶν ἐν τοῖς Κονίοις προσαγορευομένοις, Ἀσδρούβαν δὲ τὸν Γέσκωνος περὶ Τάγου ποταμοῦ στόμα κατὰ τὴν Λυσιτανήν, τὸν δ’ ἕτερον Ἀσδρούβαν πολιορκεῖν τινα πόλιν ἐν τοῖς Καρπητανοῖς, οὐδένα δὲ τῶν προειρημένων ἐλάττω δέχ’ ἡμερῶν ὁδὸν ἀπέχειν τῆς Καινῆς πόλεως. νομίζων οὖν, ἐὰν μὲν εἰς μάχην συνιέναι κρίνῃ τοῖς πολεμίοις, τὸ μὲν πρὸς πάντας ἅμα κινδυνεύειν ἐπισφαλὲς εἶναι τελέως καὶ διὰ τὸ προηττῆσθαι τοὺς πρὸ αὐτοῦ καὶ διὰ τὸ πολλαπλασίους εἶναι τοὺς ὑπεναντίους, ἐὰν δὲ πρὸς ἕνα συμβαλεῖν σπεύδων, κἄπειτα τούτου φυγομαχήσαντος, ἐπιγενομένων δὲ τῶν ἄλλων δυνάμεων, συγκλεισθῇ που, κατάφοβος ἦν μὴ ταῖς αὐταῖς Γναΐῳ τῷ θείῳ καὶ Ποπλίῳ τῷ πατρὶ περιπέσῃ συμφοραῖς.", "st": "10.7"}, {"sp": "N", "t": "διὸ τοῦτο μὲν τὸ μέρος ἀπεδοκίμασε, πυνθανόμενος δὲ τὴν προειρημένην Καρχηδόνα μεγίστας μὲν χρείας παρέχεσθαι τοῖς ὑπεναντίοις, μέγιστα δὲ βλάπτειν καὶ κατὰ τὸν ἐνεστῶτα πόλεμον αὐτόν, ἐξητάκει τὰ κατὰ μέρος ὑπὲρ αὐτῆς ἐν τῇ παραχειμασίᾳ διὰ τῶν εἰδότων. ἀκούων δὲ πρῶτον μὲν ὅτι λιμένας ἔχει στόλῳ καὶ ναυτικαῖς δυνάμεσι μόνη σχεδὸν τῶν κατὰ τὴν Ἰβηρίαν, ἅμα δὲ καὶ διότι πρὸς τὸν ἀπὸ τῆς Λιβύης πλοῦν καὶ πελάγιον δίαρμα λίαν εὐφυῶς κεῖται τοῖς Καρχηδονίοις, μετὰ δὲ ταῦτα διότι καὶ τὸ τῶν χρημάτων πλῆθος καὶ τὰς ἀποσκευὰς τῶν στρατοπέδων ἁπάσας ἐν ταύτῃ τῇ πόλει συνέβαινε τοῖς Καρχηδονίοις ὑπάρχειν, ἔτι δὲ τοὺς ὁμήρους τοὺς ἐξ ὅλης τῆς Ἰβηρίας, τὸ δὲ μέγιστον, ὅτι μάχιμοι μὲν ἄνδρες εἴησαν εἰς χιλίους οἱ τὴν ἄκραν τηροῦντες διὰ τὸ μηδένα μηδέποτ’ ἂν ὑπολαμβάνειν ὅτι κρατούντων Καρχηδονίων σχεδὸν ἁπάσης Ἰβηρίας ἐπινοήσει τις τὸ παράπαν πολιορκῆσαι ταύτην τὴν πόλιν, τὸ δ’ ἄλλο πλῆθος ὅτι πολὺ μὲν εἴη διαφερόντως ἐν αὐτῇ, πᾶν δὲ δημιουργικὸν καὶ βάναυσον καὶ θαλαττουργὸν καὶ πλεῖστον ἀπέχον πολεμικῆς ἐμπειρίας, ὃ κατὰ τῆς πόλεως ὑπελάμβανεν εἶναι, παραδόξου γενομένης ἐπιφανείας. καὶ μὴν οὐδὲ τὴν θέσιν τῆς Καρχηδόνος οὐδὲ τὴν κατασκευὴν οὐδὲ τὴν τῆς περιεχούσης αὐτὴν λίμνης διάθεσιν ἠγνόει, διὰ δέ τινων ἁλιέων τῶν ἐνειργασμένων τοῖς τόποις ἐξητάκει διότι καθόλου μέν ἐστι τεναγώδης ἡ λίμνη καὶ βατὴ κατὰ τὸ πλεῖστον, ὡς δ’ ἐπὶ τὸ πολὺ καὶ γίνεταί τις αὐτῆς ἀποχώρησις καθ’ ἡμέραν ἐπὶ δείλην ὀψίαν. ἐξ ὧν συλλογισάμενος ὅτι καθικόμενος μὲν τῆς ἐπιβολῆς οὐ μόνον βλάψει τοὺς ὑπεναντίους, ἀλλὰ καὶ τοῖς σφετέροις πράγμασι μεγάλην ἐπίδοσιν παρασκευάσει, διαπεσὼν δὲ τῆς προθέσεως, ὅτι δύναται σῴζειν τοὺς ὑποταττομένους διὰ τὸ θαλαττοκρατεῖν, ἐὰν ἅπαξ ἀσφαλίσηται τὴν στρατοπεδείαν — τοῦτο δ’ ἦν εὐχερὲς διὰ τὸ μακρὰν ἀπεσπάσθαι τὰς τῶν ὑπεναντίων δυνάμεις — οὕτως ἀφέμενος τῶν ἄλλων περὶ ταύτην ἐγίνετο τὴν παρασκευὴν ἐν τῇ παραχειμασίᾳ.", "st": "10.8"}, {"sp": "N", "t": "καὶ ταύτην ἔχων τὴν ἐπιβολὴν καὶ τὴν ἡλικίαν, ἣν ἀρτίως εἶπα, πάντας ἀπεκρύψατο χωρὶς Γαΐου Λαιλίου, μέχρι πάλιν αὐτὸς ἔκρινε φανερὸν ποιεῖν. τούτοις δὲ τοῖς ἐκλογισμοῖς ὁμολογοῦντες οἱ συγγραφεῖς, ὅταν ἐπὶ τὸ τέλος ἔλθωσι τῆς πράξεως, οὐκ οἶδ’ ὅπως οὐκ εἰς τὸν ἄνδρα καὶ τὴν τούτου πρόνοιαν, εἰς δὲ τοὺς θεοὺς καὶ τὴν τύχην ἀναφέρουσι τὸ γεγονὸς κατόρθωμα, καὶ ταῦτα χωρὶς τῶν εἰκότων καὶ τῆς τῶν συμβεβιωκότων μαρτυρίας, καὶ διὰ τῆς ἐπιστολῆς τῆς πρὸς Φίλιππον αὐτοῦ τοῦ Ποπλίου σαφῶς ἐκτεθεικότος ὅτι τούτοις τοῖς ἐκλογισμοῖς χρησάμενος, οἷς ἡμεῖς ἀνώτερον ἐξελογισάμεθα, καθόλου τε τοῖς ἐν Ἰβηρίᾳ πράγμασιν ἐπιβάλοιτο καὶ κατὰ μέρος τῇ τῆς Καρχηδόνος πολιορκίᾳ. πλὴν τότε γε τῷ μὲν ἐπὶ τοῦ στόλου Γαΐῳ Λαιλίῳ δι’ ἀπορρήτων ἐντειλάμενος παρήγγειλε πλεῖν ἐπὶ τὴν προειρημένην πόλιν — μόνος γὰρ οὗτος αὐτῷ συνῄδει τὴν ἐπιβολήν, καθάπερ ἀνώτερον εἶπον — αὐτὸς δὲ τὰς πεζικὰς δυνάμεις ἀναλαβὼν ἐποιεῖτο τὴν πορείαν μετὰ σπουδῆς. εἶχε δὲ τὸ μὲν τῶν πεζῶν πλῆθος εἰς δισμυρίους καὶ πεντακισχιλίους, ἱππεῖς δ’ εἰς δισχιλίους καὶ πεντακοσίους. ἀφικόμενος δ’ ἑβδομαῖος κατεστρατοπέδευσε κατὰ τὸ πρὸς ἄρκτους μέρος τῆς πόλεως, καὶ περιεβάλετο κατὰ μὲν τὴν ἐκτὸς ἐπιφάνειαν τῆς στρατοπεδείας τάφρον καὶ χάρακα διπλοῦν ἐκ θαλάττης εἰς θάλατταν, κατὰ δὲ τὴν πρὸς τὴν πόλιν ἁπλῶς οὐδέν. αὐτὴ γὰρ ἡ τοῦ τόπου φύσις ἱκανὴν ἀσφάλειαν αὐτῷ παρεσκεύαζε. μέλλοντες δὲ καὶ τὴν πολιορκίαν καὶ τὴν ἅλωσιν τῆς πόλεως δηλοῦν, ἀναγκαῖον ἡγούμεθ’ εἶναι τὸ καὶ τοὺς παρακειμένους τόπους καὶ τὴν θέσιν αὐτῆς ἐπὶ ποσὸν ὑποδεῖξαι τοῖς ἀκούουσι.", "st": "10.9"}, {"sp": "N", "t": "κεῖται μὲν οὖν τῆς Ἰβηρίας κατὰ μέσην τὴν παραλίαν ἐν κόλπῳ νεύοντι πρὸς ἄνεμον λίβα· οὗ τὸ μὲν βάθος ἐστὶν ὡς εἴκοσι σταδίων, τὸ δὲ πλάτος ἐν ταῖς ἀρχαῖς ὡς δέκα· λαμβάνει δὲ διάθεσιν λιμένος ὁ πᾶς κόλπος διὰ τοιαύτην αἰτίαν. νῆσος ἐπὶ τοῦ στόματος αὐτοῦ κεῖται βραχὺν ἐξ ἑκατέρου τοῦ μέρους εἴσπλουν εἰς αὐτὸν ἀπολείπουσα. ταύτης ἀποδεχομένης τὸ πελάγιον κῦμα συμβαίνει τὸν κόλπον ὅλον εὐδίαν ἴσχειν, πλὴν ἐφ’ ὅσον οἱ λίβες καθ’ ἑκάτερον τὸν εἴσπλουν παρεισπίπτοντες κλύδωνας ἀποτελοῦσι. τῶν γε μὴν ἄλλων πνευμάτων ἀκλυδώνιστος ὢν τυγχάνει διὰ τὴν περιέχουσαν αὐτὸν ἤπειρον. ἐν δὲ τῷ μυχῷ τοῦ κόλπου πρόκειται χερρονησίζον ὄρος, ἐφ’ οὗ κεῖσθαι συμβαίνει τὴν πόλιν, περιεχομένην θαλάττῃ μὲν ἀπ’ ἀνατολῶν καὶ μεσημβρίας, ἀπὸ δὲ τῶν δύσεων λίμνῃ προσεπιλαμβανούσῃ καὶ τοῦ πρὸς ἄρκτον μέρους, ὥστε τὸν λοιπὸν τόπον μέχρι τῆς ἐπὶ θάτερα θαλάττης, ὃς καὶ συνάπτει τὴν πόλιν πρὸς τὴν ἤπειρον, μὴ πλέον ὑπάρχειν ἢ δυεῖν σταδίων. ἡ δὲ πόλις αὐτὴ μεσόκοιλός ἐστι· κατὰ δὲ τὴν ἀπὸ μεσημβρίας πλευρὰν ἐπίπεδον ἔχει τὴν ἀπὸ θαλάττης πρόσοδον· τὰ δὲ λοιπὰ περιέχεται λόφοις, δυσὶ μὲν ὀρεινοῖς καὶ τραχέσιν, ἄλλοις δὲ τρισὶ πολὺ μὲν χθαμαλωτέροις, σπιλώδεσι δὲ καὶ δυσβάτοις· ὧν ὁ μὲν μέγιστος ἀπὸ τῆς ἀνατολῆς αὐτῇ παράκειται, προτείνων εἰς θάλατταν, ἐφ’ οὗ καθίδρυται νεὼς Ἀσκληπιοῦ. τούτῳ δ’ ὁ ἀπὸ τῆς δύσεως ἀντίκειται, παραπλησίαν θέσιν ἔχων, ἐφ’ οὗ καὶ βασίλεια κατεσκεύασται πολυτελῶς, ἅ φασιν Ἀσδρούβαν ποιῆσαι, μοναρχικῆς ὀρεγόμενον ἐξουσίας. αἱ δὲ λοιπαὶ τρεῖς τῶν ἐλαττόνων βουνῶν ὑπεροχαὶ τὸ πρὸς ἄρκτον αὐτῆς μέρος περιέχουσι. καλεῖται δὲ τῶν τριῶν ὁ μὲν πρὸς ἀνατολὰς νεύων Ἡφαίστου, τούτῳ δ’ ὁ συνεχὴς Ἀλήτου — δοκεῖ δ’ οὗτος εὑρετὴς γενόμενος τῶν ἀργυρείων μετάλλων ἰσοθέων τετευχέναι τιμῶν — ὁ δὲ τρίτος προσαγορεύεται Κρόνου. συμβαίνει δὲ τὴν λίμνην τῇ παρακειμένῃ θαλάττῃ σύρρουν γεγονέναι χειροποιήτως χάριν τῶν θαλαττουργῶν. κατὰ δὲ τὴν τοῦ διείργοντος αὐτὰς χείλους διακοπὴν γέφυρα κατεσκεύασται πρὸς τὸ καὶ τὰ ὑποζύγια καὶ τὰς ἁμάξας ταύτῃ ποιεῖσθαι τὴν παρακομιδὴν τῶν ἐκ τῆς χώρας ἀναγκαίων.", "st": "10.10"}, {"sp": "N", "t": "τοιαύτης δ’ ὑπαρχούσης τῆς διαθέσεως τῶν τόπων, ἀσφαλίζεσθαι συνέβαινε τοῖς Ῥωμαίοις τὴν στρατοπεδείαν κατὰ τὴν ἐντὸς ἐπιφάνειαν ἀκατασκεύως ὑπό τε τῆς λίμνης καὶ τῆς ἐπὶ θάτερα θαλάττης. τὸ δὲ μεταξὺ τούτων διάστημα τὸ συνάπτον τὴν πόλιν πρὸς τὴν ἤπειρον ἀχαράκωτον εἴασε, κατὰ μέσην ὑπάρχον τὴν αὑτοῦ στρατοπεδείαν, εἴτε καὶ καταπλήξεως χάριν εἴτε καὶ πρὸς τὴν ἐπιβολὴν ἁρμοζόμενος, ὅπως ἀνεμποδίστους ἔχῃ καὶ τὰς ἐξαγωγὰς καὶ τὰς ἀναχωρήσεις εἰς τὴν παρεμβολήν. ὁ δὲ περίβολος τῆς πόλεως οὐ πλεῖον εἴκοσι σταδίων ὑπῆρχε τὸ πρότερον — καίτοι γ’ οὐκ ἀγνοῶ διότι πολλοῖς εἴρηται τετταράκοντα· τὸ δ’ ἐστὶ ψεῦδος. οὐ γὰρ ἐξ ἀκοῆς ἡμεῖς, ἀλλ’ αὐτόπται γεγονότες μετ’ ἐπιστάσεως ἀποφαινόμεθα — νῦν δὲ καὶ μᾶλλον ἔτι συνῄρηται. πλὴν ὅ γε Πόπλιος, συνάψαντος καὶ τοῦ στόλου πρὸς τὸν δέοντα καιρόν, ἐπεβάλετο συναθροίσας τὰ πλήθη παρακαλεῖν, οὐχ ἑτέροις τισὶ χρώμενος ἀπολογισμοῖς, ἀλλ’ οἷς ἐτύγχανε πεπεικὼς αὑτόν, ὑπὲρ ὧν ἡμεῖς τὸν κατὰ μέρος ἄρτι πεποιήμεθα λόγον. ἀποδείξας δὲ δυνατὴν οὖσαν τὴν ἐπιβολήν, καὶ συγκεφαλαιωσάμενος τὴν ἐκ τοῦ κατορθώματος ἐλάττωσιν τῶν ὑπεναντίων, αὔξησιν δὲ τῶν σφετέρων πραγμάτων, λοιπὸν χρυσοῦς στεφάνους ἐπηγγείλατο τοῖς πρώτοις ἐπὶ τὸ τεῖχος ἀναβᾶσι καὶ τὰς εἰθισμένας δωρεὰς τοῖς ἐπιφανῶς ἀνδραγαθήσασι· τὸ δὲ τελευταῖον ἐξ ἀρχῆς ἔφη τὴν ἐπιβολὴν αὐτῷ ταύτην ὑποδεδειχέναι τὸν Ποσειδῶνα παραστάντα κατὰ τὸν ὕπνον, καὶ φάναι συνεργήσειν ἐπιφανῶς κατ’ αὐτὸν τὸν τῆς πράξεως καιρὸν οὕτως ὥστε παντὶ τῷ στρατοπέδῳ τὴν ἐξ αὐτοῦ χρείαν ἐναργῆ γενέσθαι. τῶν δὲ κατὰ τὴν παράκλησιν λόγων ἅμα μὲν ἀπολογισμοῖς ἀκριβέσι μεμιγμένων, ἅμα δ’ ἐπαγγελίαις χρυσῶν στεφάνων, ἐπὶ δὲ πᾶσι τούτοις θεοῦ προνοίᾳ, τελέως μεγάλην ὁρμὴν καὶ προθυμίαν παρίστασθαι συνέβαινε τοῖς νεανίσκοις.", "st": "10.11"}, {"sp": "N", "t": "τῇ δ’ ἐπαύριον κατὰ μὲν τοὺς ἐκ τῆς θαλάττης τόπους περιστήσας ναῦς παντοδαποῖς βέλεσιν ἐξηρτυμένας καὶ δοὺς τὴν ἐπιτροπὴν Γαΐῳ, κατὰ δὲ γῆν τοὺς εὐρωστοτάτους τῶν ἀνδρῶν εἰς δισχιλίους ὁμόσε τοῖς κλιμακοφόροις ἐπιστήσας, ἐνήρχετο τῆς πολιορκίας κατὰ τρίτην ὥραν. ὁ δὲ Μάγων ὁ τεταγμένος ἐπὶ τῆς πόλεως τὸ μὲν τῶν χιλίων σύνταγμα διελὼν τοὺς μὲν ἡμίσεις ἐπὶ τῆς ἄκρας ἀπέλιπε, τοὺς δ’ ἄλλους ἐπὶ τοῦ πρὸς ἀνατολὰς λόφου παρενέβαλε· τῶν δὲ λοιπῶν τοὺς εὐρωστοτάτους περὶ δισχιλίους κατεσκευακὼς τοῖς ὑπάρχουσι κατὰ τὴν πόλιν ὅπλοις ἐπέστησε κατὰ τὴν πύλην τὴν φέρουσαν ἐπὶ τὸν ἰσθμὸν καὶ τὴν τῶν πολεμίων στρατοπεδείαν· τοῖς δὲ λοιποῖς παρήγγειλε βοηθεῖν κατὰ δύναμιν πρὸς πάντα τὰ μέρη τοῦ τείχους. ἅμα δὲ τῷ τὸν Πόπλιον ταῖς σάλπιγξι διασημῆναι [καὶ] τὸν καιρὸν τῆς προσβολῆς, ἐξαφίησι τοὺς καθωπλισμένους ὁ Μάγων διὰ τῆς πύλης, πεπεισμένος ὅτι καταπλήξεται τοὺς ὑπεναντίους καὶ τὸ παράπαν ἀφελεῖται τὴν ἐπιβολὴν αὐτῶν. προσπεσόντων δὲ τούτων ἐρρωμένως τοῖς ἐκ τοῦ στρατοπέδου κατὰ τὸν ἰσθμὸν παρατεταγμένοις ἐγίνετο μάχη λαμπρὰ καὶ παρακελευσμὸς ἐξ ἀμφοῖν ἐναγώνιος, τῶν μὲν ἐκ τοῦ στρατοπέδου, τῶν δ’ ἐκ τῆς πόλεως τοῖς ἰδίοις ἑκατέρων ἐπιβοώντων. τῆς δὲ διὰ τῶν βοηθούντων ἐπικουρίας οὐχ ὁμοίας ὑπαρχούσης διὰ τὸ τοῖς μὲν Καρχηδονίοις διὰ μιᾶς πύλης καὶ σχεδὸν ἀπὸ δυεῖν σταδίοιν γίνεσθαι τὴν παρουσίαν, τοῖς δὲ Ῥωμαίοις ἐκ χειρὸς καὶ κατὰ πολὺν τόπον, ἄνισος ἦν ἡ μάχη παρὰ ταύτην τὴν αἰτίαν. ὁ γὰρ Πόπλιος ἑκὼν ἐπέστησε τοὺς αὑτοῦ παρ’ αὐτὴν τὴν στρατοπεδείαν χάριν τοῦ προκαλέσασθαι τοὺς πολεμίους πορρωτάτω, σαφῶς γινώσκων, ἐὰν διαφθείρῃ τούτους, ὄντας οἷον εἰ στόμα τοῦ κατὰ τὴν πόλιν πλήθους, ὅτι διατραπήσεται τὰ ὅλα καὶ τὴν πύλην οὐκέτι τῶν ἔνδον οὐδεὶς ἐξιέναι θαρρήσει. οὐ μὴν ἀλλ’ ἕως μέν τινος ἐφάμιλλον συνέβαινε γίνεσθαι τὴν μάχην, ὡς ἐξ ἀμφοῖν κατ’ ἐκλογὴν τῶν ἀρίστων ἀνδρῶν προκεκριμένων· τέλος δ’ ἐξωθούμενοι τῷ βάρει διὰ τοὺς ἐκ τῆς παρεμβολῆς προσγινομένους ἐτράπησαν οἱ παρὰ τῶν Καρχηδονίων, καὶ πολλοὶ μὲν αὐτῶν ἐν τῷ τῆς μάχης καιρῷ διεφθάρησαν καὶ κατὰ τὴν ἀποχώρησιν, οἱ δὲ πλείους ἐν τῷ παραπίπτειν εἰς τὴν πύλην ὑφ’ αὑτῶν ἠλοήθησαν. οὗ συμβαίνοντος ὁ κατὰ τὴν πόλιν ὄχλος οὕτως ἐπτοήθη πᾶς ὥστε καὶ τοὺς ἀπὸ τῶν τειχῶν φεύγειν. παρ’ ὀλίγον μὲν οὖν ἦλθον οἱ Ῥωμαῖοι τοῦ συνεισπεσεῖν τότε μετὰ τῶν φευγόντων· οὐ μὴν ἀλλὰ τάς γε κλίμακας τῷ τείχει μετ’ ἀσφαλείας προσήρεισαν.", "st": "10.12"}, {"sp": "N", "t": "ὁ δὲ Πόπλιος ἐδίδου μὲν αὑτὸν εἰς τὸν κίνδυνον, ἐποίει δὲ τοῦτο κατὰ δύναμιν ἀσφαλῶς· εἶχε γὰρ μεθ’ αὑτοῦ τρεῖς ἄνδρας θυρεοφοροῦντας, οἳ παρατιθέντες τοὺς θυρεοὺς καὶ τὴν ἀπὸ τοῦ τείχους ἐπιφάνειαν σκεπάζοντες ἀσφάλειαν αὐτῷ παρεσκεύαζον. διὸ παρὰ τὰ πλάγια καὶ τοὺς ὑπερδεξίους τόπους ἐπιπαριὼν μεγάλα συνεβάλλετο πρὸς τὴν χρείαν· ἅμα μὲν γὰρ ἑώρα τὸ γινόμενον, ἅμα δ’ αὐτὸς ὑπὸ πάντων ὁρώμενος ἐνειργάζετο προθυμίαν τοῖς ἀγωνιζομένοις. ἐξ οὗ συνέβαινε μηδὲν ἐλλιπὲς γίνεσθαι τῶν πρὸς τὸν κίνδυνον, ἀλλ’ ὁπότε τιν’ αὐτῷ πρὸς τὸ προκείμενον ὁ καιρὸς ὑποδείξειε, πᾶν ἐκ χειρὸς ἀεὶ συνηργεῖτο πρὸς τὸ δέον. ὁρμησάντων δὲ ταῖς κλίμαξι περὶ τὴν ἀνάβασιν τῶν πρώτων τεθαρρηκότως, οὐχ οὕτως τὸ πλῆθος τῶν ἀμυνομένων ἐπικίνδυνον ἐποίει τὴν προσβολὴν ὡς τὸ μέγεθος τῶν τειχῶν. διὸ καὶ μᾶλλον ἐπερρώσθησαν οἱ κατὰ τὰ τείχη, θεωροῦντες τὴν δυσχρηστίαν τῶν συμβαινόντων. ἔνιαι μὲν γὰρ συνετρίβοντο τῶν κλιμάκων, πολλῶν ἅμα διὰ τὸ μέγεθος συνεπιβαινόντων· ἐφ’ αἷς δ’ οἱ πρῶτοι προσβαίνοντες ἐσκοτοῦντο διὰ τὴν εἰς ὕψος ἀνάτασιν καὶ βραχείας προσδεόμενοι τῆς ἐκ τῶν ἀμυνομένων ἀντιπράξεως ἐρρίπτουν σφᾶς αὐτοὺς ἀπὸ τῶν κλιμάκων. ὅτε δὲ καὶ δοκοὺς ἤ τι τοιοῦτον ἐγχειρήσαιεν ἐπιρρίπτειν ἀπὸ τῶν ἐπάλξεων, ὁμοῦ πάντες ἀπεσύροντο καὶ κατεφέροντο πρὸς τὴν γῆν. οὐ μὴν ἀλλὰ τοιούτων ἀπαντωμένων οὐδὲν ἱκανὸν ἦν πρὸς τὸ κωλύειν τὴν ἐπιφορὰν καὶ τὴν ὁρμὴν τῶν Ῥωμαίων, ἀλλ’ ἔτι καταφερομένων τῶν πρώτων ἐπέβαινον οἱ συνεχεῖς ἐπὶ τὴν ἐκλείπουσαν ἀεὶ χώραν. ἤδη δὲ τῆς ἡμέρας προβαινούσης, καὶ τῶν στρατιωτῶν τετρυμμένων ὑπὸ τῆς κακοπαθείας, ἀνεκαλέσατο ταῖς σάλπιγξιν ὁ στρατηγὸς τοὺς προσβάλλοντας.", "st": "10.13"}, {"sp": "N", "t": "οἱ μὲν οὖν ἔνδον περιχαρεῖς ἦσαν ὡς ἀποτετριμμένοι τὸν κίνδυνον· ὁ δὲ Πόπλιος, προσδοκῶν ἤδη τὸν τῆς ἀμπώτεως καιρόν, κατὰ μὲν τὴν λίμνην ἡτοίμασε πεντακοσίους ἄνδρας μετὰ κλιμάκων, κατὰ δὲ τὴν πύλην καὶ τὸν ἰσθμὸν νεαλεῖς ποιήσας τοὺς στρατιώτας καὶ παρακαλέσας προσανέδωκε κλίμακας πλείους τῶν πρότερον, ὥστε συνεχῶς πλῆρες γενέσθαι τὸ τεῖχος τῶν προσβαινόντων. ἅμα δὲ τῷ σημῆναι τὸ πολεμικὸν καὶ προσθέντας τῷ τείχει τὰς κλίμακας προσβαίνειν κατὰ πάντα τὰ μέρη τεθαρρηκότως μεγάλην συνέβαινε ταραχὴν καὶ διατροπὴν γίνεσθαι τῶν ἔνδον. νομίζοντες γὰρ ἀπολελύσθαι τῆς περιστάσεως, αὖθις ἀρχὴν ἑώρων λαμβάνοντα τὸν κίνδυνον ἐξ ἄλλης ὁρμῆς· ἅμα δὲ καὶ τῶν βελῶν αὐτοὺς ἤδη λειπόντων, καὶ τοῦ πλήθους τῶν ἀπολωλότων εἰς ἀθυμίαν ἄγοντος, δυσχερῶς μὲν ἔφερον τὸ γινόμενον, οὐ μὴν ἀλλ’ ἠμύνοντο δυνατῶς. κατὰ δὲ τὴν ἀκμὴν τοῦ διὰ τῶν κλιμάκων ἀγῶνος ἤρχετο τὰ κατὰ τὴν ἄμπωτιν, καὶ τὰ μὲν ἄκρα τῆς λίμνης ἀπέλειπε τὸ ὕδωρ κατὰ βραχύ, διὰ δὲ τοῦ στόματος ὁ ῥοῦς εἰς τὴν συνεχῆ θάλατταν ἅθρους ἐφέρετο καὶ πολύς, ὥστε τοῖς ἀπρονοήτως θεωμένοις ἄπιστον φαίνεσθαι τὸ γινόμενον. ὁ δὲ Πόπλιος ἔχων ἑτοίμους τοὺς καθηγεμόνας ἐμβαίνειν παρεκελεύετο καὶ θαρρεῖν τοὺς πρὸς τὴν χρείαν ταύτην ἡτοιμασμένους· καὶ γὰρ ἦν εὖ πεφυκώς, εἰ καὶ πρὸς ἄλλο τι, πρὸς τὸ θάρσος ἐμβαλεῖν καὶ συμπαθεῖς ποιῆσαι τοὺς παρακαλουμένους. τότε δὴ πειθαρχησάντων αὐτῶν καὶ διὰ τοῦ τέλματος ἁμιλλωμένων, ἅπαν τὸ στρατόπεδον ὑπέλαβε μετά τινος θεοῦ προνοίας γίνεσθαι τὸ συμβαῖνον. ἐξ οὗ καὶ μνησθέντες τῶν κατὰ τὸν Ποσειδῶ καὶ τῆς τοῦ Ποπλίου κατὰ τὴν παράκλησιν ἐπαγγελίας, ἐπὶ τοσοῦτο ταῖς ψυχαῖς παρωρμήθησαν ὡς συμφράξαντες καὶ βιασάμενοι πρὸς τὴν πύλην ἔξωθεν ἐπεχείρουν διακόπτειν τοῖς πελέκεσι καὶ ταῖς ἀξίναις τὰς θύρας. οἱ δὲ διὰ τῶν τελμάτων ἐγγίσαντες τῷ τείχει, καὶ καταλαβόντες ἐρήμους τὰς ἐπάλξεις, οὐ μόνον προσέθεσαν ἀσφαλῶς τὰς κλίμακας, ἀλλὰ καὶ κατέσχον ἀναβάντες ἀμαχητὶ τὸ τεῖχος, ἅτε τῶν ἔνδον περισπωμένων μὲν περὶ τοὺς ἄλλους τόπους, καὶ μάλιστα τοὺς κατὰ τὸν ἰσθμὸν καὶ τὴν ταύτῃ πύλην, οὐδέποτε δ’ ἂν ἐλπισάντων ἐγγίσαι τῷ τείχει τοὺς πολεμίους κατὰ τὸν τῆς λίμνης τόπον, τὸ δὲ πλεῖστον, ὑπὸ τῆς ἀτάκτου κραυγῆς καὶ τῆς συμμίκτου πολυοχλίας οὐ δυναμένων οὔτ’ ἀκούειν οὔτε συνορᾶν τῶν δεόντων οὐδέν.", "st": "10.14"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι κρατήσαντες τοῦ τείχους τὸ μὲν πρῶτον ἐπεπορεύοντο κατὰ τὴν ἐφοδείαν ἀποσύροντες τοὺς πολεμίους, μεγάλα συμβαλλομένης αὐτοῖς τῆς ὁπλίσεως πρὸς τοῦτο τὸ γένος τῆς χρείας· ἐπεὶ δ’ ἀφίκοντο πρὸς τὴν πύλην, οἱ μὲν καταβάντες διέκοπτον τοὺς μοχλούς, οἱ δ’ ἔξωθεν εἰσέπιπτον, οἱ δὲ διὰ τῶν κλιμάκων βιαζόμενοι κατὰ τὸν ἰσθμόν, ἤδη κρατοῦντες τῶν ἀμυνομένων, ἐπέβαινον ἐπὶ τὰς ἐπάλξεις. καὶ τέλος τὰ μὲν τείχη τούτῳ τῷ τρόπῳ κατείληπτο, τὸν δὲ λόφον οἱ διὰ τῆς πύλης εἰσπορευόμενοι κατελάμβανον τὸν πρὸς τὰς ἀνατολάς, τρεψάμενοι τοὺς φυλάττοντας. ὁ δὲ Πόπλιος ἐπεὶ τοὺς εἰσεληλυθότας ἀξιόχρεως ὑπελάμβανεν εἶναι, τοὺς μὲν πλείστους ἐφῆκε κατὰ τὸ παρ’ αὐτοῖς ἔθος ἐπὶ τοὺς ἐν τῇ πόλει, παραγγείλας κτείνειν τὸν παρατυχόντα καὶ μηδενὸς φείδεσθαι, μηδὲ πρὸς τὰς ὠφελείας ὁρμᾶν, μέχρις ἂν ἀποδοθῇ τὸ σύνθημα. ποιεῖν δέ μοι δοκοῦσι τοῦτο καταπλήξεως χάριν· διὸ καὶ πολλάκις ἰδεῖν ἔστιν ἐν ταῖς τῶν Ῥωμαίων καταλήψεσι τῶν πόλεων οὐ μόνον τοὺς ἀνθρώπους πεφονευμένους, ἀλλὰ καὶ τοὺς κύνας δεδιχοτομημένους καὶ τῶν ἄλλων ζῴων μέλη παρακεκομμένα. τότε δὲ καὶ τελέως πολὺ τὸ τοιοῦτον ἦν διὰ τὸ πλῆθος τῶν κατειλημμένων. αὐτὸς δὲ περὶ χιλίους ἔχων ὥρμησε πρὸς τὴν ἄκραν. ἐγγίσαντος δ’ αὐτοῦ τὸ μὲν πρῶτον ἐπεβάλλετο Μάγων ἀμύνεσθαι, μετὰ δὲ ταῦτα συννοήσας βεβαίως ἤδη κατειλημμένην τὴν πόλιν διεπέμψατο περὶ τῆς ἀσφαλείας τῆς αὑτοῦ, καὶ παρέδωκε τὴν ἄκραν. οὗ γενομένου, καὶ τοῦ συνθήματος ἀποδοθέντος, τοῦ μὲν φονεύειν ἀπέστησαν, ὥρμησαν δὲ πρὸς τὰς ἁρπαγάς. ἐπιγενομένης δὲ τῆς νυκτὸς οἱ μὲν ἐπὶ τῆς παρεμβολῆς ἔμενον, οἷς ἦν οὕτω διατεταγμένον· μετὰ δὲ τῶν χιλίων ὁ στρατηγὸς ἐπὶ τῆς ἄκρας ηὐλίσθη, τοὺς δὲ λοιποὺς διὰ τῶν χιλιάρχων ἐκ τῶν οἰκιῶν ἐκκαλεσάμενος ἐπέταξε συναθροίσαντας εἰς τὴν ἀγορὰν τὰ διηρπασμένα κατὰ σημαίας ἐπὶ τούτων κοιτάζεσθαι. τοὺς δὲ γροσφομάχους ἐκ τῆς παρεμβολῆς καλέσας ἐπὶ τὸν λόφον ἐπέστησε τὸν ἀπὸ τῶν ἀνατολῶν. καὶ τῆς μὲν κατὰ τὴν Ἰβηρίαν Καρχηδόνος τοῦτον τὸν τρόπον ἐγένοντο κύριοι Ῥωμαῖοι·", "st": "10.15"}, {"sp": "N", "t": "εἰς δὲ τὴν ἐπαύριον ἁθροισθείσης εἰς τὴν ἀγορὰν τῆς τε τῶν στρατευομένων παρὰ τοῖς Καρχηδονίοις ἀποσκευῆς καὶ τῆς τῶν πολιτικῶν καὶ τῶν ἐργαστικῶν κατασκευῆς, ταῦτα μὲν ἐμέριζον οἱ χιλίαρχοι τοῖς ἰδίοις στρατοπέδοις κατὰ τὸ παρ’ αὑτοῖς ἔθος. ἔστι δὲ παρὰ Ῥωμαίοις τοιαύτη τις ἡ περὶ τὰς τῶν πόλεων καταλήψεις οἰκονομία. ποτὲ μὲν γὰρ ἑκάστης σημαίας πρὸς τὴν πρᾶξιν ἀπομερίζονταί τινες τῶν ἀνδρῶν κατὰ τὸ μέγεθος τῆς πόλεως, ποτὲ δὲ κατὰ σημαίας μερίζουσιν αὐτούς. οὐδέποτε δὲ πλείους ἀποτάττονται πρὸς τοῦτο τῶν ἡμίσεων· οἱ δὲ λοιποὶ μένοντες κατὰ τὰς τάξεις ἐφεδρεύουσι, ποτὲ μὲν ἐκτὸς τῆς πόλεως, ποτὲ δὲ πάλιν ἐντός, ἀεὶ πρὸς τὸ δεικνύειν. τῆς δὲ δυνάμεως διῃρημένης αὐτοῖς κατὰ μὲν τὸ πλεῖον εἰς δύο στρατόπεδα Ῥωμαϊκὰ καὶ δύο τῶν συμμάχων, τοτὲ δὲ καὶ σπανίως ἁθροιζομένων ὁμοῦ τῶν τεττάρων, πάντες οἱ πρὸς τὴν ἁρπαγὴν ἀπομερισθέντες ἀναφέρουσι τὰς ὠφελείας ἕκαστοι τοῖς ἑαυτῶν στρατοπέδοις, κἄπειτα πραθέντων τούτων οἱ χιλίαρχοι διανέμουσι πᾶσιν ἴσον, οὐ μόνον τοῖς μείνασιν ἐν ταῖς ἐφεδρείαις, ἀλλὰ καὶ τοῖς τὰς σκηνὰς φυλάττουσι τοῖς τ’ ἀρρωστοῦσι καὶ τοῖς ἐπί τινα λειτουργίαν ἀπεσταλμένοις. περὶ δὲ τοῦ μηδένα νοσφίζεσθαι μηδὲν τῶν ἐκ τῆς διαρπαγῆς, ἀλλὰ τηρεῖν τὴν πίστιν κατὰ τὸν ὅρκον, ὃν ὀμνύουσι πάντες, ὅταν ἁθροισθῶσι πρῶτον εἰς τὴν παρεμβολήν, ἐξιέναι μέλλοντες εἰς τὴν πολεμίαν, ὑπὲρ τούτου δὲ τοῦ μέρους εἴρηται πρότερον ἡμῖν διὰ πλειόνων ἐν τοῖς περὶ τῆς πολιτείας. λοιπὸν ὅταν οἱ μὲν ἡμίσεις τράπωνται πρὸς τὰς ἁρπαγάς, οἱ δ’ ἡμίσεις διαφυλάττοντες τὰς τάξεις ἐφεδρεύωσι τούτοις, οὐδέποτε κινδυνεύει Ῥωμαίοις τὰ ὅλα διὰ πλεονεξίαν. τῆς γὰρ ἐλπίδος τῆς κατὰ τὴν ὠφέλειαν οὐκ ἀπιστουμένης ἀλλήλοις, ἀλλ’ ἐπ’ ἴσης ἑστηκυίας τοῖς μένουσι κατὰ τὰς ἐφεδρείας καὶ τοῖς διαρπάζουσιν, οὐδεὶς ἀπολείπει τὰς τάξεις· ὃ μάλιστα τοὺς ἄλλους εἴωθε βλάπτειν.", "st": "10.16"}, {"sp": "N", "t": "ἐπειδὴ γὰρ οἱ πλεῖστοι τῶν ἀνθρώπων κακοπαθοῦσι καὶ κινδυνεύουσι τοῦ κέρδους ἕνεκεν, φανερὸν ὡς, ὅταν ὁ καιρὸς οὗτος ὑποπέσῃ, δυσχερῶς εἰκὸς ἀπέχεσθαι τοὺς ἐν ταῖς ἐφεδρείαις ἢ στρατοπεδείαις ἀπολειπομένους διὰ τὸ [τοὺς] παρὰ τοῖς πλείστοις πᾶν τὸ ληφθὲν εἶναι τοῦ κυριεύσαντος· καὶ γὰρ ἂν ὅλως μόναρχος ἢ στρατηγὸς ἐπιμελὴς ἀναφέρειν εἰς τὸ κοινὸν ἐπιτάξῃ τὰς ὠφελείας, ὅμως τὰ δυνατὰ κρύπτεσθαι πάντες ἴδια νομίζουσι. διὸ τῶν πολλῶν ὁρμώντων ἐπὶ τοῦτο τὸ μέρος οὐ δυνάμενοι κρατεῖν κινδυνεύουσι τοῖς ὅλοις· καὶ πολλοὶ δή τινες κατορθώσαντες τὰς ἐπιβολάς, καὶ ποτὲ μὲν ἐπιπεσόντες ταῖς τῶν πολεμίων παρεμβολαῖς, ποτὲ δὲ καταλαβόμενοι πόλεις, οὐ μόνον ἐξέπεσον, ἀλλὰ καὶ τοῖς ὅλοις ἐσφάλησαν παρ’ οὐδὲν ἢ τὴν προειρημένην αἰτίαν. διὸ δεῖ περὶ μηδὲν οὕτω σπουδάζειν καὶ προνοεῖσθαι τοὺς ἡγουμένους ὡς περὶ τοῦτο τὸ μέρος, ἵνα, καθ’ ὅσον ἐστὶ δυνατόν, ὑπάρχῃ παρὰ τοῖς πολλοῖς ἐλπὶς ὡς ἐξ ἴσου πᾶσι τῆς ὠφελείας οὔσης, ἐάν τις ὑποπίπτῃ τοιοῦτος καιρός. πλὴν οἱ μὲν χιλίαρχοι τότε περὶ τὴν τῶν λαφύρων ἦσαν οἰκονομίαν· ὁ δὲ στρατηγὸς τῶν Ῥωμαίων, ἐπεὶ συνήχθη τὸ τῶν αἰχμαλώτων πλῆθος, ὃ συνέβη γενέσθαι μικρῷ λεῖπον τῶν μυρίων, συνέταξε χωρισθῆναι πρῶτον μὲν τοὺς πολιτικοὺς ἄνδρας τε καὶ γυναῖκας καὶ τὰ τούτων τέκνα, δεύτερον δὲ τοὺς χειροτέχνας. γενομένου δὲ τούτου, τοὺς μὲν πολιτικοὺς παρακαλέσας εὐνοεῖν Ῥωμαίοις καὶ μνημονεύειν τῆς εὐεργεσίας ἀπέλυσε πάντας ἐπὶ τὰς ἰδίας οἰκήσεις. οὗτοι μὲν οὖν ἅμα δακρύοντες καὶ χαίροντες ἐπὶ τῷ παραδόξῳ τῆς σωτηρίας, προσκυνήσαντες τὸν στρατηγὸν διελύθησαν· τοῖς δὲ χειροτέχναις κατὰ τὸ παρὸν εἶπε διότι δημόσιοι τῆς Ῥώμης εἰσί· παρασχομένοις δὲ τὴν εὔνοιαν καὶ προθυμίαν ἑκάστοις κατὰ τὰς αὑτῶν τέχνας ἐπηγγείλατο τὴν ἐλευθερίαν, κατὰ νοῦν χωρήσαντος τοῦ πρὸς τοὺς Καρχηδονίους πολέμου. καὶ τούτους μὲν ἀπογράφεσθαι προσέταξε πρὸς τὸν ταμίαν, συστήσας Ῥωμαϊκὸν ἐπιμελητὴν κατὰ τριάκοντα· τὸ γὰρ πᾶν πλῆθος ἐγένετο τούτων περὶ δισχιλίους. ἐκ δὲ τῶν λοιπῶν αἰχμαλώτων ἐκλέξας τοὺς εὐρωστοτάτους καὶ τοῖς εἴδεσι καὶ ταῖς ἡλικίαις ἀκμαιοτάτους προσέμιξε τοῖς αὑτοῦ πληρώμασι, καὶ ποιήσας ἡμιολίους τοὺς πάντας ναύτας ἢ πρόσθεν συνεπλήρωσε καὶ τὰς αἰχμαλώτους νῆας, ὥστε τοὺς ἄνδρας ἑκάστῳ σκάφει βραχύ τι λείπειν τοῦ διπλασίους εἶναι τοὺς ὑπάρχοντας τῶν προγενομένων· αἱ μὲν γὰρ αἰχμάλωτοι νῆες ἦσαν ὀκτωκαίδεκα τὸν ἀριθμόν, αἱ δ’ ἐξ ἀρχῆς πέντε καὶ τριάκοντα. παραπλησίως δὲ καὶ τούτοις ἐπηγγείλατο τὴν ἐλευθερίαν, παρασχομένοις τὴν αὑτῶν εὔνοιαν καὶ προθυμίαν, ἐπειδὰν κρατήσωσι τῷ πολέμῳ τῶν Καρχηδονίων. τοῦτον δὲ χειρίσας τὸν τρόπον τὰ κατὰ τοὺς αἰχμαλώτους μεγάλην μὲν εὔνοιαν καὶ πίστιν ἐνειργάσατο τοῖς πολιτικοῖς καὶ πρὸς αὑτὸν καὶ πρὸς τὰ κοινὰ πράγματα, μεγάλην δὲ προθυμίαν τοῖς χειροτέχναις διὰ τὴν ἐλπίδα τῆς ἐλευθερίας. ἡμιόλιον δὲ ποιήσας τὸ ναυτικὸν ἐκ τοῦ καιροῦ διὰ τὴν αὑτοῦ πρόνοιαν μετὰ δὲ ταῦτα Μάγωνα καὶ τοὺς ἅμα τούτῳ Καρχηδονίους ἐχώριζε.", "st": "10.17"}, {"sp": "N", "t": "δύο μὲν γὰρ ἦσαν κατειλημμένοι τῶν ἐκ τῆς γερουσίας, πέντε δὲ καὶ δέκα τῶν ἐκ τῆς συγκλήτου. καὶ τούτους μὲν συνέστησε Γαΐῳ Λαιλίῳ, συντάξας τὴν ἁρμόζουσαν ἐπιμέλειαν ποιεῖσθαι τῶν ἀνδρῶν· ἐπὶ δὲ τούτοις τοὺς ὁμήρους προσεκαλέσατο, πλείους ὄντας τῶν τριακοσίων. καὶ τοὺς μὲν παῖδας καθ’ ἕνα προσαγαγόμενος καὶ καταψήσας θαρρεῖν ἐκέλευε, διότι μετ’ ὀλίγας ἡμέρας ἐπόψονται τοὺς αὑτῶν γονεῖς· τοὺς δὲ λοιποὺς ὁμοῦ παρεκάλεσε πάντας θαρρεῖν καὶ γράφειν αὐτοὺς εἰς τὰς ἰδίας πόλεις πρὸς αὑτῶν ἀναγκαίους πρῶτον μὲν ὅτι σῴζονται καὶ καλῶς αὐτοῖς ἐστι, δεύτερον δὲ διότι θέλουσι Ῥωμαῖοι πάντας αὐτοὺς εἰς τὴν οἰκείαν ἀποκαταστῆσαι μετ’ ἀσφαλείας, ἑλομένων τῶν ἀναγκαίων σφίσι τὴν πρὸς Ῥωμαίους συμμαχίαν. ταῦτα δ’ εἰπών, καὶ παρεσκευακὼς πρότερον ἐκ τῶν λαφύρων τὰ λυσιτελέστερα πρὸς τὴν ἐπίνοιαν, τότε κατὰ γένη καὶ καθ’ ἡλικίαν ἑκάστοις ἐδωρεῖτο τὰ πρέποντα, ταῖς μὲν παισὶ κόνους καὶ ψέλλια, τοῖς δὲ νεανίσκοις ῥαμφὰς καὶ μαχαίρας. ἐκ δὲ τῶν αἰχμαλωτίδων τῆς Μανδονίου γυναικός, ὃς ἦν ἀδελφὸς Ἀνδοβάλου τοῦ τῶν Ἰλεργητῶν βασιλέως, προσπεσούσης αὐτῷ καὶ δεομένης μετὰ δακρύων ἐπιστροφὴν ποιήσασθαι τῆς αὑτῶν εὐσχημοσύνης ἀμείνω Καρχηδονίων, συμπαθὴς γενόμενος ἤρετο τί λείπει τῶν ἐπιτηδείων αὐταῖς· καὶ γὰρ ἦν ἡ γυνὴ πρεσβυτέρα καί τινα προστασίαν ἀξιωματικὴν ἐπιφαίνουσα. τῆς δὲ κατασιωπώσης ἐκάλει τοὺς πρὸς τὴν ἐπιμέλειαν τῶν γυναικῶν ἀποτεταγμένους. ὧν παραγενομένων καὶ διασαφούντων ὅτι πάντα τὰ δέοντα δαψιλῶς αὐταῖς παρασκευάζοιεν, πάλιν ὁμοίως ἁψαμένης αὐτοῦ τῶν γονάτων τῆς γυναικὸς καὶ τὸν αὐτὸν εἰπούσης λόγον, μᾶλλον ἔτι διαπορήσας ὁ Πόπλιος, καί τινα λαβὼν ἔννοιαν ὡς ὀλιγωρούντων καὶ ψευδῶς πρὸς τὸ παρὸν ἀποφαινομένων τῶν πρὸς τὴν ἐπιμέλειαν ἀποτεταγμένων, θαρρεῖν ἐκέλευε τὰς γυναῖκας· αὐτὸς γὰρ ἑτέρους ἐπιστήσειν τοὺς φροντιοῦντας ἵνα μηδὲν αὐτὰς ἐλλείπῃ τῶν ἐπιτηδείων. ἡ δ’ ἐπισχοῦσα μικρόν \"Οὐκ ὀρθῶς\" ἔφη \"στρατηγέ, τοὺς ἡμετέρους ἐκδέχῃ λόγους, εἰ νομίζεις ἡμᾶς ὑπὲρ τῆς γαστρὸς δεῖσθαί σου νῦν\". καὶ τότε λαβὼν ὁ Πόπλιος ἐν νῷ τὸ βούλημα τῆς γυναικός, καὶ θεωρῶν ὑπὸ τὴν ὄψιν τὴν ἀκμὴν τῶν Ἀνδοβάλου θυγατέρων καὶ πλειόνων ἄλλων δυναστῶν, ἠναγκάσθη δακρῦσαι, τῆς γυναικὸς ἐν ὀλίγῳ τὴν τῆς περιστάσεως ἔμφασιν ὑποδεικνυούσης. διὸ δὴ καὶ τότε φανερὸς γενόμενος ὅτι συνῆκε τὸ ῥηθέν, καὶ λαβόμενος τῆς δεξιᾶς, θαρρεῖν αὐτήν τε ταύτην ἐκέλευε καὶ τὰς ἄλλας ὁμοίως· ποιήσεσθαι γὰρ πρόνοιαν ὡς ἰδίων ἀδελφῶν καὶ τέκνων, συστήσεσθαι δὲ καὶ πρὸς τὴν τούτων ἐπιμέλειαν ἀκολούθως τοῖς προειρημένοις πιστοὺς ἄνδρας.", "st": "10.18"}, {"sp": "N", "t": "μετὰ ταῦτα παρεδίδου τοῖς ταμίαις [τὰ χρήματα], ὅσα δημόσια κατελήφθη τῶν Καρχηδονίων. ἦν δὲ ταῦτα πλείω τῶν ἑξακοσίων ταλάντων, ὥστε προστεθέντων τούτων οἷς παρῆν αὐτὸς ἐκ Ῥώμης ἔχων τετρακοσίοις, τὴν ὅλην παράθεσιν αὐτῷ γενέσθαι τῆς χορηγίας πλείω τῶν χιλίων. κατὰ δὲ τὸν καιρὸν τοῦτον νεανίσκοι τινὲς τῶν Ῥωμαίων ἐπιτυχόντες παρθένῳ κατὰ τὴν ἀκμὴν καὶ κατὰ τὸ κάλλος διαφερούσῃ τῶν ἄλλων γυναικῶν, καὶ συνιδόντες φιλογύνην ὄντα τὸν Πόπλιον, ἧκον αὐτὴν ἄγοντες καὶ παραστήσαντες ἔφασκον αὐτῷ δωρεῖσθαι τὴν κόρην. ὁ δὲ καταπλαγεὶς καὶ θαυμάσας τὸ κάλλος, ἰδιώτης μὲν ὢν οὐδεμίαν ἥδιον ἂν ἔφη δέξασθαι ταύτης τῆς δωρεᾶς, στρατηγὸς δ’ ὑπάρχων οὐδ’ ὁποίαν ἧττον, ὡς μὲν ἐμοὶ δοκεῖ, τοῦτ’ αἰνιττόμενος διὰ τῆς ἀποφάσεως, διότι κατὰ μὲν τὰς ἀναπαύσεις ἐνίοτε καὶ ῥᾳθυμίας ἐν τῷ ζῆν ἡδίστας τοῖς νέοις ἀπολαύσεις τὰ τοιαῦτα παρέχεται καὶ διατριβάς, ἐν δὲ τοῖς τοῦ πράττειν καιροῖς μέγιστα γίνεται καὶ κατὰ σῶμα καὶ κατὰ ψυχὴν ἐμπόδια τοῖς χρωμένοις. τοῖς μὲν οὖν νεανίσκοις ἔφη χάριν ἔχειν, τὸν δὲ τῆς παρθένου πατέρα καλέσας καὶ δοὺς αὐτὴν ἐκ χειρὸς ἐκέλευε συνοικίζειν ᾧ ποτ’ ἂν προαιρῆται τῶν πολιτῶν. δι’ ὧν καὶ τὰ τῆς ἐγκρατείας καὶ τὰ τῆς μετριότητος ἐμφαίνων μεγάλην ἀποδοχὴν ἐνειργάζετο τοῖς ὑποταττομένοις. ταῦτα δὲ διοικησάμενος, καὶ τὰ λοιπὰ τῶν αἰχμαλώτων παραδοὺς τοῖς χιλιάρχοις, ἐξέπεμψε Γάιον τὸν Λαίλιον ἐπὶ πεντήρους εἰς τὴν Ῥώμην, τούς τε Καρχηδονίους συστήσας καὶ τῶν ἄλλων αἰχμαλώτων τοὺς ἐπιφανεστάτους, δηλώσοντα τοῖς ἐν τῇ πατρίδι τὰ γεγονότα. τὸ γὰρ πλεῖον αὐτῶν ἤδη τὰ κατὰ τὴν Ἰβηρίαν ἀπηλπικότων, σαφῶς ᾔδει διότι τούτων προσαγγελθέντων αὖθις ἀναθαρρήσαντες πολλαπλασίως συνεπιλήψονται τῶν πραγμάτων.", "st": "10.19"}, {"sp": "N", "t": "αὐτὸς δὲ χρόνον μέν τιν’ ἐν τῇ Καρχηδόνι τάς τε ναυτικὰς δυνάμεις ἐγύμναζε συνεχῶς καὶ τοῖς χιλιάρχοις ὑπέδειξε τοιοῦτόν τινα τρόπον τῆς τῶν πεζικῶν στρατοπέδων γυμνασίας. τὴν μὲν πρώτην ἡμέραν ἐκέλευσε τροχάζειν ἐπὶ τριάκοντα σταδίους ἐν τοῖς ὅπλοις, τὴν δὲ δευτέραν πάντας ἐκτρίβειν καὶ θεραπεύειν καὶ κατασκοπεῖν ἐν τῷ φανερῷ τὰς πανοπλίας, τῇ δ’ ἑξῆς ἀναπαύεσθαι καὶ ῥᾳθυμεῖν, τῇ δὲ μετὰ ταύτην τοὺς μὲν μαχαιρομαχεῖν ξυλίναις ἐσκυτωμέναις μετ’ ἐπισφαιρῶν μαχαίραις, τοὺς δὲ τοῖς ἐσφαιρωμένοις γρόσφοις ἀκοντίζειν, τῇ δὲ πέμπτῃ πάλιν ἐπὶ τοὺς αὐτοὺς δρόμους καὶ τὴν ἀρχὴν ἐπανάγειν. ἵνα δὲ μήτε τῶν πρὸς τὰς μελέτας ὅπλων μήτε τῶν πρὸς τὴν ἀλήθειαν μηδὲν ἐλλείπῃ, τὴν πλείστην ἐποιεῖτο σπουδὴν πρὸς τοὺς χειροτέχνας. κατὰ μέρος μὲν οὖν ἄνδρας ἐπιμελεῖς ἐφεστάκει πρὸς ταύτην τὴν χρείαν, καθάπερ ἐπάνω προεῖπον· αὐτὸς δὲ καθ’ ἡμέραν ἐπεπορεύετο, καὶ δι’ αὑτοῦ τὰς χορηγίας ἑκάστοις παρεσκεύαζε. λοιπὸν τῶν μὲν πεζικῶν στρατοπέδων κατὰ τοὺς πρὸ τῆς πόλεως τόπους χρωμένων ταῖς μελέταις καὶ ταῖς γυμνασίαις, τῶν δὲ ναυτικῶν δυνάμεων κατὰ θάλατταν ταῖς ἀναπείραις καὶ ταῖς εἰρεσίαις, τῶν δὲ κατὰ τὴν πόλιν ἀκονώντων τε καὶ χαλκευόντων καὶ τεκταινομένων, καὶ συλλήβδην ἁπάντων σπουδαζόντων περὶ τὰς τῶν ὅπλων κατασκευάς, οὐκ ἔσθ’ ὃς οὐκ ἂν εἶπε κατὰ τὸν Ξενοφῶντα τότε θεασάμενος ἐκείνην τὴν πόλιν ἐργαστήριον εἶναι πολέμου. ἐπεὶ δ’ αὐτῷ πάντα καλῶς ἐδόκει καὶ δεόντως ἐξησκῆσθαι τὰ πρὸς τὰς χρείας, μετὰ ταῦτα ταῖς τε φυλακαῖς καὶ ταῖς τῶν τειχῶν κατασκευαῖς ἀσφαλισάμενος τὰ κατὰ τὴν πόλιν, ἀνέζευξε καὶ τῇ πεζικῇ καὶ ναυτικῇ δυνάμει, καὶ προῆγε ποιούμενος τὴν πορείαν ὡς ἐπὶ Ταρράκωνος, ἔχων μεθ’ αὑτοῦ καὶ τοὺς ὁμήρους.", "st": "10.20"}, {"sp": "N", "t": "ὅτι Εὐρυλέων ὁ τῶν Ἀχαιῶν στρατηγὸς ἄτολμος ἦν καὶ πολεμικῆς χρείας ἀλλότριος. τοῦ δὲ καιροῦ τοῦ κατὰ τὴν διήγησιν ἐφεστακότος ἡμᾶς ἐπὶ τὴν ἀρχὴν τῶν Φιλοποίμενος πράξεων, καθήκειν ἡγούμεθα, καθάπερ καὶ περὶ τῶν ἄλλων τῶν ἀξιολόγων ἀνδρῶν τὰς ἑκάστων ἀγωγὰς καὶ φύσεις ἐπειράθημεν ὑποδεικνύναι, καὶ περὶ τούτου ποιῆσαι τὸ παραπλήσιον. καὶ γὰρ ἄτοπον τὰς μὲν τῶν πόλεων κτίσεις τοὺς συγγραφέας, καὶ πότε καὶ πῶς καὶ διὰ τίνων ἐκτίσθησαν, ἔτι δὲ τὰς διαθέσεις καὶ περιστάσεις μετ’ ἀποδείξεως ἐξαγγέλλειν, τὰς δὲ τῶν τὰ ὅλα χειρισάντων ἀνδρῶν ἀγωγὰς καὶ ζήλους παρασιωπᾶν, καὶ ταῦτα τῆς χρείας μεγάλην ἐχούσης τὴν διαφοράν· ὅσῳ γὰρ ἄν τις καὶ ζηλῶσαι καὶ μιμήσασθαι δυνηθείη μᾶλλον τοὺς ἐμψύχους ἄνδρας τῶν ἀψύχων κατασκευασμάτων, τοσούτῳ καὶ τὸν περὶ αὐτῶν λόγον διαφέρειν εἰκὸς πρὸς ἐπανόρθωσιν τῶν ἀκουόντων. εἰ μὲν οὖν μὴ κατ’ ἰδίαν ἐπεποιήμεθα τὴν περὶ αὐτοῦ σύνταξιν, ἐν ᾗ διεσαφοῦμεν καὶ τίς ἦν καὶ τίνων καὶ τίσιν ἀγωγαῖς ἐχρήσατο νέος ὤν, ἀναγκαῖον ἦν ὑπὲρ ἑκάστου τῶν προειρημένων φέρειν ἀπολογισμόν· ἐπεὶ δὲ πρότερον ἐν τρισὶ βυβλίοις ἐκτὸς ταύτης τῆς συντάξεως τὸν ὑπὲρ αὐτοῦ πεποιήμεθα λόγον, τήν τε παιδικὴν ἀγωγὴν διασαφοῦντες καὶ τὰς ἐπιφανεστάτας πράξεις, δῆλον ὡς ἐν τῇ νῦν ἐξηγήσει πρέπον ἂν εἴη τῆς μὲν νεωτερικῆς ἀγωγῆς καὶ τῶν νεωτερικῶν ζήλων κατὰ μέρος ἀφελεῖν, τοῖς δὲ κατὰ τὴν ἀκμὴν αὐτοῦ κεφαλαιωδῶς ἐκεῖ δεδηλωμένοις ἔργοις προσθεῖναι καὶ κατὰ μέρος, ἵνα τὸ πρέπον ἑκατέρᾳ τῶν συντάξεων τηρῶμεν. ὥσπερ γὰρ ἐκεῖνος ὁ τόπος, ὑπάρχων ἐγκωμιαστικός, ἀπῄτει τὸν κεφαλαιώδη καὶ μετ’ αὐξήσεως τῶν πράξεων ἀπολογισμόν, οὕτως ὁ τῆς ἱστορίας, κοινὸς ὢν ἐπαίνου καὶ ψόγου, ζητεῖ τὸν ἀληθῆ καὶ τὸν μετ’ ἀποδείξεως καὶ τῶν ἑκάστοις παρεπομένων συλλογισμῶν.", "st": "10.21"}, {"sp": "N", "t": "Φιλοποίμην τοίνυν πρῶτον μὲν ἔφυ καλῶς· ἦν γὰρ ἐξ ἀνδρῶν τῶν ἐπιφανεστάτων κατ’ Ἀρκαδίαν, τραφεὶς δὲ καὶ παιδευθεὶς ὑπὸ Κλέανδρον τὸν Μαντινέα, πατρικὸν μὲν αὐτῷ ξένον ὑπάρχοντα, φυγαδεύοντα δὲ κατ’ ἐκείνους τοὺς καιρούς, ὄντα δὲ Μαντινέων ἐπιφανέστατον. μετὰ δὲ ταῦτα παραγενόμενος εἰς ἡλικίαν ἐγένετο ζηλωτὴς Ἐκδήμου καὶ Δημοφάνους, οἳ τὸ μὲν γένος ἦσαν ἐκ Μεγάλης πόλεως, φεύγοντες δὲ τοὺς τυράννους καὶ συμβιώσαντες Ἀρκεσίλᾳ τῷ φιλοσόφῳ κατὰ τὴν φυγὴν ἠλευθέρωσαν μὲν τὴν αὑτῶν πατρίδα, συστησάμενοι κατ’ Ἀριστοδήμου τοῦ τυράννου πρᾶξιν, συνεπελάβοντο δὲ καὶ τῆς καταλύσεως τοῦ Σικυωνίων τυράννου Νικοκλέους, κοινωνήσαντες Ἀράτῳ τῆς ἐπιβολῆς· ἔτι δὲ Κυρηναίων αὐτοὺς μεταπεμψαμένων ἐπιφανῶς προύστησαν καὶ διεφύλαξαν αὐτοῖς τὴν ἐλευθερίαν, οἷς κατὰ τὴν πρώτην ἡλικίαν ἐπὶ πολὺ συμβιώσας διέφερε μὲν εὐθέως τῶν καθ’ αὑτὸν περί τε τὰς ἐν τοῖς κυνηγίοις κακοπαθείας καὶ τόλμας περί τε τὰς ἐν τοῖς πολεμικοῖς, ἦν δὲ καὶ περὶ τὸν βίον ἐπιμελὴς καὶ λιτὸς κατὰ τὴν περικοπήν, παρειληφὼς παρὰ τῶν προειρημένων ἀνδρῶν τοιαύτας τινὰς δόξας ὡς οὐχ οἷόν τε τῶν κοινῶν προστατεῖν καλῶς τὸν ὀλιγωροῦντα τῶν κατὰ τὸν ἴδιον βίον, οὔτε μὴν ἀποσχέσθαι τῶν τῆς πατρίδος, ὅστις πολυτελέστερον ζῇ τῆς κατὰ τὴν ἰδίαν ὕπαρξιν χορηγίας. πλὴν κατασταθεὶς ὑπὸ τῶν Ἀχαιῶν ἱππάρχης ἐν τοῖς προειρημένοις καιροῖς, καὶ παραλαβὼν τὰ συντάγματα τῶν ἱππέων παντὶ τρόπῳ κατεφθαρμένα καὶ τὰς ψυχὰς τῶν ἀνδρῶν ἡττημένας, οὐ μόνον αὐτοὺς ἑαυτῶν βελτίους, ἀλλὰ καὶ τῶν ὑπεναντίων κρείττους ἐν ὀλίγῳ χρόνῳ κατεσκεύασε, πάντας εἰς ἀληθινὴν ἄσκησιν καὶ ζῆλον ἐπιτευκτικὸν ἐμβιβάσας. τῶν μὲν γὰρ ἄλλων οἱ πλεῖστοι τῶν καθισταμένων ἐπὶ τὴν προειρημένην ἀρχήν, οἱ μὲν διὰ τὴν ἰδίαν ἀδυναμίαν ἐν τοῖς ἱππικοῖς οὐδὲ τοῖς πλησίον τολμῶσιν οὐδὲν ὧν καθήκει προστάττειν, οἱ δὲ τῆς στρατηγίας ὀρεγόμενοι διὰ ταύτης τῆς ἀρχῆς ἐξεριθεύονται τοὺς νέους καὶ παρασκευάζουσιν εὔνους συναγωνιστὰς εἰς τὸ μέλλον, οὐκ ἐπιτιμῶντες τῷ δεομένῳ, δι’ οὗ τρόπου σῴζεται τὰ κοινά, ἀλλὰ συμπεριστέλλοντες τὰς ἁμαρτίας καὶ μικρᾷ χάριτι μεγάλα βλάπτοντες τοὺς πιστεύοντας. εἰ δέ ποτε γένοιντο τῶν ἀρχόντων τινὲς τῇ τε κατὰ σῶμα χρείᾳ δυνατοὶ πρός τε τὸ τῶν κοινῶν ἀπέχεσθαι πρόθυμοι, πλείω κατὰ τῶν ὀλιγωρούντων διὰ τὴν κακοζηλωσίαν ἀπεργάζονται τοὺς πεζούς, ἔτι δὲ μᾶλλον τοὺς ἱππεῖς.", "st": "10.22"}, {"sp": "N", "t": "ἦσαν δὲ κινήσεις, ἃς ὑπελάμβανε πρὸς πάντα καιρὸν ἁρμόζειν, αἷς ἔδει συνειθίσθαι τοὺς ἱππεῖς, αὗται· αἱ καθ’ ἵππον μὲν κλίσεις ἐφ’ ἡνίαν καὶ πάλιν ἐπὶ δόρυ, πρὸς δὲ τούτοις ἀναστροφὴ καὶ μεταβολή, κατ’ οὐλαμὸν δ’ ἐπιστροφὴ καὶ περισπασμός, ἔτι δ’ ἐκπερισπασμός, πρὸς δὲ τούτοις ἐξαγωγαὶ κατὰ λόχους καὶ διλοχίας ἀφ’ ἑκατέρων τῶν κεράτων μετὰ τάχους, ποτὲ δ’ ἀπὸ τῶν μέσων, καὶ συναγωγαὶ πάλιν μετ’ ἐποχῆς εἰς οὐλαμούς, εἰς ἴλας, εἰς ἱππαρχίας, ἐπὶ δὲ τούτοις ἐκτάξεις ἐφ’ ἑκατέρων τῶν κεράτων ἢ διὰ παρεμβολῆς ἢ διὰ παραγωγῆς τῆς παρὰ τοὺς οὐραγούς. τὰς μὲν γὰρ κατὰ περίκλασιν οὐ προσδεῖσθαι μελέτης ἔφη· σχεδὸν γὰρ ὡς ἂν εἰ πορείας ἔχειν διάθεσιν. ἐκ δὲ τούτου τὰς ἐπαγωγὰς τὰς ἐπὶ τοὺς ἐναντίους καὶ τὰς ἀποχωρήσεις ἔδει συνεθίζειν ἐν πάσαις ταῖς κινήσεσιν ἐπὶ τοσοῦτον ὥστε δεινῷ τῷ τάχει προσάγειν, ἐφ’ ὅσον συζυγοῦντας καὶ συστοιχοῦντας διαμένειν, ἅμα δὲ καὶ τὰ διαστήματα κατὰ τοὺς οὐλαμοὺς τηρεῖν, ὡς ἱππέων λελυκότων τὴν τάξιν τὴν ἐν οὐλαμοῖς, αἱρουμένων κινδυνεύειν, οὐδὲν ἐπισφαλέστερον ὑπάρχον οὐδ’ ἀχρειότερον. ταῦτα δ’ ὑποδείξας τοῖς τε πολλοῖς καὶ τοῖς ἀποτελείοις, αὖθις ἐπεπορεύετο τὰς πόλεις, ἐξετάζων πρῶτον μὲν εἰ συμπεριφέρονθ’ οἱ πολλοὶ τοῖς παραγγελλομένοις, δεύτερον δ’ εἰ κρατοῦσιν οἱ κατὰ πόλεις ἄρχοντες τοῦ σαφῶς καὶ δεόντως διδόναι τὰ παραγγέλματα, κρίνων πρὸς τὴν ἀλήθειαν οὐδὲν ἀναγκαιότερον εἶναι τῆς τῶν κατὰ μέρος ἡγεμόνων ἐμπειρίας.", "st": "10.23"}, {"sp": "N", "t": "προκατασκευασάμενος δὲ τὰ προειρημένα τοῦτον τὸν τρόπον, συνῆγε τοὺς ἱππεῖς ἐκ τῶν πόλεων εἰς ἕνα τόπον, καὶ δι’ αὑτοῦ τὰς κινήσεις ἐπετέλει καὶ τὸν ὅλον χειρισμὸν αὐτὸς ἐποιεῖτο τῆς ἐξοπλισίας, οὐ προηγούμενος πάντων, ὅπερ οἱ νῦν ποιοῦσιν ἡγεμόνες, ὑπολαμβάνοντες ἡγεμονικὴν εἶναι τὴν πρώτην χώραν. τί γὰρ ἀπειρότερον, ἅμα δ’ ἐπισφαλέστερον ἄρχοντος, ὃς ὁρᾶται μὲν ὑπὸ πάντων τῶν ὑποτεταγμένων, ὁρᾷ δ’ οὐδένα; οὐ γὰρ στρατιωτικῆς ἐξουσίας, ἀλλ’ ἡγεμονικῆς ἐμπειρίας, ἅμα δὲ καὶ δυνάμεως δεῖγμα δεῖ φέρειν τὸν ἱππάρχην ἐν ταῖς ἐξοπλισίαις, ποτὲ μὲν ἐν πρώτοις, ποτὲ δ’ ἐν ἐσχάτοις, ποτὲ δὲ κατὰ μέσους γινόμενον. ὅπερ ὁ προειρημένος ἀνὴρ ἐποίει, παριππεύων καὶ πάντας ἐφορῶν αὐτός, καὶ προσδιασαφῶν αὐτοῖς ἀποροῦσι καὶ διορθῶν ἐν ἀρχαῖς πᾶν τὸ διαμαρτανόμενον. ἦν δὲ τὰ τοιαῦτα τελέως βραχέα καὶ σπάνια διὰ τὴν προγεγενημένην ἐν τοῖς κατὰ μέρος ἐπιμέλειαν. Δημήτριος ὁ Φαληρεὺς ἕως λόγου τὸ τοιοῦτον ὑπέδειξε, φήσας ὅτι καθάπερ ἐν οἰκοδομίαις, ἐὰν κατὰ μίαν πλίνθον θῇς καὶ καθ’ ἕνα δόμον ἐπιμελείας τύχῃ τὸ παρατεθέν, οὕτως ἐν στρατοπέδῳ τὸ κατ’ ἄνδρα καὶ κατὰ λόχον ἀκριβωθὲν ὅλην ποιεῖ τὴν δύναμιν ἰσχυράν. —", "st": "10.24"}, {"sp": "N", "t": "εἶναι γὰρ τὸ νῦν γινόμενον ὁμοιότατον τῇ περὶ τὰς παρατάξεις οἰκονομίᾳ καὶ χειρισμῷ. καὶ γὰρ ἐπ’ ἐκείνων προκινδυνεύει μὲν ὡς ἐπίπαν καὶ προαπόλλυται τὰ κοῦφα καὶ τὰ πρακτικώτατα τῆς δυνάμεως, τὴν δ’ ἐπιγραφὴν τῶν ἐκβαινόντων ἡ φάλαγξ καὶ τὰ βαρέα λαμβάνει τῶν ὅπλων. νῦν δὲ παραπλησίως προκινδυνεύουσι μὲν Αἰτωλοὶ καὶ Πελοποννησίων οἱ τούτοις συμμαχοῦντες, ἐφεδρεύουσι δὲ Ῥωμαῖοι, φάλαγγος ἔχοντες διάθεσιν. κἂν μὲν οὗτοι πταίσαντες καταφθαρῶσιν, ἀναστρέψαντες ἐκ τῶν πραγμάτων ἀβλαβεῖς ἀπολυθήσονται Ῥωμαῖοι· νικησάντων δὲ τούτων, ὃ μὴ δόξειε τοῖς θεοῖς, ἅμα τούτοις καὶ τοὺς ἄλλους Ἕλληνας ὑφ’ αὑτοὺς ἐκεῖνοι ποιήσονται. — πᾶσαν γὰρ δημοκρατικὴν συμμαχίαν καὶ φιλίας πολλῆς δεῖσθαι διὰ τὰς ἐν τοῖς πλήθεσι γινομένας ἀλογίας. —", "st": "10.25"}, {"sp": "N", "t": "ὅτι Φίλιππος ὁ βασιλεὺς Μακεδόνων μετὰ τὸ ἐκτελέσαι τὸν τῶν Νεμέων ἀγῶνα αὖθις εἰς Ἄργος ἐπανῆλθε καὶ τὸ μὲν διάδημα καὶ τὴν πορφύραν ἀπέθετο, βουλόμενος αὑτὸν ἴσον τοῖς πολλοῖς καὶ πρᾷόν τινα καὶ δημοτικὸν ὑπογράφειν. ὅσῳ δὲ τὴν ἐσθῆτα δημοτικωτέραν περιετίθετο, τοσούτῳ τὴν ἐξουσίαν ἐλάμβανε μείζω καὶ μοναρχικωτέραν. οὐ γὰρ ἔτι τὰς χήρας ἐπείρα γυναῖκας οὐδὲ τὰς ὑπάνδρους ἠρκεῖτο μοιχεύων, ἀλλ’ ἐκ προστάγματος ἣν αὐτῷ φανείη, προσπέμψας ἐκάλει, ταῖς δὲ μὴ προχείρως συνυπακουούσαις ἐνύβριζε, κώμους ποιούμενος ἐπὶ τὰς οἰκίας. καὶ τῶν μὲν τοὺς υἱεῖς, τῶν δὲ τοὺς ἄνδρας ἀνακαλούμενος ἐπὶ προφάσεσιν ἀλόγοις διέσειε, καὶ πολλὴν ἀσέλγειαν ἐναπεδείκνυτο καὶ παρανομίαν. διὸ καὶ χρώμενος τῇ κατὰ τὴν παρεπιδημίαν ἐξουσίᾳ ἀνέδην πολλοὺς ἐλύπει τῶν Ἀχαιῶν, καὶ μάλιστα τοὺς μετρίους ἄνδρας. πιεζόμενοι δὲ διὰ τὸ πανταχόθεν αὐτοῖς περιεστάναι τὸν πόλεμον ἠναγκάζοντο καρτερεῖν καὶ φέρειν τὰ παρὰ φύσιν. ὅτι [Φιλίππου] οὐκ ἂν ἀγαθὰ μείζω τις σχοίη πρὸς βασιλείαν οὐδεὶς τῶν πρότερον οὐδὲ κακὰ τούτου τοῦ βασιλέως. καί μοι δοκεῖ τὰ μὲν ἀγαθὰ φύσει περὶ αὐτὸν ὑπάρξαι, τὰ δὲ κακὰ προβαίνοντι κατὰ τὴν ἡλικίαν ἐπιγενέσθαι, καθάπερ ἐνίοις ἐπιγίνεται γηράσκουσι τῶν ἵππων. καίπερ ἡμεῖς οὐκ ἐν τοῖς προοιμίοις, ὥσπερ τῶν λοιπῶν συγγραφέων, προφερόμεθα τὰς τοιαύτας διαλήψεις, ἀλλ’ ἐπ’ αὐτῶν τῶν πραγμάτων ἀεὶ τὸν καθήκοντα λόγον ἁρμόζοντες ἀποφαινόμεθα περί τε τῶν βασιλέων καὶ τῶν ἐπιφανῶν ἀνδρῶν, νομίζοντες ταύτην οἰκειοτέραν εἶναι καὶ τοῖς γράφουσι καὶ τοῖς ἀναγινώσκουσι τὴν ἐπισημασίαν.", "st": "10.26"}, {"sp": "N", "t": "ἔστι τοίνυν ἡ Μηδία κατά τε τὸ μέγεθος τῆς χώρας ἀξιοχρεωτάτη τῶν κατὰ τὴν Ἀσίαν δυναστειῶν καὶ κατὰ τὸ πλῆθος καὶ κατὰ τὰς ἀρετὰς τῶν ἀνδρῶν, ὁμοίως δὲ καὶ τῶν ἵππων· τοῖς γὰρ ζῴοις τούτοις σχεδὸν ἅπασαν χορηγεῖ τὴν Ἀσίαν τῷ καὶ τὰ βασιλικὰ συστήματα τῶν ἱπποτροφιῶν Μήδοις ἐπιτετράφθαι διὰ τὴν τῶν τόπων εὐφυΐαν. περιοικεῖται δὲ πόλεσιν Ἑλληνίσι κατὰ τὴν ὑφήγησιν τὴν Ἀλεξάνδρου, φυλακῆς ἕνεκεν τῶν συγκυρούντων αὐτῇ βαρβάρων πλὴν Ἐκβατάνων. αὕτη δ’ ἔκτισται μὲν ἐν τοῖς πρὸς τὰς ἄρκτους μέρεσι τῆς Μηδίας, ἐπίκειται δὲ τοῖς περὶ τὴν Μαιῶτιν καὶ τὸν Εὔξεινον μέρεσι τῆς Ἀσίας, ἦν δὲ βασίλειον ἐξ ἀρχῆς Μήδων, πλούτῳ δὲ καὶ τῇ τῆς κατασκευῆς πολυτελείᾳ μέγα τι παρὰ τὰς ἄλλας δοκεῖ διενηνοχέναι πόλεις. κεῖται μὲν οὖν ὑπὸ τὴν παρώρειαν τὴν παρὰ τὸν Ὀρόντην, ἀτείχιστος οὖσα, ἄκραν δ’ ἐν αὑτῇ χειροποίητον ἔχει, θαυμασίως πρὸς ὀχυρότητα κατεσκευασμένην. ὑπὸ δὲ ταύτην ἐστὶ βασίλεια, περὶ ὧν καὶ τὸ λέγειν κατὰ μέρος καὶ τὸ παρασιωπᾶν ἔχει τιν’ ἀπορίαν· τοῖς μὲν γὰρ αἱρουμένοις τὰς ἐκπληκτικὰς τῶν διηγήσεων προφέρεσθαι καὶ μετ’ αὐξήσεως ἔνια καὶ διαθέσεως εἰθισμένοις ἐξαγγέλλειν καλλίστην ὑπόθεσιν ἡ προειρημένη πόλις ἔχει, τοῖς δ’ εὐλαβῶς προσπορευομένοις πρὸς πᾶν τὸ παρὰ τὴν κοινὴν ἔννοιαν λεγόμενον ἀπορίαν παρασκευάζει καὶ δυσχρηστίαν. πλὴν ἔστι γε τὰ βασίλεια τῷ μὲν μεγέθει σχεδὸν ἑπτὰ σταδίων ἔχοντα τὴν περιγραφήν, τῇ δὲ τῶν κατὰ μέρος κατασκευασμάτων πολυτελείᾳ μεγάλην ἐμφαίνοντα τὴν τῶν ἐξ ἀρχῆς καταβαλλομένων εὐκαιρίαν. οὔσης γὰρ τῆς ξυλείας ἁπάσης κεδρίνης καὶ κυπαριττίνης, οὐδεμίαν αὐτῶν γεγυμνῶσθαι συνέβαινεν, ἀλλὰ καὶ τὰς δοκοὺς καὶ τὰ φατνώματα καὶ τοὺς κίονας τοὺς ἐν ταῖς στοαῖς καὶ περιστύλοις, τοὺς μὲν ἀργυραῖς, τοὺς δὲ χρυσαῖς λεπίσι περιειλῆφθαι, τὰς δὲ κεραμίδας ἀργυρᾶς εἶναι πάσας. τούτων δὲ τὰ μὲν πλεῖστα συνέβη λεπισθῆναι κατὰ τὴν Ἀλεξάνδρου καὶ Μακεδόνων ἔφοδον, τὰ δὲ λοιπὰ κατὰ τὴν Ἀντιγόνου καὶ Σελεύκου τοῦ Νικάνορος δυναστείαν. ὅμως δὲ κατὰ τὴν Ἀντιόχου παρουσίαν ὅ τε ναὸς αὐτὸς ὁ τῆς Αἴνης προσαγορευόμενος ἔτι τοὺς κίονας εἶχε τοὺς πέριξ κεχρυσωμένους, καὶ κεραμίδες ἀργυραῖ καὶ πλείους ἐν αὐτῷ συνετέθειντο, πλίνθοι δὲ χρυσαῖ τινες ὀλίγαι μὲν ἦσαν, ἀργυραῖ δὲ καὶ πλείους ὑπέμενον. ἐκ δὲ πάντων τῶν προειρημένων τὸ χαραχθὲν εἰς τὸ βασιλικὸν ἡθροίσθη νόμισμα μικρῷ λεῖπον τετρακισχιλίων ταλάντων. —", "st": "10.27"}, {"sp": "N", "t": "ἕως μὲν οὖν τούτων τῶν τόπων ἤλπισεν αὐτὸν ἥξειν Ἀρσάκης, τὴν δ’ ἔρημον τὴν τούτοις πρόσχωρον οὐ τολμήσειν ἔτι δυνάμει τηλικαύτῃ διεκβαλεῖν, καὶ μάλιστα διὰ τὴν ἀνυδρίαν. ἐπιπολῆς μὲν γὰρ οὐδέν ἐστι φαινόμενον ὕδωρ ἐν τοῖς προειρημένοις τόποις, ὑπόνομοι δὲ πλείους εἰσὶ καὶ διὰ τῆς ἐρήμου φρεατίας ἔχοντες ἀγνοουμένας τοῖς ἀπείροις. περὶ δὲ τούτων ἀληθὴς παραδίδοται λόγος διὰ τῶν ἐγχωρίων, ὅτι καθ’ οὓς χρόνους Πέρσαι τῆς Ἀσίας ἐπεκράτουν, ἔδωκαν τοῖς ἐπί τινας τόπους τῶν μὴ πρότερον ἀρδευομένων ἐπεισαγομένοις ὕδωρ πηγαῖον ἐπὶ πέντε γενεὰς καρπεῦσαι τὴν χώραν· ὅθεν ἔχοντος τοῦ Ταύρου πολλὰς καὶ μεγάλας ὑδάτων ἀπορρύσεις, πᾶσαν ἐπεδέχοντο δαπάνην καὶ κακοπάθειαν, ἐκ μακροῦ κατασκευάζοντες τοὺς ὑπονόμους, ὥστε κατὰ τοὺς νῦν καιροὺς μηδὲ τοὺς χρωμένους τοῖς ὕδασι γινώσκειν τὰς ἀρχὰς τῶν ὑπονόμων πόθεν ἔχουσι τὰς ἐπιρρύσεις. πλὴν ὁρῶν Ἀρσάκης ἐπιβαλόμενον αὐτὸν τῇ διὰ τῆς ἐρήμου πορείᾳ, τὸ τηνικάδε χωννύειν καὶ φθείρειν ἐνεχείρησε τὰς φρεατίας. ὁ δὲ βασιλεύς, ἐξαγγελθέντος αὐτῷ, πάλιν ἐξαπέστειλε τοὺς περὶ Νικομήδην μετὰ χιλίων ἱππέων, οἳ καὶ καταλαβόντες τὸν Ἀρσάκην μετὰ τῆς δυνάμεως ὑποκεχωρηκότα, τινὰς δὲ τῶν ἱππέων φθείροντας τὰ στόματα τῶν ὑπονόμων, τούτους μὲν ἐξ ἐφόδου τρεψάμενοι φυγεῖν ἠνάγκασαν, αὐτοὶ δὲ πάλιν ἀνεχώρησαν ὡς τὸν Ἀντίοχον. ὁ δὲ βασιλεὺς διανύσας τὴν ἔρημον ἧκε πρὸς τὴν Ἑκατόμπυλον προσαγορευομένην, ἣ κεῖται μὲν ἐν μέσῃ τῇ Παρθυηνῇ, τῶν δὲ διόδων τῶν φερουσῶν ἐπὶ πάντας τοὺς πέριξ τόπους ἐνταῦθα συμπιπτουσῶν ἀπὸ τοῦ συμβαίνοντος ὁ τόπος εἴληφε τὴν προσηγορίαν.", "st": "10.28"}, {"sp": "N", "t": "πλὴν αὐτοῦ διαναπαύσας τὴν δύναμιν, καὶ συλλογισάμενος ὡς εἰ μὲν οἷός τ’ ἦν Ἀρσάκης διὰ μάχης κρίνεσθαι πρὸς σφᾶς, οὔτ’ ἂν ἐξεχώρει λιπὼν τὴν αὑτοῦ χώραν οὔτ’ ἂν ἐπιτηδειοτέρους τόπους ἐζήτει πρὸς ἀγῶνα ταῖς σφετέραις δυνάμεσι τῶν περὶ τὴν Ἑκατόμπυλον· ἐπειδὴ δ’ ἐκχωρεῖ, δῆλός ἐστι τοῖς ὀρθῶς σκοπουμένοις ἐπ’ ἄλλης ὢν γνώμης· διόπερ ἔκρινε προάγειν εἰς τὴν Ὑρκανίαν. παραγενόμενος δ’ ἐπὶ Ταγάς, καὶ πυνθανόμενος τῶν ἐγχωρίων τήν τε δυσχέρειαν τῶν τόπων, οὓς ἔδει διεκβάλλειν αὐτόν, ἕως εἰς τὰς ὑπερβολὰς διεξίκοιτο τοῦ Λάβου τὰς νευούσας ἐπὶ τὴν Ὑρκανίαν, καὶ τὸ πλῆθος τῶν βαρβάρων τῶν κατὰ τόπους ἐφεστώτων ταῖς δυσχωρίαις αὐτοῦ, προέθετο διατάττειν τὸ τῶν εὐζώνων πλῆθος καὶ τοὺς τούτων ἡγεμόνας μερίζειν, ὡς ἑκάστους δεήσει πορεύεσθαι, ὁμοίως δὲ καὶ τοὺς λειτουργούς, οὓς ἔδει παραπορευομένους τὸν καταλαμβανόμενον ὑπὸ τῶν εὐζώνων τόπον εὔβατον παρασκευάζειν τῇ τῶν φαλαγγιτῶν καὶ τῇ τῶν ὑποζυγίων πορείᾳ. ταῦτα δὲ διανοηθεὶς τὴν μὲν πρώτην ἔδωκε τάξιν Διογένει, συστήσας αὐτῷ τοξότας καὶ σφενδονήτας καὶ τῶν ὀρείων τοὺς ἀκοντίζειν καὶ λιθάζειν δυναμένους, οἵτινες τάξιν μὲν οὐκ ἔνεμον, αἰεὶ δὲ πρὸς τὸν παρόντα καιρὸν καὶ τόπον κατ’ ἄνδρα ποιούμενοι τὸν κίνδυνον πραγματικωτάτην παρείχοντο χρείαν ἐν ταῖς δυσχωρίαις. τούτοις δὲ συνεχεῖς Κρῆτας ἀσπιδιώτας ἐπέταξε περὶ δισχιλίους, ὧν ἡγεῖτο Πολυξενίδας Ῥόδιος, τελευταίους δὲ θωρακίτας καὶ θυρεοφόρους, ὧν εἶχον τὴν ἡγεμονίαν Νικομήδης Κῷος καὶ Νικόλαος Αἰτωλός.", "st": "10.29"}, {"sp": "N", "t": "προαγόντων δὲ τούτων εἰς τὸ πρόσθεν, πολλῷ δυσχερεστέρας συνέβαινε φαίνεσθαι τὰς τῶν τόπων τραχύτητας καὶ στενότητας τῆς τοῦ βασιλέως προσδοκίας. ἦν γὰρ τὸ μὲν ὅλον μῆκος τῆς ἀναβάσεως περὶ τριακοσίους σταδίους· ταύτης δὲ τὸ πλεῖστον μέρος ἔδει ποιεῖσθαι τῆς πορείας διὰ χαράδρας χειμάρρου καὶ βαθείας, εἰς ἣν πολλαὶ μὲν αὐτομάτως ἐκ τῶν ὑπερκειμένων κρημνῶν πέτραι κατενηνεγμέναι καὶ δένδρα δύσβατον ἐποίουν τὴν δι’ αὐτῆς πορείαν, πολλὰ δ’ ὑπὸ τῶν βαρβάρων εἰς τοῦτο τὸ μέρος συνηργεῖτο. καὶ γὰρ ἐκκοπὰς δένδρων ἐπεποίηντο συνεχεῖς καὶ λίθων πλήθη μεγέθει διαφερόντων συνηθροίκεισαν· αὐτοί τε παρ’ ὅλην τὴν φάραγγα τὰς εὐκαίρους ὑπεροχὰς καὶ δυναμένας σφίσιν ἀσφάλειαν παρέχεσθαι κατειληφότες ἐτήρουν, ὥστ’, εἰ μὴ διήμαρτον, ἐντελῶς ἂν ἐξαδυνατήσαντα τὸν Ἀντίοχον ἀποστῆναι τῆς ἐπιβολῆς. ὡς γὰρ δέον τοὺς πολεμίους πάντας κατ’ ἀνάγκην ποιεῖσθαι δι’ αὐτῆς τῆς φάραγγος τὴν ἀνάβασιν, οὕτως παρεσκευάσαντο καὶ πρὸς τοῦτο κατελάβοντο τοὺς τόπους. ἐκεῖνο δ’ οὐκ ἔβλεψαν ὅτι τὴν μὲν φάλαγγα καὶ τὴν ἀποσκευὴν οὐκ ἄλλως δυνατὸν ἦν, ἀλλ’ ὡς ἐκεῖνοι διέλαβον, ποιεῖσθαι τὴν πορείαν· πρὸς γὰρ τὰ παρακείμενα τῶν ὀρῶν οὐχ οἷόν τ’ ἦν τούτοις προσβαλεῖν, ἀλλὰ τοῖς ψιλοῖς καὶ τοῖς εὐζώνοις οὐκ ἀδύνατος ἦν ἡ δι’ αὐτῶν τῶν λευκοπέτρων ἀναβολή. ὅθεν ἅμα τῷ πρὸς τὸ πρῶτον φυλακεῖον προσμῖξαι τοὺς περὶ τὸν Διογένην, ἔξωθεν τῆς χαράδρας ποιουμένους τὴν ἀνάβασιν, ἀλλοιοτέραν ἐλάμβανε διάθεσιν. εὐθέως γὰρ κατὰ τὴν συμπλοκὴν αὐτοῦ τοῦ πράγματος διδάσκοντος, ὑπερτιθέμενοι καὶ προσβαίνοντες πρὸς τὰ πλάγια τῶν χωρίων οἱ περὶ τὸν Διογένην, ὑπερδέξιοι τῶν πολεμίων ἐγίνοντο, καὶ χρώμενοι πυκνοῖς τοῖς ἀκοντίσμασι καὶ τοῖς ἐκ χειρὸς λίθοις κακῶς διετίθεσαν τοὺς βαρβάρους, καὶ μάλιστα ταῖς σφενδόναις ἐκακοποίουν ἐξ ἀποστήματος βάλλοντες. ὅτε δὲ τοὺς πρώτους ἐκβιασάμενοι κατάσχοιεν τὸν τούτων τόπον, ἐδίδοτο τοῖς λειτουργοῖς καιρὸς εἰς τὸ πᾶν τὸ πρὸ ποδῶν ἀνακαθαίρειν καὶ λεαίνειν μετ’ ἀσφαλείας. ἐγίνετο δὲ τοῦτο ταχέως διὰ τὴν πολυχειρίαν. οὐ μὴν ἀλλὰ τούτῳ τῷ τρόπῳ τῶν μὲν σφενδονητῶν καὶ τοξοτῶν ἔτι δ’ ἀκοντιστῶν κατὰ τοὺς ὑπερδεξίους τόπους πορευομένων σποράδην, ποτὲ δὲ συναθροιζομένων καὶ καταλαμβανομένων τοὺς εὐκαίρους τόπους, τῶν δ’ ἀσπιδιωτῶν ἐφεδρευόντων, καὶ παρ’ αὐτὴν τὴν χαράδραν παραπορευομένων ἐν τάξει καὶ βάδην, οὐκ ἔμενον οἱ βάρβαροι, πάντες δὲ λιπόντες τοὺς τόπους ἡθροίσθησαν ἐπὶ τὴν ὑπερβολήν.", "st": "10.30"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Ἀντίοχον ἀσφαλῶς διέβησαν τὰς δυσχωρίας τῷ προειρημένῳ τρόπῳ, βραδέως δὲ καὶ δυσχερῶς· μόλις γὰρ ὀγδοαῖοι πρὸς τὰς κατὰ τὸν Λάβον ὑπεροχὰς ἀφίκοντο. τῶν δὲ βαρβάρων συνηθροισμένων ἐκεῖ, καὶ πεπεισμένων κωλύειν τῆς ὑπερβολῆς τοὺς πολεμίους, ἀγὼν συνέστη νεανικός. ἐξεώσθησαν δ’ οἱ βάρβαροι διὰ τοιαύτας αἰτίας. συστραφέντες γὰρ ἐμάχοντο πρὸς τοὺς φαλαγγίτας κατὰ πρόσωπον ἐκθύμως· τῆς δὲ νυκτὸς ἔτι τῶν εὐζώνων ἐκπεριελθόντων ἐκ πολλοῦ, καὶ καταλαβομένων τοὺς ὑπερδεξίους καὶ κατὰ νώτου τόπους, ἅμα τῷ συνιδεῖν οἱ βάρβαροι τὸ γεγονὸς εὐθέως πτοηθέντες ὥρμησαν πρὸς φυγήν. ὁ δὲ βασιλεὺς τὴν μὲν ἐπὶ πλεῖον ὁρμὴν τῶν διωκόντων παρακατέσχε μετὰ πολλῆς σπουδῆς, ἀνακαλεσάμενος ταῖς σάλπιγξι, διὰ τὸ βούλεσθαι καταβαίνειν ἅθρους καὶ συντεταγμένους εἰς τὴν Ὑρκανίαν. συστησάμενος δὲ τὴν πορείαν ὡς ἐβούλετο καὶ παραγενόμενος ἐπὶ Τάμβρακα, πόλιν ἀτείχιστον, ἔχουσαν δὲ βασίλεια καὶ μέγεθος, αὐτοῦ κατεσκήνωσε. τῶν δὲ πλείστων πεποιημένων τὴν ἀποχώρησιν ἔκ τε τῆς μάχης καὶ τῆς περικειμένης χώρας εἰς τὴν προσαγορευομένην Σίρυγκα πόλιν — συνέβαινε κεῖσθαι ’κείνην οὐ μακρὰν τῆς Τάμβρακος, εἶναι δὲ τῆς Ὑρκανίας ὡς ἂν εἰ βασίλειον διά τε τὴν ὀχυρότητα καὶ τὴν ἄλλην εὐκαιρίαν — ἔκρινε ταύτην ἐξελεῖν μετὰ βίας. ἀναλαβὼν οὖν τὴν δύναμιν προῆγε, καὶ περιστρατοπεδεύσας ἤρχετο τῆς πολιορκίας. ἦν δὲ τὸ πλεῖστον μέρος τῆς ἐπιβολῆς ἐν ταῖς χωστρίσι χελώναις. τάφροι γὰρ ἦσαν τριτταί, πλάτος μὲν οὐκ ἔλαττον ἔχουσαι τριάκοντα πηχῶν, βάθος δὲ πεντεκαίδεκα· ἐπὶ δὲ τοῖς χείλεσιν ἑκάστης ἐπέκειτο χαρακώματα διπλᾶ καὶ τελευταῖον προτείχισμα δυνατόν. συμπλοκαὶ μὲν οὖν ἐγίνοντο συνεχεῖς ἐπὶ τῶν ἔργων, ἐν αἷς οὐκ ἤνυον ἑκάτεροι φέροντες τοὺς νεκροὺς καὶ τοὺς τραυματίας διὰ τὸ μὴ μόνον ὑπὲρ γῆς, ἀλλὰ καὶ κατὰ γῆς διὰ τῶν ὀρυγμάτων ἐκ χειρὸς γίνεσθαι τοὺς κινδύνους. οὐ μὴν ἀλλὰ τῷ πλήθει καὶ τῇ τοῦ βασιλέως ἐνεργείᾳ ταχέως συνέβη καὶ τὰς τάφρους χωσθῆναι καὶ τὸ τεῖχος πεσεῖν διὰ τῶν ὀρυγμάτων. οὗ συμβάντος διατραπέντες οἱ βάρβαροι τοῖς ὅλοις, καὶ τοὺς μὲν Ἕλληνας κατασφάξαντες τοὺς ἐν τῇ πόλει, τὰ δ’ ἐπιφανέστατα τῶν σκευῶν διαρπάσαντες, νυκτὸς ἀπεχώρησαν. ὁ δὲ βασιλεὺς συνθεασάμενος Ὑπερβάσαν ἀπέστειλε μετὰ τῶν μισθοφόρων· οὗ συμμίξαντος οἱ βάρβαροι ῥίψαντες τὰς ἀποσκευὰς αὖθις εἰς τὴν πόλιν ἔφυγον. τῶν δὲ πελταστῶν ἐνεργῶς βιαζομένων διὰ τοῦ πτώματος, ἀπελπίσαντες σφᾶς αὐτοὺς παρέδοσαν. Ἀχριανή, πόλις Ὑρκανίας. Πολύβιος δεκάτῳ. Καλλιόπη, πόλις Παρθυαίων. Πολύβιος δεκάτῳ.", "st": "10.31"}, {"sp": "N", "t": "βουλόμενοι δ’ οἱ ὕπατοι κατοπτεῦσαι σαφῶς τὰ πρὸς τὴν τῶν ὑπεναντίων στρατοπεδείαν κεκλιμένα μέρη τοῦ λόφου, τοῖς μὲν ἐν τῷ χάρακι μένειν κατὰ χώραν ἐπήγγειλαν, αὐτοὶ δὲ τῶν ἱππέων ἀναλαβόντες ἴλας δύο καὶ γροσφομάχους μετὰ τῶν ῥαβδοφόρων εἰς τριάκοντα προῆγον, κατασκεψόμενοι τοὺς τόπους. τῶν δὲ Νομάδων εἰθισμένοι τινὲς τοῖς ἀκροβολιζομένοις καὶ καθόλου προπορευομένοις ἐκ τοῦ τῶν ὑπεναντίων χάρακος ἐνέδρας ποιεῖν, ὑπεστάλκεισαν κατά τινα συντυχίαν ὑπὸ τὸν λόφον. οἷς τοῦ σκοποῦ σημήναντος ὅτι παραγίνονταί τινες κατ’ ἄκρον τὸν βουνὸν ὑπερδέξιοι ’κείνων, ἐξαναστάντες καὶ παρὰ πλάγια ποιησάμενοι τὴν πορείαν ἀποτέμνονται τοὺς στρατηγοὺς καὶ διακλείουσιν ἀπὸ τῆς ἰδίας παρεμβολῆς. καὶ τὸν μὲν Κλαύδιον εὐθέως ἐν τῇ πρώτῃ συμπλοκῇ καί τινας ἑτέρους ἅμα τούτῳ κατέβαλον, τοὺς δὲ λοιποὺς κατατραυματίσαντες διὰ τῶν κρημνῶν ἠνάγκασαν ἄλλον ἄλλῃ φεύγειν. οἱ δ’ ἐν τῷ στρατοπέδῳ θεωροῦντες τὸ γινόμενον οὐδαμῶς ἠδυνήθησαν ἐπικουρῆσαι τοῖς κινδυνεύουσιν· ἔτι γὰρ ἀναβοώντων καὶ πρὸς τὸ συμβαῖνον ἐκπεπληγμένων, καὶ τῶν μὲν χαλινούντων τοὺς ἵππους, τῶν δὲ καθοπλιζομένων, πέρας εἶχε τὸ πρᾶγμα. καὶ τὸν υἱὸν τοῦ Κλαυδίου τραυματίαν, μόλις καὶ παραδόξως τὸν κίνδυνον διαπεφευγότα Μάρκος μὲν οὖν ἀκακώτερον ἢ στρατηγικώτερον αὑτῷ χρησάμενος τοῖς δεδηλωμένοις περιέπεσε συμπτώμασιν· ἐγὼ δὲ παρ’ ὅλην τὴν πραγματείαν πολλάκις ἀναγκάζομαι περὶ τῶν τοιούτων ὑπομιμνήσκειν τοὺς ἐντυγχάνοντας, θεωρῶν, εἰ καὶ περί τι τῶν τῆς στρατηγίας μερῶν ἄλλο, καὶ περὶ τοῦτο διαμαρτάνοντας τοὺς ἡγεμόνας, καίτοι προδήλου τῆς ἀγνοίας ὑπαρχούσης. τί γὰρ ὄφελος ἡγεμόνος ἢ στρατηγοῦ μὴ διειληφότος διότι τῶν κατὰ μέρος κινδύνων, οἷς μὴ συμπάσχει τὰ ὅλα, πλεῖστον ἀπέχειν δεῖ τὸν ἡγούμενον; τί δ’ ἀγνοοῦντος ὅτι, κἄν ποτ’ ἀναγκάζωσιν οἱ καιροὶ πράττειν τι τῶν κατὰ μέρος, πολλοὺς δεῖ πρότερον ἀποθανεῖν τῶν συνόντων πρὶν ἢ τὸ δεινὸν ἐγγίσαι τοῖς προεστῶσι τῶν ὅλων; δεῖ γὰρ ἐν Καρὶ τὴν πεῖραν, ὡς ἡ παροιμία φησίν, οὐκ ἐν τῷ στρατηγῷ γίνεσθαι. τὸ μὲν γὰρ λέγειν ὡς \"οὐκ ἂν ᾠόμην\" \"τίς γὰρ ἂν ἤλπισε τοῦτο γενέσθαι\"; μέγιστον εἶναί μοι δοκεῖ σημεῖον ἀπειρίας στρατηγικῆς καὶ βραδυτῆτος.", "st": "10.32"}, {"sp": "N", "t": "διὸ καὶ τὸν Ἀννίβαν κατὰ πολλοὺς τρόπους ἀγαθὸν ἡγεμόνα κρίνων, κατὰ τοῦτο μάλιστά τις ἂν ἐπισημήναιτο, διότι πολλοὺς μὲν χρόνους ἐν τῇ πολεμίᾳ διατρίψας, πολλοῖς δὲ καιροῖς καὶ ποικίλοις χρησάμενος, ἔσφηλε μὲν τοὺς ὑπεναντίους πολλάκις ἐν ταῖς κατὰ μέρος χρείαις διὰ τὴν ἰδίαν ἀγχίνοιαν, ἐσφάλη δ’ οὐδέποτε τοσούτους καὶ τηλικούτους ἀγῶνας χειρίσας· τοιαύτην ἐποιεῖτο τὴν πρόνοιαν, ὡς ἔοικε, περὶ τῆς ἀσφαλείας αὑτοῦ. καὶ μάλ’ εἰκότως· ἀκεραίου μὲν γὰρ καὶ σῳζομένου τοῦ προεστῶτος, κἄν ποτε πέσῃ τὰ ὅλα, πολλὰς ἀφορμὰς ἡ τύχη δίδωσι πρὸς τὸ πάλιν ἀνακτήσασθαι τὰς ἐκ τῶν περιπετειῶν ἐλαττώσεις· πταίσαντος δέ, καθάπερ ἐν νηὶ τοῦ κυβερνήτου, κἂν [τὸ νικᾶν] ἡ τύχη τοῖς πολλοῖς παραδιδῷ κρατεῖν τῶν ἐχθρῶν, οὐδὲν ὄφελος γίνεται διὰ τὸ πάσας ἐξηρτῆσθαι τὰς ἐλπίδας ἑκάστοις ἐκ τῶν ἡγουμένων. ταῦτα μὲν οὖν εἰρήσθω μοι πρὸς τοὺς ἢ διὰ κενοδοξίαν ἢ μειρακιώδει παραστάσει περιπίπτοντας τοῖς τοιούτοις ἀλογήμασιν ἢ δι’ ἀπειρίαν ἢ διὰ καταφρόνησιν· ἓν γὰρ ἀεί τι τῶν προειρημένων αἴτιον γίνεται τῶν τοιούτων περιπετειῶν. — οἱ δὲ καταρράκτας, οὓς εἶχον ὀλίγον ἐξωτέρω διὰ μηχανημάτων ἀνημμένους, αἰφνίδιον καθῆκαν καὶ ἐπεβάλοντο, καὶ τούτους κατασχόντες πρὸ τοῦ τείχους ἀνεσκολόπισαν.", "st": "10.33"}, {"sp": "N", "t": "κατὰ δὲ τὴν Ἰβηρίαν Πόπλιος ὁ τῶν Ῥωμαίων στρατηγός, ποιούμενος τὴν παραχειμασίαν ἐν Ταρράκωνι, καθάπερ ἐν τοῖς πρὸ τούτων δεδηλώκαμεν, πρῶτον μὲν τοὺς Ἴβηρας εἰς τὴν αὑτῶν φιλίαν καὶ πίστιν ἐνεδήσατο διὰ τῆς τῶν ὁμήρων ἑκάστοις ἀποδόσεως, λαβὼν συναγωνιστὴν ἐκ ταὐτομάτου πρὸς τοῦτο τὸ μέρος Ἐδεκῶνα τὸν Ἐδετανῶν δυνάστην, ὃς ἅμα τῷ προσπεσεῖν τὴν Καρχηδόνος ἅλωσιν καὶ γενέσθαι κύριον τῆς γυναικὸς αὐτοῦ καὶ τῶν υἱῶν τὸν Πόπλιον, εὐθέως συλλογισάμενος τὴν ἐσομένην τῶν Ἰβήρων μεταβολὴν ἀρχηγὸς ἐβουλήθη γενέσθαι τῆς αὐτῆς ὁρμῆς, μάλιστα πεπεισμένος οὕτως τὴν γυναῖκα καὶ τὰ τέκνα κομιεῖσθαι καὶ δόξειν οὐ κατ’ ἀνάγκην, ἀλλὰ κατὰ πρόθεσιν αἱρεῖσθαι τὰ Ῥωμαίων· ἃ καὶ συνέβη γενέσθαι. τῶν γὰρ δυνάμεων ἄρτι διαφειμένων εἰς τὴν παραχειμασίαν παρῆν εἰς τὴν Ταρράκωνα μετὰ τῶν οἰκείων καὶ φίλων. ἐλθὼν δ’ εἰς λόγους τῷ Ποπλίῳ ταύτην ἔφη τοῖς θεοῖς μεγίστην χάριν ἔχειν, ὅτι πρῶτος τῶν κατὰ τὴν χώραν δυναστῶν ἥκει πρὸς αὐτόν. τοὺς μὲν γὰρ ἄλλους ἀκμὴν διαπέμπεσθαι καὶ βλέπειν πρὸς Καρχηδονίους, τὰς δὲ χεῖρας ἐκτείνειν Ῥωμαίοις· αὐτὸς δὲ παραγεγονέναι διδοὺς οὐ μόνον αὑτόν, ἀλλὰ καὶ τοὺς φίλους καὶ συγγενεῖς εἰς τὴν Ῥωμαίων πίστιν. διόπερ ἂν νομισθῇ παρ’ αὐτῷ φίλος καὶ σύμμαχος, μεγάλην μὲν αὐτῷ πρὸς τὸ παρὸν ἔφη, μεγάλην δ’ εἰς τὸ μέλλον παρέξεσθαι χρείαν. παραυτίκα μὲν γὰρ θεασαμένους τοὺς Ἴβηρας πρός τε τὴν φιλίαν αὑτὸν προσδεδεγμένον καὶ τετευχότα τῶν ἀξιουμένων πάντας ἐπὶ τὸ παραπλήσιον ἥξειν, σπουδάζοντας κομίσασθαι τοὺς ἀναγκαίους καὶ τυχεῖν τῆς Ῥωμαίων συμμαχίας· εἰς δὲ τὸν μετὰ ταῦτα χρόνον προκαταληφθέντας τῇ τοιαύτῃ τιμῇ καὶ φιλανθρωπίᾳ συναγωνιστὰς ἀπροφασίστους ὑπάρξειν αὐτῷ πρὸς τὰ κατάλοιπα τῶν ἔργων. διόπερ ἠξίου τὴν γυναῖκα καὶ τὰ τέκνα κομίσασθαι, καὶ κριθεὶς φίλος ἐπανελθεῖν εἰς τὴν οἰκείαν, ἵνα λαβὼν ἀφορμὴν εὔλογον ἐναποδείξηται τὴν αὑτοῦ καὶ τῶν φίλων εὔνοιαν κατὰ δύναμιν εἴς τε τὸν Πόπλιον αὐτὸν καὶ τὰ Ῥωμαίων πράγματα. Ἐδεκὼν μὲν οὖν τοιαῦτα διαλεχθεὶς ἐπέσχεν·", "st": "10.34"}, {"sp": "N", "t": "ὁ δὲ Πόπλιος, καὶ πάλαι πρὸς τοῦτο τὸ μέρος ἕτοιμος ὢν καὶ συλλελογισμένος παραπλήσια τοῖς ὑπὸ τοῦ Ἐδεκῶνος εἰρημένοις, τὴν γυναῖκα καὶ τὰ τέκνα παρέδωκεν αὐτῷ καὶ τὴν φιλίαν συνέθετο. πρὸς δὲ τούτοις παρὰ τὴν συνουσίαν ποικίλως ψυχαγωγήσας τὸν Ἴβηρα καὶ πᾶσι τοῖς αὐτοῦ μεγάλας εἰς τὸ μέλλον ἐλπίδας ὑπογράψας, οὕτως εἰς τὴν οἰκείαν ἐξαπέστειλε. τούτου τοῦ πράγματος ταχέως περιβοήτου γενομένου πάντας συνέβη τοὺς ἐντὸς Ἴβηρος ποταμοῦ κατοικοῦντας οἷον ἀπὸ μιᾶς ὁρμῆς ἑλέσθαι τὰ Ῥωμαίων, ὅσοι μὴ πρότερον αὐτῶν ὑπῆρχον φίλοι. ταῦτα μὲν οὖν καλῶς κατὰ νοῦν ἐχώρει τῷ Ποπλίῳ· μετὰ δὲ τὸν τούτων χωρισμὸν τὰς μὲν ναυτικὰς δυνάμεις διέλυσε, θεωρῶν οὐδὲν ἀντίπαλον ὑπάρχον κατὰ θάλατταν, ἐκ δὲ τῶν ναυτῶν ἐκλέξας τοὺς ἐπιτηδείους ἐπὶ τὰς σημαίας ἐμέρισε. καὶ συνηύξησε τοιούτῳ τρόπῳ τὰς πεζικὰς δυνάμεις. Ἀνδοβάλης δὲ καὶ Μανδόνιος, μέγιστοι μὲν ὄντες δυνάσται τότε τῶν κατ’ Ἰβηρίαν, ἀληθινώτατοι δὲ Καρχηδονίων φίλοι δοξαζόμενοι, πάλαι μὲν ὑπούλως διέκειντο καὶ καιρὸν ἐπετήρουν, ἐξ ὅτου προσποιηθέντες οἱ περὶ τὸν Ἀσδρούβαν ἀπιστεῖν αὐτοῖς ᾔτησαν χρημάτων τε πλῆθος καὶ τὰς γυναῖκας καὶ τὰς θυγατέρας εἰς ὁμηρείαν, καθάπερ ἐν τοῖς πρὸ τούτων ἐδηλώσαμεν· τότε δὲ νομίσαντες ἔχειν εὐφυῆ καιρόν, ἀναλαβόντες τὰς ἑαυτῶν δυνάμεις ἐκ τῆς Καρχηδονίων παρεμβολῆς νυκτὸς ἀπεχώρησαν εἴς τινας ἐρυμνοὺς τόπους καὶ δυναμένους αὐτοῖς τὴν ἀσφάλειαν παρασκευάζειν. οὗ γενομένου καὶ τῶν ἄλλων Ἰβήρων συνέβη τοὺς πλείστους ἀπολιπεῖν Ἀσδρούβαν, πάλαι μὲν βαρυνομένους ὑπὸ τῆς τῶν Καρχηδονίων ἀγερωχίας, τότε δὲ πρῶτον καιρὸν λαβόντας εἰς τὸ φανερὰν ποιῆσαι τὴν αὑτῶν προαίρεσιν.", "st": "10.35"}, {"sp": "N", "t": "ὃ δὴ καὶ περὶ πολλοὺς ἤδη γέγονε. μεγάλου γὰρ ὄντος, ὡς πλεονάκις ἡμῖν εἴρηται, τοῦ κατορθοῦν ἐν πράγμασι καὶ περιγίνεσθαι τῶν ἐχθρῶν ἐν ταῖς ἐπιβολαῖς, πολλῷ μείζονος ἐμπειρίας προσδεῖται καὶ φυλακῆς τὸ καλῶς χρήσασθαι τοῖς κατορθώμασι· διὸ καὶ πολλαπλασίους ἂν εὕροι τις τοὺς ἐπὶ προτερημάτων γεγονότας τῶν καλῶς τοῖς προτερήμασι κεχρημένων. ὃ καὶ τότε περὶ τοὺς Καρχηδονίους συνέβη γενέσθαι. μετὰ γὰρ τὸ νικῆσαι μὲν τὰς Ῥωμαίων δυνάμεις, ἀποκτεῖναι δὲ τοὺς στρατηγοὺς ἀμφοτέρους, Πόπλιον καὶ Γνάϊον, ὑπολαβόντες ἀδήριτον αὐτοῖς ὑπάρχειν τὴν Ἰβηρίαν, ὑπερηφάνως ἐχρῶντο τοῖς κατὰ τὴν χώραν. τοιγαροῦν ἀντὶ συμμάχων καὶ φίλων πολεμίους ἔσχον τοὺς ὑποταττομένους. καὶ τοῦτ’ εἰκότως ἔπαθον· ἄλλως μὲν γὰρ ἐπειδήπερ ὑπέλαβον δεῖν κτᾶσθαι τὰς ἀρχάς, ἄλλως δὲ τηρεῖν, οὐκ ἔμαθον διότι κάλλιστα φυλάττουσι τὰς ὑπεροχὰς οἱ κάλλιστα διαμείναντες ἐπὶ τῶν αὐτῶν προαιρέσεων, αἷς ἐξ ἀρχῆς κατεκτήσαντο τὰς δυναστείας, καίτοι γε προφανοῦς ὄντος καὶ ἐπὶ πολλῶν ἤδη τεθεωρημένου διότι κτῶνται μὲν ἄνθρωποι τὰς εὐκαιρίας εὖ ποιοῦντες καὶ προτεινόμενοι τὴν ἀγαθὴν ἐλπίδα τοῖς πέλας, ἐπειδὰν δὲ τῶν ἐπιθυμουμένων τυχόντες κακῶς ποιῶσι καὶ δεσποτικῶς ἄρχωσι τῶν ὑποτεταγμένων, εἰκότως ἅμα ταῖς τῶν προεστώτων μεταβολαῖς συμμεταπίπτουσι καὶ τῶν ὑποταττομένων αἱ προαιρέσεις. ὃ καὶ τότε συνέβη τοῖς Καρχηδονίοις.", "st": "10.36"}, {"sp": "N", "t": "Ἀσδρούβας μὲν οὖν ἐν τοιαύταις περιστάσεσι πολλὰς καὶ ποικίλας ἐποιεῖτο περὶ τῶν ἐπιφερομένων πραγμάτων ἐννοίας. ἐλύπει μὲν γὰρ αὐτὸν ἡ περὶ τὸν Ἀνδοβάλην ἀπόστασις, ἐλύπει δὲ καὶ τὰ κατὰ τὴν ἀντιπαραγωγὴν καὶ τὴν ἀλλοτριότητα τὴν ὑπάρχουσαν αὐτῷ πρὸς τοὺς ἄλλους στρατηγούς· ἠγωνία δὲ καὶ τὴν Ποπλίου παρουσίαν. καὶ τὸ λοιπὸν ἤδη προσδοκῶν αὐτὸν ἥξειν μετὰ τῶν δυνάμεων, θεωρῶν δ’ αὑτὸν μὲν ἐγκαταλειπόμενον ὑπὸ τῶν Ἰβήρων, τοῖς δὲ Ῥωμαίοις πάντας ὁμοθυμαδὸν προσχωροῦντας, ἐπί τινας λογισμοὺς κατήντησε τοιούτους. προέθετο γὰρ διότι δεῖ παρεσκευασμένον τὰ δυνατὰ συμβαλεῖν πρὸς μάχην τοῖς ὑπεναντίοις, κἂν μὲν ἡ τύχη δῷ τὸ νικᾶν, βουλεύσασθαι μετὰ ταῦτα περὶ τῶν ἑξῆς ἀσφαλῶς· ἂν δ’ ἀντιπίπτῃ τὰ κατὰ τὴν μάχην, ποιεῖσθαι τὴν ἀποχώρησιν μετὰ τῶν διασῳζομένων ἐξ αὐτῆς εἰς Γαλατίαν, κἀκεῖθεν παραλαβόντα τῶν βαρβάρων ὡς πλείστους βοηθεῖν εἰς τὴν Ἰταλίαν καὶ κοινωνεῖν Ἀννίβᾳ τἀδελφῷ τῶν αὐτῶν ἐλπίδων. Ἀσδρούβας μὲν δὴ ταῦτα διανοηθεὶς πρὸς τούτοις ἦν· Πόπλιος δὲ προσδεξάμενος Γάιον τὸν Λαίλιον καὶ διακούσας τῶν παραγγελλομένων ὑπὸ τῆς συγκλήτου, προῇγε τὰς δυνάμεις ἀναλαβὼν ἐκ τῆς παραχειμασίας, ἀπαντώντων αὐτῷ κατὰ τὴν δίοδον τῶν Ἰβήρων, ἑτοίμως καὶ προθύμως συνεξορμώντων. οἱ δὲ περὶ τὸν Ἀνδοβάλην πάλαι μὲν διεπέμποντο πρὸς τὸν Πόπλιον, τότε δὲ πλησιάσαντος αὐτοῦ τοῖς τόποις ἧκον ὡς αὐτὸν ἐκ τῆς παρεμβολῆς ἅμα τοῖς φίλοις, καὶ συμμίξαντες ἀπελογίσαντο περὶ τῆς προγεγενημένης σφίσι φιλίας πρὸς Καρχηδονίους, ὁμοίως δὲ καὶ τὰς χρείας καὶ τὴν ὅλην πίστιν ἐνεφάνιζον, ἣν ἐτύγχανον ἐκείνοις παρεσχημένοι. μετὰ δὲ ταῦτα τὰς ἀδικίας ἐξηγοῦντο καὶ τὰς ὕβρεις τὰς ἐξ ἐκείνων ἀπηντημένας. διόπερ ἠξίουν τὸν Πόπλιον αὐτὸν κριτὴν γίνεσθαι τῶν λεγομένων, κἂν μὲν φανῶσιν ἀδίκως ἐγκαλοῦντες Καρχηδονίοις, σαφῶς γινώσκειν αὐτὸν ὡς οὐδὲ τὴν πρὸς Ῥωμαίους δύνανται τηρεῖν πίστιν· ἐὰν δὲ πολλὰς ἀδικίας ἀναλογιζόμενοι κατ’ ἀνάγκην ἀφιστῶνται τῆς εὐνοίας τῆς ἐκείνων, καλὰς ἐλπίδας ἔχειν διότι νῦν ἑλόμενοι τὰ Ῥωμαίων βεβαίως τηρήσουσι τὴν πρὸς αὐτοὺς εὔνοιαν.", "st": "10.37"}, {"sp": "N", "t": "καὶ πλείω πρὸς τοῦτο τὸ μέρος αὐτῶν διαλεχθέντων, ἐπεὶ κατέπαυσαν τὸν λόγον, μεταλαβὼν ὁ Πόπλιος καὶ τοῖς ὑπ’ ἐκείνων εἰρημένοις ἔφη πιστεύειν, μάλιστα δὲ γινώσκειν τὴν Καρχηδονίων ὕβριν ἔκ τε τῆς εἰς τοὺς ἄλλους Ἴβηρας καὶ μάλιστα τῆς εἰς τὰς ἐκείνων γυναῖκας καὶ θυγατέρας ἀσελγείας, ἃς αὐτὸς παρειληφὼς νῦν οὐχ ὁμήρων ἐχούσας διάθεσιν, ἀλλ’ αἰχμαλώτων καὶ δούλων, οὕτως τετηρηκέναι τὴν πίστιν ὡς οὐδ’ ἂν αὐτοὺς ἐκείνους τηρῆσαι πατέρας ὑπάρχοντας. τῶν δ’ ἀνθομολογησαμένων διότι παρακολουθοῦσι καὶ προσκυνησάντων αὐτὸν καὶ προσφωνησάντων βασιλέα πάντων, οἱ μὲν παρόντες ἐπεσημήναντο τὸ ῥηθέν, ὁ δὲ Πόπλιος ἐντραπεὶς θαρρεῖν αὐτοῖς παρῄνει· τεύξεσθαι γὰρ ἔφη σφᾶς ἁπάντων τῶν φιλανθρώπων ὑπὸ Ῥωμαίων. καὶ παραυτίκα μὲν ἐκ χειρὸς τὰς θυγατέρας ἀπέδωκε, τῇ δ’ ἐπαύριον ἐποιεῖτο τὰς συνθήκας πρὸς αὐτούς. ἦν δὲ τὸ συνέχον τῶν ὁμολογηθέντων ἀκολουθεῖν τοῖς Ῥωμαίων ἄρχουσι καὶ πείθεσθαι τοῖς ὑπὸ τούτων παραγγελλομένοις. γενομένων δὲ τούτων ἀναχωρήσαντες εἰς τὰς αὑτῶν παρεμβολὰς καὶ παραλαβόντες τὰς δυνάμεις, ἧκον πρὸς τὸν Πόπλιον, καὶ στρατοπεδεύσαντες ὁμοῦ τοῖς Ῥωμαίοις προῆγον ἐπὶ τὸν Ἀσδρούβαν. ὁ δὲ τῶν Καρχηδονίων στρατηγὸς ἐτύγχανε μὲν διατρίβων ἐν τοῖς περὶ Κασταλῶνα τόποις περὶ Βαίκυλα πόλιν οὐ μακρὰν τῶν ἀργυρείων μετάλλων· πυθόμενος δὲ τὴν παρουσίαν τῶν Ῥωμαίων μετεστρατοπέδευσε, καὶ λαβὼν ἐκ μὲν τῶν ὄπισθεν ποταμὸν ἀσφαλῆ, παρὰ δὲ τὴν κατὰ πρόσωπον πλευρὰν τοῦ χάρακος ἐπίπεδον τόπον, ὀφρὺν προβεβλημένην ἔχοντα καὶ βάθος ἱκανὸν πρὸς ἀσφάλειαν καὶ μῆκος πρὸς ἔκταξιν, ἔμενεν ἐπὶ τῶν ὑποκειμένων, προτιθέμενος ἐπὶ τὴν ὀφρὺν ἀεὶ τὰς ἐφεδρείας. ὁ δὲ Πόπλιος ἐγγίσας προθύμως μὲν εἶχε πρὸς τὸ διακινδυνεύειν, ἀπόρως δὲ διέκειτο, θεωρῶν τοὺς τόπους εὐφυεῖς ὄντας πρὸς τὴν τῶν ἐναντίων ἀσφάλειαν. οὐ μὴν ἀλλὰ προσανασχὼν δύ’ ἡμέρας καὶ διαγωνιάσας μὴ συνεπιγενομένων τῶν περὶ τὸν Μάγωνα καὶ τὸν τοῦ Γέσκωνος Ἀσδρούβαν πανταχόθεν αὐτὸν οἱ πολέμιοι περιστῶσιν, ἔκρινε παραβάλλεσθαι καὶ καταπειράζειν τῶν ὑπεναντίων.", "st": "10.38"}, {"sp": "N", "t": "τὴν μὲν οὖν ἄλλην δύναμιν ἑτοιμάσας πρὸς μάχην συνεῖχεν ἐν τῷ χάρακι, τοὺς δὲ γροσφομάχους καὶ τῶν πεζῶν τοὺς ἐπιλέκτους ἐξαφιεὶς ἐκέλευε προσβάλλειν πρὸς τὴν ὀφρὺν καὶ καταπειράζειν τῆς τῶν πολεμίων ἐφεδρείας. τῶν δὲ ποιούντων τὸ παραγγελθὲν εὐψύχως, τὰς μὲν ἀρχὰς ὁ τῶν Καρχηδονίων στρατηγὸς ἐκαραδόκει τὸ συμβαῖνον· θεωρῶν δὲ διὰ τὴν τόλμαν τῶν Ῥωμαίων τοὺς παρ’ αὑτῶν πιεζομένους καὶ κακῶς πάσχοντας, ἐξῆγε τὴν δύναμιν καὶ παρενέβαλε παρὰ τὴν ὀφρύν, πιστεύων τοῖς τόποις. κατὰ δὲ τὸν καιρὸν τοῦτον ὁ Πόπλιος τοὺς μὲν εὐζώνους ἅπαντας ἐπαφῆκε, συντάξας βοηθεῖν τοῖς προκινδυνεύουσι, τοὺς δὲ λοιποὺς ἑτοίμους ἔχων, τοὺς μὲν ἡμίσεις αὐτὸς ἔχων, περιελθὼν τὴν ὀφρὺν κατὰ τὸ λαιὸν τῶν ὑπεναντίων, προσέβαλλε τοῖς Καρχηδονίοις, τοὺς δ’ ἡμίσεις Λαιλίῳ δοὺς ὁμοίως παρήγγειλε τὴν ἔφοδον ἐπὶ τὰ δεξιὰ μέρη τῶν πολεμίων. οὗ συμβαίνοντος ὁ μὲν Ἀσδρούβας ἀκμὴν ἐκ τῆς στρατοπεδείας ἐξῆγε τὴν δύναμιν· τὸν γὰρ πρὸ τούτου χρόνον ἐπέμενε πιστεύων τοῖς τόποις καὶ πεπεισμένος μηδέποτε τολμήσειν τοὺς πολεμίους ἐγχειρεῖν αὐτοῖς· διὸ παρὰ τὴν προσδοκίαν γεγενημένης τῆς ἐπιθέσεως καθυστέρει τῆς ἐκτάξεως. οἱ δὲ Ῥωμαῖοι κατὰ κέρας ποιούμενοι τὸν κίνδυνον, οὐδέπω τῶν πολεμίων κατειληφότων τοὺς ἐπὶ τῶν κεράτων τόπους, οὐ μόνον ἐπέβησαν ἀσφαλῶς ἐπὶ τὴν ὀφρύν, ἀλλὰ καὶ προσάγοντες ἔτι παρεμβαλλόντων καὶ κινουμένων τῶν ὑπεναντίων τοὺς μὲν αὐτῶν προσπίπτοντας ἐκ πλαγίων ἐφόνευον, τοὺς δὲ παρεμβάλλοντας ἐξ ἐπιστροφῆς φεύγειν ἠνάγκαζον. Ἀσδρούβας δὲ κατὰ τοὺς ἐξ ἀρχῆς διαλογισμούς, θεωρῶν κλινούσας καὶ διατετραμμένας τὰς αὑτοῦ δυνάμεις, τὸ μὲν ψυχομαχεῖν μέχρι τῆς ἐσχάτης ἐλπίδος ἀπεδοκίμαζε, λαβὼν δὲ τά τε χρήματα καὶ τὰ θηρία, καὶ τῶν φευγόντων ὅσους ἠδύνατο πλείστους ἐπισπασάμενος, ἐποιεῖτο τὴν ἀναχώρησιν παρὰ τὸν Τάγον ποταμὸν ὡς ἐπὶ τὰς Πυρήνης ὑπερβολὰς καὶ τοὺς ταύτῃ κατοικοῦντας Γαλάτας. Πόπλιος δὲ τὸ μὲν ἐκ ποδὸς ἕπεσθαι τοῖς περὶ τὸν Ἀσδρούβαν οὐχ ἡγεῖτο συμφέρειν τῷ δεδιέναι τῶν ἄλλων στρατηγῶν τὴν ἔφοδον, τὸν δὲ χάρακα τῶν ὑπεναντίων ἐφῆκε τοῖς αὑτοῦ στρατιώταις διαρπάζειν.", "st": "10.39"}, {"sp": "N", "t": "εἰς δὲ τὴν ἐπαύριον συναθροίσας τὸ τῶν αἰχμαλώτων πλῆθος, ὧν ἦσαν πεζοὶ μὲν εἰς μυρίους, ἱππεῖς δὲ πλείους δισχιλίων, ἐγίνετο περὶ τὴν τούτων οἰκονομίαν. τῶν δ’ Ἰβήρων ὅσοι κατὰ τοὺς προειρημένους τόπους Καρχηδονίοις τότε συνεμάχουν, ἧκον ἐγχειρίζοντες σφᾶς αὐτοὺς εἰς τὴν Ῥωμαίων πίστιν, κατὰ δὲ τὰς ἐντεύξεις βασιλέα προσεφώνουν τὸν Πόπλιον. πρῶτον μὲν οὖν ἐποίησε τοῦτο καὶ προσεκύνησε πρῶτος Ἐδεκών, μετὰ δὲ τοῦτον οἱ περὶ τὸν Ἀνδοβάλην. τότε μὲν οὖν ἀνεπιστάτως αὐτὸν παρέδραμε τὸ ῥηθέν· μετὰ δὲ τὴν μάχην ἁπάντων βασιλέα προσφωνούντων, εἰς ἐπίστασιν ἤγαγε τὸν Πόπλιον τὸ γινόμενον. διὸ καὶ συναθροίσας τοὺς Ἴβηρας βασιλικὸς μὲν ἔφη βούλεσθαι καὶ λέγεσθαι παρὰ πᾶσι καὶ ταῖς ἀληθείαις ὑπάρχειν, βασιλεύς γε μὴν οὔτ’ εἶναι θέλειν οὔτε λέγεσθαι παρ’ οὐδενί. ταῦτα δ’ εἰπὼν παρήγγειλε στρατηγὸν αὑτὸν προσφωνεῖν. ἴσως μὲν οὖν καὶ τότε δικαίως ἄν τις ἐπεσημήνατο τὴν μεγαλοψυχίαν τἀνδρός, ᾗ κομιδῇ νέος ὢν καὶ τῆς τύχης αὐτῷ συνεκδραμούσης ἐπὶ τοσοῦτον ὥστε πάντας τοὺς ὑποταττομένους ἐξ αὑτῶν ἐπί τε ταύτην κατενεχθῆναι τὴν διάληψιν καὶ τὴν ὀνομασίαν, ὅμως ἐν ἑαυτῷ διέμεινε καὶ παρῃτεῖτο τὴν τοιαύτην ὁρμὴν καὶ φαντασίαν. πολὺ δὲ μᾶλλον ἄν τις θαυμάσειε τὴν ὑπερβολὴν τῆς περὶ τὸν ἄνδρα μεγαλοψυχίας, βλέψας εἰς τοὺς ἐσχάτους τοῦ βίου καιρούς, ἡνίκα πρὸς τοῖς κατὰ τὴν Ἰβηρίαν ἔργοις κατεστρέψατο μὲν Καρχηδονίους, καὶ τὰ πλεῖστα καὶ κάλλιστα μέρη τῆς Λιβύης ἀπὸ τῶν Φιλαίνου βωμῶν ἕως Ἡρακλείων στηλῶν ὑπὸ τὴν τῆς πατρίδος ἐξουσίαν ἤγαγε, κατεστρέψατο δὲ τὴν Ἀσίαν καὶ τοὺς τῆς Συρίας βασιλεῖς, καὶ τὸ κάλλιστον καὶ μέγιστον μέρος τῆς οἰκουμένης ὑπήκοον ἐποίησε Ῥωμαίοις, ἔλαβε δὲ καιροὺς εἰς τὸ περιποιήσασθαι δυναστείαν βασιλικὴν ἐν οἷς ἐπιβάλοιτο καὶ βουληθείη τόποις τῆς οἰκουμένης. ταῦτα γὰρ οὐ μόνον ἀνθρωπίνην φύσιν, ἀλλὰ καὶ θειοτέραν, εἰ θέμις εἰπεῖν, ὑπερφρονεῖν ἂν ἐποίησεν. Πόπλιος δὲ τοσοῦτον ὑπερέθετο μεγαλοψυχίᾳ τοὺς ἄλλους ἀνθρώπους ὡς οὗ μεῖζον ἀγαθὸν εὔξασθαί τις τοῖς θεοῖς οὐ τολμήσειε, λέγω δὲ βασιλείας, τοῦτ’ ἐκεῖνος πολλάκις ὑπὸ τῆς τύχης αὐτῷ δεδομένον ἀπηξίωσε, καὶ περὶ πλείονος ἐποιήσατο τὴν πατρίδα καὶ τὴν ταύτης πίστιν τῆς περιβλέπτου καὶ μακαριστῆς βασιλείας. πλὴν τότε γε διαλέξας ἐκ τῶν αἰχμαλώτων τοὺς Ἴβηρας, τούτους μὲν ἀπέλυσε χωρὶς λύτρων πάντας εἰς τὰς ἑαυτῶν πατρίδας, τῶν δ’ ἵππων τριακοσίους κελεύσας ἐκλέξαι τοῖς περὶ τὸν Ἀνδοβάλην τοὺς λοιποὺς διέδωκε τοῖς ἀνίπποις. καὶ τὸ λοιπὸν ἤδη μεταλαβὼν τὴν τῶν Καρχηδονίων στρατοπεδείαν διὰ τὴν τῶν τόπων εὐφυΐαν, αὐτὸς μὲν ἔμενε καραδοκῶν τοὺς καταλειπομένους τῶν Καρχηδονίων στρατηγούς, ἐπὶ δὲ τὰς ὑπερβολὰς τῶν Πυρηναίων ὀρέων ἐξαπέστειλε τοὺς τηρήσοντας τὸν Ἀσδρούβαν. μετὰ δὲ ταῦτα, τῆς ὥρας ἤδη συναπτούσης, ἀνεχώρησε μετὰ τῆς δυνάμεως εἰς Ταρράκων’, ἐν τούτοις τοῖς τόποις ποιεῖσθαι τὴν παραχειμασίαν.", "st": "10.40"}, {"sp": "N", "t": "οἱ μὲν Αἰτωλοί, προσφάτως ἐπηρμένοι ταῖς ἐλπίσιν ἐπὶ τῇ Ῥωμαίων καὶ τῇ τοῦ βασιλέως Ἀττάλου παρουσίᾳ, πάντας ἐξέπληττον καὶ πᾶσιν ἐπέκειντο κατὰ γῆν, οἱ δὲ περὶ τὸν Ἄτταλον καὶ Πόπλιον κατὰ θάλατταν. διόπερ ἧκον Ἀχαιοὶ μὲν παρακαλοῦντες τὸν Φίλιππον βοηθεῖν· οὐ γὰρ μόνον τοὺς Αἰτωλοὺς ἠγωνίων, ἀλλὰ καὶ τὸν Μαχανίδαν διὰ τὸ προκαθῆσθαι μετὰ τῆς δυνάμεως ἐπὶ τοῖς τῶν Ἀργείων ὅροις. Βοιωτοὶ δὲ δεδιότες τὸν στόλον τῶν ὑπεναντίων, ἡγεμόνα καὶ βοήθειαν ᾔτουν. φιλοπονώτατά γε μὴν οἱ τὴν Εὔβοιαν κατοικοῦντες ἠξίουν ἔχειν τινὰ πρόνοιαν τῶν πολεμίων. παραπλήσια δ’ Ἀκαρνᾶνες παρεκάλουν. ἦν δὲ καὶ παρ’ Ἠπειρωτῶν πρεσβεία. προσήγγελτο δὲ καὶ Σκερδιλαΐδαν καὶ Πλευρᾶτον ἐξάγειν τὰς δυνάμεις· ἔτι δὲ τοὺς προσοροῦντας τῇ Μακεδονίᾳ Θρᾷκας, καὶ μάλιστα τοὺς Μαιδούς, ἐπιβολὰς ἔχειν ὡς ἐμβαλοῦντας ἐπὶ Μακεδονίαν, ἐὰν βραχύ τι μόνον ὁ βασιλεὺς τῆς οἰκείας ἀποσπασθῇ. προκατελάμβανον δὲ καὶ τὰ περὶ Θερμοπύλας στενὰ τάφροις καὶ χάρακι καὶ φυλακαῖς βαρείαις Αἰτωλοί, πεπεισμένοι συγκλείειν τὸν Φίλιππον καὶ καθόλου κωλύειν παραβοηθεῖν τοῖς ἐντὸς Πυλῶν συμμάχοις. δοκεῖ δέ μοι τὰς τοιαύτας περιστάσεις εὐλόγως ἄν τις ἐπισημήνασθαι καὶ συνεφιστάνειν τοὺς ἀναγινώσκοντας, ἐν αἷς πεῖρα καὶ βάσανος ἀληθινὴ γίνεται κατὰ τάς τε ψυχικὰς ὁρμὰς καὶ τὰς σωματικὰς δυνάμεις τῶν ἡγεμόνων. καθάπερ γὰρ ἐν ταῖς κυνηγεσίαις τὰ ζῷα τότε διάδηλα γίνεται κατὰ τὴν ἀλκὴν καὶ τὴν δύναμιν, ὅταν τὸ δεινὸν αὐτὰ περιστῇ πανταχόθεν, τὸν αὐτὸν τρόπον συμβαίνει καὶ ἐπὶ τῶν ἡγουμένων. ὃ δὴ τότε μάλιστα συνιδεῖν ἦν γινόμενον ὑπὸ τοῦ Φιλίππου· τὰς μὲν γὰρ πρεσβείας ἀπέλυσε πάσας, ἑκάστοις τὰ δυνατὰ ποιήσειν ἐπαγγειλάμενος, τῷ δὲ πολέμῳ πανταχόθεν ἐπεῖχε, καραδοκῶν πῇ καὶ πρὸς τίνα πρῶτον δεήσει ποιεῖσθαι τὴν ὁρμήν.", "st": "10.41"}, {"sp": "N", "t": "προσπεσόντος δ’ αὐτῷ κατὰ τὸν καιρὸν τοῦτον τοὺς περὶ τὸν Ἄτταλον διάραντας καὶ προσορμήσαντας τῇ Πεπαρήθῳ κατεσχηκέναι τὴν χώραν, τούτοις μὲν ἐξαπέστειλε τοὺς παραφυλάξοντας τὴν πόλιν, εἰς δὲ Φωκέας καὶ τοὺς κατὰ τὴν Βοιωτίαν τόπους Πολυφάνταν ἐξέπεμψε μετὰ συμμέτρου δυνάμεως, εἰς δὲ Χαλκίδα καὶ τὴν ἄλλην Εὔβοιαν Μένιππον, ἔχοντα πελταστὰς χιλίους, Ἀγριᾶνας πεντακοσίους. αὐτὸς δὲ προῆγε ποιούμενος τὴν πορείαν εἰς Σκοτοῦσαν, παραπλησίως δὲ καὶ τοῖς Μακεδόσιν εἰς ταύτην τὴν πόλιν παρήγγειλεν ἀπαντᾶν. πυθόμενος δὲ τοὺς περὶ τὸν Ἄτταλον εἰς Νίκαιαν καταπεπλευκέναι, τῶν δ’ Αἰτωλῶν τοὺς ἄρχοντας εἰς Ἡράκλειαν ἁθροίζεσθαι χάριν τοῦ κοινολογηθῆναι πρὸς ἀλλήλους ὑπὲρ τῶν ἐνεστώτων, ἀναλαβὼν τὴν δύναμιν ἐκ τῆς Σκοτούσης ὥρμησε σπεύδων καταταχῆσαι καὶ πτοήσας διασῦραι τὴν σύνοδον αὐτῶν. τοῦ μὲν οὖν συλλόγου καθυστέρει, τὸν δὲ σῖτον φθείρας καὶ παρελόμενος τῶν περὶ τὸν Αἰνιᾶνα κόλπον κατοικούντων ἐπανῆλθε. καὶ τὴν μὲν δύναμιν ἐν τῇ Σκοτούσῃ πάλιν ἀπέλειπε, μετὰ δὲ τῶν εὐζώνων καὶ τῆς βασιλικῆς ἴλης εἰς Δημητριάδα καταλύσας ἔμενε, καραδοκῶν τὰς τῶν ἐναντίων ἐπιβολάς. ἵνα δὲ μηδὲν αὐτὸν λανθάνῃ τῶν πραττομένων, διεπέμψατο πρὸς Πεπαρηθίους καὶ πρὸς τοὺς ἐπὶ τῆς Φωκίδος, ὁμοίως δὲ καὶ πρὸς τοὺς ἐπὶ τῆς Εὐβοίας, καὶ παρήγγειλε διασαφεῖν αὑτῷ πάντα τὰ γινόμενα διὰ τῶν πυρσῶν ἐπὶ τὸ Τίσαιον. τοῦτο δ’ ἐστὶ τῆς Θετταλίας ὄρος, εὐφυῶς κείμενον πρὸς τὰς τῶν προειρημένων τόπων περιφάσεις.", "st": "10.42"}, {"sp": "N", "t": "τοῦ δὲ κατὰ τὰς πυρσείας γένους, μεγίστας δὴ παρεχομένου χρείας ἐν τοῖς πολεμικοῖς, ἀνεργάστου πρότερον ὑπάρχοντος, χρήσιμον εἶναί μοι δοκεῖ τὸ μὴ παραδραμεῖν, ἀλλὰ ποιήσασθαι περὶ αὐτοῦ τὴν ἁρμόζουσαν μνήμην. ὅτι μὲν οὖν ὁ καιρὸς ἐν πᾶσι μεγάλην ἔχει μερίδα πρὸς τὰς ἐπιβολάς, μεγίστην δ’ ἐν τοῖς πολεμικοῖς, παντὶ δῆλον· τῶν δὲ πρὸς τοῦτο συναγωνισμάτων πλείστην ἔχουσι δύναμιν οἱ πυρσοί. ἄρτι γὰρ τὰ μὲν γέγονε, τινὰ δ’ ἀκμὴν ἐνεργεῖται καὶ δυνατόν ἐστι γινώσκειν, ᾧ μέλει, ποτὲ μὲν ἡμερῶν τριῶν ἢ τεττάρων ὁδὸν ἀπέχοντι, ποτὲ δὲ καὶ πλειόνων. ὥστ’ ἀεὶ τοῖς δεομένοις πράγμασιν ἐπικουρίας παράδοξον γίνεσθαι τὴν βοήθειαν διὰ τῆς τῶν πυρσῶν ἀπαγγελίας. τὸν μὲν οὖν πρὸ τούτου χρόνον ἁπλῆς γινομένης τῆς πυρσείας κατὰ τὸ πλεῖστον αὐτὴν ἀνωφελῆ συνέβαινε γίνεσθαι τοῖς χρωμένοις. διὰ γὰρ συνθημάτων ὡρισμένων ἔδει τὴν χρείαν συντελεῖν· τῶν δὲ πραγμάτων ἀορίστων ὑπαρχόντων τὰ πλεῖστα διέφυγε τὴν τῶν πυρσῶν χρείαν, οἷον ἐπ’ αὐτῶν τῶν νῦν εἰρημένων. ὅτι μὲν οὖν εἰς Ὠρεὸν καὶ Πεπάρηθον ἢ Χαλκίδα πάρεστι στόλος, δυνατὸν ἦν διασαφεῖν τοῖς περὶ τούτου συνθεμένοις· ὅτι δὲ μεταβάλλονταί τινες τῶν πολιτῶν ἢ προδιδόασιν, ἢ φόνος ἐν τῇ πόλει γέγονεν, ἤ τι τῶν τοιούτων, ἃ δὴ συμβαίνει μὲν πολλάκις, πρόληψιν δ’ ἔχειν πάντων ἀδύνατον — μάλιστα δὲ τὰ παραδόξως γινόμενα τῆς ἐκ τοῦ καιροῦ συμβουλίας καὶ ἐπικουρίας προσδεῖται — τὰ τοιαῦτα πάντα διέφυγε τὴν τῶν πυρσῶν χρείαν. περὶ ὧν γὰρ οὐκ ἐνεδέχετο προνοηθῆναι, περὶ τούτων οὐδὲ σύνθημα ποιήσασθαι δυνατόν.", "st": "10.43"}, {"sp": "N", "t": "Αἰνείας δὲ βουληθεὶς διορθώσασθαι τὴν τοιαύτην ἀπορίαν, ὁ τὰ περὶ τῶν Στρατηγικῶν ὑπομνήματα συντεταγμένος, βραχὺ μέν τι προεβίβασε, τοῦ γε μὴν δέοντος ἀκμὴν πάμπολυ τὸ κατὰ τὴν ἐπίνοιαν ἀπελείφθη. γνοίη δ’ ἄν τις ἐκ τούτων. φησὶ γὰρ δεῖν τοὺς μέλλοντας ἀλλήλοις διὰ τῶν πυρσῶν δηλοῦν τὸ κατεπεῖγον ἀγγεῖα κατασκευάσαι κεραμεᾶ, κατά τε τὸ πλάτος καὶ κατὰ τὸ βάθος ἰσομεγέθη πρὸς ἀκρίβειαν· εἶναι δὲ μάλιστα τὸ μὲν βάθος τριῶν πηχῶν, τὸ δὲ πλάτος πήχεος. εἶτα παρασκευάσαι φελλοὺς βραχὺ κατὰ πλάτος ἐνδεεῖς τῶν στομάτων, ἐν δὲ τούτοις μέσοις ἐμπεπηγέναι βακτηρίας διῃρημένας εἰς ἴσα μέρη τριδάκτυλα, καθ’ ἕκαστον δὲ μέρος εἶναι περιγραφὴν εὔσημον. ἐν ἑκάστῳ δὲ μέρει γεγράφθαι τὰ προφανέστατα καὶ καθολικώτατα τῶν ἐν τοῖς πολεμικοῖς συμβαινόντων, οἷον εὐθέως ἐν τῷ πρώτῳ, διότι \" πάρεισιν ἱππεῖς εἰς τὴν χώραν,\" ἐν δὲ τῷ δευτέρῳ διότι \"πεζοὶ βαρεῖς,\" ἐν δὲ τῷ τρίτῳ \"ψιλοί,\" τούτων δ’ ἑξῆς \" πεζοὶ μεθ’ ἱππέων,\" εἶτα \"πλοῖα,\" μετὰ δὲ ταῦτα \"σῖτος,\" καὶ κατὰ τὸ συνεχὲς οὕτω, μέχρις ἂν ἐν πάσαις γραφῇ ταῖς χώραις τὰ μάλιστ’ ἂν ἐκ τῶν εὐλόγων προνοίας τυγχάνοντα καὶ συμβαίνοντα κατὰ τοὺς ἐνεστῶτας καιροὺς ἐκ τῶν πολεμικῶν. τούτων δὲ γενομένων ἀμφότερα κελεύει τρῆσαι τὰ ἀγγεῖα πρὸς ἀκρίβειαν, ὥστε τοὺς αὐλίσκους ἴσους εἶναι καὶ κατ’ ἴσον ἀπορρεῖν· εἶτα πληρώσαντας ὕδατος ἐπιθεῖναι τοὺς φελλοὺς ἔχοντας τὰς βακτηρίας, κἄπειτα τοὺς αὐλίσκους ἀφεῖναι ῥεῖν ἅμα. τούτου δὲ συμβαίνοντος δῆλον ὡς ἀνάγκη πάντων ἴσων καὶ ὁμοίων ὄντων, καθ’ ὅσον ἂν ἀπορρέῃ τὸ ὑγρόν, κατὰ τοσοῦτον τοὺς φελλοὺς καταβαίνειν καὶ τὰς βακτηρίας κρύπτεσθαι κατὰ τῶν ἀγγείων. ὅταν δὲ τὰ προειρημένα γένηται κατὰ τὸν χειρισμὸν ἰσοταχῆ καὶ σύμφωνα, τότε κομίσαντας ἐπὶ τοὺς τόπους, ἐν οἷς ἑκάτεροι μέλλουσι συντηρεῖν τὰς πυρσείας, ἑκάτερον θεῖναι τῶν ἀγγείων. εἶτ’ ἐπὰν ἐμπέσῃ τι τῶν ἐν τῇ βακτηρίᾳ γεγραμμένων, πυρσὸν ἆραι κελεύει, καὶ μένειν, ἕως ἂν ἀνταίρωσιν οἱ συντεταγμένοι· γενομένων δὲ φανερῶν ἀμφοτέρων ἅμα τῶν πυρσῶν καθελεῖν. εἶτ’ εὐθέως ἀφεῖναι τοὺς αὐλίσκους ῥεῖν. ὅταν δὲ καταβαίνοντος τοῦ φελλοῦ καὶ τῆς βακτηρίας ἔλθῃ τῶν γεγραμμένων ὃ βούλει δηλοῦν κατὰ τὸ χεῖλος τοῦ τεύχους, ἆραι κελεύει τὸν πυρσόν· τοὺς δ’ ἑτέρους ἐπιλαβεῖν εὐθέως τὸν αὐλίσκον, καὶ σκοπεῖν τί κατὰ τὸ χεῖλός ἐστι τῶν ἐν τῇ βακτηρίᾳ γεγραμμένων· ἔσται δὲ τοῦτο τὸ δηλούμενον πάντων ἰσοταχῶς παρ’ ἀμφοτέροις κινουμένων.", "st": "10.44"}, {"sp": "N", "t": "ταῦτα δὲ βραχὺ μέν τι τῆς διὰ τῶν συνθημάτων πυρσείας ἐξήλλαχεν, ἀκμὴν δ’ ἐστὶν ἀόριστα. δῆλον γὰρ [ἔσται] ὡς οὔτε προϊδέσθαι τὰ μέλλοντα πάντα δυνατὸν οὔτε προϊδόμενον εἰς τὴν βακτηρίαν γράψαι· λοιπὸν ὁπόταν ἐκ τῶν καιρῶν ἀνυπονόητά τινα συμβαίνῃ, φανερὸν ὡς οὐ δύναται δηλοῦσθαι κατὰ ταύτην τὴν ἐπίνοιαν. καὶ μὴν οὐδ’ αὐτῶν τῶν ἐν τῇ βακτηρίᾳ γεγραμμένων οὐδέν ἐστιν ὡρισμένον. πόσοι γὰρ ἥκουσιν ἱππεῖς ἢ πόσοι πεζοὶ καὶ ποῦ τῆς χώρας καὶ πόσαι νῆες καὶ πόσος σῖτος, οὐχ οἷόν τε διασαφῆσαι· περὶ γὰρ ὧν ἀδύνατον γνῶναι πρὶν ἢ γενέσθαι, περὶ τούτων οὐδὲ συνθέσθαι πρὸ τοῦ δυνατόν. τὸ δὲ συνέχον ἐστὶ τοῦτο· πῶς γὰρ ἄν τις βουλεύσαιτο περὶ τοῦ βοηθεῖν μὴ γινώσκων πόσοι πάρεισι τῶν πολεμίων ἢ ποῦ; πῶς δὲ θαρρήσαι πάλιν ἢ τοὐναντίον ἢ καθόλου διανοηθείη τι μὴ συνεὶς πόσαι νῆες ἢ πόσος σῖτος ἥκει παρὰ τῶν συμμάχων; ὁ δὲ τελευταῖος τρόπος, ἐπινοηθεὶς διὰ Κλεοξένου καὶ Δημοκλείτου, τυχὼν δὲ τῆς ἐξεργασίας δι’ ἡμῶν, πάντη πάντως μέν ἐστιν ὡρισμένος καὶ πᾶν τὸ κατεπεῖγον δυνάμενος ἀκριβῶς διασαφεῖν, κατὰ δὲ τὸν χειρισμὸν ἐπιμελείας δεῖ καὶ παρατηρήσεως ἀκριβεστέρας. ἔστι δὲ τοιοῦτος. τὸ τῶν στοιχείων πλῆθος ἑξῆς δεῖ λαμβάνοντας διελεῖν εἰς πέντε μέρη κατὰ πέντε γράμματα. λείψει δὲ τὸ τελευταῖον ἑνὶ στοιχείῳ· τοῦτο δ’ οὐ βλάπτει πρὸς τὴν χρείαν. μετὰ δὲ ταῦτα πλατεῖα παρεσκευάσθαι πέντε τοὺς μέλλοντας ἀποδιδόναι τὴν πυρσείαν ἀλλήλοις ἑκατέρους καὶ γράψαι τῶν μερῶν ἑξῆς εἰς ἕκαστον πλατεῖον, κἄπειτα συνθέσθαι πρὸς αὑτοὺς διότι τοὺς μὲν πρώτους ἀρεῖ πυρσοὺς ὁ μέλλων σημαίνειν ἅμα καὶ δύο καὶ μενεῖ μέχρις ἂν ὁ ἕτερος ἀνταίρῃ. τοῦτο δ’ ἔσται χάριν τοῦ διὰ ταύτης τῆς πυρσείας ἑαυτοῖς ἀνθομολογήσασθαι διότι προσέχουσι. καθαιρεθέντων δὲ τούτων λοιπὸν ὁ σημαίνων ἀρεῖ μὲν τοὺς πρώτους ἐκ τῶν εὐωνύμων, διασαφῶν τὸ πλατεῖον ποῖον δεήσει σκοπεῖν, οἷον ἐὰν μὲν τὸ πρῶτον, ἕν’, ἂν δὲ τὸ δεύτερον, δύο, καὶ κατὰ λόγον οὕτω· τοὺς δὲ δευτέρους ἐκ τῶν δεξιῶν κατὰ τὸν αὐτὸν λόγον, ποῖον δεήσει γράμμα τῶν ἐκ τοῦ πλατείου γράφειν αὖ τὸν ἀποδεχόμενον τὴν πυρσείαν.", "st": "10.45"}, {"sp": "N", "t": "ὅταν δὲ ταῦτα συνθέμενοι χωρισθῶσιν, ἑκάτερον ἐπὶ τοῦ τόπου δεήσει πρῶτον μὲν διόπτραν ἔχειν δύ’ αὐλίσκους ἔχουσαν, ὥστε τοῦ μέλλοντος ἀντιπυρσεύειν τῷ μὲν τὸν δεξιὸν τόπον, τῷ δὲ τὸν εὐώνυμον δύνασθαι θεωρεῖν. παρὰ δὲ τὴν διόπτραν ἑξῆς ὀρθὰ δεῖ τὰ πλατεῖα πεπηγέναι, παραπεφράχθαι δὲ καὶ τὸν δεξιὸν καὶ τὸν εὐώνυμον τόπον ἐπὶ δέκα πόδας, τὸ δὲ βάθος ὡς ἀνδρόμηκες, εἰς τὸ τοὺς πυρσοὺς αἰρομένους μὲν παρὰ ταῦτα τὴν φάσιν ἀκριβῆ ποιεῖν, καθαιρουμένους δὲ τὴν κρύψιν. τούτων δ’ ἑτοιμασθέντων παρ’ ἀμφοτέροις, ὅταν βούλῃ δηλῶσαι λόγου χάριν διότι \"τῶν στρατιωτῶν τινες εἰς ἑκατὸν ἀποκεχωρήκασι πρὸς τοὺς ὑπεναντίους,\" πρῶτον δεῖ διαλέξαι τῶν λέξεων, ὅσαι δι’ ἐλαχίστων γραμμάτων δύνανται ταὐτὸ δηλοῦν, οἷον ἀντὶ τοῦ προειρημένου \"Κρῆτες ἑκατὸν ἀφ’ ἡμῶν ηὐτομόλησαν.\" νῦν γὰρ τὰ μὲν γράμματ’ ἐστὶν ἐλάττω τῶν ἡμίσεων, διασαφεῖται δὲ ταὐτόν. τούτου δὲ γραφέντος εἰς πινάκιον, οὕτω δηλωθήσεται τοῖς πυρσοῖς. πρῶτον δ’ ἐστὶ γράμμα τὸ κάππα· τοῦτο δ’ ἐστὶν ἐν τῇ δευτέρᾳ μερίδι καὶ τῷ δευτέρῳ πλατείῳ. δεήσει δὲ καὶ πυρσοὺς ἐκ τῶν εὐωνύμων δύ’ αἴρειν, ὥστε τὸν ἀποδεχόμενον γινώσκειν ὅτι δεῖ τὸ δεύτερον πλατεῖον ἐπισκοπεῖν. εἶτ’ ἐκ τῶν δεξιῶν ἀρεῖ πέντε, διασαφῶν ὅτι κάππα· τοῦτο γὰρ πέμπτον ἐστὶ τῆς δευτέρας μερίδος, ὃ δεήσει γράφειν εἰς τὸ πινάκιον τὸν ἀποδεχόμενον τοὺς πυρσούς. εἶτα τέτταρας ἐκ τῶν εὐωνύμων, ἐπεὶ τὸ ῥῶ τῆς τετάρτης ἐστὶ μερίδος. εἶτα δύο πάλιν ἐκ τῶν δεξιῶν· δεύτερον γάρ ἐστι τῆς τετάρτης. ἐξ οὗ τὸ ῥῶ γράφει [ὁ δεχόμενος τοὺς πυρσούς]· καὶ τὰ λοιπὰ τὸν αὐτὸν τρόπον. προδηλοῦται μὲν οὖν πᾶν τὸ προσπῖπτον ὡρισμένως κατὰ ταύτην τὴν ἐπίνοιαν,", "st": "10.46"}, {"sp": "N", "t": "πολλοὶ δὲ γίνονθ’ οἱ πυρσοὶ διὰ τὸ δεῖν ὑπὲρ ἑκάστου γράμματος διττὰς ποιεῖσθαι τὰς πυρσείας. οὐ μὴν ἀλλ’ ἐάν τις εὐτρεπῆ ποιήσῃ τὰ πρὸς τὸ πρᾶγμα, δύναται γίνεσθαι τὸ δέον. καθ’ ἑκατέραν δὲ τὴν ἐπίνοιαν προμελετᾶν δεῖ τοὺς χειρίζοντας, ἵνα τῆς χρείας γινομένης ἀδιαπτώτως δύνωνται διασαφεῖν ἀλλήλοις. πηλίκην δὲ συμβαίνει φαίνεσθαι τὴν διαφορὰν ἐπὶ τῶν αὐτῶν πραγμάτων πρῶτον λεγομένων καὶ πάλιν κατὰ συνήθειαν γινομένων, ἐκ πολλῶν εὐχερὲς τῷ βουλομένῳ καταμαθεῖν. πολλὰ γὰρ οὐ μόνον τῶν δυσχερῶν, ἀλλὰ καὶ τῶν ἀδυνάτων εἶναι δοκούντων κατὰ τὰς ἀρχάς, μετὰ ταῦτα χρόνου καὶ συνηθείας τυχόντα ῥᾷστα πάντων ἐπιτελεῖται. τοῦ δὲ τοιούτου λόγου παραδείγματα μὲν πολλὰ καὶ ἕτερα πρὸς πίστιν, ἐναργέστατον δὲ τὸ γινόμενον ἐπὶ τῆς ἀναγνώσεως. ἐπὶ γὰρ ἐκείνης, εἴ τις παραστησάμενος ἄνθρωπον ἄπειρον μὲν καὶ ἀσυνήθη γραμματικῆς, τἄλλα δ’ ἀγχίνουν, κἄπειτα παιδάριον ἕξιν ἔχον παραστήσας καὶ δοὺς βυβλίον κελεύοι λέγειν τὰ γεγραμμένα, δῆλον ὡς οὐκ ἂν δύναιτο πιστεῦσαι διότι δεῖ πρῶτον ἐπὶ τὰς ὄψεις τὰς ἑνὸς ἑκάστου τῶν γραμμάτων ἐπιστῆσαι τὸν ἀναγινώσκοντα, δεύτερον ἐπὶ τὰς δυνάμεις, τρίτον ἐπὶ τὰς πρὸς ἄλληλα συμπλοκάς, ὧν ἕκαστον ποσοῦ χρόνου τινὸς δεῖται. διόπερ ὅταν ἀνεπιστάτως θεωρῇ τὸ παιδάριον ὑπὸ τὴν ἀναπνοὴν ἑπτὰ καὶ πέντε στίχους συνεῖρον, οὐκ ἂν εὐχερῶς δύναιτο πιστεῦσαι διότι πρότερον οὗτος οὐκ ἀνέγνωκε τὸ βυβλίον· εἰ δὲ καὶ τὴν ὑπόκρισιν καὶ τὰς διαιρέσεις, ἔτι δὲ δασύτητας καὶ ψιλότητας δύναιτο συσσῴζειν, οὐδὲ τελέως. διόπερ οὐκ ἀποστατέον οὐδενὸς τῶν χρησίμων διὰ τὰς προφαινομένας δυσχερείας, προσακτέον δὲ τὴν ἕξιν, ᾗ πάντα τὰ καλὰ γίνεται θηρατὰ τοῖς ἀνθρώποις, ἄλλως τε καὶ περὶ τῶν τοιούτων, ἐν οἷς πολλάκις κεῖται τὸ συνέχον τῆς σωτηρίας. ταῦτα μὲν οὖν κατὰ τὴν ἐξ ἀρχῆς ἐπαγγελίαν προήχθημεν εἰπεῖν. ἔφαμεν γὰρ πάντα τὰ θεωρήματα καθ’ ἡμᾶς ἐπὶ τοσοῦτον εἰληφέναι τὰς προκοπάς, ὥστε τῶν πλείστων τρόπον τινὰ μεθοδικὰς εἶναι τὰς ἐπιστήμας. διὸ καὶ τοῦτο γίνεται τῆς δεόντως ἱστορίας συντεταγμένης ὠφελιμώτατον.", "st": "10.47"}, {"sp": "N", "t": "οἱ δ’ Ἀπασιάκαι κατοικοῦσι μὲν ἀνὰ μέσον Ὄξου καὶ Τανάιδος, ὧν ὁ μὲν εἰς τὴν Ὑρκανίαν ἐμβάλλει θάλατταν, ὁ δὲ Τάναϊς ἐξίησιν εἰς τὴν Μαιῶτιν λίμνην· εἰσὶ δ’ ἑκάτεροι κατὰ τὸ μέγεθος πλωτοί. καὶ δοκεῖ θαυμαστὸν εἶναι πῶς οἱ Νομάδες περαιούμενοι τὸν Ὄξον εἰς τὴν Ὑρκανίαν ἔρχονται πεζῇ μετὰ τῶν ἵππων. εἰσὶ δὲ δύο λόγοι περὶ τούτου τοῦ πράγματος, ὁ μὲν ἐπιεικής, ὁ δ’ ἕτερος παράδοξος, οὐ μὴν ἀδύνατος. ὁ γὰρ Ὄξος ἔχει μὲν ἐκ τοῦ Καυκάσου τὰς πηγάς, ἐπὶ πολὺ δ’ αὐξηθεὶς ἐν τῇ Βακτριανῇ, συρρεόντων εἰς αὐτὸν ὑδάτων, φέρεται διὰ πεδιάδος χώρας πολλῷ καὶ θολερῷ ῥεύματι. παραγενόμενος δ’ εἰς τὴν ἔρημον ἐπί τινας πέτρας ἀπορρῶγας ἐξωθεῖ τὸ ῥεῦμα τῇ βίᾳ διὰ τὸ πλῆθος καὶ τὴν καταφορὰν τῶν ὑπερκειμένων τόπων ἐπὶ τοσοῦτον ὥστε τῆς πέτρας ἐν τοῖς κάτω μέρεσι πλεῖον ἢ στάδιον ἀφάλλεσθαι τὴν καταφορὰν αὐτοῦ. διὰ δὴ τούτου τοῦ τόπου φασὶ τοὺς Ἀπασιάκας παρ’ αὐτὴν τὴν πέτραν ὑπὸ τὴν καταφορὰν τοῦ ποταμοῦ πεζεύειν μετὰ τῶν ἵππων εἰς τὴν Ὑρκανίαν. ὁ δ’ ἕτερος λόγος ἐπιεικεστέραν ἔχει τοῦ πρόσθεν τὴν ἀπόφασιν. τοῦ γὰρ ὑποκειμένου τόπου μεγάλους ἔχοντος πλαταμῶνας, εἰς οὓς καταρράττει, τούτους φασὶ τῇ βίᾳ τοῦ ῥεύματος ἐκκοιλαίνοντα καὶ διαρρηγνύντα κατὰ βάθος ὑπὸ γῆν φέρεσθαι τόπον οὐ πολύν, εἶτ’ ἀναφαίνεσθαι πάλιν. τοὺς δὲ βαρβάρους διὰ τὴν ἐμπειρίαν κατὰ τὸν διαλείποντα τόπον ποιεῖσθαι τὴν δίοδον ἐπὶ τῶν ἵππων εἰς τὴν Ὑρκανίαν. —", "st": "10.48"}, {"sp": "N", "t": "γενομένης δὲ τῆς προσαγγελίας διότι συμβαίνει τὸν μὲν Εὐθύδημον μετὰ τῆς δυνάμεως εἶναι περὶ Ταπουρίαν, μυρίους δ’ ἱππεῖς προκαθίζεσθαι φυλάττοντας τὰς περὶ τὸν Ἄριον ποταμὸν διαβάσεις, ἔκρινε τὴν πολιορκίαν ἀπογνοὺς ἔχεσθαι τῶν προκειμένων. ἀπέχοντος δὲ τοῦ ποταμοῦ τριῶν ἡμερῶν ὁδόν, ἐπὶ μὲν ἡμέρας δύο σύμμετρον ἐποιήσατο τὴν πορείαν, τῇ δὲ τρίτῃ μετὰ τὸ δειπνῆσαι τοῖς ἄλλοις ἅμα τῷ φωτὶ ποιεῖσθαι παρήγγειλε τὴν ἀναζυγήν, αὐτὸς δ’ ἀναλαβὼν τοὺς ἱππέας καὶ τοὺς εὐζώνους, ἅμα δὲ πελταστὰς μυρίους, προῆγε νυκτός, πορείᾳ χρώμενος ἐνεργῷ. τοὺς γὰρ ἱππεῖς ἐπυνθάνετο τῶν ὑπεναντίων τὰς μὲν ἡμέρας ἐφεδρεύειν παρὰ τὸ χεῖλος τοῦ ποταμοῦ, τὰς δὲ νύκτας ὑποχωρεῖν πρός τινα πόλιν οὐκ ἔλαττον εἴκοσι σταδίων διέχουσαν. διανύσας δὲ νύκτωρ τὴν καταλειπομένην ὁδόν, ἅτε τῶν πεδίων ἱππασίμων ὑπαρχόντων, ἔφθασε περαιώσας τὸν ποταμὸν ἅμα τῷ φωτὶ τὸ πλεῖστον μέρος τῆς μεθ’ ἑαυτοῦ δυνάμεως. οἱ δὲ τῶν Βακτριανῶν ἱππεῖς, σημηνάντων αὐτοῖς τῶν σκοπῶν τὸ γεγονός, ἐξεβοήθουν, καὶ κατὰ πορείαν συνέμισγον τοῖς ὑπεναντίοις. ὁ δὲ βασιλεύς, θεωρῶν ὅτι δεῖ δέξασθαι τὴν πρώτην ἐπιφορὰν τῶν πολεμίων, παρακαλέσας τοὺς περὶ αὐτὸν εἰθισμένους κινδυνεύειν τῶν ἱππέων δισχιλίους, τοῖς μὲν ἄλλοις παρήγγειλε κατὰ σημαίας καὶ κατ’ οὐλαμοὺς αὐτοῦ παρεμβαλεῖν καὶ λαμβάνειν ἑκάστους τὰς εἰθισμένας τάξεις, αὐτὸς δὲ μετὰ τῶν προειρημένων ἱππέων ἀπαντήσας συνέβαλε τοῖς πρώτοις ἐπιφερομένοις τῶν Βάκτρων. δοκεῖ δὲ κατὰ τοῦτον τὸν κίνδυνον Ἀντίοχος ἀγωνίσασθαι διαπρεπέστατα τῶν μεθ’ αὑτοῦ. πολλοὶ μὲν οὖν ἀμφοτέρων διεφθάρησαν, ἐπεκράτησαν δὲ τῆς πρώτης ἱππαρχίας οἱ μετὰ τοῦ βασιλέως· τῆς δὲ δευτέρας καὶ τρίτης ἐπιφερομένης ἐπιέζοντο καὶ κακῶς ἀπήλλαττον. κατὰ δὲ τὸν καιρὸν τοῦτον, τῶν πλείστων ἱππέων ἐκτεταγμένων ἤδη, Παναίτωλος ἐπαγαγεῖν παραγγείλας τὸν μὲν βασιλέα καὶ τοὺς μετ’ αὐτοῦ κινδυνεύοντας ἐδέξατο, τοὺς δὲ τῶν Βακτριανῶν ἐπιφερομένους ἀτάκτως ἐκ μεταβολῆς προτροπάδην ἠνάγκασε φυγεῖν. ἐκεῖνοι μὲν οὖν, τῶν περὶ τὸν Παναίτωλον αὐτοῖς ἐπικειμένων, οὐ πρότερον ἔστησαν ἕως οὗ συνέμιξαν τοῖς περὶ τὸν Εὐθύδημον, τοὺς πλείστους ἀπολωλεκότες αὑτῶν· οἱ δὲ τοῦ βασιλέως ἱππεῖς, πολλοὺς μὲν φονεύσαντες, πολλοὺς δὲ ζωγρίᾳ λαβόντες, ἀνεχώρουν. καὶ τότε μὲν αὐτοῦ παρὰ τὸν ποταμὸν ηὐλίσθησαν· ἐν δὲ τούτῳ τῷ κινδύνῳ τὸν μὲν ἵππον συμβαίνει ἀποθανεῖν τραυματισθέντα, αὐτὸν δὲ πληγέντα διὰ τοῦ στόματος ἀποβαλεῖν τινας· τῶν ὀδόντων, καθόλου δὲ φήμην ἐπ’ ἀνδρείᾳ περιποιήσασθαι τότε μάλιστα. γενομένης δὲ τῆς μάχης ταύτης ὁ μὲν Εὐθύδημος καταπλαγεὶς ἀνεχώρησε μετὰ τῆς δυνάμεως εἰς πόλιν Ζαριάσπαν τῆς Βακτριανῆς.", "st": "10.49"}, {"sp": "HDR", "t": "Βιβλίον ΙΑʹ", "st": "11"}, {"sp": "N", "t": "ἴσως δέ τινες ἐπιζητοῦσι πῶς ἡμεῖς οὐ προγραφὰς ἐν ταύτῃ τῇ βίβλῳ, καθάπερ οἱ πρὸ ἡμῶν, ἀλλὰ καὶ προεκθέσεις καθ’ ἑκάστην ὀλυμπιάδα πεποιήκαμεν τῶν πράξεων. ἐγὼ δὲ κρίνω χρήσιμον μὲν εἶναι καὶ τὸ τῶν προγραφῶν γένος· καὶ γὰρ εἰς ἐπίστασιν ἄγει τοὺς ἀναγινώσκειν θέλοντας καὶ συνεκκαλεῖται καὶ παρορμᾷ πρὸς τὴν ἀνάγνωσιν τοὺς ἐντυγχάνοντας, πρὸς δὲ τούτοις πᾶν τὸ ζητούμενον ἑτοίμως ἔνεστιν εὑρεῖν διὰ τούτου· θεωρῶν δὲ διὰ πολλὰς αἰτίας καὶ τὰς τυχούσας ὀλιγωρούμενον καὶ φθειρόμενον τὸ τῶν προγραφῶν γένος, οὕτως καὶ διὰ ταῦτα πρὸς τοῦτο τὸ μέρος κατηνέχθην· τῆς γὰρ προεκθέσεως οὐ μόνον ἰσοδυναμούσης πρὸς τὴν προγραφήν, ἀλλὰ καὶ πλεῖόν τι δυναμένης, ἅμα δὲ καὶ χώραν ἐχούσης ἀσφαλεστέραν διὰ τὸ συμπεπλέχθαι τῇ πραγματείᾳ, τούτῳ μᾶλλον ἐδοκιμάσαμεν χρῆσθαι τῷ μέρει παρ’ ὅλην τὴν σύνταξιν πλὴν ἓξ τῶν πρώτων βυβλίων· ἐν ἐκείνοις δὲ προγραφὰς ἐποιησάμεθα διὰ τὸ μὴ λίαν ἐναρμόζειν ἐν αὐτοῖς τὸ τῶν προεκθέσεων γένος.", "st": "11.1"}, {"sp": "N", "t": "ἀλλὰ πολὺ ῥᾳδιεστέραν καὶ συντομωτέραν συνέβη γενέσθαι τὴν Ἀσδρούβου παρουσίαν εἰς Ἰταλίαν. — διόπερ ὡς οὐδέποτε μᾶλλον ὀρθὴ καὶ περίφοβος ἡ τῶν Ῥωμαίων πόλις ἐγεγόνει, καραδοκοῦσα τὸ συμβησόμενον. — Ἀσδρούβᾳ δὲ τούτων μὲν ἤρεσκεν οὐδέν, τῶν δὲ πραγμάτων οὐκέτι διδόντων ἀναστροφὴν διὰ τὸ θεωρεῖν τοὺς πολεμίους ἐκτεταγμένους καὶ προσάγοντας, ἠναγκάζετο παρατάττειν τοὺς Ἴβηρας καὶ τοὺς μετ’ αὐτοῦ γεγονότας Γαλάτας. προθέμενος δὲ τὰ θηρία τὸν ἀριθμὸν ὄντα δέκα, καὶ τὸ βάθος αὐξήσας τῶν τάξεων, καὶ ποιήσας ἐν βραχεῖ χώρῳ τὴν ὅλην δύναμιν, πρὸς δὲ τούτοις μέσον αὑτὸν θεὶς τῆς παρατάξεως κατὰ τὴν τῶν θηρίων προστασίαν, ἐποιεῖτο τὴν ἔφοδον ἐπὶ τὰ λαιὰ τῶν πολεμίων, προδιειληφὼς ὅτι δεῖ κατὰ τὸν παρόντα κίνδυνον νικᾶν ἢ θνήσκειν. ὁ μὲν οὖν Λίβιος ἀντεπῄει τοῖς πολεμίοις σοβαρῶς καὶ συμβαλὼν ταῖς αὑτοῦ δυνάμεσιν ἐμάχετο γενναίως· ὁ δὲ Κλαύδιος ἐπὶ τοῦ δεξιοῦ κέρατος τεταγμένος προάγειν μὲν εἰς τοὔμπροσθεν καὶ περικερᾶν τοὺς ὑπεναντίους οὐκ ἐδύνατο διὰ τὰς προκειμένας δυσχωρίας, αἷς πεπιστευκὼς Ἀσδρούβας ἐποιήσατο τὴν ἐπὶ τὰ λαιὰ τῶν πολεμίων ἔφοδον. ἀπόρως δὲ διακείμενος ἐπὶ τῷ μηδὲν πράττειν, ὑπ’ αὐτοῦ τοῦ συμβαίνοντος ἔμαθεν ὃ δέον ἦν πράττειν. διὸ καὶ παραδεξάμενος ἀπὸ τῶν δεξιῶν τοὺς αὑτοῦ στρατιώτας κατὰ τὸν ὄπισθεν τόπον τῆς μάχης, καὶ τὸ λαιὸν ὑπεράρας τῆς ἰδίας παρεμβολῆς, προσέβαλε κατὰ κέρας τοῖς Καρχηδονίοις ἐπὶ τὰ θηρία. καὶ μέχρι μὲν [οὖν] τούτων ἀμφίδοξος ἦν ἡ νίκη. οἵ τε γὰρ ἄνδρες ἐφαμίλλως ἐκινδύνευον ἀμφότεροι διὰ τὸ μήτε τοῖς Ῥωμαίοις ἐλπίδα καταλείπεσθαι σωτηρίας, εἰ σφαλεῖεν, μήτε τοῖς Ἴβηρσι καὶ Καρχηδονίοις· τά τε θηρία κοινὴν ἀμφοῖν παρείχοντο τὴν χρείαν ἐν τῇ μάχῃ· μέσα γὰρ ἀπειλημμένα καὶ συνακοντιζόμενα διετάραττε καὶ τὰς τῶν Ῥωμαίων καὶ τὰς τῶν Ἰβήρων τάξεις. ἅμα δὲ τῷ τοὺς περὶ τὸν Κλαύδιον προσπεσεῖν κατ’ οὐρὰν τοῖς πολεμίοις ἄνισος ἦν ἡ μάχη, τῶν μὲν κατὰ πρόσωπον, τῶν δὲ κατὰ νώτου τοῖς Ἴβηρσι προσκειμένων. ἐξ οὗ καὶ συνέβη τοὺς πλείστους τῶν Ἰβήρων ἐν αὐτῷ τῷ τῆς μάχης καιρῷ κατακοπῆναι. τῶν δὲ θηρίων τὰ μὲν ἓξ ἅμα τοῖς ἀνδράσιν ἔπεσε, τὰ δὲ τέτταρα διωσάμενα τὰς τάξεις ὕστερον ἑάλω μεμονωμένα καὶ ψιλὰ τῶν Ἰνδῶν.", "st": "11.1"}, {"sp": "N", "t": "Ἀσδρούβας δὲ καὶ τὸν πρὸ τούτου χρόνον καὶ κατὰ τὸν ἔσχατον καιρὸν ἀνὴρ ἀγαθὸς γενόμενος, ἐν χειρῶν νόμῳ κατέστρεψε τὸν βίον· ὃν οὐκ ἄξιον ἀνεπισήμαντον παραλιπεῖν. ὅτι μὲν ἀδελφὸς ἦν Ἀννίβου κατὰ φύσιν, καὶ διότι χωριζόμενος εἰς τὴν Ἰταλίαν τούτῳ τὰς κατὰ τὴν Ἰβηρίαν πράξεις ἐνεχείρισε, ταῦτα μὲν ἐν τοῖς πρὸ τούτων ἡμῖν δεδήλωται. παραπλησίως δὲ καὶ διότι πολλοῖς μὲν χρησάμενος ἀγῶσι πρὸς Ῥωμαίους, πολλαῖς δὲ καὶ ποικίλαις περιστάσεσι παλαίσας διὰ τὸ τοὺς ἐπαποστελλομένους ἐκ Καρχηδόνος εἰς Ἰβηρίαν στρατηγούς, ἐν πᾶσι τοῖς εἰρημένοις καιροῖς ἀξίως μὲν τοῦ πατρὸς Βάρκα, καλῶς δὲ καὶ γενναίως τὰς περιπετείας καὶ τὰς ἐλαττώσεις διετέλει φέρων, καὶ ταῦτα διὰ τῶν πρὸ τοῦ συντάξεων δεδηλώκαμεν. περὶ δὲ τῶν τελευταίων ἀγώνων νῦν ἐροῦμεν, καθὸ μάλιστα πέφηνεν ἡμῖν ἄξιος ἐπιστάσεως εἶναι καὶ ζήλου. τοὺς γὰρ πλείστους ἰδεῖν ἔστι τῶν στρατηγῶν καὶ τῶν βασιλέων, ἐπειδὰν συνιστῶνται τοὺς ὑπὲρ τῶν ὅλων ἀγῶνας, τὰ μὲν ἐκ τῶν κατορθωμάτων ἔνδοξα καὶ λυσιτελῆ συνεχῶς λαμβάνοντας ὑπὸ τὴν ὄψιν, καὶ πολλάκις ἐφιστάνοντας καὶ διαλογιζομένους πῶς ἑκάστοις χρήσονται, κατὰ λόγον σφίσι χωρησάντων τῶν πραγμάτων, τὰ δ’ ἐκ τῶν ἀποπτωμάτων οὐκέτι πρὸ ὀφθαλμῶν τιθεμένους, οὐδ’ ἐν νῷ λαμβάνοντας πῇ καὶ τί πρακτέον ἑκάστοις ἐστὶ κατὰ τὰς περιπετείας. καίτοι τὸ μὲν ἕτοιμόν ἐστι, τὸ δὲ πολλῆς δεῖται προνοίας. τοιγαροῦν οἱ πλεῖστοι διὰ τὴν αὑτῶν ἀγεννίαν καὶ τὴν ἐν τούτοις ἀβουλίαν αἰσχρὰς μὲν ἐποίησαν τὰς ἥττας, εὐγενῶς πολλάκις ἠγωνισμένων τῶν στρατιωτῶν, κατῄσχυναν δὲ τὰς πρὸ τούτου πράξεις, ἐπονείδιστον δὲ σφίσι τὸν καταλειπόμενον ἐποίησαν βίον. διότι δὲ πολλοὶ τῶν ἡγουμένων περὶ τοῦτο τὸ μέρος σφάλλονται, καὶ διότι μεγίστην ἐν τούτοις ἔχει διαφορὰν ἀνὴρ ἀνδρός, εὐχερὲς τῷ βουλομένῳ καταμαθεῖν· πολλὰ γὰρ ὑποδείγματα τῶν τοιούτων πεποίηκεν ὁ προγεγονὼς χρόνος. Ἀσδρούβας δ’, ἕως μὲν ἦν ἐλπὶς ἐκ τῶν κατὰ λόγον τοῦ δύνασθαι πράττειν ἄξιόν τι τῶν προβεβιωμένων, οὐδενὸς μᾶλλον προενοεῖτο κατὰ τοὺς κινδύνους ὡς τῆς αὑτοῦ σωτηρίας· ἐπεὶ δὲ πάσας ἀφελομένη τὰς εἰς τὸ μέλλον ἐλπίδας ἡ τύχη συνέκλεισε πρὸς τὸν ἔσχατον καιρόν, οὐδὲν παραλιπὼν οὔτε περὶ τὴν παρασκευὴν οὔτε κατὰ τὸν κίνδυνον πρὸς τὸ νικᾶν, οὐχ ἧττον πρόνοιαν εἶχε καὶ τοῦ σφαλεὶς τοῖς ὅλοις ὁμόσε χωρῆσαι τοῖς παροῦσι καὶ μηδὲν ὑπομεῖναι τῶν προβεβιωμένων ἀνάξιον. ταῦτα μὲν οὖν ἡμῖν εἰρήσθω περὶ τῶν ἐν πράγμασιν ἀναστρεφομένων, ἵνα μήτε προπετῶς κινδυνεύοντες σφάλλωσι τὰς τῶν πιστευσάντων ἐλπίδας μήτε φιλοζωοῦντες παρὰ τὸ δέον αἰσχρὰς καὶ ἐπονειδίστους ποιῶσι τὰς αὑτῶν περιπετείας·", "st": "11.2"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ τῇ μάχῃ κατορθώσαντες παραυτίκα μὲν τὸν χάρακα διήρπαζον τῶν ὑπεναντίων, καὶ πολλοὺς μὲν τῶν Κελτῶν ἐν ταῖς στιβάσι κοιμωμένους διὰ τὴν μέθην κατέκοπτον ἱερείων τρόπον· συνῆγον δὲ καὶ τὴν λοιπὴν τῶν αἰχμαλώτων λείαν, ἀφ’ ἧς εἰς τὸ δημόσιον ἀνήχθη πλείω τῶν τριακοσίων ταλάντων. ἀπέθανον δὲ τῶν μὲν Καρχηδονίων κατὰ τὴν μάχην σὺν τοῖς Κελτοῖς οὐκ ἐλάττους μυρίων, τῶν δὲ Ῥωμαίων περὶ δισχιλίους. ἑάλωσαν δὲ καὶ ζωγρίᾳ τινὲς τῶν ἐνδόξων Καρχηδονίων, οἱ δὲ λοιποὶ κατεφθάρησαν. τῆς δὲ φήμης ἀφικομένης εἰς τὴν Ῥώμην τὴν μὲν ἀρχὴν ἠπίστουν τῷ λίαν βούλεσθαι τοῦτο γενόμενον ἰδεῖν· ἐπειδὴ δὲ καὶ πλείους ἧκον, οὐ μόνον τὸ γεγονός, ἀλλὰ καὶ τὰ κατὰ μέρος διασαφοῦντες, τότε δὴ χαρᾶς ὑπερβαλλούσης ἦν ἡ πόλις πλήρης, καὶ πᾶν μὲν τέμενος ἐκοσμεῖτο, πᾶς δὲ ναὸς ἔγεμε πελάνων καὶ θυμάτων, καθόλου δ’ εἰς τοιαύτην εὐελπιστίαν παρεγένοντο καὶ θάρσος ὥστε πάντας τὸν Ἀννίβαν, ὃν μάλιστα πρότερον ἐφοβήθησαν, τότε μηδ’ ἐν Ἰταλίᾳ νομίζειν παρεῖναι. ὁ δὲ φαντασίαν μὲν ἔχειν ἔφη τοὺς εἰρημένους λόγους, τὴν δ’ ἀλήθειαν οὐ τοιαύτην εἶναι, τὸ δ’ ἐναντίον. —", "st": "11.3"}, {"sp": "N", "t": "\"ὅτι μὲν οὔτε Πτολεμαῖος ὁ βασιλεὺς οὔθ’ ἡ τῶν Ῥοδίων πόλις οὔθ’ ἡ τῶν Βυζαντίων καὶ Χίων καὶ Μυτιληναίων ἐν παρέργῳ τίθενται τὰς ὑμετέρας, ὦ ἄνδρες Αἰτωλοί, διαλύσεις, ἐξ αὐτῶν τῶν πραγμάτων ὑπολαμβάνω τοῦτ’ εἶναι συμφανές. οὐ γὰρ νῦν πρῶτον οὐδὲ δεύτερον ποιούμεθα πρὸς ὑμᾶς τοὺς ὑπὲρ τῆς εἰρήνης λόγους, ἀλλ’ ἐξ ὅτου τὸν πόλεμον ἐνεστήσασθε, προσεδρεύοντες καὶ πάντα καιρὸν θεραπεύοντες οὐ διαλείπομεν ὑπὲρ τούτων ποιούμενοι πρὸς ὑμᾶς μνήμην, κατὰ μὲν τὸ παρὸν τῆς ὑμετέρας καὶ Μακεδόνων στοχαζόμενοι καταφθορᾶς, πρὸς δὲ τὸ μέλλον καὶ περὶ τῶν σφετέρων πατρίδων καὶ περὶ τῶν ἄλλων Ἑλλήνων προνοούμενοι. καθάπερ γὰρ ἐπὶ τοῦ πυρός, ὅταν ὑφάψῃ τις ἅπαξ τὴν ὕλην, οὐκέτι τὸ λοιπὸν ἐπὶ τῇ τούτου προαιρέσει γίνεται τὸ συμβαῖνον, ἀλλ’ ᾗ ποτ’ ἂν τύχῃ λαμβάνει τὴν νομήν, τὸ πλεῖον τοῖς ἀνέμοις κυβερνώμενον καὶ τῇ τῆς ὑποκειμένης ὕλης διαφθορᾷ, καὶ πολλάκις ἐπ’ αὐτὸν τὸν ἐμπρήσαντα πρῶτον ὥρμησε παραλόγως, τὸν αὐτὸν τρόπον [καὶ] ὁ πόλεμος ὑπό τινων ὅταν ἅπαξ ἐκκαυθῇ, τοτὲ μὲν αὐτοὺς τούτους πρώτους ἀπόλλυσι, ποτὲ δὲ φέρεται φθείρων ἀδίκως πᾶν τὸ παραπεσόν, αἰεὶ καινοποιούμενος καὶ προσφυσώμενος, ὥσπερ ὑπ’ ἀνέμων, ὑπὸ τῆς τῶν πλησιαζόντων ἀγνοίας. διόπερ, ὦ ἄνδρες Αἰτωλοί, νομίσαντες καὶ τοὺς νησιώτας πανδημεὶ καὶ τοὺς τὴν Ἀσίαν κατοικοῦντας Ἕλληνας παρόντας ὑμῶν δεῖσθαι τὸν μὲν πόλεμον ἆραι, τὴν δ’ εἰρήνην ἑλέσθαι, διὰ τὸ καὶ πρὸς σφᾶς ἀνήκειν τὰ γινόμενα, σωφρονήσαντες ἐντράπητε καὶ πείσθητε τοῖς παρακαλουμένοις. καὶ γὰρ εἰ κατά τινα τύχην ἐπολεμεῖτε πόλεμον ἀλυσιτελῆ μέν, ἐπειδὴ παντὶ πολέμῳ τοῦτο παρέπεται κατὰ τὸ πλεῖστον, ἔνδοξον δὲ καὶ κατὰ τὴν ἐξ ἀρχῆς ὑπόθεσιν καὶ κατὰ τὴν τῶν ἀποβαινόντων ἐπιγραφήν, ἴσως ἄν τις ὑμῖν ἔσχε συγγνώμην, φιλοτίμως διακειμένοις. εἰ δὲ πάντων αἴσχιστον καὶ πολλῆς ἀδοξίας πλήρη καὶ βλασφημίας, ἆρ’ οὐ μεγάλης προσδεῖται τὰ πράγματ’ ἐπιστάσεως; ῥηθήσεται γὰρ τὸ δοκοῦν μετὰ παρρησίας· ὑμεῖς δ’, ἂν εὖ φρονῆτε, μεθ’ ἡσυχίας ἀνέξεσθε. πολλῷ γάρ ἐστιν ἄμεινον ὀνειδισθέντας ἐν καιρῷ σωθῆναι μᾶλλον ἢ πρὸς χάριν ἀκούσαντας μετ’ ὀλίγον ἀπολέσθαι μὲν αὐτούς, ἀπολέσαι δὲ καὶ τοὺς λοιποὺς Ἕλληνας.", "st": "11.4"}, {"sp": "N", "t": "λάβετε τοίνυν πρὸ ὀφθαλμῶν τὴν αὑτῶν ἄγνοιαν. φατὲ μὲν γὰρ πολεμεῖν ὑπὲρ τῶν Ἑλλήνων πρὸς Φίλιππον, ἵνα σῳζόμενοι μὴ ποιῶσι τούτῳ τὸ προσταττόμενον, πολεμεῖτε δ’ ἐπ’ ἐξανδραποδισμῷ καὶ καταφθορᾷ τῆς Ἑλλάδος. ταῦτα γὰρ αἱ συνθῆκαι λέγουσιν ὑμῶν αἱ πρὸς Ῥωμαίους, αἳ πρότερον μὲν ἐν τοῖς γράμμασιν ὑπῆρχον, νῦν δ’ ἐν τοῖς πράγμασι θεωροῦνται γινόμεναι. καὶ τότε μὲν αὐτὰ τὰ γράμματα τὴν αἰσχύνην ὑμῖν ἐπέφερε, νῦν δὲ διὰ τῶν ἔργων ὑπὸ τὴν ὄψιν τοῦτο γίνεται πᾶσι καταφανές. λοιπὸν ὁ μὲν Φίλιππος ὄνομα γίνεται καὶ πρόσχημα τοῦ πολέμου· πάσχει γὰρ οὐδὲν δεινόν· τούτῳ δὲ συμμάχων ὑπαρχόντων Πελοποννησίων τῶν πλείστων, Βοιωτῶν, Εὐβοέων, Φωκέων, Λοκρῶν, Θετταλῶν, Ἠπειρωτῶν, κατὰ τούτων πεποίησθε τὰς συνθήκας ἐφ’ ᾧ τὰ μὲν σώματα καὶ τἄπιπλα Ῥωμαίων ὑπάρχειν, τὰς δὲ πόλεις καὶ τὴν χώραν Αἰτωλῶν. καὶ κυριεύσαντες μὲν αὐτοὶ πόλεως οὔτ’ ἂν ὑβρίζειν ὑπομείναιτε τοὺς ἐλευθέρους οὔτ’ ἐμπιπράναι τὰς πόλεις, νομίζοντες ὠμὸν εἶναι τὸ τοιοῦτο καὶ βαρβαρικόν· συνθήκας δὲ πεποίησθε τοιαύτας, δι’ ὧν ἅπαντας τοὺς ἄλλους Ἕλληνας ἐκδότους δεδώκατε τοῖς βαρβάροις εἰς τὰς αἰσχίστας ὕβρεις καὶ παρανομίας. καὶ ταῦτα πρότερον μὲν ἠγνοεῖτο· νυνὶ δὲ διὰ τῆς Ὠρειτῶν καὶ τῶν ταλαιπώρων Αἰγινητῶν ἅπασι γεγόνατε καταφανεῖς, τῆς τύχης ὥσπερ ἐπίτηδες ἐπὶ τὴν ἐξώστραν ἀναβιβαζούσης τὴν ὑμετέραν ἄγνοιαν. ἡ μὲν οὖν ἀρχὴ τοῦ πολέμου καὶ τὰ νῦν ἤδη συμβαίνοντα τοιαῦτ’ ἐστί· τὸ δὲ τέλος, ἂν ὅλως πάντα κατὰ νοῦν ὑμῖν χωρήσῃ, ποῖόν τι δεῖ προσδοκᾶν; ἆρ’ οὐ κακῶν ἀρχὴν μεγάλων ἅπασι τοῖς Ἕλλησιν;", "st": "11.5"}, {"sp": "N", "t": "ὅτι γάρ, ἂν Ῥωμαῖοι τὸν ἐν Ἰταλίᾳ πόλεμον ἀποτρίψωνται — τοῦτο δ’ ἐστὶν ἐν ὀλίγῳ, συγκεκλειμένου τῆς Βρεττίας εἰς πάνυ βραχεῖς τόπους Ἀννίβου — λοιπὸν ὅτι πάσῃ τῇ δυνάμει τὴν ὁρμὴν ἐπὶ τοὺς κατὰ τὴν Ἑλλάδα τόπους ποιήσονται, λόγῳ μὲν Αἰτωλοῖς βοηθήσοντες κατὰ Φιλίππου, τῇ δ’ ἀληθείᾳ πᾶσαν ὑφ’ ἑαυτοὺς ποιησόμενοι, καὶ λίαν ὑπολαμβάνω τοῦτ’ εἶναι καταφανές. ἐάν τε καλῶς προθῶνται ποιεῖν Ῥωμαῖοι κυριεύσαντες, ἐκείνων ἔσεσθαι καὶ τὴν χάριν καὶ τὴν ἐπιγραφήν, ἐάν τε κακῶς, τῶν αὐτῶν ὑπάρξειν καὶ τὰς ὠφελείας ἐκ τῶν ἀπολλυμένων καὶ τὴν ἐξουσίαν τῶν σῳζομένων. ὑμεῖς δὲ τότε τοὺς θεοὺς ἐπικαλέσεσθε μάρτυρας, ὅταν μήτε τῶν θεῶν βούληται μήτε τῶν ἀνθρώπων ἔτι δύνηται βοηθεῖν ὑμῖν μηδείς. ἴσως μὲν οὖν ἐξ ἀρχῆς ἔδει πάντα προορᾶσθαι· τοῦτο γὰρ ἦν ὑμῖν πρέπον· ἐπειδὴ δὲ πολλὰ διαφεύγει τῶν μελλόντων τὴν ἀνθρωπίνην πρόνοιαν, νῦν γε δέον ἂν εἴη, διὰ τούτων τῶν πραγμάτων συνεωρακότας τὸ συμβαῖνον, βέλτιον βουλεύεσθαι περὶ τοῦ μέλλοντος. οὐ μὴν ἀλλ’ ἡμεῖς γε κατὰ τὸ παρὸν οὐδὲν ἀπολελοίπαμεν τῶν ἁρμοζόντων ἢ λέγειν ἢ πράττειν τοῖς ἀληθινοῖς φίλοις, καὶ περὶ τοῦ μέλλοντος τὸ δοκοῦν μετὰ παρρησίας εἰρήκαμεν· ὑμᾶς δ’ ἀξιοῦμεν καὶ παρακαλοῦμεν μήθ’ αὑτοῖς φθονῆσαι μήτε τοῖς ἄλλοις Ἕλλησι τῆς ἐλευθερίας καὶ τῆς σωτηρίας.\" τούτου δὲ ποιήσαντος διατροπήν τινα τοῖς πολλοῖς, ὡς ἐδόκει, μετὰ τοῦτον εἰσῆλθον οἱ παρὰ τοῦ Φιλίππου πρέσβεις, οἳ τοὺς μὲν κατὰ μέρος λόγους ὑπερέθεντο, δύο δ’ ἔφασαν ἥκειν ἔχοντες ἐντολάς, αἱρουμένων μὲν τῶν Αἰτωλῶν τὴν εἰρήνην ἑτοίμως δέχεσθαι τοὺς θεοὺς καὶ τοὺς πρεσβευτὰς τοὺς παρόντας ἀπὸ τῆς Ἑλλάδος ἐπιμαρτυραμένους χωρίζεσθαι διότι τῶν μετὰ ταῦτα συμβησομένων τοῖς Ἕλλησιν Αἰτωλούς, ἀλλ’ οὐ Φίλιππον αἴτιον δεήσει νομίζειν. —", "st": "11.6"}, {"sp": "N", "t": "καὶ πολλὰ μὲν αὑτὸν κατοιμώξας ὅτι παρὰ μικρὸν ἔλθοι τοῦ λαβεῖν τὸν Ἄτταλον ὑποχείριον. — ὅτι Φίλιππος πορευθεὶς ἐπὶ τὴν Τριχωνίδα λίμνην καὶ παραγενόμενος εἰς τὸν Θέρμον, ἔνθ’ ἦν ἱερὸν Ἀπόλλωνος, ὅσα πρότερον ἀπέλιπε τῶν ἀναθημάτων, τότε πάλιν ἅπαντα διελωβήσατο, κακῶς μὲν πρὸ τοῦ, κακῶς δὲ τότε χρώμενος τῷ θυμῷ· τὸ γὰρ τοῖς ἀνθρώποις ὀργιζόμενον εἰς τὸ θεῖον ἀσεβεῖν τῆς πάσης ἀλογιστίας ἐστὶ σημεῖον. — Ἐλλόπιον, πόλις Αἰτωλίας. Πολύβιος ιαʹ. Φύταιον, πόλις Αἰτωλίας. Πολύβιος ἑνδεκάτῳ.", "st": "11.7"}, {"sp": "N", "t": "ὅτι τριῶν ὄντων τρόπων, καθ’ οὓς ἐφίενται πάντες στρατηγίας οἱ κατὰ λόγον αὐτῇ προσιόντες, πρώτου. μὲν διὰ τῶν ὑπομνημάτων καὶ τῆς ἐκ τούτων κατασκευῆς, ἑτέρου δὲ τοῦ μεθοδικοῦ καὶ τῆς παρὰ τῶν ἐμπείρων ἀνδρῶν παραδόσεως, τρίτου δὲ τοῦ διὰ τῆς ἐπ’ αὐτῶν τῶν πραγμάτων ἕξεως καὶ τριβῆς, πάντων ἦσαν τούτων ἀνεννόητοι οἱ τῶν Ἀχαιῶν στρατηγοὶ ἁπλῶς. — τοῖς γὰρ πλείστοις ὑπεγεγόνει τις ζῆλος οὐκ εὐτυχὴς ἐκ τῆς τῶν ἄλλων ἀλαζονείας καὶ τῆς ἀκαιρίας· ἐσπούδαζον γὰρ τὰς ἀκολουθίας καὶ τὰς ἐσθῆτας διαφερόντως, καί τις ἦν περὶ τοὺς πλείστους καλλωπισμός, ὑπερέχων τὴν ἐκ τοῦ βίου χορηγίαν. ὅπλων δ’ οὐδὲ τὸν ἐλάχιστον ἐποιοῦντο λόγον. — οἱ γὰρ πολλοὶ τὰ μὲν ἔργα τῶν εὐτυχούντων οὐδὲ πειρῶνται μιμεῖσθαι, τὰ δὲ πάρεργα ζηλοῦντες μετὰ βλάβης ἐκθεατρίζουσι τὴν ἑαυτῶν ἀκρισίαν. —", "st": "11.8"}, {"sp": "N", "t": "μεγάλα μὲν γὰρ ἔφη τὴν λαμπρότητα συμβάλλεσθαι πρὸς ἔκπληξιν τῶν ὑπεναντίων, πολλὰ δὲ συνεργεῖν τὴν ἐκ τῆς ἐπισκευῆς ἁρμογὴν τῶν ὅπλων εἰς τὴν χρείαν. γίνεσθαι δ’ ἂν μάλιστα τὸ δέον, εἰ τὴν μὲν ἐπιμέλειαν, ἣν νῦν ποιοῦνται περὶ τὸν ἱματισμόν, ταύτην ποιήσαιντο περὶ τῶν ὅπλων, τὴν δὲ πρότερον ὀλιγωρίαν περὶ τῶν ὅπλων παρ’ αὐτοῖς ὑπάρχουσαν, ταύτην μετενέγκαιεν ἐπὶ τὰς ἐσθῆτας· οὕτως γὰρ ἅμα τούς τε κατ’ ἰδίαν βίους ὠφελήσεσθαι καὶ τὰ κοινὰ πράγμαθ’ ὁμολογουμένως αὐτοὺς δυνήσεσθαι σῴζειν. διόπερ ἔφη δεῖν τὸν εἰς ἐξοπλισίαν ἢ στρατείαν ἐκπορευόμενον, ὅτε μὲν τὰς κνημῖδας περιτίθεται, σκοπεῖν ὅπως ἀραρυῖαί τε καὶ στίλβουσαι τῶν ὑποδεσμῶν καὶ κρηπίδων ὑπάρχωσιν αὗται μᾶλλον, ὅταν δὲ τὴν ἀσπίδα καὶ τὸν θώρακα καὶ τὸ κράνος διαλαμβάνῃ, περιβλέπειν ἵνα τῆς χλαμύδος καὶ τοῦ χιτῶνος καθαρειότερα ταῦθ’ ὑπάρχῃ καὶ πολυτελέστερα· παρ’ οἷς γὰρ τὰ πρὸς ἐπιφάνειαν αἱρετώτερά [ἐστι] τῶν πρὸς τὴν χρείαν, παρὰ τούτοις αὐτόθεν εὐθέως προφανὲς εἶναι τὸ συμβησόμενον ἐν τοῖς κινδύνοις. καθόλου δ’ ἠξίου διαλαμβάνειν ὡς ὁ μὲν ἐν τοῖς ἱματίοις καλλωπισμὸς γυναικός ἐστι, καὶ ταύτης οὐ λίαν σώφρονος, ἡ δ’ ἐν τοῖς ὅπλοις πολυτέλεια καὶ σεμνότης ἀνδρῶν ἀγαθῶν, προαιρουμένων ἑαυτοὺς καὶ τὰς πατρίδας ἐνδόξως σῴζειν. πάντες δ’ οἱ παρόντες οὕτως ἀπεδέξαντο τὰ ῥηθέντα καὶ τὸν νοῦν τῆς παρακλήσεως ἐθαύμασαν, ὡς καὶ παραχρῆμα μὲν ἐκπορευόμενοι τὸ βουλευτήριον εὐθέως ἐνεδείκνυντο τοὺς κεκαλλωπισμένους καὶ διακλίνειν ἐνίους ἠνάγκαζον τῆς ἀγορᾶς, ἔτι δὲ μᾶλλον ἐν ταῖς ἐξοπλισίαις καὶ στρατείαις παρετήρουν σφᾶς αὐτοὺς ἐν τοῖς προειρημένοις.", "st": "11.9"}, {"sp": "N", "t": "οὕτως εἷς λόγος εὐκαίρως ῥηθεὶς ὑπ’ ἀνδρὸς ἀξιοπίστου πολλάκις οὐ μόνον ἀποτρέπει τῶν χειρίστων, ἀλλὰ καὶ παρορμᾷ πρὸς τὰ κάλλιστα τοὺς ἀνθρώπους. ὅταν δὲ καὶ τὸν ἴδιον βίον ἀκόλουθον εἰσφέρηται τοῖς εἰρημένοις ὁ παρακαλῶν, ἀνάγκη λαμβάνειν τὴν πρώτην πίστιν τὴν παραίνεσιν. ὃ δὴ περὶ ἐκεῖνον τὸν ἄνδρα μάλιστ’ ἄν τις ἴδοι γινόμενον. κατά τε γὰρ τὴν ἐσθῆτα καὶ τὴν σίτησιν ἀφελὴς καὶ λιτὸς ἦν, ὁμοίως δὲ καὶ περὶ τὰς τοῦ σώματος θεραπείας, ἔτι δὲ καὶ τὰς ἐντεύξεις, εὐπερίκοπτος καὶ ἀνεπίφθονος· περί γε μὴν τοῦ παρ’ ὅλον τὸν βίον ἀληθεύειν μεγίστην ἐποιήσατο σπουδήν. τοιγάρτοι βραχέα καὶ τὰ τυχόντ’ ἀποφαινόμενος μεγάλην ἐγκατέλειπε πίστιν τοῖς ἀκούουσι· παράδειγμα γὰρ ἐν πᾶσι τὸν ἴδιον βίον εἰσφερόμενος οὐ πολλῶν ἐποίει προσδεῖσθαι λόγων τοὺς ἀκούοντας. διὸ καὶ πολλάκις λόγους μακροὺς καὶ δοκοῦντας ὑπὸ τῶν ἀντιπολιτευομένων δεόντως εἰρῆσθαι δι’ ὀλίγων ῥημάτων τῇ πίστει καὶ ταῖς ἐννοίαις τῶν πραγμάτων ὁλοσχερῶς ἐξέβαλε. πλὴν τότε συντελεσθέντος τοῦ διαβουλίου πάντες ἐπανῆγον ἐπὶ τὰς πόλεις, τά τε ῥηθέντα καὶ τὸν ἄνδρα διαφερόντως ἀποδεδεγμένοι, καὶ νομίζοντες οὐδ’ ἂν παθεῖν οὐδὲν δεινὸν ἐκείνου προεστῶτος. ὁ δὲ Φιλοποίμην εὐθέως ἐπεπορεύετο τὰς πόλεις, ἐνεργῶς καὶ μετὰ σπουδῆς ποιούμενος τὴν ἔφοδον. κἄπειτα συναγαγὼν τοὺς ὄχλους ἅμα μὲν ἐγύμναζεν ἅμα δὲ συνέταττε καὶ τέλος οὐδ’ ὅλους ὀκτὼ μῆνας χρησάμενος τῇ τοιαύτῃ παρασκευῇ καὶ μελέτῃ συνῆγε τὰς δυνάμεις εἰς Μαντίνειαν, διαγωνιούμενος πρὸς τὸν τύραννον ὑπὲρ τῆς ἁπάντων Πελοποννησίων ἐλευθερίας.", "st": "11.10"}, {"sp": "N", "t": "ὁ δὲ Μαχανίδας κατατεθαρρηκώς, καὶ νομίζων ὡς ἂν εἰ κατ’ εὐχὴν αὐτῷ γίνεσθαι τὴν τῶν Ἀχαιῶν ὁρμήν, ἅμα τῷ γνῶναι διότι συνηθροισμένοι τυγχάνουσιν εἰς τὴν Μαντίνειαν, παρακαλέσας ἐν Τεγέᾳ τοὺς Λακεδαιμονίους τὰ πρέποντα τοῖς καιροῖς, εὐθέως εἰς τὴν ἐπιοῦσαν, ἄρτι τῆς ἡμέρας ἐπιφαινούσης, προῆγεν ὡς ἐπὶ τὴν Μαντίνειαν, τῆς μὲν φάλαγγος καθηγούμενος τῷ δεξιῷ κέρατι, τοὺς δὲ μισθοφόρους ἐξ ἑκατέρου τοῦ μέρους τῆς πρωτοπορείας παραλλήλους ἄγων, ἐπὶ δὲ τούτοις ζεύγη πλῆθος ὀργάνων καὶ βελῶν κομίζοντα καταπελτικῶν. κατὰ δὲ τὸν αὐτὸν καιρὸν Φιλοποίμην εἰς τρία μέρη διῃρηκὼς τὴν δύναμιν ἐξῆγεν ἐκ τῆς Μαντινείας, κατὰ μὲν τὴν ἐκ τοῦ Ποσειδῶνος ἱεροῦ φέρουσαν τοὺς Ἰλλυριοὺς καὶ θωρακίτας, ἅμα δὲ τὸ ξενικὸν ἅπαν καὶ τοὺς εὐζώνους, κατὰ δὲ τὴν ἑξῆς ὡς πρὸς τὰς δύσεις τοὺς φαλαγγίτας, ἔτι δὲ κατὰ τὴν ἐχομένην τοὺς πολιτικοὺς ἱππεῖς. τοῖς μὲν οὖν εὐζώνοις κατελάβετο πρώτοις τὸν λόφον τὸν πρὸ τῆς πόλεως, ὃς ἀνατείνων ἱκανὸν ὑπὲρ τὴν ὁδὸν κεῖται τὴν Ξενίδα καὶ τὸ προειρημένον ἱερόν· τοὺς δὲ θωρακίτας συνάπτων ἐπὶ τὴν μεσημβρίαν κατέστησε. τούτοις δὲ συνεχεῖς τοὺς Ἰλλυριοὺς παρενέβαλε. μετὰ δὲ τούτους ἐπὶ τὴν αὐτὴν εὐθεῖαν τὴν φάλαγγα κατὰ τέλη σπειρηδὸν ἐν διαστήμασιν ἐπέστησε παρὰ τὴν τάφρον τὴν φέρουσαν ἐπὶ τοῦ Ποσειδίου διὰ μέσου τοῦ τῶν Μαντινέων πεδίου καὶ συνάπτουσαν τοῖς ὄρεσι τοῖς συντερμονοῦσι τῇ τῶν Ἐλισφασίων χώρᾳ. πρὸς μὲν τούτοις ἐπὶ τὸ δεξιὸν κέρας ἐπέστησε τοὺς Ἀχαϊκοὺς ἱππεῖς, ὧν Ἀρισταίνετος ἡγεῖτο Δυμαῖος· κατὰ δὲ τὸ λαιὸν αὐτὸς εἶχε τὸ ξενικὸν ἅπαν ἐν ἐπαλλήλοις τάξεσιν.", "st": "11.11"}, {"sp": "N", "t": "ἅμα δὲ τῷ σύνοπτον ἤδη καλῶς εἶναι παραγενομένην τὴν τῶν ὑπεναντίων δύναμιν ἐπιπορευόμενος τὰ συστήματα τῶν φαλαγγιτῶν παρεκάλει βραχέως μέν, ἐμφαντικῶς δὲ τοῦ παρόντος κινδύνου. τὰ μὲν οὖν πλεῖστα τῶν λεγομένων ἀσαφῆ συνέβαινε γίνεσθαι· διὰ γὰρ τὴν πρὸς αὐτὸν εὔνοιαν καὶ πίστιν τῶν ὄχλων εἰς τοιαύτην ὁρμὴν καὶ προθυμίαν παρέστη τὸ πλῆθος ὥστε παραπλησίαν ἐνθουσιασμῷ. τὴν ἀντιπαράκλησιν γίνεσθαι τῶν δυνάμεων, ἄγειν καὶ θαρρεῖν αὐτὸν παρακελευομένων· τοῦτο μέντοι παράπαν ἐπιμελῶς ἐπειρᾶτο διασαφεῖν, ὅτε λάβοι καιρόν, ὅτι τοῖς μὲν ὑπὲρ αἰσχρᾶς καὶ ἐπονειδίστου δουλείας, τοῖς δ’ ὑπὲρ ἀειμνήστου καὶ λαμπρᾶς ἐλευθερίας συνέστηκεν ὁ παρὼν κίνδυνος. ὁ δὲ Μαχανίδας τὸ μὲν πρῶτον ὑπέδειξεν ὡς ὀρθίᾳ τῇ φάλαγγι προσμίξων πρὸς τὸ δεξιὸν τῶν πολεμίων· ἐπεὶ δ’ ἐπλησίασε, λαβὼν σύμμετρον ἀπόστημα περιέκλα τὴν δύναμιν ἐπὶ δόρυ, καὶ παρεκτείνας ἴσον ἐποίησε τὸ παρ’ αὑτοῦ δεξιὸν τῷ τῶν Ἀχαιῶν εὐωνύμῳ, τοὺς δὲ καταπέλτας πρὸ πάσης ἐπέστησε τῆς δυνάμεως ἐν διαστήμασιν. ὁ δὲ Φιλοποίμην θεασάμενος αὐτοῦ τὴν ἐπιβολήν, ὅτι τοῖς καταπέλταις ἐπενόει βαλὼν εἰς τὰς σπείρας τῶν φαλαγγιτῶν τραυματίζειν τοὺς ἄνδρας καὶ θόρυβον ἐμποιεῖν τοῖς ὅλοις, οὐκέτι χρόνον ἔδωκεν οὐδ’ ἀναστροφήν, ἀλλὰ διὰ τῶν Ταραντίνων ἐνεργῶς ἐχρῆτο τῇ καταρχῇ τοῦ κινδύνου κατὰ τοὺς περὶ τὸ Ποσείδιον τόπους, ὄντας ἐπιπέδους καὶ πρὸς ἱππικὴν εὐφυεῖς χρείαν. ὁ δὲ Μαχανίδας ὁρῶν τὸ γινόμενον ἠναγκάζετο ποιεῖν τὸ παραπλήσιον καὶ συναφεῖναι τοὺς παρ’ αὑτοῦ Ταραντίνους.", "st": "11.12"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον αὐτῶν τούτων ἀνδρώδης ἦν ἡ σύμπτωσις· κατὰ βραχὺ δὲ προσγινομένων τοῖς πιεζομένοις τῶν εὐζώνων, ἐν πάνυ βραχεῖ χρόνῳ συνέβη τὸ παρ’ ἑκατέρων ξενικὸν ἀναμὶξ γενέσθαι, πάντῃ δὲ τούτων συμπλοκῆς ἁθρόως καὶ κατ’ ἄνδρα γινομένης ἐπὶ πολὺν χρόνον πάρισος ἦν ὁ κίνδυνος οὕτως ὥστε τὰς λοιπὰς δυνάμεις, καραδοκούσας καθ’ ὁποτέρων ὁ κονιορτὸς τραπήσεται, μὴ δύνασθαι συμβαλεῖν διὰ τὸ μένειν ἀμφοτέρους ἐπὶ πολὺ διακατέχοντας ἐν τῇ μάχῃ τὸν ἐξ ἀρχῆς τόπον. χρόνου δὲ γινομένου κατίσχυον καὶ τῷ πλήθει καὶ ταῖς εὐχειρίαις διὰ τὴν ἕξιν οἱ παρὰ τοῦ τυράννου μισθοφόροι. τοῦτο δ’ εἰκότως καὶ τὸ παράπαν εἴωθε γίνεσθαι. ὅσῳ γὰρ συμβαίνει τοὺς ἐν ταῖς δημοκρατίαις ὄχλους προθυμοτέρους ὑπάρχειν ἐν τοῖς πολεμικοῖς ἀγῶσι τῶν τοῖς τυράννοις πολιτικῶν ὑποταττομένων, τοσούτῳ τὰ παρὰ τοῖς μονάρχοις ξενικὰ τῶν ἐν ταῖς δημοκρατίαις μισθοφορούντων εἰκὸς ὑπεράγειν καὶ διαφέρειν. ὥσπερ γὰρ ἐπ’ ἐκείνων οἷς μὲν ὑπὲρ ἐλευθερίας ἐστίν, οἷς δ’ ὑπὲρ δουλείας ὁ κίνδυνος, οὕτως ἐπὶ τῶν μισθοφόρων οἷς μὲν ὑπὲρ ὁμολογουμένης ἐπανορθώσεως, οἷς δ’ ὑπὲρ προδήλου βλάβης γίνεται φιλοτιμία. δημοκρατία μὲν γάρ, ἐπανελομένη τοὺς ἐπιβουλεύσαντας, οὐκέτι μισθοφόροις τηρεῖ τὴν ἑαυτῆς ἐλευθερίαν· τυραννὶς δ’ ὅσῳ μειζόνων ἐφίεται, τοσούτῳ πλειόνων προσδεῖται μισθοφόρων. πλείονας γὰρ ἀδικοῦσα πλείονας ἔχει καὶ τοὺς ἐπιβουλεύοντας. ἡ δὲ τῶν μονάρχων ἀσφάλεια τὸ παράπαν ἐν τῇ τῶν ξένων εὐνοίᾳ κεῖται καὶ δυνάμει.", "st": "11.13"}, {"sp": "N", "t": "διὸ δὴ καὶ τότε συνέβαινε τὸ παρὰ τῷ Μαχανίδᾳ ξενικὸν οὕτως ἐκθύμως ἀγωνίζεσθαι καὶ βιαίως ὥστε μηδὲ τοὺς ἐφεδρεύοντας τοῖς ξένοις Ἰλλυριοὺς καὶ θωρακίτας δύνασθαι τὴν ἔφοδον αὐτῶν ὑπομεῖναι, πάντας δ’ ἐκπιεσθέντας φεύγειν προτροπάδην ὡς ἐπὶ τῆς Μαντινείας, ἀπεχούσης τῆς πόλεως ἑπτὰ σταδίους. ἐν ᾧ δὴ καιρῷ τὸ παρ’ ἐνίοις ἀπορούμενον τότε παρὰ πᾶσιν ὁμολογούμενον ἐγένετο καὶ συμφανές, ὅτι πλεῖστα τῶν κατὰ πόλεμον συντελουμένων παρὰ τὴν τῶν ἡγουμένων ἐμπειρίαν καὶ πάλιν ἀπειρίαν ἐπιτελεῖται. μέγα μὲν γὰρ ἴσως καὶ τὸ προτερήματος ἀρχὴν λαβόντα προσθεῖναι τἀκόλουθον, πολὺ δὲ μεῖζον τὸ σφαλέντα ταῖς πρώταις ἐπιβολαῖς μεῖναι παρ’ αὑτὸν καὶ συνιδεῖν τὴν τῶν εὐτυχούντων ἀκρισίαν καὶ συνεπιθέσθαι τοῖς τούτων ἁμαρτήμασιν. ἰδεῖν γοῦν ἔστι πολλάκις τοὺς μὲν ἤδη δοκοῦντας πεπροτερηκέναι μετ’ ὀλίγον τοῖς ὅλοις ἐσφαλμένους, τοὺς δ’ ἐν ἀρχαῖς δόξαντας ἐπταικέναι πάλιν ἐκ μεταβολῆς παρὰ τὴν αὑτῶν ἀγχίνοιαν τὰ ὅλα παραδόξως κατωρθωκότας. ὃ δὴ καὶ τότε προφανῶς ἐδόκει περὶ τοὺς ἡγεμόνας ἀμφοτέρους γεγονέναι. τοῦ γὰρ ξενικοῦ παντὸς ἐγκεκλικότος τοῖς Ἀχαιοῖς καὶ παραλελυμένου τοῦ λαιοῦ κέρως, ὁ μὲν Μαχανίδας ἀφέμενος τοῦ μένειν ἐπὶ τῶν ὑποκειμένων, καὶ τοὺς μὲν κατὰ κέρας ὑπεραίρειν τοῖς δὲ κατὰ πρόσωπον ἀπαντᾶν καὶ πειρᾶσθαι τῶν ὅλων, τούτων μὲν οὐδὲν ἔπραξεν, ἀκρατῶς δὲ καὶ μειρακιωδῶς συνεκχυθεὶς τοῖς ἑαυτοῦ μισθοφόροις ἐπέκειτο τοῖς φεύγουσιν, ὥσπερ οὐκ αὐτὸν τὸν φόβον ἱκανὸν ὄντα τοὺς ἅπαξ ἐγκλίναντας ἄχρι τῶν πυλῶν συνδιώκειν.", "st": "11.14"}, {"sp": "N", "t": "ὁ δὲ τῶν Ἀχαιῶν στρατηγὸς ἕως μὲν τοῦ δυνατοῦ διακατεῖχε τοὺς μισθοφόρους, ἐπ’ ὀνόματος καλῶν καὶ παροξύνων τοὺς ἡγεμόνας· ἐπεὶ δ’ ἑώρα τούτους ἐκβιαζομένους, οὐ πτοηθεὶς ἔφευγεν οὐδ’ ἀθυμήσας ἀπέστη, ἀλλ’ ὑποστείλας αὑτὸν ὑπὸ τὸ τῆς φάλαγγος κέρας, ἅμα τῷ παραπεσεῖν τοὺς διώκοντας καὶ γενέσθαι τὸν τόπον ἔρημον, καθ’ ὃν ὁ κίνδυνος ἦν, εὐθέως τοῖς πρώτοις τέλεσι τῶν φαλαγγιτῶν ἐπ’ ἀσπίδα κλίνων, προῆγε μετὰ δρόμου, τηρῶν τὰς τάξεις. καταλαβόμενος δὲ τὸν ἐκλειφθέντα τόπον ὀξέως, ἅμα μὲν ἀπετέτμητο τοὺς διώκοντας, ἅμα δ’ ὑπερδέξιος ἐγεγόνει τοῦ τῶν πολεμίων κέρατος. καὶ τοὺς μὲν φαλαγγίτας αὐτοῦ παρεκάλει θαρρεῖν καὶ μένειν, ἕως ἂν παραγγείλῃ ποιεῖσθαι τὴν ἐπαγωγὴν ἀναμίξ· Πολυαίνῳ δ’ ἐπέταξε τῷ Μεγαλοπολίτῃ τοὺς περιλειπομένους καὶ τοὺς διακεκλικότας τὴν φυγὴν Ἰλλυριοὺς καὶ θωρακίτας καὶ μισθοφόρους συναθροίσαντι μετὰ σπουδῆς ἐφεδρεύειν τῷ κέρατι τῆς φάλαγγος καὶ τηρεῖν τὴν ἐπάνοδον τῶν ἐκ διώγματος ἀναχωρούντων. οἱ δὲ Λακεδαιμόνιοι χωρὶς παραγγέλματος, ἐπαρθέντες ταῖς διανοίαις ἐπὶ τῷ τῶν εὐζώνων προτερήματι, καταβαλόντες τὰς σαρίσας ὥρμησαν ἐπὶ τοὺς ὑπεναντίους. ὅτε δὲ κατὰ τὴν ἐπαγωγὴν προάγοντες ἧκον ἐπὶ τὸ τῆς τάφρου χεῖλος, τὰ μὲν οὐκέτι διδόντος τοῦ καιροῦ μεταμέλειαν ὥστ’ ἐν χερσὶν ὄντας τῶν πολεμίων ἀναστρέφειν, τὰ δὲ καὶ τῆς τάφρου καταφρονήσαντες διὰ τὸ τὴν κατάβασιν ἔχειν ἐκ πολλοῦ καὶ μήθ’ ὕδωρ κατὰ τὸ τέλος ἐν αὐτῇ μήτε τιν’ ἀγρίαν ὕλην ὑπάρχειν, ὥρμησαν ἀνεπιστάτως διὰ ταύτης.", "st": "11.15"}, {"sp": "N", "t": "ὁ δὲ Φιλοποίμην ἅμα τῷ παραπεσεῖν κατὰ τῶν ὑπεναντίων τὸν ἐκ πολλῶν χρόνων ἑωραμένον ὑπ’ αὐτοῦ καιρόν, τότε πᾶσιν ἐπάγειν τοῖς φαλαγγίταις καταβαλοῦσι τὰς σαρίσας παρήγγειλε. τῶν δ’ Ἀχαιῶν ὁμοθυμαδὸν καὶ μετὰ καταπληκτικῆς κραυγῆς ποιησαμένων τὴν ἔφοδον, οἱ μὲν προδιαλελυκότες τὰς τάξεις τῶν Λακεδαιμονίων ἐν τῇ τῆς τάφρου καταβάσει πάλιν ἀναβαίνοντες πρὸς ὑπερδεξίους τοὺς πολεμίους ἀποδειλιάσαντες ἐτρέποντο· τὸ δὲ πολὺ πλῆθος ἐν αὐτῇ τῇ τάφρῳ διεφθείρετο, τὸ μὲν ὑπὸ τῶν Ἀχαιῶν, τὸ δ’ ὑπὸ τῶν ἰδίων. συνέβαινε δὲ τὸ προειρημένον οὐκ αὐτομάτως οὐδ’ ἐκ τοῦ καιροῦ, διὰ δὲ τὴν ἀγχίνοιαν τοῦ προεστῶτος, ὃς εὐθέως προεβάλετο τὴν τάφρον. ὁ δὲ Φιλοποίμην οὐ φυγομαχῶν, ὥς τινες ὑπελάμβανον, ἀλλὰ καὶ λίαν ἀκριβῶς καὶ στρατηγικῶς ἕκαστα συλλογισάμενος, ὅτι παραγενόμενος ὁ Μαχανίδας, εἰ μὲν προσάξει τὴν δύναμιν οὐ προϊδόμενος τὴν τάφρον, οὕτω συμβήσεται παθεῖν αὐτῷ τὴν φάλαγγα τὸ προειρημένον νῦν, γινόμενον δὲ τότ’ ἐπὶ τῆς ἀληθείας· εἰ δὲ συλλογισάμενος τὴν δυσχρηστίαν τῆς τάφρου, κἄπειτα μεταμεληθεὶς καὶ δόξας ἀποδειλιᾶν, ἐκ παρατεταγμένων ἀπολύσει καὶ μακρὰν αὑτὸν ἐν πορείᾳ διδόναι μέλλει, διότι χωρὶς ὁλοσχεροῦς ἀγῶνος αὐτῷ μὲν τὸ νικᾶν, ἐκείνῳ δὲ τἀναντία περιέσται. πολλοῖς γὰρ ἤδη τοῦτο συμβέβηκεν, οἵτινες παραταξάμενοι μέν, οὐκ ἀξιόχρεως δὲ νομίσαντες σφᾶς αὐτοὺς εἶναι τοῖς ὑπεναντίοις ἀγωνίζεσθαι, τινὲς μὲν διὰ τόπους, οἱ δὲ διὰ πλῆθος, οἱ δὲ δι’ ἄλλας αἰτίας, μακρὰν ἑαυτοὺς δόντες ἐν πορείᾳ, κατὰ τὴν ἀπόλυσιν δι’ αὐτῶν τῶν οὐραγούντων ἤλπισαν οἱ μὲν προτερήσειν, οἱ δ’ ἀσφαλῶς ἀπολυθήσεσθαι τῶν πολεμίων. ἐν οἷς δὴ καὶ μέγιστα συμβαίνει τοὺς ἡγουμένους πλὴν ὅ γε Φιλοποίμην οὐ διεψεύσθη τῇ προνοίᾳ τοῦ συντελεσθησομένου·", "st": "11.16"}, {"sp": "N", "t": "τροπὴν γὰρ ἰσχυρὰν συνέβαινε γίνεσθαι τῶν Λακεδαιμονίων. συνορῶν δὲ τὴν φάλαγγα νικῶσαν καὶ τὰ ὅλα καλῶς αὑτῷ προχωροῦντα καὶ λαμπρῶς, ἐπὶ τὸ καταλειπόμενον ὥρμησε τῆς ὅλης ἐπιβολῆς· τοῦτο δ’ ἦν τὸ μὴ διαφυγεῖν τὸν Μαχανίδαν. εἰδὼς οὖν αὐτὸν κατὰ τὴν τοῦ διώγματος παράπτωσιν ἀποτετμημένον ἐν τοῖς πρὸς τὴν πόλιν μέρεσι τῆς τάφρου μετὰ τῶν ἰδίων μισθοφόρων, ἐκαραδόκει τὴν τούτου παρουσίαν. ὁ δὲ Μαχανίδας, συνθεωρήσας κατὰ τὴν ἀπόλυσιν τὴν ἀπὸ τοῦ διώγματος φεύγουσαν τὴν αὑτοῦ δύναμιν, καὶ συλλογισάμενος διότι προπέπτωκε καὶ διέψευσται τῆς ὅλης ἐλπίδος, εὐθέως ἐπειρᾶτο συστραφεὶς μεθ’ ὧν εἶχε περὶ αὑτὸν ξένων, ἅθρους διαπεσεῖν διὰ τῶν ἐσκεδασμένων καὶ διωκόντων. εἰς ἃ καὶ συνορῶντες ἔνιοι συνέμενον αὐτῷ τὰς ἀρχάς, ταύτην ἔχοντες τὴν ἐλπίδα τῆς σωτηρίας. ὡς δὲ παραγενόμενοι συνεῖδον τοὺς Ἀχαιοὺς τηροῦντας τὴν ἐπὶ τῆς τάφρου γέφυραν, τότε δὴ πάντες ἐξαθυμήσαντες ἀπέρρεον ἀπ’ αὐτοῦ, καὶ καθ’ ἑαυτὸν ἕκαστος ἐπορίζετο τὴν σωτηρίαν. καθ’ ὃν δὴ καιρὸν ὁ τύραννος ἀπογνοὺς τὴν διὰ τῆς γεφύρας ὁδὸν παρήλαυνε παρὰ τὴν τάφρον, ἐνεργῶς διάβασιν ζητῶν.", "st": "11.17"}, {"sp": "N", "t": "ὁ δὲ Φιλοποίμην, ἐπιγνοὺς τὸν Μαχανίδαν ἀπό τε τῆς πορφυρίδος καὶ τοῦ περὶ τὸν ἵππον κόσμου, τοὺς μὲν περὶ τὸν Ἀναξίδαμον ἀπολείπει, παρακαλέσας τηρεῖν ἐπιμελῶς τὴν δίοδον καὶ μηδενὸς φείδεσθαι τῶν μισθοφόρων διὰ τὸ τούτους εἶναι τοὺς συναύξοντας αἰεὶ τὰς ἐν τῇ Σπάρτῃ τυραννίδας· αὐτὸς δὲ παραλαβὼν Πολύαινον τὸν Κυπαρισσέα καὶ Σιμίαν, οἷς ἐχρῆτο τότε παρασπισταῖς, ἐκ τοῦ πέραν τῆς τάφρου τὴν ἀντιπαραγωγὴν ἐποιεῖτο τῷ τυράννῳ καὶ τοῖς μετ’ αὐτοῦ· δύο γὰρ ἦσαν οἱ τότε τῷ Μαχανίδᾳ συμμίξαντες, Ἀρηξίδαμος καὶ τῶν μισθοφόρων εἷς. ἅμα δὲ τῷ τὸν Μαχανίδαν κατά τινα τόπον εὔβατον τῆς τάφρου, προσθέντα τοὺς μύωπας, βίᾳ τὸν ἵππον ἐπάγειν καὶ διαπερᾶν, συναγαγὼν ἐκ μεταβολῆς ὁ Φιλοποίμην αὐτῷ καὶ πατάξας τῷ δόρατι καιρίως, καὶ προσενεγκὼν τῷ σαυρωτῆρι πληγὴν ἄλλην ἐκ διαλήψεως, ἐν χειρῶν νόμῳ διέφθειρε τὸν τύραννον. τὸ δὲ παραπλήσιον ἐγίνετο καὶ περὶ τὸν Ἀρηξίδαμον ὑπὸ τῶν παρίππων. ὁ δὲ τρίτος ἀπογνοὺς τὴν διάβασιν διέφυγε τὸν κίνδυνον κατὰ τὸν τῶν προειρημένων φόνον. πεσόντων δ’ ἀμφοτέρων, εὐθέως οἱ περὶ τὸν Σιμίαν, σκυλεύσαντες τοὺς νεκροὺς καὶ συναφελόντες ἅμα τοῖς ὅπλοις τὴν τοῦ τυράννου κεφαλήν, ἠπείγοντο πρὸς τοὺς διώκοντας, σπεύδοντες ἐπιδεῖξαι τοῖς ὄχλοις τὴν ἀπώλειαν τοῦ τῶν ὑπεναντίων ἡγεμόνος χάριν τοῦ πιστεύσαντας ἔτι μᾶλλον ἀνυπόπτως καὶ τεθαρρηκότως ποιήσασθαι τὸν ἐπιδιωγμὸν τῶν ὑπεναντίων ἕως τῆς Τεγεατῶν πόλεως. ὃ καὶ μεγάλα συνεβάλετο πρὸς τὴν ὁρμὴν τῶν ὄχλων· οὐ γὰρ ἥκιστα διὰ τούτων τῆς μὲν Τεγέας ἐξ ἐφόδου κύριοι κατέστησαν, ταῖς δ’ ἐχομέναις παρὰ τὸν Εὐρώταν ἐστρατοπέδευον, κρατοῦντες ἤδη τῶν ὑπαίθρων ἀναμφισβητήτως. καὶ πολλῶν χρόνων οὐ δυνάμενοι τοὺς πολεμίους ἐκ τῆς οἰκείας ἀπώσασθαι, τότε πᾶσαν ἀδεῶς ἐπόρθουν αὐτοὶ τὴν Λακωνικήν, τῶν μὲν ἰδίων οὐ πολλοὺς ἀπολωλεκότες ἐν τῇ μάχῃ, τῶν δὲ Λακεδαιμονίων ἀπεκτακότες μὲν οὐκ ἐλάττους τῶν τετρακισχιλίων, ζωγρίᾳ δ’ εἰληφότες ἔτι πλείους τούτων, ὁμοίως δὲ καὶ τῆς ἀποσκευῆς κεκυριευκότες ἁπάσης καὶ τῶν ὅπλων.", "st": "11.18"}, {"sp": "N", "t": "ὅτι φησὶν ὁ Πολύβιος, τί γὰρ ὄφελός ἐστι τοῖς ἀναγινώσκουσι διεξιέναι πολέμους καὶ μάχας καὶ πόλεων ἐξανδραποδισμοὺς καὶ πολιορκίας, εἰ μὴ τὰς αἰτίας ἐπιγνώσονται, παρ’ ἃς ἐν ἑκάστοις οἱ μὲν κατώρθωσαν, οἱ δ’ ἐσφάλησαν; τὰ γὰρ τέλη τῶν πράξεων ψυγαγωγεῖ μόνον τοὺς ἀκούοντας, αἱ δὲ πρόσθεν διαλήψεις τῶν ἐπιβαλλομένων ἐξεταζόμεναι δεόντως ὠφελοῦσι τοὺς φιλομαθοῦντας. μάλιστα δὲ πάντων ὁ κατὰ μέρος χειρισμὸς ἑκάστων ἐπιδεικνύμενος ἐπανορθοῖ τοὺς συνεφιστάνοντας. —", "st": "11.19"}, {"sp": "N", "t": "τίς οὐκ ἂν ἐπισημήναιτο τὴν ἡγεμονίαν καὶ τὴν ἀρετὴν καὶ τὴν δύναμιν ἐν τοῖς ὑπαίθροις τἀνδρός, βλέψας εἰς τὸ μῆκος τούτου τοῦ χρόνου, καὶ συνεπιστήσας αὑτὸν ἐπί τε τὰς καθόλου καὶ τὰς κατὰ μέρος μάχας καὶ πολιορκίας καὶ πόλεων μεταβολὰς καὶ περιστάσεις καιρῶν, ἐπί τε τὴν περιοχὴν τῆς ὅλης ἐπιβολῆς καὶ πράξεως, ἐν ᾗ συνεχῶς Ἀννίβας ἑκκαίδεκα πολεμήσας ἔτη Ῥωμαίοις κατὰ τὴν Ἰταλίαν οὐδέποτε διέλυσε τὰς δυνάμεις ἐκ τῶν ὑπαίθρων, ἀλλὰ συνέχων ὑφ’ αὑτόν, ὥσπερ ἀγαθὸς κυβερνήτης, ἀστασίαστα διετήρησε τοσαῦτα πλήθη καὶ πρὸς αὑτὸν καὶ πρὸς ἄλληλα, καίπερ οὐχ οἷον ὁμοεθνέσιν, ἀλλ’ οὐδ’ ὁμοφύλοις χρησάμενος στρατοπέδοις. εἶχε γὰρ Λίβυας, Ἴβηρας, Λιγυστίνους, Κελτούς, Φοίνικας, Ἰταλούς, Ἕλληνας, οἷς οὐ νόμος, οὐκ ἔθος, οὐ λόγος, οὐχ ἕτερον οὐδὲν ἦν κοινὸν ἐκ φύσεως πρὸς ἀλλήλους. ἀλλ’ ὅμως ἡ τοῦ προεστῶτος ἀγχίνοια τὰς τηλικαύτας καὶ τοιαύτας διαφορὰς ἑνὸς ἐποίει προστάγματος ἀκούειν καὶ μιᾷ πείθεσθαι γνώμῃ, καίπερ οὐχ ἁπλῆς οὔσης τῆς περιστάσεως, ἀλλὰ καὶ ποικίλης, καὶ πολλάκις μὲν αὐτοῖς λαμπρᾶς ἐπιπνεούσης τῆς τύχης, ποτὲ δὲ τοὐναντίον. ἐξ ὧν εἰκότως ἄν τις θαυμάσειε τὴν τοῦ προεστῶτος δύναμιν ἐν τούτῳ τῷ μέρει, καὶ θαρρῶν εἴπειεν ὡς εἴπερ ποιησάμενος τὴν ἀρχὴν ἐπ’ ἄλλα μέρη τῆς οἰκουμένης ἐπὶ τελευταίους ἦλθε Ῥωμαίους, οὐδὲν ἂν τῶν προτεθέντων αὐτὸν διέφυγε. νῦν δ’, ἐφ’ οὓς ἔδει τελευταίους ἐλθεῖν, ἀπὸ τούτων ἀρξάμενος, ἐν τούτοις ἐποιήσατο καὶ τὴν ἀρχὴν τῶν πράξεων καὶ τὸ τέλος.", "st": "11.19"}, {"sp": "N", "t": "οἱ μὲν οὖν περὶ τὸν Ἀσδρούβαν, ἁθροίσαντες τὴν στρατιὰν ἐκ τῶν πόλεων, ἐν αἷς ἐποιοῦντο τὴν παραχειμασίαν, προῆλθον, καὶ κατεστρατοπέδευσαν οὐ μακρὰν ἀπὸ τῆς πόλεως τῆς προσαγορευομένης Ἰλίπας, βαλόμενοι τὸν χάρακα πρὸς ταῖς ὑπωρείαις, καὶ προθέμενοι πεδία πρὸς ἀγῶνα καὶ μάχην εὐφυῆ. πλῆθος δὲ πεζῶν μὲν εἶχον εἰς ἑπτὰ μυριάδας, ἱππεῖς δὲ τετρακισχιλίους, θηρία δὲ δυσὶ πλείω τῶν τριάκοντα. Πόπλιος δὲ Μάρκον μὲν Ἰούνιον ἐξαπέστειλε πρὸς Κολίχαντα, παραληψόμενον τὰς ἑτοιμασθείσας αὐτῷ παρὰ τούτου δυνάμεις· αὗται δ’ ἦσαν πεζοὶ μὲν τρισχίλιοι, ἱππεῖς δὲ πεντακόσιοι· τοὺς δὲ λοιποὺς συμμάχους αὐτὸς παρελάμβανε, προάγων καὶ ποιούμενος τὴν πορείαν ἐπὶ τὸ προκείμενον. ἐγγίσας δὲ τῷ Κασταλῶνι καὶ τοῖς περὶ Βαίκυλα τόποις, καὶ συμμίξας ἐνθάδε τῷ Μάρκῳ καὶ ταῖς παρὰ τοῦ Κολίχαντος δυνάμεσιν, εἰς πολλὴν ἀπορίαν ἐνέπιπτε περὶ τῶν ἐνεστώτων. χωρὶς γὰρ τῶν συμμάχων οὐκ ἀξιόχρεοι παρῆσαν αἱ Ῥωμαϊκαὶ δυνάμεις αὐτῷ πρὸς τὸ διακινδυνεύειν· τὸ δ’ ἐπὶ τοῖς συμμάχοις ἔχοντας τὰς ἐλπίδας ὑπὲρ τῶν ὅλων κινδυνεύειν ἐπισφαλὲς ἐδόκει καὶ λίαν εἶναι παράβολον. οὐ μὴν ἀλλὰ διαπορήσας, ὑπὸ δὲ τῶν πραγμάτων συγκλειόμενος, ἐπὶ τὸ συγχρῆσθαι κατηνέχθη τοῖς Ἴβηρσιν οὕτως ὥστε φαντασίαν μὲν παρασκευάζειν τοῖς ὑπεναντίοις, τὸν δ’ ἀγῶνα ποιεῖσθαι διὰ τῶν ἰδίων στρατοπέδων. ταῦτα δὲ προθέμενος ἀνέζευξε μετὰ πάσης τῆς δυνάμεως, ἔχων πεζοὺς μὲν εἰς τετρακισμυρίους καὶ πεντακισχιλίους, ἱππεῖς δὲ περὶ τρισχιλίους. ἐγγίσας δὲ τοῖς Καρχηδονίοις καὶ γενόμενος σύνοπτος ἐστρατοπέδευσε περί τινας γεωλόφους καταντικρὺ τῶν πολεμίων.", "st": "11.20"}, {"sp": "N", "t": "Μάγων δὲ νομίσας εὐφυῆ καιρὸν ἐπιθέσθαι καταστρατοπεδεύουσι τοῖς Ῥωμαίοις, ἀναλαβὼν τὸ πλεῖστον μέρος τῶν ἰδίων ἱππέων καὶ Μασαννάσαν μετὰ τῶν Νομάδων, ἤλαυνε πρὸς τὴν παρεμβολήν, πεπεισμένος ἀφυλακτοῦντα λήψεσθαι τὸν Πόπλιον. ὁ δὲ πάλαι προορώμενος τὸ μέλλον, ὑπό τινα βουνὸν ὑπεστάλκει τοὺς ἱππεῖς, ἴσους τοῖς τῶν Καρχηδονίων· ὧν ἀνυπονοήτως ἐμπεσόντων πολλοὶ μὲν ἐν ταῖς ἀρχαῖς ἀναστρέφοντες διὰ τὸ παράδοξον τῆς ἐπιφανείας τῆς ἄφνω τῶν ἱππέων ἀπέπεσον, οἱ δὲ λοιποὶ συμβάλλοντες τοῖς πολεμίοις ἐμάχοντο γενναίως. τῇ δὲ παρὰ τῶν καταβαινόντων ἐν τοῖς Ῥωμαϊκοῖς ἱππεῦσιν εὐχειρίᾳ δυσχρηστούμενοι καὶ πολλοὺς ἀπολλύντες οἱ Καρχηδόνιοι, βραχὺ προσαντισχόντες ἐνέκλιναν. καὶ τὸ μὲν πρῶτον ἐν τάξει τὴν ἀναχώρησιν ἐποιοῦντο, τῶν δὲ Ῥωμαίων ἐγκειμένων αὐτοῖς λύσαντες τὰς ἴλας κατέφυγον ὑπὸ τὴν αὑτῶν παρεμβολήν. οἱ μὲν οὖν Ῥωμαῖοι τούτου γενομένου θαρραλεώτερον διέκειντο πρὸς τὸν κίνδυνον, οἱ δὲ Καρχηδόνιοι τοὐναντίον. οὐ μὴν ἀλλὰ ταῖς ἑξῆς ἐπί τινας ἡμέρας τάς τε δυνάμεις ἐκτάξαντες ἐν τῷ μεταξὺ πεδίῳ καὶ διὰ τῶν ἱππέων καὶ διὰ τῶν εὐζώνων ἀκροβολισμοὺς ποιησάμενοι καὶ καταπειράσαντες ἀλλήλων, ὥρμησαν ἐπὶ τὸ κρίνειν τὰ ὅλα.", "st": "11.21"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον δυσὶ δοκεῖ κεχρῆσθαι στρατηγήμασιν ὁ Πόπλιος. θεωρῶν γὰρ τὸν Ἀσδρούβαν ὀψὲ ποιούμενον τὰς ἐξαγωγάς, καὶ μέσους Λίβυας, τὰ δὲ θηρία προτιθέμενον ἑκατέρων τῶν κεράτων, αὐτὸς εἰωθὼς τῇ μὲν ὥρᾳ προσανατείνειν, τοὺς δὲ Ῥωμαίους μέσους ἀντιτάττειν τοῖς Λίβυσι, τοὺς δ’ Ἴβηρας ἐπὶ τῶν κεράτων παρεμβάλλειν, ᾗ προέθετο κρίνειν ἡμέρᾳ, τἀναντία τοῖς προειρημένοις ποιήσας μεγάλα συνήργησε ταῖς σφετέραις δυνάμεσι πρὸς τὸ νικᾶν, οὐκ ὀλίγα δ’ ἠλάττωσε τοὺς πολεμίους. ἅμα γὰρ τῷ φωτὶ διαπεμψάμενος τοὺς ὑπηρέτας παρήγγειλε πᾶσι τοῖς χιλιάρχοις καὶ τοῖς στρατιώταις ἀριστοποιησαμένους καὶ καθοπλισαμένους ἐξάγειν πρὸ τοῦ χάρακος. γενομένου δὲ τούτου καὶ προθύμως πειθαρχησάντων διὰ τὴν ὑπόνοιαν τοῦ μέλλοντος, τοὺς μὲν ἱππεῖς καὶ τοὺς εὐζώνους προαπέστειλε, συντάξας ἐγγίζειν τῇ παρεμβολῇ τῶν ὑπεναντίων καὶ προσακροβολίζεσθαι θρασέως, αὐτὸς δὲ τοὺς πεζοὺς ἔχων ἄρτι τῆς κατὰ τὸν ἥλιον ἀνατολῆς ἐπιφαινομένης προῆγε, καὶ παραγενόμενος εἰς μέσον τὸ πεδίον παρενέβαλε, τάττων ἐναντίως ἢ πρόσθεν· μέσους μὲν γὰρ ἐτίθει τοὺς Ἴβηρας, ἐπὶ δὲ τῶν κεράτων τὰ τῶν Ῥωμαίων. τοῖς δὲ Καρχηδονίοις, ἄφνω συνεγγιζόντων πρὸς τὸν χάρακα τῶν ἱππέων, ἅμα δὲ καὶ τῆς ἄλλης δυνάμεως ἐκταττομένης ἐν ὄψει, μόλις ἐδόθη καιρὸς εἰς τὸ καθοπλίσασθαι. διόπερ ἠναγκάσθησαν οἱ περὶ τὸν Ἀσδρούβαν ἔτι νήστεις ἔχοντες τοὺς ἄνδρας ἀπαρασκεύως ἐκ τοῦ καιροῦ τοὺς μὲν ἱππεῖς καὶ τοὺς εὐζώνους ἐπαφιέναι τοῖς ἱππεῦσι τῶν ὑπεναντίων εἰς τὰ πεδία, τὰς δὲ πεζικὰς δυνάμεις παρατάττειν, οὐ πολὺ τῆς παρωρείας ἐν τοῖς ἐπιπέδοις ποιούμενοι τὴν ἔκταξιν, καθάπερ ἦν ἔθος αὐτοῖς. ἕως μὲν οὖν τινος ἔμενον οἱ Ῥωμαῖοι τὴν ἡσυχίαν ἔχοντες· ἐπειδὴ δὲ τὸ μὲν τῆς ἡμέρας προύβαινε, τῶν δ’ εὐζώνων ἄκριτος ἦν καὶ πάρισος ἡ συμπλοκὴ διὰ τὸ τοὺς πιεζομένους καταφεύγοντας ὑπὸ τὰς ἰδίας φάλαγγας ἐκ μεταβολῆς κινδυνεύειν, τὸ τηνικαῦτα δὲ διαδεξάμενος ὁ Πόπλιος διὰ τῶν διαστημάτων ἐν ταῖς σημαίαις εἴσω τοὺς ἀκροβολιζομένους, καὶ μερίσας ἐφ’ ἑκάτερον κέρας ὀπίσω τῶν παρατεταγμένων, πρῶτον μὲν τοὺς γροσφομάχους, ἐπὶ δὲ τούτοις ἐπιβάλλει τοὺς ἱππεῖς, τὰς μὲν ἀρχὰς μετωπηδὸν ποιούμενος τὴν ἔφοδον· ἀποσχὼν δὲ περὶ τετραστάδιον τῶν ὑπεναντίων, τοὺς μὲν Ἴβηρας τηροῦντας τὰς τάξεις τὸν αὐτὸν τρόπον ποιεῖσθαι τὴν ἐπαγωγὴν παρήγγειλε, τῷ μὲν δεξιῷ τὰς σημαίας καὶ τὰς ἴλας ἐπιστρέφειν ἐπὶ δόρυ, τῷ δ’ εὐωνύμῳ τἀναντία.", "st": "11.22"}, {"sp": "N", "t": "καὶ λαβὼν αὐτὸς μὲν ἀπὸ τοῦ δεξιοῦ, Λεύκιος δὲ Μάρκιος καὶ Μάρκος Ἰούνιος ἀπὸ τῶν εὐωνύμων τρεῖς ἴλας ἱππέων τὰς ἡγουμένας, καὶ πρὸ τούτων γροσφομάχους τοὺς εἰθισμένους καὶ τρεῖς σπείρας — τοῦτο δὲ καλεῖται τὸ σύνταγμα τῶν πεζῶν παρὰ Ῥωμαίοις κοόρτις — πλὴν οἱ μὲν ἐπ’ ἀσπίδα περικλάσαντες τούτους, οἱ δ’ ἐπὶ δόρυ, προῆγον ὀρθίους ἐπὶ τοὺς πολεμίους, ἐνεργῆ ποιούμενοι τὴν ἔφοδον, ἀεὶ τῶν ἑξῆς ἐπιβαλλόντων καὶ κατὰ περίκλασιν ἑπομένων. ἐπεὶ δὲ τούτους μὲν οὐ πολὺ συνέβαινε τῶν πολεμίων ἀπέχειν, τοὺς δ’ Ἴβηρας ἐν τῇ κατὰ πρόσωπον πλευρᾷ τόπον ἱκανὸν ἔτι διεστάναι τῷ βάδην ποιεῖσθαι τὴν ἐπαγωγήν, προσέβαλλον τοῖς κέρασιν ἀμφοτέροις ἅμα τοῖς τῶν ὑπεναντίων ὀρθίαις ταῖς Ῥωμαϊκαῖς δυνάμεσι κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. αἱ δὲ μετὰ ταῦτα κινήσεις, δι’ ὧν συνέβαινε τοὺς ἑπομένους, ἐπιπαρεμβάλλοντας ἐπὶ τὴν αὐτὴν εὐθεῖαν τοῖς ἡγουμένοις, συγκαθίστασθαι τοῖς πολεμίοις εἰς τὴν μάχην, τὴν ἐναντίαν εἶχον διάθεσιν ἀλλήλαις, καὶ καθόλου τὸ δεξιὸν κέρας τῷ λαιῷ καὶ κατὰ μέρος οἱ πεζοὶ τοῖς ἱππεῦσιν. οἱ μὲν γὰρ ἐπὶ τοῦ δεξιοῦ κέρως ἱππεῖς μετὰ τῶν εὐζώνων, ἐκ δόρατος ἐπιπαρεμβάλλοντες, ὑπερκερᾶν ἐπειρῶντο τοὺς πολεμίους, οἱ δὲ πεζοὶ τοὐναντίον ἐξ ἀσπίδος παρενέβαλλον· τῶν δὲ κατὰ τὸ λαιὸν οἱ μὲν ἐν ταῖς σπείραις ἐκ δόρατος, οἱ δ’ ἱππεῖς μετὰ τῶν γροσφομάχων ἐξ ἡνίας. ἐγεγόνει μὲν οὖν ἐκ τῶν ἱππέων καὶ τῶν εὐζώνων ἀμφοτέρων τῶν κεράτων ἐκ ταύτης τῆς κινήσεως τὸ δεξιὸν εὐώνυμον. οὗ μικρὸν λόγον θέμενος ὁ στρατηγὸς τοῦ μείζονος ἐποιήσατο πρόνοιαν, τοῦ κατὰ τὴν ὑπερκέρασιν, ὀρθῶς λογιζόμενος· εἰδέναι μὲν γὰρ δεῖ τὸ γινόμενον, χρῆσθαι δὲ ταῖς πρὸς τὸν καιρὸν ἁρμοζούσαις κινήσεσιν.", "st": "11.23"}, {"sp": "N", "t": "ἐκ δὲ τῆς τούτων συμπλοκῆς τὰ μὲν θηρία διὰ τῶν γροσφομάχων καὶ τῶν ἱππέων ἀκοντιζόμενα καὶ διαταραττόμενα πανταχόθεν ἔπασχε μὲν κακῶς, ἔβλαπτε δ’ οὐδὲν ἧττον τοὺς φίλους ἢ τοὺς πολεμίους· φερόμενα γὰρ εἰκῇ τοὺς ὑποπεσόντας ἐξ ἀμφοῖν αἰεὶ διέφθειρε. τῆς δὲ πεζικῆς δυνάμεως τὰ μὲν κέρατα τῶν Καρχηδονίων ἐθραύετο, τὸ δὲ μέσον τὸ κατὰ τοὺς Λίβυας, ὅπερ ἦν χρησιμώτατον, εἰς τέλος ἄπρακτον ἦν· οὔτε γὰρ παραβοηθεῖν ἠδύναντο τοῖς ἐπὶ τῶν κεράτων, λιπόντες τὸν ἴδιον τόπον διὰ τὴν τῶν Ἰβήρων ἔφοδον, οὔτε μένοντες ἐπὶ τῶν ὑποκειμένων ἐνεργεῖν τι τῶν δεόντων οἷοί τ’ ἦσαν διὰ τὸ μὴ συνιέναι τοὺς κατὰ πρόσωπον πολεμίους αὐτοῖς εἰς τὰς χεῖρας. οὐ μὴν ἀλλὰ χρόνον μέν τινα διηγωνίζοντο τὰ κέρατα γενναίως διὰ τὸ περὶ τῶν ὅλων ἑκατέροις συνεστάναι τὸν κίνδυνον. ἤδη δὲ τοῦ καύματος ἐφεστῶτος κατὰ τὴν ἀκμήν, οἱ μὲν Καρχηδόνιοι παρελύοντο διὰ τὸ μὴ πεποιῆσθαι τὴν ἔξοδον κατὰ τὴν ἰδίαν προαίρεσιν, κεκωλῦσθαι δὲ τῆς ἁρμοζούσης παρασκευῆς, οἱ δὲ Ῥωμαῖοι καὶ τῇ δυνάμει καὶ ταῖς εὐψυχίαις καθυπερεῖχον, καὶ μάλιστα τῷ τοῖς χρησιμωτάτοις πρὸς τοὺς ἀχρειοτάτους τῶν πολεμίων συμβεβληκέναι διὰ τὴν τοῦ στρατηγοῦ πρόνοιαν. τὰς μὲν οὖν ἀρχὰς οἱ περὶ τὸν Ἀσδρούβαν κατὰ πόδα πιεζούμενοι τὴν ἀναχώρησιν ἐποιοῦντο, μετὰ δὲ ταῦτα κλίναντες ἁθρόοι πρὸς τὴν παρώρειαν ἀπεχώρουν· ἐγκειμένων δὲ τῶν Ῥωμαίων βιαιότερον ἔφευγον εἰς τὸν χάρακα προτροπάδην. εἰ μὲν οὖν μὴ θεὸς αὐτοῖς τις συνεπελάβετο τῆς σωτηρίας, παραχρῆμ’ ἂν ἐξέπεσον ἐκ τῆς παρεμβολῆς. ἐπιγενομένης δὲ κατὰ τὸν ἀέρα συστροφῆς ἐξαισίου, καὶ καταρραγέντος ὄμβρου λάβρου καὶ συνεχοῦς, μόλις εἰς τὴν αὑτῶν στρατοπεδείαν ἀνεκομίσθησαν οἱ Ῥωμαῖοι. — Ἰλούργεια, πόλις Ἰβηρίας, Πολύβιος ἑνδεκάτῃ. τὸ δὲ τετηκὸς καὶ συνερρυηκὸς ἀργύριον καὶ χρυσίον ἀναζητοῦντες ὑπὸ τοῦ πυρὸς πλεῖστοι Ῥωμαίων διεφθάρησαν. —", "st": "11.24"}, {"sp": "N", "t": "ὅτι πάντων εὐδαιμονιζόντων τὸν Πόπλιον μετὰ τὸ τοὺς Καρχηδονίους ἐξελάσαι τῆς Ἰβηρίας, καὶ παρακαλούντων ἀναπαύεσθαι καὶ ῥᾳθυμεῖν, ἐπεὶ πέρας ἐπιτέθεικε τῷ πολέμῳ, μακαρίζειν αὐτοὺς ἔφη διότι τοιαύτας ἔχουσι τὰς ἐλπίδας, αὐτὸς δὲ νῦν καὶ μάλιστα βουλεύεσθαι τίνα τρόπον ἄρξηται τοῦ πρὸς Καρχηδονίους πολέμου· τὸν μὲν γὰρ πρὸ τούτου χρόνον Καρχηδονίους Ῥωμαίοις πεπολεμηκέναι, νυνὶ δὲ τὴν τύχην παραδεδωκέναι καιρὸν εἰς τὸ Ῥωμαίους Καρχηδονίοις ἐξενεγκεῖν πόλεμον.", "st": "11.24b"}, {"sp": "N", "t": "ὅτι ὁ Πόπλιος διαλεχθεὶς τῷ Σόφακι, ἅτε δὴ πρὸς τοῦτο τὸ μέρος εὐφυὴς ὑπάρχων, οὕτω φιλανθρώπως ὡμίλησε καὶ ἐπιδεξίως ὥστε τὸν Ἀσδρούβαν εἰπεῖν ταῖς ὕστερον ἡμέραις πρὸς τὸν Σόφακα διότι φοβερώτερος αὐτῷ Πόπλιος πέφηνε κατὰ τὴν ὁμιλίαν ἤπερ ἐν τοῖς ὅπλοις. —", "st": "11.24c"}, {"sp": "N", "t": "ὅτι στάσεως γενομένης τινῶν ἐν τῷ στρατοπέδῳ τῷ Ῥωμαϊκῷ, ὁ Πόπλιος, καίπερ ἤδη πεῖραν εἰληφὼς τῶν πραγμάτων ἐφ’ ἱκανόν, ὅμως οὐδέποτε μᾶλλον εἰς ἀπορίαν ἧκε καὶ δυσχρηστίαν. καὶ τοῦτ’ ἔπασχε κατὰ λόγον· καθάπερ γὰρ ἐπὶ τῶν σωμάτων τὰς μὲν ἐκτὸς αἰτίας τοῦ βλάπτειν, λέγω δ’ οἷον ψύχους, καύματος, κόπου, τραυμάτων, καὶ πρὶν γίνεσθαι φυλάξασθαι δυνατὸν καὶ γενομέναις εὐμαρὲς βοηθῆσαι, τὰ δ’ ἐξ αὐτῶν τῶν σωμάτων γινόμενα φύματα καὶ νόσους δυσχερὲς μὲν προϊδέσθαι, δυσχερὲς δὲ γενομένοις βοηθεῖν, τὸν αὐτὸν δὴ τρόπον καὶ περὶ πολιτείας καὶ περὶ στρατοπέδων διαληπτέον. πρὸς μὲν γὰρ τὰς ἔξωθεν ἐπιβουλὰς καὶ πολέμους πρόχειρος ὁ τρόπος τῆς παρασκευῆς καὶ βοηθείας τοῖς ἐφιστάνουσι, πρὸς δὲ τὰς ἐν αὐτοῖς γενομένας ἀντιπολιτείας καὶ στάσεις καὶ ταραχὰς δύσχρηστος ἡ βοήθεια καὶ μεγάλης ἐπιδεξιότητος καὶ διαφερούσης ἀγχινοίας δεομένη· πλὴν ἑνὸς παραγγέλματος, ὃ πᾶσιν ἁρμόσει, δεῖ καὶ στρατοπέδοις καὶ πόλεσι καὶ σώμασιν, ὡς ἐμὴ δόξα. τοῦτο δ’ ἐστὶ τὸ μηδέποτ’ ἐᾶν ἐπὶ πολὺ ῥᾳθυμεῖν καὶ σχολάζειν περὶ μηδὲν τῶν προειρημένων, ἥκιστα δ’ ἐν ταῖς εὐροίαις τῶν πραγμάτων καὶ ἐν ταῖς δαψιλείαις τῶν ἐπιτηδείων. πλὴν ὅ γε Πόπλιος, ἅτε διαφερόντως ἐπιμελὴς ὤν, καθάπερ ἐξ ἀρχῆς εἶπον, ἔτι δ’ ἀγχίνους καὶ πρακτικός, συναθροίσας τοὺς χιλιάρχους τοιάνδε τινὰ τῶν ἐνεστώτων εἰσηγεῖτο λύσιν. ἔφη γὰρ δεῖν ἀναδέξασθαι τοῖς στρατιώταις τὴν τῶν ὀψωνίων ἀπόδοσιν· χάριν δὲ τοῦ πιστεύεσθαι τὴν ἐπαγγελίαν, τὰς ἐπιτεταγμένας εἰσφορὰς ταῖς πόλεσι πρότερον εἰς τὴν τοῦ παντὸς στρατοπέδου χορηγίαν ταύτας νῦν ἁθροίζειν ἐπιφανῶς καὶ μετὰ σπουδῆς, ὡς πρὸς τὴν διόρθωσιν τῶν ὀψωνίων γινομένης τῆς παρασκευῆς· τοὺς δὲ χιλιάρχους τοὺς αὐτοὺς πάλιν πορευθέντας ἀξιοῦν καὶ παρακαλεῖν μετατίθεσθαι τὴν ἄγνοιαν καὶ κομίζεσθαι τὰς σιταρχίας, παραγινομένους ὡς αὐτόν, ἄν τε κατὰ μέρη βούλωνται τοῦτο ποιεῖν ἄν θ’ ὁμοῦ πάντες. γενομένου δὲ τούτου τὸ λοιπὸν ἤδη παρ’ αὐτὸν τὸν καιρὸν ἔφη δεῖν βουλεύεσθαι τί δέον ἐστὶ πράττειν.", "st": "11.25"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ταῦτα διανοηθέντες ἐγίνοντο περὶ τὴν τῶν χρημάτων ἐπιμέλειαν·. … τῶν δὲ χιλιάρχων διασαφούντων τὰ δεδογμένα, γνοὺς ὁ Πόπλιος ἀνεκοινοῦτο τῷ συνεδρίῳ τί δέον ἐστὶ ποιεῖν. ἔδοξεν οὖν αὐτοῖς, ἡμέραν διασαφήσαντας εἰς ἣν δεήσει παρεῖναι, πρὸς μὲν τὸ πλῆθος διαλύεσθαι, τοὺς δ’ αἰτίους κολάζειν πικρῶς· οὗτοι δ’ ἦσαν εἰς πέντε καὶ τριάκοντα τὸν ἀριθμόν. τῆς δ’ ἡμέρας ἐπελθούσης, καὶ παραγενομένων τῶν ἀποστατῶν ἐπί τε τὰς διαλύσεις καὶ τὴν κομιδὴν τῶν ὀψωνίων, τοῖς μὲν χιλιάρχοις τοῖς πρεσβεύσασι συνέταξε δι’ ἀπορρήτων ὁ Πόπλιος ἀπαντᾶν τοῖς ἀποστάταις καὶ διελομένους ἕκαστον πέντε τῶν ἀρχηγῶν τῆς στάσεως εὐθέως κατὰ τὴν ἀπάντησιν φιλανθρωπεῖν καὶ καλεῖν ὡς αὑτούς, μάλιστα μὲν πρὸς κατασκήνωσιν· οἳ δ’ ἂν μὴ δύνωνται τοῦτο, πρός γε δεῖπνον καὶ τοιαύτην συνουσίαν. τῷ δὲ μεθ’ αὑτοῦ στρατοπέδῳ παρήγγειλε πρὸ ἡμερῶν τριῶν ἐφόδια παρεσκευάσθαι κατὰ πλείω χρόνον ὡς ἐπὶ τὸν Ἀνδοβάλην αὐτῶν μετὰ Μάρκου πορευομένων. ὃ καὶ θαρραλεωτέρους αὐτοὺς ἀκούσαντας ἐποίησε τοὺς ἀποστάτας· ἐν αὑτοῖς γὰρ ὑπέλαβον ἔσεσθαι τὴν πλείστην ἐξουσίαν, ἐπειδὰν συμμίξωσι τῷ στρατηγῷ τῶν ἄλλων στρατοπέδων κεχωρισμένων.", "st": "11.26"}, {"sp": "N", "t": "συνεγγιζόντων δ’ αὐτῶν τῇ πόλει, τοῖς μὲν ἄλλοις στρατιώταις εἰς τὴν ἐπαύριον ἅμα τῷ φωτὶ παρηγγέλλετο μετὰ τῆς παρασκευῆς ἐξάγειν, τοῖς δὲ χιλιάρχοις καὶ τοῖς ἐπάρχοις, ὅταν ἐκπορευομένοις μετὰ τοῦτο τὸ πρῶτον τὰς μὲν ἀποσκευὰς ἀποτιθέναι, τοὺς δὲ στρατιώτας κατέχειν ἐν τοῖς ὅπλοις ἐπὶ τῆς πύλης, κἄπειτα διελεῖν σφᾶς ἐφ’ ἑκάστην τῶν πυλῶν καὶ φροντίζειν ἵνα μηδεὶς ἐκπορεύηται τῶν ἀποστατῶν. οἱ δὲ πρὸς τὴν ἀπάντησιν ἀποτεταγμένοι, συμμίξαντες τοῖς παραγινομένοις πρὸς αὐτούς, ἀπῆγον μετὰ φιλανθρωπίας τοὺς ἐν ταῖς αἰτίαις κατὰ τὸ συντεταγμένον. τούτοις μὲν οὖν ὑπ’ αὐτὸν τὸν καιρὸν ἐρρήθη συλλαβεῖν τοὺς πέντε καὶ τριάκοντ’ ἄνδρας, ἐπειδὰν δειπνήσωσι, δήσαντάς τε τηρεῖν, μηδενὸς ἔτι τῶν ἔνδον ἐκπορευομένου πλὴν τοῦ διασαφήσοντος τῷ στρατηγῷ παρ’ ἑκάστου τὸ γεγονός. πραξάντων δὲ τῶν χιλιάρχων τὸ συνταχθέν, εἰς τὴν ἐπιοῦσαν ὁ στρατηγὸς ἅμα τῷ φωτὶ θεωρῶν τοὺς παραγινομένους ἡθροισμένους εἰς τὴν ἀγοράν, συνεκάλει τὴν ἐκκλησίαν. πάντων δὲ συντρεχόντων κατὰ τὸν ἐθισμὸν ἅμα τῷ σημῆναι, καὶ μετεώρων ὄντων ταῖς διανοίαις οἷόν ποτ’ ὄψονται τὸν στρατηγὸν καὶ τί ποτ’ ἀκούσονται περὶ τῶν ἐνεστώτων, πρὸς μὲν τοὺς ἐπὶ τῶν πυλῶν χιλιάρχους ὁ Πόπλιος διεπέμψατο, κελεύων αὐτοὺς ἄγειν τοὺς στρατιώτας ἐν τοῖς ὅπλοις καὶ περιστῆναι τὴν ἐκκλησίαν, αὐτὸς δὲ προπορευθεὶς ἐξέστησε ταῖς διανοίαις πάντας εὐθέως κατὰ τὴν πρώτην φαντασίαν· ἔτι γὰρ ὑπολαμβάνοντες αὐτὸν ἀσθενῶς ἔχειν οἱ πολλοί, κἄπειτα παρὰ τὴν προσδοκίαν αἰφνιδίως ἐρρωμένον θεασάμενοι κατὰ τὴν ἐπίφασιν κατεπλάγησαν.", "st": "11.27"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ οὕτω πως ἤρξατο τῶν λόγων. ἔφη γὰρ θαυμάζειν τίνι δυσαρεστήσαντες ἢ ποίαις ἐλπίσιν ἐπαρθέντες ἐπεβάλοντο ποιεῖσθαι τὴν ἀπόστασιν. τρεῖς γὰρ αἰτίας εἶναι, δι’ ἃς τολμῶσι στασιάζειν ἄνθρωποι πρὸς πατρίδα καὶ τοὺς ἡγουμένους, ὅταν τοῖς προεστῶσι μέμφωνταί τι καὶ δυσχεραίνωσιν, ἢ τοῖς ὑποκειμένοις πράγμασι δυσαρεστῶσιν, ἢ καὶ νὴ Δία μειζόνων ὀρεχθῶσι καὶ καλλιόνων ἐλπίδων. \"ἐρωτῶ δὲ τί τούτων ὑμῖν ὑπῆρξεν; ἐμοὶ δῆλον ὅτι δυσηρεστήσασθε, διότι τὰς σιταρχίας ὑμῖν οὐκ ἀπεδίδουν· ἀλλὰ τοῦτ’ ἐμὸν μὲν οὐκ ἦν ἔγκλημα· κατὰ γὰρ τὴν ἐμὴν ἀρχὴν οὐδὲν ὑμῖν ἐνέλειπε τῶν ὀψωνίων· εἰ δ’ ἄρ’ ἦν ἐκ τῆς Ῥώμης, διότι τὰ πάλαι προσοφειλόμενα νῦν οὐ διωρθοῦτο — πότερον οὖν ἐχρῆν ἀποστάτας γενομένους τῆς πατρίδος καὶ πολεμίους τῆς θρεψάσης οὕτως ἐγκαλεῖν ἢ παρόντας λέγειν μὲν περὶ τούτων πρὸς ἐμέ, παρακαλεῖν δὲ τοὺς φίλους συνεπιλαβέσθαι καὶ βοηθεῖν ὑμῖν; δοκῶ γάρ, ἦν τοῦτο βέλτιον. τοῖς μὲν γὰρ μισθοῦ παρά τισι στρατευομένοις ἔστιν ὅτε συγγνώμην δοτέον ἀφισταμένοις τῶν μισθοδοτῶν, τοῖς δ’ ὑπὲρ ἑαυτῶν πολεμοῦσι καὶ γυναικῶν ἰδίων καὶ τέκνων οὐδαμῶς συγχωρητέον· ἔστι γὰρ παραπλήσιον ὡς ἂν εἴ τις ὑπὸ γονέως ἰδίου φάσκων εἰς ἀργυρίου λόγον ἀδικεῖσθαι παρείη μετὰ τῶν ὅπλων, ἀποκτενῶν τοῦτον παρ’ οὗ τὸ ζῆν αὐτὸς ἔλαβε. νὴ Δί’ ἀλλ’ ἐγὼ τὰς μὲν κακοπαθείας ὑμῖν καὶ τοὺς κινδύνους πλείους ἢ τοῖς ἄλλοις ἐπέταττον, τὰ δὲ λυσιτελῆ καὶ τὰς ὠφελείας ἑτέροις μᾶλλον ἐμέριζον· ἀλλ’ οὔτε τολμᾶτε τοῦτο λέγειν οὔτε τολμήσαντες δύναισθ’ ἂν ἀποδεῖξαι. τί οὖν ἐστιν, ἐφ’ ᾧ δυσαρεστούμενοι κατὰ τὸ παρὸν ἡμῖν τὰς ἀποστάσεις ἐποιήσασθε; τοῦτ’ ἤδη βούλομαι πυθέσθαι· δοκῶ μὲν γὰρ οὐδὲν οὔτ’ ἐρεῖν οὔτ’ ἐπινοήσειν ὑμῶν οὐδένα.", "st": "11.28"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τοῖς ὑποκειμένοις ἀσχάλλοντες· πότε γὰρ εὔροια πραγμάτων μείζων; πότε δὲ πλείω προτερήματα γέγονε τῇ Ῥώμῃ; πότε δὲ τοῖς στρατευομένοις μείζους ἐλπίδες ἢ νῦν; ἀλλ’ ἴσως ἐρεῖ τις τῶν ἀπηλπικότων ὅτι πλείω τὰ λυσιτελῆ τὰ παρὰ τοῖς ἐχθροῖς προυφαίνετο καὶ μείζους ἐλπίδες καὶ βεβαιότεραι· παρὰ τίσι δὴ τούτοις; ἢ παρ’ Ἀνδοβάλῃ καὶ Μανδονίῳ; καὶ τίς ὑμῶν οὐκ οἶδε διότι πρότερον μὲν οὗτοι παρασπονδήσαντες Καρχηδονίους πρὸς ἡμᾶς ἀπέστησαν, νῦν δὲ πάλιν ἀθετήσαντες τοὺς ὅρκους καὶ τὴν πίστιν ἐχθροὺς ἡμῖν σφᾶς αὐτοὺς ἀναδεδείχασι; καλόν γε τούτοις πιστεύσαντας πολεμίους γενέσθαι τῆς ἑαυτῶν πατρίδος. οὐ μὴν οὐδ’ ἐν αὑτοῖς εἴχετε τὰς ἐλπίδας ὡς κρατήσοντες τῆς Ἰβηρίας· οὐδὲ γὰρ μετ’ Ἀνδοβάλου ταχθέντες ἱκανοὶ πρὸς ἡμᾶς ἦτε διακινδυνεύειν, μή τι καὶ καθ’ ἑαυτοὺς ταττόμενοι. τί οὖν ἦν ᾧ προσείχετε; πυθέσθαι γὰρ ἂν βουλοίμην ὑμῶν. εἰ μὴ νὴ Δία ταῖς ἐμπειρίαις τῶν νῦν προχειρισθέντων ἡγεμόνων καὶ ταῖς ἀρεταῖς πιστεύοντες ἢ καὶ ταῖς ῥάβδοις καὶ τοῖς πελέκεσι τοῖς προηγουμένοις αὐτῶν· ὑπὲρ ὧν οὐδὲ λέγειν πλείω καλόν. ἀλλ’ οὐκ ἔστι τούτων, ὦ ἄνδρες, οὐδέν· οὐδ’ ἂν ἔχοιθ’ ὑμεῖς δίκαιον οὐδὲ τοὐλάχιστον εἰπεῖν οὔτε πρὸς ἡμᾶς οὔτε πρὸς τὴν πατρίδα. διόπερ ἐγὼ περὶ ὑμῶν πρός τε τὴν Ῥώμην καὶ πρὸς αὑτὸν ἀπολογήσομαι, τὰ παρὰ πᾶσιν ἀνθρώποις ὁμολογούμενα δίκαια προθέμενος. ταῦτα δ’ ἐστὶ διότι πᾶς ὄχλος εὐπαραλόγιστος ὑπάρχει καὶ πρὸς πᾶν εὐάγωγος. ὅθεν αἰεὶ τὸ παραπλήσιον πάθος συμβαίνει περί τε τοὺς ὄχλους καὶ τὴν θάλατταν. καθάπερ γὰρ κἀκείνης ἡ μὲν ἰδία φύσις ἐστὶν ἀβλαβὴς τοῖς χρωμένοις καὶ στάσιμος, ὅταν δ’ εἰς αὐτὴν ἐμπέσῃ τὰ πνεύματα βίᾳ, τοιαύτη φαίνεται τοῖς χρωμένοις οἷοί τινες ἂν ὦσιν οἱ κυκλοῦντες αὐτὴν ἄνεμοι, τὸν αὐτὸν τρόπον καὶ τὸ πλῆθος ἀεὶ καὶ φαίνεται καὶ γίνεται πρὸς τοὺς χρωμένους οἵους ἂν ἔχῃ προστάτας καὶ συμβούλους. διὸ κἀγὼ νῦν καὶ πάντες οἱ προεστῶτες τοῦ στρατοπέδου πρὸς μὲν ὑμᾶς διαλυόμεθα καὶ πίστιν δίδομεν ἐφ’ ᾧ μὴ μνησικακήσειν. πρὸς δὲ τοὺς αἰτίους ἀκαταλλάκτως διακείμεθα, κολάζειν αὐτοὺς ἀξίως καὶ τῶν εἰς τὴν πατρίδα καὶ τῶν εἰς ἡμᾶς ἡμαρτημένων.\"", "st": "11.29"}, {"sp": "N", "t": "ἀκμὴν δὲ ταῦτ’ ἔλεγε καὶ κύκλῳ μὲν οἱ στρατιῶται περιεστῶτες ἐν τοῖς ὅπλοις ἀπὸ παραγγέλματος συνεψόφησαν ταῖς μαχαίραις τοὺς θυρεούς, ἅμα δὲ τούτοις δεδεμένοι γυμνοὶ οἱ τῆς στάσεως αἴτιοι γεγονότες εἰσήγοντο. τῷ δὲ πλήθει τοιοῦτον παρέστη δέος ὑπό τε τοῦ πέριξ φόβου καὶ τῶν κατὰ πρόσωπον δεινῶν, ὥστε τῶν μὲν μαστιγουμένων, τῶν δὲ πελεκιζομένων μήτε τὴν ὄψιν ἀλλοιῶσαι μήτε φωνὴν προέσθαι μηδένα, μένειν δὲ πάντας ἀχανεῖς, ἐκπεπληγμένους πρὸς τὸ συμβαῖνον. οἱ μὲν οὖν ἀρχηγοὶ τῶν κακῶν αἰκισθέντες εἵλκοντο διὰ μέσων, ἀπηλλαγμένοι τοῦ ζῆν· οἱ δὲ λοιποὶ παρὰ μὲν τοῦ στρατηγοῦ καὶ τῶν ἄλλων ἀρχόντων κατὰ κοινὸν ἔλαβον τὰς πίστεις ἐφ’ ᾧ μηδένα μηδενὶ μνησικακήσειν, αὐτοὶ δὲ καθ’ ἕνα προϊόντες ὤμνυον τοῖς χιλιάρχοις ἦ μὴν πειθαρχήσειν τοῖς παραγγελλομένοις ὑπὸ τῶν ἀρχόντων καὶ μηδὲν ὑπεναντίον φρονήσειν τῇ Ῥώμῃ. Πόπλιος μὲν οὖν, μεγάλων κινδύνων ἀρχὴν φυομένων καλῶς διορθωσάμενος, πάλιν ἀποκατέστησε τὰς οἰκείας δυνάμεις εἰς τὴν ἐξ ἀρχῆς διάθεσιν. —", "st": "11.30"}, {"sp": "N", "t": "ὁ δὲ Πόπλιος συναθροίσας εὐθέως ἐν αὐτῇ τῇ Καρχηδόνι τὰς δυνάμεις εἰς ἐκκλησίαν ἔλεγε περί τε τῆς Ἀνδοβάλου τόλμης καὶ τῆς εἰς αὐτοὺς ἀθεσίας, καὶ πολλὰ πρὸς τοῦτο τὸ μέρος ἐνεγκάμενος παρώξυνε τοὺς πολλοὺς πρὸς τὴν κατὰ τῶν προειρημένων δυναστῶν ὁρμήν. ἐπὶ δὲ τούτοις ἐξηριθμήσατο τοὺς προγεγενημένους αὐτοῖς ἀγῶνας πρὸς Ἴβηρας ὁμοῦ καὶ πρὸς Καρχηδονίους, στρατηγούντων Καρχηδονίων, ἐν οἷς ἀεὶ νικῶντας οὐ καθήκειν ἔφη νυνὶ διαπορεῖν, μήποτε πρὸς αὐτοὺς Ἴβηρας Ἀνδοβάλου στρατηγοῦντος μαχόμενοι λειφθῶσι. διόπερ οὐδὲ προσδέξασθαι συναγωνιστὴν Ἰβήρων οὐδένα καθάπαξ ἔφη, δι’ αὐτῶν δὲ Ῥωμαίων συστήσασθαι τὸν κίνδυνον, ἵνα φανερὸν γένηται πᾶσιν ὡς οὐκ Ἴβηρσι Καρχηδονίους καταπολεμησάμενοι, καθάπερ ἔνιοί φασιν, ἐξεβάλομεν ἐξ Ἰβηρίας, ἀλλὰ καὶ Καρχηδονίους καὶ Κελτίβηρας ταῖς Ῥωμαίων ἀρεταῖς καὶ τῇ σφετέρᾳ γενναιότητι νενικήκαμεν. ταῦτα δ’ εἰπὼν ὁμονοεῖν παρῄνει καὶ θαρροῦντας, εἰ καὶ πρὸς ἄλλον τινά, καὶ πρὸς τοῦτον ἰέναι τὸν κίνδυνον. περὶ δὲ τοῦ νικᾶν αὐτὸς ἔφη μετὰ τῶν θεῶν ποιήσασθαι τὴν καθήκουσαν πρόνοιαν. τῷ δὲ πλήθει τοιαύτη παρέστη προθυμία καὶ θάρσος ὥστε παραπλησίους εἶναι πάντας ἐκ τῆς ἀπόψεως τοῖς ὁρῶσι τοὺς πολεμίους καὶ μέλλουσιν ὅσον οὔπω πρὸς αὐτοὺς διακινδυνεύειν.", "st": "11.31"}, {"sp": "N", "t": "τότε μὲν οὖν ταῦτ’ εἰπὼν διαφῆκε τὴν ἐκκλησίαν. τῇ δ’ ἐπαύριον ἀναζεύξας προῆγε, καὶ παραγενηθεὶς ἐπὶ τὸν Ἴβηρα ποταμὸν δεκαταῖος καὶ περαιωθεὶς τῇ τετάρτῃ μετὰ ταύτην προσεστρατοπέδευσε τοῖς ὑπεναντίοις, λαβὼν αὐλῶνά τινα μεταξὺ τῆς αὑτοῦ καὶ τῶν πολεμίων στρατοπεδείας. τῇ δ’ ἑξῆς εἰς τὸν προειρημένον αὐλῶνα προσέβαλέ τινα θρέμματα τῶν παρεπομένων τῷ στρατοπέδῳ, συντάξας ἑτοίμους ἔχειν τοὺς ἱππεῖς τῷ Γαΐῳ, τοὺς δὲ γροσφομάχους ἐπέταξε τῶν χιλιάρχων τισὶ παρασκευάζειν. ταχὺ δὲ τῶν Ἰβήρων ἐπιπεσόντων ἐπὶ τὰ θρέμματ’ ἐξαφῆκε τῶν γροσφομάχων τινάς. γινομένης δὲ διὰ τούτων συμπλοκῆς καὶ προσβοηθούντων ἑκατέροις πλειόνων, συνέστη μέγας ἀκροβολισμὸς τῶν πεζῶν περὶ τὸν αὐλῶνα. τοῦ δὲ καιροῦ παραδιδόντος εὐλόγους ἀφορμὰς πρὸς ἐπίθεσιν, ἔχων ὁ Γάιος ἑτοίμους τοὺς ἱππεῖς κατὰ τὸ συνταχθὲν ἐπεβάλετο τοῖς ἀκροβολιζομένοις, ἀποτεμόμενος ἀπὸ τῆς παρωρείας, ὥστε τοὺς πλείους αὐτῶν κατὰ τὸν αὐλῶνα σκεδασθέντας ὑπὸ τῶν ἱππέων διαφθαρῆναι. γενομένου δὲ τούτου, παροξυνθέντες οἱ βάρβαροι, καὶ διαγωνιάσαντες μὴ διὰ τὸ προηττῆσθαι δόξωσι καταπεπλῆχθαι τοῖς ὅλοις, ἐξῆγον ἅμα τῷ φωτὶ καὶ παρέταττον εἰς μάχην ἅπασαν τὴν δύναμιν. ὁ δὲ Πόπλιος ἕτοιμος μὲν ἦν πρὸς τὴν χρείαν, θεωρῶν δὲ τοὺς Ἴβηρας ἀλογίστως συγκαταβαίνοντας εἰς τὸν αὐλῶνα καὶ τάττοντας οὐ μόνον τοὺς ἱππεῖς, ἀλλὰ καὶ τοὺς πεζοὺς ἐν τοῖς ἐπιπέδοις, ἐπέμενε, βουλόμενος ὡς πλείστους ταύτῃ χρήσασθαι τῇ παρεμβολῇ, πιστεύων μὲν καὶ τοῖς ἱππεῦσι τοῖς ἰδίοις, ἔτι δὲ μᾶλλον τοῖς πεζοῖς, διὰ τὸ κατὰ τὰς ἐξ ὁμολόγου καὶ συστάδην μάχας τόν τε καθοπλισμὸν καὶ τοὺς ἄνδρας τοὺς παρ’ αὑτοῦ πολὺ διαφέρειν τῶν Ἰβήρων.", "st": "11.32"}, {"sp": "N", "t": "ἐπεὶ δ’ ἔδοξε τὸ δέον αὐτῷ γίνεσθαι, πρὸς μὲν τοὺς ἐν τῇ παρωρείᾳ τεταγμένους τῶν πολεμίων ἀντέταττε πρὸς δὲ τοὺς εἰς τὸν αὐλῶνα καταβεβηκότας ἅθρους ἄγων ἐκ τῆς παρεμβολῆς ἐπὶ τέτταρας κοόρτις προσέβαλε τοῖς πεζοῖς τῶν ὑπεναντίων. κατὰ δὲ τὸν καιρὸν τοῦτον καὶ Γάιος Λαίλιος, ἔχων τοὺς ἱππεῖς, προῆγε διὰ τῶν λόφων τῶν ἀπὸ τῆς παρεμβολῆς ἐπὶ τὸν αὐλῶνα κατατεινόντων, καὶ προσέβαλλε τοῖς τῶν Ἰβήρων ἱππεῦσι κατὰ νώτου, καὶ συνεῖχε τούτους ἐν τῇ πρὸς αὑτὸν μάχῃ. λοιπὸν οἱ μὲν πεζοὶ τῶν ὑπεναντίων, ἐρημωθέντες τῆς τῶν ἱππέων χρείας, οἷς πιστεύσαντες εἰς τὸν αὐλῶνα κατέβησαν, ἐπιεζοῦντο καὶ κατεβαροῦντο τῇ μάχῃ, οἱ δ’ ἱππεῖς τὸ παραπλήσιον ἔπασχον· ἀπειλημμένοι γὰρ ἐν στενῷ καὶ δυσχρηστούμενοι πλείους ὑφ’ αὑτῶν ἢ τῶν πολεμίων διεφθείροντο, τῶν μὲν ἰδίων πεζῶν ἐκ πλαγίου προσκειμένων αὐτοῖς, τῶν δὲ πολεμίων τῶν πεζῶν κατὰ πρόσωπον, τῶν δ’ ἱππέων κατὰ νώτου περιεστώτων. τοιαύτης δὲ γενομένης τῆς μάχης οἱ μὲν εἰς τὸν αὐλῶνα καταβάντες σχεδὸν ἅπαντες διεφθάρησαν, οἱ δ’ ἐν τῇ παρωρείᾳ διέφυγον. οὗτοι δ’ ἦσαν εὔζωνοι, τρίτον δὲ μέρος τῆς ἁπάσης δυνάμεως, μεθ’ ὧν καὶ τὸν Ἀνδοβάλην συνέβη διασωθέντα φυγεῖν εἴς τι χωρίον ὀχυρόν. — Πόπλιος δέ, συντέλειαν ἐπιτεθεικὼς τοῖς κατὰ τὴν Ἰβηρίαν ἔργοις, παρῆν εἰς τὸν Ταρράκωνα μετὰ μεγίστης χαρᾶς, κάλλιστον θρίαμβον καὶ καλλίστην νίκην τῇ πατρίδι κατάγων. σπεύδων δὲ μὴ καθυστερεῖν τῆς ἐν τῇ Ῥώμῃ καταστάσεως τῶν ὑπάτων, πάντα τὰ κατὰ τὴν Ἰβηρίαν διατάξας καὶ παραδοὺς τὸ στρατόπεδον τοῖς περὶ τὸν Ἰούνιον καὶ Μάρκιον, αὐτὸς ἀπέπλευσε μετὰ Γαΐου καὶ τῶν ἄλλων φίλων εἰς τὴν Ῥώμην.", "st": "11.33"}, {"sp": "N", "t": "καὶ γὰρ αὐτὸς ἦν ὁ Εὐθύδημος Μάγνης, πρὸς ὃν ἀπελογίζετο φάσκων ὡς οὐ δικαίως αὐτὸν Ἀντίοχος ἐκ τῆς βασιλείας ἐκβαλεῖν σπουδάζει· γεγονέναι γὰρ οὐκ αὐτὸς ἀποστάτης τοῦ βασιλέως, ἀλλ’ ἑτέρων ἀποστάντων ἐπανελόμενος τοὺς ἐκείνων ἐκγόνους, οὕτως κρατῆσαι τῆς Βακτριανῶν ἀρχῆς. καὶ πλείω δὲ πρὸς ταύτην τὴν ὑπόθεσιν διαλεχθεὶς ἠξίου τὸν Τηλέαν μεσιτεῦσαι τὴν διάλυσιν εὐνοϊκῶς, παρακαλέσαντα τὸν Ἀντίοχον μὴ φθονῆσαι τῆς ὀνομασίας αὑτῷ τῆς τοῦ βασιλέως καὶ προστασίας, ὥς γ’ ἐὰν μὴ συγχωρῇ τοῖς ἀξιουμένοις, οὐδετέρῳ τῆς ἀσφαλείας ὑπαρχούσης· πλήθη γὰρ οὐκ ὀλίγα παρεῖναι τῶν Νομάδων, δι’ ὧν κινδυνεύειν μὲν ἀμφοτέρους, ἐκβαρβαρωθήσεσθαι δὲ τὴν χώραν ὁμολογουμένως, ἐὰν ἐκείνους προσδέχωνται. ταῦτα δ’ εἰπὼν ἐξαπέστειλε τὸν Τηλέαν πρὸς τὸν Ἀντίοχον. ὁ δὲ βασιλεύς, πάλαι περιβλεπόμενος λύσιν τῶν πραγμάτων, πυθόμενος ταῦτα παρὰ τοῦ Τηλέου, προθύμως ὑπήκουσε πρὸς τὰς διαλύσεις διὰ τὰς προειρημένας αἰτίας. τοῦ δὲ Τηλέου προσανακάμψαντος καὶ πολλάκις πρὸς ἀμφοτέρους, τέλος Εὐθύδημος ἐξέπεμψε Δημήτριον τὸν υἱὸν βεβαιώσοντα τὰς ὁμολογίας· ὃν ὁ βασιλεὺς ἀποδεξάμενος, καὶ νομίσας ἄξιον εἶναι τὸν νεανίσκον βασιλείας καὶ κατὰ τὴν ἐπιφάνειαν καὶ κατὰ τὴν ἔντευξιν καὶ προστασίαν, πρῶτον μὲν ἐπηγγείλατο δώσειν αὐτῷ μίαν τῶν ἑαυτοῦ θυγατέρων· δεύτερον δὲ συνεχώρησε τῷ πατρὶ τὸ τῆς βασιλείας ὄνομα. περὶ δὲ τῶν λοιπῶν ἐγγράπτους ποιησάμενος ὁμολογίας καὶ συμμαχίαν ἔνορκον, ἀνέζευξε σιτομετρήσας δαψιλῶς τὴν δύναμιν, προσλαβὼν καὶ τοὺς ὑπάρχοντας ἐλέφαντας τοῖς περὶ τὸν Εὐθύδημον. ὑπερβαλὼν δὲ τὸν Καύκασον καὶ κατάρας εἰς τὴν Ἰνδικήν, τήν τε φιλίαν ἀνενεώσατο τὴν πρὸς τὸν Σοφαγασῆνον τὸν βασιλέα τῶν Ἰνδῶν, καὶ λαβὼν ἐλέφαντας, ὥστε γενέσθαι τοὺς ἅπαντας εἰς ἑκατὸν καὶ πεντήκοντ’, ἔτι δὲ σιτομετρήσας πάλιν ἐνταῦθα τὴν δύναμιν, αὐτὸς μὲν ἀνέζευξε μετὰ τῆς στρατιᾶς, Ἀνδροσθένην δὲ τὸν Κυζικηνὸν ἐπὶ τῆς ἀνακομιδῆς ἀπέλιπε τῆς γάζης τῆς ὁμολογηθείσης αὐτῷ παρὰ τοῦ βασιλέως. διελθὼν δὲ τὴν Ἀραχωσίαν καὶ περαιωθεὶς τὸν Ἐρύμανθον ποταμόν, ἧκε διὰ τῆς Δραγγηνῆς εἰς τὴν Καρμανίαν, οὗ καὶ συνάπτοντος ἤδη τοῦ χειμῶνος ἐποιήσατο τὴν παραχειμασίαν. τὸ μὲν οὖν πέρας τῆς εἰς τοὺς ἄνω τόπους στρατείας Ἀντιόχου τοιαύτην ἔλαβε τὴν συντέλειαν, δι’ ἧς οὐ μόνον τοὺς ἄνω σατράπας ὑπηκόους ἐποιήσατο τῆς ἰδίας ἀρχῆς, ἀλλὰ καὶ τὰς ἐπιθαλαττίους πόλεις καὶ τοὺς ἐπὶ τάδε τοῦ Ταύρου δυνάστας, καὶ συλλήβδην ἠσφαλίσατο τὴν βασιλείαν, καταπληξάμενος τῇ τόλμῃ καὶ φιλοπονίᾳ πάντας τοὺς ὑποταττομένους· διὰ γὰρ ταύτης τῆς στρατείας ἄξιος ἐφάνη τῆς βασιλείας οὐ μόνον τοῖς κατὰ τὴν Ἀσίαν, ἀλλὰ καὶ τοῖς κατὰ τὴν Εὐρώπην.", "st": "11.34"}, {"sp": "HDR", "t": "Βιβλίον ΙΒʹ", "st": "12"}, {"sp": "N", "t": "Πολύβιος … Βυζακίδα χώραν εἶναί φησι περὶ τὰς Σύρτεις ἐν δωδεκάτῳ· \"σταδίων μὲν οὖσα τὴν περίμετρον δισχιλίων, τῷ δὲ σχήματι περιφερής.\" Ἱππών, Λιβύης πόλις. Πολύβιος δωδεκάτῳ. Σίγγα, πόλις, Λιβύης, ὡς Πολύβιος δωδεκάτῳ. Τάβρακα, πόλις Λιβύης. Πολύβιος δωδεκάτῳ. χαλκεῖα, πόλις Λιβύης· ὁ πολυΐστωρ ἐν Λιβυκῶν τρίτῳ, ὡς Δημοσθένης· ᾧ μεμφόμενος Πολύβιος ἐν τῷ δωδεκάτῳ ὧδε γράφει· \"ἀγνοεῖ δὲ μεγάλως καὶ περὶ τῶν Χαλκείων· οὐδὲ γὰρ πόλις ἐστίν, ἀλλὰ χαλκουργεῖα.\"", "st": "12.1"}, {"sp": "N", "t": "τὰ παραπλήσια τοῖς περὶ τὸν Ἡρόδοτον ἱστορεῖ περὶ τοῦ ἐν Λιβύῃ καλουμένου λωτοῦ αὐτόπτης γενόμενος ὁ Μεγαλοπολίτης Πολύβιος ἐν τῇ ιβʹ τῶν ἱστοριῶν λέγων οὕτως· \" ἔστι δὲ τὸ δένδρον ὁ λωτὸς οὐ μέγα, τραχὺ δὲ καὶ ἀκανθῶδες, ἔχει δὲ φύλλον χλωρὸν παραπλήσιον τῇ ῥάμνῳ, μικρὸν βαθύτερον καὶ πλατύτερον. ὁ δὲ καρπὸς τὰς μὲν ἀρχὰς ὅμοιός ἐστι καὶ τῇ χρόᾳ καὶ τῷ μεγέθει ταῖς λευκαῖς μυρτίσι ταῖς τετελειωμέναις, αὐξανόμενος δὲ τῷ μὲν χρώματι γίνεται φοινικοῦς, τῷ δὲ μεγέθει ταῖς γογγύλαις ἐλαίαις παραπλήσιος, πυρῆνα δὲ ἔχει τελέως μικρόν. ἐπὰν δὲ πεπανθῇ, συνάγουσι, καὶ τὸν μὲν τοῖς οἰκέταις μετὰ χόνδρου κόψαντες σάττουσιν εἰς ἀγγεῖα, τὸν δὲ τοῖς ἐλευθέροις ἐξελόντες τὸν πυρῆνα συντιθέασιν ὡσαύτως, καὶ σιτεύονται τοῦτον. ἔστι δὲ τὸ βρῶμα παραπλήσιον σύκῳ καὶ φοινικοβαλάνῳ, τῇ δὲ εὐωδίᾳ βέλτιον. γίνεται δὲ καὶ οἶνος ἐξ αὐτοῦ βρεχομένου καὶ τριβομένου δι’ ὕδατος, κατὰ μὲν τὴν γεῦσιν ἡδὺς καὶ ἀπολαυστικός, οἰνομέλιτι χρηστῷ παραπλήσιος, ᾧ χρῶνται χωρὶς ὕδατος. οὐ δύναται δὲ πλέον δέκα μένειν ἡμερῶν· διὸ καὶ ποιοῦσι κατὰ βραχὺ πρὸς τὴν χρείαν. ποιοῦσι δὲ καὶ ὄξος ἐξ αὐτῶν.\"", "st": "12.2"}, {"sp": "N", "t": "τὴν μὲν τῆς χώρας ἀρετὴν πᾶς ἄν τις θαυμάσειε, τὸν δὲ Τίμαιον εἴποι τις ἂν οὐ μόνον ἀνιστόρητον γεγονέναι περὶ τῶν κατὰ τὴν Λιβύην, ἀλλὰ καὶ παιδαριώδη καὶ τελέως ἀσυλλόγιστον καὶ ταῖς ἀρχαίαις φήμαις ἀκμὴν ἐνδεδεμένον, ἃς παρειλήφαμεν, ὡς ἀμμώδους πάσης καὶ ξηρᾶς καὶ ἀκάρπου καθυπαρχούσης τῆς Λιβύης. ὁ δ’ αὐτὸς λόγος καὶ περὶ τῶν ζῴων. τό τε γὰρ τῶν ἵππων καὶ τῶν βοῶν καὶ προβάτων, ἅμα δὲ τούτοις αἰγῶν πλῆθος τοσοῦτόν ἐστι κατὰ τὴν χώραν ὅσον οὐκ οἶδ’ εἰ δύναιτ’ ἂν εὑρεθῆναι κατὰ τὴν λοιπὴν οἰκουμένην, διὰ τὸ πολλὰ τῶν κατὰ Λιβύην ἐθνῶν τοῖς μὲν ἡμέροις μὴ χρῆσθαι καρποῖς, ἀπὸ δὲ τῶν θρεμμάτων καὶ σὺν τοῖς θρέμμασιν ἔχειν τὸν βίον. καὶ μὴν τὸ τῶν ἐλεφάντων καὶ λεόντων καὶ παρδάλεων πλῆθος καὶ τὴν ἀλκήν, ἔτι δὲ βουβάλων κάλλος καὶ στρουθῶν μεγέθη, τίς οὐχ ἱστόρησεν; ὧν κατὰ μὲν τὴν Εὐρώπην τὸ παράπαν οὐδέν ἐστιν, ἡ δὲ Λιβύη πλήρης ἐστὶ τῶν προειρημένων. περὶ ὧν οὐδὲν ἱστορήσας Τίμαιος ὥσπερ ἐπίτηδες τἀναντία τοῖς κατ’ ἀλήθειαν ὑπάρχουσιν ἐξηγεῖται. καθάπερ δὲ καὶ περὶ τῶν κατὰ Λιβύην ἀπεσχεδίακεν, οὕτως καὶ περὶ τῶν κατὰ τὴν νῆσον τὴν προσαγορευομένην Κύρνον. καὶ γὰρ ὑπὲρ ἐκείνης μνημονεύων ἐν τῇ δευτέρᾳ βύβλῳ φησὶν αἶγας ἀγρίας καὶ πρόβατα καὶ βοῦς ἀγρίους ὑπάρχειν ἐν αὐτῇ πολλούς, ἔτι δ’ ἐλάφους καὶ λαγὼς καὶ λύκους καί τινα τῶν ἄλλων ζῴων, καὶ τοὺς ἀνθρώπους περὶ ταῦτα διατρίβειν κυνηγετοῦντας καὶ τὴν ὅλην τοῦ βίου διαγωγὴν ἐν τούτοις ἔχειν. κατὰ δὲ τὴν προειρημένην νῆσον οὐχ οἷον αἲξ ἄγριος ἢ βοῦς, ἀλλ’ οὐδὲ λαγὼς οὐδὲ λύκος οὐδ’ ἔλαφος οὐδ’ ἄλλο τῶν τοιούτων ζῴων οὐδέν ἐστι, πλὴν ἀλωπέκων καὶ κυνίκλων καὶ προβάτων ἀγρίων. ὁ δὲ κύνικλος πόρρωθεν μὲν ὁρώμενος εἶναι δοκεῖ λαγὼς μικρός, ὅταν δ’ εἰς τὰς χεῖρας λάβῃ τις, μεγάλην ἔχει διαφορὰν καὶ κατὰ τὴν ἐπιφάνειαν καὶ κατὰ τὴν βρῶσιν· γίνεται δὲ τὸ πλεῖον μέρος κατὰ γῆς.", "st": "12.3"}, {"sp": "N", "t": "δοκεῖ γε μὴν πάντ’ εἶναι τὰ ζῷα κατὰ τὴν νῆσον ἄγρια διὰ τοιαύτην αἰτίαν. οὐ δύνανται κατὰ τὰς νομὰς συνακολουθεῖν οἱ ποιμαίνοντες τοῖς θρέμμασι διὰ τὸ σύνδενδρον καὶ κρημνώδη καὶ τραχεῖαν εἶναι τὴν νῆσον· ἀλλ’ ὅταν βούλωνται συναθροῖσαι, κατὰ τοὺς εὐκαίρους τόπους ἐφιστάμενοι τῇ σάλπιγγι συγκαλοῦσι τὰ ζῷα, καὶ πάντα πρὸς τὴν ἰδίαν ἀδιαπτώτως συντρέχει σάλπιγγα. λοιπὸν ὅταν τινὲς προσπλεύσαντες πρὸς τὴν νῆσον αἶγας ἢ βοῦς θεάσωνται νεμομένας ἐρήμους, κἄπειτα βουληθῶσι καταλαβεῖν, οὐ προσίεται τὰ ζῷα διὰ τὴν ἀσυνήθειαν, ἀλλὰ φεύγει. ὅταν δὲ καὶ συνιδὼν ὁ ποιμὴν τοὺς ἀποβαίνοντας σαλπίσῃ, προτροπάδην ἅμα φέρεται καὶ συντρέχει πρὸς τὴν σάλπιγγα. διὸ φαντασίαν ἀγρίων ποιεῖ· ὑπὲρ ὧν Τίμαιος κακῶς καὶ παρέργως ἱστορήσας ἐσχεδίασε. τὸ δὲ τῇ σάλπιγγι πειθαρχεῖν οὐκ ἔστι θαυμάσιον· καὶ γὰρ κατὰ τὴν Ἰταλίαν οἱ τὰς ὗς τρέφοντες οὕτω χειρίζουσι τὰ κατὰ τὰς νομάς. οὐ γὰρ ἕπονται κατὰ πόδας οἱ συοφορβοὶ τοῖς θρέμμασιν, ὥσπερ παρὰ τοῖς Ἕλλησιν, ἀλλὰ προηγοῦνται φωνοῦντες τῇ βυκάνῃ κατὰ διάστημα, τὰ δὲ θρέμματα κατόπιν ἀκολουθεῖ καὶ συντρέχει πρὸς τὴν φωνήν, καὶ τηλικαύτη γίνεται συνήθεια τοῖς ζῴοις πρὸς τὴν ἰδίαν βυκάνην ὥστε θαυμάζειν καὶ δυσπαραδέκτως ἔχειν τοὺς πρώτους ἀκούσαντας. διὰ γὰρ τὴν πολυχειρίαν καὶ τὴν λοιπὴν χορηγίαν μεγάλα συμβαίνει τὰ συβόσια κατὰ τὴν Ἰταλίαν ὑπάρχειν, καὶ μάλιστα [τὴν παλαίαν], παρά τε τοῖς Τυρρηνικοῖς καὶ Γαλάταις, ὥστε τὴν μίαν τοκάδα χιλίους ἐκτρέφειν ὗς, ποτὲ δὲ καὶ πλείους. διὸ καὶ κατὰ γένη ποιοῦνται καὶ καθ’ ἡλικίαν τὰς ἐκ τῶν νυκτερευμάτων ἐξαγωγάς. ὅθεν εἰς τὸν αὐτὸν τόπον προαγομένων καὶ πλειόνων συστημάτων οὐ δύνανται ταῦτα κατὰ γένη τηρεῖν, ἀλλά γε συμπίπτει κατά τε τὰς ἐξελασίας καὶ νομὰς ἀλλήλοις, ὁμοίως δὲ κατὰ τὰς προσαγωγάς. ἐξ ὧν αὐτοῖς ἐπινενόηται πρὸς τὸ διακρίνειν, ὅταν συμπέσῃ, χωρὶς κόπου καὶ πραγματείας τὸ κατὰ βυκάνην. ἐπειδὰν γὰρ τῶν νεμόντων ὁ μὲν ἐπὶ τοῦτο τὸ μέρος προάγῃ φωνῶν, ὁ δ’ ἐφ’ ἕτερον ἀποκλίνας, αὐτὰ δι’ αὑτῶν χωρίζεται τὰ θρέμματα καὶ κατακολουθεῖ ταῖς ἰδίαις βυκάναις μετὰ τοιαύτης προθυμίας ὥστε μὴ δυνατὸν εἶναι βιάσασθαι μηδὲ κωλῦσαι μηδενὶ τρόπῳ τὴν ὁρμὴν αὐτῶν. παρὰ δὲ τοῖς Ἕλλησι κατὰ τοὺς δρυμούς, ἐπειδὰν ἀλλήλοις συμπέσῃ διώκοντα τὸν καρπόν, ὁ πλείονας ἔχων χεῖρας καὶ κατευκαιρήσας περιλαβὼν τοῖς ἰδίοις θρέμμασιν ἀπάγει τὰ τοῦ πλησίον. ποτὲ δὲ κλέπτης ὑποκαθίσας ἀπήλασεν, οὐδ’ ἐπιγινώσκοντος τοῦ περιάγοντος πῶς ἀπέβαλε, διὰ τὸ μακρὰν ἀποσπᾶσθαι τὰ κτήνη τῶν περιαγόντων, ἁμιλλώμενα περὶ τὸν καρπόν, ὅταν ἀκμὴν ἄρχηται ῥεῖν. πλὴν ταῦτα μὲν ἐπὶ τοσοῦτον.", "st": "12.4"}, {"sp": "N", "t": "ὅτι διασύρας ὁ Πολύβιος τὸν Τίμαιον ἐν πολλοῖς αὖθίς φησι· τίς ἂν ἔτι δοίη συγγνώμην ἐπὶ τοῖς τοιούτοις ἁμαρτήμασιν ἄλλως τε καὶ Τιμαίῳ τῷ προσφυομένῳ τοῖς ἄλλοις πρὸς τὰς τοιαύτας παρωνυχίας; ἐν αἷς Θεοπόμπου μὲν κατηγορεῖ διότι Διονυσίου ποιησαμένου τὴν ἀνακομιδὴν ἐκ Σικελίας εἰς Κόρινθον ἐν μακρᾷ νηί, Θεόπομπός φησιν ἐν στρογγύλῃ παραγενέσθαι τὸν Διονύσιον, Ἐφόρου δὲ πάλιν ἄγνοιαν καταψεύδεται, φάσκων λέγειν αὐτὸν ὅτι Διονύσιος ὁ πρεσβύτερος παρελάμβανε τὴν ἀρχὴν ἐτῶν εἴκοσι τριῶν ὑπάρχων, δυναστεύσαι δὲ τετταράκοντα καὶ δύο, μεταλλάξαι δὲ τὸν βίον προσλαβὼν τοῖς ἑξήκοντα τρία· τοῦτο γὰρ οὐδεὶς ἂν εἴπειε δήπου τοῦ συγγραφέως εἶναι τὸ διάπτωμα, τοῦ δὲ γραφέως ὁμολογουμένως· ἢ γὰρ δεῖ τὸν Ἔφορον ὑπερβεβηκέναι τῇ μωρίᾳ καὶ τὸν Κόροιβον καὶ τὸν Μαργίτην, εἰ μὴ δυνατὸς ἦν συλλογίζεσθαι διότι τὰ τετταράκοντα καὶ δύο προστεθέντα τοῖς εἴκοσι καὶ τρισὶν ἑξήκοντα γίνεται καὶ πέντε· ἢ τούτου μηδαμῶς ἂν πιστευθέντος ὑπὲρ Ἐφόρου φανερὸν ὅτι τὸ μὲν ἁμάρτημα ἐστι τοῦ γραφέως, τὸ δὲ Τιμαίου φιλεπίτιμον καὶ φιλέγκλημον οὐδεὶς ἂν ἀποδέξαιτο.", "st": "12.4a"}, {"sp": "N", "t": "καὶ μὴν ἐν τοῖς περὶ Πύρρου πάλιν φησὶ τοὺς Ῥωμαίους ἔτι νῦν ὑπόμνημα ποιουμένους τῆς κατὰ τὸ Ἴλιον ἀπωλείας ἐν ἡμέρᾳ τινὶ κατακοντίζειν ἵππον πολεμιστὴν πρὸ τῆς πόλεως ἐν τῷ Κάμπῳ καλουμένῳ, διὰ τὸ τῆς Τροίας τὴν ἅλωσιν διὰ τὸν ἵππον γενέσθαι τὸν δούριον προσαγορευόμενον, πρᾶγμα πάντων παιδαριωδέστατον· οὕτω μὲν γὰρ δεήσει πάντας τοὺς βαρβάρους λέγειν Τρώων ἀπογόνους ὑπάρχειν· σχεδὸν γὰρ πάντες, εἰ δὲ μή γ’, οἱ πλείους, ὅταν ἢ πολεμεῖν μέλλωσιν ἐξ ἀρχῆς ἢ διακινδυνεύειν πρός τινας ὁλοσχερῶς, ἵππον προθύονται καὶ σφαγιάζονται, σημειούμενοι τὸ μέλλον ἐκ τῆς τοῦ ζῴου πτώσεως.", "st": "12.4b"}, {"sp": "N", "t": "ὁ δὲ Τίμαιος περὶ τοῦτο τὸ μέρος τῆς ἀλογίας οὐ μόνον ἀπειρίαν, ἔτι δὲ μᾶλλον ὀψιμαθίαν δοκεῖ μοι πολλὴν ἐπιφαίνειν, ὅς γε, διότι θύουσιν ἵππον, εὐθέως ὑπέλαβε τοῦτο ποιεῖν αὐτοὺς διὰ τὸ τὴν Τροίαν ἀφ’ ἵππου δοκεῖν ἑαλωκέναι. πλὴν ὅτι γε κακῶς ἱστόρηκε καὶ τὰ περὶ τὴν Λιβύην καὶ τὰ περὶ τὴν Σαρδόνα, καὶ μάλιστα τὰ κατὰ τὴν Ἰταλίαν, ἐκ τούτων ἐστὶ συμφανές, καὶ καθόλου διότι τὸ περὶ τὰς ἀνακρίσεις μέρος ἐπισέσυρται παρ’ αὐτῷ τελέως· ὅπερ ἐστὶ κυριώτατον τῆς ἱστορίας. ἐπειδὴ γὰρ αἱ μὲν πράξεις ἅμα πολλαχῇ συντελοῦνται, παρεῖναι δὲ τὸν αὐτὸν ἐν πλείοσι τόποις κατὰ τὸν αὐτὸν καιρὸν ἀδύνατον, ὁμοίως γε μὴν οὐδ’ αὐτόπτην γενέσθαι πάντων τῶν κατὰ τὴν οἰκουμένην τόπων καὶ τῶν ἐν τοῖς τόποις ἰδιωμάτων τὸν ἕνα δυνατόν, καταλείπεται πυνθάνεσθαι μὲν ὡς παρὰ πλείστων, πιστεύειν δὲ τοῖς ἀξίοις πίστεως, κριτὴν δ’ εἶναι τῶν προσπιπτόντων μὴ κακόν.", "st": "12.4c"}, {"sp": "N", "t": "ἐν ᾧ γένει μεγίστην ἐπίφασιν ἕλκων Τίμαιος πλεῖστον ἀπολείπεσθαί μοι δοκεῖ τῆς ἀληθείας· τοσοῦτο γὰρ ἀπέχει τοῦ δι’ ἑτέρων ἀκριβῶς τὴν ἀλήθειαν ἐξετάζειν ὡς οὐδὲ τούτων ὧν αὐτόπτης γέγονε καὶ ἐφ’ οὓς αὐτὸς ἥκει τόπους, οὐδὲ περὶ τούτων οὐδὲν ὑγιὲς ἡμῖν ἐξηγεῖται. τοῦτο δ’ ἔσται δῆλον, ἐὰν ἐν τοῖς κατὰ τὴν Σικελίαν δείξωμεν αὐτὸν ἀγνοοῦντα περὶ ὧν ἀποφαίνεται· σχεδὸν γὰρ οὐ πολλῶν ἔτι προσδεήσει λόγων ὑπέρ γε τῆς ψευδολογίας, ἐὰν ἐν οἷς ἔφυ καὶ ἐτράφη τόποις, καὶ τούτων ἐν τοῖς ἐπιφανεστάτοις [ἐν τούτοις] ἀγνοῶν εὑρεθῇ καὶ παραπαίων τῆς ἀληθείας. φησὶ τοιγαροῦν τὴν Ἀρέθουσαν κρήνην τὴν ἐν ταῖς Συρακούσαις ἔχειν τὰς πηγὰς ἐκ τοῦ κατὰ Πελοπόννησον διά τε τῆς Ἀρκαδίας καὶ διὰ τῆς Ὀλυμπίας ῥέοντος [ποταμοῦ] Ἀλφειοῦ· ἐκεῖνον γὰρ δύντα κατὰ γῆς καὶ τετρακισχιλίους σταδίους ὑπὸ τὸ Σικελικὸν ἐνεχθέντα πέλαγος ἀναδύνειν ἐν ταῖς Συρακούσαις, γενέσθαι δὲ τοῦτο δῆλον ἐκ τοῦ κατά τινα χρόνον οὐρανίων ὄμβρων ῥαγέντων κατὰ τὸν τῶν Ὀλυμπίων καιρὸν καὶ τοῦ ποταμοῦ τοὺς κατὰ τὸ τέμενος ἐπικλύσαντος τόπους, ὄνθου τε πλῆθος ἀναβλύζειν τὴν Ἀρέθουσαν ἐκ τῶν κατὰ τὴν πανήγυριν θυομένων βοῶν καὶ φιάλην χρυσῆν ἀναβαλεῖν, ἣν ἐπιγνόντες εἶναι τῆς ἑορτῆς ἀνείλοντο.", "st": "12.4d"}, {"sp": "N", "t": "ἐμοὶ δὴ συμβαίνει καὶ παραβεβληκέναι πλεονάκις εἰς τὴν τῶν Λοκρῶν πόλιν καὶ παρεσχῆσθαι χρείας αὐτοῖς ἀναγκαίας· καὶ γὰρ τῆς εἰς Ἰβηρίαν στρατείας αὐτοὺς παραλυθῆναι συνέβη δι’ ἐμὲ καὶ τῆς εἰς Δαλματεῖς, ἣν ὤφειλον κατὰ θάλατταν ἐκπέμπειν Ῥωμαίοις κατὰ τὰς συνθήκας. ἐξ ὧν καὶ κακοπαθείας καὶ κινδύνου καὶ δαπάνης ἱκανῆς τινος ἀπολυθέντες πᾶσιν ἡμᾶς ἠμείψαντο τοῖς τιμίοις καὶ φιλανθρώποις· διόπερ ὀφείλω μᾶλλον εὐλογεῖν Λοκροὺς ἢ τοὐναντίον. ἀλλ’ ὅμως οὐκ ὤκνησα καὶ λέγειν καὶ γράφειν ὅτι τὴν ὑπ’ Ἀριστοτέλους παραδιδομένην ἱστορίαν περὶ τῆς ἀποικίας ἀληθινωτέραν εἶναι συμβαίνει τῆς ὑπὸ Τιμαίου λεγομένης. σύνοιδα γὰρ τοῖς ἀνθρώποις ὁμολογοῦσιν ὅτι παραδόσιμος αὐτοῖς ἐστιν αὕτη περὶ τῆς ἀποικίας ἡ φήμη παρὰ πατέρων, ἣν Ἀριστοτέλης εἴρηκεν, οὐ Τίμαιος. καὶ τούτων γε τοιαύτας ἔφερον ἀποδείξεις. πρῶτον μὲν ὅτι πάντα τὰ διὰ προγόνων ἔνδοξα παρ’ αὐτοῖς ἀπὸ τῶν γυναικῶν, οὐκ ἀπὸ τῶν ἀνδρῶν ἐστιν, οἷον εὐθέως εὐγενεῖς παρὰ σφίσι νομίζεσθαι τοὺς ἀπὸ τῶν ἑκατὸν οἰκιῶν λεγομένους· ταύτας δ’ εἶναι τὰς ἑκατὸν οἰκίας τὰς προκριθείσας ὑπὸ τῶν Λοκρῶν πρὶν ἢ τὴν ἀποικίαν ἐξελθεῖν, ἐξ ὧν ἔμελλον οἱ Λοκροὶ κατὰ τὸν χρησμὸν κληροῦν τὰς ἀποσταλησομένας παρθένους εἰς Ἴλιον. τούτων δή τινας τῶν γυναικῶν συνεξᾶραι μετὰ τῆς ἀποικίας, ὧν τοὺς ἀπογόνους ἔτι νῦν εὐγενεῖς νομίζεσθαι καὶ καλεῖσθαι τοὺς ἀπὸ τῶν ἑκατὸν οἰκιῶν. πάλιν ὑπὲρ τῆς φιαληφόρου παρ’ αὐτοῖς λεγομένης τοιαύτη τις ἱστορία παραδέδοτο, διότι καθ’ ὃν καιρὸν τοὺς Σικελοὺς ἐκβάλοιεν τοὺς κατασχόντας τὸν τόπον τοῦτον τῆς Ἰταλίας, ὧν καὶ ταῖς θυσίαις προηγεῖτο τῶν ἐνδοξοτάτων καὶ τῶν εὐγενεστάτων ὑπάρχων παῖς, αὐτοὶ καὶ πλείω τῶν Σικελικῶν ἐθῶν παραλαβόντες διὰ τὸ μηδὲν αὐτοῖς πάτριον ὑπάρχειν καὶ τοῦτο διαφυλάττοιεν ἀπ’ ἐκείνων, αὐτὸ δὲ τοῦτο διορθώσαιντο, τὸ μὴ παῖδα ποιεῖν ἐξ αὑτῶν τὸν φιαληφόρον, ἀλλὰ παρθένον, διὰ τὴν ἀπὸ τῶν γυναικῶν εὐγένειαν.", "st": "12.5"}, {"sp": "N", "t": "συνθῆκαι δὲ πρὸς μὲν τοὺς κατὰ τὴν Ἑλλάδα Λοκροὺς οὔτ’ ἦσαν οὔτ’ ἐλέγοντο παρ’ αὐτοῖς γεγονέναι, πρὸς μέντοι Σικελοὺς πάντες εἶχον ἐν παραδόσει. περὶ ὧν ἔλεγον διότι, καθ’ ὃν καιρὸν ἐκ τῆς πρώτης παρουσίας καταλάβοιεν Σικελοὺς κατέχοντας ταύτην τὴν χώραν, ἐν ᾗ νῦν κατοικοῦσι, καταπλαγέντων αὐτοὺς ἐκείνων καὶ προσδεξαμένων διὰ τὸν φόβον, ὁμολογίας ποιήσαιντο τοιαύτας, ἦ μὴν εὐνοήσειν αὐτοῖς καὶ κοινῇ τὴν χώραν ἕξειν, ἕως ἂν ἐπιβαίνωσι τῇ γῇ ταύτῃ καὶ τὰς κεφαλὰς ἐπὶ τοῖς ὤμοις φορῶσι. τοιούτων δὲ τῶν ὅρκων γινομένων φασὶ τοὺς Λοκροὺς εἰς μὲν τὰ πέλματα τῶν ὑποδημάτων ἐμβαλόντας γῆν, ἐπὶ δὲ τοὺς ὤμους σκόρδων κεφαλὰς ἀφανεῖς ὑποθεμένους οὕτως ποιήσασθαι τοὺς ὅρκους, κἄπειτα τὴν μὲν γῆν ἐκβαλόντας ἐκ τῶν ὑποδημάτων, τὰς δὲ κεφαλὰς τῶν σκόρδων ἀπορρίψαντας μετ’ οὐ πολὺ καιροῦ παραπεσόντος ἐκβαλεῖν τοὺς Σικελοὺς ἐκ τῆς χώρας. ταῦτα μὲν οὖν λέγεται παρὰ Λοκροῖς. —", "st": "12.6"}, {"sp": "N", "t": "ἐκ τούτων ἄν τις συλλογιζόμενος Ἀριστοτέλει πρόσσχοι μᾶλλον ἢ Τιμαίῳ· καὶ μὴν τὸ συνεχὲς τούτῳ τελέως ἄτοπον· τὸ γὰρ ὑπολαμβάνειν, καθάπερ ἐκεῖνος ὑποδείκνυσιν, ὡς οὐκ εἰκὸς ἦν τοὺς οἰκέτας τῶν Λακεδαιμονίοις συμμαχησάντων τὴν τῶν κυρίων εὔνοιαν ἀναφέρειν πρὸς τοὺς ἐκείνων φίλους εὔηθες· οὐ γὰρ μόνον τὰς εὐνοίας, ἀλλὰ καὶ τὰς ξενίας καὶ τὰς συγγενείας τῶν δεσποτῶν οἱ δουλεύσαντες, ὅταν εὐτυχήσωσι παραδόξως καὶ χρόνος ἐπιγένηται, πειρῶνται προσποιεῖσθαι καὶ συνανανεοῦσθαι τῶν κατὰ φύσιν ἀναγκαίων μᾶλλον, αὐτῷ τούτῳ σπουδάζοντες τὴν προγεγενημένην περὶ αὐτοὺς ἐλάττωσιν καὶ τὴν ἀδοξίαν ἐξαλείφειν, τῷ βούλεσθαι τῶν δεσποτῶν ἀπόγονοι μᾶλλον ἐπιφαίνειν ἤπερ ἀπελεύθεροι.", "st": "12.6"}, {"sp": "N", "t": "τοῦτο δὲ μάλιστα περὶ τοὺς Λοκροὺς εἰκός ἐστι γεγονέναι· πολὺ γὰρ ἐκτοπίσαντες ἐκ τῶν συνειδότων καὶ προσλαβόντες συνεργὸν τὸν χρόνον, οὐχ οὕτως ἄφρονες ἦσαν ὥστε ταῦτ’ ἐπιτηδεύειν, δι’ ὧν ἔμελλον ἀνανέωσιν ποιεῖσθαι τῶν ἰδίων ἐλαττωμάτων, ἀλλὰ μὴ τοὐναντίον δι’ ὧν ἐπικαλύψειν ταῦτα. διὸ καὶ τὴν ὀνομασίαν τῇ πόλει τὴν ἀπὸ τῶν γυναικῶν εἰκότως ἐπέθεσαν καὶ τὴν οἰκειότητα τὴν κατὰ τὰς γυναῖκας προσεποιήθησαν, ἔτι δὲ τὰς φιλίας καὶ τὰς συμμαχίας τὰς προγονικὰς τὰς ἀπὸ τῶν γυναικῶν ἀνενεοῦντο. ᾗ καὶ τὸ τοὺς Ἀθηναίους πορθῆσαι τὴν χώραν αὐτῶν οὐδέν ἐστι σημεῖον ψευδῆ λέγειν τὸν Ἀριστοτέλην· εὐλόγου γὰρ ὄντος ἐκ τῶν προειρημένων, εἰ καὶ δεκάκις ἦσαν οἰκέται, τοῦ προσπεποιῆσθαι τὴν τῶν Λακεδαιμονίων φιλίαν τοὺς ἐξάραντας ἐκ τῶν Λοκρῶν καὶ κατασχόντας εἰς τὴν Ἰταλίαν, εὔλογος γίνεται καὶ [ἡ] τῶν Ἀθηναίων ἀλλοτριότης ἡ πρὸς πάντας τοὺς προειρημένους, οὐχ οὕτως ἐξεταζόντων τὸ γένος ὡς τὴν προαίρεσιν. νὴ Δί’ ἀλλὰ πῶς αὐτοὶ μὲν ἐξαπέστελλον οἱ Λακεδαιμόνιοι τοὺς ἀκμάζοντας εἰς τὴν πατρίδα τεκνοποιίας χάριν, τοὺς δὲ Λοκροὺς τὸ παραπλήσιον οὐκ εἴων ποιεῖν; ἕκαστα δὲ τούτων οὐ μόνον κατὰ τὸ πιθανόν, ἀλλὰ καὶ κατὰ τὴν ἀλήθειαν μεγάλην ἔχει διαφοράν. οὔτε γὰρ κωλύειν τοὺς Λοκροὺς ἔμελλον, αὐτοὶ τὸ ὅμοιον ποιοῦντες — ἄτοπον γάρ — οὐδὲ μὴν κελευόντων αὐτῶν οἱ Λοκροὶ πάντως ποιήσειν ἐκείνοις τὸ παραπλήσιον. παρὰ μὲν γὰρ τοῖς Λακεδαιμονίοις καὶ πάτριον ἦν καὶ σύνηθες τρεῖς ἄνδρας ἔχειν τὴν γυναῖκα καὶ τέτταρας, τοτὲ δὲ καὶ πλείους ἀδελφοὺς ὄντας, καὶ τὰ τέκνα τούτων εἶναι κοινά, καὶ γεννήσαντα παῖδας ἱκανοὺς ἐκδόσθαι γυναῖκά τινι τῶν φίλων καλὸν καὶ σύνηθες. διόπερ οἱ Λοκροὶ μήτε ταῖς ἀραῖς ὄντες ἔνοχοι μήτε τοῖς ὅρκοις, οἷς ὤμοσαν οἱ Λακεδαιμόνιοι μὴ πρότερον εἰς τὴν οἰκείαν ἐπανήξειν πρὶν ἢ τὴν Μεσσήνην κατὰ κράτος ἑλεῖν, τῆς μὲν κατὰ τὸ κοινὸν ἐξαποστολῆς εὐλόγως οὐ μετέσχον, κατὰ δὲ μέρος τὰς ἐπανόδους ποιούμενοι καὶ σπανίως ἔδοσαν ἀναστροφὴν ταῖς γυναιξὶ πρὸς οἰκέτας γενέσθαι συνηθεστέραν ἢ πρὸς τοὺς ἐξ ἀρχῆς ἄνδρας, ταῖς δὲ παρθένοις καὶ μᾶλλον· ὃ καὶ τῆς ἐξαναστάσεως αἴτιον γέγονεν. —", "st": "12.6"}, {"sp": "N", "t": "ὅτι πολλὰ ἱστορεῖ ψευδῆ ὁ Τίμαιος, καὶ δοκεῖ τὸ παράπαν οὐκ ἄπειρος ὢν οὐδενὸς τῶν τοιούτων, ὑπὸ δὲ τῆς φιλονεικίας ἐπισκοτούμενος, ὅταν ἅπαξ ἢ ψέγειν ἢ τοὐναντίον ἐγκωμιάζειν τινὰ πρόθηται, πάντων ἐπιλανθάνεται καὶ πολύ τι τοῦ καθήκοντος παρεκβαίνει. πλὴν ταῦτα μὲν ἡμῖν ὑπὲρ Ἀριστοτέλους εἰρήσθω πῶς καὶ τίσι προσέχων τοιαύτην ἐποιήσατο τὴν περὶ τῶν Λοκρῶν ἐξήγησιν· τὰ δὲ λέγεσθαι μέλλοντα περὶ Τιμαίου καὶ τῆς ὅλης συντάξεως αὐτοῦ καὶ καθόλου περὶ τοῦ καθήκοντος τοῖς πραγματευομένοις ἱστορίαν τοιάνδε τινὰ λήψεται τὴν ἀπάντησιν. ὅτι μὲν οὖν ἀμφότεροι κατὰ τὸν εἰκότα λόγον πεποίηνται τὴν ἐπιχείρησιν, καὶ διότι πλείους εἰσὶ πιθανότητες ἐν τῇ κατ’ Ἀριστοτέλην ἱστορίᾳ, δοκῶ, πᾶς ἄν τις ἐκ τῶν εἰρημένων ὁμολογήσειεν· ἀληθὲς μέντοι γε καὶ καθάπαξ διαστεῖλαι περί τινος οὐδὲν ἔστιν ἐν τούτοις. οὐ μὴν ἀλλ’ ἔστω τὸν Τίμαιον εἰκότα λέγειν μᾶλλον. διὰ ταύτην οὖν τὴν αἰτίαν δεήσει πᾶν ῥῆμα καὶ πᾶσαν φωνὴν ἀκούειν καὶ μόνον οὐ θανάτου κρίσιν ὑπέχειν τοὺς ἐν ταῖς ἱστορίαις ἧττον εἰκότα λέγοντας; οὐ δήπου. τοῖς μὲν γὰρ κατ’ ἄγνοιαν ψευδογραφοῦσιν ἔφαμεν δεῖν διόρθωσιν εὐμενικὴν καὶ συγγνώμην ἐξακολουθεῖν, τοῖς δὲ κατὰ προαίρεσιν ἀπαραίτητον κατηγορίαν.", "st": "12.7"}, {"sp": "N", "t": "ἢ δεικτέον οὖν τὸν Ἀριστοτέλην κατὰ τὸν ἄρτι λόγον τὰ περὶ Λοκρῶν εἰρηκότα χάριτος ἢ κέρδους ἢ διαφορᾶς ἕνεκεν ἢ μηδὲ τολμῶντας τοῦτο λέγειν ὁμολογητέον ἀγνοεῖν καὶ παραπαίειν τοὺς τοιαύτῃ χρωμένους ἀπεχθείᾳ καὶ πικρίᾳ κατὰ τῶν πέλας οἵᾳ κέχρηται Τίμαιος κατ’ Ἀριστοτέλους. φησὶ γὰρ αὐτὸν εἶναι θρασύν, εὐχερῆ, προπετῆ, πρὸς δὲ τούτοις κατατετολμηκέναι τῆς τῶν Λοκρῶν πόλεως, εἰπόντα τὴν ἀποικίαν αὐτῶν εἶναι δραπετῶν, οἰκετῶν, μοιχῶν, ἀνδραποδιστῶν. καὶ ταῦτα λέγειν αὐτόν φησιν οὕτως ἀξιοπίστως ὥστε δοκεῖν ἕνα τῶν ἐστρατηγηκότων ὑπάρχειν καὶ τοὺς Πέρσας ἐν ταῖς Κιλικίαις πύλαις ἄρτι παρατάξει νενικηκότα διὰ τῆς αὑτοῦ δυνάμεως, ἀλλ’ οὐ σοφιστὴν ὀψιμαθῆ καὶ μισητὸν ὑπάρχοντα καὶ τὸ πολυτίμητον ἰατρεῖον ἀρτίως ἀποκεκλεικότα, πρὸς δὲ τούτοις εἰς πᾶσαν αὐλὴν καὶ σκηνὴν ἐμπεπηδηκότα, πρὸς δὲ γαστρίμαργον, ὀψαρτυτήν, ἐπὶ στόμα φερόμενον ἐν πᾶσι. δοκεῖ δή μοι τὰ τοιαῦτα μόλις ἂν ἄνθρωπος ἀγύρτης καὶ προπετὴς ἐπὶ δικαστηρίου ῥιψολογῶν ἀνεκτὸς φανῆναι· μέτριος μὲν γὰρ οὐ δοκεῖ. συγγραφεὺς δὲ κοινῶν πράξεων καὶ προστάτης ἱστορίας ἀληθινὸς οὐδ’ ἂν αὐτὸς ἐν αὑτῷ διανοηθῆναι μή τι δὴ καὶ γράφειν τολμήσαι τοιοῦτον.", "st": "12.8"}, {"sp": "N", "t": "σκεψώμεθα δὴ καὶ τὴν αὐτοῦ τοῦ Τιμαίου προαίρεσιν, καὶ τὰς ἀποφάσεις συγκρίνωμεν ἐκ παραθέσεως, ἃς πεποίηται περὶ τῆς αὐτῆς ἀποικίας, ἵνα γνῶμεν πότερος ἄξιος ἔσται τῆς τοιαύτης κατηγορίας. φησὶ τοιγαροῦν κατὰ τὴν αὐτὴν βύβλον, οὐκέτι κατὰ τὸν αὐτὸν εἰκότα λόγον χρώμενος τοῖς ἐλέγχοις, ἀλλ’ ἀληθινῶς αὐτὸς ἐπιβαλὼν εἰς τοὺς κατὰ τὴν Ἑλλάδα Λοκρούς, ἐξετάζειν τὰ περὶ τῆς ἀποικίας. τοὺς δὲ πρῶτον μὲν ἐπιδεικνύειν αὐτῷ συνθήκας ἐγγράπτους, ἔτι καὶ νῦν διαμενούσας, πρὸς τοὺς ἐξαπεσταλμένους, αἷς ὑπογεγράφθαι τὴν ἀρχὴν τοιαύτην \"ὡς γονεῦσι πρὸς τέκνα. \" πρὸς δὲ τούτοις εἶναι δόγματα, καθ’ ἃ πολιτείαν ὑπάρχειν ἑκατέροις παρ’ ἑκατέροις. καθόλου διακούοντας τὴν Ἀριστοτέλους ἐξήγησιν περὶ τῆς ἀποικίας θαυμάζειν τὴν ἰταμότητα τοῦ συγγραφέως. μεταβὰς δὲ πάλιν ἐπὶ τοὺς ἐν Ἰταλίᾳ Λοκροὺς εὑρίσκειν ἀκολούθους καὶ τοὺς νόμους φησὶ τοὺς παρ’ αὐτοῖς καὶ τοὺς ἐθισμοὺς οὐ τῇ τῶν οἰκετῶν ῥᾳδιουργίᾳ, τῇ δὲ τῶν ἐλευθέρων ἀποικίᾳ· πάντως γὰρ καὶ τοῖς ἀνδραποδισταῖς ἐπιτίμια τετάχθαι παρ’ αὐτοῖς, ὁμοίως τοῖς μοιχοῖς, τοῖς δραπέταις· ὧν οὐδὲν ἂν ὑπάρχειν, εἰ συνῄδεισαν αὑτοῖς ἐκ τοιούτων πεφυκόσι.", "st": "12.9"}, {"sp": "N", "t": "πρῶτον δὴ διαπορήσαι τις ἂν πρὸς τίνας τῶν Λοκρῶν παραγενόμενος ἐπυνθάνετο περὶ τούτων. εἰ μὲν γὰρ συνέβαινε, καθάπερ τοὺς ἐν Ἰταλίᾳ Λοκρούς, οὕτω καὶ τοὺς κατὰ τὴν Ἑλλάδα μίαν πόλιν ἔχειν, τάχ’ ἂν οὐκ ἔδει διαπορεῖν, ἀλλ’ ἦν ἂν εὐθεώρητον· ἐπεὶ δὲ δύ’ ἔθνη Λοκρῶν ἐστι, πρὸς ποτέρους ἦλθε καὶ πρὸς ποίας πόλεις τῶν ἑτέρων, καὶ παρὰ τίσιν εὗρε τὰς συνθήκας ἀναγεγραμμένας; οὐδὲν γὰρ ἡμῖν διασαφεῖται τούτων. καίτοι διότι τοῦτ’ ἴδιόν ἐστι Τιμαίου καὶ ταύτῃ παρημίλληται τοὺς ἄλλους συγγραφέας καὶ καθόλου τῇδέ πῃ τῆς ἀποδοχῆς — λέγω δὲ κατὰ τὴν ἐν τοῖς χρόνοις καὶ ταῖς ἀναγραφαῖς ἐπίφασιν τῆς ἀκριβείας καὶ τὴν περὶ τοῦτο τὸ μέρος ἐπιμέλειαν — δοκῶ, πάντες γινώσκομεν. διὸ καὶ θαυμάζειν ἐστὶν ἄξιον πῶς οὔτε τὸ τῆς πόλεως ὄνομα, παρ’ οἷς εὗρεν, οὔτε τὸν τόπον, ἐν ᾧ συμβαίνει τὴν συνθήκην ἀναγεγράφθαι, διεσάφησεν ἡμῖν, οὔτε τοὺς ἄρχοντας τοὺς δείξαντας αὐτῷ τὴν ἀναγραφὴν καὶ πρὸς οὓς ἐποιεῖτο τὸν λόγον, ἵνα μηδενὶ διαπορεῖν ἐξῇ μηδέν, ἀλλ’ ὡρισμένου τοῦ τόπου καὶ τῆς πόλεως ἐνῇ τοῖς ἀμφισβητοῦσιν εὑρεῖν τὴν ἀκρίβειαν. ὁ δὲ πάντα ταῦτα παραλελοιπὼς δῆλός ἐστι συνειδὼς αὑτῷ κατὰ πρόθεσιν ἐψευσμένῳ. διότι γὰρ τῶν τοιούτων ἐπιλαβόμενος οὐδὲν ἂν παρέλειπε Τίμαιος, ἀλλ’ ἀπρίξ, τὸ δὴ λεγόμενον, ἀμφοῖν τοῖν χεροῖν ἐπέφυ, προφανὲς ἐκ τούτων. ὁ γὰρ πρὸς τὴν Ἐχεκράτους πίστιν ἀπερεισάμενος ἐπ’ ὀνόματος, πρὸς ὅν φησι περὶ τῶν ἐν Ἰταλίᾳ Λοκρῶν ποιήσασθαι τοὺς λόγους καὶ παρ’ οὗ πυθέσθαι περὶ τούτων, καὶ προσεξειργασμένος, ἵνα μὴ φανῇ τοῦ τυχόντος ἀκηκοὼς ὅτι συνέβαινε τὸν τούτου πατέρα πρεσβείας κατηξιῶσθαι πρότερον ὑπὸ Διονυσίου, ἦ πού γ’ ἂν οὗτος δημοσίας ἀναγραφῆς ἐπιλαβόμενος ἢ παραδοσίμου στήλης παρεσιώπησεν;", "st": "12.10"}, {"sp": "N", "t": "ὁ γὰρ τὰς συγκρίσεις ποιούμενος ἀνέκαθεν τῶν ἐφόρων πρὸς τοὺς βασιλεῖς τοὺς ἐν Λακεδαίμονι καὶ τοὺς ἄρχοντας τοὺς Ἀθήνησι καὶ τὰς ἱερείας τὰς ἐν Ἄργει παραβάλλων πρὸς τοὺς ὀλυμπιονίκας, καὶ τὰς ἁμαρτίας τῶν πόλεων περὶ τὰς ἀναγραφὰς τὰς τούτων ἐξελέγχων, παρὰ τρίμηνον ἐχούσας τὸ διαφέρον, οὗτός ἐστι. καὶ μὴν ὁ τὰς ὀπισθοδόμους στήλας καὶ τὰς ἐν ταῖς φλιαῖς τῶν νεῶν προξενίας ἐξευρηκὼς Τίμαιός ἐστιν. ὃν οὔθ’ ὑπάρχον τι τῶν τοιούτων ἀγνοεῖν οὔθ’ εὑρόντα παραλιπεῖν πιστευτέον οὔτε ψευσαμένῳ συγγνώμην δοτέον οὐδαμῶς· πικρὸς γὰρ γεγονὼς καὶ ἀπαραίτητος ἐπιτιμητὴς τῶν πέλας εἰκότως ἂν καὶ ὑπὸ τῶν πλησίον αὐτὸς ἀπαραιτήτου τυγχάνοι κατηγορίας. οὐ μὴν ἀλλὰ προφανῶς ἐν τούτοις ἐψευσμένος, μεταβὰς ἐπὶ τοὺς ἐν Ἰταλίᾳ Λοκροὺς πρῶτον μέν φησι τήν τε πολιτείαν καὶ τὰ λοιπὰ φιλάνθρωπα τοῖς Λοκροῖς ἀμφοτέροις Ἀριστοτέλη καὶ Θεόφραστον κατεψεῦσθαι τῆς πόλεως. ἐγὼ δ’ οὐκ ἀγνοῶ μὲν ὅτι καὶ ταύτῃ τῆς πραγματείας ἀναγκασθήσομαι παρεκβαίνειν, διοριζόμενος καὶ διαβεβαιούμενος περὶ τούτων· οὐ μὴν ἀλλὰ διὰ ταύτην τὴν αἰτίαν εἰς ἕνα τόπον ὑπερεθέμην τὸν περὶ Τιμαίου λόγον, ἵνα μὴ πολλάκις ἀναγκάζωμαι τοῦ καθήκοντος ὀλιγωρεῖν. — ὅτι Τίμαιός φησι μέγιστον ἁμάρτημα περὶ τὴν ἱστορίαν εἶναι τὸ ψεῦδος· διὸ καὶ παραινεῖ τούτοις, οὓς ἂν ἐξελέγξῃ διεψευσμένους ἐν τοῖς συγγράμμασιν, ἕτερόν τι ζητεῖν ὄνομα τοῖς βυβλίοις, πάντα δὲ μᾶλλον ἢ καλεῖν ἱστορίαν. —", "st": "12.11"}, {"sp": "N", "t": "καθάπερ γὰρ ἐπὶ τῶν κανόνων, κἂν ἐλάττων ᾖ τῷ μήκει κἂν τῷ πλάτει ταπεινότερος, μετέχῃ δὲ τῆς τοῦ κανόνος ἰδιότητος, κανόνα φησὶ δεῖν προσαγορεύειν ὅμως, ὅταν δὲ τῆς εὐθείας καὶ τῆς πρὸς ταύτην οἰκειότητος ἐκπέσῃ, πάντα μᾶλλον δεῖν ἢ κανόνα καλεῖν, τὸν αὐτὸν τρόπον καὶ τῶν συγγραμμάτων ὅσα μὲν ἂν ἢ κατὰ τὴν λέξιν ἢ κατὰ τὸν χειρισμὸν ἢ κατ’ ἄλλο τι διαμαρτάνηται τῶν ἰδίων μερῶν, ἀντέχηται δὲ τῆς ἀληθείας, προσίεσθαί φησι τὸ τῆς ἱστορίας ὄνομα τὰς βύβλους, ὅταν δὲ ταύτης παραπέσῃ, μηκέτι καλεῖσθαι δεῖν ἱστορίαν. ἐγὼ δὲ διότι μὲν ἡγεῖσθαι δεῖ τῶν τοιούτων συγγραμμάτων τὴν ἀλήθειαν ὁμολογῶ, καὶ κατὰ τὴν πραγματείαν αὐτός που κέχρημαι λέγων οὕτως, ὅτι, καθάπερ ἐμψύχου σώματος τῶν ὄψεων ἐξαιρεθεισῶν ἀχρειοῦται τὸ ὅλον, οὕτως ἐξ ἱστορίας ἐὰν ἄρῃς τὴν ἀλήθειαν, τὸ καταλειπόμενον αὐτῆς ἀνωφελὲς γίνεται διήγημα. — δύο μέντοι τρόπους ἔφαμεν εἶναι ψεύδους, ἕνα μὲν τὸν κατ’ ἄγνοιαν, ἕτερον δὲ τὸν κατὰ προαίρεσιν, καὶ τούτων δεῖν τοῖς μὲν κατ’ ἄγνοιαν παραπαίουσι τῆς ἀληθείας διδόναι συγγνώμην, τοῖς δὲ κατὰ προαίρεσιν ἀκαταλλάκτως ἔχειν. — τούτων δ’ ἡμῖν ὁμολογουμένων, αὐτοῦ τούτου τοῦ ψεύδους μεγάλην ὑπολαμβάνω διαφορὰν εἶναι τοῦ κατ’ ἄγνοιαν γινομένου καὶ τοῦ κατὰ προαίρεσιν, καὶ τὸ μὲν ἐπιδέχεσθαι συγγνώμην καὶ διόρθωσιν εὐμενικήν, τὸ δ’ ἀπαραιτήτου δικαίως ἂν τυγχάνειν κατηγορίας· ᾧ γένει μάλιστ’ ἂν εὕροι τις ἔνοχον αὐτὸν ὄντα τὸν Τίμαιον· διότι δ’ ἐστὶ τοιοῦτος σκοπεῖν ἤδη πάρεστιν. —", "st": "12.12"}, {"sp": "N", "t": "ἐπὶ τῶν ἀθετούντων τὰς ὁμολογίας προφερόμεθα ταύτην τὴν παροιμίαν \"Λοκροὶ τὰς συνθήκας.\" τοῦτο δέ τις ἐξεύρηκεν ὅτι καὶ παρὰ τοῖς συγγραφεῦσι καὶ παρὰ τοῖς ἄλλοις ἀνθρώποις ὁμολογούμενόν ἐστι, διότι κατὰ τὴν τῶν Ἡρακλειδῶν ἔφοδον συνθεμένων τῶν Λοκρῶν τοῖς Πελοποννησίοις πολεμίους πυρσοὺς αἴρειν, ἐὰν συμβῇ τοὺς Ἡρακλείδας μὴ κατὰ τὸν Ἰσθμόν, ἀλλὰ κατὰ τὸ Ῥίον ποιεῖσθαι τὴν διάβασιν, χάριν τοῦ προαισθομένους φυλάξασθαι τὴν ἔφοδον αὐτῶν, οὐ ποιησάντων δὲ τῶν Λοκρῶν, πᾶν δὲ τοὐναντίον φιλίους ἀράντων πυρσούς, ὅτε παρῆσαν, τοὺς μὲν Ἡρακλείδας συνέβη μετ’ ἀσφαλείας χρῆσθαι τῇ διαβάσει, τοὺς δὲ Πελοποννησίους κατολιγωρήσαντας λαθεῖν παραδεξαμένους εἰς τὴν οἰκείαν τοὺς ὑπεναντίους παρασπονδηθέντας ὑπὸ τῶν Λοκρῶν.", "st": "12.12"}, {"sp": "N", "t": "κατηγορεῖν καὶ θειασμὸν διασύρειν τῶν ὀνειρωττόντων καὶ δαιμονώντων ἐν τοῖς ὑπομνήμασιν· ὅσοι γε μὴν αὐτοὶ πολλὴν τῆς τοιαύτης ἐμπεποίηνται φλυαρίας, τοὺς τοιούτους ἀγαπᾶν ἂν δέοι μὴ τυγχάνοντας κατηγορίας, μηδ’ ὅτι καὶ τῶν ἄλλων αὐτοὺς κατατρέχειν· ὃ συμβέβηκε περὶ Τίμαιον. ἐκεῖνος γὰρ κόλακα μὲν εἶναί φησι τὸν Καλλισθένην τοιαῦτα γράφοντα καὶ πλεῖστον ἀπέχειν φιλοσοφίας, κόρδαξί τε προσέχοντα καὶ κορυβαντιώσαις γυναιξί· δικαίως δ’ αὐτὸν ὑπ’ Ἀλεξάνδρου τετευχέναι τιμωρίας διεφθαρκότα τὴν ἐκείνου ψυχὴν καθ’ ὅσον οἷός τ’ ἦν· καὶ Δημοσθένην μὲν καὶ τοὺς ἄλλους ῥήτορας τοὺς κατ’ ἐκεῖνον τὸν καιρὸν ἀκμάσαντας ἐπαινεῖ καί φησι τῆς Ἑλλάδος ἀξίους γεγονέναι, διότι ταῖς Ἀλεξάνδρου τιμαῖς ταῖς ἰσοθέοις ἀντέλεγον, τὸν δὲ φιλόσοφον αἰγίδα καὶ κεραυνὸν περιθέντα θνητῇ φύσει δικαίως αὐτὸν ὑπὸ τοῦ δαιμονίου τετευχέναι τούτων ὧν ἔτυχεν. —", "st": "12.12"}, {"sp": "N", "t": "ὅτι Τίμαιός φησι Δημοχάρην ἡταιρηκέναι μὲν τοῖς ἄνω μέρεσι τοῦ σώματος, οὐκ εἶναι δ’ ἄξιον τὸ ἱερὸν πῦρ φυσᾶν, ὑπερβεβηκέναι δὲ τοῖς ἐπιτηδεύμασι τὰ Βότρυος ὑπομνήματα καὶ τὰ Φιλαινίδος καὶ τῶν ἄλλων ἀναισχυντογράφων· ταύτην δὲ τὴν λοιδορίαν καὶ τὰς ἐμφάσεις οὐχ οἷον ἄν τις διέθετο πεπαιδευμένος ἀνήρ, ἀλλ’ οὐδὲ τῶν ἀπὸ τέγους ἀπὸ τοῦ σώματος εἰργασμένων οὐδείς. ὁ δ’ ἵνα πιστὸς φανῇ κατὰ τὴν αἰσχρολογίαν καὶ τὴν ὅλην ἀναισχυντίαν, καὶ προσκατέψευσται τἀνδρός, κωμικόν τινα μάρτυρα προσεπισπασάμενος ἀνώνυμον. πόθεν δ’ ἐγὼ καταστοχάζομαι τοῦτο; πρῶτον μὲν ἐκ τοῦ καὶ πεφυκέναι καὶ τεθράφθαι καλῶς Δημοχάρην, ἀδελφιδοῦν ὄντα Δημοσθένους, δεύτερον ἐκ τοῦ μὴ μόνον στρατηγίας αὐτὸν ἠξιῶσθαι παρ’ Ἀθηναίοις, ἀλλὰ καὶ τῶν ἄλλων τιμῶν, ὧν οὐδὲν ἂν αὐτῷ συνεξέδραμε τοιαύταις ἀτυχίαις παλαίοντι. διὸ καὶ δοκεῖ μοι Τίμαιος οὐχ οὕτως Δημοχάρους κατηγορεῖν ὡς Ἀθηναίων, εἰ τοιοῦτον ἄνδρα προῆγον καὶ τοιούτῳ τὴν πατρίδα καὶ τοὺς ἰδίους βίους ἐνεχείριζον. ἀλλ’ οὐκ ἔστι τούτων οὐδέν. οὐ γὰρ ἂν Ἀρχέδικος ὁ κωμῳδιογράφος ἔλεγε ταῦτα μόνος περὶ Δημοχάρους, ὡς Τίμαιός φησιν, ἀλλὰ πολλοὶ μὲν ἂν τῶν Ἀντιπάτρου φίλων, καθ’ οὗ πεπαρρησίασται πολλὰ καὶ δυνάμενα λυπεῖν οὐ μόνον αὐτὸν Ἀντίπατρον, ἀλλὰ καὶ τοὺς ἐκείνου διαδόχους καὶ φίλους γεγονότας, πολλοὶ δὲ τῶν ἀντιπεπολιτευμένων, ὧν ἦν καὶ Δημήτριος ὁ Φαληρεύς. οὗ ’κεῖνος οὐ τὴν τυχοῦσαν πεποίηται κατηγορίαν ἐν ταῖς ἱστορίαις, φάσκων αὐτὸν γεγονέναι τοιοῦτον προστάτην τῆς πατρίδος καὶ ἐπὶ τούτοις σεμνύνεσθαι κατὰ τὴν πολιτείαν, ἐφ’ οἷς ἂν καὶ τελώνης σεμνυνθείη βάναυσος. ἐπὶ γὰρ τῷ πολλὰ καὶ λυσιτελῶς πωλεῖσθαι κατὰ τὴν πόλιν καὶ δαψιλῆ τὰ πρὸς τὸν βίον ὑπάρχειν πᾶσιν, ἐπὶ τούτοις φησὶ μεγαλαυχεῖν αὐτόν· καὶ διότι κοχλίας αὐτομάτως βαδίζων προηγεῖτο τῆς πομπῆς αὐτῷ, σίαλον ἀναπτύων, σὺν δὲ τούτοις ὄνοι διεπέμποντο διὰ τοῦ θεάτρου, διότι δὴ πάντων τῶν τῆς Ἑλλάδος καλῶν ἡ πατρὶς παρακεχωρηκυῖα τοῖς ἄλλοις ἐποίει Κασσάνδρῳ τὸ προσταττόμενον, ἐπὶ τούτοις αὐτὸν οὐκ αἰσχύνεσθαί φησιν. ἀλλ’ ὅμως οὔτε Δημήτριος οὔτ’ ἄλλος οὐδεὶς εἰρήκει περὶ Δημοχάρους τοιοῦτον οὐδέν.", "st": "12.13"}, {"sp": "N", "t": "ἐξ ὧν ἐγώ, βεβαιοτέραν τὴν τῆς πατρίδος ἡγούμενος μαρτυρίαν ἢ τὴν Τιμαίου πικρίαν, θαρρῶν ἀποφαίνομαι μηδενὶ τὸν Δημοχάρους βίον ἔνοχον εἶναι τῶν τοιούτων κατηγορημάτων. καίπερ εἰ κατ’ ἀλήθειαν ὑπῆρχέ τι τοιοῦτον ἀτύχημα περὶ Δημοχάρην, ποῖος καιρὸς ἢ ποία πρᾶξις ἠνάγκασε Τίμαιον ταῦτα κατατάττειν εἰς τὴν ἱστορίαν; καθάπερ γὰρ οἱ νοῦν ἔχοντες, ἐπὰν ἀμύνασθαι κρίνωσι τοὺς ἐχθρούς, οὐ τοῦτο πρῶτον σκοποῦνται τί παθεῖν ἄξιός ἐστιν ὁ πλησίον, ἀλλὰ τί ποιεῖν αὐτοῖς πρέπει, τοῦτο μᾶλλον οὕτως καὶ περὶ τῶν λοιδοριῶν, οὐ τί τοῖς ἐχθροῖς ἀκούειν ἁρμόζει, τοῦτο πρῶτον ἡγητέον, ἀλλὰ τί λέγειν ἡμῖν πρέπει, τοῦτ’ ἀναγκαιότατον λογιστέον. περὶ δὲ τῶν πάντα μετρούντων ταῖς ἰδίαις ὀργαῖς καὶ φιλοτιμίαις ἀνάγκη πάνθ’ ὑποπτεύειν ἐστὶ καὶ πᾶσι διαπιστεῖν πέρα τοῦ δέοντος λεγομένοις. διὸ δὴ καὶ νῦν ἡμεῖς μὲν εἰκότως ἂν δόξαιμεν ἀθετεῖν τοῖς ὑπὸ Τιμαίου κατὰ Δημοχάρους εἰρημένοις· ἐκεῖνος δ’ ἂν οὐκ εἰκότως τυγχάνοι συγγνώμης οὐδὲ πίστεως ὑπ’ οὐδενὸς διὰ τὸ προφανῶς ἐν ταῖς λοιδορίαις ἐκπίπτειν τοῦ καθήκοντος διὰ τὴν ἔμφυτον πικρίαν.", "st": "12.14"}, {"sp": "N", "t": "καὶ γὰρ οὐδὲ ταῖς κατ’ Ἀγαθοκλέους ἔγωγε λοιδορίαις, εἰ καὶ πάντων γέγονεν ἀσεβέστατος, εὐδοκῶ. λέγω δ’ ἐν τούτοις, ἐν οἷς ἐπὶ καταστροφῇ τῆς ὅλης ἱστορίας φησὶ γεγονέναι τὸν Ἀγαθοκλέα κατὰ τὴν πρώτην ἡλικίαν κοινὸν πόρνον, ἕτοιμον τοῖς ἀκρατεστάτοις, κολοιόν, τριόρχην, πάντων τῶν βουλομένων τοῖς ὄπισθεν ἔμπροσθεν γεγονότα. πρὸς δὲ τούτοις, ὅτ’ ἀπέθανε, τὴν γυναῖκά φησι κατακλαιομένην αὐτὸν οὕτως θρηνεῖν· \"τί δ’ οὐκ ἐγὼ σέ; τί δ’ οὐκ ἐμὲ σύ; \" ἐν γὰρ τούτοις πάλιν οὐ μόνον ἄν τις ἐπιφθέγξαιτο τὰ καὶ περὶ Δημοχάρους, ἀλλὰ καὶ τὴν ὑπερβολὴν θαυμάσειε τῆς πικρίας. ὅτι γὰρ ἐκ φύσεως ἀνάγκη μεγάλα προτερήματα γεγονέναι περὶ τὸν Ἀγαθοκλέα, τοῦτο δῆλόν ἐστιν ἐξ αὐτῶν ὧν ὁ Τίμαιος ἀποφαίνεται. εἰ γὰρ εἰς τὰς Συρακούσας παρεγενήθη φεύγων τὸν τροχόν, τὸν καπνόν, τὸν πηλόν, περὶ ἔτη τὴν ἡλικίαν ὀκτωκαίδεκα γεγονώς, καὶ μετά τινα χρόνον ὁρμηθεὶς ἀπὸ τοιαύτης ὑποθέσεως κύριος μὲν ἐγενήθη πάσης Σικελίας, μεγίστους δὲ κινδύνους περιέστησε Καρχηδονίοις, τέλος ἐγγηράσας τῇ δυναστείᾳ κατέστρεψε τὸν βίον βασιλεὺς προσαγορευόμενος, ἆρ’ οὐκ ἀνάγκη μέγα τι γεγονέναι χρῆμα καὶ θαυμάσιον τὸν Ἀγαθοκλέα καὶ πολλὰς ἐσχηκέναι ῥοπὰς καὶ δυνάμεις πρὸς τὸν πραγματικὸν τρόπον; ὑπὲρ ὧν δεῖ τὸν συγγραφέα μὴ μόνον τὰ πρὸς διαβολὴν κυροῦντα καὶ κατηγορίαν ἐξηγεῖσθαι τοῖς ἐπιγινομένοις, ἀλλὰ καὶ τὰ πρὸς ἔπαινον ἥκοντα περὶ τὸν ἄνδρα· τοῦτο γὰρ ἴδιόν ἐστι τῆς ἱστορίας. ὁ δ’ ἐπεσκοτημένος ὑπὸ τῆς ἰδίας πικρίας τὰ μὲν ἐλαττώματα δυσμενικῶς καὶ μετ’ αὐξήσεως ἡμῖν ἐξήγγελκε, τὰ δὲ κατορθώματα συλλήβδην παραλέλοιπεν, ἀγνοῶν ὅτι τὸ ψεῦδος οὐχ ἧττόν ἐστι περὶ τοὺς τὰ γεγονότα γράφοντας ἐν ταῖς ἱστορίαις. ἡμεῖς δὲ τὸ μὲν ἐπιμετρεῖν τῆς ἀπεχθείας αὐτοῦ χάριν ἀφήκαμεν, τὰ δ’ οἰκεῖα τῆς προθέσεως αὑτῶν οὐ παρελείψαμεν. —", "st": "12.15"}, {"sp": "N", "t": "νεανίσκων δυεῖν περί τινος οἰκέτου διαφερομένων συνέβαινε παρὰ μὲν τὸν ἕτερον καὶ πλείω χρόνον γεγονέναι τὸν παῖδα, τὸν δ’ ἕτερον ἡμέραις δυσὶ πρότερον εἰς τὸν ἀγρὸν ἐλθόντα μὴ παρόντος τοῦ δεσπότου μετὰ βίας εἰς οἶκον ἀπηχέναι τὸν δοῦλον, κἄπειτα τὸν ἕτερον αἰσθόμενον ἐλθεῖν ἐπὶ τὴν οἰκίαν, καὶ λαβόντ’ ἀπάγειν ἐπὶ τὴν ἀρχήν, καὶ φάναι δεῖν κύριον αὐτὸν εἶναι διδόντα τοὺς ἐγγυητάς· κελεύειν γὰρ τὸν Ζαλεύκου νόμον τοῦτον δεῖν κρατεῖν τῶν ἀμφισβητουμένων ἕως τῆς κρίσεως παρ’ οὗ τὴν ἀγωγὴν συμβαίνει γίνεσθαι. τοῦ δ’ ἑτέρου κατὰ τὸν αὐτὸν νόμον παρ’ αὑτοῦ φάσκοντος γεγονέναι τὴν ἀγωγήν — ἐκ γὰρ τῆς οἰκίας τῆς ἐκείνου τὸ σῶμα πρὸς τὴν ἀρχὴν ἥκειν ἀπαγόμενον — τοὺς προκαθημένους ἄρχοντας διαποροῦντας ὑπὲρ τοῦ πράγματος ἐπισπάσασθαι καὶ συμμεταδοῦναι τῷ κοσμοπόλιδι. τὸν δὲ διαστείλασθαι τὸν νόμον, φήσαντα παρὰ τούτων τὴν ἀγωγὴν αἰεὶ γίνεσθαι, παρ’ οἷς ἂν ἔσχατον ἀδήριτον ᾖ χρόνον τινὰ γεγονὸς τὸ διαμφισβητούμενον· ἐὰν δέ τις ἀφελόμενος βίᾳ παρά τινος ἀπαγάγῃ πρὸς αὑτόν, κἄπειτα παρὰ τούτου τὴν ἀγωγὴν ὁ προϋπάρχων ποιῆται δεσπότης, οὐκ εἶναι ταύτην κυρίαν. τοῦ δὲ νεανίσκου δεινοπαθοῦντος καὶ μὴ φάσκοντος εἶναι τοῦ νομοθέτου ταύτην τὴν προαίρεσιν, προκαλέσασθαί φασι τὸν κοσμόπολιν, εἴ τι βούλεται λέγειν ὑπὲρ τῆς γνώμης κατὰ τὸν Ζαλεύκου νόμον. τοῦτο δ’ ἐστὶ καθισάντων τῶν χιλίων καὶ βρόχων κρεμασθέντων λέγειν ὑπὲρ τῆς τοῦ νομοθέτου γνώμης· ὁπότερος δ’ ἂν αὐτῶν φανῇ τὴν προαίρεσιν ἐπὶ τὸ χεῖρον ἐκδεχόμενος, τὸν τοιοῦτον διὰ τῆς ἀγχόνης ἀπόλλυσθαι βλεπόντων τῶν χιλίων. ταῦτα προτείναντος τοῦ κοσμοπόλιδος, τὸν νεανίσκον εἰπεῖν φασιν ἄνισον εἶναι τὴν συνθήκην· τῷ μὲν γὰρ ἔτη δύ’ ἢ τρία καταλείπεσθαι τοῦ ζῆν· συνέβαινε γὰρ εἶναι τὸν κοσμόπολιν οὐ πολὺ λεῖπον τῶν ἐνενήκοντ’ ἐτῶν· αὑτῷ δὲ τοῦ βίου τὸ πλεῖον ἐκ τῶν εὐλόγων ἔτι μένειν. ὁ μὲν οὖν νεανίσκος οὕτως εὐτραπελευσάμενος ἐξέλυσε τὴν σπουδήν, οἱ δ’ ἄρχοντες ἔκριναν τὴν ἀγωγὴν κατὰ τὴν τοῦ κοσμοπόλιδος γνώμην.", "st": "12.16"}, {"sp": "N", "t": "ἵνα δὲ μὴ δόξωμεν τῶν τηλικούτων ἀνδρῶν καταξιοπιστεῖσθαι, μνησθησόμεθα μιᾶς παρατάξεως, ἣν ἅμα μὲν οἵαν ἐπιφανεστάτην εἶναι συμβέβηκεν, ἅμα δὲ τοῖς καιροῖς οὐ μακρὰν ἀπηρτῆσθαι, τὸ δὲ μέγιστον, παρατετευχέναι τὸν Καλλισθένη. λέγω δὲ περὶ τῆς ἐν Κιλικίᾳ γενομένης Ἀλεξάνδρῳ πρὸς Δαρεῖον, ἐν ᾗ φησὶ μὲν Ἀλέξανδρον ἤδη διαπεπορεῦσθαι τὰ στενὰ καὶ τὰς λεγομένας ἐν τῇ Κιλικίᾳ Πύλας, Δαρεῖον δὲ χρησάμενον τῇ διὰ τῶν Ἀμανίδων λεγομένων Πυλῶν πορείᾳ κατᾶραι μετὰ τῆς δυνάμεως εἰς Κιλικίαν· πυθόμενον δὲ παρὰ τῶν ἐγχωρίων προάγειν τὸν Ἀλέξανδρον ὡς ἐπὶ Συρίαν, ἀκολουθεῖν, καὶ συνεγγίσαντα τοῖς στενοῖς στρατοπεδεῦσαι παρὰ τὸν Πίναρον ποταμόν. εἶναι δὲ τοῦ μὲν τόπου τὸ διάστημ’ οὐ πλείω τῶν τεττάρων καὶ δέκα σταδίων ἀπὸ θαλάττης ἕως πρὸς τὴν παρώρειαν· διὰ δὲ τούτου φέρεσθαι τὸν προειρημένον ποταμὸν ἐπικάρσιον, ἀπὸ μὲν τῶν ὀρῶν εὐθέως ἐκρήγματα τῶν πλευρῶν, διὰ δὲ τῶν ἐπιπέδων ἕως εἰς θάλατταν ἀποτόμους ἔχοντα καὶ δυσβάτους λόφους. ταῦτα δ’ ὑποθέμενος, ἐπεὶ συνεγγίζοιεν οἱ περὶ τὸν Ἀλέξανδρον ἐξ ὑποστροφῆς ἐπ’ αὐτοὺς ἀναχωροῦντες, κρῖναί φησι Δαρεῖον καὶ τοὺς ἡγεμόνας τὴν μὲν φάλαγγα τάξαι πᾶσαν ἐν αὐτῇ τῇ στρατοπεδείᾳ, καθάπερ ἐξ ἀρχῆς εἶχε, χρήσασθαι δὲ τῷ ποταμῷ προβλήματι διὰ τὸ παρ’ αὐτὴν ῥεῖν τὴν στρατοπεδείαν. μετὰ δὲ ταῦτά φησι τοὺς μὲν ἱππεῖς τάξαι παρὰ θάλατταν, τοὺς δὲ μισθοφόρους ἑξῆς τούτοις παρ’ αὐτὸν τὸν ποταμόν, ἐχομένους τούτων τοὺς πελταστὰς συνάπτοντας τοῖς ὄρεσι.", "st": "12.17"}, {"sp": "N", "t": "πῶς δὲ προέταξε τούτους πρὸ τῆς φάλαγγος, τοῦ ποταμοῦ ῥέοντος παρ’ αὐτὴν τὴν στρατοπεδείαν, δυσχερὲς κατανοῆσαι, καὶ ταῦτα τῷ πλήθει τοσούτων ὑπαρχόντων. τρισμύριοι μὲν γὰρ ἱππεῖς ὑπῆρχον, ὡς αὐτὸς ὁ Καλλισθένης φησί, τρισμύριοι δὲ μισθοφόροι· πόσου δ’ εἶχον οὗτοι τόπου χρείαν, εὐχερὲς καταμαθεῖν. πλεῖστον μὲν γὰρ ἱππέων τάττεται βάθος ἐπ’ ὀκτὼ πρὸς ἀληθινὴν χρείαν, καὶ μεταξὺ τῶν ἰλῶν ἑκάστης ἴσον ὑπάρχειν δεῖ διάστημα τοῖς μετώποις πρὸς τὸ ταῖς ἐπιστροφαῖς δύνασθαι καὶ τοῖς περισπασμοῖς εὐχρηστεῖν. ἐξ ὧν τὸ στάδιον ὀκτακοσίους λαμβάνει, τὰ δὲ δέκα τοὺς ὀκτακισχιλίους, τὰ δὲ τέτταρα τρισχιλίους διακοσίους, ὥστ’ ἀπὸ τῶν μυρίων χιλίων διακοσίων πεπληρῶσθαι τὸν τῶν τετταρεσκαίδεκα σταδίων τόπον. ἐὰν δὲ πάντας ἐκτάττῃ τοὺς τρισμυρίους, βραχὺ λείπει τοῦ τριφαλαγγίαν ἐπάλληλον εἶναι τῶν ἱππέων αὐτῶν. εἰς ποῖον οὖν τόπον ἐτάττετο τὸ τῶν μισθοφόρων πλῆθος; εἰ μὴ νὴ Δία κατόπιν τῶν ἱππέων. ἀλλ’ οὔ φησιν, ἀλλὰ συμπεπτωκέναι τούτους τοῖς Μακεδόσι κατὰ τὴν ἐπαγωγήν. ἐξ ὧν ἀνάγκη ποιεῖσθαι τὴν ἐκδοχὴν διότι τὸ μὲν ἥμισυ τοῦ τόπου τὸ παρὰ θάλατταν ἡ τῶν ἱππέων ἐπεῖχε τάξις, τὸ δ’ ἥμισυ τὸ πρὸς τοῖς ὄρεσιν ἡ τῶν μισθοφόρων. ἐκ δὲ τούτων εὐσυλλόγιστον πόσον ὑπῆρχε τὸ βάθος τῶν ἱππέων καὶ ποῖον ἔδει τόπον ἀπέχειν τὸν ποταμὸν ἀπὸ τῆς στρατοπεδείας. μετὰ δὲ ταῦτα συνεγγιζόντων τῶν πολεμίων φησὶ τὸν Δαρεῖον αὐτόν, κατὰ μέσην ὑπάρχοντα τὴν τάξιν, καλεῖν τοὺς μισθοφόρους ἀπὸ τοῦ κέρατος πρὸς αὑτόν. πῶς δὲ λέγεται τοῦτο, διαπορεῖν ἔστι· τῶν γὰρ μισθοφόρων ἀνάγκη καὶ τῶν ἱππέων τὴν συναφὴν κατὰ μέσον ὑπάρχειν τὸν τόπον, ὥστ’ ἐν αὐτοῖς ὢν τοῖς μισθοφόροις ὁ Δαρεῖος ποῦ καὶ πρὸς τί καὶ πῶς ἐκάλει τοὺς μισθοφόρους; τὸ δὲ τελευταῖόν φησι τοὺς ἀπὸ τοῦ δεξιοῦ κέρατος ἱππεῖς ἐπαγαγόντας ἐμβαλεῖν τοῖς περὶ τὸν Ἀλέξανδρον, τοὺς δὲ γενναίως δεξαμένους ἀντεπάγειν καὶ ποιεῖν μάχην ἰσχυράν. ὅτι δὲ ποταμὸς ἦν ἐν μέσῳ, καὶ ποταμὸς οἷον ἀρτίως εἶπεν, ἐπελάθετο.", "st": "12.18"}, {"sp": "N", "t": "τούτοις δ’ ἐστὶ παραπλήσια τὰ κατὰ τὸν Ἀλέξανδρον. φησὶ γὰρ αὐτὸν ποιήσασθαι τὴν εἰς τὴν Ἀσίαν διάβασιν, πεζῶν μὲν ἔχοντα τέτταρας μυριάδας, ἱππεῖς δὲ τετρακισχιλίους καὶ πεντακοσίους, μέλλοντι δ’ εἰς Κιλικίαν ἐμβάλλειν ἄλλους ἐλθεῖν ἐκ Μακεδονίας πεζοὺς μὲν πεντακισχιλίους, ἱππεῖς δ’ ὀκτακοσίους. ἀφ’ ὧν εἴ τις ἀφέλοι τρισχιλίους μὲν πεζούς, τριακοσίους δ’ ἱππεῖς, ἐπὶ τὸ πλεῖον ποιῶν τὴν ἀπουσίαν πρὸς τὰς γεγενημένας χρείας, ὅμως πεζοὶ μὲν ἀπολειφθήσονται τετρακισμύριοι δισχίλιοι, πεντακισχίλιοι δ’ ἱππεῖς. τούτων οὖν ὑποκειμένων, φησὶ τὸν Ἀλέξανδρον πυθέσθαι τὴν Δαρείου παρουσίαν εἰς Κιλικίαν ἑκατὸν ἀπέχοντα σταδίους ἀπ’ αὐτοῦ, διαπεπορευμένον ἤδη τὰ στενά· διόπερ ἐξ ὑποστροφῆς πάλιν ποιεῖσθαι τὴν πορείαν διὰ τῶν στενῶν, ἄγοντα πρῶτον μὲν τὴν φάλαγγα, μετὰ δὲ ταῦτα τοὺς ἱππεῖς, ἐπὶ πᾶσι τὸ σκευοφόρον. ἅμα δὲ τῷ πρῶτον εἰς τὰς εὐρυχωρίας ἐκπεσεῖν, διασκευάζεσθαι παραγγείλαντα πᾶσιν ἐπιπαρεμβαλεῖν τὴν φάλαγγα, καὶ ποιῆσαι τὸ βάθος αὐτῆς ἐπὶ τριάκοντα καὶ δύο, μετὰ δὲ ταῦτα πάλιν εἰς ἑκκαίδεκα, τὸ δὲ τελευταῖον, ἐγγίζοντα τοῖς πολεμίοις, εἰς ὀκτώ. ταῦτα δ’ ἐστὶ μείζω τῶν προειρημένων ἀλογήματα. τοῦ γὰρ σταδίου λαμβάνοντος ἄνδρας ἐν τοῖς πορευτικοῖς διαστήμασιν, ὅταν εἰς ἑκκαίδεκα τὸ βάθος ὦσι, χιλίους ἑξακοσίους, ἑκάστου τῶν ἀνδρῶν ἓξ πόδας ἐπέχοντος, φανερὸν ὅτι τὰ δέκα στάδια λήψεται μυρίους ἑξακισχιλίους, τὰ δ’ εἴκοσι τοὺς διπλασίους. ἐκ δὲ τούτων εὐθεώρητον ὅτι καθ’ ὃν καιρὸν ἐποίησε τὴν δύναμιν Ἀλέξανδρος ἑκκαίδεκα τὸ βάθος, ἀναγκαῖον ἦν εἴκοσι σταδίων ὑπάρχειν τὸ τοῦ τόπου διάστημα καὶ περιττεύειν ἔτι τοὺς μὲν ἱππεῖς πάντας, τῶν δὲ πεζῶν μυρίους.", "st": "12.19"}, {"sp": "N", "t": "μετὰ δὲ ταῦτά φησι μετωπηδὸν ἄγειν τὴν δύναμιν, ἀπέχοντα τῶν πολεμίων περὶ τετταράκοντα σταδίους. τούτου δὲ μεῖζον ἀλόγημα δυσχερὲς ἐπινοῆσαι· ποῦ γὰρ ἂν εὕροι τις τοιούτους τόπους, ἄλλως τε καὶ κατὰ Κιλικίαν, ὥστ’ ἐπὶ σταδίους εἴκοσι μὲν τὸ πλάτος τετταράκοντα δὲ τὸ μῆκος μετωπηδὸν ἄγειν φάλαγγα σαρισοφόρον; τοσαῦτα γάρ ἐστιν ἐμπόδια πρὸς τὴν τοιαύτην τάξιν καὶ χρείαν, ἅ τις οὐδ’ ἂν ἐξαριθμήσαιτο ῥᾳδίως. ἓν δὲ τῶν ὑπ’ αὐτοῦ Καλλισθένους λεγομένων ἱκανὸν ὑπάρχει πρὸς πίστιν· τοὺς γὰρ ἀπὸ τῶν ὀρῶν χειμάρρους καταφερομένους τοσαῦτά φησι ποιεῖν ἐκρήγματα κατὰ τὸ πεδίον ὥστε καὶ τῶν Περσῶν κατὰ τὴν φυγὴν διαφθαρῆναι λέγουσι τοὺς πλείστους ἐν τοῖς τοιούτοις κοιλώμασι. νὴ Δί’, ἀλλ’ ἕτοιμος ἐβούλετ’ εἶναι πρὸς τὴν τῶν πολεμίων ἐπιφάνειαν. τί δ’ ἀνετοιμότερον φάλαγγος ἐν μετώπῳ διαλελυμένης καὶ διεσταμένης; πόσῳ γὰρ ἐκ πορευτικῆς ἀγωγῆς ἁρμοζούσης παρατάξαι ῥᾷον ἢ διαλελυμένην ἐν μετώπῳ καὶ διεσπασμένην δύναμιν ἐπὶ τὴν αὐτὴν εὐθεῖαν ἀγαγεῖν καὶ συστῆσαι πρὸς μάχην ἐν τόποις ὑλώδεσι καὶ περικεκλασμένοις; διόπερ οὐδὲ παρὰ μικρὸν ἦν κρεῖττον ἄγειν διφαλαγγίαν ἢ τετραφαλαγγίαν ἁρμόζουσαν, ᾗ καὶ τόπον πορείας εὑρεῖν οὐκ ἀδύνατον, καὶ τὸ παρατάξαι ταχέως ῥᾴδιόν γε, δυνάμενον διὰ τῶν προδρόμων ἐκ πολλοῦ γινώσκειν τὴν τῶν πολεμίων παρουσίαν. ὁ δὲ χωρὶς τῶν ἄλλων οὐδὲ τοὺς ἱππεῖς προέθετο, μετωπηδὸν ἄγων τὴν δύναμιν ἐν τόποις ἐπιπέδοις, ἀλλ’ ἐξ ἴσου ποιεῖ τοῖς πεζοῖς.", "st": "12.20"}, {"sp": "N", "t": "τὸ δὲ δὴ πάντων μέγιστον· ἤδη γὰρ σύνεγγυς ὄντα τοῖς πολεμίοις αὐτὸν εἰς ὀκτὼ ποιῆσαί φησι τὸ βάθος. ἐξ οὗ δῆλον ὅτι κατ’ ἀνάγκην ἐπὶ τετταράκοντα σταδίους ἔδει γενέσθαι τὸ μῆκος τῆς φάλαγγος. εἰ δ’ ὅλως συνήσπισαν κατὰ τὸν ποιητὴν οὕτως ὥστε συνερεῖσαι πρὸς ἀλλήλους, ὅμως εἴκοσι σταδίων ἔδει τὸν τόπον ὑπάρχειν. αὐτὸς δέ φησι λείπειν τῶν δεκατεττάρων σταδίων καὶ τούτου μέρος μέν τι πρὸς θαλάττῃ τοὺς ἡμίσεας ἐπὶ τοῦ δεξιοῦ· ἔτι δὲ τὴν ὅλην τάξιν ἀπὸ τῶν ὀρῶν ἱκανὸν τόπον ἀφεστάναι πρὸς τὸ μὴ τοῖς πολεμίοις ὑποπεπτωκέναι τοῖς κατέχουσι τὰς παρωρείας. ἴσμεν γὰρ ὃ ποιεῖ πρὸς τούτους ἐπικάμπιον. Ὑπολειπόμεθα καὶ νῦν ἡμεῖς τοὺς μυρίους πεζούς, πλείους ὄντας τῆς ἐκείνου προθέσεως. ὥστ’ ἐκ τούτων ἕνδεκα σταδίους ἐπὶ τὸ πλεῖον ἀπολείπεσθαι τὸ τῆς φάλαγγος μῆκος κατ’ αὐτὸν τὸν Καλλισθένην, ἐν οἷς ἀνάγκη τοὺς τρισμυρίους καὶ δισχιλίους ἐπὶ τριάκοντα τὸ βάθος ὑπάρχειν συνησπικότας. ὁ δέ φησιν εἰς ὀκτὼ τεταγμένων γενέσθαι τὴν μάχην. τὰ δὲ τοιαῦτα τῶν ἁμαρτημάτων οὐδ’ ἀπολογίαν ἐπιδέχεται· τὸ γὰρ ἀδύνατον ἐν πράγμασιν αὐτόθεν ἔχει τὴν πίστιν. διόπερ ὅταν καὶ τὰ κατ’ ἄνδρα διαστήματα καὶ τὸ πᾶν τοῦ τόπου μέγεθος ὡρισμένον ὑποθῶσι καὶ τὸν ἀριθμὸν τῶν ἀνδρῶν, ἀναπολόγητον γίνεται τὸ ψεῦδος.", "st": "12.21"}, {"sp": "N", "t": "τὰ μὲν γὰρ ἅμα τούτοις ἀλογήματα μακρὸν ἂν εἴη λέγειν πάντα πλὴν τελέως ὀλίγων. φησὶ γὰρ τὸν Ἀλέξανδρον σπουδάζειν κατὰ τὴν τάξιν, ἵνα κατὰ τὸν Δαρεῖον αὐτὸν ποιήσηται τὴν μάχην· ὁμοίως δὲ κατὰ μὲν ἀρχὰς καὶ τὸν Δαρεῖον αὐτὸν βούλεσθαι κατὰ τὸν Ἀλέξανδρον, ὕστερον δὲ μετανοῆσαι. πῶς δ’ ἐπέγνωσαν ἀλλήλους οὗτοι ποῦ τῆς ἰδίας δυνάμεως ἔχουσι τὴν τάξιν, ἢ ποῦ μετέβη πάλιν ὁ Δαρεῖος, ἁπλῶς οὐδὲν λέγεται. πῶς δὲ προσανέβη πρὸς τὴν ὀφρὺν τοῦ ποταμοῦ φαλαγγιτῶν τάξις, ἀπότομον οὖσαν καὶ βατώδη; καὶ γὰρ τοῦτο παρὰ λόγον. Ἀλεξάνδρῳ μὲν οὖν οὐκ ἐποιστέον τὴν τοιαύτην ἀτοπίαν διὰ τὸ πᾶσιν ὁμολογουμένην παραλαμβάνεσθαι περὶ αὐτοῦ τὴν ἐν τοῖς πολεμικοῖς ἐμπειρίαν καὶ τριβὴν ἐκ παιδός, τῷ δὲ συγγραφεῖ μᾶλλον, ὃς διὰ τὴν ἀπειρίαν οὐδὲ τὸ δυνατὸν καὶ τὸ μὴ δυνατὸν ἐν τοῖς τοιούτοις δύναται διευκρινεῖν. περὶ μὲν οὖν Ἐφόρου καὶ Καλλισθένους ταῦθ’ ἡμῖν εἰρήσθω.", "st": "12.22"}, {"sp": "N", "t": "ὅτι κατὰ τοῦ Ἐφόρου Τίμαιος πλείστην πεποίηται καταδρομήν, αὐτὸς ὢν δυσὶν ἁμαρτήμασιν ἔνοχος, τῷ μὲν ὅτι πικρῶς κατηγορεῖ τῶν πέλας ἐπὶ τούτοις οἷς αὐτὸς ἔνοχός ἐστι, τῷ δὲ διότι καθόλου διέφθαρται τῇ ψυχῇ, τοιαύτας ἀποφάσεις ἐκτιθέμενος ἐν τοῖς ὑπομνήμασι καὶ τοιαύτας ἐντίκτων δόξας τοῖς ἐντυγχάνουσι. πλὴν εἰ τὸν Καλλισθένην θετέον εἰκότως κολασθέντα μεταλλάξαι τὸν βίον, τί χρὴ πάσχειν Τίμαιον; πολὺ γὰρ ἂν δικαιότερον τούτῳ νεμεσήσαι τὸ δαιμόνιον ἢ Καλλισθένει. ἐκεῖνος μὲν οὖν ἀποθεοῦν Ἀλέξανδρον ἐβουλήθη, Τίμαιος δὲ μείζω ποιεῖ Τιμολέοντα τῶν ἐπιφανεστάτων θεῶν, καὶ Καλλισθένης μὲν ἄνδρα τοιοῦτον, ὃν πάντες μεγαλοφυέστερον ἢ κατ’ ἄνθρωπον γεγονέναι τῇ ψυχῇ συγχωροῦσιν, οὗτος δὲ Τιμολέοντα τὸν οὐχ οἷον δόξαντά τι πεπραχέναι μεγαλεῖον, ἀλλ’ οὐδ’ ἐπιβαλόμενον, μίαν δ’ ἐν τῷ βίῳ γραμμὴν διανύσαντα, καὶ ταύτην οὐδὲ σπουδαίαν τρόπον τινὰ πρὸς τὸ μέγεθος τῆς οἰκουμένης, λέγω δὲ τὴν ἐκ τῆς πατρίδος εἰς Συρακούσας. ἀλλά μοι δοκεῖ πεισθῆναι Τίμαιος ὡς, ἂν Τιμολέων, πεφιλοδοξηκὼς ἐν αὐτῇ Σικελίᾳ, καθάπερ ἐν ὀξυβάφῳ, σύγκριτος φανῇ τοῖς ἐπιφανεστάτοις τῶν ἡρώων, κἂν αὐτὸς ὑπὲρ Ἰταλίας μόνον καὶ Σικελίας πραγματευόμενος εἰκότως παραβολῆς ἀξιωθῆναι τοῖς ὑπὲρ τῆς οἰκουμένης καὶ τῶν καθόλου πράξεων πεποιημένοις τὰς συντάξεις. περὶ μὲν οὖν Ἀριστοτέλους καὶ Θεοφράστου καὶ Καλλισθένους, ἔτι δ’ Ἐφόρου καὶ Δημοχάρους, ἱκανὰ ταῦθ’ ἡμῖν ἐστι πρὸς τὴν Τιμαίου καταδρομήν, ὁμοίως δὲ καὶ πρὸς τοὺς ἀφιλοτίμως πεπεισμένους ἀληθεύειν τὸν συγγραφέα τοῦτον. —", "st": "12.23"}, {"sp": "N", "t": "ὅτι διαπορεῖν ἔστι περὶ τῆς αἱρέσεως Τιμαίου. φησὶ γὰρ τοὺς ποιητὰς καὶ συγγραφέας διὰ τῶν ὑπεράνω πλεονασμῶν ἐν τοῖς ὑπομνήμασι διαφαίνειν τὰς ἑαυτῶν φύσεις. λέγων τὸν μὲν ποιητὴν ἐκ τοῦ δαιτρεύειν πολλαχοῦ τῆς ποιήσεως ὡς ἂν εἰ γαστρίμαργον παρεμφαίνειν, τὸν δ’ Ἀριστοτέλην, ὀψαρτύοντα πλεονάκις ἐν τοῖς συγγράμμασιν, ὀψοφάγον εἶναι καὶ λίχνον. τὸν αὐτὸν τρόπον ἐπὶ τοῦ Διονυσίου τοῦ τυράννου, κλινοκοσμοῦντος καὶ τὰς τῶν ὑφασμάτων ἰδιότητας καὶ ποικιλίας ἐξεργαζομένου συνεχῶς. ἀνάγκη τὴν ἀκόλουθον ποιεῖσθαι διάληψιν καὶ δυσαρεστεῖσθαι κατὰ τὴν προαίρεσιν. οὗτος γὰρ ἐν μὲν ταῖς τῶν πέλας κατηγορίαις πολλὴν ἐπιφαίνει δεινότητα καὶ τόλμαν, ἐν δὲ ταῖς ἰδίαις ἀποφάσεσιν ἐνυπνίων καὶ τεράτων καὶ μύθων ἀπιθάνων καὶ συλλήβδην δεισιδαιμονίας ἀγεννοῦς καὶ τερατείας γυναικώδους ἐστὶ πλήρης. οὐ μὴν ἀλλὰ διότι γε συμβαίνει διὰ τὴν ἀπειρίαν καὶ κακοκρισίαν πολλοὺς ἐνίοτε καθάπερ εἰ παρόντας τρόπον τινὰ μὴ παρεῖναι καὶ βλέποντας μὴ βλέπειν ἐκ τῶν εἰρημένων τε νῦν καὶ τῶν Τιμαίῳ συμβεβηκότων γέγονε φανερόν. —", "st": "12.24"}, {"sp": "N", "t": "ὅτι περὶ τοῦ ταύρου τοῦ χαλκοῦ τοῦ παρὰ Φαλάριδος κατασκευασθέντος ἐν Ἀκράγαντι, εἰς ὃν ἐνεβίβαζεν ἀνθρώπους, κἄπειτα πῦρ ὑποκαίων ἐλάμβανε τιμωρίαν παρὰ τῶν ὑποταττομένων τοιαύτην ὥστ’ ἐκπυρουμένου τοῦ χαλκοῦ τὸν μὲν ἄνθρωπον πανταχόθεν παροπτώμενον καὶ περιφλεγόμενον διαφθείρεσθαι, κατὰ δὲ τὴν ὑπερβολὴν τῆς ἀλγηδόνος, ὁπότ’ ἀναβοήσειε, μυκηθμῷ παραπλήσιον τὸν ἦχον ἐκ τοῦ κατασκευάσματος προσπίπτειν τοῖς ἀκούουσι. τούτου δὲ τοῦ ταύρου κατὰ τὴν ἐπικράτειαν Καρχηδονίων μετενεχθέντος ἐξ Ἀκράγαντος εἰς Καρχηδόνα, καὶ τῆς θυρίδος διαμενούσης περὶ τὰς συνωμίας, δι’ ἧς συνέβαινε καθίεσθαι τοὺς ἐπὶ τὴν τιμωρίαν, καὶ ἑτέρας αἰτίας, δι’ ἣν ἐν Καρχηδόνι κατεσκευάσθη τοιοῦτος ταῦρος, οὐδαμῶς δυναμένης εὑρεθῆναι τὸ παράπαν, ὅμως Τίμαιος ἐπεβάλετο καὶ τὴν κοινὴν φήμην ἀνασκευάζειν καὶ τὰς ἀποφάσεις τῶν ποιητῶν καὶ συγγραφέων ψευδοποιεῖν, φάσκων μήτ’ εἶναι τὸν ἐν Καρχηδόνι ταῦρον ἐξ Ἀκράγαντος μήτε γεγονέναι τοιοῦτον ἐν τῇ προειρημένῃ πόλει· καὶ πολλοὺς δή τινας εἰς τοῦτο τὸ μέρος διατέθειται λόγους. — κατὰ τῆς Τιμαίου τί ποτε δεῖ λέγειν ὄνομα καὶ ῥῆμα; πάντα γὰρ ἐπιδέχεσθαί μοι δοκεῖ τὰ πικρότατα τὸ γένος, οἷς ἐκεῖνος κέχρηται κατὰ τῶν πλησίον. ὅτι μὲν οὖν ἐστι φιλαπεχθὴς καὶ ψεύστης καὶ τολμηρός, σχεδὸν ἱκανῶς ἐκ τῶν προειρημένων ὑπεδείχθη· διότι δ’ ἀφιλόσοφός ἐστι καὶ συλλήβδην ἀνάγωγος συγγραφεύς, ἐκ τῶν λέγεσθαι μελλόντων ἔσται συμφανές. ἐν γὰρ τῇ μιᾷ καὶ εἰκοστῇ βύβλῳ, καὶ ταύτης ἐπὶ τελευτῇ, λέγει κατὰ τὴν τοῦ Τιμολέοντος παράκλησιν ταῦτα, διότι τῆς γῆς τῆς ὑπὸ τῷ κόσμῳ κειμένης εἰς τρία μέρη διῃρημένης, καὶ τῆς μὲν Ἀσίας, τῆς δὲ Λιβύης, τῆς δ’ Εὐρώπης προσαγορευομένης. ταῦτα γὰρ οὐχ οἷον Τίμαιον εἰρηκέναι τίς ἂν πιστεύσειεν, ἀλλ’ οὐδὲ τὸν λεγόμενον Μαργίτην ἐκεῖνον. τίς γὰρ οὕτως ἐστὶν ἀδαής, οὐ λέγω τῶν πρὸς ὑπομνήμασι γεγονότων", "st": "12.25"}, {"sp": "N", "t": "ὅτι περὶ Τιμαίου φησὶν ὁ Πολύβιος ὁ Μεγαλοπολίτης· καθάπερ γὰρ ἐκ τῶν παροιμιῶν ἱκανὸν εἶναί φασι σταλαγμὸν ἕνα τοῦ μεγίστου τεύχους εἰς τὸ γνῶναι τὸ πᾶν ἔγχυμα, τὸν αὐτὸν τρόπον καὶ περὶ τῶν ὑποκειμένων χρὴ διαλαμβάνειν· ἐπειδὰν γὰρ ἓν ἢ δεύτερον εὑρεθῇ ψεῦδος ἐν τοῖς συγγράμμασι, καὶ τοῦτο γεγονὸς ᾖ κατὰ προαίρεσιν, δῆλον ὡς οὐδὲν ἂν ἔτι βέβαιον οὐδ’ ἀσφαλὲς γένοιτο τῶν ὑπὸ τοῦ τοιούτου συγγραφέως λεγομένων. ἵνα δὲ καὶ τοὺς φιλοτιμότερον διακειμένους μεταπείσωμεν, ῥητέον ἂν εἴη περὶ τῆς αἱρέσεως αὐτοῦ καὶ μελέτης τῆς κατὰ τὰς δημηγορίας καὶ τὰς παρακλήσεις, ἔτι δὲ τοὺς πρεσβευτικοὺς λόγους, καὶ συλλήβδην πᾶν τὸ τοιοῦτο γένος, ἃ σχεδὸν ὡς εἰ κεφάλαια τῶν πράξεών ἐστι καὶ συνέχει τὴν ὅλην ἱστορίαν· διότι γὰρ ταῦτα παρ’ ἀλήθειαν ἐν τοῖς ὑπομνήμασι κατατέταχε Τίμαιος, καὶ τοῦτο πεποίηκε κατὰ πρόθεσιν, τίς οὐ παρακολουθεῖ τῶν ἀνεγνωκότων; οὐ γὰρ τὰ ῥηθέντα γέγραφεν, οὐδ’ ὡς ἐρρήθη κατ’ ἀλήθειαν, ἀλλὰ προθέμενος ὡς δεῖ ῥηθῆναι, πάντας ἐξαριθμεῖται τοὺς ῥηθέντας λόγους καὶ τὰ παρεπόμενα τοῖς πράγμασιν οὕτως ὡς ἂν εἴ τις ἐν διατριβῇ πρὸς ὑπόθεσιν ἐπιχειροίη ὥσπερ ἀπόδειξιν τῆς ἑαυτοῦ δυνάμεως ποιούμενος, ἀλλ’ οὐκ ἐξήγησιν τῶν κατ’ ἀλήθειαν εἰρημένων. —", "st": "12.25a"}, {"sp": "N", "t": "ὅτι τῆς ἱστορίας ἰδίωμα τοῦτ’ ἐστὶ τὸ πρῶτον μὲν αὐτοὺς τοὺς κατ’ ἀλήθειαν εἰρημένους, οἷοί ποτ’ ἂν ὦσι, γνῶναι λόγους, δεύτερον τὴν αἰτίαν πυνθάνεσθαι, παρ’ ἣν ἢ διέπεσεν ἢ κατωρθώθη τὸ πραχθὲν ἢ ῥηθέν· ἐπεὶ ψιλῶς λεγόμενον αὐτὸ τὸ γεγονὸς ψυχαγωγεῖ μέν, ὠφελεῖ δ’ οὐδέν· προστεθείσης δὲ τῆς αἰτίας ἔγκαρπος ἡ τῆς ἱστορίας γίνεται χρῆσις. ἐκ γὰρ τῶν ὁμοίων ἐπὶ τοὺς οἰκείους μεταφερομένων καιροὺς ἀφορμαὶ γίνονται καὶ προλήψεις εἰς τὸ προϊδέσθαι τὸ μέλλον, καὶ ποτὲ μὲν εὐλαβηθῆναι, ποτὲ δὲ μιμούμενον τὰ προγεγονότα θαρραλεώτερον ἐγχειρεῖν τοῖς ἐπιφερομένοις· ὁ δὲ καὶ τοὺς ῥηθέντας λόγους καὶ τὴν αἰτίαν παρασιωπῶν, ψευδῆ δ’ ἀντὶ τούτων ἐπιχειρήματα καὶ διεξοδικοὺς λέγων λόγους, ἀναιρεῖ τὸ τῆς ἱστορίας ἴδιον· ὃ μάλιστα ποιεῖ Τίμαιος· καὶ διότι τούτου τοῦ γένους ἐστὶ πλήρη τὰ βυβλία παρ’ αὐτῷ, πάντες γινώσκομεν.", "st": "12.25b"}, {"sp": "N", "t": "ἴσως δ’ οὖν ἄν τις ἐναπορήσειε πῶς τοιοῦτος ὢν οἷον ἡμεῖς ὑποδείκνυμεν τοιαύτης παρ’ ἐνίοις ἀποδοχῆς τέτευχε καὶ πίστεως. τούτου δ’ ἐστὶν αἴτιον διότι πλεοναζούσης αὐτῷ κατὰ τὴν πραγματείαν τῆς κατὰ τῶν ἄλλων ἐπιτιμήσεως καὶ λοιδορίας οὐκ ἐκ τῆς αὑτοῦ θεωρεῖται πραγματείας οὐδ’ ἐκ τῶν ἰδίων ἀποφάσεων, ἀλλ’ ἐκ τῆς τῶν πέλας κατηγορίας, πρὸς ὃ γένος καὶ πολυπραγμοσύνην δοκεῖ μοι καὶ φύσιν προσενέγκασθαι διαφέρουσαν· παραπλήσιον γὰρ δή τι τοιοῦτο συμβέβηκε καὶ Στράτωνι τῷ φυσικῷ· καὶ γὰρ ἐκεῖνος ὅταν ἐγχειρήσῃ τὰς τῶν ἄλλων δόξας διαστέλλεσθαι καὶ ψευδοποιεῖν, θαυμάσιός ἐστιν· ὅταν δ’ ἐξ αὑτοῦ τι προφέρηται καί τι τῶν ἰδίων ἐπινοημάτων ἐξηγῆται, παρὰ πολὺ φαίνεται τοῖς ἐπιστήμοσιν εὐηθέστερος αὑτοῦ καὶ νωθρότερος. καί μοι δοκεῖ παντάπασιν ὅμοιόν τι γίνεσθαι περὶ τοὺς γράφοντας τῷ περὶ τὸν ὅλον ἡμῶν βίον συμβαίνοντι· καὶ γὰρ ἐν τούτῳ τὸ μὲν ἐπιτιμῆσαι τοῖς πέλας ἐστὶ ῥᾴδιον, τὸ δ’ αὑτὸν ἀναμάρτητον παρέχεσθαι χαλεπόν, καὶ σχεδὸν ὡς ἔπος εἰπεῖν ἴδοι τις ἂν τοὺς προχειρότατα τοῖς πέλας ἐπιτιμῶντας πλεῖστα περὶ τὸν ἴδιον βίον ἁμαρτάνοντας.", "st": "12.25c"}, {"sp": "N", "t": "τῷ δὲ Τιμαίῳ καὶ ἕτερόν τι χωρὶς τῶν προγεγραμμένων συμβέβηκεν· ἀποκαθίσας γὰρ Ἀθήνησι σχεδὸν ἔτη πεντήκοντα καὶ πρὸς τοῖς τῶν προγεγονότων ὑπομνήμασι γενόμενος ὑπέλαβε τὰς μεγίστας ἀφορμὰς ἔχειν πρὸς τὴν ἱστορίαν, ἀγνοῶν, ὥς γ’ ἐμοὶ δοκεῖ. ἐχούσης γάρ τι παραπλήσιον τῆς ἱστορίας καὶ τῆς ἰατρικῆς διὰ τὸ κατὰ τὰς ὁλοσχερεῖς διαφορὰς ἑκατέραν αὐτῶν ὑπάρχειν τριμερῆ, παραπλησίους εἶναι συμβαίνει καὶ τὰς τῶν ἐπιβαλλομένων ἐπ’ αὐτὰς διαθέσεις· οἷον εὐθέως τῆς ἰατρικῆς, ἑνὸς μὲν μέρους αὐτῆς ὑπάρχοντος λογικοῦ, τοῦ δ’ ἑξῆς διαιτητικοῦ, τοῦ δὲ τρίτου χειρουργικοῦ καὶ φαρμακευτικοῦ, γένους ὁλοσχερῶς. ε … μαι τῶι καταψεύδεσθαι τοῦ ἐπιτηδεύματος τὸ δὲ λογικόν, ὃ δὴ πλεῖστον ἀπὸ τῆς Ἀλεξανδρείας ἄρχεται παρὰ τῶν Ἡροφιλείων καὶ Καλλιμαχείων ἐκεῖ προσαγορευομένων, τοῦτο μέρος μέν τι κατέχει τῆς ἰατρικῆς, κατὰ δὲ τὴν ἐπίφασιν καὶ τὴν ἐπαγγελίαν τοιαύτην ἐφέλκεται φαντασίαν ὥστε δοκεῖν μηδένα τῶν ἄλλων κρατεῖν τοῦ πράγματος· οὓς ὅταν ἐπὶ τὴν ἀλήθειαν ἀπαγαγὼν ἄρρωστον ἐγχειρίσῃς, τοσοῦτον ἀπέχοντες εὑρίσκονται τῆς χρείας ὅσον [καὶ] οἱ μηδὲν ἀνεγνωκότες ἁπλῶς ἰατρικὸν ὑπόμνημα· οἷς ἤδη τινὲς τῶν ἀρρώστων ἐπιτρέψαντες αὑτοὺς διὰ τὴν ἐν λόγῳ δύναμιν οὐδὲν ἔχοντες δεινὸν τοῖς ὅλοις πολλάκις ἐκινδύνευσαν. εἰσὶ γὰρ ἀληθῶς ὅμοιοι τοῖς ἐκ βυβλίου κυβερνῶσιν· ἀλλ’ ὅμως οὗτοι μετὰ φαντασίας ἐπιπορευόμενοι τὰς πόλεις, ἐπειδὰν ἁθροίσωσι τοὺς ὄχλους ἐπ’ ὀνόματος, τοὺς ἐπ’ αὐτῶν τῶν ἔργων ἀληθινὴν πεῖραν δεδωκότας αὑτῶν εἰς τὴν ἐσχάτην ἄγουσιν ἀπορίαν καὶ καταφρόνησιν παρὰ τοῖς ἀκούουσι, τῆς τοῦ λόγου πιθανότητος καταγωνιζομένης πολλάκις τὴν ἐπ’ αὐτῶν τῶν ἔργων δοκιμασίαν. τὸ δὲ τρίτον, τὸ τὴν ἀληθινὴν προσφερόμενον ἕξιν ἐν ἑκάστοις τῶν ἐπιτηδευμάτων, οὐ μόνον ὑπάρχει σπάνιον, ἀλλὰ καὶ πολλάκις ὑπὸ τῆς στωμυλίας καὶ τόλμης ἐπισκοτεῖται διὰ τὴν τῶν πολλῶν ἀκρισίαν.", "st": "12.25d"}, {"sp": "N", "t": "τὸν αὐτὸν δὴ τρόπον καὶ τῆς πραγματικῆς ἱστορίας ὑπαρχούσης τριμεροῦς, τῶν δὲ μερῶν αὐτῆς ἑνὸς μὲν ὄντος τοῦ περὶ τὴν ἐν τοῖς ὑπομνήμασι πολυπραγμοσύνην καὶ τὴν παράθεσιν τῆς ἐκ τούτων ὕλης, ἑτέρου δὲ τοῦ περὶ τὴν θέαν τῶν πόλεων καὶ τῶν τόπων περί τε ποταμῶν καὶ λιμένων καὶ καθόλου τῶν κατὰ γῆν καὶ κατὰ θάλατταν ἰδιωμάτων καὶ διαστημάτων, τρίτου δὲ τοῦ περὶ τὰς πράξεις τὰς πολιτικάς, παραπλησίως ἐφίενται μὲν ταύτης πολλοὶ διὰ τὴν προγεγενημένην περὶ αὐτῆς δόξαν, προσφέρονται δὲ πρὸς τὴν ἐπιβολὴν οἱ μὲν πλεῖστοι τῶν γραφόντων ἁπλῶς δίκαιον οὐδὲν πλὴν εὐχέρειαν καὶ τόλμαν καὶ ῥᾳδιουργίαν, παραπλήσιον τοῖς φαρμακοπώλαις δοξοκοποῦντες καὶ πρὸς χάριν λέγοντες ἀεὶ τὰ πρὸς τοὺς καιροὺς ἕνεκα τοῦ πορίζειν τὸν βίον διὰ τούτων· περὶ ὧν οὐκ ἄξιον πλείω ποιεῖσθαι λόγον. ἔνιοι δὲ τῶν δοκούντων εὐλόγως προσάγειν πρὸς τὴν ἱστορίαν, καθάπερ οἱ λογικοὶ τῶν ἰατρῶν ἐνδιατρίψαντες ταῖς βυβλιοθήκαις καὶ καθόλου τὴν ἐκ τῶν ὑπομνημάτων περιποιησάμενοι πολυπειρίαν πείθουσιν αὑτοὺς ὡς ὄντες ἱκανοὶ πρὸς τὴν ἐπιβολήν, καὶ τοῖς ἐκτὸς ἀρκούντως δοκοῦσι προσφέρεσθαι, μέρος, ὡς ἐμοὶ δοκεῖ, πρὸς τὴν πραγματικὴν ἱστορίαν· τὸ γὰρ ἐποπτεῦσαι τὰ πρότερον ὑπομνήματα πρὸς μὲν τὸ γνῶναι τὰς τῶν ἀρχαίων διαλήψεις καὶ τὰς ἐννοίας ἃς πρὶν εἶχον ὑπὲρ διαθέσεων, τόπων, ἐθνῶν, πολιτειῶν, πράξεων, ἔτι δὲ πρὸς τὸ συνεῖναι τὰς ἑκάστων περιστάσεις καὶ τύχας, αἷς κέχρηνται κατὰ τοὺς ἀνωτέρω χρόνους, εὔχρηστόν ἐστι· συνεφίστησι γὰρ τὰ προγεγονότα πρὸς τὸ μέλλον ἡμᾶς οἰκείως, ἐάν τις ὑπὲρ ἑκάστων ἀληθινῶς ἱστορῇ τὰ παρεληλυθότα· τό γε μὴν ἀπ’ αὐτῆς ταύτης τῆς δυνάμεως ὁρμηθέντα πεπεῖσθαι γράφειν τὰς ἐπιγινομένας πράξεις καλῶς, ὃ πέπεισται Τίμαιος, τελέως εὔηθες καὶ παραπλήσιον ὡς ἂν εἴ τις τὰ τῶν ἀρχαίων ζωγράφων ἔργα θεασάμενος ἱκανὸς οἴοιτο ζωγράφος εἶναι καὶ προστάτης τῆς τέχνης.", "st": "12.25e"}, {"sp": "N", "t": "δῆλον δ’ ἔσται τὸ λεγόμενον ἔτι μᾶλλον ἐκ τῶν ἐπιφερομένων, οἷον εὐθέως ἐκ τῶν συμβεβηκότων Ἐφόρῳ κατὰ τόπους τινὰς τῆς ἱστορίας. ἐκεῖνος γὰρ ἐν τοῖς πολεμικοῖς τῶν μὲν κατὰ θάλατταν ἔργων ἐπὶ ποσὸν ὑπόνοιαν ἐσχηκέναι μοι δοκεῖ, τῶν δὲ κατὰ γῆν ἀγώνων ἄπειρος εἶναι τελέως. τοιγαροῦν ὅταν μὲν πρὸς τὰς περὶ Κύπρον ναυμαχίας καὶ τὰς περὶ Κνίδον ἀτενίσῃ τις, αἷς ἐχρήσανθ’ οἱ βασιλέως στρατηγοὶ πρὸς Εὐαγόραν τὸν Σαλαμίνιον καὶ πάλιν πρὸς Λακεδαιμονίους θαυμάζειν τὸν συγγραφέα καὶ κατὰ τὴν δύναμιν καὶ κατὰ τὴν ἐμπειρίαν εἰκὸς καὶ πολλὰ τῶν χρησίμων ἀπενέγκασθαι πρὸς τὰς ὁμοίας περιστάσεις· ὅταν δὲ τὴν περὶ Λεῦκτρα μάχην ἐξηγῆται Θηβαίων καὶ Λακεδαιμονίων ἢ τὴν ἐν Μαντινείᾳ πάλιν τῶν αὐτῶν τούτων, ἐν ᾗ καὶ μετήλλαξε τὸν βίον Ἐπαμινώνδας, ἐν τούτοις ἐὰν ἐπὶ τὰ κατὰ μέρος ἐπιστήσας τις θεωρῇ τὰς ἐκτάξεις καὶ μετατάξεις τὰς κατ’ αὐτοὺς τοὺς κινδύνους, γελοῖος φαίνεται καὶ παντελῶς ἄπειρος καὶ ἀόρατος τῶν τοιούτων ὤν. ὁ μὲν οὖν ἐν τοῖς Λεύκτροις κίνδυνος ἁπλοῦς γεγονὼς καὶ καθ’ ἕν τι μέρος τῆς δυνάμεως οὐ λίαν ἐκφανῆ ποιεῖ τὴν τοῦ συγγραφέως ἀπειρίαν· ὁ δὲ περὶ τὴν Μαντίνειαν τὴν μὲν ἔμφασιν ἔχει ποικίλην καὶ στρατηγικήν, ἔστι δ’ ἀνυπόστατος καὶ τελέως ἀδιανόητος τῷ συγγραφεῖ. τοῦτο δ’ ἔσται δῆλον, ἐάν τις τοὺς τόπους ὑποθέμενος ἀληθινῶς ἐπιμετρῇ τὰς κινήσεις τὰς ὑπ’ αὐτοῦ δηλουμένας. τὸ δ’ αὐτὸ συμβαίνει καὶ Θεοπόμπῳ καὶ μάλιστα Τιμαίῳ, περὶ οὗ νῦν ὁ λόγος· οὗ μὲν γὰρ ἂν ὑπὲρ τῶν τοιούτων κεφαλαιώδη ποιήσωνται τὴν ὑπόθεσιν, διαλανθάνουσιν, οὗ δ’ ἂν βουληθῶσι διαθέσθαι καὶ συνυποδεῖξαί τι τῶν κατὰ μέρος, τοιοῦτοι φαίνονται καὶ πάντως οἷος Ἔφορος. —", "st": "12.25f"}, {"sp": "N", "t": "ὅτι οὔτε περὶ τῶν κατὰ πόλεμον συμβαινόντων δυνατόν ἐστι γράψαι καλῶς τὸν μηδεμίαν ἐμπειρίαν ἔχοντα τῶν πολεμικῶν ἔργων οὔτε περὶ τῶν ἐν ταῖς πολιτείαις τὸν μὴ πεπειραμένον τῶν τοιούτων πράξεων καὶ περιστάσεων. λοιπὸν οὔτ’ ἐμπείρως ὑπὸ τῶν βυβλιακῶν οὔτ’ ἐμφαντικῶς οὐδενὸς γραφομένου συμβαίνει τὴν πραγματείαν ἄπρακτον γίνεσθαι τοῖς ἐντυγχάνουσιν· εἰ γὰρ ἐκ τῆς ἱστορίας ἐξέλοι τις τὸ δυνάμενον ὠφελεῖν ἡμᾶς, τὸ λοιπὸν αὐτῆς ἄζηλον καὶ ἀνωφελὲς γίνεται παντελῶς. ἔτι δὲ περὶ τῶν πόλεων καὶ τόπων ὅταν ἐπιβάλωνται γράφειν τὰ κατὰ μέρος, ὄντες ἀτριβεῖς τῆς τοιαύτης ἐμπειρίας, δῆλον ὡς ἀνάγκη συμβαίνειν τὸ παραπλήσιον, καὶ πολλὰ μὲν ἀξιόλογα παραλείπειν, περὶ πολλῶν δὲ ποιεῖσθαι πολὺν λόγον οὐκ ἀξίων ὄντων· ὃ δὴ συμβαίνει μάλιστα Τιμαίῳ διὰ τὴν ἀορασίαν. —", "st": "12.25g"}, {"sp": "N", "t": "ὅτι Τίμαιός φησιν ἐν τῇ τριακοστῇ καὶ τετάρτῃ βύβλῳ \"πεντήκοντα συνεχῶς ἔτη διατρίψας Ἀθήνησι ξενιτεύων καὶ πάσης ὁμολογουμένως ἄπειρος [ἐγένετο] πολεμικῆς χρείας, ἔτι δὲ καὶ τῆς τῶν τόπων θέας\". λοιπὸν ὅταν εἴς τι τῶν μερῶν τούτων ἐμπέσῃ κατὰ τὴν ἱστορίαν, πολλὰ μὲν ἀγνοεῖ καὶ ψεύδεται· κἄν ποτε δὲ τῆς ἀληθείας ἐπιψαύσῃ, παραπλήσιός ἐστι τοῖς ζωγράφοις τοῖς ἀπὸ τῶν ἀνασεσαγμένων θυλάκων ποιουμένοις τὰς ὑπογραφάς· καὶ γὰρ ἐπ’ ἐκείνων ἡ μὲν ἐκτὸς ἐνίοτε γραμμὴ σῴζεται, τὸ δὲ τῆς ἐμφάσεως καὶ τῆς ἐνεργείας τῶν ἀληθινῶν ζῴων ἄπεστιν, ὅπερ ἴδιον ὑπάρχει τῆς ζωγραφικῆς τέχνης. τὸ δ’ αὐτὸ συμβαίνει καὶ περὶ Τίμαιον καὶ καθόλου τοὺς ἀπὸ ταύτης τῆς βυβλιακῆς ἕξεως ὁρμωμένους· ἡ γὰρ ἔμφασις τῶν πραγμάτων αὐτοῖς ἄπεστι διὰ τὸ μόνον ἐκ τῆς αὐτοπαθείας τοῦτο γίνεσθαι τῆς τῶν συγγραφέων· ὅθεν οὐκ ἐντίκτουσιν ἀληθινοὺς ζήλους τοῖς ἀκούουσιν οἱ μὴ δι’ αὐτῶν πεπορευμένοι τῶν πραγμάτων. ᾗ καὶ τοιαύτας ᾤοντο δεῖν ἐν τοῖς ὑπομνήμασιν ὑπάρχειν ἐμφάσεις οἱ πρὸ ἡμῶν ὥσθ’, ὅτε μὲν ὑπὲρ πολιτικῶν ὁ λόγος εἴη πραγμάτων, ἐπιφθέγγεσθαι διότι κατ’ ἀνάγκην ὁ γράφων πεπολίτευται καὶ πεῖραν ἔσχηκε τῶν ἐν τούτῳ τῷ μέρει συμβαινόντων, ὅτε δὲ περὶ πολεμικῶν, ὅτι πάλιν ἐστράτευκε καὶ κεκινδύνευκε, καὶ μὴν ὅτε περὶ βιωτικῶν, ὅτι τέτραφε τέκνα καὶ μετὰ γυναικὸς ἔζηκε. τὸ δὲ παραπλήσιον καὶ περὶ τῶν ἄλλων τοῦ βίου μερῶν· ὃ παρὰ μόνοις εἰκὸς εὑρίσκεσθαι τῶν συγγραφέων τοῖς δι’ αὐτῶν πεπορευμένοις τῶν πραγμάτων καὶ τοῦτο τὸ μέρος περιπεποιημένοις τῆς ἱστορίας. πάντων μὲν οὖν οἷον αὐτουργὸν γενέσθαι καὶ δράστην δυσχερὲς ἴσως, τῶν μέντοι μεγίστων καὶ κοινοτάτων ἀναγκαῖον.", "st": "12.25h"}, {"sp": "N", "t": "ὅτι δὲ τὸ λεγόμενον οὐκ ἀδύνατον, ἱκανὸν ὑπόδειγμα πρὸς πίστιν ὁ ποιητής, παρ’ ᾧ πολὺ τὸ τῆς τοιαύτης ἐμφάσεως ἴδοι τις ἂν ὑπάρχον. ἐξ ὧν πᾶς ἂν εἰκότως συγκατάθοιτο τρίτον εἶναι μέρος τῆς ἱστορίας καὶ τρίτην ἔχειν τάξιν τὴν ἐκ τῶν ὑπομνημάτων πολυπραγμοσύνην. ὡς δ’ ἀληθές ἐστι τὸ νυνὶ λεγόμενον καὶ ἐκφανέστατον γένοιτ’ ἂν ἐπί τε τῶν συμβουλευτικῶν καὶ παρακλητικῶν, ἔτι δὲ πρεσβευτικῶν λόγων, οἷς κέχρηται Τίμαιος. ὀλίγοι μὲν γὰρ καιροὶ πάντας ἐπιδέχονται διαθέσθαι τοὺς ἐνόντας λόγους, οἱ δὲ πλεῖστοι βραχεῖς [καί] τινας τῶν ὑπόντων, καὶ τούτων τινὰς μὲν οἱ νῦν, ἄλλους δ’ οἱ προγεγονότες, καὶ τινὰς μὲν Αἰτωλοὶ προσίενται, τινὰς δὲ Πελοποννήσιοι, τινὰς δ’ Ἀθηναῖοι. καὶ τὸ μὲν ματαίως καὶ ἀκαίρως [καὶ] πρὸς πάντα πάντας διεξιέναι τοὺς ἐνόντας λόγους, ὃ ποιεῖ Τίμαιος πρὸς πᾶσαν ὑπόθεσιν εὑρεσιλογῶν, τελέως ἀνάληθες καὶ μειρακιῶδες καὶ διατριβικόν — ἅμα καὶ πολλοῖς ἀποτυχίας αἴτιον ἤδη τοῦτο γέγονε καὶ καταφρονήσεως — τὸ δὲ τοὺς ἁρμόζοντας καὶ καιρίους ἀεὶ λαμβάνειν, τοῦτ’ ἀναγκαῖον. ἀστάτου δὲ τῆς χρείας οὔσης καὶ πόσοις καὶ ποίοις τῶν ἐνόντων χρηστέον, ἀλλοιοτέρου τινὸς δεῖ ζήλου καὶ παραγγέλματος, εἰ μέλλομεν μὴ βλάπτειν, ἀλλ’ ὠφελεῖν τοὺς ἀναγινώσκοντας. ἔστι μὲν οὖν ὁ καιρὸς ἐν πᾶσι δυσπαράγγελτος, οὐ μὴν ἀδύνατος εἰς ὑπόνοιαν ἀχθῆναι διὰ τῶν ἐκ τῆς αὐτοπαθείας καὶ τριβῆς θεωρημάτων· ἐπὶ δὲ τοῦ παρόντος μάλιστ’ ἂν ὑπονοηθείη τὸ λεγόμενον ἐκ τούτων. εἰ γὰρ οἱ συγγραφεῖς ὑποδείξαντες τοὺς καιροὺς καὶ τὰς ὁρμὰς καὶ διαθέσεις τῶν βουλευομένων, κἄπειτα τοὺς κατ’ ἀλήθειαν ῥηθέντας λόγους ἐκθέντες διασαφήσαιεν ἡμῖν τὰς αἰτίας, δι’ ἃς ἢ κατευστοχῆσαι συνέβη τοὺς εἰπόντας ἢ διαπεσεῖν, γένοιτ’ ἄν τις ἔννοια τοῦ πράγματος ἀληθινή, καὶ δυναίμεθ’ ἂν ἅμα μὲν διακρίνοντες, ἅμα δὲ μεταφέροντες ἐπὶ τὰ παραπλήσια κατευστοχεῖν ἀεὶ τῶν προκειμένων. ἀλλ’ ἔστιν, οἶμαι, τὸ μὲν αἰτιολογεῖν δυσχερές, τὸ δὲ ῥησικοπεῖν ἐν τοῖς βυβλίοις ῥᾴδιον, καὶ τὸ μὲν ὀλίγα καιρίως εἰπεῖν καὶ τούτου παραγγελίαν εὑρεῖν ὀλίγοις ἐφικτόν, τὸ δὲ πολλὰ διαθέσθαι καὶ ματαίως τῶν ἐν μέσῳ κειμένων καὶ κοινόν.", "st": "12.25i"}, {"sp": "N", "t": "ἵνα δὲ καὶ περὶ ταῦτα βεβαιωσώμεθα τὴν ἀπόφασιν τὴν ὑπὲρ Τιμαίου, καθάπερ καὶ τὴν ὑπὲρ τῆς ἀγνοίας, ἔτι δὲ τῆς ἑκουσίου ψευδογραφίας, βραχέα προοισόμεθα τῶν ὁμολογουμένων αὐτοῦ λόγων ἐπ’ ὀνόματος. — ὅτι τῶν δεδυναστευκότων ἐν Σικελίᾳ μετὰ Γέλωνα τὸν ἀρχαῖον πραγματικωτάτους ἄνδρας παρειλήφαμεν Ἑρμοκράτην, Τιμολέοντα, Πύρρον τὸν Ἠπειρώτην, οἷς ἥκιστ’ ἂν δέοι περιάπτειν μειρακιώδεις καὶ διατριβικοὺς λόγους. ὁ δέ φησιν ἐν τῇ μιᾷ καὶ εἰκοστῇ βύβλῳ, καθ’ ὃν καιρὸν Εὐρυμέδων παραγενόμενος εἰς Σικελίαν παρεκάλει τὰς πόλεις εἰς τὸν κατὰ τῶν Συρακοσίων πόλεμον, τότε τοὺς Γελῴους κάμνοντας τῷ πολέμῳ διαπέμψασθαι πρὸς τοὺς Καμαριναίους ὑπὲρ ἀνοχῶν· τῶν δὲ προθύμως δεξαμένων, μετὰ ταῦτα πρεσβεύειν ἑκατέρους πρὸς τοὺς ἑαυτῶν συμμάχους καὶ παρακαλεῖν ἄνδρας ἐκπέμψαι πιστούς, οἵτινες εἰσελθόντες εἰς Γέλαν βουλεύσονται περὶ διαλύσεως καὶ τῶν κοινῇ συμφερόντων. παραγενομένων δὲ τῶν συνέδρων, καὶ διαβουλίου προτεθέντος τοιούτοις τισὶ χρώμενον εἰσάγει λόγοις τὸν Ἑρμοκράτην. ἐπαινέσας γὰρ ὁ προειρημένος ἀνὴρ τοὺς Γελῴους καὶ τοὺς Καμαριναίους, πρῶτον μὲν ὡς αὐτῶν ποιησάντων τὰς ἀνοχάς, δεύτερον ὅτι τοῦ περὶ διαλύσεως γενέσθαι λόγους αἴτιοι καθεστήκασι, τρίτον ὅτι προνοηθεῖεν τοῦ μὴ βουλεύεσθαι τὰ πλήθη περὶ τῶν διαλύσεων, ἀλλὰ τοὺς προεστῶτας τῶν πολιτῶν τοὺς σαφῶς εἰδότας τίνα διαφορὰν ὁ πόλεμος ἔχει τῆς εἰρήνης, μετὰ δὲ ταῦτα δύ’ ἢ τρία λαβὼν ἐπιχειρήματα πραγματικά, λοιπόν φησιν αὐτοὺς ἐπιστήσαντας μαθεῖν ἡλίκην ὁ πόλεμος διαφορὰν ἔχει τῆς εἰρήνης, μικρῷ πρότερον εἰρηκὼς ὅτι κατ’ αὐτὸ τοῦτο χάριν ἔχει τοῖς Γελῴοις τὸ μὴ γίνεσθαι τοὺς λόγους ἐν τοῖς πολλοῖς ἀλλ’ ἐν συνεδρίῳ καλῶς γινώσκοντι τὰς τοιαύτας περιπετείας. ἐξ ὧν ὁ Τίμαιος οὐ μόνον τῆς πραγματικῆς ἂν δόξειεν ἀπολείπεσθαι δυνάμεως, ἀλλὰ καὶ τῶν ἐν ταῖς διατριβαῖς ἐπιχειρήσεων οὐκ ὀλίγον ἐλαττοῦσθαι. πάντες γὰρ δήπουθεν οἴονται δεῖν τὰς ἀποδείξεις φέρειν τῶν ἀγνοουμένων καὶ τῶν ἀπιστουμένων παρὰ τοῖς ἀκροαταῖς, περὶ δὲ τῶν ἤδη γινωσκομένων ματαιότατον εἶναι πάντων καὶ παιδαριωδέστατον τὸ καθευρεσιλογεῖν … μενον ἢ τὸ γινωσκόμενον. ὁ δὲ χωρὶς τῆς ὅλης παραπτώσεως τοῦ διατεθεῖσθαι τὸ πλεῖστον μέρος τοῦ λόγου πρὸς τὰ καθάπαξ μὴ προσδεόμενα λόγου καὶ λήμμασι κέχρηται τοιούτοις, οἷς τὸν μὲν Ἑρμοκράτην τίς ἂν κεχρῆσθαι πιστεύσειε, τὸν συναγωνισάμενον μὲν Λακεδαιμονίοις τὴν ἐν Αἰγὸς ποταμοῖς ναυμαχίαν, αὐτανδρὶ δὲ χειρωσάμενον τὰς Ἀθηναίων δυνάμεις καὶ τοὺς στρατηγοὺς κατὰ Σικελίαν, ἀλλ’ οὐδὲ μειράκιον τὸ τυχόν;", "st": "12.25k"}, {"sp": "N", "t": "ὅς γε πρῶτον μὲν οἴεται δεῖν ἀναμνησθῆναι τοὺς συνέδρους διότι τοὺς κοιμωμένους τὸν ὄρθρον ἐν μὲν τῷ πολέμῳ διεγείρουσιν αἱ σάλπιγγες, κατὰ δὲ τὴν εἰρήνην οἱ ὄρνιθες. μετὰ δὲ ταῦτα τὸν Ἡρακλέα φησὶ τὸν μὲν Ὀλυμπίων ἀγῶνα θεῖναι καὶ τὴν ἐκεχειρίαν δεῖγμα ποιούμενον τῆς αὑτοῦ προαιρέσεως, ὅσοις δ’ ἐπολέμησε, τούτους πάντας βεβλαφέναι κατὰ τὴν ἀνάγκην καὶ κατ’ ἐπιταγήν, ἑκουσίως δὲ παραίτιον οὐδενὶ γεγονέναι κακοῦ τῶν ἀνθρώπων. ἑξῆς δὲ τούτοις παρὰ μὲν τῷ ποιητῇ τὸν Δία παρεισάγεσθαι δυσαρεστούμενον τῷ Ἄρει καὶ λέγοντα ἔχθιστος δέ μοί ἐσσι θεῶν, οἳ Ὄλυμπον ἔχουσιν· αἰεὶ γάρ τοι ἔρις τε φίλη πόλεμοί τε μάχαι τε. ὁμοίως δὲ καὶ τὸν φρονιμώτατον τῶν ἡρώων λέγειν ἀφρήτωρ, ἀθέμιστος, ἀνέστιός ἐστιν ἐκεῖνος ὃς πολέμου ἔραται ἐπιδημίου ὀκρυόεντος. ὁμογνωμονεῖν δὲ τῷ ποιητῇ καὶ τὸν Εὐριπίδην, ἐν οἷς φησιν, εἰρήνα βαθύπλουτε, καλλίστα μακάρων θεῶν, ζῆλός μοι σέθεν, ὡς χρονίζεις. δέδοικα δὲ μὴ πρὶν ὑπερβάλῃ με γῆρας, πρὶν σὰν χαρίεσσαν προσιδεῖν ὥραν καὶ καλλιχόρους ἀοιδὰς φιλοστεφάνους τε κώμους. ἔτι δὲ πρὸς τούτοις ὁμοιότατον εἶναί φησι τὸν μὲν πόλεμον τῇ νόσῳ, τὴν δ’ εἰρήνην τῇ ὑγιείᾳ· τὴν μὲν γὰρ καὶ τοὺς κάμνοντας ἀναλαμβάνειν, ἐν ᾧ δὲ καὶ τοὺς ὑγιαίνοντας ἀπόλλυσθαι. καὶ κατὰ μὲν τὴν εἰρήνην τοὺς πρεσβυτέρους ὑπὸ τῶν νέων θάπτεσθαι κατὰ φύσιν, ἐν δὲ τῷ πολέμῳ τἀναντία, τὸ δὲ μέγιστον ἐν μὲν τῷ πολέμῳ μηδ’ ἄχρι τῶν τειχῶν εἶναι τὴν ἀσφάλειαν, κατὰ δὲ τὴν εἰρήνην μέχρι τῶν τῆς χώρας ὅρων, καὶ τούτοις ἕτερα παραπλήσια. θαυμάζω δὴ τίσι ποτ’ ἂν ἄλλοις ἐχρήσατο λόγοις ἢ προφοραῖς μειράκιον ἄρτι γενόμενον περὶ διατριβὰς καὶ τὰς ἐκ τῶν ὑπομνημάτων πολυπραγμοσύνας καὶ βουλόμενον παραγγελματικῶς ἐκ τῶν παρεπομένων τοῖς προσώποις ποιεῖσθαι τὴν ἐπιχείρησιν· δοκεῖ γὰρ οὐχ ἑτέροις, ἀλλὰ τούτοις οἷς Τίμαιος Ἑρμοκράτην κεχρῆσθαί φησι.", "st": "12.26"}, {"sp": "N", "t": "τί δὲ πάλιν ὅταν ὁ Τιμολέων ἐν τῇ αὐτῇ βύβλῳ παρακαλῶν τοὺς Ἕλληνας πρὸς τὸν ἐπὶ τοὺς Καρχηδονίους κίνδυνον, καὶ μόνον οὐκ ἤδη μελλόντων συνάγειν εἰς τὰς χεῖρας τοῖς ἐχθροῖς πολλαπλασίοις οὖσι, πρῶτον μὲν ἀξιοῖ μὴ βλέπειν αὐτοὺς πρὸς τὸ πλῆθος τῶν ὑπεναντίων, ἀλλὰ πρὸς τὴν ἀνανδρίαν; καὶ γὰρ τῆς Λιβύης ἁπάσης συνεχῶς οἰκουμένης καὶ πληθυούσης ἀνθρώπων, ὅμως ἐν ταῖς παροιμίαις, ὅταν περὶ ἐρημίας ἔμφασιν βουλώμεθα ποιῆσαι, λέγειν ἡμᾶς \"ἐρημότερα τῆς Λιβύης\", οὐκ ἐπὶ τὴν ἐρημίαν φέροντας τὸν λόγον, ἀλλ’ ἐπὶ τὴν ἀνανδρίαν τῶν κατοικούντων. καθόλου δέ, φησί, τίς ἂν φοβηθείη τοὺς ἄνδρας, οἵτινες τῆς φύσεως τοῦτο τοῖς ἀνθρώποις δεδωκυίας ἴδιον παρὰ τὰ λοιπὰ τῶν ζῴων, λέγω δὲ τὰς χεῖρας, ταύτας παρ’ ὅλον τὸν βίον ἐντὸς τῶν χιτώνων ἔχοντες ἀπράκτους περιφέρουσι; τὸ δὲ μέγιστον ὅτι καὶ ὑπὸ τοῖς χιτωνίσκοις, φησί, περιζώματα φοροῦσιν, ἵνα μηδ’ ὅταν ἀποθάνωσιν ἐν ταῖς μάχαις φανεροὶ γένωνται τοῖς ὑπεναντίοις …", "st": "12.26a"}, {"sp": "N", "t": "ὅτι Γέλωνος ἐπαγγελλομένου τοῖς Ἕλλησι δισμυρίοις πεζοῖς, διακοσίαις δὲ ναυσὶ καταφράκτοις βοηθήσειν, ἐὰν αὐτῷ τῆς ἡγεμονίας ἢ τῆς κατὰ γῆν ἢ τῆς κατὰ θάλατταν παραχωρήσωσι, φασὶ τοὺς προκαθημένους ἐν Κορίνθῳ τῶν Ἑλλήνων πραγματικώτατον ἀπόκριμα δοῦναι τοῖς παρὰ τοῦ Γέλωνος πρεσβευταῖς· ἐκέλευον γὰρ ὡς ἐπίκουρον ἔρχεσθαι τὸν Γέλωνα μετὰ τῶν δυνάμεων, τὴν δ’ ἡγεμονίαν ἀνάγκῃ τὰ πράγματα περιθήσειν τοῖς ἀρίστοις τῶν ἀνδρῶν· τοῦτο δ’ ἐστὶν οὐ καταφευγόντων ἐπὶ τὰς Συρακοσίων ἐλπίδας, ἀλλὰ πιστευόντων αὑτοῖς καὶ προκαλουμένων τὸν βουλόμενον ἐπὶ τὸν τῆς ἀνδρείας ἀγῶνα καὶ τὸν περὶ τῆς ἀρετῆς στέφανον. ἀλλ’ ὅμως Τίμαιος εἰς ἕκαστα τῶν προειρημένων τοσούτους ἐκτείνει λόγους καὶ τοιαύτην ποιεῖται σπουδὴν περὶ τοῦ τὴν μὲν Σικελίαν μεγαλομερεστέραν ποιῆσαι τῆς συμπάσης Ἑλλάδος, τὰς δ’ ἐν αὐτῇ πράξεις ἐπιφανεστέρας καὶ καλλίους τῶν κατὰ τὴν ἄλλην οἰκουμένην, τῶν δ’ ἀνδρῶν τῶν μὲν σοφίᾳ διενηνοχότων σοφωτάτους τοὺς ἐν Σικελίᾳ, τῶν δὲ πραγματικῶν ἡγεμονικωτάτους καὶ θειοτάτους τοὺς ἐκ Συρακουσῶν, ὥστε μὴ καταλιπεῖν ὑπερβολὴν τοῖς μειρακίοις τοῖς ἐν ταῖς διατριβαῖς καὶ τοῖς περιπάτοις πρὸς τὰς παραδόξους ἐπιχειρήσεις, ὅταν ἢ Θερσίτου λέγειν ἐγκώμιον ἢ Πηνελόπης πρόθωνται ψόγον ἤ τινος ἑτέρου τῶν τοιούτων.", "st": "12.26b"}, {"sp": "N", "t": "λοιπὸν ἐκ τούτων διὰ τὴν ὑπερβολὴν τῆς παραδοξολογίας οὐκ εἰς σύγκρισιν, ἀλλ’ εἰς καταμώκησιν ἄγει καὶ τοὺς ἄνδρας καὶ τὰς πράξεις ὧν βούλεται προΐστασθαι, καὶ σχεδὸν εἰς τὸ παραπλήσιον ἐμπίπτει τοῖς περὶ τοὺς ἐν Ἀκαδημείᾳ λόγους πρὸς τὸν προχειρότατον λόγον ἠσκηκόσι. καὶ γὰρ ἐκείνων τινὲς βουλόμενοι περί τε τῶν προφανῶς καταληπτῶν εἶναι δοκούντων καὶ περὶ τῶν ἀκαταλήπτων εἰς ἀπορίαν ἄγειν τοὺς προσδιαλεγομένους τοιαύταις χρῶνται παραδοξολογίαις καὶ τοιαύτας εὐποροῦσι πιθανότητας ὥστε διαπορεῖν εἰ δυνατόν ἐστι τοὺς ἐν Ἀθήναις ὄντας ὀσφραίνεσθαι τῶν ἑψομένων ᾠῶν ἐν Ἐφέσῳ καὶ διστάζειν μή πως, καθ’ ὃν καιρὸν ἐν Ἀκαδημείᾳ διαλέγονται περὶ τούτων, οὐχ ὕπαρ, ἀλλ’ ὄναρ ἐν οἴκῳ κατακείμενοι τούτους διατίθενται τοὺς λόγους. ἐξ ὧν διὰ τὴν ὑπερβολὴν τῆς παραδοξολογίας εἰς διαβολὴν ἤχασι τὴν ὅλην αἵρεσιν, ὥστε καὶ τὰ καλῶς ἀπορούμενα παρὰ τοῖς ἀνθρώποις εἰς ἀπιστίαν ἦχθαι. καὶ χωρὶς τῆς ἰδίας ἀστοχίας καὶ τοῖς νέοις τοιοῦτον ἐντετόκασι ζῆλον, ὥστε τῶν μὲν ἠθικῶν καὶ πραγματικῶν λόγων μηδὲ τὴν τυχοῦσαν ἐπίνοιαν ποιεῖσθαι συμβαίνει, δι’ ὧν ὄνησις τοῖς φιλοσοφοῦσι, περὶ δὲ τὰς ἀνωφελεῖς καὶ παραδόξους εὑρεσιλογίας κενοδοξοῦντες κατατρίβουσι τοὺς βίους.", "st": "12.26c"}, {"sp": "N", "t": "τὸ δ’ αὐτὸ καὶ Τιμαίῳ συμβέβηκε περὶ τὴν ἱστορίαν καὶ τοῖς τούτου ζηλωταῖς· παραδοξολόγος γὰρ ὢν καὶ φιλόνεικος περὶ τὸ προτεθὲν τοὺς μὲν πολλοὺς καταπέπληκται τοῖς λόγοις, ἠνάγκακε δ’ αὑτῷ προσέχειν διὰ τὴν ἐπίφασιν τῆς ἀληθινολογίας, τινὰς δὲ καὶ προσκέκληται καὶ μετ’ ἀποδείξεως δοκεῖ πείσειν. καὶ μάλιστα ταύτην γ’ ἐνείργασται τὴν δόξαν ἐκ τῶν περὶ τὰς ἀποικίας καὶ κτίσεις καὶ συγγενείας ἀποφάσεων· ἐν γὰρ τούτοις τηλικαύτην ἐπίφασιν ποιεῖ διὰ τῆς ἀκριβολογίας καὶ τῆς πικρίας τῆς ἐπὶ τῶν ἐλέγχων, οἷς χρῆται κατὰ τῶν πέλας, ὥστε δοκεῖν τοὺς ἄλλους συγγραφέας ἅπαντας συγκεκοιμῆσθαι τοῖς πράγμασι καὶ κατεσχεδιακέναι τῆς οἰκουμένης, αὐτὸν δὲ μόνον ἐξητακέναι τὴν ἀκρίβειαν καὶ διευκρινηκέναι τὰς ἐν ἑκάστοις ἱστορίας, ἐν οἷς πολλὰ μὲν ὑγιῶς λέγεται, πολλὰ δὲ καὶ ψευδῶς.", "st": "12.26d"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ οἱ πλείω χρόνον συντραφέντες αὐτοῦ τοῖς πρώτοις ὑπομνήμασιν, ἐν οἷς αἱ περὶ τῶν προειρημένων εἰσὶ συντάξεις, ὅταν ἅπασαν συνταξαμένῳ τὴν ὑπερβολὴν τῆς ἐπαγγελίας ἀποπιστεύσωσι, κἄπειτά τις αὐτοῖς ἀποδεικνύῃ τὸν Τίμαιον, ἐν οἷς πικρότατός ἐστι κατὰ τῶν πέλας, αὐτὸν ἔνοχον ὄντα, καθάπερ ἡμεῖς ἀρτίως ἐπὶ τῶν Λοκρῶν καὶ τῶν ἑξῆς παραπαίοντα συνεστήσαμεν, δυσέριδες γίνονται καὶ φιλόνεικοι καὶ δυσμετάθετοι, καὶ σχεδὸν ὡς ἔπος εἰπεῖν οἱ φιλοπονώτατα προσεδρεύσαντες τοῖς ὑπομνήμασιν αὐτοῦ τοῦτ’ ἀποφέρονται τὸ λυσιτελὲς ἐκ τῆς ἀναγνώσεως. οἵ γε μὴν ταῖς δημηγορίαις προσσχόντες αὐτοῦ καὶ καθόλου τοῖς διεξοδικοῖς λόγοις μειρακιώδεις καὶ διατριβικοὶ καὶ τελέως ἀναλήθεις γίνονται διὰ τὰς ἄρτι ῥηθείσας αἰτίας.", "st": "12.26e"}, {"sp": "N", "t": "λοιπὸν δὲ τὸ πραγματικὸν αὐτῷ μέρος τῆς ἱστορίας ἐκ πάντων σύγκειται τῶν ἁμαρτημάτων, ὧν τὰ πλεῖστα διεληλύθαμεν· τὴν δ’ αἰτίαν τῆς ἁμαρτίας νῦν ἐροῦμεν, ἥτις οὐκ ἔνδοξος μὲν φανεῖται τοῖς πλείστοις, ἀληθινωτάτη δ’ εὑρεθήσεται τῶν Τιμαίου κατηγορημάτων. δοκεῖ μὲν γὰρ καὶ τὴν ἐμπειρικὴν περὶ ἕκαστα δύναμιν καὶ τὴν ἐπὶ τῆς πολυπραγμοσύνης ἕξιν παρεσκευάσθαι καὶ συλλήβδην φιλοπόνως προσεληλυθέναι πρὸς τὸ γράφειν τὴν ἱστορίαν, ἐν ἐνίοις δ’ οὐδεὶς οὔτ’ ἀπειρότερος οὔτ’ ἀφιλοπονώτερος φαίνεται γεγονέναι τῶν ἐπ’ ὀνόματος συγγραφέων. δῆλον δ’ ἔσται τὸ λεγόμενον ἐκ τούτων.", "st": "12.27"}, {"sp": "N", "t": "δυεῖν γὰρ ὄντων κατὰ φύσιν ὡς ἂν εἴ τινων ὀργάνων ἡμῖν, οἷς πάντα πυνθανόμεθα καὶ πολυπραγμονοῦμεν [ἀκοῆς καὶ ὁράσεως], ἀληθινωτέρας δ’ οὔσης οὐ μικρῷ τῆς ὁράσεως κατὰ τὸν Ἡράκλειτον — ὀφθαλμοὶ γὰρ τῶν ὤτων ἀκριβέστεροι μάρτυρες — τούτων Τίμαιος τὴν ἡδίω μέν, ἥττω δὲ τῶν ὁδῶν ὥρμησε πρὸς τὸ πολυπραγμονεῖν. τῶν μὲν γὰρ διὰ τῆς ὁράσεως εἰς τέλος ἀπέστη, τῶν δὲ διὰ τῆς ἀκοῆς ἀντεποιήσατο. καὶ ταύτης διμεροῦς οὔσης τινός, τοῦ μὲν διὰ τῶν ὑπομνημάτων τὸ δὲ περὶ τὰς ἀνακρίσεις ῥᾳθύμως ἀνεστράφη, καθάπερ ἐν τοῖς ἀνώτερον ἡμῖν δεδήλωται. δι’ ἣν δ’ αἰτίαν ταύτην ἔσχε τὴν αἵρεσιν εὐχερὲς καταμαθεῖν· ὅτι τὰ μὲν ἐκ τῶν βυβλίων δύναται πολυπραγμονεῖσθαι χωρὶς κινδύνου καὶ κακοπαθείας, ἐάν τις αὐτὸ τοῦτο προνοηθῇ μόνον ὥστε λαβεῖν ἢ πόλιν ἔχουσαν ὑπομνημάτων πλῆθος ἢ βυβλιοθήκην που γειτνιῶσαν. λοιπὸν κατακείμενον ἐρευνᾶν δεῖ τὸ ζητούμενον καὶ συγκρίνειν τὰς τῶν προγεγονότων συγγραφέων ἀγνοίας ἄνευ πάσης κακοπαθείας. ἡ δὲ πολυπραγμοσύνη πολλῆς μὲν προσδεῖται ταλαιπωρίας καὶ δαπάνης, μέγα δέ τι συμβάλλεται καὶ μέγιστόν ἐστι μέρος τῆς ἱστορίας. δῆλον δὲ τοῦτ’ ἐστὶν ἐξ αὐτῶν τῶν τὰς συντάξεις πραγματευομένων. ὁ μὲν γὰρ Ἔφορός φησιν, εἰ δυνατὸν ἦν αὐτοὺς παρεῖναι πᾶσι τοῖς πράγμασι, ταύτην ἂν διαφέρειν πολὺ τῶν ἐμπειριῶν· ὁ δὲ Θεόπομπος τοῦτον μὲν ἄριστον ἐν τοῖς πολεμικοῖς τὸν πλείστοις κινδύνοις παρατετευχότα, τοῦτον δὲ δυνατώτατον ἐν λόγῳ τὸν πλείστων μετεσχηκότα πολιτικῶν ἀγώνων. τὸν αὐτὸν δὲ τρόπον συμβαίνειν ἐπ’ ἰατρικῆς καὶ κυβερνητικῆς. ἔτι δὲ τούτων ἐμφαντικώτερον ὁ ποιητὴς εἴρηκε περὶ τούτου τοῦ μέρους. ἐκεῖνος γὰρ βουλόμενος ὑποδεικνύειν ἡμῖν οἷον δεῖ τὸν ἄνδρα τὸν πραγματικὸν εἶναι, προθέμενος τὸ τοῦ Ὀδυσσέως πρόσωπον λέγει πως οὕτως· ἄνδρα μοι ἔννεπε, Μοῦσα, πολύτροπον, ὃς μάλα πολλὰ πλάγχθη, καὶ προβάς, πολλῶν δ’ ἀνθρώπων ἴδεν ἄστεα καὶ νόον ἔγνω, πολλὰ δ’ ὅγ’ ἐν πόντῳ πάθεν ἄλγεα ὃν κατὰ θυμόν, καὶ ἔτι ἀνδρῶν τε πτολέμους ἀλεγεινά τε κύματα πείρων.", "st": "12.27"}, {"sp": "N", "t": "δοκεῖ δέ μοι καὶ τὸ τῆς ἱστορίας πρόσχημα τοιοῦτον ἄνδρα ζητεῖν. ὁ μὲν οὖν Πλάτων φησὶ τότε τἀνθρώπεια καλῶς ἕξειν, ὅταν ἢ οἱ φιλόσοφοι βασιλεύσωσιν ἢ οἱ βασιλεῖς φιλοσοφήσωσι· κἀγὼ δ’ ἂν εἴποιμι διότι τὰ τῆς ἱστορίας ἕξει τότε καλῶς, ὅταν ἢ οἱ πραγματικοὶ τῶν ἀνδρῶν γράφειν ἐπιχειρήσωσι τὰς ἱστορίας, μὴ καθάπερ νῦν παρέργως, νομίσαντες δὲ καὶ τοῦτ’ εἶναι σφίσι τῶν ἀναγκαιοτάτων καὶ καλλίστων, ἀπερίσπαστοι παράσχωνται πρὸς τοῦτο τὸ μέρος κατὰ τὸν βίον, ἢ οἱ γράφειν ἐπιβαλλόμενοι τὴν ἐξ αὐτῶν τῶν πραγμάτων ἕξιν ἀναγκαίαν ἡγήσωνται πρὸς τὴν ἱστορίαν. πρότερον δ’ οὐκ ἔσται παῦλα τῆς τῶν ἱστοριογράφων ἀγνοίας. ὧν Τίμαιος οὐδὲ τὴν ἐλαχίστην πρόνοιαν θέμενος, ἀλλὰ καταβιώσας ἐν ἑνὶ τόπῳ ξενιτεύων, καὶ σχεδὸν ὡς εἰ κατὰ πρόθεσιν ἀπειπάμενος καὶ τὴν ἐνεργητικὴν τὴν περὶ τὰς πολεμικὰς καὶ πολιτικὰς πράξεις καὶ τὴν ἐκ τῆς πλάνης καὶ θέας αὐτοπάθειαν, οὐκ οἶδ’ ὅπως ἐκφέρεται δόξαν ὡς ἕλκων τὴν τοῦ συγγραφέως προστασίαν. καὶ διότι τοιοῦτός ἐστιν αὐτὸν ἀνθομολογούμενον εὐχερὲς παραστῆσαι τὸν Τίμαιον. κατὰ γὰρ τὸ προοίμιον τῆς ἕκτης βύβλου φησί τινας ὑπολαμβάνειν διότι τινὸς μείζονος δεῖται φύσεως καὶ φιλοπονίας καὶ παρασκευῆς τὸ τῶν ἐπιδεικτικῶν λόγων γένος ἢ τὸ τῆς ἱστορίας· ταύτας δὲ τὰς δόξας πρότερον μὲν Ἐφόρῳ φησὶ προσπεσεῖν, οὐ δυνηθέντος δ’ ἱκανῶς ἐκείνου πρὸς τοὺς ταῦτα λέγοντας ἀπαντῆσαι, πειρᾶται συγκρίνειν αὐτὸς ἐκ παραβολῆς τὴν ἱστορίαν τοῖς ἐπιδεικτικοῖς λόγοις, πρᾶγμα ποιῶν πάντων ἀτοπώτατον, πρῶτον μὲν τὸ καταψεύσασθαι τοῦ συγγραφέως. ὁ γὰρ Ἔφορος παρ’ ὅλην τὴν πραγματείαν θαυμάσιος ὢν καὶ κατὰ τὴν φράσιν καὶ κατὰ τὸν χειρισμὸν καὶ κατὰ τὴν ἐπίνοιαν τῶν λημμάτων, δεινότατός ἐστιν ἐν ταῖς παρεκβάσεσι καὶ ταῖς ἀφ’ αὑτοῦ γνωμολογίαις, καὶ συλλήβδην ὅταν που τὸν ἐπιμετροῦντα λόγον διατίθηται· κατὰ δέ τινα συντυχίαν εὐχαριστότατα καὶ πιθανώτατα περὶ τῆς συγκρίσεως εἴρηκε τῆς τῶν ἱστοριογράφων καὶ λογογράφων. ὁ δ’ ἵνα μὴ δόξῃ κατακολουθεῖν Ἐφόρῳ, πρὸς τῷ κατεψεῦσθαι ’κείνου καὶ τῶν λοιπῶν ἅμα κατέγνωκε· τὰ γὰρ παρ’ ἄλλων δεόντως κεχειρισμένα μακρῶς καὶ ἀσαφῶς καὶ τρόπῳ παντὶ χεῖρον ἐξηγούμενος οὐδένα τῶν ζώντων ὑπέλαβε τοῦτο παρατηρήσειν.", "st": "12.28"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ βουλόμενος αὔξειν τὴν ἱστορίαν πρῶτον μὲν τηλικαύτην εἶναί φησι διαφορὰν τῆς ἱστορίας πρὸς τοὺς ἐπιδεικτικοὺς λόγους, ἡλίκην ἔχει τὰ κατ’ ἀλήθειαν ᾠκοδομημένα καὶ κατεσκευασμένα τῶν ἐν ταῖς σκηνογραφίαις φαινομένων τόπων καὶ διαθέσεων· δεύτερον αὐτὸ τὸ συναθροῖσαί φησι τὴν παρασκευὴν τὴν πρὸς τὴν ἱστορίαν μεῖζον ἔργον εἶναι τῆς ὅλης πραγματείας τῆς περὶ τοὺς ἐπιδεικτικοὺς λόγους· αὐτὸς γοῦν τηλικαύτην ὑπομεμενηκέναι δαπάνην καὶ κακοπάθειαν τοῦ συναγαγεῖν τὰ παρὰ Κυρνίων ὑπομνήματα καὶ πολυπραγμονῆσαι τὰ Λιγύων ἔθη καὶ Κελτῶν, ἅμα δὲ τούτοις Ἰβήρων, ὥστε μήτ’ ἂν αὐτὸς ἐλπίσαι μήτ’ ἂν ἑτέρους ἐξηγουμένους πιστευθῆναι περὶ τούτων. ἡδέως δέ τις ἂν ἔροιτο τὸν συγγραφέα πότερον ὑπολαμβάνει μείζονος δεῖσθαι δαπάνης καὶ κακοπαθείας τὸ καθήμενον ἐν ἄστει συνάγειν ὑπομνήματα καὶ πολυπραγμονεῖν τὰ Λιγύων ἔθη καὶ Κελτῶν ἢ τὸ πειραθῆναι τῶν πλείστων ἐθνῶν καὶ τόπων αὐτόπτην γενέσθαι. τί δ’ αὖ τὸ πυνθάνεσθαι τὰς παρατάξεις καὶ πολιορκίας, ἔτι δὲ ναυμαχίας, τῶν παρατετυχηκότων τοῖς κινδύνοις, ἢ τὸ πεῖραν λαβεῖν τῶν δεινῶν καὶ τῶν ἅμα τούτοις συμβαινόντων ἐπ’ αὐτῶν τῶν ἔργων; ἐγὼ μὲν γὰρ οὐκ οἴομαι τηλικαύτην διαφορὰν ἔχειν τὰ κατ’ ἀλήθειαν οἰκοδομήματα τῶν ἐν ταῖς σκηνογραφίαις τόπων, οὐδὲ τὴν ἱστορίαν τῶν ἐπιδεικτικῶν λόγων, ἡλίκην ἐπὶ πασῶν τῶν συντάξεων τὴν ἐξ αὐτουργίας καὶ τὴν ἐξ αὐτοπαθείας ἀπόφασιν τῶν ἐξ ἀκοῆς καὶ διηγήματος γραφομένων· ἧς εἰς τέλος ἄπειρος ὢν εἰκότως ὑπέλαβε τὸ πάντων ἐλάχιστον καὶ ῥᾷστον εἶναι μέγιστον καὶ χαλεπώτατον τοῖς πραγματευομένοις τὴν ἱστορίαν, λέγω δὲ τὸ συνάγειν ὑπομνήματα καὶ πυνθάνεσθαι παρὰ τῶν εἰδότων ἕκαστα τῶν πραγμάτων. καίτοι γε περὶ τοῦτο τὸ μέρος ἀνάγκη μεγάλα διαψεύδεσθαι τοὺς ἀπείρους· πῶς γὰρ οἷόν τε καλῶς ἀνακρῖναι περὶ παρατάξεως ἢ πολιορκίας ἢ ναυμαχίας; πῶς δὲ συνεῖναι τῶν ἐξηγουμένων τὰ κατὰ μέρος ἀνεννόητον ὄντα τῶν προειρημένων; οὐ γὰρ ἔλαττον ὁ πυνθανόμενος τῶν ἀπαγγελλόντων συμβάλλεται πρὸς τὴν ἐξήγησιν· ἡ γὰρ τῶν παρεπομένων τοῖς πράγμασιν ὑπόμνησις αὐτὴ χειραγωγεῖ τὸν ἐξηγούμενον ἐφ’ ἕκαστα τῶν συμβεβηκότων· ὑπὲρ ὧν ὁ μὲν ἄπειρος οὔτ’ ἀνακρῖναι τοὺς παραγεγονότας ἱκανός ἐστιν οὔτε συμπαρὼν γνῶναι τὸ γινόμενον, ἀλλὰ κἂν παρῇ, τρόπον τινὰ παρὼν οὐ πάρεστιν.", "st": "12.28a"}, {"sp": "HDR", "t": "Βιβλίον ΙΓʹ", "st": "13"}, {"sp": "N", "t": "ὅτι Αἰτωλοὶ διά τε τὴν συνέχειαν τῶν πολέμων καὶ διὰ τὴν πολυτέλειαν τῶν βίων ἔλαθον οὐ μόνον ἄλλους, ἀλλὰ καὶ σφᾶς αὐτοὺς κατάχρεοι γενηθέντες. διόπερ οἰκείως διακείμενοι πρὸς καινοτομίαν τῆς οἰκείας πολιτείας εἵλοντο νομογράφους Δωρίμαχον καὶ Σκόπαν, θεωροῦντες τούτους κατά τε τὰς προαιρέσεις κινητικοὺς ὑπάρχοντας καὶ κατὰ τὰς οὐσίας ἐνδεδεμένους εἰς πολλὰ τῶν βιωτικῶν συναλλαγμάτων. οἳ καὶ παραλαβόντες τὴν ἐξουσίαν ταύτην ἔγραψαν νόμους. —", "st": "13.1"}, {"sp": "N", "t": "ὅτι Ἀλέξανδρος ὁ Αἰτωλὸς νομοθετοῦντος Δωριμάχου καὶ Σκόπα ἀντέλεγε τοῖς γραφομένοις, ἐκ πολλῶν ἐπιδεικνύμενος ὅτι παρ’ οἷς ἔφυ τοῦτο τὸ φυτόν, οὐδέποτε κατέληξε πρότερον ἢ μεγάλοις κακοῖς περιβαλεῖν τοὺς ἅπαξ αὐτῷ χρησαμένους· διόπερ ἠξίου μὴ μόνον πρὸς τὸ παρὸν ἀποβλέπειν, εἰ κουφισθήσονται τῶν ἐνεστώτων συναλλαγμάτων, ἀλλὰ καὶ πρὸς τὸ μέλλον· ἄτοπον γὰρ εἶναι πολεμοῦντας μὲν καὶ τὸ πνεῦμα προΐεσθαι χάριν τῆς τῶν τέκνων ἀσφαλείας, βουλευομένους δὲ μηδένα ποιεῖσθαι λόγον τοῦ μετὰ ταῦτα χρόνου. —", "st": "13.1"}, {"sp": "N", "t": "ὅτι Σκόπας Αἰτωλῶν στρατηγὸς ἀποτυχὼν τῆς ἀρχῆς, ἧς χάριν ἐτόλμα γράφειν τοὺς νόμους, μετέωρος ἦν εἰς τὴν Ἀλεξάνδρειαν, ταῖς ἐκεῖθεν ἐλπίσι πεπεισμένος ἀναπληρώσειν τὰ λείποντα τοῦ βίου καὶ τὴν τῆς ψυχῆς πρὸς τὸ πλεῖον ἐπιθυμίαν, οὐκ εἰδὼς ὅτι, καθάπερ ἐπὶ τῶν ὑδρωπικῶν οὐδέποτε ποιεῖ παῦλαν οὐδὲ κόρον τῆς ἐπιθυμίας ἡ τῶν ἔξωθεν ὑγρῶν παράθεσις, ἐὰν μὴ τὴν ἐν αὐτῷ τῷ σώματι διάθεσιν ὑγιάσῃ τις, τὸν αὐτὸν τρόπον οὐδὲ τὴν πρὸς τὸ πλεῖον ἐπιθυμίαν οἷόν τε κορέσαι μὴ οὐ τὴν ἐν τῇ ψυχῇ κακίαν λόγῳ τινὶ διορθωσάμενον. ἐμφανέστατον δὲ τοῦτο συνέβη γενέσθαι περὶ τὸν ἄνδρα τοῦτον, ὑπὲρ οὗ νῦν ὁ λόγος. τούτῳ γὰρ εἰς Ἀλεξάνδρειαν ἀφικομένῳ πρὸς ταῖς ἐκ τῶν ὑπαίθρων ὠφελείαις, ὧν ἦν αὐτὸς κύριος διὰ τὸ πιστεύεσθαι περὶ τῶν ὅλων, καὶ τῆς ἡμέρας ἑκάστης ὀψώνιον ἐξέθηκεν ὁ βασιλεὺς αὐτῷ μὲν δεκαμναιαῖον, τοῖς δ’ ἐπί τινος ἡγεμονίας μετ’ αὐτὸν τεταγμένοις μναιαῖον. ἀλλ’ ὅμως οὐκ ἠρκεῖτο τούτοις, ὃς τὸ πρότερον προσκαρτερῶν τῷ πλείονι διετέλεσε, μέχρι διὰ τὴν ἀπληστίαν καὶ παρ’ αὐτοῖς τοῖς διδοῦσι φθονηθεὶς τὸ πνεῦμα προσέθηκε τῷ χρυσίῳ. —", "st": "13.2"}, {"sp": "N", "t": "ἐγένετο περὶ τὴν τοιαύτην κακοπραγμοσύνην, ἣν δὴ βασιλικὴν μὲν οὐδαμῶς οὐδεὶς ἂν εἶναι φήσειεν, ἀναγκαίαν δὲ βούλονται λέγειν ἔνιοι πρὸς τὸν πραγματικὸν τρόπον διὰ τὴν νῦν ἐπιπολάζουσαν κακοπραγμοσύνην. οἱ μὲν γὰρ ἀρχαῖοι πολύ τι τοῦ τοιούτου μέρους ἐκτὸς ἦσαν· τοσοῦτο γὰρ ἀπηλλοτρίωντο τοῦ κακομηχανεῖν περὶ τοὺς φίλους χάριν τοῦ τῷ τοιούτῳ συναύξειν τὰς σφετέρας δυναστείας, ὥστ’ οὐδὲ τοὺς πολεμίους ᾑροῦντο δι’ ἀπάτης νικᾶν, ὑπολαμβάνοντες οὐδὲν οὔτε λαμπρὸν οὐδὲ μὴν βέβαιον εἶναι τῶν κατορθωμάτων, ἐὰν μή τις ἐκ τοῦ προφανοῦς μαχόμενος ἡττήσῃ ταῖς ψυχαῖς τοὺς ἀντιταττομένους. διὸ καὶ συνετίθεντο πρὸς σφᾶς μήτ’ ἀδήλοις βέλεσι μήθ’ ἑκηβόλοις χρήσασθαι κατ’ ἀλλήλων, μόνην δὲ τὴν ἐκ χειρὸς καὶ συστάδην γινομένην μάχην ἀληθινὴν ὑπελάμβανον εἶναι κρίσιν πραγμάτων. ᾗ καὶ τοὺς πολέμους ἀλλήλοις προύλεγον καὶ τὰς μάχας, ὅτε πρόθοιντο διακινδυνεύειν, καὶ τοὺς τόπους, εἰς οὓς μέλλοιεν ἐξιέναι παραταξόμενοι. νῦν δὲ καὶ φαύλου φασὶν εἶναι στρατηγοῦ τὸ προφανῶς τι πράττειν τῶν πολεμικῶν. βραχὺ δέ τι λείπεται παρὰ Ῥωμαίοις ἴχνος ἔτι τῆς ἀρχαίας αἱρέσεως περὶ τὰ πολεμικά· καὶ γὰρ προλέγουσι τοὺς πολέμους καὶ ταῖς ἐνέδραις σπανίως χρῶνται καὶ τὴν μάχην ἐκ χειρὸς ποιοῦνται καὶ συστάδην. ταῦτα μὲν οὖν εἰρήσθω πρὸς τὸν ἐπιπολάζοντα νῦν ὑπὲρ τὸ δέον ἐν τῇ κακοπραγμοσύνῃ ζῆλον περὶ τοὺς ἡγουμένους ἔν τε ταῖς πολιτικαῖς καὶ πολεμικαῖς οἰκονομίαις.", "st": "13.3"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος Ἡρακλείδῃ μέν, καθάπερ ὑπόθεσιν δούς, ἐπέταξε φροντίζειν πῶς ἂν κακοποιήσαι καὶ διαφθείραι τὰς τῶν Ῥοδίων νῆας, εἰς δὲ τὴν Κρήτην πρεσβευτὰς ἐξαπέστειλε τοὺς ἐρεθιοῦντας καὶ παρορμήσοντας ἐπὶ τὸν κατὰ τῶν Ῥοδίων πόλεμον. ὁ δ’ Ἡρακλείδης, ἄνθρωπος εὖ πεφυκὼς πρὸς τὸ κακόν, ἑρμαῖον ἡγησάμενος τὴν ἐπιταγήν, καὶ διανοηθεὶς ἅττα δήποτ’ οὖν παρ’ αὑτῷ, μετά τινα χρόνον ὥρμησε καὶ παρῆν καταπλέων εἰς τὴν Ῥόδον. συνέβαινε δὲ τὸν Ἡρακλείδην τοῦτον τὸ μὲν γένος ἀνέκαθεν εἶναι Ταραντῖνον, πεφυκέναι δ’ ἐκ βαναύσων καὶ χειροτεχνῶν ἀνθρώπων, μεγάλα δ’ ἐσχηκέναι προτερήματα πρὸς ἀπόνοιαν καὶ ῥᾳδιουργίαν· πρῶτον μὲν γὰρ ἀναφανδὸν τῷ σώματι παρεκέχρητο κατὰ τὴν πρώτην ἡλικίαν, εἶτ’ ἀγχίνους ὑπῆρχε καὶ μνήμων, καὶ πρὸς μὲν τοὺς ταπεινοτέρους καταπληκτικώτατος καὶ τολμηρότατος, πρὸς δὲ τοὺς ὑπερέχοντας κολακικώτατος. οὗτος ἀρχῆθεν μὲν ἐκ τῆς πατρίδος ἐξέπεσε δόξας τὸν Τάραντα πράττειν Ῥωμαίοις, οὐ πολιτικὴν ἔχων δύναμιν, ἀλλ’ ἀρχιτέκτων ὑπάρχων καὶ διά τινας ἐπισκευὰς τῶν τειχῶν κύριος γενόμενος τῶν κλειδῶν τῆς πύλης τῆς ἐπὶ τὸ μεσόγαιον φερούσης· καταφυγὼν δὲ πρὸς Ῥωμαίους, καὶ πάλιν ἐκεῖθεν γράφων καὶ διαπεμπόμενος εἰς τὸν Τάραντα καὶ πρὸς Ἀννίβαν, ἐπεὶ καταφανὴς ἐγένετο, προαισθόμενος τὸ μέλλον αὖθις ἔφυγε πρὸς τὸν Φίλιππον. παρ’ ᾧ τοιαύτην περιεποιήσατο πίστιν καὶ δύναμιν ὥστε τοῦ καταστραφῆναι τὴν τηλικαύτην βασιλείαν σχεδὸν αἰτιώτατος γεγονέναι. —", "st": "13.4"}, {"sp": "N", "t": "Διαπιστοῦντες δ’ οἱ πρυτάνεις ἤδη τῷ Φιλίππῳ διὰ τὴν περὶ τὰ Κρητικὰ κακοπραγμοσύνην, καὶ τὸν Ἡρακλείδην ὑπώπτευον ἐγκάθετον εἶναι. — ὁ δ’ εἰσελθὼν ἀπελογίζετο τὰς αἰτίας, δι’ ἃς πεφευγὼς εἴη τὸν Φίλιππον. — πᾶν γὰρ βουληθῆναι τὸν Φίλιππον ἀναδέξασθαι ἢ καταφανῆ γενέσθαι Ῥοδίοις τὴν ἐν τούτοις αὐτοῦ προαίρεσιν. ᾗ καὶ τὸν Ἡρακλείδην ἀπέλυσε τῆς ὑποψίας. — καί μοι δοκεῖ μεγίστην θεὸν τοῖς ἀνθρώποις ἡ φύσις ἀποδεῖξαι τὴν ἀλήθειαν καὶ μεγίστην αὐτῇ προσθεῖναι δύναμιν. πάντων γοῦν αὐτὴν καταγωνιζομένων, ἐνίοτε καὶ πασῶν τῶν πιθανοτήτων μετὰ τοῦ ψεύδους ταττομένων, οὐκ οἶδ’ ὅπως αὐτὴ δι’ αὑτῆς εἰς τὰς ψυχὰς εἰσδύεται τῶν ἀνθρώπων, καὶ ποτὲ μὲν παραχρῆμα δείκνυσι τὴν αὑτῆς δύναμιν, ποτὲ δὲ καὶ πολὺν χρόνον ἐπισκοτισθεῖσα, τέλος αὐτὴ δι’ ἑαυτῆς ἐπικρατεῖ καὶ καταγωνίζεται τὸ ψεῦδος, ὡς συνέβη γενέσθαι περὶ τὸν Ἡρακλείδην τὸν παρὰ τοῦ Φιλίππου τοῦ βασιλέως εἰς Ῥόδον ἀφικόμενον. — ὅτι Δαμοκλῆς ὁ μετὰ Πυθίωνος πεμφθεὶς κατάσκοπος πρὸς Ῥωμαίους ὑπηρετικὸν ἦν σκεῦος εὐφυὲς καὶ πολλὰς ἔχον ἀφορμὰς εἰς πραγμάτων οἰκονομίαν. —", "st": "13.5"}, {"sp": "N", "t": "ὁ δὲ τῶν Λακεδαιμονίων τύραννος Νάβις, ἔτος ἤδη τρίτον ἔχων τὴν ἀρχήν, ὁλοσχερὲς μὲν οὐδὲν ἐπεβάλλετο πράττειν οὐδὲ τολμᾶν διὰ τὸ πρόσφατον εἶναι τὴν ὑπὸ τῶν Ἀχαιῶν ἧτταν τοῦ Μαχανίδου, καταβολὴν δ’ ἐποιεῖτο καὶ θεμέλιον ὑπεβάλλετο πολυχρονίου καὶ βαρείας τυραννίδος. διέφθειρε γὰρ τοὺς λοιποὺς ἄρδην ἐκ τῆς Σπάρτης, ἐφυγάδευσε δὲ τοὺς κατὰ πλέον πλούτῳ διαφέροντας ἢ δόξῃ προγονικῇ, τὰς δὲ τούτων οὐσίας καὶ γυναῖκας διεδίδου τῶν ἄλλων τοῖς ἐπιφανεστάτοις καὶ τοῖς μισθοφόροις. οὗτοι δ’ ἦσαν ἀνδροφόνοι καὶ παρασχίσται, λωποδύται, τοιχωρύχοι. καθόλου γὰρ τοῦτο τὸ γένος ἡθροίζετο πρὸς αὐτὸν ἐπιμελῶς ἐκ τῆς οἰκουμένης, οἷς ἄβατος ἦν ἡ θρέψασα δι’ ἀσέβειαν καὶ παρανομίαν. ὧν προστάτην [καὶ βασιλέα] αὑτὸν ἀναδείξας, καὶ χρώμενος δορυφόροις καὶ σωματοφύλαξι τούτοις, δῆλον ἔμελλε πολυχρόνιον ἔχειν τὴν ἐπ’ ἀσεβείᾳ φήμην καὶ δυναστείαν. ὅς γε χωρὶς τῶν προειρημένων οὐκ ἐξηρκεῖτο φυγαδεύειν τοὺς πολίτας, ἀλλ’ οὐδὲ τοῖς φεύγουσιν οὐδεὶς τόπος ἦν ἀσφαλὴς οὐδὲ καταφυγὴ βέβαιος. τοὺς μὲν γὰρ ἐν ταῖς ὁδοῖς ἐπαποστέλλων ἀνῄρει, τοὺς δ’ ἐκ τῶν τόπων ἐπανάγοντας ἐφόνευε. τὸ δὲ τελευταῖον ἐν ταῖς πόλεσι τὰς σύνεγγυς οἰκίας, ὅπου τις τυγχάνοι κατοικῶν τῶν φυγάδων, μισθούμενος δι’ ἀνυπονοήτων ἀνθρώπων, εἰς ταύτας εἰσέπεμπε Κρῆτας, οἵτινες ῥήγματα ποιοῦντες ἐν τοῖς τοίχοις καὶ διὰ τῶν ὑπαρχουσῶν θυρίδων τοξεύοντες τοὺς μὲν ἑστῶτας τῶν φυγάδων, τοὺς δ’ ἀνακειμένους ἐν ταῖς ἰδίαις οἰκίαις διέφθειρον, ὥστε μήτε τόπον εἶναι μηδένα φύξιμον μήτε καιρὸν ἀσφαλῆ τοῖς ταλαιπώροις Λακεδαιμονίοις. καὶ δὴ τῷ τοιούτῳ τρόπῳ τοὺς μὲν πλείστους αὐτῶν ἠφάνισε.", "st": "13.6"}, {"sp": "N", "t": "κατεσκευάσατο δὲ καί τινα μηχανήν, εἰ μηχανὴν ταύτην χρὴ λέγειν. ἦν γὰρ εἴδωλον γυναικεῖον, πολυτελέσιν ἱματίοις ἠμφιεσμένον, κατὰ δὲ τὴν μορφὴν εἰς ὁμοιότητα τῇ τοῦ Νάβιδος γυναικὶ διαφόρως ἀπειργασμένον. ὁπότε δέ τινας τῶν πολιτικῶν ἀνακαλέσαιτο, βουλόμενος εἰσπρᾶξαι χρήματα, τὰς μὲν ἀρχὰς διετίθετο λόγους πλείονας καὶ φιλανθρώπους, ὑποδεικνύων μὲν τὸν ὑπὸ τῶν Ἀχαιῶν ἐπικρεμάμενον τῇ χώρᾳ καὶ τῇ πόλει φόβον, διασαφῶν δὲ τὸ πλῆθος τῶν μισθοφόρων τὸ τρεφόμενον τῆς ἐκείνων ἀσφαλείας χάριν, ἔτι δὲ τὰς εἰς τοὺς θεοὺς καὶ τὰς κοινὰς τῆς πόλεως δαπάνας. εἰ μὲν οὖν ἐντρέποιντο διὰ τῶν τοιούτων λόγων, εἶχεν ἀποχρώντως αὐτῷ πρὸς τὸ προκείμενον· εἰ δέ τινες ἐξαρνούμενοι διωθοῖντο τὴν ἐπιταγήν, ἐπεφθέγγετο λόγον τοιοῦτον \"ἴσως ἐγὼ μὲν οὐ δύναμαί σε πείθειν, Ἀπῆγαν μέντοι ταύτην δοκῶ σε πείσειν\" τοῦτο δ’ ἦν ὄνομα τῇ γυναικὶ τοῦ Νάβιδος. καὶ τοῦτ’ ἔλεγε, καὶ παρῆν ὃ μικρῷ πρότερον ἔλεγον εἴδωλον. καὶ δεξιωσάμενος, ἐπειδὰν ἐκ τῆς καθέδρας ἀνέστησε τὴν γυναῖκα καὶ περιέπτυξε ταῖς χερσί, προσήγετο κατὰ βραχὺ πρὸς τὰ στέρνα. τοὺς δὲ πήχεις εἶχε καὶ τὰς χεῖρας πλήρεις σιδηρῶν γόμφων ὑπὸ τοῖς ἱματίοις, ὁμοίως καὶ κατὰ τοὺς μαστούς. ὅταν προσήρεισε ταῖς χερσὶ πρὸς τὰ νῶτα τῆς γυναικός, κἄπειτα διὰ τῶν ὀργάνων ἑλκόμενον ἐπέτεινε καὶ προσῆγε πρὸς τοὺς μαστοὺς κατ’ ἐλάχιστον, πᾶσαν ἠνάγκαζε φωνὴν προΐεσθαι τὸν πιεζόμενον. καὶ πολλοὺς δή τινας τῷ τοιούτῳ τρόπῳ διέφθειρε τῶν ἐξαρνουμένων.", "st": "13.7"}, {"sp": "N", "t": "καὶ τὰ λοιπὰ δ’ ἦν τούτοις ὅμοια καὶ σύστοιχα κατὰ τὴν ἀρχήν. ἐκοινώνει μὲν γὰρ τοῖς Κρησὶ τῶν κατὰ θάλατταν λῃστειῶν· εἶχε δὲ καθ’ ὅλην τὴν Πελοπόννησον ἱεροσύλους, ὁδοιδόκους, φονέας, οἷς μερίτης γινόμενος τῶν ἐκ τῆς ῥᾳδιουργίας λυσιτελῶν ὁρμητήριον καὶ καταφυγὴν παρείχετο τούτοις τὴν Σπάρτην. πλὴν κατά γε τοὺς καιροὺς τούτους ξένοι τῶν ἀπὸ τῆς Βοιωτίας εἰς τὴν Λακεδαίμονα παρεπιδημήσαντες ἐψυχαγώγησάν τινα τῶν τοῦ Νάβιδος ἱπποκόμων ὥστε συναποχωρῆσαι μεθ’ ἑαυτῶν ἔχοντα λευκὸν ἵππον, ὃς ἐδόκει γενναιότατος εἶναι τῶν ἐκ τῆς τυραννικῆς ἱπποστάσεως. τοῦτο δὲ πεισθέντος καὶ πράξαντος τοῦ προειρημένου, καταδιώξαντες οἱ παρὰ τοῦ Νάβιδος εἰς τὴν Μεγάλην πόλιν καὶ καταλαβόντες τὸν μὲν ἵππον εὐθὺς ἀπῆγον καὶ τὸν ἱπποκόμον, οὐδενὸς ἀντιποιουμένου, μετὰ δὲ ταῦτα καὶ τοῖς ξένοις ἐπέβαλον τὰς χεῖρας. οἱ δὲ Βοιωτοὶ τὸ μὲν πρῶτον ἠξίουν ἄγειν αὑτοὺς ἐπὶ τὴν ἀρχήν· οὐδενὸς δὲ προσέχοντος ἀνεβόα τις τῶν ξένων \"βοήθεια\". συνδραμόντων δὲ τῶν ἐγχωρίων καὶ μαρτυρομένων τοὺς ἄνδρας ἐπανάγειν ἐπὶ τὴν ἀρχήν, ἠναγκάσθησαν προιέμενοι τοὺς ἀνθρώπους οἱ παρὰ τοῦ Νάβιδος ἀπελθεῖν. ὁ δὲ πάλαι ζητῶν ἀφορμὰς ἐγκλημάτων καὶ πρόφασιν εὔλογον διαφορᾶς, τότε λαβόμενος ταύτης εὐθέως ἤλαυνε τὰ Προαγόρου θρέμματα καί τινων ἑτέρων. ἐξ ὧν ἐγένετο καταρχὴ τοῦ πολέμου.", "st": "13.8"}, {"sp": "N", "t": "Λάβαι, ὡς Σάβαι, Χαττηνίας πόλις. Πολύβιος τρισκαιδεκάτῳ. τὸ ἐθνικὸν Λαβαῖος ὡς Σαβαῖος. τῆς αὐτῆς χώρας ἀμφότεραι· ἡ γὰρ Χαττηνία τῶν Γερραίων ἐστὶ χώρα. — Χαττηνία, χώρα τρίτη Γερραίων. Πολύβιος ιγʹ \"ἔστι δ’ ἡ Χαττηνία τἄλλα μὲν λυπρά, κώμαις δὲ καὶ πύργοις διεσκεύασται διὰ τὴν εὐκαιρίαν τῶν Γερραίων· οὗτοι γὰρ αὐτὴν νέμονται\". ἔστι δὲ τῆς Ἐρυθρᾶς θαλάσσης. οἱ πολῖται Χαττηνοί, ὡς αὐτός· \"τούτοις μὲν γὰρ παρήγγειλε φείδεσθαι τῆς τῶν Χαττηνῶν χώρας\". — οἱ δὲ Γερραῖοι ἀξιοῦσι τὸν βασιλέα μὴ καταλῦσαι τὰ παρὰ τῶν θεῶν αὐτοῖς δεδομένα, τοῦτ’ ἔστιν ἀΐδιον εἰρήνην καὶ ἐλευθερίαν. ὁ δὲ ἑρμηνευθείσης οἱ τῆς ἐπιστολῆς ἔφη συγχωρεῖν τοῖς ἀξιουμένοις. — κυρωθείσης δὲ τῆς ἐλευθερίας τοῖς Γερραίοις ἐστεφάνωσαν παραχρῆμα τὸν Ἀντίοχον τὸν βασιλέα πεντακοσίοις ἀργυρίου ταλάντοις, χιλίοις δὲ λιβανωτοῦ καὶ διακοσίοις τῆς λεγομένης στακτῆς. καὶ ἐποίει τὸν πλοῦν ἐπὶ Τύλον τὴν νῆσον καὶ ἐποίει τὸν ἀπόπλουν ἐπὶ Σελευκείας. ἦσαν δὲ τὰ ἀρώματα ἐν τῇ Ἐρυθρᾷ θαλάττῃ.", "st": "13.9"}, {"sp": "N", "t": "Βάδιζα, πόλις τῆς Βρεττίας, Πολύβιος τρισκαιδεκάτῳ. Λαμπέτεια, πόλις Βρεττίας, Πολύβιος τρισκαιδεκάτῳ. ἔστι γὰρ καὶ Ταμέση πόλις τῆς Ἰταλίας καὶ ποταμός. Πολύβιος δ’ ἐν τῷ ιγʹ Τεμέσειαν τὴν πόλιν καλεῖ. Ἀλλαρία, πόλις τῆς Κρήτης, Πολύβιος τρισκαιδεκάτῃ. τὸ ἐθνικὸν Ἀλλαριάτης, ὡς αὐτός φησιν. Ἰλαττία, πόλις Κρήτης, Πολύβιος τρισκαιδεκάτῳ. Σίβυρτος, πόλις Κρήτης. τὸ ἐθνικὸν Σιβύρτιος, ὡς Πολύβιος ἐν τρισκαιδεκάτῳ. Ἀδράνη, πόλις Θρᾴκης … Πολύβιος δὲ διὰ τοῦ ⟨η⟩ τὴν μέσην λέγει ἐν τρισκαιδεκάτῃ, Ἀδρήνη. Ἄρειον πεδίον … ἔστι καὶ Θρᾴκης ἔρημον πεδίον χαμαιπετῆ δένδρα ἔχον, ὡς Πολύβιος τρισκαιδεκάτῃ. Δίγηροι, ἔθνος Θρᾴκιον, Πολύβιος ιγʹ. Καβύλη, πόλις Θρᾴκης οὐ πόρρω τῆς τῶν Ἀστῶν χώρας. Πολύβιος τρισκαιδεκάτῃ. Μελίτουσσα, πόλις Ἰλλυρίας. Πολύβιος τρισκαιδεκάτῳ.", "st": "13.10"}, {"sp": "HDR", "t": "Βιβλίον ΙΔʹ", "st": "14"}, {"sp": "N", "t": "ὅτι φησὶν ὁ Πολύβιος περὶ ἑαυτοῦ καὶ περὶ τῆς τῶν βίβλων ὑποθετικῆς ἐξηγήσεως· ἴσως μὲν οὖν ἐπὶ πάσαις ταῖς ὀλυμπιάσιν αἱ προεκθέσεις τῶν πράξεων εἰς ἐπίστασιν ἄγουσι τοὺς ἐντυγχάνοντας καὶ διὰ τὸ πλῆθος καὶ διὰ τὸ μέγεθος τῶν γεγονότων, ὡς ἂν ὑπὸ μίαν σύνοψιν ἀγομένων τῶν ἐξ ὅλης τῆς οἰκουμένης ἔργων· οὐ μὴν ἀλλὰ τὰ κατὰ ταύτην τὴν ὀλυμπιάδα μάλιστα νομίζω συνεπιστήσειν τοὺς ἀναγινώσκοντας διὰ τὸ πρῶτον μὲν τοὺς κατὰ τὴν Ἰταλίαν καὶ Λιβύην πολέμους ἐν τούτοις τοῖς χρόνοις εἰληφέναι τὴν συντέλειαν· ὑπὲρ ὧν τίς οὐκ ἂν ἱστορῆσαι βουληθείη ποία τις ἡ καταστροφὴ καὶ τί τὸ τέλος αὐτῶν ἐγένετο; φύσει γὰρ πάντες ἄνθρωποι, κἂν ὁλοσχερῶς παραδέχωνται τὰ κατὰ μέρος ἔργα καὶ λόγους, ὅμως ἑκάστων τὸ τέλος ἱμείρουσι μαθεῖν· πρὸς δὲ τούτοις συμβαίνει καὶ τὰς προαιρέσεις τῶν βασιλέων ἐκφανεστάτας γεγονέναι κατὰ τοὺς αὐτοὺς χρόνους· ἃ γὰρ πρότερον ἐλέγετο περὶ αὐτῶν, τότε σαφῶς ἐπεγνώσθη πάντα παρὰ πᾶσι καὶ τοῖς μηδ’ ὅλως ἐθέλουσι πολυπραγμονεῖν. διὸ καὶ βουλόμενοι κατ’ ἀξίαν τῶν ἔργων ποιήσασθαι τὴν ἐξήγησιν, οὐ τὰς ἐκ τῶν δυεῖν ἐτῶν πράξεις κατατετάχαμεν εἰς μίαν βύβλον, καθάπερ ἐν τοῖς πρὸ τούτων ἀποδεδώκαμεν.", "st": "14.1a"}, {"sp": "N", "t": "οἱ μὲν οὖν ὕπατοι περὶ ταύτας ἐγίνοντο τὰς πράξεις, ὁ δὲ Πόπλιος ἐν τῇ Λιβύῃ κατὰ τὴν παραχειμασίαν πυνθανόμενος ἐξαρτύειν στόλον τοὺς Καρχηδονίους, ἐγίνετο μὲν καὶ περὶ ταύτην τὴν παρασκευήν, οὐχ ἧττον δὲ καὶ περὶ τὴν τῆς Ἰτύκης πολιορκίαν. οὐ μὴν οὐδὲ τῆς κατὰ τὸν Σόφακα τελέως ἐλπίδος ἀφίστατο, διεπέμπετο δὲ συνεχῶς διὰ τὸ μὴ πολὺ ἀφεστάναι τὰς δυνάμεις ἀλλήλων, πεπεισμένος μετακαλέσειν αὐτὸν ἀπὸ τῆς τῶν Καρχηδονίων συμμαχίας· οὐ γὰρ ἀπεγίνωσκε καὶ τῆς παιδίσκης αὐτὸν ἤδη κόρον ἔχειν, δι’ ἣν εἵλετο τὰ Καρχηδονίων, καὶ καθόλου τῆς πρὸς τοὺς Φοίνικας φιλίας διά τε τὴν φυσικὴν τῶν Νομάδων ἁψικορίαν καὶ διὰ τὴν πρός τε τοὺς θεοὺς καὶ τοὺς ἀνθρώπους ἀθεσίαν. ὢν δὲ περὶ πολλὰ τῇ διανοίᾳ καὶ ποικίλας ἔχων ἐλπίδας ὑπὲρ τοῦ μέλλοντος διὰ τὸ κατορρωδεῖν τὸν ἔξω κίνδυνον τῷ πολλαπλασίους εἶναι τοὺς ὑπεναντίους, ἐπελάβετό τινος ἀφορμῆς τοιαύτης. τῶν γὰρ διαπεμπομένων πρὸς τὸν Σόφακά τινες ἀνήγγειλαν αὐτῷ διότι συμβαίνει τοὺς μὲν Καρχηδονίους ἐκ παντοδαπῶν ξύλων καὶ φυλλάδος ἄνευ γῆς ἐν τῇ παραχειμασίᾳ κατεσκευακέναι τὰς σκηνάς, τῶν δὲ Νομάδων τοὺς μὲν ἐξ ἀρχῆς ἐκ καλάμων, τοὺς δ’ ἐπισυναγομένους ἐκ τῶν πόλεων κατὰ τὸ παρὸν ἐξ αὐτῆς τῆς φυλλάδος σκηνοποιεῖσθαι, τοὺς μὲν ἐντός, τοὺς δὲ πλείους αὐτῶν ἐκτὸς τῆς τάφρου καὶ τοῦ χάρακος. νομίσας οὖν ὁ Πόπλιος παραδοξοτάτην μὲν τοῖς πολεμίοις, πραγματικωτάτην δὲ σφίσιν εἶναι τὴν διὰ τοῦ πυρὸς ἐπιβολήν, ἐγένετο περὶ ταύτην τὴν κατασκευήν. ὁ δὲ Σόφαξ ἐν ταῖς πρὸς τὸν Πόπλιον διαποστολαῖς ἀεί πως ἐπὶ ταύτην κατήντα τὴν γνώμην ὅτι δέοι Καρχηδονίους μὲν ἐκ τῆς Ἰταλίας ἀπαλλάττεσθαι, Ῥωμαίους δὲ παραπλησίως ἐκ τῆς Λιβύης, τὰ δὲ μεταξὺ τούτων ἔχειν ἀμφοτέρους ὡς τότε κατεῖχον. ὧν ὁ Πόπλιος ἀκούων ἐν τοῖς πρὸ τοῦ χρόνοις οὐδαμῶς ἀνείχετο· τότε δὲ τῷ Νομάδι βραχεῖαν ἔμφασιν ἐποιήσατο διὰ τῶν ἀποστελλομένων ὡς οὐκ ἀδυνάτου τῆς ἐπιβολῆς οὔσης, ἧς ἐπιβάλλεται. δι’ οὗ συνέβη τὸν Σόφακα κουφισθέντα πολλαπλασίως ἐπιρρωσθῆναι πρὸς τὴν ἐπιπλοκήν. οὗ γινομένου πλείους ἦσαν οἱ διαπεμπόμενοι καὶ πλεονάκις· ἔστι δ’ ὅτε καί τινας ἡμέρας ἔμενον παρ’ ἀλλήλοις ἀπαρατηρήτως. ἐν αἷς ὁ Πόπλιος ἀεί τινας μὲν τῶν πραγματικῶν, οὓς δὲ καὶ στρατιωτικῶν, ῥυπῶντας καὶ ταπεινούς, εἰς δουλικὰς ἐσθῆτας διασκευάζων, μετὰ τῶν ἀποστελλομένων ἐξέπεμπε χάριν τοῦ τὰς προσόδους καὶ τὰς εἰσόδους τὰς εἰς ἑκατέραν τὴν παρεμβολὴν ἀσφαλῶς ἐξερευνῆσαι καὶ κατοπτεῦσαι. δύο γὰρ ἦσαν στρατοπεδεῖαι, μία μὲν ἣν Ἀσδρούβας εἶχε μετὰ πεζῶν τρισμυρίων καὶ τρισχιλίων ἱππέων, ἄλλη δὲ περὶ δέκα σταδίους ἀφεστῶσα ταύτης, ἡ τῶν Νομάδων, ἱππεῖς μὲν εἰς μυρίους ἔχουσα, πεζοὺς δὲ περὶ πεντακισμυρίους. ἣ δὴ καὶ μᾶλλον εὐέφοδος ἦν καὶ τὰς σκηνὰς εἶχε τελέως εὐφυεῖς πρὸς ἐμπυρισμὸν διὰ τὸ τοὺς Νομάδας, ὡς ἀρτίως εἶπον, μὴ διὰ ξύλων μηδὲ διὰ γῆς, ἁπλῶς δὲ κάνναις καὶ καλάμοις χρῆσθαι πρὸς τὰς σκηνοποιίας.", "st": "14.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ τὰ μὲν τῆς ἐαρινῆς ὥρας ὑπέφαινεν ἤδη, τῷ δὲ Σκιπίωνι πάντα διηρεύνητο πρὸς τὴν προειρημένην ἐπιβολὴν τὰ κατὰ τοὺς ὑπεναντίους, τὰς μὲν νῆας καθεῖλκε καὶ μηχανὰς κατεσκεύαζε ταύταις ὡς πολιορκήσων ἐκ θαλάττης τὴν Ἰτύκην, τοῖς δὲ πεζοῖς, οὖσιν ὡς δισχιλίοις, κατελάβετο πάλιν τὸν ὑπὲρ τὴν πόλιν κείμενον λόφον, καὶ τοῦτον ὠχυροῦτο καὶ διετάφρευε πολυτελῶς, τοῖς μὲν ὑπεναντίοις ποιῶν φαντασίαν ὡς τοῦτο πράττων τῆς πολιορκίας ἕνεκα, τῇ δ’ ἀληθείᾳ βουλόμενος ἐφεδρεύειν τοῖς κατὰ τὸν τῆς πράξεως καιρόν, ἵνα μὴ τῶν στρατοπέδων ἐκ τῆς παρεμβολῆς χωρισθέντων οἱ τὴν Ἰτύκην παραφυλάττοντες στρατιῶται τολμήσαιεν ἐξελθόντες ἐκ τῆς πόλεως ἐγχειρεῖν τῷ χάρακι διὰ τὸ σύνεγγυς εἶναι, καὶ πολιορκεῖν τοὺς φυλάττοντας. ταῦτα δὲ παρασκευαζόμενος ἅμα διεπέμπετο πρὸς τὸν Σόφακα, πυνθανόμενος, ἐὰν συγχωρῇ τοῖς παρακαλουμένοις, εἰ καὶ τοῖς Καρχηδονίοις ἔσται ταῦτα κατὰ νοῦν καὶ μὴ πάλιν ἐκεῖνοι φήσουσι βουλεύσεσθαι περὶ τῶν συγχωρουμένων. ἅμα δὲ τούτοις προσενετείλατο τοῖς πρεσβευταῖς μὴ πρότερον ὡς αὑτὸν ἀπιέναι πρὶν ἢ λαβεῖν ἀπόκρισιν ὑπὲρ τούτων. ὧν ἀφικομένων διακούσας ὁ Νομὰς ἐπείσθη διότι πρὸς τὸ συντελεῖν ἐστι τὰς διαλύσεις ὁ Σκιπίων, ἔκ τε τοῦ φάναι τοὺς πρέσβεις μὴ πρότερον ἀπαλλαγήσεσθαι πρὶν ἢ λαβεῖν παρ’ αὐτοῦ τὰς ἀποκρίσεις, ἔκ τε τοῦ διευλαβεῖσθαι τὴν τῶν Καρχηδονίων συγκατάθεσιν. διὸ καὶ πρὸς μὲν τὸν Ἀσδρούβαν ἐξ αὐτῆς ἔπεμπε, διασαφῶν τὰ γινόμενα καὶ παρακαλῶν δέχεσθαι τὴν εἰρήνην, αὐτὸς δὲ ῥᾳθύμως διῆγε, καὶ τοὺς ἐπισυναγομένους Νομάδας ἐκτὸς εἴα τῆς παρεμβολῆς αὐτοῦ κατασκηνοῦν. ὁ δὲ Πόπλιος κατὰ μὲν τὴν ἐπίφασιν ἐποίει τὸ παραπλήσιον, κατὰ δὲ τὴν ἀλήθειαν ἐν τοῖς μάλιστα περὶ τὰς παρασκευὰς ἦν. ἐπειδὴ δὲ παρὰ μὲν τῶν Καρχηδονίων τῷ Σόφακι διεσαφήθη συντελεῖν τὰ κατὰ τὰς συνθήκας, ὁ δὲ Νομὰς περιχαρὴς ὢν εἶπε τοῖς πρεσβευταῖς ὑπὲρ τούτων, εὐθέως οἱ πρέσβεις ἀπῄεσαν εἰς τὴν ἰδίαν παρεμβολήν, μηνύσοντες τῷ Ποπλίῳ τὰ πραχθέντα παρὰ τοῦ βασιλέως. ὧν ἀκούσας ὁ τῶν Ῥωμαίων στρατηγὸς αὖθις ἐκ ποδὸς ἔπεμπε πρέσβεις, δηλώσοντας τῷ Σόφακι διότι συμβαίνει τὸν μὲν Πόπλιον εὐδοκεῖν καὶ σπουδάζειν ὑπὲρ τῆς εἰρήνης, τοὺς δ’ ἐν τῷ συνεδρίῳ διαφέρεσθαι καὶ φάναι διαμένειν ἐπὶ τῶν ὑποκειμένων· οἳ καὶ παραγενόμενοι διεσάφησαν ταῦτα τῷ Νομάδι. τὴν δ’ ἀποστολὴν ταύτην ὁ Σκιπίων ἐποιήσατο χάριν τοῦ μὴ δόξαι παρασπονδεῖν, ἐὰν ἔτι μενούσης τῆς ὑπὲρ τῶν διαλύσεων ἐπικηρυκείας πρὸς ἀλλήλους πράξῃ τι τῶν πολεμικῶν ἔργων. γενομένης δὲ τῆς ἀπορρήσεως ταύτης ἅπαν τὸ γινόμενον ἀνεπίληπτον ἕξειν ὑπέλαβε τὴν προαίρεσιν.", "st": "14.2"}, {"sp": "N", "t": "ὁ δὲ Σόφαξ ταῦτα διακούσας ἔφερε μὲν δυσχερῶς διὰ τὸ προκατηλπικέναι περὶ τῶν διαλύσεων, συνῄει δὲ πρὸς τὸν Ἀσδρούβαν εἰς λόγους, καὶ διεσάφει τὰ παρὰ τῶν Ῥωμαίων αὐτῷ προσαγγελλόμενα. περὶ ὧν πολλὰ διαπορήσαντες ἐβουλεύοντο πῶς σφίσι καθήκει χρῆσθαι τοῖς ἑξῆς πράγμασι, πλεῖστον ἀπέχοντες ταῖς ἐννοίαις καὶ ταῖς ἐπιβολαῖς τοῦ μέλλοντος· περὶ φυλακῆς μὲν γὰρ ἢ τοῦ πείσεσθαί τι δεινὸν οὐδ’ ἡντινοῦν εἶχον πρόληψιν, περὶ δὲ τοῦ δρᾶσαί τι καὶ προκαλέσασθαι τοὺς πολεμίους εἰς ὁμαλὸν τόπον πολλή τις ἦν αὐτῶν ὁρμὴ καὶ προθυμία. Πόπλιος δὲ κατὰ τὸν καιρὸν τοῦτον τοῖς μὲν πολλοῖς ὑπεδείκνυε διά τε τῆς παρασκευῆς καὶ τῶν παραγγελμάτων ὡς κατὰ τῆς Ἰτύκης ἔχων πρᾶξιν, τῶν δὲ χιλιάρχων τοὺς ἐπιτηδειοτάτους καὶ πιστοτάτους καλέσας περὶ μέσον ἡμέρας ἐξέθηκε τὴν ἐπιβολήν, καὶ παρήγγειλε δειπνοποιησαμένους καθ’ ὥραν ἐξάγειν τὰ στρατόπεδα πρὸ τοῦ χάρακος, ἐπειδὰν κατὰ τὸν ἐθισμὸν οἱ σαλπιγκταὶ σημαίνωσιν ἅμα πάντες· ἔστι γὰρ ἔθος Ῥωμαίοις κατὰ τὸν τοῦ δείπνου καιρὸν τοὺς βυκανητὰς καὶ σαλπιγκτὰς πάντας σημαίνειν παρὰ τὴν τοῦ στρατηγοῦ σκηνήν, χάριν τοῦ τὰς νυκτερινὰς φυλακὰς κατὰ τὸν καιρὸν τοῦτον ἵστασθαι κατὰ τοὺς ἰδίους τόπους. μετὰ δὲ ταῦτα τοὺς κατασκόπους ἀνακαλεσάμενος, οὓς ἐτύγχανε διαπεμπόμενος εἰς τὰ τῶν πολεμίων στρατόπεδα, συνέκρινε καὶ διηρεύνα τὰ λεγόμενα περί τε τῶν προσβάσεων καὶ τῶν εἰσόδων τῶν εἰς τὰς παρεμβολάς, χρώμενος ἐπικριτῇ τῶν λεγομένων καὶ συμβούλῳ Μασαννάσᾳ διὰ τὴν τῶν τόπων ἐμπειρίαν.", "st": "14.3"}, {"sp": "N", "t": "ἐπειδὴ δὲ πάντ’ ἦν εὐτρεπῆ τὰ πρὸς τὴν χρείαν αὐτῷ τὴν ἐνεστῶσαν, ἀπολιπὼν τοὺς ἱκανοὺς καὶ τοὺς ἐπιτηδείους ἐπὶ τῆς παρεμβολῆς, ἀναλαβὼν τὰς δυνάμεις προῆγεν ἄρτι ληγούσης τῆς πρώτης φυλακῆς· περὶ γὰρ ἑξήκοντα σταδίους ἀπεῖχον οἱ πολέμιοι. συνεγγίσας δὲ τοῖς πολεμίοις περὶ τρίτην φυλακὴν λήγουσαν, Γαίῳ μὲν Λαιλίῳ καὶ Μασαννάσᾳ τοὺς ἡμίσεις ἀπονείμας τῶν στρατιωτῶν καὶ πάντας τοὺς Νομάδας ἐπέταξε ποιεῖσθαι τὴν προσβολὴν πρὸς τὸν τοῦ Σόφακος χάρακα, παρακαλέσας ἄνδρας ἀγαθοὺς γενέσθαι καὶ μηδὲν εἰκῇ πράττειν, σαφῶς εἰδότας ὅτι, καθ’ ὅσον ἐμποδίζει καὶ κωλύει τὰ τῆς ὁράσεως τὸ σκότος, κατὰ τοσοῦτον δεῖ συνεκπληροῦν τῇ διανοίᾳ καὶ τῇ τόλμῃ τὰς νυκτερινὰς ἐπιβολάς· αὐτὸς δὲ τὴν λοιπὴν στρατιὰν ἀναλαβὼν ἐποιεῖτο τὴν ὁρμὴν ἐπὶ τὸν Ἀσδρούβαν. ἦν δ’ αὐτῷ συλλελογισμένον μὴ πρότερον ἐγχειρεῖν, ἕως ἂν οἱ περὶ τὸν Λαίλιον πρῶτοι τὸ πῦρ ἐμβάλωσι τοῖς πολεμίοις. οὗτος μὲν τοιαύτας ἔχων ἐπινοίας βάδην ἐποιεῖτο τὴν πορείαν· οἱ δὲ περὶ τὸν Λαίλιον εἰς δύο μέρη σφᾶς αὐτοὺς διελόντες ἅμα προσέβαλλον τοῖς πολεμίοις. τῆς δὲ τῶν σκηνῶν διαθέσεως οἷον ἐπίτηδες πρὸς ἐμπυρισμὸν κατεσκευασμένης, καθάπερ ἀνώτερον εἶπον, ὡς οἱ προηγούμενοι τὸ πῦρ ἐνέβαλλον, κατανεμηθὲν εἰς τὰς πρώτας σκηνὰς εὐθέως ἀβοήθητον ἐποίει τὸ κακὸν διά τε τὴν συνέχειαν τῶν σκηνῶν καὶ διὰ τὸ πλῆθος τῆς ὑποκειμένης ὕλης. ὁ μὲν οὖν Λαίλιος ἔχων ἐφεδρείας τάξιν ἔμενεν· ὁ δὲ Μασαννάσας εἰδὼς τοὺς τόπους, καθ’ οὓς ἔμελλον οἱ φεύγοντες τὸ πῦρ ποιήσασθαι τὴν ἀποχώρησιν, ἐν τούτοις ἐπέστησε τοὺς αὑτοῦ στρατιώτας. τῶν δὲ Νομάδων οὐδεὶς ἁπλῶς συνυπώπτευσε τὸ γινόμενον, οὐδ’ αὐτὸς ὁ Σόφαξ, ἀλλ’ ὡς αὐτομάτως ἐμπεπρησμένου τοῦ χάρακος, ταύτην ἔσχον τὴν διάληψιν. ὅθεν ἀνυπονοήτως οἱ μὲν ἐκ τῶν ὕπνων, οἱ δ’ ἀκμὴν ἔτι μεθυσκόμενοι καὶ πίνοντες ἐξεπήδων ἐκ τῶν σκηνῶν. καὶ πολλοὶ μὲν ὑφ’ αὑτῶν περὶ τὰς τοῦ χάρακος ἐξόδους συνεπατήθησαν, πολλοὶ δὲ περικαταληφθέντες ὑπὸ τῆς φλογὸς κατεπρήσθησαν· οἱ δὲ καὶ διαφυγόντες τὴν φλόγα, πάντες εἰς τοὺς πολεμίους ἐμπίπτοντες, οὔθ’ ὃ πάσχουσιν οὔθ’ ὃ ποιοῦσι γινώσκοντες διεφθείροντο.", "st": "14.4"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον οἱ Καρχηδόνιοι, θεωροῦντες τὸ πλῆθος τοῦ πυρὸς καὶ τὸ μέγεθος τῆς ἐξαιρομένης φλογός, ὑπολαβόντες αὐτομάτως ἀνῆφθαι τὸν τῶν Νομάδων χάρακα, τινὲς μὲν ἐβοήθουν ἐξ αὐτῆς, οἱ δὲ λοιποὶ πάντες ἐκτρέχοντες ἐκ τῆς παρεμβολῆς ἄνοπλοι συνίσταντο πρὸ τῆς ἰδίας στρατοπεδείας, ἐκπλαγεῖς ὄντες ἐπὶ τοῖς γινομένοις. ὁ δὲ Σκιπίων, τῶν πραγμάτων ὡς ἂν εἰ κατ’ εὐχὴν αὐτῷ προχωρησάντων, ἐπιπεσὼν τοῖς ἐξεληλυθόσιν, οὓς μὲν ἐφόνευεν, οὓς δὲ καταδιώκων ἅμα τὸ πῦρ ἐνέβαλλε ταῖς σκηναῖς. οὗ γενομένου παραπλήσια συνέβαινε πάσχειν τοὺς Φοίνικας ὑπὸ τοῦ πυρὸς καὶ τῆς ὅλης περιστάσεως τοῖς ἄρτι ῥηθεῖσι περὶ τῶν Νομάδων. οἱ δὲ περὶ τὸν Ἀσδρούβαν τοῦ μὲν τῷ πυρὶ βοηθεῖν αὐτόθεν εὐθέως ἀπέστησαν, γνόντες ἐκ τοῦ συμβαίνοντος ὅτι καὶ περὶ τοὺς Νομάδας οὐκ αὐτομάτως, καθάπερ ὑπέλαβον, ἀλλ’ ἐκ τῆς τῶν πολεμίων ἐπιβολῆς καὶ τόλμης ἐγεγόνει τὸ δεινόν· ἐγίνοντο δὲ περὶ τὸ σῴζειν ἑαυτούς, βραχείας σφίσι καὶ περὶ τοῦτο τὸ μέρος ἐλπίδος ἔτι καταλειπομένης. τό τε γὰρ πῦρ ταχέως ἐπενέμετο καὶ περιελάμβανε πάντας τοὺς τόπους, αἵ τε δίοδοι πλήρεις ἦσαν ἵππων, ὑποζυγίων, ἀνδρῶν, τῶν μὲν ἡμιθνήτων καὶ διεφθαρμένων ὑπὸ τοῦ πυρός, τῶν δ’ ἐξεπτοημένων καὶ παρεστώτων ταῖς διανοίαις, ὥστε καὶ τοῖς ἀνδραγαθεῖν προαιρουμένοις ἐμπόδια ταῦτα γίνεσθαι, καὶ διὰ τὴν ταραχὴν καὶ σύγχυσιν ἀνέλπιστον εἶναι τὴν σωτηρίαν. παραπλήσια δὲ τούτοις ἦν καὶ τὰ περὶ τὸν Σόφακα καὶ τοὺς ἄλλους ἡγεμόνας. πλὴν οὗτοι μὲν ἀμφότεροι μετ’ ὀλίγων ἱππέων ἐξέσωσαν αὑτούς· αἱ δὲ λοιπαὶ μυριάδες ἀνδρῶν, ἵππων, ὑποζυγίων, ἀτυχῶς μὲν καὶ ἐλεεινῶς ὑπὸ τοῦ πυρὸς ἀπώλλυντο· αἰσχρῶς δὲ καὶ ἐπονειδίστως ἔνιοι τῶν ἀνδρῶν, τὴν τοῦ πυρὸς βίαν φεύγοντες, ὑπὸ τῶν πολεμίων διεφθείροντο, χωρὶς οὐ μόνον τῶν ὅπλων, ἀλλὰ καὶ τῶν ἱματίων, γυμνοὶ φονευόμενοι. καθόλου δὲ πᾶς ἦν ὁ τόπος οἰμωγῆς, βοῆς ἀτάκτου, φόβου, ψόφου παρηλλαγμένου, σὺν δὲ τούτοις πυρὸς ἐνεργοῦ καὶ φλογὸς ὑπερβαλλούσης πλήρης· ὧν ἓν ἱκανὸν [ὂν] ἐκπλῆξαι τὴν ἀνθρωπίνην φύσιν, μηδ’ ὅτι καὶ πάνθ’ ὁμοῦ συγκυρήσαντα παραδόξως. διὸ καὶ τὸ γεγονὸς οὐδὲ καθ’ ὑπερβολὴν εἰκάσαι δυνατὸν οὐδενὶ τῶν ὄντων ἐστίν· οὕτως ὑπερπεπαίκει τῇ δεινότητι πάσας τὰς προειρημένας πράξεις. ᾗ καὶ πολλῶν καὶ καλῶν διειργασμένων Σκιπίωνι κάλλιστον εἶναί μοι δοκεῖ τοῦτο τοὔργον καὶ παραβολώτατον τῶν ἐκείνῳ πεπραγμένων", "st": "14.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῆς ἡμέρας ἐπιγενομένης, καὶ τῶν πολεμίων τῶν μὲν ἀπολωλότων, τῶν δὲ προτροπάδην πεφευγότων, παρακαλέσας τοὺς χιλιάρχους ἐκ ποδὸς ἐπηκολούθει. τὰς μὲν οὖν ἀρχὰς ὁ Καρχηδόνιος ὑπέμενε, καίπερ αὐτῷ προσαγγελίας γενομένης· τοῦτο δ’ ἐποίει πιστεύων τῇ τῆς πόλεως ὀχυρότητι. μετὰ δὲ ταῦτα συνθεωρήσας τοὺς ἐγχωρίους στασιάζοντας, καταπλαγεὶς τὴν ἔφοδον τοῦ Σκιπίωνος, ἔφευγε μετὰ τῶν διασεσωσμένων· οὗτοι δ’ ἦσαν ἱππεῖς μὲν οὐκ ἐλάττους πεντακοσίων, πεζοὶ δὲ περὶ δισχιλίους. οἱ δ’ ἐγχώριοι συμφρονήσαντες ἐπέτρεψαν περὶ σφῶν αὐτῶν τοῖς Ῥωμαίοις. ὁ δὲ Πόπλιος τούτων μὲν ἐφείσατο, δύο δὲ τὰς παρακειμένας πόλεις ἐφῆκε τοῖς στρατοπέδοις διαρπάζειν, καὶ ταῦτα διαπραξάμενος αὖθις ἐπὶ τὴν ἐξ ἀρχῆς ἐπανῄει παρεμβολήν. οἱ δὲ Καρχηδόνιοι, παλιντρόπου τῆς ἐλπίδος αὐτοῖς ἀποβαινούσης πρὸς τὰς ἐξ ἀρχῆς ἐπιβολάς, βαρέως ἔφερον τὸ γεγονός· ἐλπίσαντες γὰρ πολιορκήσειν τοὺς Ῥωμαίους συγκλείσαντες εἰς τὴν ἄκραν τὴν προσοῦσαν τῆς Ἰτύκης, ἐν ᾗ τὴν παραχειμασίαν ἐποιοῦντο, κατὰ γῆν μὲν τοῖς πεζοῖς στρατεύμασι, κατὰ θάλατταν δὲ ταῖς ναυτικαῖς δυνάμεσι, καὶ πρὸς τοῦτο πάσας ἡτοιμακότες τὰς παρασκευάς, ἅμα τῷ μὴ μόνον τῶν ὑπαίθρων οὕτως ἀλόγως καὶ παραδόξως ἐκχωρῆσαι τοῖς ὑπεναντίοις, ἀλλὰ καὶ τὸν περὶ σφῶν αὐτῶν καὶ τῆς πατρίδος ὅσον οὐκ ἤδη προσδοκᾶν κίνδυνον, τελέως ἐκπλαγεῖς ἦσαν καὶ περίφοβοι ταῖς ψυχαῖς. οὐ μὴν ἀλλὰ τῶν πραγμάτων ἀναγκαζόντων ποιεῖσθαι πρόνοιαν καὶ βουλὴν ὑπὲρ τοῦ μέλλοντος, ἦν τὸ συνέδριον ἀπορίας καὶ ποικίλων καὶ τεταραγμένων ἐπινοημάτων πλῆρες. οἱ μὲν γὰρ ἔφασαν δεῖν πέμπειν ἐπὶ τὸν Ἀννίβαν καὶ καλεῖν ἐκ τῆς Ἰταλίας, ὡς μιᾶς ἔτι καταλειπομένης ἐλπίδος τῆς ἐν ἐκείνῳ τῷ στρατηγῷ καὶ ταῖς μετ’ ἐκείνου δυνάμεσιν, οἱ δὲ διαπρεσβεύεσθαι πρὸς τὸν Πόπλιον ὑπὲρ ἀνοχῶν καὶ λαλεῖν ὑπὲρ διαλύσεων καὶ συνθηκῶν, ἕτεροι δὲ θαρρεῖν καὶ συνάγειν τὰς δυνάμεις καὶ διαπέμπεσθαι πρὸς τὸν Σόφακα· καὶ γὰρ πλησίον αὐτὸν εἰς τὴν Ἄββαν ἀποκεχωρηκέναι, συναθροίζειν δὲ τοὺς ἀπὸ τοῦ κινδύνου διαφυγόντας. καὶ δὴ καὶ τέλος αὕτη τῶν γνωμῶν ἐπεκράτησεν. οὗτοι μὲν οὖν τάς τε δυνάμεις ἥθροιζον, ἐκπέμψαντες τὸν Ἀσδρούβαν, καὶ διεπέμψαντο πρὸς τὸν Σόφακα, δεόμενοι σφίσι βοηθεῖν καὶ μένειν ἐπὶ τῶν ὑποκειμένων κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, ὡς αὐτίκα μάλα τοῦ στρατηγοῦ μετὰ τῶν δυνάμεων πρὸς αὐτὸν συνάψοντος·", "st": "14.6"}, {"sp": "N", "t": "ὁ δὲ τῶν Ῥωμαίων στρατηγὸς ἐγίνετο μὲν καὶ περὶ τὴν τῆς Ἰτύκης πολιορκίαν, τὸ δὲ πλεῖον, ἀκούων ἐπιμένειν τὸν Σόφακα καὶ τοὺς Καρχηδονίους πάλιν ἁθροίζειν στρατιάν, ἐξῆγε τὰς δυνάμεις καὶ παρενέβαλλε πρὸ τῆς Ἰτύκης. ἅμα δὲ καὶ νείμας τῶν λαφύρων τοὺς μὲν ἐμπόρους ἐξαπέστειλε λυσιτελῶς· καλῆς γὰρ τῆς ὑπὲρ τῶν ὅλων ἐλπίδος ὑπογραφομένης ἐκ τοῦ γεγονότος εὐτυχήματος, ἑτοίμως τὴν παροῦσαν ὠφέλειαν οἱ στρατιῶται παρ’ οὐδὲν ποιούμενοι διετίθεντο τοῖς ἐμπόροις. τῷ δὲ βασιλεῖ τῶν Νομάδων καὶ τοῖς φίλοις τὸ μὲν πρῶτον ἐδόκει κατὰ τὸ συνεχὲς εἰς τὴν οἰκείαν ποιεῖσθαι τὴν ἀναχώρησιν· τῶν δὲ Κελτιβήρων αὐτοῖς ἀπαντησάντων περὶ τὴν Ἄββαν, οἵτινες ἐτύγχανον ὑπὸ τῶν Καρχηδονίων ἐξενολογημένοι, πλείους ὄντες τῶν τετρακισχιλίων, πιστεύοντες ταῖς χερσὶ ταύταις οὕτως ἐπέστησαν καὶ βραχύ τι ταῖς ψυχαῖς ἐθάρρησαν. σὺν δὲ τούτοις ἅμα καὶ τῆς παιδίσκης, ἥτις ἦν θυγάτηρ μὲν Ἀσδρούβου τοῦ στρατηγοῦ, γυνὴ δὲ τοῦ Σόφακος, καθάπερ ἐπάνω. προεῖπον, δεομένης καὶ λιπαρούσης μεῖναι καὶ μὴ καταλιπεῖν ἐν τοιούτοις καιροῖς τοὺς Καρχηδονίους, ἐπείσθη καὶ προσέσχε τοῖς παρακαλουμένοις ὁ Νομάς. οὐ μικρὰ δὲ καὶ τοὺς Καρχηδονίους ἐλπίζειν παρεσκεύασαν οἱ Κελτίβηρες· ἀντὶ μὲν γὰρ τῶν τετρακισχιλίων μυρίους αὑτοὺς ἀπήγγελλον εἶναι, κατὰ δὲ τοὺς κινδύνους ἀνυποστάτους ὑπάρχειν καὶ ταῖς ψυχαῖς καὶ τοῖς καθοπλισμοῖς. ἐκ δὲ ταύτης τῆς φήμης καὶ τῆς χυδαίου καὶ πανδήμου λαλιᾶς μετεωρισθέντες οἱ Καρχηδόνιοι διπλασίως ἐπερρώσθησαν πρὸς τὸ πάλιν ἀντιποιήσασθαι τῶν ὑπαίθρων. καὶ τέλος ἐν ἡμέραις τριάκοντα περὶ τὰ Μεγάλα πεδία καλούμενα βαλόμενοι χάρακα συνεστρατοπέδευον ὁμοῦ τοῖς Νομάσι καὶ τοῖς Κελτίβηρσιν, ὄντες οὐκ ἐλάττους οἱ πάντες τρισμυρίων.", "st": "14.7"}, {"sp": "N", "t": "ὧν διασαφηθέντων εἰς τὸ τῶν Ῥωμαίων στρατόπεδον εὐθέως ὁ Πόπλιος ἐγίνετο περὶ τὴν ἔξοδον, καὶ συντάξας τοῖς πολιορκοῦσι τὴν Ἰτύκην ἃ δέον ἦν πράττειν καὶ τοῖς κατὰ θάλατταν ἐξώρμησε, τὸ στράτευμα πᾶν ἔχων εὔζωνον. ἀφικόμενος δὲ πεμπταῖος ἐπὶ τὰ Μεγάλα πεδία καὶ συνεγγίσας τοῖς πολεμίοις, τὴν μὲν πρώτην ἡμέραν ἐπί τινος λόφου κατεστρατοπέδευσε, περὶ τριάκοντα σταδίους ἀποσχὼν τῶν πολεμίων, τῇ δ’ ἑξῆς καταβὰς εἰς τὰ πεδία καὶ προθέμενος τοὺς ἱππέας ἐν ἑπτὰ σταδίοις παρενέβαλε. δύο δὲ τὰς κατὰ πόδας ἡμέρας μείναντες καὶ βραχέα διὰ τῶν ἀκροβολισμῶν καταπειράσαντες ἀλλήλων, τῇ τετάρτῃ κατὰ πρόθεσιν ἐξῆγον ἀμφότεροι καὶ παρενέβαλλον τὰς δυνάμεις. ὁ μὲν οὖν Πόπλιος ἁπλῶς κατὰ τὸ παρ’ αὐτοῖς ἔθος ἔθηκε πρῶτον μὲν τὰς τῶν ἁστάτων σημαίας, ἐπὶ δὲ ταύταις τὰς τῶν πριγκίπων, τελευταίας δ’ ἐπέστησε κατόπιν τὰς τῶν τριαρίων· τῶν δ’ ἱππέων τοὺς μὲν Ἰταλικοὺς ἐπὶ τὸ δεξιὸν ἔθηκε, τοὺς δὲ Νομάδας καὶ Μασαννάσαν ἐπὶ τὸ λαιόν. οἱ δὲ περὶ τὸν Σόφακα καὶ τὸν Ἀσδρούβαν τοὺς μὲν Κελτίβηρας μέσους ἔταξαν ἀντίους ταῖς τῶν Ῥωμαίων σπείραις, τοὺς δὲ Νομάδας ἐξ εὐωνύμου, τοὺς δὲ Καρχηδονίους ἐκ τῶν δεξιῶν. ἅμα δὲ τῷ γενέσθαι τὴν πρώτην ἔφοδον εὐθέως οἱ Νομάδες ἐνέκλιναν τοὺς Ἰταλικοὺς ἱππεῖς, οἵ τε Καρχηδόνιοι τοὺς περὶ τὸν Μασαννάσαν, ἅτε πλεονάκις ἤδη προηττημένοι ταῖς ψυχαῖς. οἱ δὲ Κελτίβηρες ἐμάχοντο γενναίως, συστάντες τοῖς Ῥωμαίοις. οὔτε γὰρ φεύγοντες ἐλπίδα σωτηρίας εἶχον διὰ τὴν ἀπειρίαν τῶν τόπων οὔτε ζωγρίᾳ κρατηθέντες διὰ τὴν ἀθεσίαν τὴν εἰς τὸν Πόπλιον· οὐδὲν γὰρ πολέμιον πεπονθότες ὑπ’ αὐτοῦ κατὰ τὰς ἐν Ἰβηρίᾳ πράξεις ἀδίκως ἐφαίνοντο καὶ παρασπόνδως ἥκειν κατὰ Ῥωμαίων συμμαχήσοντες τοῖς Καρχηδονίοις. οὐ μὴν ἀλλ’ ἅμα τῷ κλῖναι τοὺς ἀπὸ τῶν κεράτων ταχέως κυκλωθέντες ὑπὸ τῶν πριγκίπων καὶ τριαρίων αὐτοῦ κατεκόπησαν πάντες πλὴν τελέως ὀλίγων. οἱ μὲν οὖν Κελτίβηρες τοῦτον τὸν τρόπον ἀπώλοντο, μεγάλην [παρ’ ὅλην] παρασχόμενοι χρείαν τοῖς Καρχηδονίοις οὐ μόνον κατὰ τὴν μάχην, ἀλλὰ καὶ κατὰ τὴν φυγήν. εἰ μὴ γὰρ τοῦτ’ ἐμπόδιον ἐγένετο τοῖς Ῥωμαίοις, ἀλλ’ εὐθέως ἐκ ποδὸς ἠκολούθησαν τοῖς φεύγουσι, παντελῶς ἂν ὀλίγοι διέφυγον τῶν ὑπεναντίων. νῦν δὲ περὶ τούτους γενομένης ἐπιστάσεως οἵ τε περὶ τὸν Σόφακα μετὰ τῶν ἱππέων ἀσφαλῶς ἐποιήσαντο τὴν ἀποχώρησιν εἰς τὴν οἰκείαν, οἵ τε περὶ τὸν Ἀσδρούβαν μετὰ τῶν διασῳζομένων εἰς τὴν Καρχηδόνα.", "st": "14.8"}, {"sp": "N", "t": "ὁ δὲ στρατηγὸς τῶν Ῥωμαίων, ἐπεὶ τὰ σκῦλα καὶ τοὺς αἰχμαλώτους εὐτρεπεῖς ἔθετο, συγκαλέσας τὸ συνέδριον ἐβουλεύετο περὶ τῶν ἑξῆς, τί δέον ἦν ποιεῖν. ἔδοξεν οὖν αὐτοῖς τὸν μὲν στρατηγὸν Πόπλιον καὶ μέρος τι τῆς δυνάμεως μένειν ἐπιπορευόμενον τὰς πόλεις, τὸν δὲ Λαίλιον καὶ τὸν Μασαννάσαν, λαβόντας τούς τε Νομάδας καὶ μέρος τῶν Ῥωμαϊκῶν στρατοπέδων, ἕπεσθαι τοῖς περὶ τὸν Σόφακα καὶ μὴ δοῦναι χρόνον εἰς ἐπίστασιν καὶ παρασκευήν. οὗτοι μὲν ταῦτα βουλευσάμενοι διεχωρίσθησαν, οἱ μὲν ἐπὶ τὸν Σόφακα μετὰ τῶν προειρημένων στρατιωτῶν, ὁ δὲ στρατηγὸς ἐπὶ τὰς πόλεις. ὧν αἱ μὲν ἐθελοντὴν προσετίθεντο τοῖς Ῥωμαίοις διὰ τὸν φόβον, ἃς δὲ πολιορκῶν ἐξ ἐφόδου κατὰ κράτος ᾕρει. πάντα δ’ ἦν οἰκεῖα μεταβολῆς τὰ κατὰ τὴν χώραν, ἅτε συνεχῶς [τε] ἐκκείμενα ταῖς κακοπαθείαις καὶ ταῖς εἰσφοραῖς διὰ τὸ πολυχρονίους γεγονέναι τοὺς κατὰ τὴν Ἰβηρίαν πολέμους. ἐν δὲ τῇ Καρχηδόνι μεγάλης καὶ πρότερον ὑπαρχούσης ἀκαταστασίας, ἔτι μείζω τότε συνέβαινε γίνεσθαι τὴν ταραχήν, ὡς ἂν ἐκ δευτέρου τηλικαύτῃ πληγῇ περιπεπτωκότων ἤδη καὶ ἀπειπόντων τὰς ἐν αὑτοῖς ἐλπίδας. οὐ μὴν ἀλλ’ οἱ μὲν ἀνδρωδέστατοι δοκοῦντες εἶναι τῶν συμβούλων ταῖς μὲν ναυσὶν ἐκέλευον ἤδη πλεῖν ἐπὶ τοὺς τὴν Ἰτύκην πολιορκοῦντας, καὶ τήν τε πολιορκίαν πειρᾶσθαι λύειν καὶ ναυμαχεῖν τοῖς ὑπεναντίοις, ἀπαρασκεύοις οὖσι πρὸς τοῦτο τὸ μέρος· ἐπί τε τὸν Ἀννίβαν πέμπειν ἠξίουν καὶ μηδεμίαν ὑπερβολὴν ποιησαμένους ἐξελέγχειν καὶ ταύτην τὴν ἐλπίδα· μεγάλας γὰρ ἀμφοτέραις εἶναι ταῖς ἐπιβολαῖς ἐκ τῶν κατὰ λόγον ἀφορμὰς πρὸς σωτηρίαν. τινὲς δὲ ταύτας μὲν ἔφασαν μηκέτι φέρειν τοὺς καιρούς, τὴν δὲ πόλιν ὀχυροῦν καὶ παρασκευάζεσθαι πρὸς πολιορκίαν· πολλὰς γὰρ δώσειν ἀφορμὰς ταὐτόματον, ἂν ὁμονοῶσιν. ἅμα δὲ βουλεύεσθαι περὶ διαλύσεως καὶ συνθηκῶν παρῄνουν, ἐπὶ τίσι καὶ πῶς ἂν λύσιν ποιήσαιντο τῶν ἐνεστώτων κακῶν. γενομένων δὲ καὶ πλειόνων λόγων περὶ ταῦτα, πάσας ἐκύρωσαν ἅμα τὰς γνώμας.", "st": "14.9"}, {"sp": "N", "t": "κριθέντων δὲ τούτων οἱ μὲν εἰς τὴν Ἰταλίαν μέλλοντες πλεῖν εὐθέως ἐκ τοῦ βουλευτηρίου προῆγον ἐπὶ θάλατταν, ὁ δὲ ναύαρχος ἐπὶ τὰς ναῦς· οἱ δὲ λοιποὶ περί τε τῆς κατὰ τὴν πόλιν ἀσφαλείας προενοοῦντο καὶ περὶ τῶν κατὰ μέρος ἐβουλεύοντο συνεχῶς. καὶ [ὁ] Πόπλιος, καταγέμοντος ἤδη τοῦ στρατοπέδου τῆς λείας διὰ τὸ μηδέν’ ἀντιπράττειν, ἀλλὰ πάντας εἴκειν ταῖς ἐπιβολαῖς, ἔκρινε τὸ μὲν τῶν λαφύρων πλεῖον εἰς τὴν ἐξ ἀρχῆς παραπέμψαι παρεμβολήν, αὐτὸς δὲ τὴν στρατείαν ἀναλαβὼν εὔζωνον καταλαβέσθαι τὸν ἐπὶ Τύνητι χάρακα καὶ στρατοπεδεῦσαι τοῖς Καρχηδονίοις ἐν συνόψει· μάλιστα γὰρ οὕτως ἐκφοβήσειν ὑπελάμβανε καὶ καταπλήξειν αὐτούς. οἱ μὲν οὖν Καρχηδόνιοι μετ’ ὀλίγας ἡμέρας τά τε πληρώματα καὶ τὰς σιταρχίας ἑτοίμας ἔχοντες ἐν ταῖς ναυσὶν ἐγίνοντο πρὸς ἀναγωγῇ καὶ τοῖς προκειμένοις· ὁ δὲ Πόπλιος ἧκε πρὸς τὸν Τύνητα, καὶ φυγόντων τὴν ἔφοδον αὐτοῦ τῶν παραφυλαττόντων κατέλαβε τὸν τόπον. ὁ δὲ Τύνης ἀπέχει μὲν τῆς Καρχηδόνος ὡς ἑκατὸν εἴκοσι σταδίους, ἔστι δὲ σύνοπτος σχεδὸν ἐξ ὅλης τῆς πόλεως, διαφέρει δ’ ὀχυρότητι καὶ φυσικῇ καὶ χειροποιήτῳ, καθάπερ καὶ πρότερον ἡμῖν εἴρηται. τῶν δὲ Ῥωμαίων ἄρτι κατεστρατοπεδευκότων ἀνήγοντο ταῖς ναυσὶν οἱ Καρχηδόνιοι, ποιούμενοι τὸν πλοῦν εἰς τὴν Ἰτύκην. ὁ δὲ Πόπλιος ὁρῶν τὸν ἀνάπλουν τῶν ὑπεναντίων, καὶ δεδιὼς μή τι περὶ τὸ σφέτερον αὐτῶν ναυτικὸν συμβῇ, διεταράττετο πάντων ἀνυπονοήτως διακειμένων καὶ ἀπαρασκεύως πρὸς τὸ μέλλον. αὖθις δ’ ἐκ μεταβολῆς ἀναστρατοπεδεύσας ἠπείγετο βοηθήσων τοῖς ἰδίοις πράγμασι. καταλαβὼν δὲ τὰς καταφράκτους ναῦς πρὸς μὲν τὰς ἐξαιρέσεις καὶ προσαγωγὰς τῶν ὀργάνων καὶ καθόλου πρὸς πολιορκίαν εὖ καὶ δεόντως ἐξηρτυμένας, πρὸς δὲ ναυμαχίαν ἥκιστα παρεσκευασμένας, τὸν δὲ τῶν ὑπεναντίων στόλον ἐξ ὅλου τοῦ χειμῶνος πρὸς αὐτὸ τοῦτο κατηρτισμένον, τὸ μὲν ἀντανάγεσθαι καὶ ναυμαχεῖν ἀπογνούς, συνορμίσας δὲ τὰς καταφράκτους νῆας περιέστησε ταύταις τὰς φορτηγοὺς ἐπὶ τρεῖς καὶ τέτταρας τὸ βάθος, κἄπειτα καθελόμενος τοὺς ἱστοὺς καὶ τὰς κεραίας ἔζευξε τούτοις βιαίως πρὸς ἀλλήλας, βραχὺ διάστημα ποιῶν, ὥσθ’ ὑπηρετικοῖς ἐκπλεῖν δύνασθαι καὶ διαπλεῖν.", "st": "14.10"}, {"sp": "N", "t": "⟨Πολύβιος⟩ ἐν τῇ τεσσαρεσκαιδεκάτῃ ⟨φησὶν⟩ Ἀγαθοκλέους τοῦ Οἰνάνθης υἱοῦ, ἑταίρου δὲ τοῦ Φιλοπάτορος βασιλέως, ⟨κόλακα γενέσθαι⟩ Φίλωνα. — Πολύβιος δὲ ἐν τῇ τεσσαρεσκαιδεκάτῃ τῶν ἱστοριῶν Κλεινοῦς φησι τῆς οἰνοχοούσης αὑτῷ ⟨Πτολεμαίῳ τῷ Φιλαδέλφῳ⟩ εἰκόνας πολλὰς ἀνακεῖσθαι κατὰ τὴν Ἀλεξάνδρειαν μονοχίτωνας καὶ ῥυτὸν ἐχούσας ἐν ταῖς χερσίν. αἱ δὲ κάλλισται τῶν οἰκιῶν, φησίν, οὐ Μυρτίου καὶ Μνησίδος καὶ Ποθεινῆς προσαγορεύονται; καίτοι Μνησὶς μὲν ἦν αὐλητρὶς καὶ Ποθεινή. Μύρτιον δὲ μία τῶν ἀποδεδειγμένων καὶ κοινῶν δεικτηριάδων. τοῦ δὲ Φιλοπάτορος βασιλέως Πτολεμαίου οὐκ Ἀγαθόκλεια ἡ ἑταίρα ἐκράτει ἡ καὶ πᾶσαν ἀνατρέψασα τὴν βασιλείαν; —", "st": "14.11"}, {"sp": "N", "t": "ἴσως δέ τινες ἐπαπορήσουσι πῶς ἡμεῖς τὰς ἄλλας πράξεις ἁπάσας κατ’ ἐνιαυτὸν γράφοντες τὰς καταλλήλους περὶ μόνων τῶν κατ’ Αἴγυπτον ἐν καιρῷ τῷ νῦν ἐκ πλείονος χρόνου πεποιήμεθα τὴν ἐξήγησιν. ἡμεῖς δὲ τοῦτο πεποιήκαμεν διά τινας τοιαύτας αἰτίας. Πτολεμαῖος ὁ βασιλεύς, περὶ οὗ νῦν ὁ λόγος, ὁ Φιλοπάτωρ, μετὰ τὸ συντελεσθῆναι τὸν περὶ Κοίλην Συρίαν πόλεμον ἀποστὰς πάντων τῶν καλῶν ἐτράπη πρὸς βίον ἄσωτον καὶ τοιοῦτον οἷον ἀρτίως διεληλύθαμεν. ὀψὲ δέ ποτε βιασθεὶς ὑπὸ τῶν πραγμάτων ἐνέπεσεν εἰς τὸν νῦν δεδηλωμένον πόλεμον, ὃς χωρὶς τῆς εἰς ἀλλήλους ὠμότητος καὶ παρανομίας οὔτε παράταξιν οὔτε ναυμαχίαν οὔτε πολιορκίαν οὔθ’ ἕτερον οὐδὲν ἔσχε μνήμης ἄξιον. διόπερ ὑπέδραμεν οὕτω κἀμοὶ τῷ γράφοντι ῥᾳδίαν ἔσεσθαι καὶ τοῖς ἀναγινώσκουσιν εὐμαθεστέραν τὴν διήγησιν, εἰ μὴ κατ’ ἐνιαυτὸν ἐπιψαύων μικρῶν [καὶ] οὐκ ἀξίων ἐπιστάσεως πραγμάτων ἀποδιδοίην τὸν λόγον, ἀλλ’ εἰσάπαξ οἷον εἰ σωματοειδῆ ποιήσας τὴν τοῦ βασιλέως προαίρεσιν ἀπαγγείλαιμι περὶ αὐτῆς.", "st": "14.12"}, {"sp": "HDR", "t": "Βιβλίον ΙΕʹ", "st": "15"}, {"sp": "N", "t": "ὅτι τῶν Καρχηδονίων λαβόντων αἰχμαλώτους τὰς φορτηγοὺς νῆας τῶν Ῥωμαίων καὶ χορηγίας πλῆθος ἐξαίσιον ὁ Πόπλιος βαρέως μὲν ἔφερεν ἐπὶ τῷ μὴ μόνον σφίσι παρῃρῆσθαι τὴν χορηγίαν, ἀλλὰ καὶ τοῖς ἐχθροῖς παρεσκευάσθαι δαψίλειαν τῶν ἀναγκαίων, ἔτι δὲ βαρύτερον ἐπὶ τῷ παραβεβηκέναι τοὺς ὅρκους καὶ τὰς συνθήκας τοὺς Καρχηδονίους καὶ πάλιν ἐξ ἄλλης ἀρχῆς ἐγείρεσθαι τὸν πόλεμον. διὸ καὶ παραυτίκα προχειρισάμενος πρεσβευτὰς Λεύκιον Σέργιον καὶ Λεύκιον Βαίβιον καὶ Λεύκιον Φάβιον ἐξαπέστειλε διαλεξομένους τοῖς Καρχηδονίοις ὑπὲρ τῶν γεγονότων, ἅμα δὲ καὶ δηλώσοντας ὅτι κεκύρωκε τὰς συνθήκας ὁ δῆμος τῶν Ῥωμαίων· ἄρτι γὰρ ἧκε τῷ Ποπλίῳ γράμματα διασαφοῦντα περὶ τῶν προειρημένων. οἱ δὲ παραγενηθέντες εἰς τὴν Καρχηδόνα τὸ μὲν πρῶτον εἰς τὴν σύγκλητον, μετὰ δὲ ταῦτα πάλιν ἐπὶ τοὺς πολλοὺς παραχθέντες, ἔλεγον ὑπὲρ τῶν ἐνεστώτων μετὰ παρρησίας, πρῶτον μὲν ἀναμιμνήσκοντες ὡς οἱ παρ’ ἐκείνων πρεσβευταί, παραγενηθέντες εἰς Τύνητα πρὸς σφᾶς καὶ παρελθόντες εἰς τὸ συνέδριον, οὐ μόνον τοὺς θεοὺς ἀσπάσαιντο καὶ τὴν γῆν προσκυνήσαιεν, καθάπερ ἔστιν ἔθος τοῖς ἄλλοις ἀνθρώποις, ἀλλὰ καὶ πεσόντες ἐπὶ τὴν γῆν ἀγεννῶς τοὺς πόδας καταφιλοῖεν τῶν ἐν τῷ συνεδρίῳ, μετὰ δὲ ταῦτα πάλιν ἀναστάντες [ὡς] κατηγορήσαιεν σφῶν αὐτῶν, διότι καὶ τὰς ἐξ ἀρχῆς γενομένας συνθήκας Ῥωμαίοις καὶ Καρχηδονίοις ἀθετήσαιεν αὐτοί. διόπερ ἔφασαν οὐκ ἀγνοεῖν ὅτι πᾶν εἰκότως ἂν πάθοιεν ὑπὸ Ῥωμαίων, ἀλλὰ τῆς τύχης ἕνεκα τῶν ἀνθρώπων ἐδέοντο μηδὲν παθεῖν ἀνήκεστον· ἔσεσθαι γὰρ τὴν σφετέραν ἀβουλίαν ἀπόδειξιν τῆς Ῥωμαίων καλοκἀγαθίας. ὧν μνημονεύοντα τὸν στρατηγὸν ἔφασαν [τὸν] αὐτὸν οἱ πρέσβεις καὶ τοὺς ἐν τῷ συνεδρίῳ τότε γεγονότας ἐκπλήττεσθαι, τίνι ποτὲ πιστεύοντες ἐπελανθάνοντο μὲν τῶν τότε ῥηθέντων, ἀθετεῖν δὲ τολμῶσι τοὺς ὅρκους καὶ τὰς συνθήκας. σχεδὸν δὲ τοῦτ’ εἶναι δῆλον ὡς Ἀννίβᾳ πεποιθότες καὶ ταῖς μετὰ τούτου παρούσαις δυνάμεσι ταῦτα τολμῶσι ποιεῖν, κακῶς φρονοῦντες· σαφῶς γὰρ εἰδέναι πάντας ὅτι ἐκεῖνοι δεύτερον ἔτος ἤδη φεύγοντες ἐκ πάσης Ἰταλίας εἰς τοὺς περὶ Λακίνιον τόπους, κἀκεῖ συγκεκλεισμένοι καὶ μόνον οὐ πολιορκούμενοι, μόλις ἑαυτοὺς ἐκσεσωκότες ἥκουσι νῦν. \"οὐ μὴν ἀλλ’ εἰ καὶ νενικηκότες τοὺς ἐκεῖ παρῆσαν, καὶ πρὸς ἡμᾶς ἔμελλον διακινδυνεύειν τοὺς δυσὶ μάχαις ἑξῆς ὑμᾶς ἤδη νενικηκότας, ὅμως ἀμφιδόξους ἔχειν ἔδει τὰς ἐλπίδας ὑπὲρ τοῦ μέλλοντος, καὶ μὴ μόνον τοῦ νικᾶν ἔννοιαν λαμβάνειν, ἀλλὰ καὶ τοῦ σφαλῆναι πάλιν. οὗ συμβάντος ποίους ἐπικαλέσεσθε\" ἔφη \"θεούς; ποίοις δὲ χρώμενοι λόγοις τὸν ἐκ τῶν κρατούντων ἔλεον ἐπισπάσεσθε πρὸς τὰς ἑαυτῶν συμφοράς; πάσης εἰκὸς ὑμᾶς ἐλπίδος ἀποκλεισθήσεσθαι καὶ παρὰ θεῶν καὶ παρ’ ἀνθρώπων διὰ τὴν ἀθεσίαν καὶ τὴν ἀβουλίαν.\"", "st": "15.1"}, {"sp": "N", "t": "οἱ μὲν οὖν πρέσβεις τοιαῦτα διαλεχθέντες ἀνεχώρησαν· τῶν δὲ Καρχηδονίων ὀλίγοι μὲν ἦσαν οἱ συναινοῦντες μὴ παραβαίνειν τὰς ὁμολογίας, οἱ δὲ πλείους καὶ τῶν πολιτευομένων καὶ τῶν βουλευομένων βαρέως μὲν ἔφερον τὰς ἐν ταῖς συνθήκαις ἐπιταγάς, δυσχερῶς δ’ ἀνείχοντο τὴν τῶν πρεσβευτῶν παρρησίαν, πρὸς δὲ τούτοις οὐχ οἷοί τ’ ἦσαν προέσθαι τὰ κατηγμένα πλοῖα καὶ τὰς ἐκ τούτων χορηγίας. τὸ δὲ συνέχον, οὐ μικρὰς ἀλλὰ μεγάλας εἶχον ἐλπίδας νικήσειν διὰ τῶν περὶ τὸν Ἀννίβαν. τοῖς μὲν οὖν πολλοῖς ἔδοξε τοὺς πρέσβεις ἀναποκρίτους ἐξαποστέλλειν· τῶν δὲ πολιτευομένων οἷς ἦν προκείμενον ἐκ παντὸς τρόπου συγχέαι πάλιν τὸν πόλεμον, οὗτοι συνεδρεύσαντες μηχανῶνταί τι τοιοῦτον. ἔφασαν δεῖν πρόνοιαν ποιήσασθαι τῶν πρεσβευτῶν, ἵνα μετ’ ἀσφαλείας ἀνακομισθῶσιν εἰς τὴν ἰδίαν παρεμβολήν. καὶ παραυτίκα τούτοις μὲν ἡτοίμαζον δύο τριήρεις παραπόμπους, πρὸς δὲ τὸν ναύαρχον Ἀσδρούβαν διεπέμψαντο παρακαλοῦντες ἑτοιμάσαι πλοῖα μὴ μακρὰν τῆς τῶν Ῥωμαίων παρεμβολῆς, ἵν’ ἐπειδὰν αἱ παραπέμπουσαι νῆες ἀπολίπωσι τοὺς Ῥωμαίους, ἐπαναχθέντα ταῦτα καταποντίσῃ τοὺς πρεσβευτάς. ἐφώρμει γὰρ αὐτοῖς τὸ ναυτικὸν κατὰ τοὺς πρὸ τῆς Ἰτύκης ἐγκειμένους τόπους. οὗτοι μὲν οὖν ταῦτα διαταξάμενοι πρὸς τὸν Ἀσδρούβαν ἐξέπεμπον τοὺς Ῥωμαίους, ἐντειλάμενοι τοῖς ἐπὶ τῶν τριήρων, [ὡς] ἐὰν παραλλάξωσι τὸν Μακάραν ποταμόν, αὖθις ἀπολιπόντας ἀποπλεῖν ἐν τῷ πόρῳ τοὺς πρεσβευτάς· καὶ γὰρ ἦν ἐκ τούτων τῶν τόπων συνορᾶν ἤδη τὴν τῶν ὑπεναντίων παρεμβολήν· οἱ δὲ παραπέμποντες, ἐπεὶ κατὰ τὸ συνταχθὲν παρήλλαξαν τὸν ποταμόν, ἀσπασάμενοι τοὺς Ῥωμαίους αὖθις ἐπανέπλεον. οἱ δὲ περὶ τὸν Λεύκιον ἄλλο μὲν οὐδὲν ὑφεωρῶντο δεινόν, νομίσαντες δὲ τοὺς παραπέμποντας δι’ ὀλιγωρίαν αὐτοὺς προαπολιπεῖν ἐπὶ ποσὸν ἐδυσχέραινον. ἅμα δὲ τῷ μονωθέντας αὐτοὺς πλεῖν ἐπανάγονται τρισὶ τριήρεσιν ἐξ ὑποβολῆς οἱ Καρχηδόνιοι, καὶ παραβαλόντες τῇ Ῥωμαϊκῇ πεντήρει τρῶσαι μὲν οὐχ οἷοί τ’ ἦσαν, ὑποχωρούσης τῆς νεώς, οὐδὲ τοῦ καταστρώματος ἐπιβῆναι διὰ τὸ γενναίως ἀμύνεσθαι τοὺς ἄνδρας· ἐκ παραβολῆς δὲ καὶ πέριξ προσμαχόμενοι κατετίτρωσκον τοὺς ἐπιβάτας καὶ διέφθειρον πολλοὺς αὐτῶν, ἕως οὗ κατιδόντες οἱ Ῥωμαῖοι τοὺς προνομεύοντας τὴν παραλίαν ἀπὸ τῆς ἰδίας στρατοπεδείας παραβοηθοῦντας ἐπὶ τὸν αἰγιαλὸν ἐξέβαλον τὴν ναῦν εἰς τὴν γῆν. τῶν μὲν οὖν ἐπιβατῶν οἱ πλεῖστοι διεφθάρησαν, οἱ δὲ πρεσβευταὶ παραδόξως ἐξεσώθησαν.", "st": "15.2"}, {"sp": "N", "t": "γενομένων δὲ τούτων αὖθις ὁ πόλεμος ἄλλην ἀρχὴν εἰλήφει βαρυτέραν τῆς πρόσθεν καὶ δυσμενικωτέραν. οἵ τε γὰρ Ῥωμαῖοι δοκοῦντες παρεσπονδῆσθαι φιλοτίμως διέκειντο πρὸς τὸ περιγενέσθαι τῶν Καρχηδονίων, οἵ τε Καρχηδόνιοι συνειδότες σφίσι τὰ πεπραγμένα πρὸς πᾶν ἑτοίμως εἶχον πρὸς τὸ μὴ τοῖς ἐχθροῖς ὑποχείριοι γενηθῆναι. τοιαύτης δὲ τῆς ἐξ ἀμφοῖν παραστάσεως ὑπαρχούσης προφανὲς ἦν ὅτι δεήσει μάχῃ κρίνεσθαι περὶ τῶν ἐνεστώτων. ἐξ οὗ συνέβαινε μὴ μόνον τοὺς κατὰ τὴν Ἰταλίαν καὶ Λιβύην πάντας, ἀλλὰ καὶ τοὺς κατὰ τὴν Ἰβηρίαν καὶ Σικελίαν καὶ Σαρδόνα μετεώρους εἶναι καὶ περισπᾶσθαι ταῖς διανοίαις, καραδοκοῦντας τὸ συμβησόμενον. κατὰ δὲ τὸν καιρὸν τοῦτον Ἀννίβας, ἐλλείπων τοῖς ἱππικοῖς, διέπεμπε πρός τινα Νομάδα Τυχαῖον, ὃς ἦν μὲν οἰκεῖος Σόφακος, ἱππεῖς δὲ μαχιμωτάτους ἔχειν ἐδόκει τῶν κατὰ τὴν Λιβύην, παρακαλῶν αὐτὸν βοηθεῖν καὶ συνεπιλαμβάνεσθαι τοῦ καιροῦ, σαφῶς γινώσκοντα διότι Καρχηδονίων κρατησάντων δύναται διαφυλάττειν τὴν ἀρχήν, Ῥωμαίων δ’ ἐκνικησάντων καὶ τῷ βίῳ κινδυνεύσει διὰ τὴν Μασαννάσου φιλαρχίαν. οὗτος οὖν πεισθεὶς τοῖς παρακαλουμένοις ἧκε μετὰ δισχιλίων ἱππέων πρὸς τὸν Ἀννίβαν.", "st": "15.3"}, {"sp": "N", "t": "Πόπλιος δὲ τὰ περὶ τὴν ναυτικὴν δύναμιν ἀσφαλισάμενος καὶ καταλιπὼν Βαίβιον ἀντιστράτηγον, αὐτὸς μὲν ἐπεπορεύετο τὰς πόλεις, οὐκέτι παραλαμβάνων εἰς τὴν πίστιν τοὺς ἐθελοντὴν σφᾶς αὐτοὺς ἐγχειρίζοντας, ἀλλὰ μετὰ βίας ἀνδραποδιζόμενος καὶ φανερὰν ποιῶν τὴν ὀργήν, ἣν εἶχε πρὸς τοὺς πολεμίους διὰ τὴν Καρχηδονίων παρασπόνδησιν· πρὸς δὲ Μασαννάσαν διεπέμπετο συνεχῶς, ἀποδηλῶν αὐτῷ τίνα τρόπον παραβεβηκότες εἶεν οἱ Φοίνικες τὰς σπονδάς, καὶ παρακαλῶν ἁθροίζειν δύναμιν ὡς πλείστην καὶ συνάπτειν αὐτῷ κατὰ σπουδήν. ὁ γὰρ Μασαννάσας ἅμα τῷ γενέσθαι τὰς συνθήκας, καθάπερ εἴρηται πρότερον, εὐθέως ἀφώρμησε μετὰ τῆς ἰδίας δυνάμεως, προσλαβὼν δέκα σημαίας Ῥωμαϊκὰς ἱππέων καὶ πεζῶν καὶ πρεσβευτὰς παρὰ τοῦ στρατηγοῦ, χάριν τοῦ μὴ μόνον τὴν πατρῴαν ἀρχὴν ἀπολαβεῖν, ἀλλὰ καὶ τὴν τοῦ Σόφακος προσκατακτήσασθαι διὰ τῆς Ῥωμαίων ἐπικουρίας· ὃ καὶ συνέβη γενέσθαι. συνέτυχε δὲ καὶ τοὺς ἐκ Ῥώμης πρεσβευτὰς περὶ τοὺς αὐτοὺς καιροὺς εἰς τὸν ναυτικὸν χάρακα τὸν τῶν Ῥωμαίων καταπλεῦσαι. τοὺς μὲν οὖν παρ’ αὑτῶν ὁ Βαίβιος παραχρῆμα πρὸς τὸν Πόπλιον ἐξέπεμψε, τοὺς δὲ τῶν Καρχηδονίων παρακατεῖχε, τά τε λοιπὰ δυσθύμως διακειμένους καὶ νομίζοντας ἐν τοῖς μεγίστοις εἶναι κινδύνοις· πυθόμενοι γὰρ τὴν γεγενημένην ἐκ τῶν Καρχηδονίων ἀσέβειαν πρὸς τοὺς τῶν Ῥωμαίων πρέσβεις, πρόδηλον ἐδόκουν εἶναι σφίσι τὴν ἐκ τούτων τιμωρίαν. ὁ δὲ Πόπλιος, διακούσας τῶν παραγεγονότων ὅτι προθύμως ἥ τε σύγκλητος ὅ τε δῆμος ἀποδέξαιντο τὰς γενομένας δι’ αὑτοῦ συνθήκας πρὸς τοὺς Καρχηδονίους καὶ διότι πρὸς πᾶν τὸ παρακαλούμενον ἑτοίμως ἔχοιεν, ἐπὶ μὲν τούτοις ἔχαιρε μεγάλως, τοὺς δὲ τῶν Καρχηδονίων προσέταξε τῷ Βαιβίῳ μετὰ πάσης φιλανθρωπίας ἀποπέμπειν εἰς τὴν οἰκείαν, πάνυ καλῶς βουλευσάμενος, ὥς γ’ ἐμοὶ δοκεῖ, καὶ φρονίμως. θεωρῶν γὰρ τὴν σφετέραν πατρίδα περὶ πλείστου ποιουμένην τὴν περὶ τοὺς πρεσβευτὰς πίστιν, ἐσκοπεῖτο παρ’ αὑτῷ συλλογιζόμενος οὐχ οὕτως τί δέον παθεῖν Καρχηδονίους, ὡς τί δέον ἦν πρᾶξαι Ῥωμαίους. διὸ παρακατασχὼν τὸν ἴδιον θυμὸν καὶ τὴν ἐπὶ τοῖς γεγονόσι πικρίαν, ἐπειράθη διαφυλάξαι, κατὰ τὴν παροιμίαν \"πατέρων εὖ κείμενα ἔργα.\" τοιγαροῦν καὶ τοὺς ἐν τῇ Καρχηδόνι πάντας ἥττησε ταῖς ψυχαῖς καὶ τὸν Ἀννίβαν αὐτόν, ὑπερθέμενος τῇ καλοκἀγαθίᾳ τὴν ἐκείνων ἄνοιαν.", "st": "15.4"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι θεωροῦντες τὰς πόλεις ἐκπορθουμένας, ἔπεμπον πρὸς τὸν Ἀννίβαν, δεόμενοι μὴ μέλλειν, ἀλλὰ προσπελάζειν τοῖς πολεμίοις καὶ κρίνειν τὰ πράγματα διὰ μάχης. ὁ δὲ διακούσας τοῖς μὲν παροῦσιν ἀπεκρίθη τἄλλα σκοπεῖν, περὶ δὲ τούτου ῥᾳθυμεῖν· διαλήψεσθαι γὰρ τὸν καιρὸν αὐτός. μετὰ δέ τινας ἡμέρας ἀναζεύξας ἐκ τῶν παρὰ τὸν Ἀδρύμητα τόπων προῆλθε καὶ κατεστρατοπέδευσε περὶ Ζάμαν· αὕτη δ’ ἐστὶ πόλις ἀπέχουσα Καρχηδόνος ὡς πρὸς τὰς δύσεις ὁδὸν ἡμερῶν πέντε. κἀκεῖθεν ἐξέπεμψε τρεῖς κατασκόπους, βουλόμενος ἐπιγνῶναι ποῦ στρατοπεδεύουσι καὶ πῶς χειρίζει τὰ κατὰ τὰς παρεμβολὰς ὁ τῶν Ῥωμαίων στρατηγός. Πόπλιος δ’, ἐπαναχθέντων ὡς αὐτὸν τῶν κατασκόπων, τοσοῦτον ἀπέσχε τοῦ κολάζειν τοὺς ἑαλωκότας, καθάπερ ἔθος ἐστὶ τοῖς ἄλλοις, ὡς τοὐναντίον συστήσας αὐτοῖς χιλίαρχον ἐπέταξε πάντα καθαρίως ὑποδεῖξαι τὰ κατὰ τὴν παρεμβολήν. γενομένου δὲ τούτου προσεπύθετο τῶν ἀνθρώπων εἰ πάντα φιλοτίμως αὐτοῖς ὑποδέδειχεν ὁ συσταθείς· τῶν δὲ φησάντων, δοὺς ἐφόδια καὶ παραπομπὴν ἐξαπέστειλε προστάξας ἐπιμελῶς Ἀννίβᾳ διασαφεῖν περὶ τῶν ἀπηντημένων αὐτοῖς. ὧν παραγενηθέντων θαυμάσας ὁ Ἀννίβας τὴν μεγαλοψυχίαν καὶ τόλμαν τἀνδρὸς οὐκ οἶδ’ ὅπως εἰς ὁρμὴν ἔπεσε τοῦ βούλεσθαι συνελθεῖν εἰς λόγους τῷ Ποπλίῳ. κρίνας δὲ τοῦτο διεπέμψατο κήρυκα, φάσκων βούλεσθαι κοινολογηθῆναι πρὸς αὐτὸν ὑπὲρ τῶν ὅλων. ὁ δὲ Πόπλιος ἀκούσας ταῦτα τοῦ κήρυκος συγκατετίθετο τοῖς παρακαλουμένοις, ἔφη δὲ πέμψειν πρὸς αὐτὸν διασαφῶν, ἐπειδὰν μέλλῃ συμπορεύεσθαι, τὸν τόπον καὶ τὸν καιρόν. ταῦτα μὲν οὖν ἀκούσας ὁ κῆρυξ ἐπανῆλθε πάλιν εἰς τὴν ἰδίαν παρεμβολήν· τῇ δ’ ἐπαύριον ἧκε Μασαννάσας, ἔχων πεζοὺς μὲν εἰς ἑξακισχιλίους, ἱππεῖς δὲ περὶ τετρακισχιλίους. ὃν ἀποδεξάμενος ὁ Πόπλιος φιλανθρώπως καὶ συγχαρεὶς ἐπὶ τῷ πάντας ὑπηκόους πεποιῆσθαι τοὺς πρότερον Σόφακι πειθομένους, ἀνέζευξε, καὶ παραγενηθεὶς πρὸς πόλιν Ναράγαρα κατεστρατοπέδευσε, πρός τε τἄλλα τόπον εὐφυῆ καταλαβόμενος καὶ τὴν ὑδρείαν ἐντὸς βέλους ποιησάμενος.", "st": "15.5"}, {"sp": "N", "t": "κἀντεῦθεν ἐξέπεμψε πρὸς τὸν τῶν Καρχηδονίων στρατηγόν, φάσκων ἕτοιμος εἶναι συμπορεύεσθαι πρὸς αὐτὸν εἰς λόγους. ὧν ἀκούσας Ἀννίβας ἀνέζευξε, καὶ συνεγγίσας, ὥστε μὴ πλεῖον ἀπέχειν τριάκοντα σταδίων, κατεστρατοπέδευσε πρός τινα λόφον, ὃς τὰ μὲν λοιπὰ πρὸς τὸν παρόντα καιρὸν ὀρθῶς ἔχειν ἐδόκει, τὴν δ’ ὑδρείαν ἀπωτέρω μικρὸν εἶχε· καὶ πολλὴν ταλαιπωρίαν ὑπέμενον οἱ στρατιῶται περὶ τοῦτο τὸ μέρος, κατὰ δὲ τὴν ἑξῆς ἡμέραν προῆλθον ἀπὸ τῆς ἰδίας παρεμβολῆς ἀμφότεροι μετ’ ὀλίγων ἱππέων, κἄπειτα χωρισθέντες ἀπὸ τούτων αὐτοὶ συνῆλθον εἰς τὸ μέσον ἔχοντες ἑρμηνέα μεθ’ αὑτῶν. δεξιωσάμενος δὲ πρῶτος Ἀννίβας ἤρξατο λέγειν ὡς ἐβούλετο μὲν ἂν μήτε Ῥωμαίους ἐπιθυμῆσαι μηδέποτε μηδενὸς τῶν ἐκτὸς Ἰταλίας μήτε Καρχηδονίους τῶν ἐκτὸς Λιβύης· ἀμφοτέροις γὰρ εἶναι ταύτας καὶ καλλίστας δυναστείας καὶ συλλήβδην ὡς ἂν εἰ περιωρισμένας ὑπὸ τῆς φύσεως. \"ἐπεὶ δὲ πρῶτον μὲν ὑπὲρ τῶν κατὰ Σικελίαν ἀμφισβητήσαντες ἐξεπολεμώσαμεν ἀλλήλους, μετὰ δὲ ταῦτα πάλιν ὑπὲρ τῶν κατ’ Ἰβηρίαν, τὸ δὲ τέλος ὑπὸ τῆς τύχης οὔπω νουθετούμενοι μέχρι τούτου προβεβήκαμεν ὥστε καὶ περὶ τοῦ τῆς πατρίδος ἐδάφους οὓς μὲν κεκινδυνευκέναι, τοὺς δ’ ἀκμὴν ἔτι καὶ νῦν κινδυνεύειν, λοιπόν ἐστιν, εἴ πως δυνάμεθα δι’ αὑτῶν παραιτησάμενοι τοὺς θεοὺς διαλύσασθαι τὴν ἐνεστῶσαν φιλοτιμίαν. ἐγὼ μὲν οὖν ἕτοιμός εἰμι τῷ πεῖραν εἰληφέναι δι’ αὐτῶν τῶν πραγμάτων ὡς εὐμετάθετός ἐστιν ἡ τύχη καὶ παρὰ μικρὸν εἰς ἑκάτερα ποιεῖ μεγάλας ῥοπάς, καθάπερ εἰ νηπίοις παισὶ χρωμένη·", "st": "15.6"}, {"sp": "N", "t": "σὲ δ’ ἀγωνιῶ, Πόπλιε, λίαν\" ἔφη \"καὶ διὰ τὸ νέον εἶναι κομιδῇ καὶ διὰ τὸ πάντα σοι κατὰ λόγον κεχωρηκέναι καὶ τὰ κατὰ τὴν Ἰβηρίαν καὶ τὰ κατὰ τὴν Λιβύην καὶ μηδέπω μέχρι γε τοῦ νῦν εἰς τὴν τῆς τύχης ἐμπεπτωκέναι παλιρρύμην, μήποτ’ οὐ πεισθῇς διὰ ταῦτα τοῖς ἐμοῖς λόγοις, καίπερ οὖσι πιστοῖς. σκόπει δ’ ἀφ’ ἑνὸς τῶν λόγων τὰ πράγματα, μὴ τὰ τῶν προγεγονότων, ἀλλὰ τὰ καθ’ ἡμᾶς αὐτούς. εἰμὶ τοιγαροῦν Ἀννίβας ἐκεῖνος, ὃς μετὰ τὴν ἐν Κάνναις μάχην σχεδὸν ἁπάσης Ἰταλίας ἐγκρατὴς γενόμενος μετά τινα χρόνον ἧκον πρὸς αὐτὴν τὴν Ῥώμην, καὶ στρατοπεδεύσας ἐν τετταράκοντα σταδίοις ἐβουλευόμην ὑπὲρ ὑμῶν καὶ τοῦ τῆς ὑμετέρας πατρίδος ἐδάφους πῶς ἐστί μοι χρηστέον, ὃς νῦν ἐν Λιβύῃ πάρειμι πρὸς σὲ Ῥωμαῖον ὄντα περὶ τῆς ἐμαυτοῦ καὶ τῶν Καρχηδονίων σωτηρίας κοινολογησόμενος. εἰς ἃ βλέποντα παρακαλῶ σε μὴ μέγα φρονεῖν, ἀλλ’ ἀνθρωπίνως βουλεύεσθαι περὶ τῶν ἐνεστώτων· τοῦτο δ’ ἐστὶ τῶν μὲν ἀγαθῶν ἀεὶ τὸ μέγιστον, τῶν κακῶν δὲ τοὐλάχιστον αἱρεῖσθαι. τίς οὖν ἂν ἕλοιτο νοῦν ἔχων πρὸς τοιοῦτον ὁρμᾶν κίνδυνον οἷος σοὶ νῦν ἐνέστηκεν; ἐν ᾧ νικήσας μὲν οὔτε τῇ σαυτοῦ δόξῃ μέγα τι προσθήσεις οὔτε τῇ τῆς πατρίδος, ἡττηθεὶς δὲ πάντα τὰ πρὸ τούτου σεμνὰ καὶ καλὰ δι’ αὑτὸν ἄρδην ἀναιρήσεις. τί οὖν ἐστιν ὃ προτίθεμαι τέλος τῶν νυνὶ λόγων; πάντα περὶ ὧν πρότερον ἠμφισβητήσαμεν, Ῥωμαίων ὑπάρχειν — ταῦτα δ’ ἦν Σικελία, Σαδρώ, τὰ κατὰ τὴν Ἰβηρίαν — καὶ μηδέποτε Καρχηδονίους Ῥωμαίοις ὑπὲρ τούτων ἀντᾶραι πόλεμον· ὁμοίως δὲ καὶ τὰς ἄλλας νήσους, ὅσαι μεταξὺ κεῖνται τῆς Ἰταλίας καὶ Λιβύης, Ῥωμαίων ὑπάρχειν. ταύτας γὰρ πέπεισμαι τὰς συνθήκας καὶ πρὸς τὸ μέλλον ἀσφαλεστάτας μὲν εἶναι Καρχηδονίοις, ἐνδοξοτάτας δὲ σοὶ καὶ πᾶσι Ῥωμαίοις.\"", "st": "15.7"}, {"sp": "N", "t": "Ἀννίβας μὲν οὖν ταῦτ’ εἶπεν. ὁ δὲ Πόπλιος ὑπολαβὼν οὔτε τοῦ περὶ Σικελίας ἔφη πολέμου Ῥωμαίους οὔτε τοῦ περὶ τῆς Ἰβηρίας αἰτίους γεγονέναι, Καρχηδονίους δὲ προφανῶς· ὑπὲρ ὧν κάλλιστα γινώσκειν αὐτὸν τὸν Ἀννίβαν. μάρτυρας δὲ καὶ τοὺς θεοὺς γεγονέναι τούτων, περιθέντας τὸ κράτος οὐ τοῖς ἄρχουσι χειρῶν ἀδίκων, ἀλλὰ τοῖς ἀμυνομένοις. βλέπειν δὲ καὶ τὰ τῆς τύχης οὐδενὸς ἧττον καὶ τῶν ἀνθρωπίνων στοχάζεσθαι κατὰ δύναμιν. \" ἀλλ’ εἰ μὲν πρὸ τοῦ τοὺς Ῥωμαίους διαβαίνειν εἰς Λιβύην αὐτὸς ἐξ Ἰταλίας ἐκχωρήσας προύτεινας τὰς διαλύσεις ταύτας, οὐκ ἂν οἴομαί σε διαψευσθῆναι τῆς ἐλπίδος. ἐπεὶ δὲ σὺ μὲν ἄκων ἐκ τῆς Ἰταλίας ἀπηλλάγης, ἡμεῖς δὲ διαβάντες εἰς τὴν Λιβύην τῶν ὑπαίθρων ἐκρατήσαμεν, δῆλον ὡς μεγάλην εἴληφε τὰ πράγματα παραλλαγήν. τὸ δὲ δὴ μέγιστον ἤλθομεν ἐπὶ τί πέρας; ἡττηθέντων καὶ δεηθέντων τῶν παρὰ σοῦ πολιτῶν ἐθέμεθα συνθήκας ἐγγράπτους, ἐν αἷς ἦν πρὸς τοῖς ὑπὸ σοῦ νῦν προτεινομένοις τοὺς αἰχμαλώτους ἀποδοῦναι χωρὶς λύτρων Καρχηδονίους, τῶν πλοίων παραχωρῆσαι τῶν καταφράκτων, πεντακισχίλια τάλαντα προσενεγκεῖν, ὅμηρα δοῦναι περὶ τούτων. ταῦτ’ ἦν ἃ συνεθέμεθα πρὸς ἀλλήλους· ὑπὲρ τούτων ἐπρεσβεύσαμεν ἀμφότεροι πρός τε τὴν σύγκλητον τὴν ἡμετέραν καὶ πρὸς τὸν δῆμον, ἡμεῖς μὲν ὁμολογοῦντες εὐδοκεῖν τοῖς γεγραμμένοις, Καρχηδόνιοι δὲ δεόμενοι τούτων τυχεῖν. ἐπείσθη τὸ συνέδριον τούτοις, ὁ δὲ δῆμος συγκατῄνεσε. τυχόντες ὧν ἠξίουν ἠθέτησαν ταῦτα Καρχηδόνιοι, παρασπονδήσαντες ἡμᾶς. τί λείπεται ποιεῖν; σὺ τὴν ἐμὴν χώραν μεταλαβὼν εἶπον. ἀφελεῖν τὰ βαρύτατα τῶν ὑποκειμένων ἐπιταγμάτων; ἵνα δὴ λαβόντες ἆθλα τῆς παρανομίας διδαχθῶσι τοὺς εὖ ποιοῦντας εἰς τὸ λοιπὸν παρασπονδεῖν· ἀλλ’ ἵνα τυχόντες ὧν ἀξιοῦσι χάριν ὀφείλωσιν ἡμῖν; ἀλλὰ νυνὶ μεθ’ ἱκετηρίας τυχόντες ὧν παρεκάλουν, ὅτι βραχείας ἐλπίδος ἐπελάβοντο τῆς κατὰ σέ, παρὰ πόδας ὡς ἐχθροῖς ἡμῖν κέχρηνται καὶ πολεμίοις. ἐν οἷς βαρυτέρου μέν τινος προσεπιταχθέντος δυνατὸν ἀνενεγκεῖν τῷ δήμῳ περὶ διαλύσεως, ὑφαίρεσιν δὲ ποιουμένοις τῶν ὑποκειμένων οὐδ’ ἀναφορὰν ἔχει τὸ διαβούλιον. τί πέρας οὖν πάλιν τῶν ἡμετέρων λόγων; ἢ τὴν ἐπιτροπὴν ὑμᾶς διδόναι περὶ σφῶν αὐτῶν καὶ τῆς πατρίδος ἢ μαχομένους νικᾶν\".", "st": "15.8"}, {"sp": "N", "t": "ταῦτα μὲν οὖν διαλεχθέντες αὑτοῖς Ἀννίβας καὶ Πόπλιος ἐχωρίσθησαν, ἀσύμβατον ποιησάμενοι τὴν κοινολογίαν. εἰς δὲ τὴν ἐπαύριον ἅμα τῷ φωτὶ τὰς δυνάμεις ἐξῆγον ἀμφότεροι καὶ συνίσταντο τὸν ἀγῶνα, Καρχηδόνιοι μὲν ὑπὲρ τῆς σφετέρας σωτηρίας καὶ τῶν κατὰ τὴν Λιβύην πραγμάτων, Ῥωμαῖοι δὲ περὶ τῆς τῶν ὅλων ἀρχῆς καὶ δυναστείας. ἐφ’ ἃ τίς οὐκ ἂν ἐπιστήσας συμπαθὴς γένοιτο κατὰ τὴν ἐξήγησιν; οὔτε γὰρ δυνάμεις πολεμικωτέρας οὔθ’ ἡγεμόνας ἐπιτυχεστέρους τούτων καὶ μᾶλλον ἀθλητὰς γεγονότας τῶν κατὰ πόλεμον ἔργων εὕροι τις ἂν ἑτέρους, οὐδὲ μὴν ἆθλα μείζω τὴν τύχην ἐκτεθεικυῖαν τοῖς ἀγωνιζομένοις τῶν τότε προκειμένων· οὐ γὰρ τῆς Λιβύης αὐτῆς οὐδὲ τῆς Εὐρώπης ἔμελλον κυριεύειν οἱ τῇ μάχῃ κρατήσαντες, ἀλλὰ καὶ τῶν ἄλλων μερῶν τῆς οἰκουμένης, ὅσα νῦν πέπτωκεν ὑπὸ τὴν ἱστορίαν. ὃ καὶ συνέβη γενέσθαι μετ’ ὀλίγον. πλὴν ὁ μὲν Πόπλιος ἔθηκε τὰς τάξεις τῶν ἰδίων δυνάμεων τὸν τρόπον τοῦτον. πρῶτον μὲν τοὺς ἁστάτους καὶ τὰς τούτων σημαίας ἐν διαστήμασιν, ἐπὶ δὲ τούτοις τοὺς πρίγκιπας, τιθεὶς τὰς σπείρας οὐ κατὰ τὸ τῶν πρώτων σημαιῶν διάστημα, καθάπερ ἔθος ἐστὶ τοῖς Ῥωμαίοις, ἀλλὰ καταλλήλους ἐν ἀποστάσει διὰ τὸ πλῆθος τῶν παρὰ τοῖς ἐναντίοις ἐλεφάντων· τελευταίους δ’ ἐπέστησε τοὺς τριαρίους. ἐπὶ δὲ τῶν κεράτων ἔταξε κατὰ μὲν τὸ λαιὸν Γάιον Λαίλιον, ἔχοντα τοὺς Ἰταλικοὺς ἱππέας, κατὰ δὲ τὸ δεξιὸν μέρος Μασαννάσαν μετὰ πάντων τῶν ὑφ’ ἑαυτὸν ταττομένων Νομάδων. τὰ δὲ διαστήματα τῶν πρώτων σημαιῶν ἀνεπλήρωσε ταῖς τῶν γροσφομάχων σπείραις, παραγγείλας τούτοις προκινδυνεύειν, ἐὰν δ’ ἐκβιάζωνται κατὰ τὴν τῶν θηρίων ἔφοδον, ἀποχωρεῖν, τοὺς μὲν καταταχοῦντας διὰ τῶν ἐπ’ εὐθείας διαστημάτων εἰς τοὐπίσω τῆς ὅλης δυνάμεως, τοὺς δὲ περικαταλαμβανομένους εἰς τὰ πλάγια παρίστασθαι διαστήματα κατὰ τὰς σημαίας.", "st": "15.9"}, {"sp": "N", "t": "ταῦτα δ’ ἑτοιμασάμενος ἐπεπορεύετο παρακαλῶν τὰς δυνάμεις βραχέως μέν, οἰκείως δὲ τῆς ὑποκειμένης περιστάσεως. ἠξίου γὰρ μνημονεύοντας τῶν προγεγονότων ἀγώνων ἄνδρας ἀγαθοὺς γίνεσθαι, σφῶν καὶ τῆς πατρίδος ἀξίους, καὶ λαμβάνειν πρὸ ὀφθαλμῶν ὅτι κρατήσαντες μὲν τῶν ἐχθρῶν οὐ μόνον τῶν ἐν Λιβύῃ πραγμάτων ἔσονται κύριοι βεβαίως, ἀλλὰ καὶ τῆς ἄλλης οἰκουμένης τὴν ἡγεμονίαν καὶ δυναστείαν ἀδήριτον αὑτοῖς τε καὶ τῇ πατρίδι περιποιήσουσιν· ἐὰν δ’ ὡς ἄλλως ἐκβῇ τὰ κατὰ τὸν κίνδυνον, οἱ μὲν ἀποθανόντες εὐγενῶς ἐν τῇ μάχῃ κάλλιστον ἐντάφιον ἕξουσι τὸν ὑπὲρ τῆς πατρίδος θάνατον, οἱ δὲ διαφυγόντες αἴσχιστον καὶ ἐλεεινότατον τὸν ἐπίλοιπον βίον. ἀσφάλειαν γὰρ τοῖς φυγοῦσιν οὐδεὶς ἱκανὸς περιποιῆσαι τόπος τῶν ἐν τῇ Λιβύῃ· πεσοῦσι δ’ ὑπὸ τὰς τῶν Καρχηδονίων χεῖρας οὐκ ἄδηλα [εἶναι] τὰ συμβησόμενα τοῖς ὀρθῶς λογιζομένοις· \"ὧν\" ἔφη \"μηδενὶ γένοιτο πεῖραν ὑμῶν λαβεῖν. τῆς δ’ οὖν τύχης ἡμῖν τὰ μέγιστα τῶν ἄθλων εἰς ἑκάτερον τὸ μέρος ἐκτεθεικυίας, πῶς οὐκ ἂν εἴημεν ἀγεννέστατοι καὶ συλλήβδην ἀφρονέστατοι πάντων, εἰ παρέντες τὰ κάλλιστα τῶν ἀγαθῶν ἑλοίμεθα τὰ μέγιστα τῶν κακῶν διὰ φιλοζωίαν; \" διόπερ ἠξίου δύο προθεμένους, ταῦτα δ’ ἐστὶν ἢ νικᾶν ἢ θνήσκειν, ὁμόσε χωρεῖν εἰς τοὺς πολεμίους. τοὺς γὰρ τοιαύτας ἔχοντας διαλήψεις κατ’ ἀνάγκην ἀεὶ κρατεῖν τῶν ἀντιταττομένων, ἐπειδὰν ἀπελπίσαντες τοῦ ζῆν ἴωσιν εἰς τὴν μάχην.", "st": "15.10"}, {"sp": "N", "t": "ὁ μὲν οὖν Πόπλιος τοιαύτην ἐποιήσατο τὴν παραίνεσιν. ὁ δ’ Ἀννίβας τὰ μὲν θηρία πρὸ πάσης τῆς δυνάμεως, ὄντα πλείω τῶν ὀγδοήκοντα, μετὰ δὲ ταῦτα τοὺς μισθοφόρους ἐπέστησε, περὶ μυρίους ὄντας καὶ δισχιλίους τὸν ἀριθμόν. οὗτοι δ’ ἦσαν Λιγυστῖνοι, Κελτοί, Βαλιαρεῖς, Μαυρούσιοι. τούτων δὲ κατόπιν παρενέβαλε τοὺς ἐγχωρίους Λίβυας καὶ Καρχηδονίους, ἐπὶ δὲ πᾶσι τοὺς ἐξ Ἰταλίας ἥκοντας μεθ’ αὑτοῦ, πλεῖον ἢ στάδιον ἀποστήσας τῶν προτεταγμένων. τὰ δὲ κέρατα διὰ τῶν ἱππέων ἠσφαλίσατο, θεὶς ἐπὶ μὲν τὸ λαιὸν τοὺς συμμάχους Νομάδας, ἐπὶ δὲ τὸ δεξιὸν τοὺς τῶν Καρχηδονίων ἱππεῖς. παρήγγειλε δὲ τοὺς ἰδίους στρατιώτας ἕκαστον παρακαλεῖν, ἀναφέροντας τὴν ἐλπίδα τῆς νίκης ἐφ’ ἑαυτὸν καὶ τὰς μεθ’ αὑτοῦ παραγεγενημένας δυνάμεις· τοῖς δὲ Καρχηδονίοις ἐκέλευσε τοὺς ἡγουμένους τὰ συμβησόμενα περὶ τέκνων καὶ γυναικῶν ἐξαριθμεῖσθαι καὶ τιθέναι πρὸ ὀφθαλμῶν, ἐὰν ἄλλως πως ἐκβῇ τὰ τῆς μάχης. οὗτοι μὲν οὖν οὕτως ἐποίουν τὸ παραγγελθέν. Ἀννίβας δὲ τοὺς μεθ’ αὑτοῦ παραγεγονότας ἐπιπορευόμενος ἠξίου καὶ παρεκάλει διὰ πλειόνων μνησθῆναι μὲν τῆς πρὸς ἀλλήλους ἑπτακαιδεκαέτους συνηθείας, μνησθῆναι δὲ τοῦ πλήθους τῶν προγεγονότων αὐτοῖς πρὸς Ῥωμαίους ἀγώνων· ἐν οἷς ἀηττήτους γεγονότας οὐδ’ ἐλπίδα τοῦ νικᾶν οὐδέποτ’ ἔφη Ῥωμαίοις αὐτοὺς ἀπολελοιπέναι. τὸ δὲ μέγιστον, ἠξίου λαμβάνειν πρὸ ὀφθαλμῶν χωρὶς τῶν κατὰ μέρος κινδύνων καὶ τῶν ἀναριθμήτων προτερημάτων τήν τε περὶ τὸν Τρεβίαν ποταμὸν μάχην πρὸς τὸν πατέρα τοῦ νῦν ἡγουμένου Ῥωμαίων, ὁμοίως τὴν ἐν Τυρρηνίᾳ πρὸς Φλαμίνιον μάχην, ἔτι δὲ τὴν περὶ Κάννας γενομένην πρὸς Αἰμίλιον, ἃς οὔτε κατὰ πλῆθος τῶν ἀνδρῶν οὔτε κατὰ τὰς ἀρετὰς ἀξίας εἶναι συγκρίσεως πρὸς τὸν νῦν ἐπιφερόμενον κίνδυνον. καὶ ταῦτα λέγων ἀναβλέπειν αὐτοὺς ἐκέλευε καὶ τὴν τῶν ὑπεναντίων κατοπτεύειν τάξιν· οὐ γὰρ οἷον ἐλάττους, ἀλλ’ οὐδὲ πολλοστὸν μέρος εἶναι τῶν τότε πρὸς αὐτοὺς ἀγωνισαμένων, ταῖς γε μὴν ἀρεταῖς οὐδὲ σύγκρισιν ἔχειν. ἐκείνους μὲν γὰρ ἀηττήτους ὄντας ἐξ ἀκεραίου διηγωνίσθαι πρὸς σφᾶς, τούτων δὲ τοὺς μὲν ἐκγόνους εἶναι, τοὺς δὲ λείψανα τῶν ἡττημένων ἐν Ἰταλίᾳ καὶ πεφευγότων αὐτὸν πλεονάκις. διόπερ [ᾤετο] δεῖν μὴ καταλῦσαι μήτε τὴν σφῶν αὐτῶν μήτε τὴν τοῦ προεστῶτος δόξαν καὶ προσηγορίαν, ἀλλ’ ἀγωνισαμένους εὐψύχως βεβαιῶσαι τὴν διαδεδομένην περὶ αὐτῶν φήμην, ὡς ὄντων ἀηττήτων. ταῦτα μὲν οὖν καὶ τοιαῦτα παρεκάλεσαν ἀμφότεροι.", "st": "15.11"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἑκατέροις ἦν εὐτρεπῆ τὰ πρὸς τὸν κίνδυνον, πάλαι τῶν Νομαδικῶν ἱππέων πρὸς ἀλλήλους ἀκροβολιζομένων, τότε παρήγγειλε τοῖς ἐπὶ τῶν ἐλεφάντων Ἀννίβας ποιεῖσθαι τὴν ἔφοδον ἐπὶ τοὺς ὑπεναντίους. ἅμα δὲ τῷ πανταχόθεν τὰς σάλπιγγας καὶ τὰς βυκάνας ἀναβοῆσαι τινὰ μὲν διαταραχθέντα τῶν θηρίων ἐξ αὐτῆς ὥρμησε παλίσσυτα κατὰ τῶν βεβοηθηκότων τοῖς Καρχηδονίοις Νομάδων· τῶν περὶ τὸν Μασαννάσαν ταχέως ἐψιλώθη τὸ λαιὸν κέρας τῶν Καρχηδονίων. τὰ δὲ λοιπὰ συμπεσόντα τοῖς τῶν Ῥωμαίων γροσφομάχοις ἐν τῷ μεταξὺ χωρίῳ τῶν παρατάξεων πολλὰ μὲν ἔπασχε κακά, πολλὰ δ’ ἐποίει τοὺς ὑπεναντίους, ἕως ὅτου πεφοβημένα τὰ μὲν διὰ τῶν διαστημάτων ἐξέπεσε, δεξαμένων αὐτὰ τῶν Ῥωμαίων ἀσφαλῶς κατὰ τὴν τοῦ στρατηγοῦ πρόνοιαν, τὰ δ’ ἐπὶ τὸ δεξιὸν μέρος παραφυγόντα διὰ τῶν ἱππέων συνακοντιζόμενα τέλος εἰς τὸν ἔξω τόπον τῶν στρατοπέδων ἐξέπεσεν, ὅτε δὴ καὶ Λαίλιος ἅμα τῇ περὶ τοὺς ἐλέφαντας ταραχῇ συμβαλὼν ἠνάγκασε φυγεῖν τοὺς τῶν Καρχηδονίων ἱππεῖς προτροπάδην. οὗτος μὲν οὖν ἐπέκειτο τοῖς φεύγουσιν ἐκθύμως· τὸ δ’ ὅμοιον ἐποίει καὶ Μασαννάσας. κατὰ δὲ τὸν καιρὸν τοῦτον αἱ φάλαγγες ἀμφότεραι βάδην ἀλλήλαις καὶ σοβαρῶς ἐπῄεσαν, πλὴν τῶν ἐκ τῆς Ἰταλίας μετ’ Ἀννίβου παραγεγονότων· οὗτοι δ’ ἔμενον ἐπέχοντες τὸν ἐξ ἀρχῆς τόπον. ἐπειδὴ δ’ ἐγγὺς ἦσαν ἀλλήλων, οἱ μὲν Ῥωμαῖοι κατὰ τὰ πάτρια συναλαλάξαντες καὶ συμψοφήσαντες τοῖς ξίφεσι τοὺς θυρεοὺς προσέβαλλον τοῖς ὑπεναντίοις, οἱ δὲ μισθοφόροι τῶν Καρχηδονίων ἀδιάκριτον ἐποίουν τὴν φωνὴν καὶ παρηλλαγμένην· οὐ γὰρ πάντων ἦν κατὰ τὸν ποιητὴν ὁ αὐτὸς θροῦς οὐδ’ ἴα γῆρυς, ἄλλη δ’ ἄλλων γλῶσσα, πολύκλητοι δ’ ἔσαν ἄνδρες, καθάπερ ἀρτίως ἐξηριθμησάμην.", "st": "15.12"}, {"sp": "N", "t": "πάσης δ’ οὔσης ἐκ χειρὸς καὶ κατ’ ἄνδρα τῆς μάχης [διὰ τὸ μὴ δόρασι μηδὲ ξίφεσι χρῆσθαι τοὺς ἀγωνιζομένους], τῇ μὲν εὐχερείᾳ καὶ τόλμῃ προεῖχον οἱ μισθοφόροι τὰς ἀρχάς, καὶ πολλοὺς κατετραυμάτιζον τῶν Ῥωμαίων, τῷ δὲ τῆς συντάξεως ἀκριβεῖ καὶ τῷ καθοπλισμῷ πιστεύοντες οἱ Ῥωμαῖοι μᾶλλον ἐπέβαινον εἰς τὸ πρόσθεν. ἅμα δὲ τοῖς μὲν Ῥωμαίοις ἑπομένων καὶ παρακαλούντων τῶν κατόπιν, τοῖς δὲ μισθοφόροις τῶν Καρχηδονίων οὐ συνεγγιζόντων οὐδὲ παραβοηθούντων, ἀλλ’ ἀποδειλιώντων ταῖς ψυχαῖς, πέρας ἐνέκλιναν οἱ βάρβαροι, καὶ δόξαντες ἐγκαταλείπεσθαι προφανῶς ὑπὸ τῶν ἰδίων, ἐπιπεσόντες κατὰ τὴν ἀποχώρησιν εἰς τοὺς ἐφεστῶτας ἔκτεινον τούτους. ὃ καὶ πολλοὺς ἠνάγκασε τῶν Καρχηδονίων ἀνδρωδῶς ἀποθανεῖν· φονευόμενοι γὰρ ὑπὸ τῶν μισθοφόρων ἐμάχοντο παρὰ τὴν αὑτῶν προαίρεσιν ἅμα πρός τε τοὺς ἰδίους καὶ πρὸς τοὺς Ῥωμαίους. ποιούμενοι δὲ τὸν κίνδυνον ἐκστατικῶς καὶ παρηλλαγμένως οὐκ ὀλίγους διέφθειραν καὶ τῶν ἰδίων καὶ τῶν ὑπεναντίων. καὶ δὴ τῷ τοιούτῳ τρόπῳ συνέχεαν ἐπιπεσόντες τὰς τῶν ἁστάτων σημαίας· οἱ μέντοι τῶν πριγκίπων ἡγεμόνες συνθεασάμενοι τὸ γεγονὸς ἐπέστησαν τὰς αὑτῶν τάξεις. τῶν δὲ μισθοφόρων καὶ τῶν Καρχηδονίων τὸ πλεῖστον μέρος τὸ μὲν ὑφ’ αὑτῶν, τὸ δ’ ὑπὸ τῶν ἁστάτων αὐτοῦ κατεκόπη. τοὺς δὲ διασῳζομένους καὶ φεύγοντας οὐκ εἴασε καταμιγῆναι ταῖς δυνάμεσιν Ἀννίβας, ἀλλὰ προβαλέσθαι παραγγείλας τοῖς ἐπιστάταις ἐκώλυσε μὴ παραδέξασθαι τοὺς ἐγγίζοντας. ὅθεν ἠναγκάσθησαν οὗτοι μὲν ποιεῖσθαι τὴν ἀποχώρησιν ἐπὶ τὰ κέρατα καὶ τὰς ἐκ τούτων", "st": "15.13"}, {"sp": "N", "t": "εὐρυχωρίας, γενομένου δὲ τοῦ μεταξὺ τόπου τῶν καταλειπομένων στρατοπέδων πλήρους αἵματος, φόνου, νεκρῶν, πολλὴν ἀπορίαν παρεῖχε τῷ τῶν Ῥωμαίων στρατηγῷ τὸ τῆς τροπῆς ἐμπόδιον· ὅ τε γὰρ τῶν νεκρῶν ὄλισθος, ὡς ἂν αἱμοφύρτων καὶ σωρηδὸν πεπτωκότων, ἥ τε τῶν χύδην ἐρριμμένων ὅπλων ὁμοῦ τοῖς πτώμασιν ἀλογία δυσχερῆ τὴν δίοδον ἔμελλε ποιήσειν τοῖς ἐν τάξει διαπορευομένοις. οὐ μὴν ἀλλὰ τοὺς μὲν τραυματίας εἰς τοὐπίσω τῆς παρατάξεως κομισάμενος, τοὺς δ’ ἐπιδιώκοντας τῶν ἁστάτων ἀνακαλεσάμενος διὰ τῆς σάλπιγγος, τοὺς μὲν αὐτοῦ πρὸ τῆς μάχης κατὰ μέσους τοὺς πολεμίους ἐπέστησε, τοὺς δὲ πρίγκιπας καὶ τριαρίους πυκνώσας ἐφ’ ἑκάτερον τὸ κέρας προάγειν παρήγγειλε διὰ τῶν νεκρῶν. ἐπειδὴ δ’ ὑπερβάντες ἐξ ἴσου τοῖς ἁστάτοις ἐγένοντο, συνέβαλον αἱ φάλαγγες ἀλλήλαις μετὰ τῆς μεγίστης ὁρμῆς καὶ προθυμίας. ὄντων δὲ καὶ τῷ πλήθει καὶ τοῖς φρονήμασι καὶ ταῖς ἀρεταῖς καὶ τοῖς καθοπλισμοῖς παραπλησίων ἀμφοτέρων, ἄκριτον ἐπὶ πολὺ συνέβαινε γενέσθαι τὴν μάχην, ἐν αὐταῖς ταῖς χώραις ἐναποθνησκόντων τῶν ἀνδρῶν διὰ φιλοτιμίαν, ἕως οἱ περὶ τὸν Μασαννάσαν καὶ Λαίλιον ἀπὸ τοῦ διώγματος τῶν ἱππέων ἀνακάμπτοντες [καὶ] δαιμονίως εἰς δέοντα καιρὸν συνῆψαν. ὧν προσπεσόντων τοῖς περὶ τὸν Ἀννίβαν κατόπιν οἱ μὲν πλεῖστοι κατεκόπησαν ἐν τῇ τάξει, τῶν δὲ πρὸς φυγὴν ὁρμησάντων ὀλίγοι μὲν τελέως διέφυγον, ἅτε τῶν ἱππέων ἐν χερσὶν ὄντων καὶ τῶν τόπων ἐπιπέδων ὑπαρχόντων. ἔπεσον δὲ τῶν μὲν Ῥωμαίων ὑπὲρ τοὺς χιλίους πεντακοσίους, τῶν δὲ Καρχηδονίων ὑπὲρ δισμυρίους, αἰχμάλωτοι δ’ ἑάλωσαν οὐ πολὺ τούτων ἐλάττους.", "st": "15.14"}, {"sp": "N", "t": "ἡ μὲν οὖν ἐπὶ πᾶσι γενομένη μάχη καὶ τὰ ὅλα κρίνασα Ῥωμαίοις διὰ τῶν προειρημένων ἡγεμόνων τοιοῦτον ἔσχε τὸ τέλος· μετὰ δὲ τὴν μάχην Πόπλιος μὲν ἐπακολουθήσας καὶ διαρπάσας τὸν χάρακα τῶν Καρχηδονίων αὖτις ἀνεχώρησεν εἰς τὴν ἰδίαν παρεμβολήν. Ἀννίβας δὲ μετ’ ὀλίγων ἱππέων κατὰ τὸ συνεχὲς ποιούμενος τὴν ἀναχώρησιν εἰς Ἀδρύμητα διεσώθη, πάντα τὰ δυνατὰ ποιήσας κατὰ τὸν κίνδυνον, ὅσα τὸν ἀγαθὸν ἔδει στρατηγὸν καὶ πολλῶν ἤδη πραγμάτων πεῖραν εἰληφότα. πρῶτον μὲν γὰρ εἰς λόγους συνελθὼν ἐπειράθη δι’ αὑτοῦ λύσιν ποιήσασθαι τῶν ἐνεστώτων· τοῦτο δ’ ἐστὶ τοῦ προειδότος τὰ κατορθώματα, ἀλλ’ ἀπιστοῦντος τῇ τύχῃ καὶ προορωμένου τὰ περὶ τὰς μάχας ἐκβαίνοντα παράλογα. μετὰ δὲ ταῦτα συγκαταστὰς εἰς τὸν κίνδυνον οὕτως ἐχρήσατο τοῖς πράγμασιν ὥστε μὴ δυνατὸν εἶναι βέλτιον πρὸς Ῥωμαίους ἀγῶνα συστήσασθαι, παραπλησίῳ καθοπλισμῷ χρώμενον, οὗ τότε συνεστήσατ’ Ἀννίβας. οὔσης γὰρ δυσδιασπάστου τῆς Ῥωμαίων τάξεως καὶ δυνάμεως, τὸν ἄνδρα συνέβη καὶ καθόλου καὶ κατὰ μέρη μάχεσθαι πρὸς πάσας τὰς ἐπιφανείας διὰ τῆς μιᾶς ἐκτάξεως, ἀεὶ τῶν ἔγγιστα τῷ δεινῷ σημαιῶν συνεπιστρεφουσῶν πρὸς τὸ δεόμενον. ἔτι δὲ τοῦ καθοπλισμοῦ σκέπην καὶ θράσος παρασκευάζοντος καὶ διὰ τὸ μέγεθος τοῦ θυρεοῦ καὶ τὴν τῆς μαχαίρας ὑπομονὴν τῶν πληγῶν, δύσμαχοι γίνονται καὶ δυσκαταγώνιστοι διὰ τὰς προειρημένας αἰτίας.", "st": "15.15"}, {"sp": "N", "t": "ἀλλ’ ὅμως πρὸς ἕκαστα τούτων οὕτως ἐνδεχομένως Ἀννίβας ἐκ τῶν κατὰ λόγον ἡρμόσατο παρ’ αὐτὸν τὸν καιρὸν ὥσθ’ ὑπερβολὴν μὴ καταλιπεῖν. τὸ μὲν γὰρ τῶν ἐλεφάντων πλῆθος ἐξ αὐτῆς παρεσκευάσατο καὶ τότε προεβάλετο χάριν τοῦ συνταράξαι καὶ διασπάσαι τὰς τάξεις τῶν ὑπεναντίων· τοὺς δὲ μισθοφόρους προέταξε καὶ τοὺς Καρχηδονίους ἔθηκε μετὰ τούτους ἕνεκα τοῦ προεκλῦσαι μὲν τῷ κόπῳ τὰ σώματα τῶν πολεμίων, ἀχρειῶσαι δὲ τὰς ἀκμὰς τῶν ὅπλων διὰ τὸ πλῆθος τῶν φονευομένων, ἀναγκάσαι δὲ τοὺς Καρχηδονίους μέσους ὄντας μένειν καὶ μάχεσθαι κατὰ τὸν ποιητὴν ὄφρα καὶ οὐκ ἐθέλων τις ἀναγκαίῃ πολεμίζοι. τοὺς δὲ μαχιμωτάτους καὶ στασιμωτάτους τῶν ἀνδρῶν ἐν ἀποστάσει παρενέβαλε χάριν τοῦ προορωμένους ἐκ πολλοῦ τὸ συμβαῖνον καὶ διαμένοντας ἀκεραίους τοῖς τε σώμασι καὶ ταῖς ψυχαῖς σὺν καιρῷ χρήσασθαι ταῖς σφετέραις ἀρεταῖς. εἰ δὲ πάντα τὰ δυνατὰ ποιήσας πρὸς τὸ νικᾶν ἐσφάλη τὸν πρὸ τούτου χρόνον ἀήττητος ὤν, συγγνώμην δοτέον· ἔστι μὲν γὰρ ὅτε καὶ ταὐτόματον ἀντέπραξε ταῖς ἐπιβολαῖς τῶν ἀγαθῶν ἀνδρῶν, ἔστι δ’ ὅτε πάλιν κατὰ τὴν παροιμίαν ἐσθλὸς ἐὼν ἄλλου κρείττονος ἀντέτυχεν· ὃ δὴ καὶ τότε γεγονέναι περὶ ἐκεῖνον φήσειεν ἄν τις. —", "st": "15.16"}, {"sp": "N", "t": "τὰ γὰρ ὑπεραίροντα τὴν κοινὴν συνήθειαν τῶν παρ’ ἐνίοις ἐθισμῶν, ὅταν μὲν αὐτοπαθῶς δόξῃ γίνεσθαι διὰ τὸ μέγεθος τῶν συμπτωμάτων, ἔλεον ἐκκαλεῖται παρὰ τοῖς ὁρῶσι καὶ τοῖς ἀκούουσι, καὶ συγκινεῖ πως ἕκαστον ἡμῶν ὁ ξενισμός· ἐπὰν δὲ φαίνηται γοητείας χάριν καὶ καθ’ ὑπόκρισιν γίνεσθαι τὸ τοιοῦτον, οὐκ ἔλεον, ἀλλ’ ὀργὴν ἐξεργάζεται καὶ μῖσος. ὃ καὶ τότε συνέβη γενέσθαι περὶ τοὺς πρεσβευτὰς τῶν Καρχηδονίων. — ὁ δὲ Πόπλιος διὰ βραχέων ἤρξατο λέγειν πρὸς αὐτούς, ὡς ἐκείνων μὲν χάριν οὐδὲν ὀφείλουσι ποιεῖν φιλάνθρωπον, ὁμολογούντων αὐτῶν διότι καὶ τὸν πόλεμον ἐξ ἀρχῆς ἐπενέγκαιεν Ῥωμαίοις, παρὰ τὰς συνθήκας ἐξανδραποδισάμενοι τὴν Ζακανθαίων πόλιν, καὶ πρῴην παρασπονδήσαιεν, ἀθετήσαντες τοὺς ὅρκους καὶ τὰς ἐγγράπτους ὁμολογίας· αὑτῶν δὲ χάριν ἔφησε καὶ τῆς τύχης καὶ τῶν ἀνθρωπίνων κεκρίσθαι σφίσι πρᾴως χρῆσθαι καὶ μεγαλοψύχως τοῖς πράγμασι. φανήσεσθαι δὲ τοῦτο κἀκείνοις ἔφησεν, ἐὰν ὀρθῶς διαλαμβάνωσι περὶ τῶν ἐνεστώτων· οὐ γὰρ εἴ τι πάσχειν ἢ ποιεῖν ἢ διδόναι σφίσιν ἐπιταχθήσεται, τοῦτο δεῖν νομίζειν δεινόν, ἀλλ’ εἴ τι συγχωρηθήσεται φιλάνθρωπον, τοῦτο μᾶλλον ἡγεῖσθαι παράδοξον, ἐπείπερ ἡ τύχη παρελομένη τὸν ἔλεον αὐτῶν καὶ τὴν συγγνώμην διὰ τὴν σφετέραν ἀδικίαν ὑποχειρίους πεποίηκε τοῖς ἐχθροῖς. ταῦτα δ’ εἰπὼν ἔλεγε τὰ φιλάνθρωπα τὰ διδόμενα, καὶ πάλιν ἃ δέον ἦν ὑπομένειν αὐτούς.", "st": "15.17"}, {"sp": "N", "t": "ἦν δὲ τὰ κεφάλαια τῶν προτεινομένων ταῦτα. πόλεις ἔχειν κατὰ Λιβύην ἃς καὶ πρότερον εἶχον ἢ τὸν τελευταῖον πόλεμον ἐξενεγκεῖν Ῥωμαίοις, καὶ χώραν ἣν καὶ τὸ παλαιὸν εἶχον, κτήνη καὶ σώματα καὶ τὴν ἄλλην ὕπαρξιν, ἀπὸ δὲ τῆς ἡμέρας ἐκείνης ἀσινεῖς Καρχηδονίους ὑπάρχειν, ἔθεσι καὶ νόμοις χρῆσθαι τοῖς ἰδίοις, ἀφρουρήτους ὄντας. ταῦτα μὲν οὖν ἦν τὰ φιλάνθρωπα, τὰ δ’ ἐναντία τούτοις πάλιν τὰ κατὰ τὰς ἀνοχὰς ἀδικήματα γενόμενα πάντα Καρχηδονίους ἀποκαταστῆσαι Ῥωμαίοις, τοὺς αἰχμαλώτους καὶ δραπέτας ἐκ παντὸς ἀποδοῦναι τοῦ χρόνου, τὰ μακρὰ πλοῖα παραδοῦναι πάντα πλὴν δέκα τριήρων, ὁμοίως καὶ πάντας τοὺς ἐλέφαντας. πόλεμον μηδενὶ τῶν ἔξω τῆς Λιβύης ἐπιφέρειν καθόλου μηδὲ τῶν ἐν τῇ Λιβύῃ χωρὶς τῆς Ῥωμαίων γνώμης· οἰκίας καὶ χώραν καὶ πόλεις, καὶ εἴ τι ἕτερόν ἐστι Μασαννάσου τοῦ βασιλέως ἢ τῶν προγόνων ἐντὸς τῶν ἀποδειχθησομένων ὅρων αὐτοῖς πάντα ἀποδοῦναι Μασαννάσᾳ· σιτομετρῆσαί τε τὴν δύναμιν τριμήνου καὶ μισθοδοτῆσαι μέχρι ἂν ἐκ Ῥώμης ἀντιφωνηθῇ τι κατὰ τὰς συνθήκας· ἐξενεγκεῖν ἀργυρίου τάλαντα μύρια Καρχηδονίους ἐν ἔτεσι πεντήκοντα, φέροντας καθ’ ἕκαστον ἐνιαυτὸν Εὐβοϊκὰ τάλαντα διακόσια· ὁμήρους δοῦναι πίστεως χάριν ἑκατὸν οὓς ἂν προγράψῃ τῶν νέων ὁ στρατηγὸς τῶν Ῥωμαίων, μὴ νεωτέρους τετταρεσκαίδεκα ἐτῶν μηδὲ πρεσβυτέρους τριάκοντα.", "st": "15.18"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὁ στρατηγὸς εἶπε τῶν Ῥωμαίων τοῖς πρεσβευταῖς· οἱ δ’ ἀκούσαντες ἠπείγοντο καὶ διεσάφουν τοῖς ἐν τῇ πατρίδι. καθ’ ὃν δὴ καιρὸν λέγεται, μέλλοντός τινος τῶν ἐκ τῆς γερουσίας ἀντιλέγειν τοῖς προτεινομένοις καὶ καταρχομένου, προελθόντα τὸν Ἀννίβαν κατασπάσαι τὸν ἄνθρωπον ἀπὸ τοῦ βήματος. τῶν δὲ λοιπῶν ἐξοργισθέντων διὰ τὸ παρὰ τὴν συνήθειαν αὐτὸν τοῦτο πρᾶξαι, πάλιν τὸν Ἀννίβαν ἀναστάντα φασὶν ἀγνοεῖν μὲν ὁμολογῆσαι, δεῖν δὲ συγγνώμην ἔχειν, εἴ τι παρὰ τοὺς ἐθισμοὺς πράττει, γινώσκοντας ὅτι τὴν μὲν ἔξοδον ἐκ τῆς πατρίδος ἐνναέτης ὢν ποιήσαιτο, πλείω δὲ τῶν πέντε καὶ τετταράκοντ’ ἐτῶν ἔχων εἰς αὐτὴν ἐπανήκει. διόπερ ἠξίου μὴ τοῦτο σκοπεῖν, εἴ τι παραπέπαικε τῆς συνηθείας, πολὺ δὲ μᾶλλον, εἰ τοῖς τῆς πατρίδος πράγμασιν ἀληθινῶς συμπάσχει· διὰ γὰρ ταῦτα καὶ νῦν εἰς τὴν ἀλογίαν ἐμπεπτωκένει ταύτην. θαυμαστὸν γὰρ αὐτῷ φανῆναι καὶ τελέως ἐξηλλαγμένον, εἴ τις ὑπάρχων Καρχηδόνιος καὶ συνειδὼς τὰ βεβουλευμένα καὶ κοινῇ τῇ πατρίδι καὶ κατ’ ἰδίαν ἑκάστοις ἡμῶν κατὰ Ῥωμαίων οὐ προσκυνεῖ τὴν τύχην, εἰ γεγονὼς ὑποχείριος τοιούτων τυγχάνει φιλανθρώπων· οὓς εἴ τις ὀλίγαις πρότερον ἡμέραις ἤρετο πόσ’ ἐλπίζουσι πείσεσθαι τὴν πατρίδα κρατησάντων Ῥωμαίων, οὐδ’ ἂν εἰπεῖν οἷοί τ’ ἦσαν διὰ τὸ μέγεθος καὶ τὴν ὑπερβολὴν τῶν προφαινομένων αὐτοῖς κακῶν. διόπερ ἠξίου καὶ νῦν μηδ’ ἐπὶ λόγον ἄγειν, ἀλλ’ ὁμοθυμαδὸν δεξαμένους τὰ προτεινόμενα θύειν τοῖς θεοῖς, καὶ πάντας εὔχεσθαι βεβαιῶσαι ταῦτα τὸν δῆμον τῶν Ῥωμαίων. φανέντος δὲ φρονίμως αὐτοῦ καὶ τοῖς καιροῖς οἰκείως συμβουλεύειν, ἔδοξε ποιεῖσθαι τὰς συνθήκας ἐπὶ τοῖς προειρημένοις. καὶ τὸ μὲν συνέδριον παραυτίκα πρεσβευτὰς ἐξέπεμπε τοὺς ἀνθομολογησομένους ὑπὲρ τούτων.", "st": "15.19"}, {"sp": "N", "t": "τοῦτο δὲ τίς οὐκ ἂν θαυμάσειε, πῶς, ὅτε μὲν αὐτὸς ὁ Πτολεμαῖος ζῶν οὐ προσεδεῖτο τῆς τούτων ἐπικουρίας, ἕτοιμοι βοηθεῖν ἦσαν, ὅτε δ’ ἐκεῖνος μετήλλαξε καταλιπὼν παιδίον νήπιον, ᾧ κατὰ φύσιν ἀμφοῖν ἐπέβαλλε συσσῴζειν τὴν βασιλείαν, τότε παρακαλέσαντες ἀλλήλους ὥρμησαν ἐπὶ τὸ διελόμενοι τὴν τοῦ παιδὸς ἀρχὴν ἐπανελέσθαι τὸν ἀπολελειμμένον, οὐδ’ οὖν, καθάπερ οἱ τύραννοι, βραχεῖαν δή τινα προβαλλόμενοι τῆς αἰσχύνης πρόφασιν, ἀλλ’ ἐξ αὐτῆς ἀνέδην καὶ θηριωδῶς οὕτως ὥστε προσοφλεῖν τὸν λεγόμενον τῶν ἰχθύων βίον, ἐν οἷς φασιν ὁμοφύλοις οὖσι τὴν τοῦ μείονος ἀπώλειαν τῷ μείζονι τροφὴν γίνεσθαι καὶ βίον. ἐξ ὧν τίς οὐκ ἂν ἐμβλέψας οἷον εἰς κάτοπτρον εἰς τὴν συνθήκην ταύτην αὐτόπτης δόξειε γίνεσθαι τῆς πρὸς τοὺς θεοὺς ἀσεβείας καὶ τῆς πρὸς τοὺς ἀνθρώπους ὠμότητος, ἔτι δὲ τῆς ὑπερβαλλούσης πλεονεξίας τῶν προειρημένων βασιλέων; οὐ μὴν ἀλλὰ τίς οὐκ ἂν εἰκότως τῇ τύχῃ μεμψάμενος ἐπὶ τῶν ἀνθρωπείων πραγμάτων ἐν τούτοις ἀντικαταλλαγείη, διότι ἐκείνοις μὲν ἐπέθηκε μετὰ ταῦτα τὴν ἁρμόζουσαν δίκην, τοῖς δ’ ἐπιγενομένοις ἐξέθηκε κάλλιστον ὑπόδειγμα πρὸς ἐπανόρθωσιν τὸν τῶν προειρημένων βασιλέων παραδειγματισμόν; ἔτι γὰρ αὐτῶν παρασπονδούντων μὲν ἀλλήλους, διασπωμένων δὲ τὴν τοῦ παιδὸς ἀρχήν, ἐπιστήσασα Ῥωμαίους, ἁκεῖνοι κατὰ τῶν πέλας ἐβουλεύσαντο παρανόμως, ταῦτα κατ’ ἐκείνων δικαίως ἐκύρωσε καὶ καθηκόντως. παραυτίκα γὰρ ἑκάτεροι διὰ τῶν ὅπλων ἡττηθέντες οὐ μόνον ἐκωλύθησαν τῆς τῶν ἀλλοτρίων ἐπιθυμίας, ἀλλὰ καὶ συγκλεισθέντες εἰς φόρους ὑπέμειναν Ῥωμαίοις τὸ προσταττόμενον ποιεῖν. τὸ τελευταῖον ἐν πάνυ βραχεῖ χρόνῳ τὴν μὲν Πτολεμαίου βασιλείαν ἡ τύχη διώρθωσε, τὰς δὲ τούτων δυναστείας καὶ τοὺς διαδόχους τοὺς μὲν ἄρδην ἀναστάτους ἐποίησε καὶ πανωλέθρους, τοὺς δὲ μικροῦ δεῖν τοῖς αὐτοῖς περιέβαλε συμπτώμασι. —", "st": "15.20"}, {"sp": "N", "t": "ὅτι Μολπαγόρας τις ἦν παρὰ τοῖς Κιανοῖς, ἀνὴρ καὶ λέγειν καὶ πράττειν ἱκανός, κατὰ δὲ τὴν αἵρεσιν δημαγωγικὸς καὶ πλεονέκτης. ὃς πρὸς χάριν ὁμιλῶν τῷ πλήθει καὶ τοὺς εὐκαιροῦντας τοῖς βίοις ὑποβάλλων τοῖς ὄχλοις, καὶ τινὰς μὲν εἰς τέλος ἀναιρῶν, τινὰς δὲ φυγαδεύων καὶ τὰς οὐσίας τὰς τούτων δημεύων καὶ διαδιδοὺς τοῖς πολλοῖς, ταχέως τῷ τοιούτῳ τρόπῳ περιεποιήσατο μοναρχικὴν ἐξουσίαν. — Κιανοὶ μὲν οὖν περιέπεσον τηλικαύταις συμφοραῖς οὐχ οὕτως διὰ τὴν τύχην οὐδὲ διὰ τὴν τῶν πέλας ἀδικίαν, τὸ δὲ πλεῖον διὰ τὴν αὑτῶν ἀβουλίαν καὶ κακοπολιτείαν, προάγοντες ἀεὶ τοὺς χειρίστους καὶ κολάζοντες τοὺς ἐναντιουμένους τούτοις, ἵνα διαιρῶνται τὰς ἀλλήλων οὐσίας, εἰς ταύτας οἷον ἐθελοντὴν ἐνέπεσον τὰς ἀτυχίας, εἰς ἃς οὐκ οἶδ’ ὅπως πάντες ἄνθρωποι προφανῶς ἐμπίπτοντες οὐ δύνανται λῆξαι τῆς ἀνοίας, ἀλλ’ οὐδὲ βραχὺ διαπιστῆσαι [ῥᾴδιον], καθάπερ ἔνια τῶν ἀλόγων ζῴων. ἐκεῖνα γὰρ οὐ μόνον ἐὰν αὐτά που δυσχρηστήσῃ περὶ τὰ δελέατα καὶ τὰς ἄρκυς, ἀλλὰ κἂν ἕτερον ἴδῃ κινδυνεῦον, οὐκ ἂν ἔτι ῥᾳδίως αὐτὰ προσαγάγοις πρὸς οὐδὲν τῶν τοιούτων, ἀλλὰ καὶ τὸν τόπον ὑποπτεύει καὶ παντὶ τῷ φαινομένῳ διαπιστεῖ. οἱ δ’ ἄνθρωποι τὰς μὲν ἀκούοντες ἀπολλυμένας πόλεις ἄρδην τῷ προειρημένῳ τρόπῳ, τὰς δ’ ἀκμὴν ὁρῶντες, ὅμως, ὅταν τις χρησάμενος τῷ πρὸς χάριν λόγῳ προτείνῃ τὴν ἐλπίδα τῆς ἐξ ἀλλήλων ἐπανορθώσεως, προσίασι πρὸς τὸ δέλεαρ ἀνεπιστάτως, σαφῶς εἰδότες ὅτι τῶν τὰ τοιαῦτα δελέατα καταπιόντων οὐδεὶς οὐδέποτε σέσωσται, πᾶσι δ’ ὁμολογουμένως ὄλεθρον ἐπήνεγκαν αἱ τοιαῦται πολιτεῖαι.", "st": "15.21"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος κύριος γενόμενος τῆς πόλεως περιχαρὴς ἦν, ὡς καλήν τινα καὶ σεμνὴν πρᾶξιν ἐπιτετελεσμένος καὶ βεβοηθηκὼς μὲν προθύμως τῷ κηδεστῇ, καταπεπληγμένος δὲ πάντας τοὺς ἀλλοτριάζοντας, σωμάτων δὲ καὶ χρημάτων εὐπορίαν ἐκ τοῦ δικαίου περιπεποιημένος. τὰ δ’ ἐναντία τούτοις οὐ καθεώρα, καίπερ ὄντα προφανῆ, πρῶτον μὲν ὡς οὐκ ἀδικουμένῳ, παρασπονδοῦντι δὲ τῷ κηδεστῇ τοὺς πέλας ἐβοήθει, δεύτερον ὅτι πόλιν Ἑλληνίδα περιβαλὼν τοῖς μεγίστοις ἀτυχήμασιν ἀδίκως ἔμελλε κυρώσειν τὴν περὶ αὐτοῦ διαδεδομένην φήμην ὑπὲρ τῆς εἰς τοὺς φίλους ὠμότητος, ἐξ ἀμφοῖν δὲ δικαίως καὶ κληρονομήσειν παρὰ πᾶσι τοῖς Ἕλλησι τὴν ἐπ’ ἀσεβείᾳ δόξαν, τρίτον ὡς ἐνυβρίκει τοῖς ἀπὸ τῶν προειρημένων πόλεων πρεσβευταῖς, οἳ παρῆσαν ἐξελούμενοι τοὺς Κιανοὺς ἐκ τῶν περιεστώτων κακῶν, ὑπὸ δ’ ἐκείνου παρακαλούμενοι καὶ διαγελώμενοι καθ’ ἡμέραν ἠναγκάσθησαν αὐτόπται γενέσθαι τούτων, ὧν ἥκιστ’ ἂν ἐβουλήθησαν, πρὸς δὲ τούτοις ὅτι τοὺς Ῥοδίους οὕτως ἀπετεθηριώκει τότε πρὸς αὑτὸν ὥστε μηδένα λόγον ἔτι προσίεσθαι περὶ Φιλίππου.", "st": "15.22"}, {"sp": "N", "t": "καὶ γὰρ ἡ τύχη πρός γε τοῦτο τὸ μέρος αὐτῷ συνήργησε προφανῶς. ὅτε γὰρ ὁ πρεσβευτὴν ἐν τῷ θεάτρῳ τὸν ἀπολογισμὸν ἐποιεῖτο πρὸς τοὺς Ῥοδίους, ἐμφανίζων τὴν τοῦ Φιλίππου μεγαλοψυχίαν, καὶ διότι τρόπον τινὰ κρατῶν ἤδη τῆς πόλεως δίδωσι τῷ δήμῳ τὴν χάριν ταύτην, ποιεῖ δὲ τοῦτο βουλόμενος ἐλέγξαι μὲν τὰς τῶν ἀντιπραττόντων αὐτῷ διαβολάς, φανερὰν δὲ τῇ πόλει καταστῆσαι τὴν αὑτοῦ προαίρεσιν· καὶ παρῆν τις ἐκ κατάπλου πρὸς τὸ πρυτανεῖον ἀναγγέλλων τὸν ἐξανδραποδισμὸν τῶν Κιανῶν καὶ τὴν ὠμότητα τοῦ Φιλίππου τὴν ἐν τούτοις γεγενημένην, ὥστε τοὺς Ῥοδίους, ἔτι μεταξὺ τοῦ πρεσβευτοῦ τὰ προειρημένα λέγοντος, ἐπεὶ προελθὼν ὁ πρύτανις διεσάφει τὰ προσηγγελμένα, μὴ δύνασθαι πιστεῦσαι διὰ τὴν ὑπερβολὴν τῆς ἀθεσίας. Φίλιππος μὲν οὖν, παρασπονδήσας οὐχ οὕτως Κιανοὺς ὡς ἑαυτόν, εἰς τοιαύτην ἄγνοιαν ἢ καὶ παράπτωσιν τοῦ καθήκοντος ἧκεν ὥστ’ ἐφ’ οἷς ἐχρῆν αἰσχύνεσθαι καθ’ ὑπερβολήν, ἐπὶ τούτοις ὡς καλοῖς σεμνύνεσθαι καὶ μεγαλαυχεῖν· ὁ δὲ τῶν Ῥοδίων δῆμος ἀπὸ ταύτης τῆς ἡμέρας ὡς περὶ πολεμίου διελάμβανε τοῦ Φιλίππου, καὶ πρὸς τοῦτον τὸν σκοπὸν ἐποιεῖτο τὰς παρασκευάς. παραπλήσιον δὲ καὶ τοῖς Αἰτωλοῖς μῖσος ἐκ ταύτης τῆς πράξεως ἐνειργάσατο πρὸς αὑτόν· ἄρτι γὰρ διαλελυμένος καὶ τὰς χεῖρας ἐκτείνων πρὸς τὸ ἔθνος, οὐδεμιᾶς προφάσεως ἐγγινομένης, φίλων ὑπαρχόντων καὶ συμμάχων Αἰτωλῶν, Λυσιμαχέων, Καλχηδονίων, Κιανῶν, βραχεῖ χρόνῳ πρότερον, πρῶτον μὲν προσηγάγετο τὴν Λυσιμαχέων πόλιν, ἀποσπάσας ἀπὸ τῆς τῶν Αἰτωλῶν συμμαχίας, δευτέραν δὲ τὴν Καλχηδονίων, τρίτην δὲ τὴν Κιανῶν ἐξηνδραποδίσατο, στρατηγοῦ παρ’ Αἰτωλῶν ἐν αὐτῇ διατρίβοντος καὶ προεστῶτος τῶν κοινῶν. Προυσίας δέ, καθὸ μὲν ἡ πρόθεσις αὐτοῦ συντελείας ἔτυχε, περιχαρὴς ἦν, καθὸ δὲ τὰ μὲν ἆθλα τῆς ἐπιβολῆς ἕτερος ἀπέφερεν, αὐτὸς δὲ πόλεως οἰκόπεδον ἔρημον ἐκληρονόμει, δυσχερῶς διέκειτο, ποιεῖν δ’ οὐδὲν οἷός τ’ ἦν. —", "st": "15.23"}, {"sp": "N", "t": "ὅτι Φίλιππος κατὰ τὸν ἀνάπλουν ἕτερον ἐφ’ ἑτέρῳ παρασπόνδημα μεταχειριζόμενος προσέσχε περὶ μέσον ἡμέρας πρὸς τὴν τῶν Θασίων πόλιν, καὶ ταύτην φιλίαν οὖσαν ἐξηνδραποδίσατο. — Θάσιοι εἶπον πρὸς Μητρόδωρον τὸν Φιλίππου στρατηγὸν παραδοῦναι τὴν πόλιν εἰ διατηρήσοι αὐτοὺς ἀφρουρήτους, ἀφορολογήτους, ἀνεπισταθμεύτους, νόμοις χρῆσθαι τοῖς ἰδίοις. — συγχωρεῖν τὸν βασιλέα Θασίους ἀφρουρήτους, ἀφορολογήτους, ἀνεπισταθμεύτους, νόμοις χρῆσθαι τοῖς ἰδίοις. ἐπισημηναμένων δὲ μετὰ κραυγῆς πάντων τὰ ῥηθέντα παρήγαγον τὸν Φίλιππον εἰς τὴν πόλιν. — ἴσως μὲν γὰρ πάντες οἱ βασιλεῖς κατὰ τὰς πρώτας ἀρχὰς πᾶσι προτείνουσι τὸ τῆς ἐλευθερίας ὄνομα καὶ φίλους προσαγορεύουσι καὶ συμμάχους τοὺς κοινωνήσαντας σφίσι τῶν αὐτῶν ἐλπίδων, καθικόμενοι δὲ τῶν πράξεων παρὰ πόδας οὐ συμμαχικῶς, ἀλλὰ δεσποτικῶς χρῶνται τοῖς πιστεύσασι· διὸ καὶ τοῦ μὲν καλοῦ διαψεύδονται, τοῦ δὲ παραυτὰ συμφέροντος ὡς ἐπίπαν οὐκ ἀποτυγχάνουσι· τὸ δ’ ἐπιβαλλόμενον τοῖς μεγίστοις καὶ περιλαμβάνοντα ταῖς ἐλπίσι τὴν οἰκουμένην καὶ πάσας ἀκμὴν ἀκεραίους ἔχοντα τὰς ἐπιβολὰς εὐθέως ἐν τοῖς ἐλαχίστοις καὶ πρώτοις τῶν ὑποπιπτόντων ἐπικηρύττειν ἅπασι τὴν ἀθεσίαν αὑτοῦ καὶ τὴν ἀβεβαιότητα πῶς οὐκ ἂν δόξειεν ἀλόγιστον εἶναι καὶ μανικόν;", "st": "15.24"}, {"sp": "N", "t": "ὅτι ἐπεὶ πάσας καθ’ ἕκαστον ἔτος τὰς κατάλληλα πράξεις γενομένας κατὰ τὴν οἰκουμένην ἐξηγούμεθα, δῆλον ὡς ἀναγκαῖόν ἐστι τὸ τέλος ἐπ’ ἐνίων πρότερον ἐκφέρειν τῆς ἀρχῆς, ἐπειδὰν πρότερος ὁ τόπος ὑποπέσῃ κατὰ τὸν τῆς ὅλης ὑποθέσεως μερισμὸν καὶ κατὰ τὴν τῆς διηγήσεως ἔφοδον ὁ τὴν συντέλειαν τῆς πράξεως ἔχων τοῦ τὴν ἀρχὴν καὶ τὴν ἐπιβολὴν περιέχοντος. —", "st": "15.24a"}, {"sp": "N", "t": "ὅτι Σωσίβιος ὁ ψευδεπίτροπος Πτολεμαίου ἐδόκει γεγονέναι σκεῦος ἀγχίνουν καὶ πολυχρόνιον, ἔτι δὲ κακοποιὸν ἐν βασιλείᾳ, καὶ πρώτῳ μὲν ἀρτῦσαι φόνον Λυσιμάχῳ, ὃς ἦν υἱὸς Ἀρσινόης τῆς Λυσιμάχου καὶ Πτολεμαίου, δευτέρῳ δὲ Μάγᾳ τῷ Πτολεμαίου καὶ Βερενίκης τῆς Μάγα, τρίτῃ δὲ Βερενίκῃ τῇ Πτολεμαίου μητρὶ τοῦ Φιλοπάτορος, τετάρτῳ Κλεομένει τῷ Σπαρτιάτῃ, πέμπτῃ θυγατρὶ Βερενίκης Ἀρσινόῃ. — μετὰ δ’ ἡμέρας τρεῖς ἢ τέτταρας ἐν τῷ μεγίστῳ περιστύλῳ τῆς αὐλῆς οἰκοδομήσαντες βῆμα συνεκάλεσαν τοὺς ὑπασπιστὰς καὶ τὴν θεραπείαν, ἅμα δὲ τούτοις τοὺς πεζῶν καὶ τοὺς ἱππέων ἡγεμόνας. ἁθροισθέντων δὲ τούτων ἀναβὰς Ἀγαθοκλῆς καὶ Σωσίβιος ἐπὶ τὸ βῆμα πρῶτον μὲν τὸν τοῦ βασιλέως καὶ τὸν τῆς βασιλίσσης θάνατον ἀνθωμολογήσαντο καὶ τὸ πένθος ἀνέφηναν τοῖς πολλοῖς κατὰ τὸ παρ’ αὐτοῖς ἔθος. μετὰ δὲ ταῦτα διάδημα τῷ παιδὶ περιθέντες ἀνέδειξαν βασιλέα, καὶ διαθήκην τινὰ παρανέγνωσαν πεπλασμένην, ἐν ᾗ γεγραμμένον ἦν ὅτι καταλείπει τοῦ παιδὸς ἐπιτρόπους ὁ βασιλεὺς Ἀγαθοκλέα καὶ Σωσίβιον· καὶ παρεκάλουν τοὺς ἡγεμόνας εὐνοεῖν καὶ διαφυλάττειν τῷ παιδὶ τὴν ἀρχήν· ἐπὶ δὲ τούτοις δύο κάλπιδας ἀργυρᾶς εἰσήνεγκαν, ὡς τῆς μὲν μιᾶς ἐχούσης τὰ τοῦ βασιλέως ὀστᾶ, τῆς δ’ ἑτέρας τὰ τῆς Ἀρσινόης· εἶχε δ’ ἡ μὲν μία κατ’ ἀλήθειαν τὰ τοῦ βασιλέως, ἡ δ’ ἑτέρα πλήρης ἦν ἀρωμάτων. ταῦτα δὲ ποιήσαντες εὐθέως ἐπετέλουν τὴν ἐκφοράν. ἐν ᾧ καιρῷ πᾶσι τὰ κατὰ τὴν Ἀρσινόην συνέβη γενέσθαι δῆλα. τοῦ γὰρ θανάτου φωτισθέντος ὁ τρόπος ἐπεζητεῖτο τῆς ἀπωλείας· οὐκ οὔσης δὲ προφάσεως ἄλλης οὐδεμιᾶς, τῆς ἀληθινῆς φήμης προσπεπτωκυίας, ἀκμὴν δ’ ἀμφισβητουμένης, τὸ κατ’ ἀλήθειαν γεγονὸς ἐν ταῖς ἑκάστων γνώμαις ἐπεσφραγίσθη. διὸ καὶ συνέβη μεγάλην γενέσθαι τὴν σύγχυσιν τῶν ὄχλων. τοῦ μὲν γὰρ βασιλέως οὐθεὶς οὐθένα λόγον ἐποιεῖτο, περὶ δὲ τῆς Ἀρσινόης, ἀνανεούμενοι τινὲς μὲν τὴν ὀρφανίαν αὐτῆς, ἔνιοι δὲ τὴν ἐξ ἀρχῆς ἐν τῷ ζῆν ὕβριν, ἣν ὑπέμεινε, καὶ τὴν αἰκίαν, σὺν δὲ τούτοις τὸ περὶ τὴν τελευτὴν ἀτύχημα, εἰς τοσαύτην παράστασιν ἐνέπιπτον καὶ δυσθυμίαν ὥστε πλήρη γενέσθαι τὴν πόλιν στεναγμοῦ, δακρύων, οἰμωγῆς ἀκαταπαύστου. ταῦτα δ’ ἦν τοῖς ὀρθῶς λογιζομένοις οὐχ οὕτω τῆς πρὸς Ἀρσινόην εὐνοίας τεκμήρια, πολὺ δὲ μᾶλλον τοῦ πρὸς τοὺς περὶ τὸν Ἀγαθοκλέα μίσους· ὁ δὲ προειρημένος, ἐπειδὴ τὰς ὑδρίας εἰς τοὺς βασιλικοὺς οἴκους ἔθηκε, παραγγείλας ἀποθέσθαι τὰ φαιά, πρῶτον μὲν διμήνου τὰς δυνάμεις ὠψωνίασε, πεπεισμένος τὸ παρὰ τοῖς πολλοῖς μῖσος ἀμβλύνειν διὰ τῆς πρὸς τὸ λυσιτελὲς ὁρμῆς αὐτῶν, εἶτ’ ἐπεξώρκισε τὸν ὅρκον ὃν ἦσαν ὀμνύειν εἰθισμένοι κατὰ τὰς ἀναδείξεις τῶν βασιλέων. ἐξαπέστειλε δὲ καὶ Φιλάμμωνα τὸν ἐπιστάντα τῷ τῆς Ἀρσινόης φόνῳ, ποιήσας αὐτὸν Λιβυάρχην τῶν κατὰ Κυρήνην τόπων, τὸ δὲ παιδίον ἐνεχείρισε ταῖς περὶ τὴν Οἰνάνθην καὶ Ἀγαθόκλειαν. μετὰ δὲ ταῦτα Πέλοπα μὲν ἐξέπεμψε τὸν Πέλοπος εἰς τὴν Ἀσίαν πρὸς Ἀντίοχον τὸν βασιλέα, παρακαλέσοντα συντηρεῖν τὴν φιλίαν καὶ μὴ παραβαίνειν τὰς πρὸς τὸν τοῦ παιδὸς πατέρα συνθήκας, Πτολεμαῖον δὲ τὸν Σωσιβίου πρὸς Φίλιππον τά τε περὶ τῆς ἐπιγαμίας συνθησόμενον καὶ παρακαλέσοντα βοηθεῖν, ἐὰν ὁλοσχερέστερον αὐτοὺς Ἀντίοχος ἐπιβάληται παρασπονδεῖν. προεχειρίσατο δὲ καὶ Πτολεμαῖον τὸν Ἀγησάρχου πρεσβευτὴν πρὸς Ῥωμαίους, οὐχ ὡς ἐπισπεύσοντα τὴν πρεσβείαν, ἀλλ’ ὡς, ἂν ἅψηται τῆς Ἑλλάδος καὶ συμμίξῃ τοῖς ἐκεῖ φίλοις καὶ συγγενέσιν, αὐτοῦ καταμενοῦντα. προέκειτο γὰρ αὐτῷ πάντας τοὺς ἐπιφανεῖς ἄνδρας ἐκποδὼν ποιῆσαι. ἐξαπέστειλε δὲ καὶ Σκόπαν τὸν Αἰτωλὸν ἐπὶ ξενολογίαν εἰς τὴν Ἑλλάδα, πλῆθος χρυσίου συνθεὶς εἰς τὰ προδόματα. δύο γὰρ ἔσχε προθέσεις ὑπὲρ ταύτης τῆς ἐπιβολῆς, μίαν μὲν ἀποχρῆσθαι τοῖς ξενολογηθεῖσιν εἰς τὸν πρὸς Ἀντίοχον πόλεμον, ἄλλην δὲ τοὺς ἀρχαίους καὶ προϋπάρχοντας ξένους ἐπὶ τὰ κατὰ τὴν χώραν φρούρια καὶ τὰς κατοικίας ἀποστεῖλαι, τοῖς δὲ παραγενομένοις ἀναπληρῶσαι καὶ καινοποιῆσαι τὴν θεραπείαν καὶ τὰ περὶ τὴν αὐλὴν φυλακεῖα, παραπλησίως δὲ καὶ κατὰ τὴν ἄλλην πόλιν, νομίζων τοὺς δι’ αὑτοῦ ξενολογηθέντας καὶ μισθοδοτουμένους τῶν μὲν προγεγονότων μηδενὶ συμπαθήσοντας διὰ τὸ μηδὲν γινώσκειν, ἐν αὐτῷ δὲ τὰς ἐλπίδας ἔχοντας καὶ τῆς σωτηρίας καὶ τῆς ἐπανορθώσεως, ἑτοίμους ἕξειν συναγωνιστὰς καὶ συνεργοὺς πρὸς τὸ παραγγελλόμενον. ταῦτα δ’ ἐγενήθη πρότερα τοῦ παρὰ Φιλίππῳ διαβουλίου, ὡς ἐδηλώσαμεν· ἀλλ’ ἐκείνων κατὰ τὴν τῆς διηγήσεως τάξιν προτέρων λαμβανομένων ἀναγκαῖον ἦν οὕτως ταῦτα χειρίζειν ὥστε πρότερον ἐξηγεῖσθαι τὰς ἐντεύξεις καὶ τοὺς χρηματισμοὺς τῶν πρεσβευτῶν καὶ τῆς καταστάσεως καὶ τῆς ἐξαποστολῆς. ὁ δ’ Ἀγαθοκλῆς ἐπεὶ τοὺς ἐπιφανεστάτους τῶν ἀνδρῶν ἐκποδὼν ἐποίησε, καὶ τὸ πολὺ τῆς τοῦ πλήθους ὀργῆς παρακατέσχε τῇ τῶν ὀψωνίων ἀποδόσει, παρὰ πόδας εἰς τὴν ἐξ ἀρχῆς συνήθειαν ἐπανῆλθε. καὶ τὰς μὲν τῶν φίλων χώρας ἀνεπλήρωσε, παρεισαγαγὼν ἐκ τῆς διακονίας καὶ τῆς ἄλλης ὑπηρεσίας τοὺς εἰκαιοτάτους καὶ θρασυτάτους· αὐτὸς δὲ τὸ πολὺ τῆς ἡμέρας καὶ τῆς νυκτὸς ἐν μέθῃ διέτριβε καὶ ταῖς τῇ μέθῃ παρεπομέναις ἀκρασίαις, οὐ φειδόμενος οὔτ’ ἀκμαζούσης γυναικὸς οὔτε νύμφης οὔτε παρθένου, καὶ πάντα ταῦτ’ ἔπραττε μετὰ τῆς ἐπαχθεστάτης φαντασίας. ὅθεν πολλῆς μὲν καὶ παντοδαπῆς γινομένης δυσαρεστήσεως, οὐδεμιᾶς δὲ θεραπείας οὐδὲ βοηθείας προσαγομένης, τὸ δ’ ἐναντίον ἀεὶ προσεπαγομένης ὕβρεως, ὑπερηφανίας, ῥᾳθυμίας, ἀνεθυμιᾶτο πάλιν ἐν τοῖς πολλοῖς τὸ προϋπάρχον μῖσος καὶ πάντες ἀνενεοῦντο τὰ προγεγενημένα περὶ τὴν βασιλείαν ἀτυχήματα διὰ τοὺς ἀνθρώπους τούτους. τῷ δὲ μηδὲν ἔχειν πρόσωπον ἀξιόχρεων τὸ προστησόμενον, καὶ δι’ οὗ τὴν ὀργὴν εἰς τὸν Ἀγαθοκλέα καὶ τὴν Ἀγαθόκλειαν ἀπερείσονται, τὴν ἡσυχίαν ἦγον, ἔτι μίαν ἐλπίδα καραδοκοῦντες τὴν κατὰ τὸν Τληπόλεμον καὶ ταύτῃ προσανέχοντες. ὁ δὲ Τληπόλεμος, ἕως μὲν ὁ βασιλεὺς ἔζη, τὰ καθ’ αὑτὸν ἔπραττεν· ἅμα δὲ τῷ μεταλλάξαι ’κεῖνον ταχέως ἐξομαλίσας τὰ πλήθη στρατηγὸς πάλιν ἐγενήθη τῶν κατὰ Πηλούσιον τόπων. καὶ τὰς μὲν ἀρχὰς ἐποιεῖτο τὴν ἀναφορὰν τῶν πραττομένων ἐπὶ τὸ τοῦ βασιλέως συμφέρον, πεπεισμένος ὑπάρξειν τι συνέδριον ὃ τήν τε τοῦ παιδὸς ἐπιτροπείαν ἕξει καὶ τὴν τῶν ὅλων προστασίαν. ὡς δ’ ἑώρα τοὺς μὲν ἀξίους ἐπιτροπῆς ἄνδρας ἐκποδὼν γεγονότας, τῆς δὲ τῶν ὅλων ἀρχῆς κατατολμῶντα τὸν Ἀγαθοκλέα, ταχέως ἐφ’ ἑτέρας ἐγένετο γνώμης, ὑφορώμενος τὸν προεστῶτα κίνδυνον διὰ τὴν ὑποκειμένην αὐτοῖς ἔχθραν, καὶ τάς τε δυνάμεις περὶ αὑτὸν ἥθροιζε καὶ περὶ πόρον ἐγίνετο χρημάτων, ἵνα μηδενὶ τῶν ἐχθρῶν εὐχείρωτος ᾖ. ἅμα δὲ καὶ τὴν τοῦ παιδὸς ἐπιτροπείαν καὶ τὴν τῶν ὅλων προστασίαν εἰς ἑαυτὸν ἥξειν οὐκ ἀπήλπιζε, νομίζων καὶ κατὰ τὴν ἰδίαν μὲν κρίσιν αὐτὸς ἀξιοχρεώτερος ὑπάρχειν Ἀγαθοκλέους πρὸς πᾶν, ἔτι μᾶλλον δὲ πυνθανόμενος καὶ τὰς ὑφ’ ἑαυτὸν ταττομένας δυνάμεις καὶ τὰς κατὰ τὴν Ἀλεξάνδρειαν ἐπ’ ἐκείνῳ τὰς ἐλπίδας ἔχειν τοῦ καταλύειν τὴν Ἀγαθοκλέους ὕβριν. οὔσης δὲ περὶ αὐτὸν οἵας εἴρηκα διαλήψεως, ταχέως τὰ τῆς διαφορᾶς αὔξησιν ἔλαβε συνεργούντων ἀμφοτέρων πρὸς τὴν τοιαύτην ὑπόθεσιν. ὁ μὲν γὰρ Τληπόλεμος, ἐξιδιάζεσθαι σπεύδων τοὺς ἡγεμόνας καὶ ταξιάρχους καὶ τοὺς ἐπὶ τούτων ταττομένους, συνῆγε πότους ἐπιμελῶς, καὶ παρὰ τὰς συνουσίας τὰ μὲν ὑπὸ τῶν πρὸς χάριν λεγόντων αἰκαλλόμενος, τὰ δ’ ὑπὸ τῆς ἰδίας ὁρμῆς, ἅτε νέος ὢν καὶ παρὰ τὸν οἶνον γινομένης τῆς ὁμιλίας, ἐρρίπτει λόγους κατὰ τῆς συγγενείας τῆς τῶν περὶ τὸν Ἀγαθοκλέα, τὰς μὲν ἀρχὰς αἰνιγματώδεις, εἶτ’ ἀμφιβόλους, τὸ δὲ τελευταῖον ἐκφανεῖς καὶ τὴν πικροτάτην ἔχοντας λοιδορίαν. ἐπεχεῖτο γὰρ τοῦ θρανογράφου καὶ τῆς σαμβυκιστρίας καὶ τῆς κουρίδος, ἔτι δὲ τοῦ παιδαρίου τοῦ πάντα πεποιηκότος καὶ πεπονθότος παρὰ τοὺς πότους, ὅτ’ ἐῳνοχόει τῷ βασιλεῖ παῖς ὤν. ἐπὶ δὲ τούτοις ἀεὶ τῶν συμπαρόντων γελώντων καὶ συμβαλλομένων τι πρὸς τὸν χλευασμόν, ταχέως εἰς τοὺς περὶ τὸν Ἀγαθοκλέα τὸ πρᾶγμα παρεγενήθη. γενομένης δ’ ἔχθρας ὁμολογουμένης εὐθέως ὁ Ἀγαθοκλῆς διαβολὴν εἰσῆγε κατὰ τοῦ Τληπολέμου, φάσκων αὐτὸν ἀλλοτριάζειν τοῦ βασιλέως καὶ καλεῖν Ἀντίοχον ἐπὶ τὰ πράγματα. καὶ πολλὰς εἰς τοῦτο τὸ μέρος εὐπόρει πιθανότητας, τὰς μὲν ἐκ τῶν συμβαινόντων παρεκδεχόμενος καὶ διαστρέφων, τὰς δ’ ἐκ καταβολῆς πλάττων καὶ διασκευάζων. ταῦτα δ’ ἐποίει βουλόμενος τὰ πλήθη παροξύνειν κατὰ τοῦ Τληπολέμου· συνέβαινε δὲ τοὐναντίον. πάλαι γὰρ ἐπὶ τῷ προειρημένῳ τὰς ἐλπίδας ἔχοντες οἱ πολλοὶ καὶ λίαν ἡδέως ἑώρων ἐκκαιομένην τὴν διαφοράν. ἐγένετο δ’ ἡ καταρχὴ τοῦ περὶ τὰ πλήθη κινήματος διά τινας τοιαύτας αἰτίας. Νίκων ὁ συγγενὴς τῶν περὶ τὸν Ἀγαθοκλέα ζῶντος ἔτι τοῦ βασιλέως καθεσταμένος ἦν ἐπὶ τοῦ ναυτικοῦ· τότε δὲ τῶν", "st": "15.25"}, {"sp": "N", "t": "ὅτι Δείνωνα τὸν Δείνωνος ἐπανείλετο Ἀγαθοκλῆς, καὶ τοῦτο ἔπραξε τῶν ἀδίκων ἔργων, ὡς ἡ παροιμία φησί, δικαιότατον· καθ’ ὃν μὲν γὰρ καιρόν, τῶν γραμμάτων αὐτῷ προσπεσόντων ὑπὲρ τῆς ἀναιρέσεως τῆς Ἀρσινόης, ἐξουσίαν ἔσχε μηνῦσαι τὴν πρᾶξιν καὶ σῶσαι τὰ κατὰ τὴν βασιλείαν, τότε δὴ συνεργήσας τοῖς περὶ τὸν Φιλάμμωνα, πάντων ἐγένετο τῶν ἐπιγενομένων κακῶν αἴτιος, μετὰ δὲ τὸ συντελεσθῆναι τὸν φόνον ἀνανεούμενος καὶ πρὸς πολλοὺς οἰκτιζόμενος καὶ μεταμελόμενος ἐπὶ τῷ τοιοῦτον καιρὸν παραλιπεῖν δῆλος ἐγένετο τοῖς περὶ τὸν Ἀγαθοκλέα· διὸ καὶ παραυτίκα τυχὼν τῆς ἁρμοζούσης τιμωρίας μετήλλαξε τὸν βίον. —", "st": "15.26a"}, {"sp": "N", "t": "πρώτους δὲ συναθροίσας τοὺς Μακεδόνας, εἰς τούτους εἰσῆλθε μετὰ τοῦ βασιλέως καὶ τῆς Ἀγαθοκλείας. καὶ τὰς μὲν ἀρχὰς ὑπεκρίνετο τὸν οὐ δυνάμενον εἰπεῖν ἃ βούλεται διὰ τὸ πλῆθος τῶν ἐπιφερομένων δακρύων· ἐπεὶ δὲ πλεονάκις ἀπομάττων τῇ χλαμύδι κατεκράτησε τῆς ἐπιφορᾶς, βαστάσας τὸ παιδίον \"Λάβετε\" ἔφη \"τοῦτον, ὃν ὁ πατὴρ ἀποθνήσκων εἰς μὲν τὰς ἀγκάλας ἔδωκε ταύτῃ\" δείξας τὴν ἀδελφὴν \"παρακατέθετο δ’ εἰς τὴν ὑμετέραν, ὦ ἄνδρες Μακεδόνες, πίστιν. ἡ μὲν οὖν [καὶ] ταύτης εὔνοια βραχεῖάν τινα ῥοπὴν ἔχει πρὸς τὴν τούτου σωτηρίαν, ἐν ὑμῖν δὲ κεῖται καὶ ταῖς ὑμετέραις χερσὶ τὰ τούτου νυνὶ πράγματα. Τληπόλεμος γὰρ πάλαι μὲν ἦν δῆλος τοῖς ὀρθῶς σκοπουμένοις μειζόνων ἐφιέμενος ἢ καθ’ ἑαυτὸν πραγμάτων, νῦν δὲ καὶ τὴν ἡμέραν καὶ τὸν καιρὸν ὥρικεν, ἐν ᾗ μέλλει τὸ διάδημ’ ἀναλαμβάνειν. \" καὶ περὶ τούτων οὐχ αὑτῷ πιστεύειν ἐκέλευεν, ἀλλὰ τοῖς εἰδόσι τὴν ἀλήθειαν καὶ παροῦσι νῦν ἐξ αὐτῶν τῶν πραγμάτων. καὶ τοῦτ’ εἰπὼν εἰσῆγε τὸν Κριτόλαον, ὃς ἔφη καὶ τοὺς βωμοὺς αὐτὸς ἑωρακέναι κατασκευαζομένους καὶ τὰ θύματα παρὰ τοῖς πλήθεσιν ἑτοιμαζόμενα πρὸς τὴν τοῦ διαδήματος ἀνάδειξιν. ὧν οἱ Μακεδόνες ἀκούοντες οὐχ οἷον ἠλέουν αὐτόν, ἀλλ’ ἁπλῶς οὐδὲν προσεῖχον τῶν λεγομένων, μυχθίζοντες δὲ καὶ διαψιθυρίζοντες ἐξελήρησαν οὕτως ὥστε μηδ’ αὐτὸν εἰδέναι [μήτε] πῶς τὸ παράπαν ἐκ τῆς ἐκκλησίας ἀπελύθη. παραπλήσια δὲ τούτοις ἐγίνετο καὶ περὶ τὰ λοιπὰ συστήματα κατὰ τοὺς ἐκκλησιασμούς. ἐν δὲ τῷ μεταξὺ πολὺς ἦν ὁ καταπλέων ἐκ τῶν ἄνω στρατοπέδων, καὶ παρεκάλουν οἱ μὲν συγγενεῖς, οἱ δὲ φίλους, βοηθεῖν τοῖς ὑποκειμένοις, καὶ μὴ περιιδεῖν σφᾶς ἀνέδην ὑφ’ οὕτως ἀναξίων ὑβριζομένους. μάλιστα δὲ παρώξυνε τοὺς πολλοὺς πρὸς τὴν κατὰ τῶν προεστώτων τιμωρίαν τὸ γινώσκειν ὅτι τὸ μέλλειν καθ’ αὑτῶν ἐστι διὰ τὸ πάντων τῶν παρακομιζομένων ἐπιτηδείων εἰς τὴν Ἀλεξάνδρειαν κρατεῖν τοὺς περὶ τὸν Τληπόλεμον.", "st": "15.26b"}, {"sp": "N", "t": "ἐγένετο δέ τι καὶ ἐξ αὐτῶν τῶν περὶ τὸν Ἀγαθοκλέα συνέργημα πρὸς τὸ τὴν ὀργὴν ἐπιτεῖναι τήν τε τῶν πολλῶν καὶ τὴν τοῦ Τληπολέμου· τὴν γὰρ Δανάην, ἥτις ἦν πενθερὰ τοῦ προειρημένου, λαβόντες ἐκ τοῦ τῆς Δήμητρος ἱεροῦ καὶ διὰ μέσου τῆς πόλεως ἑλκύσαντες ἀκατακάλυπτον εἰς φυλακὴν ἀπέθεντο, βουλόμενοι φανερὰν ποιεῖν τὴν πρὸς τὸν Τληπόλεμον διαφοράν. ἐφ’ οἷς τὸ πλῆθος ἀγανακτοῦν οὐκέτι κατ’ ἰδίαν οὐδὲ δι’ ἀπορρήτων ἐποιεῖτο τοὺς λόγους, ἀλλ’ οἱ μὲν τὰς νύκτας εἰς πάντα τόπον ἐπέγραφον, οἱ δὲ τὰς ἡμέρας συστρεφόμενοι κατὰ μέρη φανερῶς ἐξέφερον ἤδη τὸ μῖσος εἰς τοὺς προεστῶτας. οἱ δὲ περὶ τὸν Ἀγαθοκλέα βλέποντες τὰ συμβαίνοντα, καὶ μοχθηρὰς ἐλπίδας ἔχοντες περὶ αὑτῶν, τοτὲ μὲν ἐγίνοντο περὶ δρασμόν, οὐδενὸς δ’ αὐτοῖς ἡτοιμασμένου πρὸς τοῦτο τὸ μέρος διὰ τὴν σφετέραν ἀβουλίαν ἀφίσταντο τῆς ἐπιβολῆς· τοτὲ δὲ συνωμότας κατέγραφον καὶ κοινωνοὺς τῆς τόλμης, ὡς αὐτίκα μάλα τῶν ἐχθρῶν τοὺς μὲν κατασφάξοντες, τοὺς δὲ συλληψόμενοι, μετὰ δὲ ταῦτα τυραννικὴν ἐξουσίαν περιποιησόμενοι. ταῦτα δ’ αὐτῶν διανοουμένων προσέπεσε διαβολὴ κατά τινος Μοιραγένους, ἑνὸς τῶν σωματοφυλάκων, διότι μηνύοι πάντα τῷ Τληπολέμῳ καὶ συνεργοίη διὰ τὴν πρὸς Ἀδαῖον οἰκειότητα τὸν ἐπὶ τῆς Βουβαστοῦ τότε καθεσταμένον. ὁ δ’ Ἀγαθοκλῆς εὐθέως συνέταξε Νικοστράτῳ τῷ πρὸς τοῖς γράμμασι τεταγμένῳ συλλαβόντι τὸν Μοιραγένη φιλοτίμως ἐξετάσαι, πᾶσαν προτιθέντα βάσανον. οὗτος μὲν οὖν παραχρῆμα συλληφθεὶς ὑπὸ τοῦ Νικοστράτου καὶ παραχθεὶς εἴς τινα μέρη τῆς αὐλῆς ἀποκεχωρηκότα, τὸ μὲν πρῶτον ἐξ ὀρθῆς ἀνεκρίνετο περὶ τῶν προσπεπτωκότων, πρὸς οὐδὲν δὲ τῶν λεγομένων ἀνθομολογούμενος ἐξεδύθη· καὶ τινὲς μὲν τὰ πρὸς τὰς βασάνους ὄργανα διεσκεύαζον, οἱ δὲ τὰς μάστιγας ἔχοντες μετὰ χεῖρας ἀπεδύοντο τὰς χλαμύδας. κατὰ δὲ τὸν καιρὸν τοῦτον προστρέχει τις τῶν ὑπηρετῶν πρὸς τὸν Νικόστρατον, καὶ ψιθυρίσας πρὸς τὴν ἀκοὴν ἅττα δήποτ’ οὖν ἀπηλλάττετο μετὰ σπουδῆς. ὁ δὲ Νικόστρατος ἐκ ποδὸς ἐπηκολούθει τούτῳ, λέγων μὲν οὐδέν, τύπτων δὲ συνεχῶς τὸν μηρόν.", "st": "15.27"}, {"sp": "N", "t": "περὶ δὲ τὸν Μοιραγένην ἄφατον ἦν καὶ παράλογον τὸ συμβαῖνον. οἱ μὲν γὰρ μόνον οὐ διατεταμένοι τὰς μάστιγας παρέστασαν, οἱ δὲ πρὸ ποδῶν αὐτοῦ τὰ πρὸς ἀνάγκας ὄργανα διεσκεύαζον· τοῦ δὲ Νικοστράτου παραχωρήσαντος ἕστασαν ἀχανεῖς πάντες, ἐμβλέποντες ἀλλήλοις, προσδοκῶντες ἀεί ποτε τὸν προειρημένον ἀνακάμψειν. χρόνου δὲ γινομένου κατὰ βραχὺ διέρρεον οἱ παρεστῶτες, τέλος δ’ ὁ Μοιραγένης ἀπελείφθη. καὶ μετὰ ταῦτα διελθὼν τὴν αὐλὴν ἀνελπίστως παρέπεσε γυμνὸς εἴς τινα σκηνὴν τῶν Μακεδόνων, σύνεγγυς κειμένην τῆς αὐλῆς. καταλαβὼν δὲ κατὰ τύχην ἀριστῶντας καὶ συνηθροισμένους, ἔλεγε τὰ περὶ αὑτὸν συμβεβηκότα καὶ τὸ παράλογον τῆς σωτηρίας. οἱ δὲ τὰ μὲν ἠπίστουν, τὰ δὲ πάλιν ὁρῶντες αὐτὸν γυμνὸν ἠναγκάζοντο πιστεύειν. ἐκ δὲ ταύτης τῆς περιπετείας ὅ τε Μοιραγένης μετὰ δακρύων ἐδεῖτο τῶν Μακεδόνων μὴ μόνον τῆς αὑτοῦ συνεπιλαβέσθαι σωτηρίας, ἀλλὰ καὶ τῆς τοῦ βασιλέως, καὶ μάλιστα τῆς σφῶν αὐτῶν· πρόδηλον γὰρ εἶναι πᾶσι τὸν ὄλεθρον, ἐὰν μὴ συνάψωνται τοῦ καιροῦ, καθ’ ὃν ἀκμάζει τὸ τῶν πολλῶν μῖσος καὶ πᾶς ἕτοιμός ἐστι πρὸς τὴν κατ’ Ἀγαθοκλέους τιμωρίαν. ἀκμάζειν δὲ νῦν μάλιστ’ ἔφη καὶ προσδεῖσθαι τῶν καταρξομένων.", "st": "15.28"}, {"sp": "N", "t": "οἱ δὲ Μακεδόνες ἀκούσαντες τούτων παροξύνονται, καὶ πέρας ἐπείσθησαν τῷ Μοιραγένει, καὶ πρώτας μὲν εὐθέως ἐπῄεσαν τὰς τῶν Μακεδόνων σκηνάς, μετὰ δὲ ταῦτα τὰς τῶν ἄλλων στρατιωτῶν· εἰσὶ δ’ αὗται συνεχεῖς, πρὸς ἓν μέρος ἀπονενευκυῖαι τῆς πόλεως. οὔσης δὲ τῆς μὲν ὁρμῆς πάλαι προχείρου τῆς τῶν πολλῶν, προσδεομένης δὲ τοῦ προκαλεσομένου μόνον καὶ τολμήσοντος, ἅμα τῷ λαβεῖν ἀρχὴν τὸ πρᾶγμα ταχέως οἷον εἰ πῦρ ἐξέλαμψεν. οὐ γὰρ ἐγενήθησαν ὧραι τέτταρες καὶ πάντα τὰ γένη συμπεφωνήκει καὶ τὰ στρατιωτικὰ καὶ τὰ πολιτικὰ πρὸς τὴν ἐπίθεσιν. συνήργησε γὰρ μεγάλα καὶ ταὐτόματον ἐν τῷ καιρῷ τούτῳ πρὸς τὴν συντέλειαν. ὁ μὲν γὰρ Ἀγαθοκλῆς, ἀνενεχθείσης πρὸς αὐτὸν ἐπιστολῆς καὶ κατασκόπων ἐπαναχθέντων, καὶ τῆς μὲν ἐπιστολῆς γεγραμμένης πρὸς τὰς δυνάμεις παρὰ τοῦ Τληπολέμου καὶ δηλούσης ὅτι παρέσται ταχέως, τῶν δὲ κατασκόπων διασαφούντων ὅτι πάρεστιν, οὕτως ἐξέστη τῶν φρενῶν ὥστ’ ἀφέμενος τοῦ πράττειν τι καὶ διανοεῖσθαι περὶ τῶν προσπεπτωκότων ἀπῆλθε κατὰ τὸν εἰθισμένον καιρὸν εἰς τὸν πότον, κἀκεῖ κατὰ τὴν εἰθισμένην ἀγωγὴν ἐπετέλει τὴν συνουσίαν. ἡ δ’ Οἰνάνθη περικακοῦσα παρῆν εἰς τὸ Θεσμοφορεῖον, ἀνεῳγμένου τοῦ νεὼ διά τινα θυσίαν ἐπέτειον. καὶ τὸ μὲν πρῶτον ἐλιπάρει γονυπετοῦσα καὶ μαγγανεύουσα πρὸς τὰς θεάς, μετὰ δὲ ταῦτα καθίσασα πρὸς τὸν βωμὸν εἶχε τὴν ἡσυχίαν. αἱ μὲν οὖν πολλαὶ τῶν γυναικῶν, ἡδέως ὁρῶσαι τὴν δυσθυμίαν καὶ περικάκησιν αὐτῆς, ἀπεσιώπων· αἱ δὲ τοῦ Πολυκράτους συγγενεῖς καί τινες ἕτεραι τῶν ἐνδόξων, ἀδήλου τῆς περιστάσεως αὐταῖς ἀκμὴν ὑπαρχούσης, προσελθοῦσαι παρεμυθοῦντο τὴν Οἰνάνθην. ἡ δ’ ἀναβοήσασα μεγάλῃ τῇ φωνῇ \"μή μοι πρόσιτέ\" φησι \"θηρία· καλῶς γὰρ ὑμᾶς γινώσκω, διότι καὶ φρονεῖθ’ ἡμῖν ἐναντία καὶ ταῖς θεαῖς εὔχεσθε τὰ δυσχερέστατα καθ’ ἡμῶν. οὐ μὴν ἀλλ’ ἔτι πέποιθα τῶν θεῶν βουλομένων γεύσειν ὑμᾶς τῶν ἰδίων τέκνων\". καὶ ταῦτ’ εἰποῦσα ταῖς ῥαβδούχοις ἀνείργειν προσέταξε καὶ παίειν τὰς μὴ πειθαρχούσας. αἱ δ’ ἐπιλαβόμεναι τῆς προφάσεως ταύτης ἀπηλλάττοντο πᾶσαι, τοῖς θεοῖς ἀνίσχουσαι τὰς χεῖρας καὶ καταρώμεναι λαβεῖν αὐτὴν ἐκείνην πεῖραν τούτων, ἃ κατὰ τῶν πέλας ἐπανετείνετο πράξειν.", "st": "15.29"}, {"sp": "N", "t": "ἤδη δὲ κεκριμένου τοῦ καινοτομεῖν τοῖς ἀνδράσιν, ἐπιγενομένης καθ’ ἑκάστην οἰκίαν καὶ τῆς ἐκ τῶν γυναικῶν ὀργῆς διπλάσιον ἐξεκαύθη τὸ μῖσος. ἅμα δὲ τῷ μεταλαβεῖν τὸ τῆς νυκτὸς πᾶσα πλήρης ἦν ἡ πόλις θορύβου καὶ φώτων καὶ διαδρομῆς· οἱ μὲν γὰρ εἰς τὸ στάδιον ἡθροίζοντο μετὰ κραυγῆς, οἱ δὲ παρεκάλουν ἀλλήλους, οἱ δὲ κατεδύοντο διαδιδράσκοντες εἰς ἀνυπονοήτους οἰκίας καὶ τόπους· ἤδη δὲ τῶν περὶ τὴν αὐλὴν εὐρυχωριῶν καὶ τοῦ σταδίου καὶ τῆς πλατείας πλήρους ὑπαρχούσης ὄχλου παντοδαποῦ καὶ τῆς περὶ τὸ Διονυσιακὸν θέατρον προστασίας, πυθόμενος τὸ συμβαῖνον Ἀγαθοκλῆς ἐξηγέρθη μεθύων, ἄρτι καταλελυκὼς τὸν πότον, καὶ παραλαβὼν τοὺς συγγενεῖς πάντας πλὴν Φίλωνος ἧκε πρὸς τὸν βασιλέα. καὶ βραχέα πρὸς τοῦτον οἰκτισάμενος καὶ λαβόμενος αὐτοῦ τῆς χειρός, ἀνέβαινεν εἰς τὴν σύριγγα τὴν μεταξὺ τοῦ Μαιάνδρου καὶ τῆς παλαίστρας κειμένην καὶ φέρουσαν ἐπὶ τὴν τοῦ θεάτρου πάροδον. μετὰ δὲ ταῦτα, δύο θύρας ἀσφαλισάμενος τὰς πρώτας, εἰς τὴν τρίτην ἀνεχώρησε μετὰ δυεῖν ἢ τριῶν σωματοφυλάκων καὶ τοῦ βασιλέως καὶ τῆς αὑτοῦ συγγενείας. συνέβαινε δὲ τὰς θύρας εἶναι δικτυωτὰς διαφανεῖς, ἀποκλειομένας δὲ διττοῖς μοχλοῖς. κατὰ δὲ τὸν καιρὸν τοῦτον ἡθροισμένου τοῦ πλήθους ἐξ ἁπάσης τῆς πόλεως, ὥστε μὴ μόνον τοὺς ἐπιπέδους τόπους, ἀλλὰ καὶ τὰ βάθρα καὶ τὰ τέγη καταγέμειν ἀνθρώπων, ἐγίνετο βοὴ καὶ κραυγὴ σύμμικτος, ὡς ἂν γυναικῶν ὁμοῦ καὶ παίδων ἀνδράσιν ἀναμεμιγμένων· οὐ γὰρ ἐλάττω ποιεῖ τὰ παιδάρια τῶν ἀνδρῶν περὶ τὰς τοιαύτας ταραχὰς ἔν τε τῇ Καρχηδονίων πόλει καὶ κατὰ τὴν Ἀλεξάνδρειαν.", "st": "15.30"}, {"sp": "N", "t": "ἤδη δὲ τῆς ἡμέρας ὑποφαινούσης ἦν μὲν ἄκριτος ἡ κραυγή, μάλιστα δ’ ἐξ αὐτῆς ἐξέλαμψε τὸ καλεῖν τὸν βασιλέα. τὸ μὲν οὖν πρῶτον οἱ Μακεδόνες ἐξαναστάντες κατελάβοντο τὸν χρηματιστικὸν πυλῶνα τῶν βασιλείων· μετὰ δέ τινα χρόνον ἐπιγνόντες ποῦ τῆς αὐλῆς ἦν ὁ βασιλεύς, περιελθόντες τὰς μὲν πρώτας τῆς [πρώτης] σύριγγος ἐξέβαλον θύρας, ἐγγίσαντες δὲ τῆς δευτέρας ᾐτοῦντο τὸν παῖδα μετὰ κραυγῆς. οἱ δὲ περὶ τὸν Ἀγαθοκλέα, βλέποντες ἤδη τὰ καθ’ αὑτούς, ἐδέοντο τῶν σωματοφυλάκων πρεσβεῦσαι περὶ αὑτῶν πρὸς τοὺς Μακεδόνας, δηλοῦντας ὅτι τῆς ἐπιτροπείας ἐκχωροῦσι καὶ τῆς ἄλλης ἐξουσίας καὶ τῶν τιμῶν, ἔτι δὲ τῶν χορηγίων ὧν ἔχουσι πάντων, αὐτὸ δὲ τὸ πνευμάτιον δέονται συγχωρηθῆναι σφίσι μετὰ τῆς ἀναγκαίας τροφῆς, ἵνα χωρήσαντες εἰς τὴν ἐξ ἀρχῆς διάθεσιν μηδὲ βουληθέντες ἔτι δύνωνται λυπεῖν μηδένα. τῶν μὲν οὖν ἄλλων σωματοφυλάκων οὐδεὶς ὑπήκουσεν, Ἀριστομένης δὲ μόνος ὑπέστη τὴν χρείαν ταύτην ὁ μετά τινα χρόνον ἐπὶ τῶν πραγμάτων γενόμενος. ὁ δ’ ἀνὴρ οὗτος τὸ μὲν γένος ἦν Ἀκαρνάν, καθ’ ὅσον δὲ προβαίνων κατὰ τὴν ἡλικίαν, γενόμενος κύριος τῶν ὅλων πραγμάτων, κάλλιστα καὶ σεμνότατα δοκεῖ προστῆναι τοῦ τε βασιλέως καὶ τῆς βασιλείας, κατὰ τοσοῦτον κεκολακευκέναι τὴν Ἀγαθοκλέους εὐκαιρίαν. πρῶτος μὲν γὰρ ὡς ἑαυτὸν ἐπὶ δεῖπνον καλέσας τὸν Ἀγαθοκλέα χρυσοῦν στέφανον ἀνέδωκε μόνῳ τῶν παρόντων, ὃ τοῖς βασιλεῦσιν αὐτοῖς ἔθος ἐστὶ μόνοις συγχωρεῖσθαι, πρῶτος δὲ τὴν εἰκόνα τοῦ προειρημένου φέρειν ἐτόλμησεν ἐν τῷ δακτυλίῳ· γενομένης δὲ θυγατρὸς αὐτῷ ταύτην Ἀγαθόκλειαν προσηγόρευσεν. ἀλλ’ ἴσως ὑπὲρ μὲν τούτων ἐξαρκεῖ καὶ τὰ νῦν εἰρημένα· λαβὼν δὲ τὰς προειρημένας ἐντολὰς καὶ διά τινος ῥινοπύλης ἐξελθών, ἧκε πρὸς τοὺς Μακεδόνας. βραχέα δ’ αὐτοῦ διαλεχθέντος καὶ δηλώσαντος τὴν προαίρεσιν, ἐπεβάλοντο μὲν οἱ Μακεδόνες παραχρῆμα συγκεντῆσαι, ταχὺ δέ τινων ὑπερεχόντων αὐτοῦ τὰς χεῖρας καὶ παραιτησαμένων τοὺς πολλούς, ἐπανῆλθε λαβὼν ἐντολὴν ἢ τὸν βασιλέα πρὸς αὐτοὺς ἄγονθ’ ἥκειν ἢ μηδ’ αὐτὸν ἐξιέναι. τὸν μὲν οὖν Ἀριστομένην ταῦτ’ εἰπόντες οἱ Μακεδόνες ἀπέπεμψαν, αὐτοὶ δὲ ταῖς δευτέραις θύραις ἐγγίσαντες ἐξέωσαν καὶ ταύτας. οἱ δὲ περὶ τὸν Ἀγαθοκλέα θεωροῦντες τὴν τῶν Μακεδόνων βίαν διά τε τῶν ἐνεργουμένων καὶ διὰ τῆς ἀποκρίσεως, τὸ μὲν πρῶτον ἐπεβάλοντο διὰ τῆς θύρας προτείναντες τὰς χεῖρας, ἡ δ’ Ἀγαθόκλεια καὶ τοὺς μασθούς, οἷς ἔφη θρέψαι τὸν βασιλέα, δεῖσθαι τῶν Μακεδόνων, πᾶσαν προϊέμενοι φωνὴν πρὸς τὸ περιποιήσασθαι τὸ ζῆν αὐτὸ μόνον·", "st": "15.31"}, {"sp": "N", "t": "ἐπεὶ δὲ πολλὰ κατολοφυρόμενοι τὴν αὑτῶν τύχην οὐδὲν ἤνυον, τέλος ἐξέπεμψαν τὸν παῖδα μετὰ τῶν σωματοφυλάκων. οἱ δὲ Μακεδόνες, παραλαβόντες τὸν βασιλέα καὶ ταχέως ἐφ’ ἵππον ἀναβιβάσαντες, ἦγον εἰς τὸ στάδιον. ἅμα δὲ τῷ φανῆναι μεγάλης κραυγῆς καὶ κρότου γενηθέντος, ἐπιστήσαντες τὸν ἵππον καθεῖλον τὸν παῖδα, καὶ προαγαγόντες ἐκάθισαν εἰς τὴν βασιλικὴν θέαν. περὶ δὲ τοὺς ὄχλους ἐγένετό τις ἅμα χαρὰ καὶ λύπη· τὰ μὲν γὰρ ἦσαν περιχαρεῖς ἐπὶ τῷ κεκομίσθαι τὸν παῖδα, τὰ δὲ πάλιν δυσηρέστουν τῷ μὴ συνειλῆφθαι τοὺς αἰτίους μηδὲ τυγχάνειν τῆς ἁρμοζούσης τιμωρίας. διὸ καὶ συνεχῶς ἐβόων, ἄγειν κελεύοντες καὶ παραδειγματίζειν τοὺς πάντων τῶν κακῶν αἰτίους. ἤδη δὲ τῆς ἡμέρας προβαινούσης, καὶ τοῦ πλήθους ἐπ’ οὐδένα δυναμένου πέρας ἀπερείσασθαι τὴν ὁρμήν, Σωσίβιος, ὃς ἦν μὲν υἱὸς Σωσιβίου, τότε δὲ σωματοφύλαξ ὑπάρχων μάλιστα τὸν νοῦν προσεῖχε τῷ τε βασιλεῖ καὶ τοῖς πράγμασι, θεωρῶν τήν τε τοῦ πλήθους ὁρμὴν ἀμετάθετον οὖσαν καὶ τὸ παιδίον δυσχρηστούμενον διά τε τὴν τῶν παρεστώτων ἀσυνήθειαν καὶ διὰ τὴν περὶ τὸν ὄχλον ταραχήν, ἐπύθετο τοῦ βασιλέως εἰ παραδώσει τοῖς πολλοῖς τοὺς εἰς αὐτὸν ἢ τὴν μητέρα τι πεπλημμεληκότας. τοῦ δὲ κατανεύσαντος, τῶν μὲν σωματοφυλάκων τισὶν εἶπε δηλῶσαι τὴν τοῦ βασιλέως γνώμην, τὸ δὲ παιδίον ἀναστήσας ἀπῆγε πρὸς τὴν θεραπείαν εἰς τὴν ἰδίαν οἰκίαν, σύνεγγυς οὖσαν. τῶν δὲ διασαφούντων τὰ παρὰ τοῦ βασιλέως, κατερρήγνυτο πᾶς ὁ τόπος ὑπὸ τοῦ κρότου καὶ τῆς κραυγῆς. οἱ δὲ περὶ τὸν Ἀγαθοκλέα καὶ τὴν Ἀγαθόκλειαν ἐν τούτῳ τῷ καιρῷ διεχωρίσθησαν ἀλλήλων εἰς τὰς ἰδίας καταλύσεις. ταχὺ δὲ τῶν στρατιωτῶν τινες, οἱ μὲν ἐθελοντήν, οἱ δ’ ὑπὸ τοῦ πλήθους ἐξωθούμενοι, παρώρμησαν ἐπὶ τὸ ζητεῖν τοὺς προειρημένους.", "st": "15.32"}, {"sp": "N", "t": "τοῦ δὲ ποιεῖν αἷμα καὶ φόνους ἐγένετό τις ἐκ ταὐτομάτου καταρχὴ τοιαύτη. τῶν γὰρ Ἀγαθοκλέους ὑπηρετῶν καὶ κολάκων τις ὄνομα Φίλων ἐξῆλθε κραιπαλῶν εἰς τὸ στάδιον. οὗτος θεωρῶν τὴν ὁρμὴν τῶν ὄχλων εἶπε πρὸς τοὺς παρεστῶτας ὅτι πάλιν αὐτοῖς, καθάπερ καὶ πρῴην, ἐὰν Ἀγαθοκλῆς ἐξέλθῃ, μεταμελήσει. τῶν δ’ ἀκουσάντων οἱ μὲν ἀπελοιδόρουν αὐτόν, οἱ δὲ προώθουν. ἐπιβαλομένου δ’ ἀμύνεσθαι ταχέως οἱ μὲν τὴν χλαμύδα περιέρρηξαν, οἱ δὲ τὰς λόγχας προσερείσαντες ἐξεκέντησαν. ἅμα δὲ τῷ τοῦτον εἰς τὸ μέσον ἑλκυσθῆναι μεθ’ ὕβρεως ἔτι σπαίροντα, καὶ γεύσασθαι τὰ πλήθη φόνου, πάντες ἐκαραδόκουν τὴν τῶν ἄλλων παρουσίαν. μετ’ οὐ πολὺ δὲ παρῆν ἀγόμενος πρῶτος Ἀγαθοκλῆς δέσμιος· ὃν εὐθέως εἰσιόντα προσδραμόντες τινὲς ἄφνω συνεκέντησαν, ἔργον ποιοῦντες οὐκ ἐχθρῶν, ἀλλ’ εὐνοούντων· αἴτιοι γὰρ ἐγένοντο τοῦ μὴ τυχεῖν αὐτὸν τῆς ἁρμοζούσης καταστροφῆς· μετὰ δὲ τοῦτον ἤχθη Νίκων, εἶτ’ Ἀγαθόκλεια γυμνὴ σὺν ταῖς ἀδελφαῖς, ἑξῆς δὲ τούτοις πάντες οἱ συγγενεῖς. ἐπὶ δὲ πᾶσιν ἐκ τοῦ Θεσμοφορείου τὴν Οἰνάνθην ἀποσπάσαντες ἧκον εἰς τὸ στάδιον, ἄγοντες γυμνὴν ἐφ’ ἵππου. παραδοθέντων δὲ πάντων ὁμοῦ τοῖς ὄχλοις, οἱ μὲν ἔδακνον, οἱ δ’ ἐκέντουν, οἱ δὲ τοὺς ὀφθαλμοὺς ἐξέκοπτον· ἀεὶ δὲ τοῦ πεσόντος τὰ μέλη διέσπων, ἕως ὅτου κατελώβησαν πάντας αὐτούς· δεινὴ γάρ τις ἡ περὶ τοὺς θυμοὺς ὠμότης γίνεται τῶν κατὰ τὴν Αἴγυπτον ἀνθρώπων. κατὰ δὲ τὸν καιρὸν τοῦτον σύντροφοι τῆς Ἀρσινόης γεγενημέναι τινὲς παιδίσκαι, πυθόμεναι παραγεγονέναι τὸν Φιλάμμωνα τριταῖον ἀπὸ Κυρήνης τὸν ἐπιστάντα τῷ φόνῳ τῆς βασιλίσσης, ὥρμησαν ἐπὶ τὴν οἰκίαν αὐτοῦ, καὶ βιασάμεναι τὸν μὲν Φιλάμμωνα τύπτουσαι τοῖς λίθοις καὶ τοῖς ξύλοις ἀπέκτειναν, τὸν δ’ υἱὸν ἀπέπνιξαν, ἀντίπαιδα τὴν ἡλικίαν ὄντα, σὺν δὲ τούτοις τὴν γυναῖκα τοῦ Φιλάμμωνος γυμνὴν εἰς τὴν πλατεῖαν ἐξέλκουσαι διέφθειραν. καὶ τὰ μὲν περὶ τὸν Ἀγαθοκλέα καὶ τὴν Ἀγαθόκλειαν καὶ τοὺς τούτων συγγενεῖς τοιοῦτον ἔσχε τὸ τέλος.", "st": "15.33"}, {"sp": "N", "t": "ἐγὼ δ’ οὐκ ἀγνοῶ μὲν τὰς τερατείας καὶ διασκευάς, αἷς κέχρηνται πρὸς ἔκπληξιν τῶν ἀκουόντων ἔνιοι τῶν γεγραφότων τὰς πράξεις ταύτας, πλείω τὸν ἐπιμετροῦντα λόγον διατιθέμενοι τοῦ συνέχοντος τὰ πράγματα καὶ κυρίου, τινὲς μὲν ἐπὶ τὴν τύχην ἀναφέροντες τὰ γεγονότα καὶ τιθέντες ὑπὸ τὴν ὄψιν τὸ ταύτης ἀβέβαιον καὶ δυσφύλακτον, οἱ δὲ τὸ παράδοξον τῶν συμβεβηκότων ὑπὸ λόγον ἄγοντες, πειρώμενοι τοῖς γεγονόσιν αἰτίας καὶ πιθανότητας ὑποτάττειν. οὐ μὴν ἔγωγε προεθέμην τούτῳ χρήσασθαι τῷ χειρισμῷ περὶ τῶν προειρημένων διὰ τὸ μήτε πολεμικὴν τόλμαν καὶ δύναμιν ἐπίσημον γεγονέναι περὶ τὸν Ἀγαθοκλέα μήτε χειρισμὸν πραγμάτων ἐπιτυχῆ καὶ ζηλωτὸν μήτε τὸ τελευταῖον τὴν αὐλικὴν ἀγχίνοιαν καὶ κακοπραγμοσύνην διαφέρουσαν, ἐν ᾗ Σωσίβιος καὶ πλείους ἕτεροι κατεβίωσαν, βασιλεῖς ἐκ βασιλέων μεταχειριζόμενοι, τὰ δ’ ἐναντία τούτοις συμβεβηκέναι περὶ τὸν προειρημένον ἄνδρα. προαγωγῆς μὲν γὰρ ἔτυχε παραδόξου διὰ τὴν τοῦ Φιλοπάτορος ἀδυναμίαν τοῦ βασιλεύειν· τυχὼν δὲ ταύτης καὶ παραλαβὼν εὐφυέστατον καιρὸν μετὰ τὸν ἐκείνου θάνατον πρὸς τὸ συντηρῆσαι τὴν ἐξουσίαν, ἅμα τὰ πράγματα καὶ τὸ ζῆν ἀπέβαλε διὰ τὴν ἰδίαν ἀνανδρίαν καὶ ῥᾳθυμίαν, ἐν πάνυ βραχεῖ χρόνῳ καταγνωσθείς.", "st": "15.34"}, {"sp": "N", "t": "διόπερ οὐ χρὴ τοῖς τοιούτοις προσάπτειν τὸν ἐπιμετροῦντα λόγον, καθάπερ εἶπα, τῷ δ’ Ἀγαθοκλεῖ καὶ Διονυσίῳ τοῖς Σικελιώταις καί τισιν ἑτέροις τῶν ἐν πράγμασιν ἐπ’ ὀνόματος γεγονότων. ἐκείνων γὰρ ὁ μὲν ἕτερος ἐκ δημοτικῆς καὶ ταπεινῆς ὑποθέσεως ὁρμηθείς, ὁ δ’ Ἀγαθοκλῆς, ὡς ὁ Τίμαιος ἐπισκώπτων φησί, κεραμεὺς ὑπάρχων καὶ καταλιπὼν τὸν τροχὸν καὶ τὸν πηλὸν καὶ τὸν καπνόν, ἧκε νέος ὢν εἰς τὰς Συρακούσας. καὶ τὸ μὲν πρῶτον ἐγενήθησαν ἀμφότεροι κατὰ τοὺς ἰδίους καιροὺς τύραννοι Συρακουσῶν, πόλεως τῆς μέγιστον ἀξίωμα τότε καὶ μέγιστον πλοῦτον περιποιησαμένης, μετὰ δὲ ταῦτα βασιλεῖς ἁπάσης Σικελίας νομισθέντες καί τινων καὶ τῆς Ἰταλίας μερῶν κυριεύσαντες. Ἀγαθοκλῆς δ’ οὐ μόνον καὶ τῶν τῆς Λιβύης ἀπεπείρασεν, ἀλλὰ καὶ τέλος ἐναπέθανε ταῖς ὑπεροχαῖς ταύταις. διὸ καὶ Πόπλιον Σκιπίωνά φασι τὸν πρῶτον καταπολεμήσαντα Καρχηδονίους ἐρωτηθέντα τίνας ὑπολαμβάνει πραγματικωτάτους ἄνδρας γεγονέναι καὶ σὺν νῷ τολμηροτάτους, εἰπεῖν τοὺς περὶ Ἀγαθοκλέα καὶ Διονύσιον τοὺς Σικελιώτας. καὶ περὶ μὲν τῶν τοιούτων ἀνδρῶν εἰς ἐπίστασιν ἄγειν τοὺς ἀναγινώσκοντας, καί που καὶ τῆς τύχης ποιήσασθαι μνήμην, ἔτι δὲ τῶν ἀνθρωπείων πραγμάτων, καὶ καθόλου προστιθέναι τὸν ἐπεκδιδάσκοντα λόγον, ἐπὶ δὲ τῶν προειρημένων ἀνδρῶν οὐδαμῶς ἁρμόζει.", "st": "15.35"}, {"sp": "N", "t": "διὰ δὴ ταύτας τὰς αἰτίας τὸν μετ’ αὐξήσεως λόγον ἀπεδοκιμάσαμεν ὑπὲρ Ἀγαθοκλέους, οὐχ ἥκιστα δὲ καὶ διὰ τὸ πάσας τὰς ἐκπληκτικὰς περιπετείας μίαν ἔχειν φαντασίαν τὴν πρώτην ἀξίαν ἐπιστάσεως, τὸ δὲ λοιπὸν οὐ μόνον ἀνωφελῆ γίνεσθαι τὴν ἀκρόασιν καὶ θέαν αὐτῶν, ἀλλὰ καὶ μετά τινος ὀχλήσεως ἐπιτελεῖσθαι τὴν ἐνέργειαν τῶν τοιούτων. δυεῖν γὰρ ὑπαρχόντων τελῶν, ὠφελείας καὶ τέρψεως, πρὸς ἃ δεῖ τὴν ἀναφορὰν ποιεῖσθαι τοὺς διὰ τῆς ἀκοῆς ἢ διὰ τῆς ὁράσεως βουλομένους τι πολυπραγμονεῖν, καὶ μάλιστα τῷ τῆς ἱστορίας γένει τούτου καθήκοντος, ἀμφοτέρων τούτων ὁ πλεονασμὸς ὑπὲρ τῶν ἐκπληκτικῶν συμπτωμάτων ἐκτὸς πίπτει. ζηλοῦν μὲν γὰρ τίς ἂν βουληθείη τὰς παραλόγους περιπετείας; οὐδὲ μὴν θεώμενος οὐδ’ ἀκούων ἥδεται συνεχῶς οὐδεὶς τῶν παρὰ φύσιν γενομένων πραγμάτων καὶ παρὰ τὴν κοινὴν ἔννοιαν τῶν ἀνθρώπων. ἀλλ’ εἰσάπαξ μὲν καὶ πρῶτον σπουδάζομεν ἃ μὲν ἰδεῖν, ἃ δ’ ἀκοῦσαι, χάριν τοῦ γνῶναι τὸ μὴ δοκοῦν δυνατὸν εἶναι διότι δυνατόν ἐστιν· ὅταν δὲ πιστεύωμεν, οὐδεὶς τοῖς παρὰ φύσιν ἐγχρονίζων εὐδοκεῖ· τῷ δ’ αὐτῷ πλεονάκις ἐγκυρεῖν οὐδ’ ὅλως ἂν βουληθείη. διόπερ ἢ ζηλωτὸν εἶναι δεῖ τὸ λεγόμενον ἢ τερπνόν· ὁ δὲ τῆς ἐκτὸς τούτων συμφορᾶς πλεονασμὸς οἰκειότερόν ἐστι τραγῳδίας ἤπερ ἱστορίας. ἀλλ’ ἴσως ἀναγκαῖόν ἐστι συγγνώμην ἔχειν τοῖς μὴ συνεφιστάνουσι μήτ’ ἐπὶ τὰ τῆς φύσεως μήτ’ ἐπὶ τὰ καθόλου κατὰ τῆς οἰκουμένης πράγματα· δοκεῖ γὰρ αὐτοῖς ταῦτ’ εἶναι μέγιστα καὶ θαυμαστότατα τῶν προγεγονότων οἷς ἂν αὐτοὶ παρατυχόντες ἐγκυρήσωσιν ἢ πυθόμενοι παρά τινων πρὸς αὐτὰ ταῦτα προσέχωσι τὸν νοῦν. διὸ καὶ λανθάνουσι πλείω τοῦ καθήκοντος διατιθέμενοι λόγον ὑπὲρ τῶν μήτε καινῶν ὄντων διὰ τὸ καὶ ἑτέροις πρότερον εἰρῆσθαι μήτ’ ὠφελεῖν μήτε τέρπειν δυναμένων. περὶ μὲν οὖν τούτων ἐπὶ τοσοῦτον ἡμῖν εἰρήσθω.", "st": "15.36"}, {"sp": "N", "t": "ὅτι Ἀντίοχος ὁ βασιλεὺς ἐδόκει κατὰ μὲν τὰς ἀρχὰς γεγονέναι μεγαλεπίβολος καὶ τολμηρὸς καὶ τοῦ προτεθέντος ἐξεργαστικός, προβαίνων δὲ κατὰ τὴν ἡλικίαν ἐφάνη πολὺ καταδεέστερος αὑτοῦ καὶ τῆς τῶν ἐκτὸς προσδοκίας.", "st": "15.37"}], []);})();
